pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps (below the minimum item
    // size of 1..100 stream -> treat anything < ~10 as near-dead) are heavily
    // penalized. Exact fits are strongly rewarded.
    if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else if post_residual < 10 {
        score += 300.0; // unusable dead space
    } else if post_residual < 20 {
        score += 120.0;
    } else if post_residual < 35 {
        score += 40.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + 0.5 * next_item_size as f64;
        } else {
            score += 30.0; // cannot host the lookahead item
        }
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // prefer consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 1.0 + 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    score *= pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make the empty bin attractive only when existing bins
    // would create dead space or the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by how much dead space we avoid.
        score += 150.0 + 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 400.0; // nothing fits elsewhere -> new bin is required
        }
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score -= 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 35.0;
    } else if post_residual < 30 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual is close to item (minimal waste).
    let gap = (bin_residual as i64 - item_size as i64) as f64;
    score -= 20.0 / (1.0 + gap.abs());

    // Lookahead: if next item fits the post-residual exactly-ish, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        if next_gap == 0 {
            score -= 45.0;
        } else if next_gap < 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post-residual unusable for the known next item: penalize.
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from many open bins: discourage spreading, favor new bin when few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Prefer bins below mean residual (fill emptier bins first, keep tight bins tight).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(-50.0).min(50.0);

    // New-bin candidate handling: baseline cost of opening a bin.
    if bin_residual == bin_capacity {
        // Attractive when no good fit exists or bins are very full.
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score = 15.0 - 25.0 * avg_fill;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual > 0 && post_residual < item_size.min(20) as f64 {
        // gap smaller than a plausible future item -> likely dead space
        score += (20 - post_residual.min(20)) as f64 * 4.0;
    }

    // Reward tight fits (small but well-used residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 6.0;

    // Reward filling bins that are already fairly full (consolidation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 4.0;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bin pressure: with many open bins, discourage spreading; prefer new bin only if fit is bad.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 0.35;

    // New-bin candidate handling: only attractive if current fit is terrible.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = bin_capacity as f64 * 0.5;
        // penalize opening a new bin when a decent fit exists elsewhere
        if post_residual >= 0 && fitting_bins_count > 0 && item_size as f64 <= mean_residual {
            score += 20.0;
        }
        // if the next item is large, a fresh bin is more valuable
        if next_item_size >= 50 {
            score -= 15.0;
        }
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 18.0;
        } else {
            score -= 4.0;
        }
    }
    // If next item would not fit here but this bin gets perfectly filled, small bonus.
    if next_item_size > 0 && post_residual == 0 {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (more full than average).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: waste nothing.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits exactly
    // into the post-residual of this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 120.0; // chain-friendly bin
        } else {
            // Dead space penalty scaled by how badly the next item misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    }

    // Penalize residuals that are too small to ever hold a meaningful item
    // (below typical minimum item size ~10), i.e. unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Tight-fit bonus: leaving little slack relative to capacity is good.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * tightness;

    // Relative-to-mean coupling: prefer bins whose post-residual stays
    // near the mean residual, penalize outliers both ways.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: opening a fresh bin is usually wasteful; penalize
    // unless current bins are nearly full (mean residual small) or it is
    // the only option.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 25.0;
        if crowded {
            score -= 150.0;
        } else {
            score += 100.0 + 0.5 * mean_residual;
        }
        // Early in the stream, opening bins is fine (build a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.1 {
            score -= 80.0;
        }
    }

    // Mild preference for consolidating into fewer bins.
    score += 2.0 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (or for the known next item) are wasted space.
    let min_item = 1u32;
    let dead = post_residual > 0 && post_residual < min_item.max(next_item_size.min(20));
    if dead {
        // The smaller the dead gap relative to capacity, the harsher the penalty.
        let gap_frac = post_residual as f64 / bin_capacity as f64;
        score += 60.0 * (1.0 - gap_frac) + 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // If this bin's residual can host the next item exactly, keep it usable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Post-residual too small for the lookahead item: future dead space risk.
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer new-bin
    // consolidation only when the current fit is poor.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * pressure;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., when mean residual is small and this is a fresh empty bin.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / bin_capacity as f64;
        // Penalize opening a new bin normally...
        score += 30.0;
        // ...but reward it when open bins are nearly full (poor fits remain).
        score -= 45.0 * (1.0 - mean_frac).min(1.0);
        // Slightly cheaper to open bins early in the stream.
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Mild bias toward filling fuller bins first (best-fit flavor).
    score -= 0.3 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below half the smallest plausible
    // next item are "unusable gaps" — penalize them heavily and nonlinearly.
    if post_residual > 0 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 3.0;
    }

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += next_item_size as f64 - post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many open bins
    // unless this is a tight fit.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - tightness) * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin has a good fit
    // (i.e., this item would create large dead space in every open bin).
    if bin_residual == bin_capacity {
        // Baseline new-bin score: moderate, so it wins only over bad fits.
        score = 60.0 + post_residual as f64 * 0.5;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // possible item (size 1) are still usable, but gaps in the "awkward zone"
    // (1..=12) are unlikely to fit typical items -> heavy penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += 25.0 * (13.0 - post_residual as f64);
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Pressure from number of open bins: prefer reusing existing bins when
    // many are open; allow new bins when few are open.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        // mild reward if next item can still fit
        score -= 5.0;
    }

    // New-bin candidate: make it attractive only when current bin would leave
    // a large unusable remainder or mean residual is already low (bins packed).
    if bin_residual == bin_capacity {
        // default neutral-ish cost; adjust with stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 10.0 + 20.0 * (1.0 - progress) - 0.5 * mean_residual;
        if post_residual <= 12 && post_residual > 0 {
            score += 25.0 * (13.0 - post_residual as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer packing into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // already fragmented; prefer bins with larger residual (closer to mean+).
    let resid = bin_residual as f64;
    if resid < mean_residual - 10.0 {
        score += (mean_residual - resid) * 0.5;
    }

    // New-bin candidate: default moderately high; allow it only when the item
    // is large relative to a fresh bin and no tight fit exists.
    if bin_residual == bin_capacity {
        let base = 45.0 + 0.3 * open_bins_count as f64;
        // If next item is small, keeping residuals large is fine -> new bin ok.
        let lookahead_bonus = if next_item_size > 0 && next_item_size >= post_residual.min(100) { -10.0 } else { 5.0 };
        score = base + lookahead_bonus;
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size <= bin_capacity {
        // post residual too small for next item -> dead space for lookahead.
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead-space quality classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Quotient class: how many "small item slots" (size <= 10) fit in the leftover
    let slots = post_residual / 10;
    // Modulo classes on post_residual relative to capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Penalize residuals that fall into awkward modulo classes (not multiples of 10)
    if post_residual % 10 != 0 {
        score += 6.0;
    }
    // Reward residuals that are multiples of common item-size harmonics
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Big leftover chunks are fine; tiny unusable chunks are dead space
    if pr > 0.0 && pr < 10.0 {
        score += 40.0;
    }
    // Medium-dead zone: too small for typical mid items, too big to ignore
    if post_residual >= 10 && post_residual < quarter {
        score += 12.0;
    }
    // Residual in [quarter, half) is a healthy working zone
    if post_residual >= quarter && post_residual < half {
        score -= 2.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward proportional to how snugly next item fits
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 15.0 * snug;
            // harmonic bonus if next item divides residual cleanly
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-good only when
    // current open bins are fragmented or item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - pr).abs();
        // prefer new bin when open bins are already fragmented or item huge
        if item_size > half {
            score -= 10.0 + 20.0 * progress;
        }
        if open_bins_count > 0 && mean_residual < (item_size as f64) {
            score -= 25.0; // no open bin really usable
        }
        if fragmentation < 5.0 && open_bins_count > 0 && item_size <= half {
            score += 30.0; // existing bins are healthy, discourage new bin
        }
    } else {
        // Slight preference for tighter existing bins (smaller residual before placement)
        score += 0.1 * (bin_residual as f64 - item_size as f64).max(0.0) / cap;
        // Encourage packing into bins when many bins can fit (reduce bin count pressure)
        if fitting_bins_count > 2 {
            score += 3.0;
        }
    }

    // Slot-count harmonic: residual that hosts many future small items is valuable
    score -= 1.5 * slots as f64;

    // Mild stream-progress adaptation: tighten standards as stream advances
    score *= 1.0 + 0.1 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are unusable; penalize them heavily, with extra weight near zero.
    if post_residual > 0 && post_residual < 10 {
        score += (11.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits generally (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 8.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual is close to the item (avoid wasting large residuals).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += waste * 0.25;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when mean residual is small relative to the item.
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.5 - (item_size as f64 * 0.2);
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // keep some headroom for the next item in the fresh bin
            score -= 5.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // dead end for the lookahead item
    }

    // Late in the stream, close bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (next_item_size as f64 - post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward reserving room for the lookahead item.
        score -= 3.0 * (post_residual as f64 - next_item_size as f64).min(10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual);
        score += 20.0 - 10.0 * fit_quality - pressure.min(5.0);
        // Early in stream, opening bins is cheaper; late, prefer filling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates from mean (consolidation of similar gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Slight preference for bins with larger residual when item is large.
    score -= 0.05 * (item_size as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are highly undesirable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open,
    // and prefer opening new bins when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with below-mean residual (keeps residuals balanced,
    // preserving larger gaps for future items).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when it genuinely beats reuse
    // (e.g., large item that would wreck a nearly-full bin).
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress.clamp(0.0, 1.0);
    let poly = 1.0 + t * (0.8 - 1.6 * t); // smooth arch-shaped weighting

    let mut score = pr * (0.5 + 0.5 * poly);

    // Penalize dead space non-linearly (quartic-ish small residual penalty)
    score += 40.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm) * t;

    // Reward tight fits (small post_residual) more strongly late in stream
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * t;

    // Lookahead coupling: favor bins whose post_residual fits next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap) * (1.0 + t);
    } else if next_item_size > 0 {
        score += 8.0 * t;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Mild penalty for spreading across many open bins late
    score += 0.5 * open_bins_count as f64 * t;

    // New-bin candidate: smooth threshold via logistic of mean residual
    let logistic = 1.0 / (1.0 + (-8.0 * (mean_residual / cap - 0.35))).max(1e-9);
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.35 * logistic) + 20.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 30.0;
    }
    // Perfect fit gets strong reward
    if post_residual == 0 {
        score -= 200.0;
    }
    // Post residual that can fit the lookahead item is valuable
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.8 + 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space relative to next item
        score += next_item_size as f64 * 0.5;
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 2.5 * (0.5 + progress);

    // Prefer bins tighter than average (good fits)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it unattractive unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * -1.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, opening new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..100 range,
    // but treat tiny gaps < 12 as likely dead space) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 45.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 25.0;
    } else if fill_ratio > 0.6 {
        score -= 8.0;
    } else if fill_ratio < 0.25 {
        // Dumping a tiny item into a big bin wastes capacity.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading items
    // into fresh space; prefer consolidating into existing residual.
    score += 0.6 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 30.0;
        } else if post_residual as u32 >= next_item_size && post_residual - next_item_size < 12 {
            // Would leave the next item creating dead space; mild penalty.
            score += 8.0;
        }
    }

    // Slight penalty if this bin's residual is far below the mean (already tight bin),
    // unless it's a near-perfect fit which is handled above.
    let dev = mean_residual - bin_residual as f64;
    if dev > 15.0 {
        score += 5.0;
    }

    // New-bin candidate (empty bin): make it attractive only when it beats bad fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by its pristine flexibility.
        score = 40.0 + 0.3 * open_bins_count as f64;
        // If no other bin can fit the item, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Tiny unusable gaps (1..=9) are the worst outcome: heavy penalty.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Mid-range gaps (10..=25) are hard to fill later: moderate penalty.
    if post_residual >= 10 && post_residual <= 25 {
        score += 8.0 * (25.0 - post_residual as f64) / 15.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Lookahead: if next item fits the post-residual exactly, big reward ---
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 50.0;
        } else if slack <= 9.0 {
            score -= 10.0 - slack; // still decent, small penalty for slack
        } else {
            score += slack * 0.1; // too much leftover for next item
        }
    }
    // If next item cannot fit in the leftover, that leftover is likely dead.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // --- Last-chance bonus: only bin that fits -> strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- Open-bin pressure: discourage proliferating bins ---
    score += open_bins_count as f64 * 0.5;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when this bin's fit is bad
        // (large post_residual) or no existing bin is a good home.
        let base = (bin_capacity - item_size) as f64; // leftover in fresh bin
        score = base;
        // Slight bias against opening bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - progress);
        // If this is the last chance among open bins, prefer reusing.
        if fitting_bins_count >= 1 && post_residual <= 9 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny unusable gaps (1..10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to the item size (low waste ratio).
    let waste_ratio = post_residual as f64 / (bin_residual as f64 + 1.0);
    score += 30.0 * waste_ratio;

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.25 * tightness;

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }
    // Penalize leaving a gap just under the next item (dead space for it).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; encourage filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Mean residual coupling: prefer bins below mean residual (fill the fullest bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large dead-space risk elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score = bin_capacity as f64 * 0.75 + desperation - 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (<= 10, or below the minimum item size) are pure waste.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable dead space: hard penalty.
        score += 500.0;
    } else {
        // Usable residual: reward proportional to how well it can host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0 * next_item_size as f64;
        } else if next_item_size > 0 {
            // Lookahead cannot fit here: penalize proportionally to the wasted gap.
            score += 1.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize tightness of the fill: a near-full residual left over is risky.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is close to the item need.
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; dead-space penalties above make poor open-bin fits lose.
        score += 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common capacity fractions
    let pr = post_residual;
    let res_mod = (pr % 10) as f64;
    let res_div = (pr / 10) as f64;

    // Reward post-residuals that are "clean" (small residue mod 10, or exact zero)
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        score += res_mod * 1.5; // penalize ragged remainders
        // Reward post_residuals that leave useful harmonic slots (>= next item size)
        if next_item_size > 0 && pr >= next_item_size {
            score -= 12.0 + (pr - next_item_size) as f64 * 0.3;
        } else if next_item_size > 0 {
            score += (next_item_size - pr) as f64 * 0.8; // dead space for lookahead
        }
        // Integer-division thresholds: post_residual in [20,30) is a classic dead zone
        let slot = pr / 10;
        if slot == 2 {
            score += 8.0;
        } else if slot == 3 {
            score -= 4.0;
        } else if slot == 0 {
            score += 25.0; // tiny unusable sliver
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / cap).min(1.0);
        score = cap - post_residual as f64; // baseline ~ item_size
        score -= 15.0 * (1.0 - tightness); // prefer new bin for large items
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size <= pr.min(100) {
            score -= 5.0;
        }
        // Discourage opening new bins when open bins have plenty of slack
        if mean_residual > item_size as f64 + 15.0 {
            score += 18.0;
        }
    }

    // Fill factor: reward tighter fills as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - post_residual as f64 / cap) * 10.0 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the mean (balance load)
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 6.0;

    // Penalize many open bins slightly to encourage consolidation
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space zone: residuals 1..=9 are unusable for items >=10 but
    // still count as waste in the new interface (items 1..100).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits: the closer post_residual is to 0, the better.
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.3;

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + slack * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the residual: penalize proportionally.
        score += post_residual as f64 * 0.15;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 35.0;
        // If some other bin is a tight fit, keep new bin expensive.
        if item_size > 0 && (bin_capacity as f64 - mean_residual).abs() > 0.0 {
            score = base + mean_residual * 0.1;
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't open a new bin when one bin barely fits
        }
        // Late in stream, prefer consolidating.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Slight preference for filling bins below mean residual (balance).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Waste that cannot host the next item: penalize proportionally.
        score += 0.15 * post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    if bin_residual < bin_capacity {
        score += 0.35 * open_bins_count as f64 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmented = mean_residual > 0.0 && mean_residual < item_size as f64;
        if fragmented {
            score -= 12.0;
        } else {
            score += 30.0;
        }
    }

    // Slight late-stream tightening: prefer consolidating as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            score -= 25.0; // perfect pairing with lookahead item
        } else {
            score -= 6.0; // next item can still fit here afterwards
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64; // how much worse open bins are
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: must open
        } else {
            // Opening a new bin is penalized more when open bins are tight/scarce.
            score += 20.0 + 15.0 * (1.0 - progress) + 5.0 * pressure;
            if spread > 0.0 {
                score -= 10.0 * spread.min(3.0); // allow opening when mean residual is large
            }
        }
    }

    // Mild global regularization: favor filling bins with large mean residual
    // (drain the "loosest" bins first).
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
    }

    // Reward near-exact fills.
    if post_residual <= 2 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A gap that cannot even hold the smallest plausible item is pure waste.
    if post_residual < item_size {
        // gap smaller than current item -> likely dead space
        score += 25.0 * (1.0 - post_residual as f64 / item_size as f64);
    }
    if post_residual > 0 && post_residual < 10 {
        // tiny unusable sliver -> strong penalty
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // gap only usable by very small items -> moderate penalty
        score += 15.0;
    }

    // Reward near-perfect fits (low post_residual relative to capacity).
    let fill_ratio = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward this placement (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here after this placement -> slight penalty
        score += 4.0;
    }

    // Open-bin pressure: discourage scattering items across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual alignment: prefer bins whose residual is below average
    // (i.e., already fairly full bins) to keep other bins flexible.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a decent fit (post_residual would be large / dead space elsewhere).
    if bin_residual == bin_capacity {
        // New bin: neutral baseline with mild penalty so tight fits in open
        // bins win, but large dead-space placements lose.
        score += 20.0 - 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good, but dead space < next item is bad).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain fill
        } else if post_residual >= next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.15 * leftover; // next item fits: reward, less if it leaves more waste
        } else {
            // next item does NOT fit in post_residual: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than average is good (we consumed the "easy" space).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving unusable tiny dead space (< smallest plausible item) unless perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Later in the stream: prefer consolidating into fewer bins.
    score += 10.0 * progress * (open_bins_count as f64 / (1.0 + post_residual as f64 / 100.0));

    // New-bin candidate: neutral-ish base, only chosen if no open bin scores better.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward: strongly prefer bins where the item fills residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness reward: quadratic decay of residual waste.
        score -= 2.0 * (bin_capacity as f64 - post_residual as f64).sqrt();

        // 2-step lookahead: reward bins whose post_residual matches the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 40.0 / (1.0 + gap as f64);
            if gap == 0 {
                score -= 60.0; // perfect chain: item then next item fill bin
            }
        } else if next_item_size > 0 {
            // Post-residual too small for next item: penalize dead space
            score += 15.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Penalize wasting a near-full bin on a small item (poor fit).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio < 0.4 {
        score += 25.0 * (0.4 - fit_ratio) * 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins have
    // large residuals that would be fragmented anyway.
    if bin_residual == bin_capacity {
        score += 120.0;
        if mean_residual > 60.0 {
            score += 40.0; // plenty of space left elsewhere; don't open new bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // pairing potential in a fresh bin
        }
    }

    // Mild preference for balancing residuals relative to mean early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * (post_residual as f64 - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space that cannot fit the next item is worse
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward using a bin that fits the next item too (chain fits)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Penalize opening a new bin when good fits exist (empty-bin candidate)
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    // Late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins whose residual falls into
    // "usable" classes (multiples of common small item sizes) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class bonus: residual divisible by 10/20/25/50 is reusable by many item sizes.
    let r = post_residual;
    let class_bonus = if r == 0 {
        40.0 // perfect fit: strongly favored
    } else if r % 50 == 0 {
        25.0
    } else if r % 25 == 0 {
        18.0
    } else if r % 20 == 0 {
        14.0
    } else if r % 10 == 0 {
        10.0
    } else if r % 5 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Penalize dead space that no plausible item (>=1, up to 100) can use well:
    // tiny residuals (1..10) are near-waste unless post_residual == 0.
    if r > 0 && r < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward strongly; if it cannot fit at all, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Harmonic threshold: next item in a "large class" (>50) makes tight fits valuable
        if next_item_size > 50 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream or with many bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 + 20.0 * progress - 2.0 * (open_bins_count.min(20) as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin is attractive if current bins are crowded
            if mean_residual < next_item_size as f64 {
                score -= 25.0;
            }
        }
    }

    // Mild preference for filling fuller bins (low post_residual relative to capacity).
    score += 0.05 * (1.0 - pr / cap) * (pr / cap) * 100.0;

    // Tie-break with mean residual deviation: prefer bins close to average state.
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    let frac = post_residual as f64 / cap;
    // Penalize residuals that fall into "dead zone" classes (too small for likely items).
    let dead = if post_residual == 0 { 0.0 }
        else if post_residual < 10 { 40.0 }
        else if post_residual < 20 { 25.0 }
        else if post_residual < 35 { 12.0 }
        else if post_residual < 50 { 4.0 }
        else { 0.0 };
    score += dead;

    // Integer-division thresholds: how well can next_item_size slot into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Lookahead fits: reward exact/near-exact couplings via modulo classes.
            let rem = post_residual % next_item_size.max(1);
            score -= 30.0 - 0.5 * rem as f64;
            if rem == 0 { score -= 15.0; } // perfect harmonic fit
        } else {
            // Lookahead won't fit here: penalize proportionally to wasted potential.
            score += 0.3 * (next_item_size - post_residual).min(60) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when open bins
    // are nearly full (small mean residual) or many bins already exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.5 * cap + mean_residual - 0.15 * open_bins_count as f64 - 10.0 * progress;
        // Prefer new bin if current item leaves a terrible residue class elsewhere.
        if post_residual == 0 { score -= 5.0; }
    }

    // Mild reward for tight fits overall (small post_residual already favored by base).
    let tightness = 1.0 - frac;
    score -= 5.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual relative to item size (non-linear).
    let item = item_size as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += (post * post) / cap; // squared dead-space penalty

    // Reward filling a bin completely (perfect fit bonus).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item also fits in the resulting residual, reward this bin.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 12.0;
        // Extra reward if next item fills the bin almost perfectly afterwards.
        let two_step_waste = post_residual as f64 - next_item_size as f64;
        score -= (cap - two_step_waste.abs()) * 0.05;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving a stranded mid-size residual.
        score += 6.0;
    }

    // Global state coupling: prefer bins below mean residual (keep spread even),
    // but when many bins are open, tighten preference for high-fill bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mean_gap = mean_residual - post;
    score += mean_gap * (0.3 + 0.4 * progress);

    // Early in stream: be more willing to open new bins (exploration);
    // late in stream: strongly prefer existing bins to avoid bin inflation.
    if bin_residual == bin_capacity {
        let exploration = (1.0 - progress) * 8.0 - progress * 15.0;
        score -= exploration + open_bins_count as f64 * 0.5;
        // Never open a new bin for a tiny item when residuals are plentiful.
        if item < 0.25 * cap && mean_residual > 2.0 * item {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose residual after placement
    // matches the next item size exactly (chain packing).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            let gap = pr - next;
            if gap == 0.0 {
                score -= 500.0; // perfect chain fit
            } else if gap <= 10.0 {
                score -= 300.0 - gap * 15.0;
            } else {
                score -= (50.0 / gap).min(50.0);
            }
        } else {
            // Next item cannot follow in this bin; penalize proportionally
            // to how much residual would be stranded relative to next item.
            score += (next - pr) * 0.8;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // prefer leaving residuals that are typical (usable), punish outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bin would waste a lot
    // and the item is large (better to start fresh).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if waste > 40.0 {
            score -= 120.0 + waste * 0.5 + progress * 50.0;
        } else {
            score += 80.0; // discourage opening bins for small waste
        }
    }

    // Mild preference for compacting into fewer bins as stream progresses.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: minimize dead space
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 == nr {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual as f64 - nr;
            // small slack after next item is good; penalize proportionally
            score -= 300.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize relative to gap
            score += 0.5 * (nr - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.7;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: keep it neutral-high so only genuinely bad fits trigger opening
    if bin_residual == bin_capacity {
        score += 60.0;
        // open a new bin if item is large relative to typical residuals
        if item_size as f64 > mean_residual {
            score -= 120.0;
        }
    }

    // Dead-space penalty for large unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Late-stream tightness: as stream progresses, waste less
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual buckets by capacity fraction.
    // Small post_residuals (< smallest possible item) are dead space -> penalize.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 5.0;
    }

    // Integer-division class of post_residual: how many more "typical" items fit.
    let typical = 25u32;
    let fits_more = post_residual / typical;
    score -= fits_more as f64 * 12.0;

    // Modulo arithmetic: reward residuals that are friendly to common size classes.
    // Sizes 1..100; residue classes mod 10 and mod 25 matter for tight packing.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
