            // next item fits but not perfectly: mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0);
        } else {
            // next item cannot use this bin's remainder: penalize wasted potential
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
        if post_residual < dead_threshold {
            score += 30.0; // still bad if it creates dead space
        }
    }

    // New-bin candidate: neutral-ish baseline; open a new bin when the fit is poor
    // or when many open bins have large mean residual (fragmentation).
    if bin_residual == bin_capacity {
        // baseline: new bin has full 100 residual, score starts at 100 via post_residual
        // penalize opening new bins when a decent fit exists elsewhere
        if fitting_bins_count > 0 {
            let best_possible = (bin_capacity - item_size) as f64;
            let frag = (mean_residual - post_residual as f64).abs();
            if post_residual as f64 >= mean_residual - 10.0 && frag < 25.0 {
                score += 120.0; // discourage new bin when an open bin fits comparably
            }
