        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
    } else {
        // prefer bins whose residual is close to the item (tight fit)
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.15;
    }

    // Prefer filling bins when many are open (limit sprawl).
    score += open_bins_count as f64 * 0.5;

    // Slight preference for earlier bins (stability), scaled by mean residual.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

