pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes.
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty grows for "awkward" residual classes (1..9 non-zero remainders
    // are harder to fill with items >= 10, so penalize, but small nonzero remainders
    // (< 10) are pure dead space -> heavy penalty).
    if pr > 0 && pr < 10 {
        score += 40.0; // unusable sliver
    } else {
        // penalty by harmonic class distance from multiples of 10
        let m = class.min(10 - class) as f64;
        score += m * 1.5;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 60.0;
    }

    // Reward if next item fits exactly into post_residual (chained perfect fit)
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            // next item fits: penalize by leftover after next placement
            let pr2 = pr - next_item_size;
            score += pr2 as f64 * 0.4;
            if pr2 > 0 && pr2 < 10 {
                score += 15.0;
            }
        } else {
            // next item won't fit here: mildly reward closing bin with small residual
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when residuals are large/fragmented
    if bin_residual == bin_capacity {
        // baseline attractiveness of a fresh bin
        score = (bin_capacity - item_size) as f64;
        // open new bin early in stream or when many bins are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // if mean residual is small (bins nearly full), fresh bin is attractive
        score -= (bin_capacity as f64 - mean_residual) * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    } else {
        // prefer tighter existing bins: subtract for small bin_residual relative to item
        let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= tightness * 8.0;
    }

    // Mild bonus for placing into bins whose residual is in the same harmonic class as item
    if bin_residual % 10 == item_size % 10 && bin_residual >= item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: residuals that are too small for typical
    // future items (1..100, but practically >= 10) are wasted capacity.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is the best possible outcome.
        score -= 60.0;
    } else {
        // Smooth tightness reward: prefer smaller but usable residuals.
        score -= 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).min(1.0);
    }

    // Next-item lookahead: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize creating a gap that cannot host the known next item.
        score += 8.0 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (a new bin is the empty-residual == capacity candidate).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 10.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // Mild pressure toward consolidating into already-open bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (pack into tighter-than-average bins to consolidate large gaps).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

