pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;
    let mut score = pr;

    // smooth polynomial coupling of post_residual with stream progress
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep-like
    score *= 1.0 + 0.6 * prog_poly * (1.0 - fit);

    // reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - pr / cap;
    score -= 30.0 * tightness * tightness * (0.5 + prog_poly);

    // penalize dead space that is too small for typical future items
    let dead = if pr < next_item_size as f64 && pr > 0.0 { pr } else { 0.0 };
    score += 2.0 * dead * (0.5 + prog_poly);

    // last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 - 0.5 * prog_poly);
    }

    // new-bin candidate: penalize slightly so we prefer reusing open bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * prog_poly - 10.0 * (1.0 - fit);
        // allow new bin late in stream when residuals are fragmented
        if mean_residual < fit * cap {
            score -= 20.0 * prog_poly;
        }
    }

    // lookahead: reward leaving space usable by next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (post_residual as f64 / cap) * (1.0 - prog_poly);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity divided into octiles
    let oct = (item_size * 8 / bin_capacity).min(7); // 0..7 harmonic class
    let post_oct = (post_residual * 8 / bin_capacity).min(7);

    // Reward tight fits: small post_residual is good
    score -= 12.0 / (1.0 + post_residual as f64);

    // Penalize dead space that cannot fit typical future items (harmonic dead zones)
    // A post_residual is "usable" if it is >= 20 (typical min item) or exactly 0
    if post_residual > 0 && post_residual < 20 {
        score += 18.0; // dead space penalty
    }

    // Modulo arithmetic: bins whose residual is a multiple of 10 are more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Residuals that are multiples of 5 but not 10 are mildly penalized
    else if post_residual % 5 == 0 && post_residual > 0 {
        score += 2.0;
    }

    // Integer-division thresholds on post_residual
    let tier = post_residual / 25; // 0,1,2,3 tiers
    match tier {
        0 => score += 8.0,          // 0..24 : nearly full, good if 0 else risky
        1 => score -= 4.0,          // 25..49 : decent pocket
        2 => score -= 7.0,          // 50..74 : roomy
        _ => score -= 9.0,          // 75..99 : wide open
    }

    // Lookahead coupling: does this bin also fit the next item's harmonic class?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Great: chain two items into this bin
        let chain_post = post_residual - next_item_size;
        score -= 14.0 - (chain_post as f64) * 0.08;
        if chain_post % 10 == 0 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize if this leaves a bad pocket
        if post_residual > 0 && post_residual < next_item_size.min(30) {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only
    // open a new bin when existing bins offer poor fits.
    if bin_residual == bin_capacity {
        // Progress-aware baseline: early stream, be liberal with new bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 20.0 + 30.0 * progress;
        // Large items justify a fresh bin more than small ones
        let size_bonus = (item_size as f64 / bin_capacity as f64) * 25.0;
        return base - size_bonus + 8.0 * (open_bins_count as f64).ln1p();
    }

    // Mean residual coupling: prefer bins close to the mean residual (balance)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Slight preference to fill more-filled bins when many bins are open
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Harmonic class mismatch penalty: pairing a huge item with a huge residual
    // wastes capacity that could host a mid-class item later
    if oct >= 5 && post_oct >= 5 {
        score += 5.0;
    }
    if oct <= 2 && post_residual > 60 {
        score += 4.0; // small item into big bin wastes the big bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are unusable; penalize them heavily, with extra weight near zero.
    if post_residual > 0 && post_residual < 10 {
        score += (11.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits generally (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 8.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual is close to the item (avoid wasting large residuals).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += waste * 0.25;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when mean residual is small relative to the item.
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.5 - (item_size as f64 * 0.2);
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // keep some headroom for the next item in the fresh bin
            score -= 5.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // dead end for the lookahead item
    }

    // Late in the stream, close bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    score += 40.0 * (post_residual as f64 / bin_capacity as f64).powi(3);

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact 2-step chaining is ideal.
            if next_item_size == post_residual {
                score -= 150.0;
            } else {
                // Partial credit, decaying with leftover slack after the pair.
                let slack = (post_residual - next_item_size) as f64;
                score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item cannot follow here: penalize, worse if post_residual is dead space.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 && dead < 10.0 {
                score += 50.0; // tiny unusable dead space
            }
            score += 20.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins already below-average residual
    // (concentrate filling) but avoid leaving extreme outliers.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: keep it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
    }

    // Mild late-stream conservatism: pack existing bins tighter as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residuals below the minimum item size are ideal,
    // but large post-residuals that are hard to fill later are wasteful.
    if post_residual < 10 {
        score -= 20.0; // near-perfect fill
    } else if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.5;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain_fit;
        } else {
            // Next item won't fit here after placement; slight penalty for fragmenting.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a good fit. Penalize the fresh bin, but relax the penalty late in
    // the stream or when open bins are mostly full (low mean residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let openness = mean_residual / bin_capacity as f64; // high = bins mostly empty
        let mut new_bin_penalty = 35.0 * openness;
        new_bin_penalty *= 1.0 - 0.3 * progress; // slightly cheaper to open bins late
        if open_bins_count == 0 {
            new_bin_penalty = 0.0;
        }
        score += new_bin_penalty;
    }

    // Global-state term: when many bins are open with high mean residual, prefer
    // consolidating into fuller bins (those have small residuals already).
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fullness * (mean_residual / bin_capacity as f64);

    // Mild time-horizon shaping: early on, keep residuals flexible; later,
    // aggressively close out bins (favor near-zero post residual).
    let urgency = progress * progress;
    score -= urgency * (bin_capacity as f64 - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, modulated by a smooth polynomial in progress
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - progress) * 4.0);

    // Non-linear coupling: waste term penalizing dead space, stronger late in stream
    let waste = norm_pr * norm_pr;
    score += 120.0 * waste * (0.4 + 0.6 * progress);

    // Reward tight fits: cubic decay of penalty as post_residual shrinks
    score -= 60.0 * (1.0 - norm_pr).powi(3) * (0.5 + 0.5 * progress);

    // Lookahead coupling: smooth interaction between post_residual and next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let match_bonus = (1.0 - gap / cap).max(0.0);
        score -= 30.0 * match_bonus * match_bonus * (1.0 - progress * 0.5);
        // Penalize post-residual that cannot host next item
        if pr < nx {
            score += 15.0 * (nx - pr) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - 0.3 * progress);
    }

    // New-bin candidate: smooth penalty tuned by open-bin pressure and mean residual
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).powf(2.0);
        score += 40.0 + 60.0 * pressure - 25.0 * (mean_residual / cap) * (1.0 - progress);
    }

    // Mild preference for bins with residual near mean (balance), smooth quadratic
    let dev = (pr - mean_residual) / cap;
    score += 20.0 * dev * dev * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo 10 buckets.
    let class = post_residual % 10;
    // Residuals that are "harmonic" (nice multiples) are more reusable.
    let harmonic_bonus = match class {
        0 => 14.0,
        5 => 9.0,
        2 | 8 => 5.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division tiers: how many items of the current size could still fit.
    let tier = post_residual / item_size.max(1);
    score -= (tier.min(4) as f64) * 6.0;

    // Lookahead compatibility: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect closure
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 18.0 - (slack.min(30) as f64) * 0.3;
            // harmonic class of the resulting slack
            if slack % 10 == 0 { score -= 8.0; }
        } else {
            // next item cannot use this bin's remainder: penalize by overshoot class
            let over = (next_item_size - post_residual) % 10;
            score += 4.0 + over as f64 * 0.5;
        }
    } else {
        // last item: prefer filling as tightly as possible
        score += post_residual as f64 * 0.5;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but reward it when open bins are crowded (many bins, low mean residual).
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += 20.0 - crowding * 2.0;
        // If the item is large and nothing fits well, opening fresh is fine.
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.4;

    // Progress-aware tie-breaking: slightly prefer tighter fits late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize residuals that the next item cannot use either (double dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 200.0;
    }

    // Reward using a bin whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    score += (open_bins_count as f64) * 2.0;

    // Last-chance bonus: only one fitting bin, use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate should only win if existing bins are very fragmented.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.5 + 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step fit: post_residual exactly matches next item -> strong reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 25.0 + 10.0 * (1.0 - progress);
        } else if post_residual < next_item_size {
            // Dead space: next item cannot use this residual.
            score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
        } else {
            // Reward closeness of residual to next item size.
            score -= (12.0 * (1.0 - gap / 60.0)).max(0.0);
        }
    } else {
        // Last item: just minimize wasted residual.
        score -= 5.0;
    }

    // Penalize residuals far above mean residual (fragmentation).
    score += 0.10 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so we reuse open bins when decent,
    // but allow opening when no open bin fits well (post_residual small already favors it).
    if is_new_bin {
        score += 8.0 - 4.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tight_fit = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight_fit * tight_fit;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin; grows with how many bins already fit the item.
        score += 30.0 + 8.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (keeps flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If many open bins have large residuals, prefer spreading instead of new bins.
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Prefer filling already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic penalty on wasted space, amplified as the stream progresses.
    let mut score = x * x * (1.0 + 2.0 * t) * cap;

    // Smooth cubic interaction: large residuals hurt more late in the stream.
    score += x.powi(3) * cap * (0.5 + 1.5 * t);

    // Reward tight fits (small post residual) with a smooth sigmoid-like bonus.
    score -= (1.0 - x).powi(2) * 10.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - x);
    }

    // Penalize opening a new bin when existing bins fit, scaled by how "wasteful" the new bin would be.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * x * (1.0 - t);
        // Late in the stream, consolidating into open bins matters even more.
        score += 10.0 * t * (1.0 - x);
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap); // next item fits: good chaining
        } else {
            score += 4.0 * (-gap); // next item won't fit: mild penalty
        }
    }

    // Mild pressure to reduce mean residual dispersion across open bins.
    score += (mean_residual - pr).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post-residual: residues mod 10 create "dead-space bands".
    // Residues 0..=9 are prime targets; mid-band residues (10..=29) are the least
    // reusable classes for typical item sizes, so penalize them super-linearly.
    let residue_class = post_residual % 10;
    let band = (post_residual / 10) % 10; // integer-division threshold class
    score -= residue_class as f64 * 0.8;              // exact-decade leftovers are gold
    if post_residual >= 10 && post_residual <= 29 {
        score += (30.0 - post) * 0.6;                 // awkward mid-band dead space
    }
    if band == 0 {
        score -= 3.0;                                 // post < 10: near-perfect fill
    }

    // Tightness coupling: reward fills that consume a large fraction of the bin.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * fill_frac * 25.0;

    // Lookahead harmony: if the next item lands exactly in the post-residual class,
    // this placement chains perfectly; penalize near-miss couplings.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 20.0;                            // perfect lookahead fit
        } else if gap > 0 && gap < 10 {
            score -= (10 - gap) as f64 * 1.5;         // close lookahead fit
        } else if gap < 0 && (-gap) <= 10 {
            score += (-gap) as f64 * 1.2;             // next item barely breaks this bin
        }
        // modulo harmony: next item's decade class matches post-residual decade
        if next_item_size / 10 == post_residual / 10 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance logic: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when every open fit would strand a bad band,
    // or when the stream is early and spreading capacity is cheap.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap - item_size as f64;               // baseline: fresh bin residual
        score -= (1.0 - progress) * 8.0;              // early stream: open bins cheaply
        score -= open_bins_count as f64 * 0.0;        // (kept neutral on open count)
        if fitting_bins_count > 0 {
            // Opening a new bin while good fits exist: only worth it if all fits
            // would leave mid-band waste (post_residual in 10..=29) in every bin.
            score += 12.0;                            // default penalty for skipping fits
            if post_residual >= 10 && post_residual <= 29 {
                score -= 10.0;                        // existing fits are bad anyway
            }
        }
        // A fresh bin with a harmonic residual (multiple of 10) is structurally nice.
        if (bin_capacity - item_size) % 10 == 0 {
            score -= 4.0;
        }
    }

    // Mild mean-residual gravity: prefer bins whose residual is near the fleet mean
    // (keeps the pool balanced and future items placeable).
    let dev = (post - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: raw leftover space (lower is better => tighter fit).
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any plausible item
    // (items are 1..100, but small gaps < 10 are almost certainly dead).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit bonus: strongly reward exact closure.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Fractional tightness reward: favor small usable leftovers.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 15.0 * tightness;
    }

    // Lookahead: reward if next item fits the post residual (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a gap that blocks the next item.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: bins with residual below mean are "dying" bins,
    // prefer filling them; bins above mean get slight penalty.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.35 * (mean_residual - residual_f);
    } else {
        score += 0.15 * (residual_f - mean_residual);
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit. Penalize the fresh empty bin moderately;
    // the last-chance bonus on real bins will override this when needed.
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
        // Late in the stream, keep consolidation: new bins cost more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild stream-progress drift: as stream nears end, prefer tighter packing.
    score += 5.0 * (step_index as f64 / (total_items.max(1) as f64)) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step match: item + next item fill the bin perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Reward near-exact 2-step match (small dead space after next item).
    if next_item_size > 0 && post_residual > next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 50.0 * (1.0 - leftover / bin_capacity as f64);
    }

    // Penalize when next item cannot fit here (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Relative to mean residual: prefer bins tighter than average (better packing).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize creating tiny unusable residuals (below min item size 1..100 heuristic floor).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Slight preference for filling existing bins over opening new ones early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // New-bin candidate: make it mildly unattractive unless it's a genuinely better fit.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small unusable leftovers (dead space below minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 / (1.0 + gap);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item won't fit here after placement; mild penalty proportional to waste.
        score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that fits (avoids opening a bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fits are bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        // Penalize new bins generally, but relax penalty as stream progresses and bins fragment.
        score += 30.0 - 0.05 * open_bins_count as f64 - 10.0 * progress;
        if fit_ratio >= 0.9 && !is_new_bin {
            score -= 5.0;
        }
        // If many bins can fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
        let _ = crowded;
    }

    // Mild global balance: prefer bins whose residual is far from the mean (rebalance fragmentation).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Encourage filling bins close to capacity as stream progresses.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 6.0 * fill * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with non-linear sharpening of small residuals
    let mut score = pr * (1.0 + 1.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling: as stream progresses, waste matters more
    score += 8.0 * pr_norm * pr_norm * progress * (1.0 + progress);

    // Penalize residuals that cannot fit typical future items (dead space)
    let dead = ((40.0 - pr).max(0.0)) / 40.0;
    score += 6.0 * dead * dead * (0.5 + 0.5 * progress);

    // Lookahead: reward if next item fits the post residual, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (1.0 - (pr - nxt) / cap) * (0.5 + progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count <= 1 {
        score -= 12.0 + 6.0 * progress;
    }

    // Mild preference for consolidating into fewer bins when many are open
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr_norm);

    // Diverge from mean residual: prefer bins unlike the average state
    score += 0.5 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small" residue classes (<= 10) are nearly perfectly packed.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fits: post_residual in {0,1..=10} gets strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Penalize dead space in awkward middle classes (21..=40): hard to fill.
    if post_residual > 20 && post_residual <= 40 {
        score += 6.0;
    }

    // Modulo-10 class coupling: residuals divisible by 10 pair well with
    // items drawn from the same granularity grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead harmony: if next item fits exactly into post_residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 12.0;
            } else {
                score += (gap as f64) * 0.15;
            }
        } else {
            // Next item cannot follow here; slight penalty unless bin is
            // otherwise the last chance.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when existing bins would
    // leave large unusable residue; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: slightly worse than a good fit, better than
        // a terrible fit.
        score = cap * 0.35;
        if open_bins_count == 0 {
            score -= 100.0; // must place somewhere
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
        // If mean residual of open bins is large, spreading is fine.
        score -= (mean_residual / cap).min(1.0) * 5.0;
    } else {
        // Prefer bins tighter than the mean residual (better packing).
        score -= (mean_residual - pr) * 0.3;
    }

    // Mild penalty for many competing bins (prefer consolidation).
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if post_residual < 10 {
            // Unusable sliver: heavy penalty scaled by how close to zero.
            score += 60.0 * (1.0 - dead / 10.0);
        } else {
            // Usable gap: mild penalty decreasing with size (large leftovers are reusable).
            score -= 0.15 * dead;
        }
    }

    // Reward a perfect / near-perfect fit strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible (small dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * post_residual as f64;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if the current item is large and would leave a big residual elsewhere,
        // a fresh bin is fine.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // Reward packing into existing bins when open-bin count is high.
        score -= 0.3 * open_bins_count as f64;
    }

    // Lookahead: penalize if the next item cannot fit into the post residual
    // (creating fragmentation that blocks the known future item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + 0.3 * (next_item_size - post_residual) as f64;
    }
    // Reward if post residual still accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Early in the stream, allow more bins (better long-term structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin {
        score -= 15.0 * (1.0 - progress);
    }

    // Slight preference to fill bins below mean residual (balance avoidance of stragglers).
    score += 0.1 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space after placement).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(20.0);
        // Extra reward if the next item then fits almost perfectly.
        if slack <= 5.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Penalize creating dead space the next item cannot use,
        // scaled by how much of the next item is left stranded.
        let stranded = (next_item_size - post_residual) as f64;
        score += (stranded / 20.0).min(15.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If no other bin fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Mild preference for filling fuller bins overall.
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size is pure waste.
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 10 {
        score -= 25.0; // unusable dead space anyway -> effectively perfect
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; penalize leaving medium gaps
            score += (post_residual as f64) * 0.25;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins relative to the fleet's mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Dynamic time horizon: early in the stream, keep residual space flexible
    // (mild penalty for very tight fits); late in the stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;
    if progress < 0.3 && post_residual > 0 && post_residual < item_size as f64 * 0.5 {
        score += 5.0 * (1.0 - progress);
    }

    // Penalize opening a new bin when open bins exist with decent room,
    // unless the item is large and nothing fits well.
    if bin_residual == bin_capacity {
        let base = 15.0 + open_bins_count as f64 * 2.0;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { base };
        score += scarcity;
        // Late in the stream, opening new bins is even less attractive.
        score += progress * 10.0;
        // But if the item is huge and would leave a big gap anywhere, new bin is fine.
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Slight preference for bins with large residual when item is small.
    if item_size <= 30 {
        score += (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial base: quadratic in normalized post residual.
    let x = pr / cap; // 0..1
    let mut score = 4.0 * x * x - 3.0 * x * x * x; // smooth, minimized near full packing

    // Reward tight fits via cubic coupling of item size with residual fill ratio.
    let fill = it / bin_residual.max(1) as f64;
    score -= 6.0 * fill * fill * fill;

    // Stream progress coupling: later in the stream, prefer filling existing bins harder.
    let late = progress * progress;
    score += late * x * x * 3.0;

    // Lookahead: if next item fits into post residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = (next_item_size as f64) / (pr + 1.0);
        score -= 2.5 * snug;
    } else if next_item_size > 0 {
        // penalize leaving residuals that strand the next item
        score += 1.5 * (1.0 - (pr / cap));
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when good fits exist.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 3.0 + 4.0 * openness * (1.0 - late);
        // but allow new bin if item is large and would leave tiny residual elsewhere
        if it > 0.7 * cap {
            score -= 2.0;
        }
    }

    // Mild penalty when bin residual deviates from mean residual (keeps bin pool balanced).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity fractions.
    // Residuals that are "harmonically useful" (multiples of common size classes) are rewarded.
    let pr = post_residual;
    let class_score = match pr {
        0 => -12.0,                                  // perfect fit
        1..=5 => -6.0,                               // near-perfect, tiny dead space
        6..=15 => 3.0,                               // dead zone: too small for most items
        16..=30 => -2.0,                             // fits small items (1..30 class)
        31..=50 => 1.0,                              // mid zone
        51..=70 => -1.5,                             // fits medium items
        _ => 0.0,
    };
    score += class_score;

    // Modulo arithmetic on post_residual: reward residuals divisible by common item granularities.
    if pr > 0 {
        if pr % 10 == 0 { score -= 2.5; }            // decade-aligned residual is reusable
        else if pr % 5 == 0 { score -= 1.0; }
        // Penalize awkward odd residuals in the low dead zone
        if pr < 16 && pr % 2 == 1 { score += 2.0; }
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward proportionally to how snugly next item fits
            let slack = (pr - next_item_size) as f64;
            score -= 4.0 - (slack / bin_capacity as f64) * 4.0;
            // Extra reward for exact next-item fit
            if next_item_size == pr { score -= 5.0; }
        } else {
            // Post residual cannot host next item: penalize by overflow gap
            let gap = (next_item_size - pr) as f64;
            score += (gap / 20.0).min(4.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread_penalty = (open_bins_count as f64) * 0.15 * (0.5 + progress);
    score += spread_penalty;

    // Mean-residual coupling: prefer bins below mean residual (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate: only attractive when current bin would leave a bad harmonic class
    // or when bin is nearly full anyway.
    if bin_residual == bin_capacity {
        let bad_leftover = pr > 0 && pr < 16;
        if bad_leftover || next_item_size > pr {
            score -= 3.0;   // fresh bin beats a bad fit
        } else {
            score += 8.0;   // keep using open bins when fit is decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Smallest possible item is 1; treat gaps < 10 (below the classic min size)
    // as unusable dead space and penalize them quadratically.
    let dead = post_residual < 10;
    if dead {
        score += 40.0 + (post_residual as f64) * (post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    } else {
        // Usable gap: mildly reward tighter fits, scaled by how much slack remains.
        score -= 8.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // --- Last-chance pressure ---
    // If this is the only bin that can fit the item, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- Open-bin pressure ---
    // Many open bins: prefer consolidating into existing bins, penalize
    // candidates that leave large slack (fragmentation).
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * (post_residual as f64) * 0.05;

    // --- New-bin candidate handling ---
    // An empty bin has post_residual == bin_capacity; only attractive when
    // no open bin fits or the fit would be terrible.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) < 0.0; // never true for empty bin
        let _ = poor_fit;
        if fitting_bins_count <= 1 {
            score -= 20.0; // nothing usable open: open a new bin
        } else {
            score += 15.0 + open_pressure * 5.0; // discourage opening when others fit
        }
    }

    // --- Lookahead coupling ---
    // If the next item could use this bin's post_residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for next item: slight penalty (future dead space risk).
        score += 3.0;
    }

    // --- Stream progression ---
    // Late in the stream, be more conservative: keep existing bins tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual - post_residual as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step lookahead match: next item exactly fills the bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too: reward closeness of match.
            score -= 0.5 * (post_residual as f64 - next_item_size as f64).abs();
        } else {
            // Dead space: post_residual too small for the next item.
            // Penalize proportionally to wasted space, heavier when the waste is small (near miss).
            let waste = post_residual as f64;
            score += 0.3 * waste;
            if waste < 10.0 {
                score += 8.0; // tiny unusable sliver is very bad
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the current mean residual (best-fit flavor).
    score -= 0.2 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it unattractive unless all open bins would leave
    // large dead space. Base penalty grows with number of open bins.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // Allow opening a new bin early in the stream when few bins exist.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared penalty on wasted space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual > 0 {
            score += 12.0;
        }
        // Chain fit: item + next item exactly fills bin.
        if item_size + next_item_size == bin_residual {
            score -= 55.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 85.0;
        // If no open bin fits or the only fit is very loose, allow new bin.
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 1 {
            let slack = (bin_capacity as f64 - mean_residual).abs();
            if slack > 0.5 * bin_capacity as f64 {
                score -= 60.0;
            }
        }
        // Early in stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 25.0;
    }

    // Congestion pressure: many open bins with low mean residual -> prefer consolidation.
    let mean_res_gap = (mean_residual - bin_residual as f64).abs();
    score += 0.08 * mean_res_gap;

    // Prefer larger residual bins slightly (best-fit bias via post_residual already).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, larger residuals are fine; late in the stream, penalize wasted space quadratically.
    let norm_pr = pr / cap;
    let t = progress;
    let coupling = norm_pr * norm_pr * (0.5 + 2.5 * t * t) * cap;
    score += 0.35 * coupling;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tight = (1.0 - norm_pr).powi(3);
    score -= 8.0 * tight * (0.5 + 0.5 * t);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * t;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 5.0 * (1.0 - slack * slack);
        } else {
            score += 2.0 * ((nx - pr) / cap);
        }
    }

    // Penalize bins far from the mean residual (fragmentation pressure), smoothly.
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + t);

    // Mild penalty when many bins are already open (encourage consolidation early).
    score += 0.02 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class 0: residual in [0,10)   -> dead space, penalize mildly.
    // Class 1: residual in [10,20)  -> small-item friendly, reward.
    // Class 2: residual in [20,40)  -> medium, neutral.
    // Class 3: residual >= 40       -> large leftover, reward strongly (bin still flexible).
    let r = post_residual;
    if r == 0 {
        score -= 25.0; // perfect fit
    } else if r < 10 {
        score += 6.0; // dead space penalty
    } else if r < 20 {
        score -= 8.0; // small items (10..20 common) fit next
    } else if r < 40 {
        score -= 2.0;
    } else {
        score -= 10.0;
    }

    // Modulo-arithmetic harmony: leftover that is a multiple of common item
    // granularities (10, 20, 25) is more reusable.
    if r > 0 {
        if r % 10 == 0 { score -= 5.0; }
        if r % 25 == 0 { score -= 4.0; }
        if r % 20 == 0 { score -= 3.0; }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= r {
        if next_item_size == r {
            score -= 30.0;
        } else if r - next_item_size < 10 {
            score -= 18.0; // near-perfect lookahead fit
        } else {
            score -= (r - next_item_size) as f64 * 0.15;
        }
    }
    // Next item cannot fit here: penalize proportionally to wasted potential.
    if next_item_size > r && next_item_size > 0 {
        score += 5.0 + (next_item_size - r).min(30) as f64 * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is bad.
    if bin_residual == bin_capacity {
        // Empty bin baseline: attractive early or when few bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 - 15.0 * (1.0 - progress) - 3.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= item_size {
            score += 10.0; // pairing with next item makes fresh bin attractive
        }
        if fitting_bins_count == 1 {
            score += 25.0; // don't abandon the last usable bin
        }
    }

    // Mild preference for tighter bins (below mean residual = tighter).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect closure is ideal.
        score -= 60.0;
    } else {
        // Usable residual: reward if it can host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Reward leaving residual >= 10 (still reusable).
        score -= 5.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit badly.
        // Penalize new bins mildly, more when open bins already exist.
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if the item is huge and leaves a small residual elsewhere,
        // the new-bin penalty stands so tight fits win.
        if item_size >= 70 {
            score += 10.0;
        }
    } else {
        // Existing bin with residual close to mean residual: neutral;
        // bins with residual far above mean are less attractive (loose bins).
        if (bin_residual as f64 - mean_residual).abs() < 5.0 {
            score -= 8.0;
        }
    }

    // Early in the stream, be more willing to open bins (future unknown);
    // late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Leftover after next item would be post_residual - next_item_size.
            let leftover = (post_residual - next_item_size) as f64;
            // Penalize leftovers that are small (dead space) but reward large usable leftovers.
            if leftover < 10.0 {
                score += (10.0 - leftover) * 2.0;
            } else {
                score -= leftover.min(40.0) * 0.3;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to how much space is wasted.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    } else {
        // Last item: only current fit matters; favor tight packing.
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Compare against mean residual of open bins: prefer bins that absorb more than average.
    score += (mean_residual - item_size as f64) * 0.2;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when plenty of open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        // Early in the stream, opening bins is cheaper (spread items out for future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // If the new empty bin would also perfectly match the next item, make it more attractive.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Mild reward for very tight fits regardless of lookahead.
    if post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize if post_residual is a small unusable sliver that
    // cannot host the next item (dead space creation).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.35 * waste;
        }
        // Reward leaving exactly enough room for the next item (perfect chaining).
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Reward leaving a residual that still leaves flexible remainder for next item.
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless this bin's fit is bad
    // or there are no good alternatives.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: proportional to item size (bigger items
        // benefit more from a fresh bin since they dominate capacity).
        score = cap - item_size as f64 + 30.0;
        // Early in the stream, new bins are cheap (plenty of future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If few fitting bins exist, opening a new bin is more attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            score += 20.0; // existing last-chance bin already gets bonus
        }
        // Large items relative to capacity favor fresh bins.
        if (item_size as f64) > 0.6 * cap {
            score -= 15.0;
        }
    } else {
        // Using an existing bin: mild reward when open bins are plentiful and
        // mean residual is high (spread load to keep flexibility).
        if (mean_residual - post_residual as f64) > 0.0 {
            score += 0.05 * (mean_residual - post_residual as f64);
        }
        // Penalize placing into a bin whose residual is much larger than needed
        // when other bins could take it (fragmentation avoidance).
        if fitting_bins_count > 1 {
            let excess = (bin_residual - item_size) as f64;
            if excess > 40.0 {
                score += 0.15 * (excess - 40.0);
            }
        }
    }

    // Late-stream consolidation: as stream ends, prefer filling existing bins
    // tightly to avoid leaving many half-empty bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;

    // Small global-state coupling: many open bins -> encourage consolidation.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 1.5 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = norm_pr * (1.0 + 0.8 * t * norm_pr + 0.5 * t * t * (1.0 - norm_pr) * (1.0 - norm_pr));

    let mut score = 1.5 * pr + poly * cap * 0.3;

    // Reward tight fits more aggressively as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_size as f64 * (0.5 + t);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (0.5 + t);
    }

    // Lookahead: penalize if post_residual can't fit next item but could almost
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt && pr - nxt < item_size as f64 * 0.3 {
            score -= 8.0; // leaves a near-useless sliver for next item
        }
        if pr < nxt && pr > 0.0 {
            score += 6.0 * (nxt - pr) / cap; // dead space relative to lookahead
        }
    }

    // Prefer filling bins when many bins are open (bin consolidation)
    score -= (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // Mild attraction to bins near mean residual (balance preservation)
    score += (mean_residual - pr).abs() * 0.05;

    // New-bin candidate: neutral-ish baseline with progress-dependent cost
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * t) - tightness * 0.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual: modulo classes over capacity ----
    let pr = post_residual as u32;
    let class = pr % 25; // quarter-capacity harmonic classes
    // Class 0 (perfect fit) heavily rewarded; small classes are dead-space prone
    let class_bonus: f64 = match class {
        0 => 60.0,
        1..=5 => -18.0,          // tiny slivers are near-useless
        6..=12 => 6.0,           // moderate
        13..=19 => 12.0,         // roomy residual
        _ => 3.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: post_residual divisible by common item sizes
    for d in [10u32, 20, 25, 50] {
        if pr != 0 && pr % d == 0 {
            score -= 14.0;
        }
    }

    // ---- Lookahead coupling: does next item fit the post residual? ----
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item chains nicely: reward proportionally to tightness
            let tight = (pr as f64 - next_item_size as f64) / cap;
            score -= 30.0 * (1.0 - tight);
            // harmonic match: next_item divides post_residual
            if next_item_size > 0 && pr % next_item_size == 0 {
                score -= 25.0;
            }
        } else {
            // next item won't fit here: residual likely becomes dead space
            score += 15.0;
        }
    }

    // ---- Tightness of current fit ----
    if post_residual == 0 {
        score -= 80.0; // perfect packing
    }

    // ---- Last-chance bin pressure ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0; // avoid opening a new bin if this is the only fit
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base penalty so fresh bins are used only when fits are poor
        score += 45.0;
        // Early stream: building a few bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // Many open bins with low mean residual -> prefer consolidation
        score += open_bins_count as f64 * 2.0;
        if mean_residual < cap * 0.25 && open_bins_count > 2 {
            score += 25.0;
        }
        // If next item is large and nothing fits well, a fresh bin is attractive
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // ---- Mean residual alignment: prefer bins near the mean (balanced packing) ----
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild late-stream consolidation pressure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=15) are heavily penalized
    // because almost no item can fit there later.
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (1.0 - (post_residual as f64) / 15.0);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_frac;

    // Last-chance pressure: if this is the only bin that fits, prefer it
    // strongly over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening a new one.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // New-bin candidate handling: an empty bin is only attractive when the
    // current item is large (little residual waste potential) or no real
    // alternative exists; otherwise penalize opening a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 >= 0.6 * bin_capacity as f64;
        if large_item || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
    }

    // Lookahead: if next item would fit exactly in the post-residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the gap -> the gap is likely dead space.
        score += 8.0;
    }

    // Mean residual coupling: placing into a bin whose residual is below
    // average (already partially packed) is preferable.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Post-residual too small for the next item: penalize wasted dead space
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 2.0;
    }

    // Post-residual larger than needed but still fits next item: mild reward scaled by tightness
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 5.0 / (1.0 + slack * 0.1);
    }

    // Compare against mean residual: bins tighter than average are better to fill
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Late in the stream, prefer closing bins tightly (small residuals)
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += post_residual as f64 * progress * 0.3;

    // Penalize near-empty bins being used when many bins are open (fragmentation risk)
    if post_residual as f64 > mean_residual * 1.5 && open_bins_count > 2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current residuals are tight.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let urgency = (item_size as f64 / bin_capacity as f64).powf(2.0);
        // Penalize new bins; discount the penalty when the item is huge,
        // residuals are tight, and we're early (long horizon to fill bin).
        let discount = urgency * (1.0 - tightness) * (1.0 - 0.5 * progress);
        score += 35.0 * (1.0 - discount);
    } else {
        // Perfect fit reward.
        if post_residual == 0 {
            score -= 60.0;
        } else {
            // Reward leaving space exactly matching the lookahead item.
            if next_item_size > 0 {
                if post_residual == next_item_size {
                    score -= 45.0;
                } else if post_residual > next_item_size {
                    // Dead-space penalty: space too small for the next item.
                    let waste = (post_residual - next_item_size) as f64;
                    score += 0.35 * waste;
                } else {
                    // Post residual smaller than next item: small dead space,
                    // scaled by how close it is to being unusable.
                    let gap = (next_item_size - post_residual) as f64;
                    score += 0.15 * gap;
                }
            }
            // Reward tight fits (small post residual relative to capacity).
            let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
            score -= 20.0 * tightness * tightness;
        }

        // Last-chance bonus: if this is the only fitting bin, strongly prefer
        // using it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Prefer bins with below-average residual (pack dense bins first),
        // keeping some bins loose for future large items.
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 12.0 * dev;

        // Late in the stream, be more aggressive about closing out bins:
        // penalize leaving large residuals when few items remain.
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let horizon = (remaining / total_items.max(1) as f64).clamp(0.0, 1.0);
        score += 8.0 * (post_residual as f64 / bin_capacity as f64) * (1.0 - horizon);

        // Mild bonus for using bins when many are open (avoid bin sprawl).
        if open_bins_count > 4 {
            score -= 1.5 * (open_bins_count as f64).ln();
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on leftover space (dead space is doubly bad late in stream)
    let mut score = post * (1.0 + 1.5 * norm_post * (0.5 + progress));

    // Reward near-perfect fits strongly (smooth exponential coupling)
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness.powi(6);

    // Lookahead coupling: reward residuals that exactly accommodate next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        score -= 8.0 * (-diff / 20.0).exp() * (0.4 + 0.6 * progress);
    } else {
        // Last item: only absolute fill matters
        score -= 6.0 * tightness;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize slightly, less so when many bins are open with fragmented residuals
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        score += 10.0 + 5.0 * (1.0 - frag) * progress;
    } else {
        // Mild preference for bins below mean residual (balance load smoothly)
        score += 0.05 * (post - mean_residual);
    }

    // Smooth stream-progress coupling: tolerate waste early, demand efficiency late
    score *= 1.0 + 0.5 * progress * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item-size classes are reusable; odd remainders are dead space.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit, ideal
    } else if pr % 10 == 0 {
        -25.0
    } else if pr % 5 == 0 {
        -12.0
    } else if pr >= 10 && pr % 2 == 0 {
        -4.0
    } else {
        15.0 // awkward odd residual: penalize
    };
    score += class_bonus;

    // Integer-division threshold on post_residual: bins whose residual falls
    // into the "small leftover" band (<= 15) are effectively closed.
    if pr > 0 && pr <= 15 {
        score += 30.0; // creating a nearly-dead bin
    } else if pr > 15 && pr <= 30 {
        score -= 8.0;
    }

    // Lookahead coupling: reward if the next item fits the post-residual,
    // scaled by how well it harmonizes (divisibility).
    if next_item_size > 0 && (next_item_size as u32) <= pr {
        let harmony = if pr % next_item_size.max(1) == 0 { 25.0 } else { 10.0 };
        score -= harmony;
    } else if next_item_size > 0 {
        score += 6.0; // next item won't fit here
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only prefer a fresh bin late in the stream
    // or when open-bin fits are all poor (large post_residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = (post_residual as f64) > 50.0 && fitting_bins_count > 0;
        if progress > 0.7 || poor_fits {
            score -= 10.0;
        } else {
            score += 20.0; // early stream: prefer filling open bins
        }
    }

    // Mild pressure toward consolidating bins when many are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Slight preference for bins tighter than the mean residual (better fit).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize leaving a dead gap that is smaller than the next item.
        let gap = post_residual as f64;
        if gap > 0.0 {
            score += 0.4 * gap;
        }
    }

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Prefer bins with residual below mean residual (tight packing), penalize
    // wasting space in already-loose bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If next item is large and no tight fit exists, opening a new bin
        // becomes relatively better when mean residual is large.
        score -= 0.2 * mean_residual;
    }

    // Early in the stream, be slightly more willing to open bins (build diversity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: strongly reward tight fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if the next item can use this bin's post-residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't chain here; penalize large wasted residuals.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should be costly unless
    // no good fit exists. An empty-bin call has high post_residual; penalize.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, softened when few bins are open (early stream)
        // or when the mean residual across open bins is too small for the item.
        let early = (step_index as f64) / (total_items.max(1) as f64);
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let mean_too_small = if (mean_residual as u32) < item_size { 1.0 } else { 0.0 };
        score += 40.0 * (1.0 - 0.5 * early) - 25.0 * desperation.max(mean_too_small);
        // Slight bonus if next item is large and would fit well in fresh bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Global state: many open bins with high mean residual -> consolidate,
    // prefer bins below mean residual (filling emptier bins less is bad).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Time horizon: late in the stream, tighten packing aggressively.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Mild penalty proportional to number of open bins to encourage closure.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but with a non-linear (quadratic) penalty on wasted space.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of wasted space with stream progress:
    // dead space matters more as the stream advances.
    score += 25.0 * norm_pr * norm_pr * progress * (2.0 - progress);

    // Reward near-perfect fits (post_residual small relative to capacity).
    let perfect_fit = (cap - pr) / cap; // fill fraction
    score -= 12.0 * perfect_fit * perfect_fit * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // next item can't use the leftover; penalize proportionally.
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure toward consolidating bins when many are open.
    score += (open_bins_count as f64) * 0.15 * norm_pr;

    // Keep score comparable with the new-bin candidate (post_residual == cap).
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual (decade buckets): reward near-full bins
    let cls = post_residual / 10;
    score += match cls {
        0 => -25.0,          // almost perfectly packed
        1 => -10.0,
        2 => 0.0,
        3 => 8.0,
        _ => 15.0,           // large leftover: poor class
    };

    // Dead-space penalty: leftover too small for the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Lookahead bonus: next item nests into the leftover, reward tightness of the nest
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= (20 - gap.min(20)) as f64 * 0.8;
    }

    // Perfect pairing: item + next item exactly fill the bin
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 5.0;
        if fitting_bins_count == 0 {
            // No open bin fits: opening a new bin is mandatory
            score -= 40.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Leave room for a clean pair in the fresh bin
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Coupling with mean residual across open bins: prefer bins whose leftover
    // diverges from the mean in the useful direction (below mean = tighter use)
    score += (mean_residual - post_residual as f64) * 0.05;

    // Late-stream pressure: as the stream progresses, push harder toward tight packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity.saturating_sub(post_residual)) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harder than large ones.
    // A residual that is too small for the smallest possible item (1) is pure waste,
    // but gaps below ~10 are especially hard to fill under the original 10..80 regime.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, prefer consolidating into them
    // (penalize opening new bins) by adding pressure scaled to open_bins_count.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + (open_bins_count as f64) * 1.5;
    } else {
        // Slight reward for using existing bins as open count grows.
        score -= (open_bins_count as f64) * 0.4;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly (sets up a perfect follow-up).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward.
            score -= 4.0;
        } else {
            // Next item will not fit in this bin afterward: mild penalty,
            // stronger if the leftover is dead space.
            score += 2.0;
            if (post_residual as f64) < dead_threshold {
                score += 4.0;
            }
        }
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps residuals uniform, easier to pack future items); penalize outliers.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.15;

    // Early in the stream, be slightly more willing to open bins (spread items);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score -= (1.0 - progress) * 5.0;
    } else {
        score += progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack / 10.0); // next item fits with some slack
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 * (gap / 40.0).min(2.0); // next item won't fit: penalize
        }
    } else {
        // Last item: prefer minimal residual, extra reward for exact fill.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Tight fits are good: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Penalize residuals far below mean (fragmentation) but reward above-mean fits mildly.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 8.0;
    } else if (post_residual as f64) > mean_residual {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when a decent fit exists in open bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0; // new bin fine if it enables a 2-chain
        } else if fitting_bins_count > 0 {
            score += 30.0; // discourage new bin when open bins fit
        }
    }

    // Early stream: be slightly greedy for tight packing; late stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Reward exact or near-exact fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64)).abs();
        } else {
            // dead space for the known next item
            score += 0.35 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bonus: only one bin can fit the item; strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Penalize opening new bins when many open bins with slack exist
    if bin_residual == bin_capacity {
        // new-bin candidate
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_slack = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // opening a new bin is fine early or when open bins are full
        score += 10.0 + 25.0 * (1.0 - progress) - 0.5 * avg_slack;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // mild penalty for using bins that are much emptier than average (fragmentation)
        let dev = bin_residual as f64 - mean_residual;
        score += 0.08 * dev;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste coupling with stream progress.
    let mut score = norm_pr * (1.0 + progress * norm_pr * 2.0);

    // Smooth cubic interaction: tight fits rewarded more as stream advances.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * (0.5 + progress);

    // Penalize residuals that no typical item can use (dead space), smoothly.
    let dead = if pr > 0 { (pr - next_item_size.max(1) as f64).max(0.0) / cap } else { 0.0 };
    score += dead * dead * (1.0 + 2.0 * progress);

    // Lookahead coupling: reward leaving room for the next item smoothly.
    let next_fits = (next_item_size as f64 <= pr) as i32 as f64;
    let nxt = next_item_size as f64 / cap;
    score -= next_fits * nxt * (1.0 + progress);

    // Last-chance bonus: only bin that fits -> strong smooth reward.
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= last_chance * (2.0 + 3.0 * progress) * (1.0 - norm_pr);

    // Congestion pressure: many open bins -> prefer filling existing ones.
    let congestion = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += congestion * norm_pr * 0.5;

    // Mean-residual anchoring: prefer bins near the mean residual (smooth).
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // New-bin candidate: penalize mildly unless residual is large and progress low.
    let is_new = (bin_residual == bin_capacity) as i32 as f64;
    score += is_new * (1.5 + 2.0 * progress) * (1.0 - norm_pr * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual modulo 10: dead-space classes
    let cls = post_residual % 10;
    // Class 0: perfectly divisible residual -> great
    if cls == 0 {
        score -= 12.0;
    }
    // Classes 1..9: dead space severity, worst are 1..5 (unusable for items >=10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: nothing else can ever fit
    } else {
        match cls {
            1..=5 => score += 18.0 + 3.0 * (5 - cls) as f64,
            6..=9 => score += 4.0,
            _ => {}
        }
    }

    // Tight fit reward: post_residual small relative to smallest possible item
    if post_residual <= 10 && post_residual > 0 {
        score -= 20.0;
    }

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item can chain into this bin: reward, especially near-exact
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / 100.0);
            // harmonic bonus when next fills bin exactly
            if next_item_size == post_residual {
                score -= 25.0;
            }
            // modulo harmony: next_item_size divides into post_residual class
            if post_residual % 10 == next_item_size % 10 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize leaving mid-range residual
            score += 8.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets neutral residual score,
    // but discourage opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        // fresh bin baseline; make it unattractive unless current fit is terrible
        score += 45.0;
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // many open bins with slack: don't open another
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 25.0;
        }
    }

    // Prefer bins whose residual deviates favorably from mean (use the fullest bins)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Small global pressure to keep open bin count low
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=10)
    // are effectively unusable; penalize heavily as they approach the dead zone.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Penalize "awkward" small gaps that few future items can use (e.g. 11..25).
    if post_residual >= 11 && post_residual <= 25 {
        score += (25 - post_residual) as f64 * 2.5;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.35 * (bin_residual - item_size) as f64;
    }

    // Lookahead: strongly prefer bins where the next item also fits the residue.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 14.0 + 0.3 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residue too small for the upcoming item: mild penalty, scaled by tightness.
        score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
    }

    // Open-bin pressure: when many bins are open, favor consolidating into
    // existing bins (penalize the new-bin candidate more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 25.0 + open_bins_count as f64 * 3.0 + mean_residual * 0.15 + 10.0 * (1.0 - progress);
    } else {
        // Existing bin: mild reward proportional to how full the fleet is.
        score -= 2.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // Prefer using bins with below-average residual (emptier bins stay flexible,
    // tighter bins get closed out) — gently steer toward tight bins.
    score += 0.08 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 2.0;
    }
    // Next item cannot use the leftover: penalize dead space proportionally
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Penalize unusable dead space relative to smallest plausible item
    if post_residual > 0 && post_residual < 1 {
        score += 500.0;
    }

    // Prefer tighter bins relative to the mean residual
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
    }

    // Slight pressure to consolidate early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item could plausibly use:
    // dead space = post_residual that is smaller than the smallest plausible item (1..100 unknown),
    // approximate with a fraction of capacity.
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            let overflow = (next_item_size - post_residual) as f64;
            score += 3.0 * (overflow / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, prefer keeping residuals flexible
    // (moderate residuals); late in the stream, just minimize post residual.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let flexibility = (post_residual as f64 - mean_residual).abs();
    score += (1.0 - t) * 4.0 * (flexibility / bin_capacity as f64);

    // Many open bins: encourage consolidation into existing bins.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: placing into a bin far below mean residual
    // balances the pool slightly.
    score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // New-bin candidate: only attractive when current item is large relative
    // to capacity or nothing fits well.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.7;
        let poor_options = fitting_bins_count == 0;
        if large_item || poor_options {
            score -= 10.0;
        } else {
            score += 35.0; // discourage wasting a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with a non-linear (quadratic) dead-space penalty.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, dead space hurts more.
    score += 12.0 * progress * norm_pr * (1.0 - norm_pr);

    // Prefer tight fits: reward small normalized post-residual via smooth cubic term.
    score -= 10.0 * (1.0 - norm_pr).powi(3);

    // Lookahead: if next item fits in the post-residual, reward; else penalize smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (nxt / cap)) * (pr / nxt).ln().max(0.0);
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin (only fitting bin): smooth penalty for opening new bins late.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize gently, more when many bins are open or fit is wasteful.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.05 * open_bins_count as f64 + 20.0 * norm_pr * (1.0 - norm_pr);
    }

    // Mild deviation from mean residual: favor bins near the mean (balanced packing).
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (multiples of 10/20/25) are more reusable -> reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    if pr == 0 {
        // Perfect fit: extremely desirable.
        score -= 1000.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else {
        // Ugly dead space: penalize small useless remainders.
        if pr < 10 { score += 25.0; }
        else { score += 5.0; }
    }

    // Integer-division thresholds: how many "average" items still fit?
    let avg_item = if next_item_size > 0 { (item_size + next_item_size) / 2 } else { item_size };
    if avg_item > 0 {
        let fits_k = pr / avg_item;
        score -= fits_k as f64 * 6.0;
    }

    // Lookahead coupling: does the next item land on a harmonic class
    // matching this post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 60.0; // next item packs perfectly here
            } else if gap % 10 == 0 {
                score -= 12.0;
            } else if gap < 10 {
                score += 10.0; // creates tiny dead space next step
            }
        } else {
            // Next item cannot fit here; slight penalty unless residual is tiny.
            if pr >= next_item_size.saturating_sub(1) {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when this bin's residual is far
    // from any useful harmonic class or the stream is early and bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        let penalty = 40.0 + 60.0 * (1.0 - progress) + 5.0 * openness;
        // Allow new bin only if current residual is genuinely useless (< 15)
        // and mean residual across bins is already small.
        let useless = if pr < 15 { 55.0 } else { 0.0 };
        score += penalty - useless;
    }

    // Mild diversity pressure: prefer bins whose residual differs from mean
    // residual (keeps a spread of residual classes available).
    let dev = (post_residual as f64 - mean_residual).abs();
    score -= 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

