    }
    // Moderate penalty for gaps that cannot fit typical next items (10..80).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize opening a brand-new bin when open bins can fit the item.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + 5.0 * open_bins_count as f64;
    }
    // Encourage using a new bin early in the stream (flexibility later).
    if bin_residual == bin_capacity && open_bins_count == 0 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor filling it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> favor compacting into existing space.
    score += 0.5 * open_bins_count as f64;

    // Favor bins tighter than the mean residual (good fits first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit post_residual, penalize leaving a stranded gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
