    }

    // Discourage opening new bins when decent open bins exist; encourage when
    // residuals are tight (mean residual low) and stream is early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above well-fitting open bins.
        score = bin_capacity as f64 * 0.9;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        if mean_residual < 25.0 && open_bins_count > 0 {
            score += 15.0 * (1.0 - progress);
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
        score -= 0.5 * (mean_residual - bin_residual as f64);
    }

    // Mild preference for keeping few open bins (consolidation pressure).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic penalty on wasted space, scaled by capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac * bin_capacity as f64;

    // Perfect fit: strong bonus (subtract).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let next_leftover = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - next_leftover / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize bins whose post_residual becomes dead space
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when item is large relative
    // to typical residuals or existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 > mean_residual * 0.85;
        if large_item || mean_residual < item_size as f64 * 0.6 {
            score -= 15.0 + 10.0 * (1.0 - progress);
        } else {
            score += 10.0;
        }
        // Late in stream, prefer consolidating into open bins.
        if progress > 0.8 {
            score += 12.0;
        }
    }

    // Prefer bins below mean residual (more filled bins) mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Reward spreading across many bins when stream is long (avoid overloading).
    score -= 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer small post residual, with non-linear polynomial shaping.
    let mut score = norm_post * norm_post * (1.0 + 2.0 * progress) + 0.5 * norm_post;

    // Tight-fit reward: smooth cubic coupling of post residual with progress.
    score -= 3.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic coupling).
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let compat = 1.0 - ((pr - n).abs() / cap).min(1.0);
        score -= 2.0 * compat * compat * (0.5 + progress);
    }

    // Mild penalty for proliferating bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * 0.05 * progress;

    // New-bin candidate: penalize opening a fresh bin unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        score += 2.0 - 2.0 * (item_size as f64 / cap) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact-fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Classify post_residual by capacity fractions (harmonic bins).
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac <= 0.05 {
        score -= 60.0; // nearly full bin: excellent
    } else if frac <= 0.1 {
        score -= 40.0;
    } else if frac <= 0.25 {
        score -= 15.0;
    } else if frac <= 0.5 {
        score -= 5.0;
    } else {
        score += 10.0; // more than half wasted: penalize
    }

    // Dead-space class: residuals that few item sizes can fill.
    // Residuals in (0,10) are unusable dead space for items >= 10,
    // but with unknown distribution (1..100) small residuals still have value.
    if post_residual < 5 {
        score += 25.0;
    }

    // Modulo-class coupling: if the next item exactly matches the post
    // residual, this bin is a perfect two-step chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Harmonic residue classes of the gap.
            match gap {
                0 => score -= 120.0,
                g if g < 5 => score -= 20.0,
                g if g % 10 == 0 => score -= 12.0,
                g if g <= 15 => score -= 8.0,
                _ => {}
            }
        } else {
            // Next item cannot follow into this bin: leftover becomes terminal.
            score += 8.0;
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // or the stream is early (plenty of items left to fill it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_item = item_size as f64;
        // A fresh bin is good if the current fit elsewhere is poor
        // (large post_residual relative to capacity) and many items remain.
        let poor_fit = post_residual as f64 > 0.6 * bin_capacity as f64;
        if poor_fit && progress < 0.9 {
            score -= 30.0 + 20.0 * (1.0 - progress);
        } else {
            score += 80.0; // discourage opening new bins by default
        }
        let _ = avg_item;
    }

    // Slight preference for tighter (smaller-residual) bins overall.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Tie-break noise-free harmonic jitter on bin index proxy via mean residual.
    score -= (mean_residual - post_residual as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize gaps too small for the smallest plausible item (<= 10% of capacity).
    let dead_threshold = bin_capacity as f64 * 0.1;
    if post_residual as f64 > 0.0 && post_residual as f64 <= dead_threshold {
        score += (dead_threshold - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item would not fit and gap is dead, penalize.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 8.0;
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Deviation from mean residual: prefer bins with residuals close to the item need.
    score += (bin_residual as f64 - item_size as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference for tight fits: post_residual already does most of the work.

    // 2-step lookahead: strongly reward bins where the next item fits the post_residual exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect 2-item chain: huge reward.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Reward proportional to how close next item brings us to a full bin.
                let chained_fill = (next_item_size as f64) / (post_residual as f64).max(1.0);
                score -= 25.0 * chained_fill;
                // Penalize leaving a gap that no item can plausibly use.
                if gap < 10.0 {
                    score += 12.0; // tiny dead space
                }
            }
        } else {
            // Next item cannot fit here: post_residual becomes dead space unless small.
            if post_residual > 0 {
                score += (post_residual as f64) * 0.35;
            }
        }
    } else {
        // Last item: only a perfect fill matters.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Reward bins that are more full than average (consolidation).
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * (fullness - 0.5);

    // Relative residual vs mean residual: prefer bins with residual near what we consume.
    let res_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * res_gap;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current placement would waste a lot.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if item is huge and would leave unusable residue elsewhere, opening may be right.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 35.0;
        }
    }

    // Early in stream: be more willing to open bins for flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.25 {
        score -= 5.0 * (1.0 - progress * 4.0);
    }

    // Penalize creating very small unusable residuals (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual dominates the score.
    score -= 0.9 * (bin_capacity as f64 - post_residual as f64).ln().max(0.0);

    // Penalize dead space: post_residual that no plausible item (>=1) can
    // exploit is pure waste; scale penalty by how close it is to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (10.0 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Lookahead: if the next item would fit exactly in the post-residual,
    // this placement chains perfectly; reward it. If the next item would
    // no longer fit anywhere, mild penalty for blocking.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged when existing bins fit decently.
        let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 14.0 * tightness;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins with slack: definitely reuse them.
        if mean_residual > item_size as f64 * 1.5 {
            score += 6.0;
        }
        // But if the item is huge and open bins are all poor fits, new bin
        // is fine (baseline score already high via post_residual == 100).
        if item_size > 70 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // Mild penalty for spreading across too many bins.
        score += (open_bins_count as f64).ln() * 1.5;
        // Prefer bins whose residual is close to mean (balanced usage),
        // penalize outliers slightly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Small deterministic tie-breaker favoring fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty for dead space.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, waste is punished more aggressively.
    let progress_coupling = 1.0 + 1.5 * progress * progress + 2.0 * progress * norm_pr;
    score *= progress_coupling;

    // Last-chance bonus: strongly reward the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (good fit), smooth term.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Lookahead: reward if next item fits into the post-residual, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (pr - nxt) / cap;
        } else {
            score += 2.0 * (nxt - pr) / cap * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutralize its raw post_residual so it competes fairly,
    // penalized slightly more as the stream progresses (prefer packing existing bins).
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable" classes
    // (multiples of small item sizes) are rewarded; awkward dead-space classes penalized.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward post-residuals divisible by common small item sizes (harmonic classes)
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Penalize dead space in awkward classes (small, hard-to-fill leftovers)
        if pr < 10 && pr > 0 {
            score += 12.0;
        }
    } else {
        // Perfect fit: strongly reward
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of slack after hypothetical next placement
            if slack % 10.0 == 0.0 {
                score -= 8.0;
            } else if slack < 10.0 {
                score += 6.0;
            }
            score += slack * 0.15;
        } else {
            // next item won't fit here: mild penalty proportional to wasted potential
            score += 3.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this fits reasonably
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score += 15.0 - 20.0 * frac;
        // early in stream, opening fresh bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Prefer tighter bins (small residual before placement) slightly
    score += (bin_residual as f64) * 0.05;

    // Mean-residual coupling: when mean residual is high, spread items; else pack tight
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Waste that cannot host the next item: penalize proportionally.
        score += 0.15 * post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    if bin_residual < bin_capacity {
        score += 0.35 * open_bins_count as f64 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmented = mean_residual > 0.0 && mean_residual < item_size as f64;
        if fragmented {
            score -= 12.0;
        } else {
            score += 30.0;
        }
    }

    // Slight late-stream tightening: prefer consolidating as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item fits exactly into the post residual (2-step lookahead match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how tightly the next item fills the leftover space.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill_ratio;
        } else {
            // Next item won't fit here: penalize large dead space.
            score += 10.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 15.0;
    }

    // Penalize creating very small unusable residuals (dead space) unless perfectly matched.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins have plenty of room, unless lookahead matches.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_r = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if mean_r > 2.0 * item_size as f64 && !(next_item_size > 0 && next_item_size == post_residual) {
            score += 30.0;
        }
        // Prefer reusing bins that still have decent residual relative to mean.
        score += 5.0;
    }

    // Slight preference for bins with residual close to mean (balanced packing),
    // damped as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev * (1.0 - 0.5 * progress);

    // Reward tight fits (small post residual) more aggressively early on.
    score -= (1.0 - progress) * 0.2 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty grows fast for dead space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the known next item: penalize proportionally.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if bin_residual < bin_capacity {
        score -= pressure * 0.5 * (0.5 + progress);
    }

    // New-bin candidate: only attractive when item is large and no open bin fits well,
    // or late in the stream with high fragmentation.
    if bin_residual == bin_capacity {
        let fit_quality = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 35.0 - 45.0 * big_item - 30.0 * fit_quality - 10.0 * (1.0 - progress);
        // If many open bins already fit, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Slight preference for bins whose residual is "compatible" with typical sizes (multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;
    let mut score = post;

    // non-linear polynomial coupling of post_residual with stream progress
    let poly = pr * pr * (1.0 - progress) + pr * progress * progress;
    score += 40.0 * poly;

    // reward tight fits, more strongly late in the stream
    score -= (1.0 - pr) * (1.0 - pr) * (30.0 + 60.0 * progress);

    // penalize opening a new bin when existing bins fit, scaled by progress
    let is_new = (bin_residual == bin_capacity) as f64;
    score += is_new * (20.0 + 60.0 * progress) * (1.0 + (fitting_bins_count as f64).ln().max(0.0));

    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // lookahead: penalize wasting space the next item could use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 15.0 * (1.0 - (nx / cap).abs() * 0.5) * (0.5 + 0.5 * progress);
        } else {
            score += 10.0 * ((nx - post) / cap) * (0.5 + 0.5 * progress);
        }
    }

    // mild coupling with mean residual to balance load
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fractions (1/2, 1/3, 1/4)
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Reward exact or near-exact fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= quarter {
        score -= 12.0;
    } else if post_residual <= third {
        score -= 5.0;
    } else if post_residual <= half {
        score += 3.0;
    } else {
        score += 8.0;
    }

    // Modulo arithmetic: dead space in classes of 5 -> penalize non-smooth residuals
    let m = post_residual % 5;
    score += (m as f64) * 0.6;

    // Lookahead: does next item fit into post_residual? Reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Harmonic coupling: next item leaves a small remainder too
            let next_post = post_residual - next_item_size;
            if next_post <= quarter {
                score -= 8.0;
            }
        } else {
            score += 6.0;
            // If next item fits exactly in current residual but not post, mild penalty
            if next_item_size == bin_residual {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        } else if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // Opening a fresh bin gives a full post_residual for the next item
            score -= 10.0;
        }
    }

    // Prefer bins with below-mean residual (tighter bins get filled first)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild pressure against accumulating many open bins
    score += (open_bins_count as f64) * 0.05;

    // Slight early-stream aggression: pack tight early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible future item are heavily penalized.
    // Treat residuals < ~10 (min item size heuristic) as fully dead.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 1000.0; // unusable gap -> very bad
    } else {
        // Penalize small-but-nonzero residuals super-linearly (wasted space).
        let r = post_residual as f64;
        score += 40.0 * (dead_threshold / r).powi(2);
    }

    // Reward tight fits: near-zero post_residual gets a big bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over spreading out; penalize placements that leave large slack.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            // still fits next item: mild reward
            score -= 20.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // New-bin candidate: neutral-ish baseline; only preferred when the current
    // item would leave a large dead gap in every open bin (handled above via
    // dead-space penalties). Slight time-based decay to encourage closing out
    // bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead coupling ----
    // Perfect match: post_residual == next_item_size => strongly reward (item + next item fill bin).
    if next_item_size > 0 {
        let match_diff = (post - next).abs();
        if match_diff <= 1.0 {
            score -= 60.0; // exact 2-item fill
        } else {
            // Reward proportional closeness of post_residual to next item size
            let closeness = 1.0 - (match_diff / cap).min(1.0);
            score -= 35.0 * closeness * closeness;
        }
        // Penalize leaving a gap just below next_item_size (dead space: next item won't fit)
        if post > 0.0 && post < next {
            let deadness = 1.0 - post / next.max(1.0);
            score += 25.0 * deadness * deadness;
        }
        // Reward leaving room for a smaller follow-up item
        if post >= next {
            score -= 8.0 * (post / cap);
        }
    } else {
        // Last item: prefer tightest fill
        score -= 20.0 * (1.0 - post / cap);
    }

    // ---- Residual context relative to mean residual ----
    // Bins with residuals far below mean are "ragged"; placing here to consolidate is good
    // if post_residual stays usable; otherwise penalize.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    if post >= 10.0 {
        score -= 10.0 * dev; // prefer fuller-than-average bins
    } else {
        score += 12.0; // creating tiny unusable residual
    }

    // ---- Last-chance bin boost ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0; // avoid opening a new bin when only this one fits
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if no good fit exists among open bins;
        // an empty bin gives post_residual = cap - item, which is large: base score already high.
        // Mild bonus early (build inventory), penalty later (fragmentation).
        score -= 5.0 * (1.0 - progress);
        score += 10.0 * progress;
        // If many bins already open, discourage more
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // ---- Tight-fit reward: item fills most of the bin ----
    let fill = item / (bin_residual as f64).max(1.0);
    score -= 15.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: squared penalty on wasted space
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus (strong)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead coupling: favor bins whose post_residual accommodates the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // chain fit: also leaves a reasonable remainder
            let chain_residual = post_residual - next_item_size;
            score -= 4.0 * (chain_residual as f64 / bin_capacity as f64);
        } else if post_residual > 0 && post_residual < next_item_size {
            // dead space relative to the known next item
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many open bins still fit the item
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost of a fresh bin
        score = bin_capacity as f64 * 0.5;
        // cheaper to open early / when open bins are fragmented
        score -= 10.0 * progress;
        if open_bins_count > 0 {
            score += 3.0 * (open_bins_count as f64).ln().max(0.0);
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
        // if mean residual is large, prefer reusing existing bins
        score += mean_residual * 0.3;
        if next_item_size > 0 && bin_capacity as f64 - mean_residual < next_item_size as f64 {
            score -= 5.0; // existing bins are cramped; new bin reasonable
        }
    }

    // Slight preference for filling fuller bins overall
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Late-stream consolidation: reward using existing bins as stream ends
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.6 * progress * progress);

    // Penalize large dead space quadratically, amplified later in the stream
    score += 0.35 * pr_norm * pr_norm * cap * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = post / (item_size as f64 + 1.0);
    score -= 8.0 / (1.0 + tightness);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        score -= 10.0 / (1.0 + diff / cap);
    }

    // Penalize opening new bins when open bins have room, more so early
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * (1.0 - progress) + mean_residual * 0.05;
    }

    // Mild pressure to consolidate: fewer open bins -> prefer filling existing
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: perfectly filled bin is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: group residuals into capacity-fraction buckets.
    // Small post_residual => good packing; large => wasteful.
    let frac = post / cap;
    let class: f64 = if post_residual == 0 { 0.0 }
        else if post_residual <= 5 { 1.0 }
        else if post_residual <= 10 { 2.0 }
        else if post_residual <= 20 { 3.0 }
        else if post_residual <= 30 { 4.0 }
        else if post_residual <= 50 { 5.0 }
        else { 6.0 };
    score += class * 12.0;

    // Modulo arithmetic: post_residual divisible by small numbers pairs well with
    // typical item sizes (multiples of 5/10).
    let pr = post_residual;
    if pr % 10 == 0 { score -= 8.0; }
    else if pr % 5 == 0 { score -= 4.0; }
    if pr % 3 == 0 && pr > 0 { score -= 2.0; }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits, but measure how well
            let nxt_post = post_residual - next_item_size;
            score -= 40.0 - (nxt_post.min(40) as f64);
        } else {
            // next item will NOT fit in this bin's remainder: penalize dead space
            score += 15.0;
            if post_residual < 10 { score += 20.0; } // tiny dead space, unusable
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // Empty bin baseline: prefer filling existing bins unless they fit badly.
        score = 55.0 + class * 2.0;
        if fitting_bins_count == 0 { score -= 100.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is below mean residual (better-than-average fit).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Late in stream: be more frugal with opening bins, squeeze harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Many open bins: discourage spreading, reward consolidation into tight fits.
    if open_bins_count > 4 {
        score -= (post_residual.min(20) as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are "dead". Penalize them super-linearly.
    let min_useful = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < min_useful && post_residual > 0 {
        // dead gap: heavily penalize, worse the closer it is to being useless
        score += 60.0 + (min_useful - post_residual as f64) * 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item if it could still fit
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // creating a gap that the next item cannot use
        score += 20.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (2.0 + 4.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        // baseline cost of opening a fresh bin
        score = bin_capacity as f64 * 0.55 + pressure * 0.5;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
        // if this bin is the only fitting option, opening new bin is competitive
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Mild bonus for filling bins tighter than the current mean residual
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 20.0;

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact match bonus scaled by how well next item fills remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // post_residual too small for next item: penalize dead space
            score += 8.0;
            // harsher if dead space is small-but-unusable (worst kind)
            if post_residual < 10 {
                score += 12.0;
            }
        }
    }

    // Relative to mean residual: bins below mean residual are already tight,
    // prefer using them rather than fragmenting looser bins
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is large
    // relative to mean residual (i.e., poor fits everywhere)
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) < mean_residual * 0.5;
        if poor_fit {
            score += 30.0; // discourage new bin when fits exist
        } else {
            score -= 5.0; // large item: fresh bin is fine
        }
        // more open bins -> opening another is costly
        score += open_bins_count as f64 * 2.0;
    }

    // Late-stream preference for consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tight * tight * (item_size as f64);

    // Perfect fit: overwhelming preference.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize leaving awkward slivers that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space below minimum item size
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 5.0; // usable residual for typical small items
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: prefer opening a new bin only when no open bin
    // fits well, or when many bins are open and residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let poor_alternatives = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        // New bin is attractive when open bins are highly fragmented OR this is
        // a forced fallback; unattractive early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 - 0.5 * fragmentation - poor_alternatives + 20.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward bins whose post_residual pairs with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0; // chain fit: next item fills this bin exactly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 10.0; // near-perfect pairing
            } else {
                score += slack * 0.05; // discourage wasting lookahead potential
            }
        }
    }

    // Global state: when mean residual is high, prefer bins that reduce variance
    // (i.e., bins whose post_residual is far from mean_residual get mild penalty).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild bonus for using older/more-filled bins to consolidate open bins.
    score += 0.01 * (open_bins_count as f64);

    // Time-horizon modulation: later in the stream, tighten packing further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post / cap;
    let mut score = post * (1.0 + 0.5 * progress * pr);

    // Smooth non-linear coupling: waste is worse as stream progresses
    score += 40.0 * progress * pr * pr * cap;

    // Reward tight fits (small post residual) with a smooth bump
    score -= 25.0 * (1.0 - pr) * (1.0 - pr) * (1.0 - progress);

    // Last-chance bonus: only fitting bin -> strongly prefer it
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits exactly into post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_gap = post - next_item_size as f64;
        score -= 15.0 * (1.0 - fit_gap / cap);
    } else if next_item_size > 0 && (next_item_size as f64) > post {
        score += 8.0 * ((next_item_size as f64 - post) / cap);
    }

    // Mild penalty for opening a new bin when open bins exist and fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 0.1 * mean_residual - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    // (capacity fractions of 10%). Small "dead" residues that no typical item
    // (1..100, but effectively multiples of small sizes) can reuse are penalized.
    let pr = post_residual;
    let residue_class = pr % 10;
    let class_penalty = match residue_class {
        0 => -6.0,   // perfectly reusable residual class
        1 | 9 => 4.0,
        2 | 8 => 2.5,
        3 | 7 => 1.5,
        4 | 6 => 0.8,
        _ => 0.0,    // 5: half-class, often reusable by odd items
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: how many 10-sized minimal
    // items could still fit.
    let slots = pr / 10;
    score -= (slots as f64) * 2.0;

    // Harmonic coupling with next item: if next item divides the post_residual
    // evenly (modulo test), strongly reward this bin.
    if next_item_size > 0 && next_item_size <= pr {
        if pr % next_item_size == 0 {
            score -= 8.0;
        } else if next_item_size * 2 <= pr {
            score -= 3.0;
        }
    } else if next_item_size > pr {
        // next item cannot use this bin's leftover -> dead space risk
        score += (next_item_size as f64 - pr as f64).min(10.0) * 0.4;
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no good harmonic fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 15.0;
        // If the item exactly divides capacity in harmonic classes, new bin is fine
        if bin_capacity % item_size.max(1) == 0 {
            score -= 10.0;
        }
        // Early in stream, allow more bin openings
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 4.0;
    }

    // Prefer tighter (fuller) bins overall: reward low residual relative to mean.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Many open bins -> discourage fragmentation, prefer filling existing bins.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the smallest plausible item are dead
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 500.0;
    }

    // Penalize gaps that cannot fit the lookahead item (wasted for next placement)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0;
    }
    // Reward gaps that can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Open-bin pressure: with many open bins, prefer tightening existing bins over new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / 10.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, more when many bins open or late in stream
        score += 120.0 + 40.0 * pressure + 50.0 * progress;
    } else {
        score -= 10.0 * pressure;
    }

    // Prefer bins tighter than the mean residual (good fills)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild preference for compact residual usage overall
    score += 0.3 * (post_residual as f64 / cap) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose residual after placement
    // matches the next item size exactly (chain packing).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            let gap = pr - next;
            if gap == 0.0 {
                score -= 500.0; // perfect chain fit
            } else if gap <= 10.0 {
                score -= 300.0 - gap * 15.0;
            } else {
                score -= (50.0 / gap).min(50.0);
            }
        } else {
            // Next item cannot follow in this bin; penalize proportionally
            // to how much residual would be stranded relative to next item.
            score += (next - pr) * 0.8;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // prefer leaving residuals that are typical (usable), punish outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bin would waste a lot
    // and the item is large (better to start fresh).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if waste > 40.0 {
            score -= 120.0 + waste * 0.5 + progress * 50.0;
        } else {
            score += 80.0; // discourage opening bins for small waste
        }
    }

    // Mild preference for compacting into fewer bins as stream progresses.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later on, be more conservative about wasting space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize dead space: small post-residuals are good, but tiny unusable slivers are bad.
    let tiny_sliver = if post_residual > 0 && post_residual < 10 { 25.0 } else { 0.0 };
    score += tiny_sliver;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: if next item fits in post_residual, big bonus (chaining placements).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - progress);
        } else {
            // If next item can't fit here, leftover space is more likely to become dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidation; penalize spreading items thin.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below mean residual (tighter bins get used first),
    // penalize placing into unusually loose bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // New-bin candidate handling: empty bin gets a moderate default penalty so it's
    // chosen only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 40.0 - 20.0 * progress;
        // If lookahead item is large and current item is small, opening fresh bin is attractive.
        if next_item_size > 50 && item_size < 30 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), non-linearly
    let mut score = pr as f64;

    // Non-linear polynomial coupling with stream progress:
    // early on, waste tolerance is higher; later, tight fits matter more.
    let tightness = x * x * (1.0 - progress) + x * x * x * progress;
    score += 40.0 * tightness;

    // Reward leaving residuals that can still host future items (smooth bump around mid residuals)
    let bump = 4.0 * x * (1.0 - x); // peaks at x=0.5
    score -= bump * (1.0 + progress);

    // Dead-space penalty for very small residuals, stronger late in stream
    let dead = (1.0 - x) * (1.0 - x) * (1.0 - x);
    score += dead * (10.0 + 30.0 * progress);

    // Lookahead: if next item fits into post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 15.0 * fit_quality * (0.5 + 0.5 * progress);
        } else {
            // penalize blocking the next item slightly
            score += 5.0 * (nxt / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty when many bins are open and this bin is already small (encourage consolidation)
    let consolidation = (open_bins_count as f64).ln().max(0.0);
    score += consolidation * (1.0 - x) * 2.0;

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
        // if existing fits are bad (large mean residual mismatch), make new bin more attractive
        let mean_x = mean_residual / cap;
        score -= 15.0 * (mean_x * mean_x) * progress;
    }

    // Mean residual coupling: prefer bins near the mean residual (predictable packing)
    let dev = (x - mean_residual / cap).abs();
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "reusable"
    // (large enough to host small items, i.e. >= 10) are rewarded.
    if post_residual > 0 {
        // dead space: leftover too small to ever fit anything (0 < r < 10)
        if post_residual < 10 {
            score += 60.0;
        }
        // modulo classes: leftovers that are multiples of small common sizes
        // (10, 20, 25, 50) are highly reusable -> subtract a bonus
        let r = post_residual;
        if r % 10 == 0 { score -= 12.0; }
        if r % 25 == 0 { score -= 8.0; }
        if r % 50 == 0 { score -= 6.0; }
        // awkward class: leftover in [10, 19] is nearly dead
        if r >= 10 && r < 20 { score += 15.0; }
    } else {
        // perfect fill is ideal
        score -= 40.0;
    }

    // Lookahead coupling: does the leftover accommodate next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover can host the next item: reward, scaled by how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 0.3 * slack;
            // exact chain fit (post_residual == next_item_size) is excellent
            if post_residual == next_item_size { score -= 25.0; }
        } else if post_residual > 0 {
            // leftover cannot host next item: penalize proportionally to waste
            score += 0.2 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // the current fit is bad. Penalize the empty-bin candidate moderately,
    // but less as the stream progresses (keeping a reserve bin is fine early).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 20.0 * (1.0 - progress);
        // opening a new bin is attractive if the item would leave a big
        // awkward leftover in every existing bin
        if post_residual >= 40 { score -= 15.0; }
        if next_item_size > 0 && post_residual >= next_item_size { score -= 10.0; }
    }

    // Fragmentation guard: avoid spreading across many bins when mean
    // residual is already large relative to capacity.
    let mean_ratio = mean_residual / bin_capacity as f64;
    if mean_ratio > 0.5 && post_residual > 0 {
        score += 8.0 * mean_ratio;
    }

    // Integer-division threshold on item_size: big items (>= 50) prefer
    // tight fits; small items tolerate looser fits.
    let big_item = item_size / 50; // 0 or 1
    if big_item == 1 {
        score += 0.15 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals too small for any item (min size 1,
    // but practically items are >= 10 in typical streams; treat tiny gaps as dead space).
    let dead_threshold: u32 = 10;
    if post_residual < dead_threshold {
        score += 60.0; // unusable gap
    } else if post_residual <= 20 {
        score += 25.0; // near-dead gap
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // Dead space relative to capacity
    score += 0.4 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Open bins pressure: discourage spreading into many bins when pressure is low,
    // but encourage using fitting bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor filling the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual < dead_threshold {
        score += 30.0; // creating a gap the next item cannot use
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 55.0 + mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a post_residual that exactly
    // accommodates the next item (perfect chain), penalize near-misses.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect fit for the next item: heavily reward.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits afterward: mild reward scaled by slack.
            score -= 15.0 - 0.1 * ((post_residual - next_item_size) as f64).min(50.0);
        } else {
            // Next item will not fit: penalize dead space creation.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Penalize leaving tiny unusable gaps (below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer tight fits relative to the mean residual of open bins.
    let tightness = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.15 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more strongly when
    // other bins could fit and the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 70.0 + 30.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 50.0; // opening a fresh bin to chain the next item is OK
        }
    }

    // Mild preference to spread load when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear tightening.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space that nothing in the plausible size range can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 {
        // Reward residuals that can still host typical items
        score -= 4.0;
    }

    // Lookahead: reward ability to also fit the next item in this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 12.0;
            // extra reward for near-exact two-item packing
            let combo_slack = post_residual - next_item_size as f64;
            score -= 6.0 * (1.0 - combo_slack / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    } else {
        // Last item: just fill as much as possible
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.05 * (post_residual as f64);
    }

    // New-bin candidate logic: opening a new bin is attractive when the current
    // fit is poor or when many bins already have fragmented space.
    if bin_residual == bin_capacity {
        // Fresh bin: score equals its post_residual (= capacity - item).
        // Compete with open bins: penalize opening new bins early / when few bins open.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the current stream is late and mean residual is fragmented,
        // a fresh bin is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // If no open bin fits well (high mean residual but we're here anyway),
        // slight discount to encourage spreading.
        if mean_residual < item_size as f64 {
            score -= 5.0;
        }
    }

    // Global fragmentation pressure: when mean residual is high relative to
    // capacity, prefer consolidating into bins with residual near mean (balance).
    let diff_from_mean = (bin_residual as f64 - mean_residual).abs();
    score += 1.5 * (diff_from_mean / bin_capacity as f64);

    // Mild preference for fuller bins as stream progresses (reduce bin count).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Penalize bins that will be left with residual in the awkward 30-50 zone
    // after placement (hard to fill later).
    if post_residual >= 30 && post_residual <= 50 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post-residual with smooth non-linear shaping (quartic coupling)
    let x = (pr / cap).clamp(0.0, 1.0);
    let mut score = pr * (0.55 + 0.45 * x * x * (1.0 - x) * 4.0);

    // Stream-progress coupling: later in stream, penalize residual waste more (quadratic in progress)
    score += pr * progress * progress * 0.35;

    // Lookahead: reward leaving space for next item (smooth Gaussian-like affinity)
    let nis = next_item_size as f64;
    if nis > 0.0 {
        let diff = pr - nis;
        let sigma = 12.0;
        let affinity = (-(diff * diff) / (2.0 * sigma * sigma)).exp();
        score -= 8.0 * affinity * (1.0 - progress * 0.5);
        // small penalty if residual slightly too small for next item (dead space)
        if diff < 0.0 {
            score += (-diff) * 0.12;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalty for opening new bin when many open bins exist with slack
    let mean_res = mean_residual.max(0.0);
    if bin_residual == bin_capacity {
        score += 6.0 + 0.05 * open_bins_count as f64;
    } else {
        score -= 2.0 * (mean_res / cap).clamp(0.0, 1.0);
    }

    // Tight-fit reward: near-perfect packing (smooth sigmoid on post_residual)
    let tight = 1.0 / (1.0 + (pr / 6.0).exp());
    score -= 10.0 * tight;

    // Mild penalty proportional to open bins count to encourage consolidation
    score += 0.03 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic bonus for small post_residual.
    let tight = (bin_capacity as f64 - (bin_residual as f64)) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tight * tight);

    // Harmonic classes: classify post_residual into residue classes mod common sizes.
    // Dead space = post_residual that cannot fit any plausible next item.
    let pr = post_residual;
    let dead = if pr == 0 { 0.0 } else if pr < 10 { 25.0 } else { 0.0 };
    score += dead;

    // If post_residual exactly matches next item size -> perfect lookahead fit.
    if next_item_size > 0 && pr == next_item_size {
        score -= 20.0;
    }
    // If next item fits in post_residual, mild reward scaled by fill.
    if next_item_size > 0 && pr >= next_item_size && pr > 0 {
        score -= 8.0 * (next_item_size as f64 / pr as f64);
    }
    // If next item does NOT fit here, penalize leftover smallness (wasted space).
    if next_item_size > 0 && pr < next_item_size && pr > 0 {
        score += 6.0 * (1.0 - pr as f64 / next_item_size as f64);
    }

    // Integer division thresholds: post_residual in low harmonic band is bad.
    let band = pr / 25; // 0..4 bands
    score += match band {
        0 => 12.0,          // 0..24 mostly dead
        1 => 4.0,           // 25..49 usable for mid items
        2 => 0.0,           // 50..74 good
        3 => -3.0,          // 75..99 nearly full, great
        _ => -5.0,          // full
    };

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: score it relative to mean residual of open bins.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins are quite full
        // (low mean residual) or many bins already open.
        score = bin_capacity as f64 - 10.0 + 0.5 * mean_residual + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // next item bigger: maybe keep fresh bin for it
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
    }

    // Late-stream consolidation: prefer filling existing bins near the end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit the next item are "dead".
    if next_item_size > 0 && post_residual < next_item_size {
        // Proportional dead-space penalty, stronger for tiny gaps.
        let dead = post_residual as f64;
        let gap_severity = 1.0 + (bin_capacity as f64 / (dead + 1.0)).min(10.0);
        score += 12.0 * gap_severity;
    } else if next_item_size > 0 {
        // Reward residuals that still accommodate the lookahead item.
        score -= 3.0;
    }

    // Reward tight packing (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize creating residuals in the awkward 20..40 "hard-to-fill" band.
    if post_residual >= 20 && post_residual <= 40 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).powf(1.3) * 2.5;
        // Only open a new bin if the item is large relative to typical residuals.
        let need = if (item_size as f64) > mean_residual { 0.0 } else { 30.0 };
        score += pressure + need;
    } else {
        // Mild reward for filling existing bins when many are open.
        score -= (open_bins_count as f64).sqrt() * 1.5;
    }

    // Early-stream: allow more bins to diversify residual sizes.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item's size (perfect chain placement).
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nr).abs();
        if diff < 1e-9 {
            score -= 60.0; // perfect 2-step match
        } else if pr >= nr {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize small leftovers
            score += 10.0 * (nr - pr) / bin_capacity as f64;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than the mean
    // (use up space in crowded bins), avoid bins looser than the mean.
    let cap = bin_capacity as f64;
    let rel = (post_residual as f64 - mean_residual) / cap;
    score += 15.0 * rel;

    // Last-chance bin before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize creating tiny dead space (< 10) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (open_bins_count as f64).recip() * 10.0;

    // New-bin candidate: keep it neutral-ish, only attractive when current
    // bin would leave a large unusable residual relative to next item.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 5.0
            - if next_item_size > 0 && (bin_residual - item_size) < next_item_size { 20.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Exact fit: perfect placement, reward strongly
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if the next item exactly fills the post-residual, this is ideal
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 600.0;
    }
    // Next item fits comfortably in the leftover space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * next_item_size as f64;
    }
    // Next item would NOT fit in the leftover: leftover is likely dead space
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 80.0 + 0.8 * post_residual as f64;
    }

    // Penalize creating tiny unusable slivers relative to typical item sizes
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        if tightness > 0.5 {
            score -= 500.0;
        } else {
            score -= 120.0;
        }
    }

    // New empty bin candidate: neutral-ish baseline; only attractive when no good
    // open option exists or we are early and many items remain
    if bin_residual == bin_capacity {
        let base = 220.0;
        // Late in the stream, avoid opening new bins unless necessary
        let time_penalty = 400.0 * progress;
        // If only this bin fits (fitting_bins_count counts it), opening is fine
        let necessity_bonus = if fitting_bins_count <= 1 { 350.0 } else { 0.0 };
        score += base + time_penalty - necessity_bonus;
    }

    // Prefer bins whose residual is close to the item (tight packing)
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * fit_gap;

    // Prefer bins with residual below the mean residual (denser bins first),
    // which keeps loose bins available for awkward future items
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild penalty for spreading across too many bins early on
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // Base: prefer tight fits (small post residual), with non-linear emphasis
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth coupling: as the stream progresses, reward fuller fills more strongly
    score -= 12.0 * fill * fill * fill * (0.5 + progress);

    // Dead-space penalty grows non-linearly with unusable residual
    let dead = pr_norm * pr_norm * pr_norm;
    score += 30.0 * dead * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 6.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * (pr - mean_residual);

    // Mild penalty for spreading across many bins early
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless the fit is poor elsewhere
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste buckets by integer division.
    // Classes: 0 (perfect), 1..=5 (tight), 6..=15 (usable), >15 (dead space).
    let class = post_residual / 6;
    score += match class {
        0 => -30.0,
        1 => -15.0,
        2 => -8.0,
        3 => -3.0,
        4 => 2.0,
        _ => (class as f64 - 4.0) * 4.0,
    };

    // Fractional capacity coupling: penalize residuals that waste a large
    // fraction of the bin, with non-linear (quadratic) growth.
    let frac = post_residual as f64 / cap;
    score += frac * frac * 40.0;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: fresh empty bin should only win when
    // existing bins would leave large dead space or are badly fragmented.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above good fits.
        score = 55.0 + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 40.0;
        }
        // Late in stream, prefer reusing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0 + open_bins_count as f64 * 0.5;
    }

    // Mean-residual pressure: when open bins are mostly empty, discourage
    // spreading items thin; when bins are tight, encourage consolidation.
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Penalize waste proportional to fraction of capacity lost.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 15.0 + 40.0 * pressure;
        // If next item could fill residual left here, mild bonus for reusing this bin.
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score += 5.0;
        }
    } else {
        // Favor bins whose residual matches next item size (lookahead packing).
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 8.0;
        }
        // Favor bins tighter than the mean residual (better packed).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Slight bonus for high fill ratio.
        score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Early stream: be slightly more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post residual, non-linear bonus)
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take
    } else {
        let pr = post_residual as f64;
        score -= 200.0 / pr; // diminishing reward as residual grows
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 150.0 / (1.0 + diff); // lookahead match bonus
        // Penalize leaving a residual just below next item size (dead space)
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // If post residual can hold next item too, extra reward
        if post_residual >= next_item_size {
            score -= 0.3 * next_item_size as f64;
        }
        let _ = nxt;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual > 0
                && (post_residual as i64 - next_item_size as i64).abs() > 20);
        if poor_fit {
            score -= 60.0;
        } else {
            score += 80.0; // keep filling open bins when fits are decent
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Penalize dead space that nothing can ever use (post residual < smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= 20.0 * (1.0 - waste as f64 / bin_capacity as f64);
        } else {
            // Next item can't use the residual: penalize proportionally.
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Global state coupling: when mean residual is high, prefer filling existing bins
    // (avoid fragmentation); when low, tolerate opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * mean_residual * (1.0 - t);

    // Crowding: many open bins -> discourage new bins, encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is low.
        score += 30.0 + 3.0 * open_bins_count as f64 + 0.1 * mean_residual;
        // But if current item is huge relative to typical residuals, opening may be wise.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Existing bin: small bonus for consolidation when crowded.
        score -= 1.5 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // Time horizon: late in the stream, be greedier about tight fits.
    score -= 10.0 * t * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted residual, quadratically so tight fits win.
    let mut score = post + 1.5 * (post / cap) * post;

    // Smooth non-linear coupling of waste with stream progress:
    // later in the stream, dead space becomes more costly (less time to fill it).
    let progress_coupling = (progress * std::f64::consts::PI).sin().abs();
    score += 8.0 * progress_coupling * (post / cap) * post;

    // Relative waste vs mean residual: bins far above mean waste are penalized,
    // bins below mean (tighter than average) are rewarded.
    let rel = if mean_residual > 0.0 { post / mean_residual } else { 1.0 };
    score += 3.0 * (rel - 1.0) * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (smoothly scaled by how much would be wasted otherwise).
    if fitting_bins_count == 1 {
        score -= 10.0 + 6.0 * (1.0 - post / cap) * (1.0 + progress);
    }

    // Lookahead: reward residual that can accommodate the next item (chaining),
    // penalize residuals that just barely fail to fit it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 5.0 * (1.0 - ((post - nxt) / cap)) * (1.0 - progress * 0.5);
        } else {
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    // New-bin candidate handling: an empty bin gets a baseline score; only
    // prefer it when all open bins would create large dead space.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) - 4.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into "usable" classes.
    // Class A: post_residual == 0 (perfect fit) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class B: post_residual <= 10 (dead space, nothing 10..80 fits except tiny items)
    else if post_residual < 10 {
        score += 15.0; // penalize small dead space
    }
    // Class C: usable mid residual (10..=49): reward via harmonic decay
    else if post_residual <= 49 {
        score -= 5.0 + 20.0 / (post_residual as f64 / 10.0 + 1.0);
    }
    // Class D: large residual (>= 50): keep it flexible but prefer smaller
    else {
        score -= 10.0;
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 pair well with
    // typical item sizes; reward multiples of 10, penalize odd residuals.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 2 == 1 {
        score += 2.5;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 60.0;
            } else {
                score -= 30.0 / (gap as f64 / 10.0);
            }
        } else {
            // next item cannot use this residual; slight penalty proportional to waste
            score += (next_item_size as f64).min(80.0) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 120.0
            - 40.0 / (fitting_bins_count.max(1) as f64)
            + if post_residual > 60 { -60.0 } else { 0.0 };
    }

    // Progression: as stream advances, prefer tighter packing (favor low residual bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * mean_residual * 0.05;

    // Many open bins: encourage closing bins (fill existing ones rather than spreading).
    score += open_bins_count as f64 * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64);
    }
    // Medium gaps (13..30) are moderately wasteful.
    if post_residual > 12 && post_residual <= 30 {
        score += 8.0 + 0.5 * post_residual as f64;
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize if next item almost fits but not quite (near-dead space).
    if next_item_size > post_residual && next_item_size - post_residual <= 10 && post_residual > 0 {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across too many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let spread = mean_residual - item_size as f64;
        if spread >= 0.0 {
            score += 120.0 + spread;
        } else {
            score += 30.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mean residual coupling: prefer bins deviating below mean residual (filling fuller bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: perfect match bonus ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Bin becomes exactly full after the next item: extremely desirable.
            score -= 60.0 + 20.0 * progress;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Penalize leftover after hypothetically placing next item,
            // but reward being able to host the next item at all.
            score -= 8.0;
            score += slack * 0.9;
            // Extra penalty if the leftover would be a small unusable sliver.
            if slack < 10.0 {
                score += 12.0 * (10.0 - slack) / 10.0;
            }
        } else {
            // Next item cannot fit here; slight penalty, scaled by how far off.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    } else {
        // Last item: minimize leftover waste as strongly as possible.
        score -= 30.0;
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins) ---
    let resid = post_residual as f64;
    let dev = resid - mean_residual;
    score += 0.25 * dev;

    // --- Last-chance fitting: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized, but less so when no open bin fits well
        // (post_residual would be small in existing bins) or late in the stream.
        let mut new_bin_score = 55.0;
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can always host the next item too.
            new_bin_score -= 5.0;
        }
        new_bin_score -= 10.0 * progress;
        // If mean residual across open bins is small (all bins nearly full),
        // opening a new bin is natural.
        if mean_residual < 15.0 {
            new_bin_score -= 15.0;
        }
        score = new_bin_score;
    }

    // --- Avoid creating tiny dead space in existing bins ---
    if bin_residual >= item_size && post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // --- Mild pressure to consolidate when many bins are open ---
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to item size)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that no future item (min size 1..small) could use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // awkward sliver
    }

    // Lookahead: reward bins whose leftover can host the next item exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to the gap
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a bin is costly when many bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
        score += 18.0 + open_pressure;

        // Opening is more acceptable late in the stream or when residuals are large
        if mean_residual > 30.0 {
            score -= 10.0;
        }
        if progress > 0.8 {
            score -= 6.0;
        }
    }

    // Prefer bins with residual above the mean (keep low-residual bins for small items)
    score += 0.08 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Mild preference for spreading load when many bins are open
    score += 0.02 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Stream-progress coupling: later in stream, punish leftover dead space more strongly
    score += 6.0 * t * norm_pr * norm_pr;

    // Smooth interaction: post_residual vs mean residual (avoid outlier bins)
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: reward if next item can fit in post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize wasting space the next item can't use
        score += 2.0 * t * norm_pr;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New empty bin candidate: penalize mildly unless post residual would be large
    if bin_residual == bin_capacity {
        score += 5.0 - 3.0 * t;
    }

    // Slight penalty for proliferating open bins
    score += 0.02 * open_bins_count as f64 * (0.5 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class logic: capacity fractions & modulo thresholds ---

    // Perfect fit is unbeatable.
    if post_residual == 0 {
        return -1000.0;
    }

    // Classify post_residual into harmonic remainder classes mod 10 and mod 20.
    let r10 = post_residual % 10;
    let r20 = post_residual % 20;

    // Dead-space penalty: residuals that no typical item (1..=100) can
    // "harmonically" reuse are penalized. Residuals < 10 are near-dead
    // unless they are exact small classes (1..=9 still usable).
    if post_residual < 10 {
        // Tiny residual: mostly dead space; penalize proportionally.
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Modulo-10 classes: residuals divisible by 10 are "harmonic" and
    // likely to be filled by future items (sizes often cluster on decades).
    if r10 == 0 {
        score -= 6.0;
    } else if r10 == 5 {
        score -= 2.5;
    } else {
        score += r10 as f64 * 0.4; // odd/awkward remainders penalized
    }

    // Modulo-20 bonus: residuals divisible by 20 are excellent targets.
    if r20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Coupling with next item: reward residuals that exactly or nearly
    // accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // chain fit: next item closes this bin perfectly
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Harmonic match: gap in a "nice" class (0,5,10 mod 10)
            let g10 = gap % 10;
            let nice = if g10 == 0 { 1.0 } else if g10 == 5 { 0.5 } else { 0.0 };
            score -= nice * 8.0 + (gap as f64 / bin_capacity as f64) * 4.0;
        } else {
            // Next item cannot use this bin's residual at all: penalize
            // leaving residual smaller than any plausible next need.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // bins would create tiny dead space and the item is large.
    if bin_residual == bin_capacity {
        // New empty bin: post_residual = capacity - item_size.
        // It is attractive if the item is big (small residual left),
        // otherwise mildly penalized to prefer filling open bins.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.7 {
            score -= 5.0 * (fill_frac - 0.7) / 0.3;
        } else {
            score += 8.0 * (0.7 - fill_frac);
        }
        // Early in the stream, opening bins is cheap; late, avoid it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    }

    // Mean-residual coupling: if this bin's residual deviates favorably
    // from the mean (smaller residual = tighter packing), reward it.
    let res_f = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (mean_residual - res_f) / mean_residual;
        score -= dev * 3.0;
    }

    // Mild pressure against accumulating too many open bins.
    score += open_bins_count as f64 * 0.15;

    // Small tie-break noise-free deterministic jitter on harmonic class.
    score += ((post_residual as u64).wrapping_mul(2654435761) % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    let min_item = 1u32; // items can be as small as 1 in this interface
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
