    // Reward leaving room for the lookahead item if it could fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if post_residual cannot fit the next item but is sizeable.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
