    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate
        score += open_bins_count as f64 * 2.0;
        // Opening a new bin is acceptable if all existing fits are poor.
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 4.0;
        }
    } else {
        score -= 2.0; // mild preference for reusing open bins
    }

    // Progress-based mild tightening: later in stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    score += (bin_residual as f64 - item_size as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: waste nothing.
    if post_residual == 0 {
        score -= 1000.0;
