    // into the post-residual of this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 120.0; // chain-friendly bin
        } else {
            // Dead space penalty scaled by how badly the next item misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    }

    // Penalize residuals that are too small to ever hold a meaningful item
    // (below typical minimum item size ~10), i.e. unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Tight-fit bonus: leaving little slack relative to capacity is good.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * tightness;

    // Relative-to-mean coupling: prefer bins whose post-residual stays
    // near the mean residual, penalize outliers both ways.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: opening a fresh bin is usually wasteful; penalize
    // unless current bins are nearly full (mean residual small) or it is
    // the only option.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 25.0;
        if crowded {
            score -= 150.0;
        } else {
            score += 100.0 + 0.5 * mean_residual;
        }
        // Early in the stream, opening bins is fine (build a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.1 {
            score -= 80.0;
        }
    }

    // Mild preference for consolidating into fewer bins.
    score += 2.0 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: small leftover that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly penalize leaving large gaps
            score += 5.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin, more so
    // when decent fitting bins exist or many bins are already open.
    if bin_residual == bin_capacity {
        let mut penalty = 25.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            penalty += 20.0;
        }
        // Late in stream, avoid opening new bins aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 20.0 * progress;
        score += penalty;
    }

    // Global state coupling: prefer bins whose residual is below mean
    // (concentrate waste in few bins) when many bins are open.
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Early stream: allow slight exploration of emptier bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: quadratic penalty on wasted residual, sharpened non-linearly
    let mut score = x * x * (1.5 + 2.5 * progress) + 0.35 * x;

    // Perfect-fit reward (smooth coupling with progress)
    score -= 3.0 * (1.0 - x * x) * (0.5 + progress);

    // Lookahead coupling: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_next = ((nx - x).abs()).max(0.0);
        score += 1.2 * fit_next * (1.0 - progress);
        // Exact next-fit bonus
        score -= 1.5 * (1.0 - fit_next * cap) * (1.0 - progress) * (1.0 - x);
    }

    // Penalize opening a new bin when existing bins fit
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 2.0 + 0.02 * open_bins_count as f64 + 4.0 * (1.0 - progress);
        // Allow new bin only if existing fits are very poor
        score += 6.0 * x * (1.0 - x);
    } else {
        // Last-chance bin bonus: strongly favor using the only fitting bin
        if fitting_bins_count == 1 {
            score -= 2.5 * (1.0 - x);
        }
        // Favor bins tighter than mean residual (smooth coupling)
        score += 0.4 * ((mean_residual - pr) / cap);
    }

    // Mild late-stream consolidation pressure
    score += progress * 0.3 * (x - 0.5) * (x - 0.5) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space thresholds
    // Small post_residuals (<=10) are near-perfect: reward heavily.
    if post_residual <= 10 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 pair well with
    // the 10..80 item grid; reward multiples of 10, penalize awkward ones.
    let cls = post_residual % 10;
    score -= match cls {
        0 => 25.0,
        1 | 9 => 12.0,
        2 | 8 => 8.0,
        _ => 0.0,
    };

    // Integer-division harmonic: can next_item_size fit exactly into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // lookahead fit: strong reward, scaled by how tight the fit is
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 200.0;
        } else if slack <= 5 {
            score -= 80.0;
        } else {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this residual: penalize wasted space
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // open new bin when existing bins are fairly full or nothing fits well
        score += 400.0;
        score -= mean_tightness * 350.0;
        score -= crowd * 8.0;
        // if this is a last-resort situation, soften the penalty
        if fitting_bins_count <= 1 {
            score -= 200.0;
        }
    }

    // Progress coupling: later in the stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.3;

    // Tightness bonus: bin_residual close to item_size is a great fit
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tight) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold anything
    // useful are heavily penalized.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * 8.0;
    }

    // Exact fit is strongly preferred.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure from open bins count: with many open bins, prefer filling
    // existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * 3.0;

    // Lookahead coupling: if the next item would fit exactly in the
    // post_residual, reward this placement (sets up a perfect follow-up).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    }
    // Penalize if next item cannot fit anywhere and we are wasting a large gap.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // New-bin candidate: opening a new bin should only win when the current
    // fit is poor. Make the empty bin moderately attractive but not dominant.
    if bin_residual == bin_capacity {
        score -= 5.0;
        // Discard new-bin preference when few bins are open (consolidate first).
        if open_bins_count < 3 {
            score += 10.0;
        }
        // If next item is large, a fresh bin is useful.
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Mild stream-progression term: as the stream advances, be slightly
    // more willing to pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Deviation from mean residual: prefer bins whose residual is already
    // below average (closer to being closed out).
    score += ((mean_residual - bin_residual as f64).abs()) * 0.05
        - (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight match to next item; strongest when gap is 0.
        score -= 40.0 * (1.0 - gap / 100.0).max(0.0);

        // If the next item fits exactly after this placement, heavily favor.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual that next item cannot use at all.
        if next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize waste only.
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are tight;
    // placing there is good (consumes scarce space), so reward below-mean bins.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Dead-space penalty: residuals too small for the smallest item (1..100 unknown,
    // assume small items possible) are less harmful, but large residuals waste bins.
    if post_residual > 50 {
        score += 0.3 * (post_residual as f64 - 50.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., when this empty-bin call should sometimes win.
    if bin_residual == bin_capacity {
        // Base penalty so open bins usually win...
        let mut new_bin_score = 30.0 + 0.5 * item_size as f64;
        // ...but if the item is large and mean residual is small (fragmented bins),
        // opening fresh becomes competitive.
        if (item_size as f64) > mean_residual {
            new_bin_score -= 25.0;
        }
        // Lookahead: if next item is big, a fresh bin preserves room for pairing.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_bin_score -= 20.0;
        }
        // Crowd control: many open bins -> discourage opening more.
        new_bin_score += 2.0 * open_bins_count as f64;
        score = new_bin_score;
    }

    // Mild stream-progression pressure: early on be flexible, later consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (near-perfect packing).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < item_size.max(10) {
        // residual can still fit a minimum-size item: mild bonus
        score -= 3.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot follow here: slight penalty proportional to mismatch
        let mismatch = (next_item_size.min(post_residual)) as f64 / (next_item_size.max(1) as f64);
        score += 4.0 * (1.0 - mismatch);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins are badly fragmented
    // or none fit well; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 {
            (mean_residual - post_residual as f64).abs() / (bin_capacity as f64)
        } else { 0.0 };
        // Base penalty grows with number of open bins and stream progress.
        score += 15.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        // Discount the penalty if open bins have large, poorly-matching residuals.
        if open_bins_count > 0 && mean_residual > 40.0 && next_item_size > 0 {
            let worst_fit_gap = (mean_residual - item_size as f64).abs();
            if worst_fit_gap > 20.0 {
                score -= 18.0;
            }
        }
        // Reward opening a fresh bin early in the stream when fragmentation is high.
        if fragmentation > 0.3 {
            score -= 6.0;
        }
    }

    // Time-horizon modulation: late in the stream, consolidation matters more,
    // so penalize leaving medium residuals that invite new bins later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 30 && post_residual < 60 {
        score += 5.0 * progress;
    }

    // Mild preference to fill bins with many siblings already open (reduce spread).
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual
    let mut score = x * x * (3.0 - 2.0 * x); // smoothstep base: penalize both extremes non-linearly
    score += 0.5 * x * x;
    // reward tight fits: strong polynomial discount near zero post residual
    score -= 2.0 * (1.0 - x) * (1.0 - x) * x;
    // stream progress coupling: later in stream, prefer tighter packing more aggressively
    score *= 1.0 + 0.8 * progress * (1.0 - x);
    // lookahead: if next item fits into post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.6 * (next_item_size as f64 / cap);
    }
    // last-chance bin: strong reward to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 1.5 + 0.5 * progress;
    }
    // penalty when this bin's residual deviates from mean residual (fragmentation)
    score += 0.3 * ((pr - mean_residual) / cap).abs();
    // mild penalty for proliferation of open bins relative to progress
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress) * x;
    // new-bin candidate: neutral-ish baseline scaled by progress
    if bin_residual == bin_capacity {
        score = 0.9 + 0.5 * progress + 0.02 * (open_bins_count as f64);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes by modulo arithmetic.
    // Residuals that are "usable" for common small items (multiples of 10, and >= 20)
    // are rewarded; tiny unusable slivers (1..10) are heavily penalized.
    let tiny_sliver = post_residual > 0 && post_residual < 10;
    let class_10 = post_residual % 10 == 0;
    let class_5 = post_residual % 5 == 0 && !class_10;

    if tiny_sliver {
        score += 60.0; // dead space, almost nothing fits
    } else if class_10 {
        score -= 12.0; // highly reusable residual
    } else if class_5 {
        score -= 5.0;
    } else {
        score += 6.0; // awkward residual
    }

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: does the residual class admit the next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Exact class match (residual - next divisible into harmonic classes)
        let after_next = post_residual - next_item_size;
        if after_next % 10 == 0 {
            score -= 15.0;
        } else if after_next < 10 && after_next > 0 {
            score += 10.0;
        }
        score -= 8.0; // bin remains useful for lookahead
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: mild penalty scaled by slack
        let gap = next_item_size - post_residual;
        score += (gap as f64).min(30.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins fit badly.
    if bin_residual == bin_capacity {
        // Base reluctance grows with number of open bins that could take the item.
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if the current item is large and would leave a bad residual in
        // open bins, opening a fresh bin is fine: reduce reluctance.
        if item_size >= 70 {
            score -= 20.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can pair current + next item
        }
    }

    // Late-stream pressure: consolidate into open bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: residuals that are too small for typical
    // future items (1..100, but practically >= 10) are wasted capacity.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is the best possible outcome.
        score -= 60.0;
    } else {
        // Smooth tightness reward: prefer smaller but usable residuals.
        score -= 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).min(1.0);
    }

    // Next-item lookahead: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize creating a gap that cannot host the known next item.
        score += 8.0 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (a new bin is the empty-residual == capacity candidate).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 10.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // Mild pressure toward consolidating into already-open bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (pack into tighter-than-average bins to consolidate large gaps).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).sqrt();
        if post_residual < 10 {
            score += 20.0 * (10 - post_residual) as f64; // tiny useless slivers
        } else {
            score += 6.0 * dead;
        }
    }

    // Lookahead coupling: reward residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0; // next item won't fit here after placement
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when existing bins fit poorly (high mean residual fragmentation) or
    // the item fits a fresh bin better than any tight option.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        // Base cost of a new bin, discounted when open bins are badly fragmented
        // or we are early in the stream (saving bins matters most later).
        let mut new_bin_cost = 60.0 + 40.0 * progress;
        new_bin_cost -= 30.0 * fragmentation.min(1.0);
        if open_bins_count == 0 {
            new_bin_cost = -10.0; // must open a bin
        }
        score += new_bin_cost;
    } else {
        // Mild preference for fuller bins when many bins are open.
        score -= 2.0 * (bin_residual as f64 / bin_capacity as f64);
        // Prefer spreading across bins when open-bin count is high relative to mean residual.
        if open_bins_count > 4 && (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Time-horizon modulation: late in the stream, avoid creating new small residuals.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling: quadratic + cubic post-residual shaping modulated by progress
    let poly = norm_post * norm_post * (1.0 - norm_post) * (1.0 - norm_post);
    score -= 60.0 * poly * (0.3 + progress);
    // Late-stream: penalize residuals that cannot fit the next item
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 25.0 * fits_next * (1.0 - gap) * (1.0 - progress);
        score += 15.0 * (1.0 - fits_next) * progress;
    }
    // Last-chance bonus (smooth logistic on fitting_bins_count)
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0_f64.max(fitting_bins_count as f64 - 1.0)).exp());
    score -= 20.0 * last_chance * (1.0 - progress * 0.5);
    // Divergence from mean residual: quadratic penalty
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;
    // Tight fit reward with progress coupling
    let tight = 1.0 - norm_post;
    score -= 8.0 * tight * tight * (1.0 + progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse when it cannot
    // plausibly hold a future item. Classes keyed by modulo 10 (min item size).
    let cls = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        // Unusable sliver: strong penalty
        score += 60.0;
    } else if cls == 0 && post_residual > 0 {
        // Residual divisible by 10: harmonically reusable
        score -= 8.0;
    } else {
        // Fractional dead space scaled by how far from a multiple of 10
        score += cls as f64 * 0.7;
    }

    // Integer-division threshold: post_residual / next_item_size
    if next_item_size > 0 && post_residual > 0 {
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            // Reward residuals that can host the lookahead item
            score -= 6.0;
            // Extra reward if lookahead fits EXACTLY (chained perfect fit)
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Penalize blocking the next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is penalized mildly so it is
    // only chosen when all open bins score badly (bad fits / dead space).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: matches a mediocre-fit residual (~50)
        score = cap_f * 0.55;
        // Late in the stream, avoid opening new bins more aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins fit the item, definitely prefer an existing one
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // If next item is large, a fresh bin has future value
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 5.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below the mean
    // (consolidate into tighter bins, keep loose bins for large items).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Small preference for fuller bins overall (tight packing)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward near-perfect fits.
    if post_residual <= 3 {
        score -= 30.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Waste ratio penalty: dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Open-bin pressure: discourage spreading across many bins slightly,
    // but not enough to override dead-space concerns.
    score += open_bins_count as f64 * 0.15;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item: mild penalty for stranding space.
        score += 5.0;
    }

    // Mean residual alignment: prefer bins whose residual is below average
    // (filling fuller bins first, best-fit style).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin
    // offers a decent fit. Make the empty bin moderately attractive but
    // dominated by good fits in existing bins.
    if bin_residual == bin_capacity {
        score += 20.0 - open_bins_count as f64 * 0.3;
        // If the item is large relative to typical residuals, a fresh bin is fine.
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: strongly reward when the next item fits the post residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize creating dead space relative to next item.
        let dead = post_residual as f64;
        score += 3.0 * dead / bin_capacity as f64;
    }

    // Perfect closure bonus: bin exactly filled now.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small residual unusable by typical items (below min size 1..100 -> treat < 10 as dead).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: prefer only when current fit is bad; make empty bin mildly unattractive.
    if bin_residual == bin_capacity {
        score += 5.0;
        // But if next item is large and current bin would leave a bad state, opening fresh is fine.
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score -= 2.0;
        }
    }

    // Relative to mean residual: bins with residual close to item size are attractive.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * (gap / bin_capacity as f64);

    // Progress-aware tightening: later in stream, be greedier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Coupling with mean residual: avoid wasting bins that are much better than average.
    score += 0.1 * (mean_residual - bin_residual as f64).abs() / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0;
        }
    }

    // Last chance bin: strong bonus to avoid opening a needless new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residual below the mean (consolidate small leftovers).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.35 * dev;

    // Time horizon: early in the stream, be pickier about large residuals;
    // late in the stream, just pack anywhere that fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.25 * (bin_residual as f64);

    // New-bin candidate: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64).ln().max(0.0);
        let bad_fit = (post_residual as f64 / bin_capacity as f64) > 0.6;
        let next_wont_follow = next_item_size > 0 && next_item_size > post_residual;
        if bad_fit && (open_bins_count > 2 || next_wont_follow) {
            score -= 15.0 + 4.0 * crowded;
        } else {
            score += 20.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.6 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / cap;
    let pr2 = pr * pr;

    // Non-linear polynomial coupling: dead space penalized quadratically, modulated by progress.
    // Early stream: tolerate moderate residual; late stream: strongly penalize waste.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += 40.0 * progress_weight * pr2;

    // Reward tight fits smoothly (low post-residual) with a cubic bonus
    let tightness = 1.0 - pr;
    score -= 20.0 * tightness * tightness * tightness;

    // Last-chance bonus: smooth sigmoid-like reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Coupling with mean residual: prefer bins whose residual is near the mean (balanced packing),
    // penalize deviation with smooth quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead coupling: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let slack = pr * cap - n;
        if slack >= 0.0 {
            let s = slack / cap;
            score -= 8.0 * s * (1.0 - s);
        } else {
            score += 5.0;
        }
    }

    // Mild penalty for spreading across too many bins early
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals divisible by large
    // power-of-2 / common divisors are more "reusable" by future items.
    let pr = post_residual;
    if pr > 0 {
        let mut h = 0u32;
        let mut p = 1u32;
        while p * 2 <= pr { p *= 2; h += 1; }
        // reward residuals in nice harmonic classes (divisible by 10, 20, 25, 50)
        let nice = if pr % 50 == 0 { 3.0 } else if pr % 25 == 0 { 2.0 }
                   else if pr % 20 == 0 { 2.0 } else if pr % 10 == 0 { 1.0 }
                   else if pr % 5 == 0 { 0.5 } else { 0.0 };
        score -= nice * 4.0 + h as f64;
    } else {
        // perfect fit: strongly reward
        score -= 50.0;
    }

    // Dead-space penalty: residual too small for the minimum plausible item (1..100 range).
    // Anything below ~10 is likely dead; below next_item_size is risky.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    if next_item_size > 0 {
        if (pr as u32) < next_item_size && pr > 0 {
            // residual cannot host the next item -> dead space unless tiny
            score += (next_item_size - pr) as f64 * 0.6;
        } else if (pr as u32) >= next_item_size {
            // residual can host next item exactly or with room: reward closeness
            let d = pr as u32 - next_item_size;
            if d == 0 { score -= 20.0; }
            else { score -= 5.0 * (1.0 - d as f64 / bin_capacity as f64); }
        }
    }

    // Integer-division threshold on residual: bucketize residual into quarters of capacity.
    let q = pr / (bin_capacity / 4);
    score -= q as f64 * 2.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad,
    // but reward it when open bins are crowded (many bins, high mean residual usage).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 8.0 - 6.0 * pressure;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 4.0; // big next item: fresh bin is fine
        }
    }

    // Slight preference for tight bins (small residual before placing) to consolidate.
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Late-stream consolidation: as stream progresses, avoid spreading.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * (bin_capacity as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size are pure waste — penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize creating gaps too small for the lookahead item when the
    // lookahead could still fit here (wasting a future opportunity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins over opening new ones.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate handling: only attractive when existing bins are
    // heavily fragmented (large mean residual spread) or item barely fits.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let fragmentation = (mean_residual - (bin_capacity - item_size) as f64).abs();
        score = 55.0 - 40.0 * tightness + fragmentation * 0.3;
        if fitting_bins_count == 1 {
            score += 50.0; // never open new when a unique fitting bin exists
        }
    }

    // Mild late-stream tightening: preserve flexibility early, pack tight late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 40.0 * fit_ratio;
    } else if fit_ratio > 0.7 {
        score -= 15.0 * fit_ratio;
    }

    // 2-step lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            // reward proportional to how snugly the next item fits
            score -= 30.0 * (1.0 - chain_waste as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot follow into this bin: penalize large dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize leaving residual far below the minimum plausible item size (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual is already below average
    // (consolidate waste into few bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Discourage opening new bins when existing bins give a reasonable fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But allow a fresh bin if the item is large and nothing fits well elsewhere.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of the fit (0 = perfect fit, 1 = item tiny vs bin).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits: subtract proportionally to how much of the residual is consumed.
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing else can use (post_residual in awkward band).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0 * (1.0 - t); // early dead space more forgivable
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Reward partial compatibility, scaled by how well it fits.
            let compat = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * compat;
        } else {
            // Next item won't fit here; penalize leaving residual that blocks nothing useful.
            score += 5.0;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins with high mean residual: discourage spreading waste; prefer
    // consolidating into bins that are already relatively full.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap;

    // Late in the stream, favor closing out bins (low post residual) more aggressively.
    score *= 1.0 + 0.5 * t;

    // New-bin candidate: make it attractive only when the item is large relative to
    // capacity or no open bin offers a decent fit. Empty-bin residual == capacity.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is cheap for big items, expensive for small ones.
        score -= 40.0 * large_item - 10.0;
        if fitting_bins_count > 0 {
            // Some open bin fits; opening a new bin should need a strong excuse.
            score += 15.0 * (1.0 - large_item);
        }
        // Fewer open bins => cheaper to open another (less fragmentation risk).
        score -= 2.0 * open_bins_count as f64 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: penalize wasted post residual, non-linearly (dead space grows quadratically)
    let mut score = norm_pr * norm_pr * cap;

    // Tight fit reward: smooth coupling between item size and post residual
    score -= (1.0 - norm_pr) * fit_ratio * 40.0;

    // Stream-progress coupling: early on, keep bins flexible (mild); late, pack tight
    let flexibility = 1.0 - progress * progress;
    score += norm_pr * norm_pr * flexibility * 30.0;

    // Last-chance bonus: only bin that fits -> strong reward
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits in post residual (smooth interaction)
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64 <= pr) as i32 as f64;
        let gap = (next_item_size as f64 - pr).abs() / cap;
        score -= next_fits * (1.0 - gap) * 15.0;
        score += gap * (1.0 - next_fits) * 8.0 * (1.0 - progress);
    }

    // Mean residual context: prefer bins near mean residual (avoid fragmentation skew)
    score += ((pr - mean_residual) / cap).abs() * 6.0;

    // New-bin candidate: penalize opening new bins unless nothing sensible fits
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
    }

    // Slight preference for bins with larger residuals when many bins open
    score -= (norm_pr * open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / cap_f;
    score -= 30.0 * tightness * tightness;

    // Harmonic class of post_residual: residues that are "friendly" to future items
    // Items 1..100; common sizes cluster in multiples of 10 and small values.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        40.0 // perfect closure is ideal
    } else if pr % 10 == 0 {
        25.0 // multiple of 10: many standard items fit exactly
    } else if pr % 5 == 0 {
        15.0
    } else if pr < 10 {
        5.0 // dead space but tiny
    } else {
        0.0
    };
    score -= class_bonus;

    // Penalize residues that no plausible item can use well:
    // if post_residual < smallest plausible item (1) it's dead; if it's in a
    // "gap band" (e.g. 91..99 where only tiny items fit), penalize moderately.
    if pr >= 91 && pr <= 99 {
        score += 10.0;
    }
    if pr >= 81 && pr <= 89 {
        score += 6.0;
    }

    // Lookahead coupling: reward if next item fits post_residual exactly or closely
    if next_item_size > 0 {
        if next_item_size <= pr {
            let next_fit = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - next_fit / cap_f);
            if pr == next_item_size {
                score -= 25.0; // perfect chaining
            }
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current fit is terrible. Give the empty bin a moderate default score.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64).sqrt() * 3.0
            - (mean_residual / cap_f) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin always fits the next item perfectly
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    // Prefer bins with residual near mean (keeps bin profile balanced)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap_f;
    score += 6.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: gaps below the minimum item size (1..=9 here)
    // are unusable, so punish them severely.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward fits that leave room for the lookahead item if it would fit,
    // penalize if the next item would no longer fit while it fit before.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // favor filling existing bins over opening new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: it is attractive only when its residual (full capacity)
    // beats what existing bins offer; add a fixed opening cost so it is chosen
    // only for poor fits elsewhere, scaled by stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * (1.0 - progress);
    }

    // Slight preference for bins whose residual deviates from the mean
    // in a way that suggests tighter packing.
    score -= (mean_residual - bin_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: strongly reward if next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits here: penalize leftover waste after the lookahead pair
            let pair_waste = post_residual - next_item_size;
            score += 0.3 * pair_waste as f64;
            score -= 50.0;
        } else {
            // next item does not fit after this placement: penalize proportionally
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot.min(80.0);
        }
    }

    // Compare against mean residual across open bins
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += 20.0 * rel;
    }

    // Dead space penalty: small residuals are hard to use (items >= 1)
    if pr > 0.0 && pr < 10.0 {
        score += 80.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: only prefer when open bins are all poor fits
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 40.0;
        // more attractive late in stream or when open bins are crowded
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // reserving empty bin for a large next item
            score -= 0.2 * next_item_size as f64;
        }
        if pr >= 0.0 && mean_residual < 20.0 {
            // open bins nearly full: opening new bin is fine
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Exact fit is extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item cannot fit anywhere after this placement, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // This placement blocks the next item from using this bin; mild penalty.
            score += 15.0;
        }
        // Reward leaving room compatible with the average upcoming need.
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        score += (pr - nr).abs() * 0.3;
    }

    // Penalize bins that deviate from the mean residual (prefer balanced usage),
    // scaled by how many bins are open (more bins -> stronger balancing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (0.05 + 0.02 * open_bins_count as f64);

    // Dynamic time horizon: early in the stream, prefer opening bins conservatively
    // (penalize near-empty bin usage slightly); late in stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill_ratio = (bin_residual as f64) / (bin_capacity as f64);
    score += (1.0 - progress) * fill_ratio * 10.0;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.2;

    // New-bin candidate: only attractive when no open bin fits well
    // (large item relative to residuals) or stream is early.
    if bin_residual == bin_capacity {
        let spread = mean_residual / bin_capacity as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { (1.0 - item_frac).max(0.0) };
        score += 200.0 * pressure * spread.max(0.0) * (1.0 - progress * 0.5);
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
    }

    // Small stochastic-free tie-breaker based on index parity of step.
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (8.0 + 10.0 * progress);

    // Penalize dead space that is too small to be useful for typical items
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 {
            score += 4.0 * (-gap) / cap;
        } else {
            score -= 2.0 * (gap / cap).sqrt();
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Alignment with mean residual state
    score -= 0.1 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are multiples
    // of common item-size classes (10, 20, 25, 50) — these are "usable" wells.
    let usable_well = post_residual % 10 == 0;
    if usable_well {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 {
        score -= 10.0;
    }

    // Integer-division threshold: residual classes by quotient of capacity.
    let q = post_residual / (bin_capacity / 4);
    score -= match q {
        0 => 14.0, // tiny sliver: near-perfect fill
        1 => 4.0,  // quarter left: decent
        2 => 0.0,  // half left: neutral
        _ => 6.0,  // mostly empty: weak fit
    };

    // Coupling with lookahead: if next item fits exactly in post_residual,
    // strongly reward (chained perfect fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_post = post_residual - next_item_size;
        if nxt_post % 10 == 0 {
            score -= 12.0;
        }
        score -= (next_item_size as f64) * 0.15;
    } else if next_item_size > post_residual {
        // next item cannot use this leftover: penalize dead space
        score += (next_item_size as f64) * 0.10;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless
    // the item is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        let pressure = (item_size as f64 / bin_capacity as f64) * (1.0 - fragmentation);
        score += 55.0 - 45.0 * pressure - 10.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Tight-fit bonus: reward placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 10.0;

    // Discourage spreading across many open bins when residuals are similar
    // (harmonic mismatch): if this bin's residual deviates from mean, slight penalty.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Modulo-class penalty: residuals in "awkward" classes (e.g. 1..9 mod 10
    // after large items) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item are pure waste — punish them quadratically.
    if post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 25.0;
    } else if post_residual < 20 {
        // Small gaps (10..20) are usable only by tiny items; mild penalty.
        score += 6.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use leftover here; slight penalty for stranding.
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones; opening a new bin (residual == capacity) gets a bonus
    // only when open-bin count is low.
    if bin_residual == bin_capacity {
        if open_bins_count > 4 {
            score += 20.0 + 2.0 * open_bins_count as f64;
        } else {
            score -= 3.0;
        }
    }

    // Prefer bins whose residual is below the mean (nearly full bins),
    // keeping large residuals in other bins available for big items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else if (bin_residual as f64) > mean_residual * 1.5 {
        score += 3.0;
    }

    // Early in the stream, tolerate new bins slightly more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Partial lookahead reward: next item fits into post-residual space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportionally to how close it was.
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (gap / bin_capacity as f64);
    }

    // Reward tight fits relative to mean residual of open bins.
    let mean_res = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    if (post_residual as f64) < mean_res {
        score -= 3.0 * (mean_res - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 3.0 * ((post_residual as f64) - mean_res) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good existing candidates exist.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin still useful for lookahead chain
        }
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: new bin is fine
        }
    }

    // Small phase-based tuning: later in stream, prefer consolidating.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Dead-space penalty for large unusable leftovers (nothing between 1 and 9 can be
    // assumed, so penalize residuals that are small relative to the minimum item size).
    if post > 0.0 && post < 10.0 {
        score += 6.0 * (10.0 - post) / 10.0;
    }

    // Lookahead: reward if the next item fits in the post residual (chaining),
    // penalize if the next item is large and this placement wastes the bin.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 8.0 * (next / cap);
        } else {
            score += 4.0 * (next / cap) * (1.0 - post / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 2.0 * crowding * (post / cap);

    // Global residual alignment: prefer bins whose post residual moves toward the mean
    // residual of open bins (keeps bin states homogeneous and packable).
    score += 3.0 * (post - mean_residual).abs() / cap;

    // Time horizon: early in the stream, be frugal with new bins; late in the stream,
    // tight fits matter more than bin count.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fill_ratio;

    // New-bin candidate: empty bin. Only attractive when the item is large and no
    // existing bin offers a decent fit; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = if fitting_bins_count > 0 {
            // penalize new bin by how well existing bins could fit (approx via mean residual)
            (mean_residual / cap).max(0.0)
        } else { 0.0 };
        score = cap * 0.9
            - 15.0 * item_frac * item_frac
            - 20.0 * desperation
            + 25.0 * (1.0 - desperation) * (1.0 - poor_fit);
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Smooth penalty for large dead space, amplified late in the stream
    let dead = norm_post * norm_post * cap;
    score += 0.6 * dead * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.3 + 0.7 * progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits into resulting post_residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - (post / (next_item_size as f64).max(1.0)).min(1.0));
    }

    // Mild penalty when bin is far above mean residual (keeps residual distribution balanced)
    score += 0.15 * (post - mean_residual).abs() * (1.0 + progress);

    // Encourage consolidating into fewer bins when many are open
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large" integer-division classes are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space quadratically, scaled by capacity fraction.
    score += (pr * pr) / cap * 0.02;

    // Harmonic tier: integer division of post_residual into quarters of capacity.
    let quarter = (bin_capacity / 4).max(1);
    let tier = post_residual / quarter; // 0..4
    match tier {
        0 => score -= 6.0,             // tiny leftover: near-perfect packing
        1 => score -= 2.0,             // small leftover still useful
        2 => {}                        // neutral
        3 => score -= 1.5,             // large leftover, roomy bin
        _ => {}                        // new empty bin candidate
    }

    // Modulo coupling: leftover that is congruent to common item-size classes
    // (multiples of 10 within 1..100 streams) is more likely reusable.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 3.0;
    } else if mod10 <= 2 {
        score += 1.0; // awkward sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // reward proportional to tightness of the follow-up fit
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 4.0 * tight;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize new-bin tie-breaks).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New empty bin candidate: only attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs() / cap;
        score += 8.0 - 6.0 * fragmentation;
        // Early in stream, opening bins is cheap; later, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
    }

    // Mild preference for bins tighter than the mean (best-fit flavor).
    score += ((bin_residual as f64 - mean_residual) / cap) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host the
    // smallest plausible item (<= ~10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fills (post_residual close to zero but usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Tight fit bonus: fraction of residual consumed by the item.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // is large (would leave a bad gap in an existing bin) or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 55.0;
        // Large items fit perfectly in fresh bins; make it competitive.
        if item_size >= 60 {
            score -= 35.0;
        }
        // Early in the stream, opening bins is cheaper (more items to come).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // Many open bins with high mean residual: avoid adding another.
        score += 3.0 * open_bins_count as f64 + 0.1 * mean_residual;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual < 10 {
            score += 8.0; // next item would be blocked by this placement
        }
    }

    // Mild pressure against accumulating many open bins.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leave nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small for typical items.
        if post_residual < 10 {
            score += 60.0;
        }
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the post residual,
    // strongly reward this bin (chain fit).
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Next item can also go here: mild reward proportional to leftover after both.
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use this bin's remainder: penalize small unusable gaps.
            score += 0.3 * (next_item_size - post_residual as u32) as f64;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Compare residual against mean residual: prefer tighter-than-average bins.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate: prefer already-open bins over new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 40.0 + 120.0 * progress;
    } else {
        score -= 20.0 * progress;
    }

    // Slight penalty for bins that would become very fragmented (tiny leftover).
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear waste.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tight * tight;

    // Reward perfect closures.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Dead space penalty: residual that likely cannot fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // small unusable sliver
    }

    // Lookahead: if next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 25.0; // chains into a perfect double fill
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize proportional waste.
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: discourage opening a new bin when a decent
    // fit exists in an open bin; encourage it when residuals are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // More attractive when open bins are crowded/fragmented on average.
        score -= 15.0 * (mean_residual / bin_capacity as f64).min(1.0);
        // More attractive late in the stream when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // Discourage new bin if this bin is the only fitting one elsewhere.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Mild preference for fuller bins overall.
    score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Global fragmentation pressure: when mean residual is small, conserve
    // remaining space in bins by penalizing large post residuals more.
    let frag = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
    score += 6.0 * frag * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, penalize large residuals more
    let progress_coupling = 1.0 + progress * (1.0 - progress) * 4.0 * norm_pr;
    score += progress_coupling * pr * 0.5;

    // Penalize residuals that cannot fit the next item (dead space), smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            let gap = (ns - pr) / cap;
            score += gap * gap * cap * (1.0 + progress);
        } else {
            // reward leaving room exactly for the next item
            let fit_quality = 1.0 - ((pr - ns) / cap);
            score -= fit_quality * fit_quality * 5.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild penalty for wasting scarce space when many bins fit
        score += (fitting_bins_count as f64).ln() * norm_pr * 3.0;
    }

    // New-bin candidate: make it attractive only when current bins are poor fits
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let mean_fit_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        score = cap * (0.6 + 0.4 * progress) - mean_fit_gap * cap * 0.9;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Deviation from mean residual: prefer bins with less residual than average
    score += (pr - mean_residual) * 0.15 * (1.0 + progress);

    // Slight pressure on bin count
    score += open_bins_count as f64 * 0.05 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by 10 are
    // "harmonic" (easy to fill with typical item sizes); odd/prime-ish
    // leftovers are dead space.
    let post = post_residual as i64;
    let harmonic = (post % 10 == 0) as i64;
    score -= harmonic as f64 * 8.0;

    // Penalize small non-zero leftovers (unusable dead space).
    if post > 0 && post < 10 {
        score += 12.0;
    }

    // Perfect fit is ideal.
    if post == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item exactly fits the post-residual,
    // or if next item leaves a harmonic residual too.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 6.0;
            }
            if nxt_post > 0 && nxt_post < 10 {
                score += 6.0;
            }
        } else {
            // next item cannot fit here anyway; mild penalty for blocking
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Slight preference for reusing existing bins over opening new ones,
    // scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, allow late when consolidation
        // is hard (many open bins with high mean residual).
        score += 18.0 - 10.0 * progress + 0.05 * open_bins_count as f64;
    }

    // Coupling with mean residual: if this bin is much emptier than average,
    // it's a poor consolidation target.
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 5.0;

    // Integer-division threshold: bins whose residual class (post/10) is
    // small get priority (tighter packing).
    score += (post / 10) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space penalty grows with how close the gap is to being usable.
        let gap_deficit = (next_item_size - post_residual) as f64;
        score += 40.0 + 2.0 * gap_deficit;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to the item itself.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Penalize leaving exactly a "hard" residual (small odd gaps 1..10 are rarely reusable).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * (open_bins_count as f64) * (1.0 - tightness);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: moderate default score; only chosen when open bins fit badly.
    if bin_residual == bin_capacity {
        score = 55.0
            + 0.3 * (open_bins_count as f64)
            - (if next_item_size > 0 && next_item_size <= bin_capacity { 10.0 } else { 0.0 });
        // Late in the stream, opening fresh bins is less attractive.
        score += 30.0 * progress;
    }

    // Slight pull toward bins with residuals near the mean (keeps bin residuals balanced).
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
