pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large post_residual super-linearly
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() <= 1.0 {
            score -= 30.0;
        } else if nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // next item won't fit here: mildly penalize leaving a large awkward gap
            score += 0.15 * pr;
        }
    }

    // Dead-space penalty scaled by how "unusable" the residual is:
    // residuals below typical small-item size (10) are dead space
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (10.0 - pr) / 10.0;
    }

    // Global state coupling: when many bins are open, prefer consolidation
    // (fill existing bins rather than spreading); when few bins open, be lenient.
    let consolidation_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * consolidation_pressure * (pr / cap);

    // Mean residual deviation: prefer bins whose residual is below average
    // (i.e., fuller bins) — placing into fuller bins preserves flexibility elsewhere.
    score -= 1.5 * (mean_residual - pr) / cap;

    // Time horizon: early in stream, be more willing to open new bins
    // (score for empty-bin candidate is post_residual = capacity, so subtract
    // from new-bin score early to make it competitive; late, penalize new bins).
    let new_bin_bias = 30.0 * (1.0 - progress) - 20.0 * progress;
    if bin_residual == bin_capacity {
        score -= new_bin_bias;
    } else {
        score += 0.0;
    }

    // Mild penalty for very small item into a very large residual (wasteful pairing)
    if (item_size as f64) < 0.35 * cap && pr > 0.5 * cap {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let poly = norm_post * (1.0 - progress * 0.6) + norm_post * norm_post * (0.5 + progress);

    let mut score = post * (1.0 + 0.5 * progress) + 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.3 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post > 0.0 && (next_item_size as f64) > post {
        score += 12.0 * (1.0 + progress);
    } else if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 * (1.0 - norm_post);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += (open_bins_count as f64).ln() * 3.0 * (0.5 + progress);

    // Deviation from mean residual: prefer bins near mean (balanced packing)
    let dev = (post - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: neutral-ish score, slightly worse early, competitive late
    if bin_residual == bin_capacity {
        score = cap * (1.05 - 0.35 * progress) + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste bucketing via integer division
    let cls = post_residual / 10; // 0..10 harmonic classes
    score += [0.0, -1.0, 0.5, 1.0, 2.0, 3.0, 4.5, 6.0, 8.0, 10.5, 13.0][cls as usize];

    // Modulo arithmetic: penalize post_residuals that are awkward for common item sizes
    let m = post_residual % 10;
    score += (m as f64) * 0.15;

    // Perfect fit reward
    if post_residual == 0 { score -= 25.0; }

    // Lookahead coupling: post_residual exactly matching next item is gold
    if next_item_size > 0 {
        if post_residual == next_item_size { score -= 20.0; }
        else if post_residual >= next_item_size { score -= 3.0; }
        else {
            // dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
        // harmonic class of lookahead: small items are easy to place later
        if next_item_size <= 10 { score -= 2.0; }
        else if next_item_size > 50 { score += 2.0; }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 15.0; }
    // Many alternatives: mild penalty to spread load
    if fitting_bins_count > 3 { score += 1.5; }

    // New-bin candidate: prefer only when existing fit is terrible
    if bin_residual == bin_capacity {
        score = 60.0 + (mean_residual - post_residual as f64).abs() * 0.1;
        if next_item_size > 0 && next_item_size > post_residual { score -= 10.0; }
    }

    // Tight-fit bonus: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 4.0;

    // Stream progression: later in stream, be more conservative about waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.05;

    // Mean residual coupling: penalize bins far below mean residual (fragmented)
    score += ((mean_residual - bin_residual as f64).abs()) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
