pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but not zero (avoid tiny dead space being valued equally with perfect fit).
    if post_residual == 0 {
        score -= 40.0; // perfect fit is excellent
    } else {
        // 2-step lookahead: reward post_residual that exactly matches the next item.
        if next_item_size > 0 {
            let pr = post_residual as i64;
            let ni = next_item_size as i64;
            let diff = (pr - ni).abs() as f64;
            if diff == 0.0 {
                score -= 50.0; // next item fits this bin perfectly
            } else if pr > ni {
                score -= 25.0 * (1.0 - diff / (bin_capacity as f64)); // next item fits with slack
            } else {
                score += 0.05 * diff; // next item won't fit; slight penalty for larger leftover
            }
        }
    }

    // Penalize creating dead space below the minimum item size (unusable gap).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 100.0;
    }
    // Small residuals are generally waste; scale penalty by how far below mean residual we land.
    if (post_residual as f64) < mean_residual {
        score += 0.3 * (mean_residual - post_residual as f64);
    } else {
        score -= 0.1 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
