    // Many fitting bins: prefer tighter ones (already handled by post_residual), but add mild penalty
    // for spreading when many bins could fit — encourage consolidation.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate logic: empty bin gets a moderate default score; only beat open bins
    // when item fits poorly everywhere (handled implicitly, but give it a mild handicap).
    if bin_residual == bin_capacity {
        score += 10.0;
        // Early in stream, opening bins is cheap; later, prefer filling existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Late-stream tightening: waste matters more as we approach the end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
