pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (1.0 + 0.6 * p2 + 0.9 * p3);

    // Base: prefer tight fits, but penalize dead space more as stream progresses.
    let mut score = coupling * cap;

    // Perfect fit reward (smooth, non-linear).
    let fit_ratio = 1.0 - norm_pr;
    score -= 12.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Lookahead: reward residuals that can host the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = pr - nx;
        if slack >= 0.0 {
            let k = 1.0 - (slack / cap) * 0.5;
            score -= 6.0 * k * (1.0 - progress * 0.5);
        } else {
            let miss = (-slack / cap).min(1.0);
            score += 4.0 * miss * (0.5 + p2);
