    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - 0.5 * p3);
    }

    // Contextual coupling with mean residual and open bin count.
    let mr_norm = (mean_residual / cap).clamp(0.0, 1.0);
    score += 3.0 * norm_pr * mr_norm;
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize opening new bins unless residual is truly large.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Harmonic / modulo classes: leftovers divisible into common small classes
    // are more likely reusable by future items (sizes 1..100 unknown).
    let class = post_residual % 10;
    if class == 0 {
        score -= 40.0; // round leftover: matches many item sizes
    } else if class <= 3 {
        score -= 15.0;
    } else {
        score += 10.0 * (class as f64 - 3.0);
    }

    // Prefer bins whose leftover is small relative to capacity (tight packing).
    score += 30.0 * frac * frac;

    // Penalize leaving a leftover that is awkwardly just below next item size
    // (dead space: next item won't fit but leftover is large).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n > pr && pr > 20.0 {
            score += 25.0; // dead space relative to lookahead
        } else if n <= pr && pr - n <= 5.0 {
            score -= 60.0; // lookahead will almost fill the remainder
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // or the item is huge relative to residual.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (mean_residual - item_size as f64) < 0.0;
        if poor_alternatives {
            score -= 150.0;
        } else {
            score += 120.0; // discourage opening bins when fits exist
        }
    }

    // Late in stream: consolidate; early: allow more bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (1.0 - frac);

    // Mild pressure to keep bin count low.
    score += 2.0 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if no open bin fits well, new bin may be fine: soften when item is large.
        if item_size > 50 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 25.0;
    }

    // Penalize placements far below mean residual usage (imbalance).
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 / (1.0 + gap);
        // Perfect 2-chain: item fits now and next item fills bin exactly.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item cannot fit here anyway: mild penalty for wasted lookahead.
        if next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Penalize residuals that are too small to ever hold a meaningful item.
    let dead = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 25.0 * dead;

    // Prefer bins tighter than average (best-fit flavor relative to mean residual).
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when open bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits (this is the only candidate), make it attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Early stream: be slightly more willing to open bins for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins that fill almost exactly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tightness * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Lookahead: penalize leaving a residual that neither fits the next item
    // (dead space) nor is large enough to be reusable.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual as f64 >= ni {
            // residual reusable by next item -> reward proportionally
            let reuse = (post_residual as f64 - ni) / bin_capacity as f64;
            score -= 6.0 * (1.0 - reuse);
        } else {
            // dead space relative to next item
            score += 5.0 * (1.0 - (post_residual as f64) / ni.max(1.0));
        }
        // Chain bonus: item + next item nearly fill the bin
        if item_size as f64 + ni >= bin_residual as f64 - 2.0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins would waste a lot
    // or the stream is early and mean residuals are large.
    if bin_residual == bin_capacity {
        let waste_penalty = 18.0 * (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 20.0 + waste_penalty * (1.0 - progress) - 10.0 * progress;
        // discourage new bin if item leaves large post residual anyway
        score += 0.3 * post_residual as f64;
    }

    // Prefer bins whose residual is close to the mean (spread load evenly)
    // except when item nearly fills the bin.
    let dev = ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();
    score += 4.0 * dev * (1.0 - tightness);

    // Mild penalty for very large post residuals that can't fit small items (10..80 range heuristic)
    if post_residual >= 1 && post_residual < 10 {
        score += 6.0; // unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item / cap;

    // Base: polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fills (small post_residual) strongly.
    // Late stream: dead space matters less, so dampen the penalty.
    let p_norm = post / cap;
    let base = post * (1.0 + 1.5 * p_norm * p_norm) * (1.0 - 0.5 * progress);

    // Reward filling a bin nearly completely (non-linear bonus).
    let fill_bonus = -8.0 * (1.0 - p_norm).powi(3);

    // Penalize creating residual that no plausible future item can use:
    // if post_residual is small but nonzero, it's likely dead space.
    let dead_penalty = if post > 0.0 && post < 10.0 { 6.0 * (10.0 - post) / 10.0 } else { 0.0 };

    // Lookahead coupling: reward if next item fits the post residual.
    let lookahead = if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        -3.0 * (next_item_size as f64 / cap)
    } else if next_item_size > 0 {
        2.0 * (1.0 - (post - next_item_size as f64).abs() / cap)
    } else {
        0.0
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -10.0 } else { 0.0 };

    // Crowd penalty: many open bins -> prefer consolidating into low-residual bins.
    let crowd = 0.5 * (open_bins_count as f64).ln().max(0.0) * p_norm;

    // Deviation from mean residual: prefer bins whose residual is close to item
    // (smooth Gaussian-like coupling).
    let dev = (bin_residual as f64 - item - mean_residual) / cap;
    let dev_pen = 4.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when other bins fit.
    let new_bin_pen = if bin_residual == bin_capacity {
        15.0 + 10.0 * (1.0 - progress) + if fitting_bins_count > 0 { 20.0 } else { 0.0 }
    } else {
        0.0
    };

    base + fill_bonus + dead_penalty + lookahead + last_chance + crowd + dev_pen + new_bin_pen
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small" residue classes (mod 10) are more likely to be filled later.
    let r = post_residual % 10;
    let harmonic_bonus: f64 = match r {
        0 => 6.0,   // perfectly round leftover, easy to reuse
        1 | 2 | 3 => 4.0,
        4 | 5 | 6 => 2.0,
        7 | 8 => 0.5,
        _ => -1.5,  // awkward leftover (9) -> penalize slightly
    };
    score -= harmonic_bonus;

    // Integer-division threshold: large post_residual quarters are dead space.
    let quarter = bin_capacity / 4;
    if post_residual >= 3 * quarter {
        score += 8.0; // leaving > 3/4 empty is wasteful
    } else if post_residual >= 2 * quarter {
        score += 3.0;
    } else if post_residual >= quarter {
        score -= 2.0; // tight fit, good
    } else {
        score -= 4.0; // near-perfect fit
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= 6.0 - (waste as f64) * 0.08;
        } else {
            // next item cannot use this residual: mild penalty scaled by gap class
            let gap_class = (next_item_size - post_residual) / 10;
            score += gap_class as f64 * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.05);
        score += 15.0 - pressure.min(14.0);
        // exact-fit class check: if item is a harmonic fraction of capacity, new bin is fine
        if bin_capacity % item_size == 0 {
            score -= 8.0;
        }
    }

    // Progress-based tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items are waste.
    let dead_threshold = 10.0 + 0.15 * mean_residual.max(0.0);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 3.0 * (dead_threshold - post_residual as f64);
    }
    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 0.1 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: penalize harder.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * pressure;

    // New-bin candidate: allow opening a fresh bin only when current fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score = bin_capacity as f64 - 10.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open
        } else if fitting_bins_count == 1 {
            // Only open new bin if the sole fitting bin would leave a bad gap.
            if (bin_residual as f64 - item_size as f64) < (bin_residual - item_size).min(next_item_size) as f64
                && post_residual < next_item_size && post_residual > 0 {
                score -= 25.0;
            } else {
                score += 20.0;
            }
        } else {
            score += 30.0; // plenty of alternatives, keep bins tight
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how well next item matches the leftover.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 - slack * 0.4;
            // Chain fit bonus: next item then leaves near-zero too.
            if slack == 0.0 {
                score -= 200.0;
            }
        } else {
            // Penalize leftovers that the next item cannot use.
            score += 30.0;
        }
    }

    // Penalize small dead space (unusable slivers), scaled by item size range.
    if post_residual > 0 {
        let dead_threshold = 12.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
    }

    // Prefer bins whose residual is far above the mean (consume the "fattest" bins first),
    // i.e. penalize bins with residual below mean.
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to typical residuals (poor fit everywhere) or late in stream
    // with many bins open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let mean_fit = if !mean_residual.is_nan() { mean_residual / bin_capacity as f64 } else { fit_ratio };
        // Penalize new bins when open bins offer reasonable fits.
        score += 80.0;
        // Reward opening a new bin when the item is big and open bins are tight.
        score -= (fit_ratio - mean_fit) * 120.0 + progress * 20.0;
        // Few open bins => cheaper to open a new one.
        if open_bins_count <= 2 {
            score -= 40.0;
        }
    }

    // Mild early-stream preference for keeping bins tight (build good structure early).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets extra bonus (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any future item (items >= 1,
    // typical >= 10) are wasted. Threshold at ~10.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0;
            // Extra reward for chained near-perfect fit.
            let chain_slack = post_residual as f64 - next_item_size as f64;
            score -= 6.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to gap.
            let gap = next_item_size as f64 - post_residual as f64;
            score += 2.0 * (gap / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // More alternatives -> mild penalty for hoarding this bin's space.
        score += 1.5 * (fitting_bins_count.saturating_sub(1) as f64).min(6.0);
    }

    // New-bin candidate handling: only open a new bin when the item fits
    // poorly everywhere else (large post_residual relative to typical items)
    // or when it's early and there's room to consolidate later.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Opening is more attractive early in the stream (future items can fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many open bins already, discourage fragmentation.
        score += 1.0 * open_bins_count as f64;
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin is more justified.
        score -= 0.5 * mean_residual;
        // If the item leaves a large residual in a new bin, that's fine
        // (fresh bin has room); if it would nearly fill a new bin, that's great.
        if post_residual < 10 {
            score -= 15.0;
        }
    } else {
        // Using an existing bin: reward when mean residual is high (bins are loose)
        // to encourage consolidation into fullest bins.
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        // Slight preference for fuller bins (smaller residual) as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual with smooth polynomial shaping
    let x = pr / cap; // in [0,1]
    let mut score = x;

    // Non-linear coupling: penalize large residuals more as stream progresses
    // (late stream => prefer tight fits to avoid opening new bins)
    let progress_weight = 0.5 + 2.0 * t * t;
    score += progress_weight * x * x;

    // Reward near-perfect fits smoothly (small post_residual => strong subtraction)
    score -= 2.0 * (1.0 - x) * (1.0 - x) * (1.0 + t);

    // Penalize bins whose post-residual matches next item poorly: if next item
    // could fill this residual, reward leaving exactly that space (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = x - nx;
        score += 0.8 * diff * diff; // best when post_residual == next_item_size
        // extra reward if next item fits exactly
        score -= 0.6 * (1.0 - (diff * diff)) * (1.0 - t);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 1.5 + 2.0 * t;
    }

    // Many open bins: prefer consolidating into bins below mean residual
    let mr = mean_residual / cap;
    score += 0.3 * (x - mr) * (open_bins_count as f64).ln();

    // Mild penalty for very full bins early (keep flexibility), smooth in t
    score += 0.4 * (1.0 - x) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // modulo classes are "tight fits" and should be rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Class A: post_residual divisible by 10 (aligns with typical size grid)
    if pr % 10 == 0 {
        score -= 6.0;
    } else {
        score += (pr % 10) as f64 * 0.4;
    }

    // Class B: small dead space classes (1..=9) are nearly unusable
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Integer-division threshold: leftover in the "half-bin" band is valuable
    let half = bin_capacity / 2;
    if pr >= half && pr <= half + 10 {
        score -= 4.0;
    }

    // Quarter-band coupling: leftover near a quarter boundary pairs well
    // with next items of small size classes.
    let q = bin_capacity / 4;
    if next_item_size > 0 {
        if pr >= next_item_size {
            // lookahead fits in this bin afterwards: reward, scaled by
            // how snugly both items nest
            let snug = (pr - next_item_size) as f64;
            score -= 3.0 + (10.0 - snug.min(10.0)) * 0.5;
        } else {
            score += 2.0;
        }
        // harmonic pairing: next_item_size and post_residual share a divisor class
        if next_item_size % 10 == pr % 10 && pr >= next_item_size {
            score -= 2.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins mildly; worse when many bins already open
        score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
        // but if the item is huge and mean residual is small, new bin is fine
        let frac = item_size as f64 / cap;
        if frac > 0.7 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // late in the stream, prefer consolidation
        let t = step_index as f64 / total_items.max(1) as f64;
        score += t * 5.0;
    } else {
        // reward filling bins close to capacity relative to mean residual
        let fill = 1.0 - prf / cap;
        score -= fill * mean_residual.max(0.0) * 0.3;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.85;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (small post_residual) already favored by starting score.

    // Aggressive 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this placement sets up an exact fit for the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits; mild reward proportional to how well it chains.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * slack;
        } else {
            // Next item won't fit in this bin's remainder; penalize dead space,
            // worse when the leftover is small (nearly unusable).
            let dead = post_residual as f64;
            score += 0.6 * dead;
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins would create bad fits.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; add small penalty so tight existing fits win,
        // but subtract if open bins are already fragmented.
        score += 5.0;
        score -= 0.15 * mean_residual;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            // Opening fresh bin pairs current item with next item nicely.
            score -= 10.0;
        }
    }

    // Prefer filling bins whose residual deviates below the mean (compact bins first).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.1 * (mean_residual - residual_f);
    } else {
        score += 0.1 * (residual_f - mean_residual);
    }

    // Slight preference to keep number of open bins low as stream progresses.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity as f64 - post_residual as f64) * (0.15 + 0.35 * progress);

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize leaving large awkward gaps.
            score += (post_residual as f64) * 0.25 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global state coupling: many open bins with high mean residual -> favor filling existing bins.
    let pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * 10.0);
    score -= pressure * (1.0 + progress);

    // Penalize creating dead space below the minimum item size (10) unless it's near capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: keep it competitive only when few fitting bins or huge mean residual.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.3 - (fitting_bins_count as f64) * 4.0;
    }

    // Mild preference for bins with residual close to item size (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;

    let mut score = pr + 12.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (10.0 + 20.0 * progress);

    // Penalize opening a new bin when existing bins can fit
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: favor bins whose post_residual fits next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 5.0 * (1.0 - ((pr - n) / cap));
        } else {
            score += 4.0;
        }
    }

    // Mild dispersion penalty relative to mean residual
    score += (pr - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual), but discount tiny residuals
    // that become dead space (harmonic class of post_residual).
    let mut score = post;

    // Harmonic class logic: classify post_residual into usable classes via
    // integer division thresholds on capacity fractions.
    let post_frac = post / cap; // 0..1
    // Dead-space class: residual too small for typical items (<= 15% of capacity
    // or <= 10 absolute) is nearly unusable -> strong penalty.
    if post_residual <= 10 || post_frac <= 0.15 {
        score += 25.0;
    }
    // Sweet-spot class: residual in [20, 50] (fits mid-size items) -> reward.
    if post_residual >= 20 && post_residual <= 50 {
        score -= 12.0;
    }
    // Large leftover class: residual > 60 wastes a nearly empty bin's potential.
    if post_residual > 60 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward heavily (perfect harmonic pair).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nxt_frac = (post_residual - next_item_size) as f64 / cap;
            // reward proportional to how well next item nests
            score -= 15.0 * (1.0 - nxt_frac);
        } else {
            // next item won't fit here: mild penalty scaled by gap
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 10.0; // still better to fill than open new bin
        }
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit. Penalize the fresh bin mildly, more so
    // when many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // but if current item is large, a fresh bin is natural
        if item_size >= 60 {
            score -= 12.0;
        }
    }

    // Mean-residual coupling: if this bin's post-residual is far below the mean,
    // it is being packed tighter than average -> reward.
    let mean_dev = (mean_residual - post) / cap;
    score -= 8.0 * mean_dev;

    // Stream progression: late in the stream, close out bins aggressively
    // (favor tight fits even more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Harmonic tie-breaker: modulo arithmetic on post_residual in units of 10
    // to break ties toward round residual classes.
    let harmonic = (post_residual % 10) as f64;
    score += 0.5 * harmonic;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 4.0 * post_residual as f64;
    }
    // Zero residual is perfect packing: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize bins whose residual is much tighter than the fleet average (waste concentration),
    // but reward bins that absorb more than average space.
    let diff = mean_residual - bin_residual as f64;
    score += 0.8 * diff;

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.3 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        // post residual cannot host next item and is small: dead space penalty
        score += 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a tight fit (i.e., best open-bin post residual would be large).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, softened when the stream is early or many bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 30.0 * (1.0 - progress);
        if post_residual >= item_size.saturating_add(10) {
            score -= 15.0; // fresh bin leaves roomy residual for future items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect fit: next item leaves a tiny remainder afterwards.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        score -= 25.0;
    }
    // Next item almost fits: leaving a residual slightly below next_item_size is wasteful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 5 {
        score += 20.0;
    }

    // Penalize unusable dead space (nonzero but below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }
    // Zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open new bins when fits are poor,
    // but reward it when all open bins are nearly full (high mean fill).
    if bin_residual == bin_capacity {
        let mean_fill = mean_residual / bin_capacity as f64;
        score += 25.0 - 50.0 * (1.0 - mean_fill);
    }

    // Early in stream, be slightly more willing to start fresh bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted fraction of the bin.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Strong reward for exact / near-exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Dead-space penalty: residuals below the minimum item size are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 18.0 * (1.0 - (next_item_size as f64) / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize if it becomes dead space.
            if post_residual < 10 {
                score += 12.0;
            }
        }
    }

    // New-bin candidate handling: penalize opening a new bin when open bins fit well,
    // but allow it when residuals across open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 55.0;
        // Later in the stream, keeping bins tight matters more; discourage new bins less
        // when mean residual is small (open bins are nearly full).
        new_bin_penalty *= 1.0 - 0.5 * progress;
        if mean_residual < 25.0 {
            new_bin_penalty -= 30.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 100.0; // forced new bin
        }
        score += new_bin_penalty;
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 15.0 * tightness;

        // Mild preference for fuller bins among many open bins.
        score += 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).sqrt() * 0.2;
    }

    // Time-horizon modulation: early in stream, be conservative (slight penalty on
    // aggressive fills that leave medium gaps); later, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - waste_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear penalty on wasted residual, amplified by stream progress
    let norm_pr = pr / cap;
    score += (norm_pr * norm_pr) * cap * (0.5 + 1.5 * progress);

    // Reward near-perfect fits smoothly
    score -= (1.0 - norm_pr).powi(3) * cap * 0.6;

    // Prefer bins whose residual is close to the item (smooth coupling)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio).abs() * cap * 0.35;

    // Lookahead: favor residual that still fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly reward using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening unless current bins fit poorly
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let bad_fit = (pr / cap).powi(2) * cap;
        score += 10.0 + openness * 0.8 - bad_fit * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += (next_item_size as f64) * 0.02 * progress;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter)
    score += (mean_residual - pr).max(0.0) * 0.08;
    score -= (pr - mean_residual).max(0.0) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead-space" classes.
    let post = post_residual as i64;
    let residue_class = (post % 10) as f64;
    // Penalize residuals that are awkward (small nonzero residues are hard to fill).
    if post > 0 {
        score += 12.0 * (1.0 - residue_class / 9.0);
    }
    // Perfect fit is excellent.
    if post == 0 {
        score -= 60.0;
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional to how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more if the leftover is tiny (wasted).
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins when open bins exist,
    // unless this stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 30.0 + 40.0 * (1.0 - progress);
        score += penalty * (open_bins_count as f64).sqrt().max(1.0);
        // A new bin is attractive if the item is huge and mean residual is low.
        if item_size as f64 > 0.6 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 50.0;
        }
    }

    // Prefer bins with residual close to item_size (tight fit) via harmonic coupling.
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64).abs() / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Slight bias toward keeping mean residual balanced across open bins.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items can be as small as 1, but statistically small gaps are wasteful)
    // are heavily penalized.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            // Unusable dead space: strong penalty.
            score += 40.0 * (10.0 - pr) / 10.0;
        } else if post_residual <= 30 {
            // Risky small gap: moderate penalty.
            score += 12.0 * (30.0 - pr) / 20.0;
        }
    }

    // Reward near-perfect fits (tight packing) with a non-linear bonus.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if tightness < 0.10 {
        score -= 15.0 * (1.0 - tightness / 0.10);
    }

    // Prefer bins whose residual is close to the item size (best-fit coupling).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.35 * fit_gap;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (2.0 + 8.0 * progress);
    score += 1.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (which would strand this bin's residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead (k=2): if the next item fits exactly in the post residual,
    // reward this placement strongly; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            if next_item_size == post_residual {
                score -= 20.0; // chainable perfect fit
            } else if post_residual - next_item_size <= 10 {
                score -= 8.0;
            }
        } else if next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 10.0; // next item would strand here anyway
        }
    }

    // Mild preference toward fuller bins relative to the fleet mean residual.
    score -= 0.25 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when item is large relative to
    // capacity (poor fit elsewhere) or no open bin is a good home.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = 60.0 - 25.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, huge reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportional to how tight the chain is
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 0.8;
        } else {
            // next item won't fit here: penalize dead space that blocks lookahead
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
    }

    // Relative to mean residual: placing in a bin with residual near the mean
    // keeps balance; extreme residuals penalized.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // competition: mild bonus, scaled by number of alternatives
        score += 10.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity (i.e., open bins are poor fits anyway).
    if bin_residual == bin_capacity {
        let mut penalty = 300.0;
        // If item nearly fills a fresh bin, opening new is fine.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        penalty -= fill_ratio * 400.0;
        // If many bins are open and residuals are large, opening is wasteful.
        penalty += open_bins_count as f64 * 5.0;
        // Late in stream, prefer consolidating.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty += progress * 100.0;
        score += penalty.max(0.0);
    }

    // Small global tightness term: prefer bins that end with small residuals
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let cap_f = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64) / cap_f;
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small to be useful for typical items,
    // but only mildly (small residuals are often unavoidable).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if (next_item_size as i64 - post_residual as i64) == 0 {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item can fit here afterwards: reward proportionally
            score -= 8.0 * (next_f / (post_residual as f64));
        } else {
            // next item cannot use the leftover: penalize large leftovers
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where fit is tighter (already captured),
        // slight penalty to spread pressure
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: opening a new bin is penalized when
    // decent fitting bins exist, but attractive when mean residual is low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // base cost of opening a bin
        score += 30.0;
        // discount the new bin when open bins are nearly full on average
        let mean_tightness = 1.0 - (mean_residual / cap_f).clamp(0.0, 1.0);
        score -= 40.0 * mean_tightness * mean_tightness;
        // late in the stream, prefer consolidating into open bins
        score += 10.0 * progress;
        // many open bins: discourage opening yet another
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Favor reusing bins whose residual is below average (consolidate fullness)
        let res_f = bin_residual as f64;
        if mean_residual > 0.0 {
            score += 0.10 * (mean_residual - res_f);
        }
        // slight preference for bins that are already fuller
        score -= 0.08 * (cap_f - res_f);
    }

    // Global pressure: when many bins are open, be greedier about tight fits.
    if open_bins_count > 1 {
        score -= 0.5 * (open_bins_count as f64).ln() * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: waste-minimizing quadratic in post residual
    let mut score = post * (1.0 + norm_post);

    // Smooth non-linear coupling with stream progress: later in the stream,
    // tolerate residual slack less (tighten packing).
    let tighten = 1.0 + 2.0 * progress * progress;
    score *= tighten;

    // Interaction: item size vs residual — large items in nearly-full bins favored
    let fill = norm_item * (1.0 - norm_post);
    score -= 8.0 * fill * (1.0 + progress);

    // Penalize bins whose residual is far from mean residual (fragmentation signal)
    let dev = (post - mean_residual).abs() / cap;
    score += 4.0 * dev * dev * (1.0 + progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // More competing bins: slight penalty to spread items across many bins
        score += 0.5 * (fitting_bins_count as f64).sqrt();
    }

    // Lookahead coupling: if next item fits into resulting residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 6.0 * (nx / cap) * (1.0 - progress * 0.5);
        } else {
            // residual too small to host next item: penalize dead space
            score += 3.0 * (nx / cap) * (1.0 - norm_post);
        }
    }

    // New-bin candidate: neutral-ish baseline with progress-dependent threshold
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.5 * progress) - 4.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes are preferred (less dead space).
    let pr = post_residual;
    let class = match pr {
        0 => -40.0,                    // perfect fit
        1..=5 => -25.0,                // near-perfect
        6..=10 => -15.0,
        11..=20 => -6.0,
        _ => 0.0,
    };
    score += class;

    // Integer-division threshold: leftover usable by the lookahead item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // leftover can host the next item: reward proportionally,
            // but not too much (keep bins tight).
            let fit_quotient = pr / next_item_size.max(1);
            score -= 4.0 + (fit_quotient as f64).min(3.0) * 2.0;
        } else {
            // leftover is dead space for the next item: penalize by gap size
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.6;
        }
    }

    // Modulo arithmetic on capacity fractions: residuals near harmonic
    // fractions of capacity are structurally useful.
    let frac = (pr as f64) / (bin_capacity as f64);
    let harmonic = (frac * 8.0).round() / 8.0; // nearest 1/8 of capacity
    let dist = (frac - harmonic).abs();
    score += dist * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits
    // well; penalize opening bins when existing ones have decent room.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / (bin_capacity as f64);
        score += 12.0 + pressure * 25.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host current+next pair
        }
    }

    // Mild stream-progression damping: early on, be more conservative
    // about wasting space in few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    // Tie-break: prefer bins with residual close to the item (tight fit)
    score += ((bin_residual - item_size) as f64 - post_residual as f64).abs() * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual <= 10 {
        // unusable dead space relative to smallest items
        score += 60.0 * (11.0 - pr) / 10.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 80.0;
    }
    // Medium residual: moderately bad if below typical small item size
    if post_residual > 10 && post_residual < 20 {
        score += 12.0 * (20.0 - pr) / 10.0;
    }

    // Favor bins whose residual is well used already (tight fits beat loose fits)
    score += 0.15 * (bin_residual as f64 - pr);

    // Open-bin pressure: penalize using bins when many are open, mild
    score += 0.05 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a bin that
    // then leaves this bin stranded.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: bonus if the leftover residual can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (1.0 - pr / cap);
        } else if pr > 0 {
            // leftover that cannot fit next item: dead-space risk
            score += 6.0 * (1.0 - pr / nx);
        }
    }

    // New-bin candidate handling: an empty new bin has large post_residual;
    // make it attractive only when this item would otherwise create bad gaps
    // (its natural pr is already high, so no extra penalty needed), but add
    // slight pressure to prefer reuse when few bins are open.
    if bin_residual == bin_capacity {
        score += 3.0;
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 4.0;
        }
    }

    // Progress term: early in the stream, allow more bins; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - pr / cap);

    // Deviation from mean residual: prefer bins tighter than average
    score += 0.08 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits into post residual with little slack.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here afterwards; penalize proportionally to overflow gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Penalize leaving dead space far from mean residual (fragmentation).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when this placement is a bad fit
    // (large post residual that nothing can use).
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its post residual is large but "clean".
        score = (bin_capacity - item_size) as f64;
        if post_residual < 10 {
            score -= 40.0; // near-perfect fill of new bin
        }
        // If item nearly fills a new bin, opening is attractive.
        score -= (item_size as f64) * 0.2;
    }

    // Progress-based mild pressure to consolidate into fewer bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
