pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    // smooth non-linear coupling of post_residual with stream progress
    let progress_term = (1.0 - t) * norm_pr * norm_pr * cap + t * norm_pr * 20.0;
    score += progress_term;
    // penalize tight fits less as stream progresses (pack harder later)
    let tightness = (norm_pr - 0.5).abs();
    score -= 15.0 * t * tightness * tightness;
    // reward filling bins nearly full
    score -= (item_size as f64 / cap) * 25.0 * (0.5 + 0.5 * t);
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0;
    }
    // discourage spreading across many open bins when residuals are high
    score += 0.5 * (open_bins_count as f64).ln() * (mean_residual / cap);
    // lookahead: favor bins whose post_residual matches next item
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64).abs();
        score += 0.3 * d;
        if next_item_size as f64 <= pr {
            score -= 8.0 * (1.0 - d / cap);
        }
    }
    // new-bin candidate: mildly penalize opening new bins unless nothing fits well
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * t;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Penalize leftovers that are unusable for typical small items (1..100 range).
    // Dead space: residual smaller than the smallest plausible item (~10) is pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward: post_residual near zero.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Harmonic classes via integer division on post_residual:
    // class 0: (0,25], class 1: (25,50], class 2: (50,75], class 3: (75,100]
    let class = post_residual / 25;
    match class {
        0 => score -= 20.0,                 // tight leftover is good
        1 => score += 10.0,                 // half-full leftover: mediocre
        2 => score += 20.0,                 // large leftover
        _ => {}                             // nearly empty bin used: fine
    }

    // Modulo arithmetic: leftover that is a clean multiple of common item sizes
    // (10, 20, 25, 50) is more likely to be filled by future items.
    let r = post_residual;
    if r != 0 && (r % 10 == 0 || r % 20 == 0 || r % 25 == 0 || r % 50 == 0) {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after next placement
            let post2 = post_residual - next_item_size;
            score -= 30.0;
            if post2 < 10 {
                score -= 15.0; // chain closes tightly
            }
        } else {
            // next item cannot use this leftover: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin if this placement is terrible.
    if bin_residual == bin_capacity {
        // New empty bin: post_residual == capacity. Give a neutral-ish baseline,
        // penalized so we prefer reusing bins with decent fits, but it becomes
        // attractive when every open bin would leave large dead space.
        score = 0.5 * cap + 40.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 30.0; // big next item likes a fresh bin
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Prefer spreading load when many bins are open and mean residual is high.
    if open_bins_count > 2 {
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.15;
    }

    // Slight preference for tighter fits overall.
    score += (1.0 - frac) * 5.0 - frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "unusable" if it is too small for typical items (1..=100 unknown,
    // so treat gaps below a conservative threshold as dead space).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 50.0; // hard penalty for creating tiny dead space
    } else if (post_residual as f64) < 2.0 * dead_threshold {
        score += 15.0; // soft penalty for near-dead space
    }

    // Reward tight fits: the smaller the post_residual relative to bin capacity,
    // the better the packing efficiency.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins when not necessary.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.5 * pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if (post_residual as f64) < dead_threshold {
            // next item cannot use the dead space; reinforce penalty
            score += 10.0;
        }
    }

    // Mean-residual anchoring: prefer bins whose resulting residual is close to
    // the mean (keeps bin states homogeneous and predictable for future fits).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // New-bin candidate calibration: an empty bin is only attractive when current
    // bins would end with dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 35.0;
        // reduce cost when many open bins already exist (consolidation pressure
        // is less useful late) and when the item is large
        score -= 0.1 * open_bins_count as f64;
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // if the only alternative creates dead space, opening a bin is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity fraction.
    score = 0.6 * score + 0.4 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // 2-step lookahead: strongly reward bins where the next item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 18.0 * (1.0 - next_tightness);
        } else {
            // Penalize leaving residual that the next item just barely misses.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 {
                score += 0.8 * miss;
            }
        }
    }

    // Compare post_residual against mean residual of open bins:
    // filling a bin below-average reduces fragmentation elsewhere.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer filling existing bins over opening new ones, more so early in stream
    // and when many bins are already open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, unless it would give a perfect lookahead chain.
        let mut new_penalty = 25.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= 0.1 * bin_capacity as f64 {
            new_penalty -= 30.0;
        }
        score += new_penalty;
    }

    // Small bonus for near-perfect fills.
    if post_residual <= 3 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared residual amplifies small dead space value.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64 / bin_capacity as f64) * 10.0;
        } else {
            // Next item won't fit here; penalize large leftovers slightly more.
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more conservative (prefer new bins
    // for large items); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Global state coupling: if mean residual is high, prefer filling bins
    // with large relative fills; if mean residual is low, tolerate slack.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * (mean_residual / bin_capacity as f64) * 8.0;

    // Penalize spreading across many open bins when a compact fit exists.
    score += open_bins_count as f64 * 0.02;

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or the stream is early (plenty of future items to fill it).
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * 10.0;
        let size_penalty = fill_ratio * 15.0;
        score += 8.0 + size_penalty - early_bonus;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0; // new bin can also host the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on leftover space (tight fits win).
    let mut score = post * post / cap;

    // Smooth coupling: as the stream progresses, waste matters more (fewer items left to fill gaps).
    score += post * (0.5 + 2.0 * progress);

    // Reward using an already-open bin, more strongly when bins are scarce relative to progress.
    let open_bonus = 8.0 + 6.0 * (1.0 - progress);
    score -= open_bonus * (1.0 - post / cap);

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward leaving that gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 6.0 * (1.0 - gap / cap);
        // Penalize leaving gaps that are awkwardly larger than the next item.
        if post > nxt {
            score += 0.15 * (post - nxt);
        }
    }

    // Prefer bins whose residual is near the mean (keeps bin population balanced).
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 * (1.0 - progress);
        score += 25.0 + open_pressure;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 15.0 * fitting_bins_count as f64;
        }
    }

    // Mild penalty for a nearly-full bin being "used up" on a small item.
    if item_size < 20 && post < 5.0 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Exact fit: overwhelmingly reward closing a bin perfectly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space class: tiny unusable sliver (1..9) is worse than a larger
    // but potentially reusable residual. Penalize it.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Harmonic class bands: integer-division classes of post_residual.
    // Larger classes (more leftover) get progressively penalized.
    let class = post_residual / 10;
    score += match class {
        0 => 0.0,
        1 => 5.0,
        2 => 10.0,
        3 => 14.0,
        4 => 17.0,
        5 => 20.0,
        6 => 22.0,
        7 => 24.0,
        8 => 26.0,
        9 => 28.0,
        _ => 30.0,
    };

    // Lookahead (k=2): if the next item also fits in the post residual,
    // reward this bin; an exact two-item closure is best.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lpost = post_residual - next_item_size;
        score -= 20.0 + lpost as f64 * 0.3;
        if lpost == 0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // next item cannot follow here: mild penalty
        score += 5.0;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many competing bins: slight tie-break toward bins with residual
    // close to the mean (keep the bin pool balanced).
    score += (post - mean_residual).abs() * 0.05;

    // New-bin candidate (empty bin): default to a high score so it is
    // only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = cap + 5.0;
        if fitting_bins_count == 0 {
            // No open bin can take the item: new bin is the only choice.
            score -= 200.0;
        } else if post_residual >= 20 {
            // Item is small relative to capacity; opening fresh is wasteful.
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item are wasted forever.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Reward tight fits (small post_residual relative to residual).
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 40.0 * tightness;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Perfect fit for the lookahead item: strong bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer spreading load toward bins with residual above the mean.
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // leftover is reusable by the next item: reward, more so if snug
            let snug = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 15.0 + 25.0 * snug;
        } else {
            // leftover too small for the next item: penalize dead space
            score += 12.0 + 0.5 * (nxt - post_residual as f64);
        }
    }

    // Compare against mean residual of open bins: prefer tighter-than-average bins.
    score += 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when every open bin would create severe dead space.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // Slight preference to fill older bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > post_residual && next_item_size > bin_residual {
            // Next item won't fit anywhere in this bin chain; keep this bin flexible.
            score += 4.0;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Prefer new bin when open bins have large residuals (poor packing) or many bins open.
        score = 20.0 + 40.0 * pressure + 2.0 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: definitely open
        }
        if fitting_bins_count == 1 {
            score += 60.0; // a last-chance bin exists: avoid opening new
        }
        // Early in stream, mild preference to consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Slight penalty for spreading across many bins.
    score += 0.5 * (open_bins_count as f64);

    // Time-horizon modulation: late in the stream, be more aggressive about tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Favor bins whose residual is close to item (minimal waste relative to need).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.15 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;
    let next = next_item_size as f64 / cap;
    let mean_res_norm = mean_residual / cap;

    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter packing is rewarded more aggressively.
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= progress_poly * (cap - post) * 0.35;

    // Non-linear penalty on dead space: small residuals that nothing can use.
    let dead = post_norm * post_norm;
    score += dead * cap * 0.6;

    // Reward residuals that closely match the next item size (smooth kernel).
    let gap = (post - next) / cap;
    score -= (-gap * gap * 8.0).exp() * 12.0;

    // Penalize bins whose residual is far below the mean residual (wasting large holes).
    let dev = (mean_res_norm - post_norm).abs();
    score += dev * dev * cap * 0.25;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mild pressure to consolidate into fewer bins as open-bin count grows.
    score += (open_bins_count as f64).ln().max(0.0) * post_norm * 3.0;

    // Slight preference for fuller bins overall (non-linear in fill ratio).
    let fill = 1.0 - post_norm;
    score -= fill * fill * cap * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes (multiples of small denominators) are favored,
    // since future items more likely tile them exactly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Residue class bonus: post_residual divisible by 10/20/25 leaves tileable space
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;
    if r10 == 0 {
        score -= 4.0;
    } else if r25 == 0 {
        score -= 3.0;
    } else if r10 <= 2 || r10 >= 8 {
        score += 1.5; // near-miss residues create awkward dead space
    }

    // Integer-division threshold: classify leftover into harmonic bands
    let band = post_residual / 25; // 0..4 quartile band of leftover
    match band {
        0 => score -= 2.0,   // tight fit, excellent packing
        1 => score += 0.5,   // small leftover, still useful
        2 => score += 1.0,
        3 => score += 2.0,   // large leftover wasted on a nearly-full bin
        _ => {}
    }

    // Lookahead coupling: does next_item_size fit exactly or well into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect harmonic pairing
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 5.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item cannot use this leftover: penalize proportionally
            let over = (next_item_size - post_residual) as f64;
            score += 2.0 * (over / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large relative to capacity or few bins fit it.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        let pressure = if fitting_bins_count == 0 { 8.0 } else { 0.0 };
        score = cap - 30.0 * frac + pressure
            - 4.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    // Mild normalization by mean residual: prefer bins tighter than average
    score -= 0.05 * (mean_residual - pr);

    // Slight recency regularization to avoid pathological late-stream hoarding
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual <= 9 {
            // Tiny gap: essentially dead space.
            score += (10.0 - pr) * 12.0;
        } else if post_residual <= 19 {
            // Risky gap: only very small items could reuse it.
            score += (20.0 - pr) * 4.0;
        } else {
            // Usable gap: mild reward scaled by reusability.
            score -= (pr - 19.0) * 0.15;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Baseline penalty so we prefer reusing open bins with decent fits.
        score += 10.0 + open_bins_count as f64 * 0.2;
        // But if the current item would leave a dead gap in every open bin,
        // opening fresh can win: new-bin post_residual is large (usable).
        if post_residual >= 20 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if next item fits the post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // Post residual can't host next item: slight penalty for waste.
        score += pr * 0.05;
    }

    // Mild drift with stream progression: early on, be conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 1.5;

    // Slight normalization toward mean residual state.
    score -= (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0; // perfect 2-item completion
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportional to tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 * tight;
        } else {
            // next item won't fit here; penalize dead space relative to next item
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer minimal post_residual
        score -= 50.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Penalize large unusable residuals (dead space below min item size 1..100 unknown; use 10 as typical floor)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize slightly unless open bins are congested or lookahead fits perfectly
    if bin_residual == bin_capacity {
        let congestion = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += 20.0 + congestion - 0.2 * open_bins_count as f64;
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap > 0.0 {
            score += 0.6 * gap.sqrt();
        } else {
            // Bonus if next item exactly fills leftover space.
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * mean_residual;
        // Open new bins more readily late in the stream when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer bins below mean residual (more filled bins get priority).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild penalty for creating residuals in the awkward 1..10 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight scaling with number of open bins: consolidate when many bins open.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr + norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress: early on, waste is cheap;
    // late in the stream, tight fits matter more (progress term grows smoothly).
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth bell around small post_residual.
    let tightness = (-norm_pr * 6.0).exp(); // peaks when post_residual near 0
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize leaving residual that is slightly larger than a typical item
    // (dead space) — smooth polynomial in normalized residual.
    let dead = (norm_pr - 0.2) * (norm_pr - 0.2);
    score += 8.0 * dead * norm_pr;

    // Last-chance bin: strongly favor using it (smooth exponential reward).
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild penalty when many bins compete, scaled smoothly.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly (smooth).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let exact = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 10.0 * exact.max(0.0) * (1.0 + progress);
    }

    // Prefer fuller bins relative to the fleet mean (smooth interaction).
    score += 0.5 * (mean_residual - pr);

    // Slight preference for consolidating into fewer bins.
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: only attractive when current bins are very full or none fit well.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).powi(2);
        score = 40.0 * (1.0 - progress) + 10.0 * pressure + 5.0;
        if fitting_bins_count == 1 {
            score += 30.0; // discourage opening new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (mod arithmetic) ---
    // Residuals divisible by 10 are "harmonic" with the item-size grid (items 10..80),
    // so reward them; small odd residues are dead space, penalize them.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongest reward.
        score -= 50.0;
    } else {
        let class = pr % 10;
        // Harmonic classes: 0 is best, 5 is half-harmonic, odd classes worst.
        let class_penalty = match class {
            0 => -8.0,
            5 => -3.0,
            2 | 4 | 6 | 8 => 2.0,
            _ => 6.0, // odd residues 1,3,7,9
        };
        score += class_penalty;

        // Integer-division threshold: can the leftover host a "small" item (<= 10)?
        // A residual >= 10 is reusable; below that it is dead space.
        if pr >= 10 {
            score -= 4.0;
        } else {
            score += 10.0;
        }
        // Residual in the "medium item" band (>= 25) is very reusable.
        if pr >= 25 {
            score -= 5.0;
        }
        // Large leftover (>= 50): bin still half-capable, big reward.
        if pr >= 50 {
            score -= 6.0;
        }
    }

    // --- Capacity-fraction coupling ---
    let frac = pr as f64 / bin_capacity as f64;
    // Non-linear: reward leaving fractions near 0.5 or 0.0 (harmonic splits).
    let half = (frac - 0.5).abs();
    score += 6.0 * half * half; // penalize distance from the half-full harmonic split
    if frac < 0.1 && pr > 0 {
        score += 8.0; // tiny sliver: nearly dead space
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if pr >= next_item_size {
            // This bin can also host the next item: chain-fit bonus.
            score -= 5.0;
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 3.0; // chained fit stays on the harmonic grid
            }
        } else if pr > 0 && pr < next_item_size {
            // Leftover is smaller than the next item: it becomes dead space
            // unless another item fills it later; mild penalty scaled by gap.
            let gap = next_item_size - pr;
            score += (gap as f64).min(20.0) * 0.3;
        }
    } else {
        // Last item: prefer zero post-residual above all.
        if pr == 0 { score -= 20.0; }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // If this is the only bin that fits, using it avoids opening a new bin.
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh empty bin: base cost of opening a new bin, modulated by stream
        // progress and how crowded the current bin set is.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 18.0 + 10.0 * progress;
        // If existing bins are heavily fragmented (high mean residual), opening
        // a fresh bin is more attractive.
        if mean_residual > 40.0 {
            open_cost -= 8.0;
        }
        // If the item is large and would leave a harmonic residual, new bin is fine.
        if item_size % 10 == 0 && item_size >= 50 {
            open_cost -= 4.0;
        }
        // If only one bin fits and it's this new bin, it's mandatory anyway.
        if fitting_bins_count == 0 {
            open_cost -= 30.0;
        }
        score += open_cost;
    }

    // --- Mild crowding pressure: many open bins -> prefer filling existing ones ---
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Prefer bins whose residual is large relative to the item (good utilization),
    // but only mildly, so dead-space logic dominates.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in the stream.
        score += 20.0 + 3.0 * open_bins_count as f64 + 30.0 * progress;
        // But allow a new bin if current bin would leave a bad gap for the next item.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 35.0;
        }
    } else {
        // Mild penalty for spreading across many open bins.
        score += (open_bins_count as f64) * 0.8;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        // Placement leaves a gap the next item barely fits into but creates future dead space.
        score += 10.0;
    }

    // Prefer bins with residuals close to the item size (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.2;

    // Mean-residual coupling: avoid bins far below the mean (they hoard large gaps).
    if (bin_residual as f64) < mean_residual - 15.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect 2-step match: place here
        } else if diff <= 10.0 {
            score -= 40.0 - 2.0 * diff; // near match, graded
        } else {
            // penalize post-residual that can't host the next item
            if pr < nxt {
                score += 0.5 * (nxt - pr);
            } else {
                score += 0.2 * (pr - nxt);
            }
        }
    }

    // Compare post_residual against mean residual: creating a below-average
    // residual is good (tight packing); above-average is wasteful.
    let pr = post_residual as f64;
    score += 0.8 * (pr - mean_residual).max(0.0);
    score -= 0.4 * (mean_residual - pr).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage leaving tiny unusable dead space (unless it fits next item).
    if next_item_size == 0 || post_residual < next_item_size {
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Prefer tighter fits generally: reward high fill ratio of this placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill;

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when open bins are genuinely poor fits; becomes more attractive late
    // in the stream or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        score = 100.0
            + 0.3 * mean_residual
            + if next_item_size > 0 { 0.5 * next_item_size as f64 } else { 0.0 }
            - if fitting_bins_count == 0 { 30.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better, super-linear penalty on waste.
    let waste = post_residual as f64;
    score += 0.15 * (waste * waste) / bin_capacity as f64;

    // Penalize bins whose post-residual falls into a "dead zone" that few future items can use.
    // Dead zones: residuals in (0, 10) are unusable; small residuals below typical item sizes are poor.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild bonus proportional to how well it fills the remainder.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item will not fit here: penalize leaving a residual close to but below next size.
            let gap = (next_item_size as f64 - post_residual as f64).min(20.0);
            score += 0.5 * gap;
        }
    } else {
        // Last item: prefer closing bins out completely.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        // Extra mercy when the bin would be left with a large usable residual anyway.
        if post_residual >= 30 {
            score -= 10.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation into existing bins.
    if open_bins_count > 2 && mean_residual > 20.0 {
        let pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
        score -= 8.0 * pressure;
    }

    // Time horizon: early in the stream, be more willing to open fresh bins for good long-term structure;
    // late in the stream, pack tightly into whatever exists.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only for large items or early stream with big residual need.
        score -= 12.0 * item_size as f64 / bin_capacity as f64;
        score += 20.0 * progress; // late stream: opening new bins is costly
        // If existing bins are fragmented, a fresh bin can still be worthwhile early on.
        if mean_residual < 15.0 && progress < 0.5 {
            score -= 10.0;
        }
    } else {
        // Existing bin: late stream favors tighter packing.
        score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress);
    score += 18.0 * pr_norm * pr_norm * (0.5 + progress);
    score -= 12.0 * item_norm * (1.0 - progress);

    // Penalize dead space more as stream advances
    score += 10.0 * pr_norm.powi(3) * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // New-bin candidate: penalize early, allow late when residuals are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_norm = mean_residual / cap;
        score += 15.0 * (1.0 - progress) - 20.0 * mean_norm * progress;
        if next_item_size as f64 > pr {
            score -= 8.0;
        }
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 6.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - pr_norm);
    }

    // Mild penalty for too many open bins early on
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into modulo buckets.
    // Post-residuals that are "small but usable" (multiples of small classes)
    // are more valuable than awkward odd remainders.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 500.0;
    } else {
        // Harmonic class: how divisible is the leftover space?
        let class = if pr % 50 == 0 {
            0.0
        } else if pr % 25 == 0 {
            1.0
        } else if pr % 10 == 0 {
            2.0
        } else if pr % 5 == 0 {
            3.0
        } else {
            4.0
        };
        score += class * 12.0;

        // Very small leftovers (< 10) are dead space; penalize extra.
        if pr < 10 {
            score += 60.0 * (10 - pr) as f64;
        }

        // Lookahead coupling: if the next item fits exactly in post_residual,
        // this is an excellent chain placement.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 300.0;
            } else if next_item_size < pr {
                let slack = pr - next_item_size;
                // Reward tight-but-feasible next placements, penalize large slack.
                score -= 80.0 - slack.min(80) as f64;
                // Harmonic check on the chain residual after next item.
                let pr2 = slack;
                if pr2 == 0 {
                    score -= 150.0;
                } else if pr2 < 10 {
                    score += 30.0;
                }
            } else {
                // Next item won't fit here; leftover must survive another round.
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: residual == capacity means a fresh bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; made cheaper only when current bins
        // are crowded or this item is large (poor fit candidates).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 180.0;
        // Large items fragment bins less if placed fresh.
        if item_size >= 60 {
            new_bin_score -= 40.0;
        }
        // If open bins are on average nearly full, a new bin is natural.
        if mean_residual < 20.0 {
            new_bin_score -= 60.0;
        }
        // Early in the stream, opening bins is cheaper (more future use).
        new_bin_score -= 40.0 * (1.0 - progress);
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            new_bin_score += 50.0 * (fitting_bins_count as f64 - 2.0);
        }
        score = new_bin_score;
    } else {
        // Mild preference for filling fuller bins (best-fit flavor) with
        // harmonic modulation via integer division of residual.
        let div_class = (bin_residual / 25) as f64; // 0..4 quartile-ish class
        score -= div_class * 5.0;

        // Slight bonus when bin residual is close to item size (tight fit).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 20.0;
    }

    // Scale pressure: as stream progresses, be slightly more conservative
    // with residual waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest possible item
    // (unusable gaps) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Pressure from number of open bins: discourage opening new bins when
    // many bins are already open; encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin: apply open-bin pressure as a penalty.
        score += 20.0 + open_pressure;
        // Opening a new bin is only attractive if no existing bin fits well.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Existing bins get a mild bonus, stronger when this is the last fitting bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        score -= 5.0;
    }

    // Lookahead: if the next item can exactly use the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item cannot use this residual; penalize leaving moderately large gaps.
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (tighter bins) when the item fits well.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits exactly into post residual region: strong reward
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // Next item does NOT fit into this bin's post-residual: penalize dead space
    else if next_item_size > 0 && post_residual < next_item_size.min(100) {
        score += 30.0 + (next_item_size as f64 - post_residual as f64).min(60.0);
    }

    // Compare post_residual against mean residual: leaving too little vs average is bad
    if (post_residual as f64) < mean_residual * 0.35 {
        score += 40.0;
    } else if (post_residual as f64) > mean_residual * 1.5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize tiny unusable residuals (< 10, min item size)
    if post_residual < 10 {
        score += 60.0;
    }

    // Early in stream: mild preference to keep bins balanced
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // New-bin candidate: prefer it only when open bins would create heavy dead space
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is much larger than the item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: small post_residual is good, but near-zero waste on
    // an almost-full bin is excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    } else {
        score += 0.35 * post_residual as f64;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual {
            // Next item fits now but not after placement -> mild penalty.
            score += 4.0;
        }
        // If next item is large relative to capacity, prefer keeping big
        // residuals for it.
        let big_next = next_item_size as f64 / bin_capacity as f64;
        score += 6.0 * big_next * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly. Base new-bin score near its raw residual
    // (bin_capacity), with a mild penalty that decays as the stream grows.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - progress);
        // If many bins are open and residuals are plentiful, discourage new bins.
        score += 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 * 1.5 {
            score += 12.0;
        }
    }

    // Global state: when mean residual is low, preserve bins with large
    // residuals for future large items.
    if mean_residual < 20.0 && post_residual > 40 {
        score += 6.0;
    } else if mean_residual > 50.0 {
        // Plenty of slack overall: consolidate into fuller bins.
        score -= 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Slight preference to fill older/earlier-indexed bins is implicit via
    // residual; add small noise-free tie-break on residual squared.
    score += 0.001 * (post_residual as f64) * (post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Tight-fit reward: strongly favor small post_residual, amplified by progress
    let fit_ratio = post_residual as f64 / cap;
    score -= (1.0 - fit_ratio).powi(3) * 30.0 * (0.5 + progress);

    // Non-linear coupling of post_residual with stream progress
    score += fit_ratio * fit_ratio * (10.0 + 20.0 * progress);

    // Penalize bins far below mean residual (fragmentation risk)
    score += ((mean_residual - post_residual as f64).abs() / cap) * 8.0 * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 12.0 * (next_item_size as f64 / cap);
        } else {
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Slight preference for consolidating into fewer bins early on
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 18.0 - 14.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic classes: classify post_residual by residue class mod 10.
    // Small dead space (< 10, the minimum item size) is unusable -> heavily penalize.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Residue class mod 10 of post_residual: dead-space potential.
    let r = post_residual % 10;
    score -= (10 - r) as f64 * 0.8; // small bonus when residual is "round"

    // Integer-division thresholds: post_residual / 10 bucket.
    let bucket = post_residual / 10;
    score += bucket as f64 * 1.5; // larger leftover = more wasted space potential

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect chain
        } else if next_item_size <= post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post < 10 && nxt_post > 0 {
                score += 25.0; // chain would create dead space
            } else {
                score -= (post_residual - next_item_size) as f64 * 0.5;
            }
        } else {
            // next item can't use this residual: penalize proportional to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is penalized slightly by number of open bins and stream progress.
        score += 40.0 + 2.0 * open_bins_count as f64
            + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if the item is large and mean residual is small, new bin is reasonable.
        if item_size > 50 && mean_residual < item_size as f64 * 0.5 {
            score -= 55.0;
        }
    } else {
        // Reward using existing bins relative to mean residual (prefer emptier bins first).
        score -= 5.0 * (mean_residual - post_residual as f64).max(-20.0).min(20.0) / 10.0;
    }

    // Fraction-of-capacity harmonics: penalize leaving residual near awkward fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.05 && frac < 0.1 {
        score += 15.0; // dead zone: 5-10% leftover rarely reusable
    } else if frac >= 0.1 && frac <= 0.3 {
        score -= 6.0; // usable window for small items
    }

    // Tie-break: mildly prefer bins with larger residual to consolidate packing.
    score -= bin_residual as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for typical items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small relative slack).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
    } else {
        score += 1.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Slight progression normalization.
    score *= 1.0 + 0.1 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish match between post_residual and next_item_size (2-step lookahead)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 60.0; // perfect two-step match: chain items together
        } else {
            score += gap as f64 * 0.8;
            // partial credit if next item still fits after this placement
            if next_item_size <= post_residual {
                score -= 15.0;
            }
        }
        // chain of three: item + next item exactly fills bin
        if item_size + next_item_size == bin_residual {
            score -= 40.0;
        }
    } else {
        // last item: prefer tightest fill
        score -= 10.0;
    }

    // Penalize creating dead space below minimum item size (assume min ~1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward filling bins tightly relative to mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current item is huge and open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = open_bins_count as f64 / 10.0;
        // penalize new bins mildly; allow it when item is large and fits nowhere well
        score += 30.0
            + 20.0 * fragmentation
            - if item_size > bin_capacity / 2 { 25.0 } else { 0.0 }
            - 10.0 * progress;
        // if no existing bin fits well (post_residual huge relative to item), new bin less bad
        if post_residual as f64 > 0.7 * bin_capacity as f64 && next_item_size > post_residual {
            score -= 35.0;
        }
    }

    // mild preference for bins with smaller residual overall (tight packing)
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that leave little dead space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that is too small for typical future items
    // (fragmentation penalty, non-linear in post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily (chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 0.35 * next_item_size as f64;
        } else {
            // Next item can't use this residual: penalize proportionally to wasted potential.
            score += 0.25 * (next_item_size as f64 - post_residual as f64).min(bin_capacity as f64);
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mildly penalize so competition sorts by fit quality.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: empty bin should win only when the fit in existing
    // bins is poor. Give the empty bin a moderate baseline penalty, softened when
    // mean residual across open bins is low (bins are full-ish) or many items remain.
    if bin_residual == bin_capacity {
        score += 25.0;
        score -= 20.0 * (1.0 - mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer filling bins with larger residuals when global residuals are high
    // (reduce spread of open-bin residuals toward fragmentation).
    let res_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * res_gap;

    // Slight preference for bins whose residual is just above the item
    // (best-fit shaping beyond raw post_residual).
    let slack = bin_residual as f64 - item_size as f64;
    if slack >= 0.0 {
        score += 0.05 * slack;
    }

    // Mild penalty for opening many bins early.
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, with non-linear (quadratic/cubic) coupling to progress
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);
    score += 25.0 * norm_pr * norm_pr * norm_pr * progress;

    // Reward tight fits: smooth function of post_residual
    score -= 60.0 * (-pr / 15.0).exp();

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 20.0 * (1.0 - nxt / cap) * (1.0 + progress);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: avoid opening a new bin when only one bin fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += 5.0 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // residue classes mod 10 (typical item granularity) and mod 25.
    let class10 = (post_residual % 10) as f64;
    let class25 = (post_residual % 25) as f64;

    // Prefer leftovers whose class is "usable" by typical small items.
    // A residual of exactly 0 is perfect; small nonzero remainders are dead space.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Penalize awkward residue classes (dead space that nothing small fits).
        score += class10 * 0.8;
        score += class25 * 0.4;
    }

    // Integer-division thresholds on post_residual: how many "medium" chunks fit.
    let medium_slots = post_residual / 25;
    score -= medium_slots as f64 * 3.0;

    // Lookahead coupling: if the next item fits the post residual exactly,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let nxt_class = next_item_size % 10;
            // reward when next item's harmonic class aligns with residual class
            if nxt_class == post_residual % 10 {
                score -= 12.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item cannot use the leftover: mild penalty for hoarding space
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the item is large or fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.5 {
            score -= 10.0 + 20.0 * (fill_frac - 0.5);
        } else {
            score += 15.0 - 20.0 * fill_frac;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.2;

    // Prefer bins tighter than the mean (best-fit flavor with harmonic twist).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=10)
    // are effectively unusable "waste"; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward leaving a gap that the lookahead item could fill.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap just barely smaller than the next item (near-miss waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid fragmenting further;
    // opening a new bin (residual == capacity) should be discouraged mildly.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        // Reward using bins that are already quite full (small residual before placement).
        score -= 10.0 * (1.0 - (bin_residual as f64) / (bin_capacity as f64));
    }

    // Prefer bins below the mean residual (tighter bins) slightly.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 25.0 - 1.5 * leftover;
    }

    // Penalize post_residual that cannot fit the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Relative to mean residual: prefer bins tighter than average when fit is good.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling nearly-full bins (small absolute residual).
    score += 0.2 * post_residual as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference against opening a brand-new bin when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0;
    }

    // Late-stream consolidation: tighten selection as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (100.0 - post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear boost
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space: residuals too small to be useful
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: strongly favor bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = post_residual as f64 / (post_residual as f64 + next_item_size as f64);
        score -= 25.0 * chain_fit;
    } else if next_item_size > 0 {
        // Penalize leaving a gap that blocks the next item
        score += 10.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let late = step_index as f64 / (total_items.max(1) as f64);
        // penalize new bins when open bins have plenty of room
        score += 45.0 * pressure + 20.0 * (1.0 - late);
        // but allow new bins when item is large and mean residual is small
        score -= 20.0 * (item_size as f64 / 100.0) * (1.0 - pressure);
    } else {
        // Slight penalty for very full bins to avoid wasting near-perfect fits on small items
        if (bin_residual as i64 - item_size as i64) > 0 && item_size < 20 {
            score += 5.0;
        }
    }

    // Spread load: mildly prefer bins with residual near mean (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: later in stream, prefer closing bins tightly (favor exact fits)
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * t * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), with non-linear shaping.
    let mut score = (x * x * (3.0 - 2.0 * x)) * 60.0 + pr * 0.35;

    // Non-linear interaction of post residual with stream progress:
    // early on, tolerate slack (keep bins flexible); late, demand tight packing.
    let slack_bias = (0.5 - progress) * (x * x) * 40.0;
    score += slack_bias;

    // Smooth coupling with mean residual: avoid bins far from the fleet average.
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * 25.0;

    // Penalize post residual that cannot fit the next item (dead space), smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (nx - x).max(0.0);
        score += gap * gap * 90.0;
        // Reward when next item fits exactly-ish into resulting residual.
        let fit = 1.0 - (nx - x).abs();
        if fit > 0.0 {
            score -= fit * fit * 15.0;
        }
    } else {
        // Last item: strongly prefer minimal post residual.
        score += x * x * 50.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - progress);
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only when
    // open bins are genuinely poor fits; penalty grows with progress.
    if bin_residual == bin_capacity {
        score += 55.0 + 40.0 * progress;
        // But if next item is huge and would leave this bin unusable anyway,
        // opening fresh is fine: soften penalty.
        if next_item_size as f64 > 0.8 * cap {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "dead zones".
    // Small post_residual with residue near 0 is valuable (reusable by common small items).
    let residue = post_residual % 10;
    if post_residual > 0 {
        // Penalize residuals whose class is hard to fill (odd, prime-ish residues)
        match residue {
            0 => score -= 6.0,                 // perfectly reusable class
            1 | 3 | 7 | 9 => score += 4.0,     // awkward odd classes
            5 => score += 1.0,                 // moderate
            _ => score += 2.5,                 // even but not 0
        }
    } else {
        // Perfect closure is excellent
        score -= 15.0;
    }

    // Integer-division thresholds: how many "standard small items" (size 10) fit after placement
    let slots = post_residual / 10;
    score -= slots as f64 * 2.0;

    // Tight fit reward: post_residual small relative to item size means dense packing
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item cannot use this residual: penalize large leftover
            score += (post_residual as f64) * 0.03;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: neutral-ish baseline so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score = 45.0
            + (post_residual as f64) * 0.1
            - (open_bins_count as f64).sqrt() * 2.0
            + (item_size as f64) * 0.1;
        // If item is huge relative to typical residual, prefer fresh bin
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 8.0; // next item pairs well with fresh bin remainder
        }
    }

    // Mild stream-phase adjustment: pack tighter early, allow slack late
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // for typical items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Pressure from number of open bins: prefer using existing bins
    // when many are already open (avoid bin proliferation).
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor filling the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // New-bin candidate (pristine bin): make it attractive only when
    // no open bin offers a decent fit. A fresh bin has full residual,
    // so its base score is high; subtract a discount scaled by stream
    // progress and how poor existing fits are (large mean residual
    // means open bins are already fragmented).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_res = mean_residual;
        // If mean residual across open bins is small (bins are tight),
        // opening a new bin is reasonable; discount accordingly.
        let discount = 30.0 + 40.0 * (1.0 - mean_res / bin_capacity as f64).min(1.0);
        score -= discount * (0.5 + 0.5 * progress);
        // Slight penalty to keep new bins from being opened too eagerly
        // when plenty of bins are open with usable space.
        score += open_bins_count as f64 * 0.5;
    }

    // Mild preference for bins whose residual is close to the item
    // (best-fit flavor beyond raw post_residual).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to capacity (wasted space is worse early).
        score += (post_residual as f64 / bin_capacity as f64) * 30.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Bonus scaled by how well the next item fills the remaining space.
            let fill_next = next_item_size as f64 / post_residual as f64;
            score -= fill_next * 20.0;
        } else {
            // Post-residual too small for next item: penalize proportionally to dead space.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Compare against mean residual: prefer bins with residuals close to item
    // needs (tight fits), penalize bins already far above the mean (fragmented).
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.15;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 60.0;
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 50.0; // large items are fine in fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Slight stream-phase adaptation: early on, keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative penalty grows superlinearly
    let tight = post_residual as f64 / cap;
    score += 6.0 * tight * tight;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small dead-space threshold: residual that few items can use
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    let openness = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.05 * openness;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here; slight penalty unless post_residual tiny
            score += 2.0 + 0.1 * (post_residual as f64);
        }
    }

    // New-bin candidate logic: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / cap;
        // opening a new bin keeps it fully available; penalize unless fit is loose
        score += 12.0 * (1.0 - fit_quality);
        if fitting_bins_count > 0 {
            score += 10.0; // opening new bins when alternatives exist is costly
        }
        if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
            score -= 5.0; // fresh bin can host next item too
        }
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 24.0 * norm_pr * norm_pr * (1.0 + 2.0 * p2 + 3.0 * p3);
    // Penalize large dead space relative to mean residual
    score += 6.0 * (pr - mean_residual).abs() / cap;
    // Reward tight fits: subtract when item fills most of the bin
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;
    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) as f64 / cap;
            score -= 14.0 * (1.0 - slack) * (1.0 + 0.5 * progress);
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }
    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }
    // Mild penalty for opening new bins late in the stream
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 8.0 + 10.0 * progress - 4.0 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues divisible by common
    // item sizes (10, 20, 25, 50) are more reusable than odd dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward residuals in "friendly" classes: multiples of 10 or 25.
    let friendly = post_residual % 10 == 0 || post_residual % 25 == 0;
    if friendly {
        score -= 6.0;
    } else {
        score += 4.0; // penalize awkward residues
    }

    // Dead-space cliff: residuals too small for the minimum item (assume ~10)
    // are nearly unusable; penalize proportionally to how deep in the cliff.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 { score -= 8.0; } else { score += slack as f64 * 0.15; }
        } else {
            // next item cannot follow here; mild penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current bin's post-fit is poor or item is large
    // relative to remaining space.
    if bin_residual == bin_capacity {
        // Base preference for fresh bin when item is bulky.
        score = cap - item_size as f64; // post_residual of empty bin
        let tight = (item_size as f64 / cap) > 0.6;
        let many_open = open_bins_count as f64;
        let mean_r = mean_residual;
        // Prefer new bin if open bins are on average too full for this item class.
        if tight && mean_r < item_size as f64 * 1.2 {
            score -= 20.0;
        }
        // Late in stream, consolidate instead of opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 25.0;
        }
        // Many open bins with slack: prefer reusing one.
        if many_open > 3.0 && mean_r > item_size as f64 {
            score += 15.0;
        }
    }

    // Slight preference for fuller bins overall (best-fit flavor) modulated
    // by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (cap - post) * 0.05 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item (1..100 unknown dist).
    // Treat gaps < 10 as near-wasted; harshly penalize.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits: post_residual small but usable.
    if post_residual > 0 && post_residual < 30 {
        score -= 8.0;
    }

    // Dead space penalty relative to capacity: large leftover waste is bad.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Open-bins pressure: prefer reusing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 10.0;
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to gap mismatch.
        score += (next_item_size as f64 - post_residual as f64) * 0.2;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) to keep large gaps open.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain fit (post_residual == next_item_size)
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 45.0;
        } else if post_residual as u32 > next_item_size {
            let slack = (post_residual as u32 - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            // penalize leftover that is small/unusable for next item
            if slack < 10.0 {
                score += 12.0 * (10.0 - slack);
            }
        } else {
            // next item cannot chain into this bin; penalize proportionally
            score += 8.0;
        }
    } else {
        // last item: prefer tightest fill
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins below-average residual (tight bins) when fit is good
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating tiny dead space (unusable fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward perfect fills
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        // default penalty so open bins with reasonable fits win
        score += 15.0;
        // if many open bins already, opening new is more acceptable
        score -= (open_bins_count as f64).sqrt() * 2.0;
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual after placement is small.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: post-residual that is too small to hold typical items is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item can still fit after this placement, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Placement strands the next item; penalize proportionally.
            score += 10.0 + 0.3 * next_item_size as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a fresh bin is attractive only for large items
    // or when existing bins have poor aggregate fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_fit = (mean_residual - item_size as f64).abs() / bin_capacity as f64;
        // Penalize new bins generally, but discount when item is large or fits are bad.
        score += 60.0 - 70.0 * large_item - 40.0 * poor_fit - 10.0 * progress;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0; // fresh bin keeps full flexibility for lookahead
        }
    }

    // Mild preference for bins already below mean residual (consolidation).
    if bin_residual < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Late-stream consolidation: fewer wasted bins near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr * (1.0 + 0.6 * progress * norm_pr + 0.9 * progress * (1.0 - progress) * 4.0);

    // Penalize dead space more as stream advances
    let dead = norm_pr * norm_pr * (1.0 + progress);

    // Lookahead: reward leaving room for the next item
    let lookahead = if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            -0.35 * ni * (1.0 - norm_pr)
        } else {
            0.5 * (ni - pr)
        }
    } else {
        0.0
    };

    // Last-chance bonus: strongly prefer using the only fitting bin
    let last_chance = if fitting_bins_count == 1 && bin_residual < bin_capacity {
        -25.0
    } else {
        0.0
    };

    // Slight preference for consolidating when many bins are open
    let consolidation = -0.05 * open_bins_count as f64 * (1.0 - norm_pr);

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is bad
    let new_bin = if bin_residual == bin_capacity {
        10.0 + 20.0 * progress * (1.0 - item_size as f64 / cap)
    } else {
        0.0
    };

    poly + 40.0 * dead + lookahead + last_chance + consolidation + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize "dead space"
    // that is too small for the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 50.0; // unreachable gap
    }

    // Harmonic class of the residual: residuals in "nice" classes
    // (multiples of 10 or 25) are more reusable by future items.
    let pr = post_residual;
    let nice = (pr % 10 == 0) || (pr % 25 == 0) || (pr % 20 == 0);
    if nice {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else {
        score += 2.5; // awkward residual class
    }

    // Integer-division thresholds: does post_residual fit a "half-class" item?
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr >= half {
        score -= 4.0; // residual can still host a big item
    } else if pr >= quarter {
        score -= 1.5;
    } else if pr > 0 {
        score += 4.0; // sub-quarter residual: likely dead space
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chain a harmonic pair).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // reward if post-residual of the pair stays in a nice class
            if (pr - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
            score += slack * 0.15;
        } else {
            // next item won't fit here; mild penalty if this was the only fitting bin
            if fitting_bins_count == 1 {
                score -= 10.0; // last-chance bin: use it rather than open new
            }
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here would be very poor.
    if bin_residual == bin_capacity {
        // Opening a new bin: score it as capacity minus potential synergy.
        score = (bin_capacity as f64) * 0.55
            - if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 5.0 } else { 0.0 }
            + (open_bins_count as f64).ln().max(0.0) * 3.0;
        // If an existing bin gives a near-perfect fit, don't open new.
        if post_residual <= 2 && bin_residual == bin_capacity {
            score += 60.0;
        }
    }

    // Last-chance bonus: this is the only open bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; placing here consolidates waste.
    let res_frac = (bin_residual as f64) / (bin_capacity as f64);
    let mean_frac = mean_residual / (bin_capacity as f64);
    if res_frac < mean_frac {
        score += (mean_frac - res_frac) * 20.0;
    } else {
        score -= (res_frac - mean_frac) * 6.0;
    }

    // Stream progression: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 0.0 + progress * (post_residual as f64) * 0.05;

    // Slight preference to fill bins with many prior items (fewer open bins).
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // for future items (sizes >= 1, typically >= 10), so penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // moderately awkward gap
    }

    // Reward exact / very tight fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
        // But if next item could use the fresh bin's large residual, soften.
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) >= mean_residual {
            score -= 5.0;
        }
    } else {
        // Slight preference for filling existing bins as stream progresses.
        score -= 0.5 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer bins whose residual is close to the item (best-fit shaping).
    score += 0.1 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs();

    // If the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 3.0; // next item can't reuse the gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space: too small for any item (sizes >= 1... keep mild since min size unknown)
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional closeness of next fit
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            if slack < 10.0 {
                score -= 15.0; // near-exact chain
            }
        } else {
            // next item cannot fit here; post_residual becomes potential dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.15 * gap;
        }
    } else {
        // last item: just minimize post_residual strongly
        score *= 1.2;
    }

    // Relative-to-mean coupling: bins with residual below mean are "sparser" fits;
    // filling a below-mean bin is good (reduces fragmentation).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.35 * (mean_residual - res);
    } else {
        score += 0.25 * (res - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is huge waste).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual > 60 {
            score += 30.0; // but avoid stuffing a big bin leaving huge waste
        }
    }

    // New-bin candidate handling: only attractive when current fit is bad
    // (large post_residual) or stream is early with few bins open.
    if bin_residual == bin_capacity {
        // neutral base for fresh bin = item_size leftover, but discourage
        // opening new bins when a decent fit exists.
        score += 20.0;
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 35.0 * progress; // late stream: fresh bin may consolidate better
        }
    }

    // Mild preference to keep many small open bins consolidated as stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fit_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        }
        // Penalize leaving residual that is just barely too small for the next item.
        if post_residual < next_item_size && post_residual >= (next_item_size as f64 * 0.6) as u32 {
            score += 6.0;
        }
    }

    // Time horizon: early in the stream, be more conservative with new bins;
    // late in the stream, prefer filling existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fit_ratio;

    // Global state coupling: many open bins -> favor existing bins over new ones.
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin.
        let new_bin_penalty = 15.0 + 2.0 * open_bins_count as f64 + 10.0 * (1.0 - progress);
        score += new_bin_penalty;
        // If no open bin fits and the item is large, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mean residual coupling: high average residual means space is plentiful;
    // prefer bins whose residual is below the mean (more filled).
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score += 4.0;
    } else if bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty for very large post residual waste relative to capacity.
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) coupling
    let mut score = post + (post / cap).powi(2) * 20.0 + (post / cap).powi(3) * 30.0;

    // Reward tight fits (small post_residual relative to item) more strongly
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * 15.0;

    // Smooth stream-progress coupling: later in the stream, penalize large residuals harder
    // (less opportunity to fill them), favoring consolidation.
    score += (post / cap) * progress * 25.0;

    // Interaction: item size vs mean residual — prefer bins whose residual is "just right"
    let mean_r = mean_residual / cap;
    let ideal = (item / cap).powf(0.5);
    let mismatch = (mean_r - ideal).abs();
    score += mismatch * 10.0 * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits the post-residual exactly-ish, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            score -= (1.0 - slack / cap) * 12.0;
        } else {
            // post residual too small for next item: mild penalty unless tiny
            score += (post / cap) * 8.0;
        }
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so we only open
    // when no open bin fits well; penalty decays as stream progresses.
    if bin_residual == bin_capacity {
        let base = 55.0 + 20.0 * (1.0 - progress);
        // If many bins already open, opening another is costlier
        score += base + (open_bins_count as f64).sqrt() * 5.0;
    }

    // Slight penalty proportional to number of open bins (encourage consolidation)
    score += (open_bins_count as f64) * 0.5 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it land in?
    let frac = post_residual as f64 / cap;
    // Integer division thresholds on post_residual (harmonic classes: 0, 1-9, 10-19, ... )
    let class = (post_residual / 10) as f64;
    score += class * 2.0;

    // Perfect fits are golden: eliminate residual entirely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space (<10) is nearly perfect; medium dead space is worst.
    if post_residual > 0 && post_residual < 10 {
        score -= 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 25.0; // unusable for typical small items
    }

    // Modulo arithmetic on residual: residuals divisible by common item sizes are reusable.
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
    if reusable {
        score -= 15.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + (next_item_size as f64) * 0.2;
            // Harmonic bonus: next item exactly consumes a harmonic chunk
            if post_residual % next_item_size.max(1) == 0 {
                score -= 20.0;
            }
        } else {
            score += 12.0; // next item won't fit here; dead space risk
        }
    } else {
        // Last item: just fill as much as possible.
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: keep it competitive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when mean residual is small (open bins nearly full) or early stream.
        let fragmentation = mean_residual / cap;
        score = 45.0 - 40.0 * fragmentation - 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    } else if mean_residual < cap * 0.15 && post_residual > 0 {
        // Open bins are nearly full; avoid leaving scraps in them.
        score += 10.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    // Fraction-based tiebreak: prefer leaving residual in low harmonic fraction bands.
    score += frac * frac * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item are wasted.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 15.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 10.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item is large and this placement leaves too little room,
    // forcing a new bin anyway.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // allow opening new bins for better fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (1.0 + progress)) * 0.8;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score = 30.0 + pressure;
        // Opening a new bin is attractive when no open bin fits well.
        if post_residual == bin_capacity {
            if fitting_bins_count == 0 {
                score -= 100.0; // no alternative: must open new bin
            }
        }
    } else {
        score += pressure * 0.5;
    }

    // Mean-residual coupling: penalize placing into a bin whose residual deviates
    // far above the mean (keeps residuals uniform, easier future packing).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.1 * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement is ideal — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize proportionally to wasted post space.
            score += 0.5 * post_residual as f64;
        }
    }

    // Prefer bins tighter than the mean residual (good fits); penalize loose bins.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0 + mean_residual * 0.5;
    }

    // Early in the stream, be slightly more willing to open bins (better structure later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that cannot fit the next item (lookahead k=2)
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // dead space: next item can't use it
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // next item fits nicely here: reward
            score -= 2.0;
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a base penalty so we prefer
    // existing bins unless the fit is poor
    if bin_residual == bin_capacity {
        score += 8.0;
        // opening new bin is attractive if it would keep a large flexible residual
        // and existing bins are fragmented (high mean residual spread)
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= fragmentation * 0.3;
        // early in stream, new bins are cheap to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
        // if next item is huge, prefer a fresh bin with room for it
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Slight preference for bins tighter than average (concentrate filling)
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Reward low post_residual non-linearly (tight packing)
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = x * (1.0 + 2.0 * x * x);

    // Smooth interaction: as stream progresses, tighten tolerance for leftover space
    score += 3.0 * progress * x * (1.0 - x);

    // Penalize dead space relative to mean residual of open bins (smooth coupling)
    score += 0.5 * (x - mean_residual / cap).abs();

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_next = pr >= n;
        let gap = ((pr - n).abs()) / cap;
        let kernel = (-8.0 * gap * gap).exp();
        if fit_next {
            score -= 4.0 * kernel * (1.0 - progress * 0.5);
        } else {
            score += 1.5 * kernel * x;
        }
    }

    // Last-chance bonus: strongly favor using a nearly-saturated fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - x);
    }

    // Mild penalty for spreading across many open bins (encourage consolidation)
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make empty bin attractive only when it avoids a bad fit
    if bin_residual == bin_capacity {
        score = x * (1.0 + 2.0 * x * x) + 1.0 - 2.0 * item_size as f64 / cap + 0.05 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "unusable" classes (small slivers) get heavily penalized.
    let pr = post_residual;
    let class = pr / 10; // integer division: harmonic decile class
    match class {
        0 => score += 60.0,               // dead space 0..9
        1 => score += 25.0,               // 10..19 hard to fill
        2 => score -= 10.0,               // 20..29 decent
        3 => score -= 18.0,               // 30..39 good
        4 => score -= 22.0,               // 40..49 sweet spot
        5 => score -= 20.0,               // 50..59
        6 => score -= 14.0,               // 60..69
        7 => score -= 6.0,                // 70..79
        _ => {}                            // 80..100 nearly full bin, fine
    }

    // Exact fit reward
    if pr == 0 {
        score -= 100.0;
    }

    // Modulo-4 harmonic class of post_residual vs next item: perfect pairing bonus.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if pr >= nxt {
            let pair_waste = pr - nxt;
            // prefer leaving exactly next_item_size
            let mod_pen = (pair_waste % 4) as f64;
            score -= 12.0;
            score += mod_pen * 2.0;
            score += pair_waste as f64 * 0.3;
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += (nxt - pr) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make it attractive only when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = cap - item_size as f64; // post_residual of empty bin
        score += 15.0;                  // inherent cost of opening a bin
        if fitting_bins_count == 0 {
            score -= 50.0;              // no alternative, must open
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;               // fresh bin can host next item too
        }
    }

    // Late-stream consolidation: prefer tightening existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.5;

    // Slight preference for bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // Many open bins: encourage filling existing ones rather than spreading.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 30.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Moderate gaps that can still fit the next item are mildly rewarded.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += next_item_size as f64 * 0.5;
    }

    // Open-bin pressure: prefer reusing bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New empty bin candidate: only attractive when current item is large
    // relative to residual or fit is hopeless elsewhere.
    if bin_residual == bin_capacity {
        score += 60.0;
        if item_size > 70 {
            score -= 55.0;
        }
    }

    // Prefer bins with residual close to the item (tight fit).
    score += (bin_residual - item_size) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: less post residual relative to capacity is better.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: strongly reward bins where the next item
    // exactly fills the post residual; penalize if next item cannot fit.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin becomes exactly full
        } else if next_item_size <= post_residual {
            // reward proportional to how much of the post residual the next item consumes
            let fill = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 25.0 * fill;
        } else {
            // next item cannot use this bin's leftover: dead space penalty
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 * (waste / 100.0).min(1.0);
        }
    }

    // Compare post residual against mean residual of open bins: prefer bins
    // whose leftover ends up below average (concentrating waste).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Opening a new bin is only attractive when the item leaves a large,
    // reusable residual or when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral baseline, penalize slightly so it is
        // chosen only when open bins score poorly (large waste there).
        score += 10.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = tightness < 0.5;
        if bad_fit && fitting_bins_count > 0 {
            score -= 12.0 + 10.0 * (1.0 - progress);
        } else {
            score += 35.0;
        }
    }

    // Global residual pressure: prefer bins below mean residual (more filled)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference to spread across fewer bins when many are open
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    // Late in stream: prioritize closing bins (avoid many small residuals)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post residual (tight fit), with stream-dependent weight.
    let mut score = pr * (0.9 + 0.6 * progress * progress);

    // Non-linear penalty for dead space: small post residuals are valuable, large ones wasteful.
    score += 40.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits more as stream progresses (consolidation).
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead coupling: favor bins whose post residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 10.0 * ((nxt - pr) / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Crowd penalty: many open bins -> prefer filling existing ones.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_item);

    // Deviation from mean residual: prefer bins below mean (fill fuller bins).
    score += 0.15 * (mean_residual - pr);

    // New-bin candidate: only attractive when current bin is a very poor fit.
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * (1.0 - norm_item) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exactness of the fit.
    // Perfect fit (post_residual == 0) is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: leftover that can't serve typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Modulo classes: leftover that is a multiple of common small sizes
    // (10, 20, 25, 50) remains usable — reward those harmonics.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 8.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Harmonic bonus: leftover can be split into two next-size chunks.
            if post_residual >= 2 * next_item_size {
                score -= 6.0;
            }
        } else {
            // Leftover too small for the next item — dead space risk.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the
    // current fit is poor or the stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = item_size as f64 / cap;
        // A fresh bin is attractive only for large items or late in the stream.
        score += 45.0 - 30.0 * fit_quality - 15.0 * progress;
        // If many bins are open and mean residual is high, prefer reusing.
        score += (open_bins_count as f64).ln().max(0.0) * 5.0;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score -= (bin_residual as f64 / cap) * 3.0;

    // Small tie-break by mean residual alignment.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residual gaps are the worst
    // outcome (wasted capacity that few future items can use).
    if post_residual > 0 {
        // Items are >= 1 and up to 100; treat gaps below ~15 as "dead space".
        if post_residual < 15 {
            score += 60.0 * (15.0 - post_residual as f64) / 15.0;
        }
        // Perfect fit bonus.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Coupling: dead space is more tolerable when the bin is a "last chance"
    // (only fitting bin) — penalize alternatives less here.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; opening a new bin is penalized via its residual == capacity.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure.
        score += 30.0 + 8.0 * pressure;
        // Late in the stream, opening new bins is relatively cheaper than
        // fragmenting old ones (fewer future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If the next item is small, a fresh bin wastes little; slight discount.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 10.0;
        }
    } else {
        // Reward tight fits relative to mean residual of open bins.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Lookahead: if next item would fit the resulting gap exactly, bonus.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: minimal waste
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.6;

        // Exact lookahead match is a strong bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }

        // Chain potential: post_residual can hold next item plus a small remainder
        if post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 8.0;
        }
    }

    // Penalize tight fits that leave dead space below the minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Relative-to-mean residual coupling: prefer bins with residuals below mean
    // (filling the emptiest bins first keeps a spread of usable residuals)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would
    // leave a large, unusable residual and lookahead doesn't match
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Late-stream bias: consolidate as the stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Slight preference for denser bin sets when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that is too small for the smallest plausible item (1..100 stream),
    // but only mildly since tiny items may appear.
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item would fit exactly in the post residual,
    // big reward; if next item is large and post residual is awkward, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let nxt_tight = nxt / post_residual.max(1) as f64;
            score -= 12.0 * nxt_tight;
        } else {
            // wasted residual relative to next item's needs
            score += 5.0 * (1.0 - post_residual as f64 / nxt.min(bin_capacity as f64));
        }
    }

    // Compare against mean residual: prefer bins with residual below mean
    // (concentrate filling of fuller bins), keeping emptier bins flexible.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 8.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Bin proliferation pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 15.0 * open_bins_count as f64 * (1.0 - progress);
        // But if the fit in any open bin is terrible (huge leftover), allow new bin:
        // handled implicitly since bad fits get high post_residual scores.
    }

    // Slight time decay: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear squashing.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: early on, tolerate residual slack;
    // later, penalize wasted space more aggressively (quadratic growth).
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress * progress);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: bonus if the next item fits the post-residual well.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
        } else {
            // Next item cannot follow into this bin: penalize dead space creation.
            score += 6.0 * norm_pr * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty when this bin's residual deviates from the mean residual
    // (avoid fragmenting many similar bins).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight penalty for contributing to bin proliferation early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    if post_residual == 0 {
        score -= 2.0 * cap; // perfect fit
    } else {
        // Harmonic class of post_residual: dead space in low classes is worse.
        let pr = post_residual as f64;
        let class = (post_residual / 10).min(9); // 0..9 decade class
        // Dead-space penalty grows quadratically for small residuals.
        score += (10.0 - class as f64) * (10.0 - class as f64) * 0.4;

        // Modulo arithmetic on post_residual: residuals that are multiples of
        // small item sizes (e.g. %5==0) remain reusable -> reward.
        if post_residual % 5 == 0 {
            score -= 3.0;
        }
        if post_residual % 10 == 0 {
            score -= 3.0;
        }
        if post_residual % 20 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead: if next item fits in post_residual, this placement chains well.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + (next_item_size as f64) * 0.05;
        // Extra bonus if next item exactly fills the bin afterwards.
        if next_item_size == post_residual {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item fits this bin but not after our placement: mild penalty.
        score += 2.0;
    }

    // Last chance: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // fit is very poor and many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 0.35 * cap;
        if poor_fit && open_bins_count > 0 && mean_residual < 0.3 * cap {
            score -= 10.0 + 10.0 * progress;
        } else {
            score += 12.0; // default: prefer existing bins
        }
    }

    // Slight preference for fuller bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are highly undesirable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open,
    // and prefer opening new bins when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with below-mean residual (keeps residuals balanced,
    // preserving larger gaps for future items).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when it genuinely beats reuse
    // (e.g., large item that would wreck a nearly-full bin).
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if pr >= nxt {
            // Perfect chain: next item exactly fills this bin afterwards.
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff < 5.0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            score += 0.5 * (nxt - pr);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let mr = mean_residual;
    if mr > 0.0 {
        score += 0.3 * (pr - mr);
    }

    // Penalize creating tiny unusable dead space (hard-to-fill fragments).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let best_fit_bonus = if next_item_size > 0 && (item_size as f64 + next_item_size as f64) <= bin_capacity as f64 { 15.0 } else { 0.0 };
        score += 45.0 + best_fit_bonus
            + 0.5 * open_bins_count as f64
            + (step_index as f64 / total_items.max(1) as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual.max(1.0);
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize very small post_residual only if it's nonzero dead space; exact fit is great.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 15.0; // tiny dead space is nearly useless
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus;
    // if next item can't fit post residual, mild penalty (wasted pairing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 35.0;
        } else if (nxt as u32) > post_residual {
            score += 8.0;
        } else {
            let pair_waste = post_residual as f64 - nxt;
            score -= 10.0 * (1.0 - pair_waste / cap);
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current bin fit is poor (large post_residual) or this bin is crowded relative
    // to the fleet mean.
    if bin_residual == bin_capacity {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early in stream: new bins are cheap; later: conserve, prefer filling.
        score += 20.0 + 30.0 * t;
        // If many bins are open with large mean residual, opening another is wasteful.
        score += (open_bins_count as f64) * 1.5 + mean_residual * 0.2;
        // But if the item is large (won't pair well), a fresh bin is more acceptable.
        score -= (item_size as f64) * 0.3;
    }

    // Slight preference for bins whose residual deviates below the mean (consolidation).
    score += 0.1 * (residual - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, non-linearly coupled with progress.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Penalize dead space quadratically: small residuals that are hard to fill.
    let dead = norm_pr * norm_pr * (norm_pr - 0.5) * cap;
    score += 2.0 * dead;

    // Smooth interaction: reward near-perfect fits more strongly later in stream.
    let fit_quality = 1.0 - norm_pr;
    score -= (item_size as f64) * fit_quality * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let d = (pr - n) / cap;
        let kernel = (-d * d).exp();
        score -= 6.0 * kernel;
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 8.0;
    }

    // Mild penalty when many bins are open relative to stream progress (encourage consolidation).
    let density = open_bins_count as f64 / (total_items.max(1) as f64);
    score += 5.0 * density * (1.0 - progress) * (1.0 - progress);

    // Alignment with mean residual: penalize bins far from mean (smooth coupling).
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev * cap * (0.5 + progress);

    // New-bin candidate: penalize slightly, but relax late when residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 3.0 - 4.0 * progress * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large" residue classes (still reusable by typical items) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward keeping post_residual in harmonic classes divisible by common sizes.
    if post_residual > 0 {
        let class = post_residual % 10;
        if class == 0 {
            score -= 12.0; // perfectly aligned leftover
        } else if class <= 5 {
            score -= 4.0;
        } else {
            score += 6.0; // awkward sliver class
        }
    }

    // Penalize dead space that no plausible item can fill.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Big-fit bonus: filling a bin almost exactly is excellent.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let fill_frac = item_size as f64 / cap;
        score -= fill_frac * 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // next item strands this residue
    }

    // New-bin candidate handling: only open a new bin when current bin would
    // leave a very small residue or when the system is lightly loaded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = post_residual as f64;
        score += 30.0; // default: prefer existing bins
        if pr < 10.0 && pr >= 0.0 && bin_residual != bin_capacity {
            // unreachable for new bin, kept for symmetry
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if next_item_size as f64 > cap * 0.5 && progress < 0.5 {
            score -= 5.0;
        }
        let _ = tight;
    }

    // Mild pressure toward consolidating into fewer bins when residuals are high.
    let mean_gap = mean_residual - pr;
    if mean_gap > 0.0 {
        score += mean_gap * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (dead space zone: 1..=15)
    if post_residual > 0 && post_residual <= 15 {
        score += (16 - post_residual as i32) as f64 * 3.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Tight fit reward: fraction of residual consumed
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= fill_frac * 5.0;

    // Open-bin pressure: discourage scattering across many bins slightly
    score += (open_bins_count as f64) * 0.15;

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    // Prefer bins below mean residual (loose bins) for large items
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 6.0 + (open_bins_count as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (small dead space).
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual <= 2 {
        score -= 60.0 + 30.0 * fit_ratio;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 50.0;
        } else if gap <= 5.0 {
            score -= 20.0;
        } else if next_item_size as f64 > post_residual as f64 {
            // Next item won't fit here; mild penalty for wasting residual.
            score += gap * 0.15;
        } else {
            score += gap * 0.05;
        }
    } else {
        // Last item: minimize dead space aggressively.
        score += post_residual as f64 * 0.5;
    }

    // Penalize bins far below mean residual (fragmented leftovers),
    // reward bins with above-average residual for big items.
    if item_size as f64 > mean_residual * 0.7 {
        score -= 10.0 * (bin_residual as f64 - mean_residual).max(0.0) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item
    // is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0
            || (fitting_bins_count <= 1 && post_residual > 20);
        if poor_fit_everywhere {
            score -= 8.0;
        } else {
            score += 35.0 + 20.0 * (1.0 - fit_ratio);
        }
    }

    // Late in the stream, tighten packing (dead space matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // Prefer filling bins that are already well-used.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual nonlinearly
    score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Lookahead: if next item fits exactly into post-residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that next item cannot use
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening new bins when many bins are already open with slack
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual / bin_capacity as f64;
        score += 20.0 * (1.0 - progress) + 15.0 * waste;
        if fitting_bins_count > 0 {
            score += 8.0;
        }
    }

    // Slight preference for bins with residuals below the mean (consolidate small spaces)
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, non-linearly
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // later in the stream, tight fits matter more (dead space costs compound)
    let tightness = 1.0 - norm_pr;
    score += progress * tightness * tightness * (cap * 0.5);

    // Penalize post-residual that no future item is likely to use:
    // interaction with next_item_size lookahead
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= (cap - gap.min(cap)) * 0.3 * (1.0 - progress);
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= cap * 0.75;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Slight preference for bins below mean residual (balance spreading)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Mild penalty for many open bins, smoothed by progress
    score += open_bins_count as f64 * (1.0 + progress) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are "clean"
    let pr = post_residual;
    let class = pr % 10;
    // Reward clean residuals (multiple of 10) that can host typical items
    if class == 0 && pr > 0 {
        score -= 8.0;
    } else if class == 5 {
        score -= 2.0;
    } else {
        score += (10 - class) as f64 * 0.3;
    }

    // Integer-division threshold bands on post_residual
    let band = pr / 20; // 0..5
    match band {
        0 => score += 6.0,          // tiny dead space (<20) is nearly unusable
        1 => score += 1.0,
        2 => score -= 3.0,          // 40..59 hosts mid items
        3 => score -= 5.0,
        4 => score -= 4.0,
        _ => score -= 6.0,          // 100+ (new bin)
    }

    // Coupling with next item: does post_residual fit next_item_size?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            // Reward if next item fits with small leftover (harmonic pair)
            if slack % 10 == 0 {
                score -= 10.0;
            }
            score -= (next_item_size as f64) * 0.05;
        } else {
            // next item cannot use this bin's residual: penalize dead space
            score += (next_item_size - pr) as f64 * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: open fresh only when few bins or early stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) / (mean_residual.max(1.0) / bin_capacity as f64).max(1.0);
        score += 20.0 - 6.0 * progress - pressure.min(10.0);
        // Avoid opening new bins when many bins already fit
        score += (fitting_bins_count as f64) * 2.5;
    }

    // Prefer tighter fits overall
    score += (item_size as f64) / (bin_residual as f64).max(1.0) * 2.0;

    // Mild stream-phase modulation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (progress - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (1..=12) are the worst outcome: heavily penalize them.
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0 + (12 - post_residual as i32).abs() as f64 * 4.0;
    }

    // Perfect fit is the ideal outcome: strong reward.
    if post_residual == 0 {
        score -= 45.0;
    }

    // Post-residual that can still fit typical items is healthy; reward larger usable gaps.
    if post_residual >= 20 {
        score -= (post_residual as f64 - 20.0).sqrt() * 3.0;
    }

    // --- Lookahead coupling (k=2) ---
    // If the next item fits exactly in the post-residual, this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Next item cannot use this gap; if gap is small it becomes dead space.
            if post_residual < 15 {
                score += 25.0;
            }
        }
    }

    // --- Last-chance pressure ---
    // If this is the only bin that fits, avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 18.0;
    }

    // --- Open-bin pressure ---
    // More open bins relative to stream progress: discourage opening yet another bin.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    // New-bin candidate: bin_residual == bin_capacity. Only prefer it when pressure is low.
    if bin_residual == bin_capacity {
        score += bin_pressure * 0.8;
    } else {
        score -= bin_pressure * 0.15;
    }

    // Mean residual context: if open bins are generally roomy, prefer reusing them.
    if bin_residual != bin_capacity {
        score -= (mean_residual - bin_residual as f64).max(0.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // ideal: bin closed perfectly after next item
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // mild reward for leaving room that can still fit the next item
            score -= (30.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot follow into this bin: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }

        // bonus if this bin AND next item together leave a perfect tiny remainder
        let two_step = (post_residual + next_item_size) as i64 - bin_capacity as i64;
        if two_step == 0 {
            score -= 25.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize creating tiny unusable slivers (< 10, the minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: prefer it only when nothing fits well
    if bin_residual == bin_capacity {
        score += 10.0 + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // lookahead suggests keeping open bins for larger items
        }
    }

    // Slight pressure toward filling bins as the stream progresses
    score += (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = if item_size > 0 { (item_size as f64) / (bin_residual as f64) } else { 0.0 };
    score -= 12.0 * tightness;

    // Penalize dead space: post_residual too small to ever fit a typical item
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count <= 1 {
        score -= 30.0;
    }

    // Lookahead coupling: prefer bins whose leftover fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
        // Perfect chaining: leftover exactly fits next item
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_frac = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill_frac * (open_bins_count as f64).ln().max(1.0);

    // Compare against mean residual: bins with less residual than mean are more valuable
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in stream, allow opening new bins more freely; late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 15.0 + 30.0 * progress;
        // But allow a new bin early if item is large and fits poorly elsewhere
        if item_size > bin_capacity / 2 && progress < 0.3 {
            score -= 10.0;
        }
    } else {
        // Late in stream, penalize leaving large residuals unused
        score += 5.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit), non-linearly.
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are acceptable; later, dead space is costly.
    let progress_weight = 0.5 + 1.5 * progress * (2.0 - progress);
    score += 12.0 * progress_weight * norm_pr * norm_pr;

    // Perfect fit reward (post residual near zero), stronger later in stream.
    let perfect = 1.0 - (norm_pr * 4.0).min(1.0);
    score -= 20.0 * perfect * (0.5 + progress);

    // Lookahead: if next item fits into post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportional to leftover dead space.
        score += 6.0 * norm_pr * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish score so it wins only over poor fits.
    // It gets a mild penalty tied to how many open bins already exist and
    // how generous the mean residual is (i.e., reuse capacity when available).
    if bin_residual == bin_capacity {
        score = 55.0 + 0.15 * open_bins_count as f64 + 10.0 * (mean_residual / cap).clamp(0.0, 1.0);
        // Late in the stream, opening new bins is less harmful.
        score -= 20.0 * progress;
    }

    // Mild pressure to consolidate across many open bins.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: capacity fractions and modulo classes on post_residual.
    let cap = bin_capacity as f64;

    // Dead-space penalty: small unusable residues are bad, especially when
    // they fall below the smallest plausible item (harmonic class 0).
    let small_floor = 1u32;
    if post_residual < small_floor.max(next_item_size.min(1)) {
        // post_residual == 0: perfect fit, reward strongly.
        score -= 40.0;
    }

    // Classify post_residual into harmonic classes of capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    // Modulo classes: residues that divide capacity evenly are "harmonic"
    // and more likely reusable by future items (e.g. sizes 10,20,25,50).
    let harmonic_mods: [u32; 5] = [10, 20, 25, 50, 100];
    let mut harmonic_bonus = 0.0;
    for m in harmonic_mods.iter() {
        if *m > 0 && post % m == 0 && post > 0 {
            harmonic_bonus += 6.0;
        }
    }
    score -= harmonic_bonus;

    // Integer-division thresholds: post_residual in the "awkward middle"
    // band (quarter..half) tends to strand space; penalize slightly.
    if post > quarter && post < half {
        score += 4.0;
    } else if post >= half && post < bin_capacity {
        // Large remaining space is generally good (bin stays flexible).
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a chained perfect fit — strong reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size < post {
            // Prefer leaving room for the lookahead item.
            score -= 8.0 * (post as f64 / cap);
        } else {
            // Next item cannot use this bin's residue; residue is dead
            // unless another bin takes the next item.
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post < bin_capacity {
        score -= 12.0;
    }

    // Stream progression: late in the stream, prefer tightening existing
    // bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress;

    // Mean-residual coupling: if this bin's post-residual is far below the
    // mean, we are compacting well; reward it.
    score -= 0.5 * (mean_residual - post as f64).max(0.0);

    // New-bin candidate: an empty bin has huge residual; make it slightly
    // less attractive than a tight fit unless the fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    // Define unusable-gap threshold relative to smallest conceivable item.
    let dead_threshold: u32 = 9; // gaps below ~10 rarely reusable if min item ~10
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0; // heavy penalty for tiny gaps
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits (small post_residual that is still usable)
    score -= (bin_capacity - post_residual) as f64 * 0.15; // favor high fill ratio

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer consolidation
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += pressure * 2.0;

    // Lookahead: if next item fits exactly into the post residual, reward this placement
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item can't use the leftover -> penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // New-bin candidate: keep it attractive when existing fits are poor.
    // Baseline: an empty bin has post_residual = capacity; make its score depend
    // on how bad the average open-bin option is.
    if bin_residual == bin_capacity {
        // neutral-ish baseline, slightly above a perfect fit but below wasteful fits
        score = (bin_capacity as f64) * 0.75 + pressure * 2.0;
        if fitting_bins_count <= 1 {
            // no real alternative: opening a new bin is fine
            score -= 15.0;
        }
        // if mean residual across open bins is large, prefer reusing open bins
        score += mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 12.0;

    // 2-step lookahead: reward if next item fits the post residual exactly / well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= next_fit * 10.0;
            if post_residual == next_item_size {
                score -= 15.0; // perfect 2-step match
            }
        } else {
            // next item cannot fit here: dead space penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: just minimize waste
        score += 0.0;
    }

    // Penalize small unusable residuals relative to mean residual
    if post_residual < 10 {
        score += 8.0;
    }
    if post_residual as f64 > mean_residual * 1.5 {
        score += 2.0; // leaving this bin too full of space vs average
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: keep it neutral unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 5.0; // pairing identical items in a fresh bin
        }
        if fitting_bins_count <= 1 {
            score -= 25.0; // no good existing bin -> open new one
        }
    }

    // Late-stream consolidation: fewer open bins preferred near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: heavily discount small post_residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: reward if the leftover residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Wasted sliver relative to next item.
            score += 5.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
        // Perfect chain: this item plus next fills bin almost exactly.
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Global state: many open bins -> encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.15 * crowding * (0.5 + progress);

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps residual distribution balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: empty bin gets a moderate penalty so it is chosen
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), non-linearly weighted by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial coupling: post_residual vs progress (dead space penalized more later).
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward near-perfect fits more aggressively as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * tightness * (0.4 + progress);

    // Penalize bins whose residual deviates from the mean residual (fragmentation balance).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: reward residual that can host the next item; penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - (pr - nxt) / cap) * (0.5 + progress);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize slightly when open bins exist and item fits elsewhere,
    // but allow opening early when mean residual is small (poor existing fits).
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 6.0 + 2.0 * open_f * (1.0 - progress) - 4.0 * (mean_residual / cap);
    }

    // Mild preference for filling fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket by capacity fractions (C/4, C/2, 3C/4)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let threeq = 3 * quarter;

    // Penalize dead space in the "unusable" low class
    if post_residual < quarter {
        score += 40.0;
    } else if post_residual < half {
        score += 10.0;
    } else if post_residual < threeq {
        score -= 5.0;
    } else {
        score -= 12.0;
    }

    // Modulo arithmetic: post_residual divisible by common small sizes (10,20,25,50)
    // is more likely reusable by future items.
    if post_residual > 0 {
        let mut reuse_bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                reuse_bonus += 6.0;
            }
        }
        score -= reuse_bonus;
    } else {
        // Perfect fit is ideal
        score -= 60.0;
    }

    // Lookahead: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < quarter {
                score -= 20.0; // next item leaves small dead space, still good
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to mismatch
            let mismatch = next_item_size - post_residual;
            score += (mismatch as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Late in the stream, be more conservative about opening new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 25.0 + 50.0 * progress;
        if next_item_size > 0 && next_item_size >= quarter && next_item_size <= half {
            score += 10.0; // keep fresh bin for medium next item
        }
    }

    // Mild penalty per open bin to encourage consolidation
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..100 range,
    // but treat tiny gaps < 12 as likely dead space) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 45.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 25.0;
    } else if fill_ratio > 0.6 {
        score -= 8.0;
    } else if fill_ratio < 0.25 {
        // Dumping a tiny item into a big bin wastes capacity.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading items
    // into fresh space; prefer consolidating into existing residual.
    score += 0.6 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 30.0;
        } else if post_residual as u32 >= next_item_size && post_residual - next_item_size < 12 {
            // Would leave the next item creating dead space; mild penalty.
            score += 8.0;
        }
    }

    // Slight penalty if this bin's residual is far below the mean (already tight bin),
    // unless it's a near-perfect fit which is handled above.
    let dev = mean_residual - bin_residual as f64;
    if dev > 15.0 {
        score += 5.0;
    }

    // New-bin candidate (empty bin): make it attractive only when it beats bad fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by its pristine flexibility.
        score = 40.0 + 0.3 * open_bins_count as f64;
        // If no other bin can fit the item, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

