    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Perfect chain match strongly rewarded
            if slack == 0 {
                score -= 40.0;
            } else {
                score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
            // Penalize leaving residual smaller than next item (dead space)
        } else {
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins deviating to reduce fragmentation
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New bin candidate: penalize unless it enables a clean two-item packing
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0; // acceptable when item+next fill a fresh bin well
        } else {
            score += 60.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
