    // New-bin candidate handling: opening a new bin wastes mean_residual spread.
    // Penalize new bins, but less so when open bins have small residuals or
    // early in the stream where structure matters less.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0
            + 0.4 * mean_residual
            + 10.0 * (1.0 - progress);
        // If no open bin fits at all, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild penalty for proliferating bins when mean residual is still large.
    if bin_residual < bin_capacity && mean_residual > 30.0 {
        score += 0.05 * (mean_residual - 30.0);
    }

    // Slight preference for bins whose residual is close to item_size (exact-ish fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + x * (0.5 + progress);
    let mut score = pr + 20.0 * poly;

    // Reward tight fits (low post residual) increasingly with progress
    score -= (1.0 - x) * (1.0 - x) * 30.0 * (0.3 + 0.7 * progress);

    // Penalize dead space if next item cannot use it
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 15.0 * (1.0 - progress) + 10.0 * x;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Slight pull toward mean residual state
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, penalize opening new bins early
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 buckets
    let post_class = post_residual % 10;
    // Penalize residuals that are awkward (1..9 are hard to fill; 0 is perfect)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_class == 0 {
        score -= 8.0;
    } else if post_residual < 10 {
        // dead space below the minimum item size
        score += 30.0;
    } else {
        score += post_class as f64 * 0.8;
    }

    // Integer-division thresholds: how many "typical" small items could still fit
    let fits_small = post_residual / 10;
    score -= fits_small as f64 * 2.0;

    // Lookahead coupling: reward if next item fits exactly, penalize if it cannot
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += 40.0 + pressure - (mean_residual - post_residual as f64).abs() * 0.1;
    }

    // Mild stream-progression regularization
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Tiny unusable gaps (1..=9) are the worst outcome: heavy penalty.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Mid-range gaps (10..=25) are hard to fill later: moderate penalty.
    if post_residual >= 10 && post_residual <= 25 {
        score += 8.0 * (25.0 - post_residual as f64) / 15.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Lookahead: if next item fits the post-residual exactly, big reward ---
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 50.0;
        } else if slack <= 9.0 {
            score -= 10.0 - slack; // still decent, small penalty for slack
        } else {
            score += slack * 0.1; // too much leftover for next item
        }
    }
    // If next item cannot fit in the leftover, that leftover is likely dead.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // --- Last-chance bonus: only bin that fits -> strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- Open-bin pressure: discourage proliferating bins ---
    score += open_bins_count as f64 * 0.5;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when this bin's fit is bad
        // (large post_residual) or no existing bin is a good home.
        let base = (bin_capacity - item_size) as f64; // leftover in fresh bin
        score = base;
        // Slight bias against opening bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - progress);
        // If this is the last chance among open bins, prefer reusing.
        if fitting_bins_count >= 1 && post_residual <= 9 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead matching: reward when the NEXT item fits exactly into the post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: place here to enable an exact fit next step.
            score -= 30.0 + 0.5 * (bin_residual as f64);
        } else if post_residual >= next_item_size {
            // Next item still fits: mildly reward, scaled by slack quality.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 - 0.08 * slack;
        } else {
            // Next item will not fit: penalize creating near-dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.12 * waste;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Compare post_residual against mean residual across open bins.
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * fitting_bins_count as f64;
        // But allow new bin if current item leaves a very awkward residual
        // and next item is large (avoid fragmenting an existing bin).
        if next_item_size > 0 && post_residual < 10 && next_item_size > 60 {
            score -= 25.0;
        }
    }

    // Early in the stream: slightly prefer consolidating into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * (open_bins_count as f64).ln().max(0.0) * 0.2;

    // Small bias toward tighter fits overall.
    score += 0.02 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space: post residual too small for any plausible item (min size 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward if next item fits exactly in post residual; penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer bins that would be emptied or heavily used.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 20.0;
    }

    // Prefer fuller bins overall (relative to mean residual).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).sqrt();
        score = 100.0 + pressure * 10.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced new bin
        } else if fitting_bins_count == 1 {
            score += 20.0; // last chance exists; avoid new bin
        }
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Early stream: slightly favor opening bins to build diversity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += (1.0 - p2) * (base * base) * cap * 0.6;
    score += p3 * base * cap * 0.9;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += (next_item_size as f64 - pr) * (1.2 - progress);
    } else if next_item_size > 0 {
        score -= (next_item_size as f64 / cap) * 4.0 * (1.0 - progress);
    }

    // Last-chance bonus: avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress);
    }

    // Mild penalty for spreading away from mean residual (fragmentation control)
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    // New-bin candidate: keep it slightly unattractive unless residual is large
    if bin_residual == bin_capacity {
        score += 3.0 + (1.0 - progress) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that sit in "usable"
    // residue classes (multiples of common item sizes), penalize dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward small post_residual strongly (tight fit) with harmonic decay.
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Modulo-class bonus: residuals divisible by 10 are reusable by
        // typical item sizes; odd/prime-ish residuals become dead space.
        if pr % 10 == 0 {
            score -= 12.0;
        }
        if pr % 25 == 0 {
            score -= 6.0;
        }
        // Harmonic fraction of capacity remaining
        let frac = pr as f64 / cap;
        if frac < 0.1 {
            score -= 10.0;
        } else if frac > 0.5 {
            score += 15.0; // leaving >half empty wastes the bin
        }

        // Dead-space penalty: residual smaller than min plausible item (1..100
        // unknown dist, but guard tiny unusable gaps)
        if pr < 5 {
            score += 20.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize if we'd be stuck
            score += 8.0;
        }
        // Harmonic class match: next item and residual share residue class
        if next_item_size % 10 == pr % 10 && next_item_size <= pr {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
    }

    // Prefer bins with residual below mean (denser bins) mildly.
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Late-stream consolidation: as stream progresses, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit gets a big reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward filling a bin deeply (relative fill).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bins pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is an outlier; filling it helps normalize the bin set.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= 0.5 * dev.min(50.0);
    }

    // New-bin candidate: bias by stream progression — early on, allow opening
    // bins more freely; late in the stream, penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 20.0 * progress + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post residual exactly matches next item.
            let match_gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 20.0 + 0.5 * match_gap;
        } else {
            // Penalize dead space that cannot host the next item.
            let dead = post_residual as f64;
            score += 0.6 * dead;
            // Extra penalty proportional to how close the next item is to fitting (near-miss waste).
            let near_miss = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 15.0 * near_miss;
        }
    }

    // Tightness reward: small post_residual is generally good (best-fit flavor).
    score -= 0.3 * (bin_capacity as f64 - post_residual as f64);

    // Relative-to-mean coupling: bins with residual far below mean are precious, keep them tight.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * rel;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slightly discourage opening new bins early in the stream when open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - progress);
        // But if next item is large and current item small, a fresh bin may chain well.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Mild preference to consolidate across many open bins.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

