    if bin_residual == bin_capacity {
        let progress = (step_index as f64) / (total_items.max(1) as f64);
        let crowding = (mean_residual / (bin_capacity as f64)).max(0.0);
        score += 80.0 - 40.0 * crowding - 15.0 * progress;
        if open_bins_count == 0 {
