    // Mild preference for bins whose residual is far from mean (consolidate space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late-stream: prefer filling bins as completely as possible.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score -= progress * (item_size as f64) * 0.3;

    // Penalize very many open bins slightly to encourage consolidation.
    score += (open_bins_count as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
