    // Early in stream: mild penalty for large post residual; late: strong penalty (dead space matters more).
    let quad = norm_post * norm_post * cap * (0.3 + 1.7 * progress);
    score += quad;

    // Cubic interaction: very small post residual (excellent fit) gets extra reward, growing with progress
    let tight_reward = (1.0 - norm_post).powi(3) * cap * (0.2 + 0.8 * progress);
    score -= tight_reward;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
