    score += (mean_residual - post).abs() * 0.15;

    // Lookahead: if next item fits exactly into post residual, reward heavily
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= post {
            let fit_quality = 1.0 - ((post - ns) / cap).abs();
            score -= 8.0 * fit_quality * (0.5 + 0.5 * progress);
        } else {
