        if next_item_size <= post_residual {
            // Excellent: gap serves the next item.
            let tight = (post_residual - next_item_size) as f64;
            score -= 20.0 + 0.5 * tight;
        } else {
            // Gap too small for next item: penalize proportionally to how close it was.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += 0.8 * miss; // painful near-miss
            } else {
                score += 2.0; // gap class useless for next item anyway
            }
        }
    } else {
        // Last item: just prefer zero waste.
        score -= 5.0;
    }

    // Modulo arithmetic on post_residual: gaps that are multiples of common
    // item-size classes (10/20/25) are more reusable.
    let m = post_residual % 10;
    if m == 0 {
        score -= 4.0;
    } else if m >= 7 {
        score += 2.0; // awkward remainder
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has flexible residual; make it
    // attractive only when the current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin scales with stream position and open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 6.0 * progress + 0.4 * open_bins_count as f64;
        // If next item is huge, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 6.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (fill the emptiest-usable bins first keeps many mid-size gaps alive).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Slight preference for tighter fits overall (small post_residual already
    // favored via gap_class; add mild non-linear term).
    score += 0.05 * (gap_class as f64).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer packing into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // already fragmented; prefer bins with larger residual (closer to mean+).
    let resid = bin_residual as f64;
    if resid < mean_residual - 10.0 {
        score += (mean_residual - resid) * 0.5;
    }

    // New-bin candidate: default moderately high; allow it only when the item
    // is large relative to a fresh bin and no tight fit exists.
    if bin_residual == bin_capacity {
        let base = 45.0 + 0.3 * open_bins_count as f64;
        // If next item is small, keeping residuals large is fine -> new bin ok.
        let lookahead_bonus = if next_item_size > 0 && next_item_size >= post_residual.min(100) { -10.0 } else { 5.0 };
        score = base + lookahead_bonus;
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size <= bin_capacity {
        // post residual too small for next item -> dead space for lookahead.
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 25.0 * chain_ratio;
        } else {
            // Dead space penalty: post-residual too small for the next item.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * waste;
        }
    } else {
        // Last item: just minimize leftover.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Mean residual coupling: prefer bins that deviate favorably from the mean.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere (large item, tight stream position).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fit_ratio < 0.5;
        if poor_fit {
            score -= 10.0 + 10.0 * progress;
        } else {
            score += 30.0;
        }
        // Never open a new bin when the next item chains well in some open bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress within the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: reward if the next item also fits in the leftover space
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-fit bonus, scaled by how snugly the next item fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 15.0 + 25.0 * (1.0 - snug / bin_capacity as f64);
        } else if post_residual >= 10 {
            // dead space: leftover too small for next item
            let dead = post_residual as f64;
            score += 10.0 + 0.5 * dead * (1.0 - progress);
        }
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it's only
    // chosen when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score += 45.0 + 5.0 * open_bins_count as f64;
        // late in the stream, be slightly more willing to open bins
        score -= 30.0 * progress;
    }

    // Prefer bins whose residual is below average (tighter bins close sooner)
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    // Penalize leaving awkward mid-range residuals that few items can use
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // nearly perfect fit, very good
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    let mut score = pr * (1.0 + 1.5 * progress * norm_pr);

    // Smooth cubic coupling: later in the stream, small residuals become dead space.
    score += 40.0 * progress * norm_pr * norm_pr * cap;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (item_size as f64 / cap);

    // Penalize leaving a residual that no typical item can use (too small).
    let usable = (pr >= next_item_size as f64) as f64;
    score -= 8.0 * usable * (1.0 - progress);

    // Lookahead coupling: reward if next item fits the post-residual.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (filling emptier bins keeps tight ones flexible).
    score += 0.5 * (pr - mean_residual);

    // Mild pressure to open new bins when many are open and progress is low.
    score += 0.3 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity fraction class does post_residual fall into?
    // Classes: 0 (perfect), 1..=10 (nearly full), 11..=30 (poor), 31..=60 (medium), >60 (roomy)
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -60.0
    } else if pr <= 10 {
        -25.0
    } else if pr <= 30 {
        15.0
    } else if pr <= 60 {
        5.0
    } else {
        0.0
    };
    score += class_penalty;

    // Dead-space coupling: leftover that can't fit the next item is wasted until a small item arrives.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += (next_item_size - pr) as f64 * 0.9;
    }
    // Bonus: leftover exactly accommodates the next item (harmonic pairing).
    if next_item_size > 0 && pr == next_item_size {
        score -= 20.0;
    }
    // Leftover is a harmonic multiple/divisor match with next item (modular affinity).
    if next_item_size > 0 && pr > 0 {
        if pr % next_item_size == 0 {
            score -= 8.0;
        } else if next_item_size % pr.min(next_item_size) == 0 && pr >= 10 {
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new one
    // unless the fit is truly awful.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if pr <= 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate (pristine bin): score it so it wins only when all open fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = (bin_capacity - item_size) as f64 + 40.0;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // Many open bins with slack -> opening another is wasteful.
        score += (open_bins_count as f64).sqrt() * 4.0;
        // If many bins fit, opening a new one is almost never right.
        if fitting_bins_count >= 2 {
            score += 60.0;
        }
        // Small items should go into existing slack.
        if item_size <= 30 {
            score += 35.0;
        }
    }

    // Prefer filling bins that are already relatively full (residual small relative to capacity).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (<= 10, or below the minimum item size) are pure waste.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable dead space: hard penalty.
        score += 500.0;
    } else {
        // Usable residual: reward proportional to how well it can host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0 * next_item_size as f64;
        } else if next_item_size > 0 {
            // Lookahead cannot fit here: penalize proportionally to the wasted gap.
            score += 1.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize tightness of the fill: a near-full residual left over is risky.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is close to the item need.
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; dead-space penalties above make poor open-bin fits lose.
        score += 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
    } else {
        // Last item: prefer tightest fit, no future concern.
        score -= 20.0;
    }

    // Penalize small dead space that likely becomes unusable.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open new bins when
    // existing fits are truly bad; allow it if item is large relative to residuals.
    if bin_residual == bin_capacity {
        let bad_fit = (mean_residual - item_size as f64).abs() > 30.0;
        if bad_fit {
            score -= 15.0;
        } else {
            score += 35.0;
        }
    }

    // Mild preference for filling bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Late in stream: consolidate into fewer bins.
    if total_items > 0 && step_index as f64 / total_items as f64 > 0.8 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill * fill;

    // Penalize small unusable post-residuals that are also too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.05 * (bin_residual as f64);
    }

    // New-bin candidate: penalize opening a new bin unless the item is large or fits are poor.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let waste = (cap - item_size as f64) / cap;
        score += 15.0 * desperation + 10.0 * waste;
        // Late in stream, opening new bins is more costly.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * t;
    }

    // Prefer bins with residual below the mean residual (consolidate space).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Prefer fewer open bins being filled further when many bins are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with a quadratic tightening over time
    let mut score = pr * (1.0 + progress * progress * 0.8) + norm_pr * norm_pr * 30.0;

    // Reward tight fits (post_residual near zero), smoothed
    let tight = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= tight * tight * tight * 12.0;

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 10.0 * (1.0 - ns / cap);
        } else {
            // penalize dead space that next item cannot use
            score += 6.0 * (1.0 - pr / ns);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight aversion to spreading across many open bins early
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // Pull toward mean residual to consolidate space
    score += (mean_residual - pr).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space that is a small
    // remainder mod common item sizes is more likely reusable later.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward residuals that are "harmonious" with typical item sizes
    // (multiples of 10, 20, 25, 50 are common packing targets).
    if pr == 0 {
        score -= 1000.0; // perfect fit, always best
    } else {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50, 100] {
            if pr % m == 0 {
                harmony += 30.0 * (m as f64 / 100.0);
            }
        }
        // small residual classes (1..=9) are near-dead space
        if pr < 10 {
            harmony -= 40.0;
        }
        score -= harmony;
    }

    // Integer-division threshold: post_residual bucketed by fifths of capacity.
    let fifth = (bin_capacity / 5).max(1);
    let bucket = pr / fifth;
    score -= match bucket {
        0 => 25.0,   // tiny leftover, nearly wasted
        1 => 10.0,
        2 => 0.0,
        3 => -10.0,
        _ => -20.0,  // large leftover, still flexible
    } as f64;

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin (creates a perfect follow-up).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            score -= 30.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here; penalize leaving awkward mid gaps
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    // (large post_residual means we "wasted" a fresh bin anyway) or
    // no open bin is tight.
    if bin_residual == bin_capacity {
        // base new-bin cost
        let mut nb = 80.0;
        // open a new bin early in the stream when many bins fit anyway
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb -= 30.0 * (1.0 - progress);
        // if mean residual across open bins is large, spreading is fine
        nb -= (mean_residual / cap).clamp(0.0, 1.0) * 40.0;
        score += nb;
    }

    // Mild pressure against hoarding many open bins with big residuals
    score += 0.5 * open_bins_count as f64;

    // Prefer tighter fits overall (small post_residual relative to capacity)
    score += (pr as f64 / cap) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the lookahead item are also dead space for k=2.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (item_size as f64).max(1.0);
        score -= 30.0 * tightness.max(0.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += 0.6 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., we are consuming the fuller bins first).
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let stream_progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 + 10.0 * stream_progress;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Penalize dead space that is too small for the smallest possible item (1..100 unknown, use 10 as typical lower bound)
        let dead_floor = 10.0;
        if (post_residual as f64) < dead_floor {
            score += 60.0; // unusable sliver
        }
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0; // chain fit: next item fills this bin perfectly
        } else if post_residual > next_item_size {
            // post_residual leaves room for next item; mild reward proportional to closeness
            let gap = (post_residual - next_item_size) as f64;
            score -= (40.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot fit here; penalize if the leftover is small/wasted
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.3;
        }
    }

    // Relative-to-mean coupling: prefer bins with residuals below mean (consolidate fullness)
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins would leave bad fits.
    if bin_residual == bin_capacity {
        // base penalty so open bins win unless they fit poorly
        score += 120.0;
        // late in the stream, opening new bins is more acceptable (packing tail items)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 80.0 * progress;
        // if next item is large, a fresh bin is more valuable
        if next_item_size >= item_size {
            score -= 30.0;
        }
        // if many bins are open and mean residual is high, spreading is fine
        if mean_residual > 50.0 {
            score -= 20.0;
        }
    }

    // Mild penalty for wasting large residual bins on tiny items
    if (item_size as f64) < 0.25 * bin_residual as f64 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress-based horizon: early on, be conservative; late, close bins tightly.
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0 + 30.0 * progress;
    }

    // Penalize new-bin opening when decent alternatives exist; reward when stream is crowded.
    if is_new_bin {
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0).max(1.0);
        score += 40.0 - 25.0 * progress - crowding.min(20.0);
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * post_residual as f64;
        } else {
            // Dead-space penalty scaled by how wasted the leftover is.
            let waste = post_residual as f64;
            score += 0.4 * waste * (1.0 - progress);
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score -= 0.25 * (mean_residual - bin_residual as f64);

    // Mild preference for filling bins with larger current items.
    score -= 0.1 * item_size as f64;

    // Small tie-break toward fewer open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual with smooth polynomial coupling to stream progress.
    let x = pr / cap; // in [0, 1]
    let coupling = x * x * (1.0 - progress) + x * x * x * progress;
    score += 3.0 * coupling;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - x;
    score -= 2.0 * tightness * tightness * (0.5 + progress);

    // Penalize residual that is close to mean residual (uninformative) vs. deviation reward.
    let dev = (pr - mean_residual) / cap;
    score -= 0.5 * dev * dev;

    // Last-chance bin bonus (smooth sigmoid-like weight on fitting_bins_count).
    if fitting_bins_count >= 1 {
        let w = 1.0 / (fitting_bins_count as f64);
        score -= 5.0 * w * (0.5 + progress);
    }

    // Lookahead: reward leaving room for the next item via smooth quadratic interaction.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (x - nx).abs();
        score -= 1.5 * (1.0 - gap) * (1.0 - gap);
        // Penalize post-residual that is just barely too small for the next item.
        let shortfall = nx - x;
        if shortfall > 0.0 && shortfall < 0.2 {
            score += 4.0 * (1.0 - shortfall / 0.2) * (0.5 + progress);
        }
    }

    // Mild pressure to prefer already-open bins over opening new ones.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is best possible
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover: post_residual mod capacity fractions.
    // Leftovers that can host "nice" item sizes (multiples of 10/25/50) are valuable.
    let pr = post_residual;
    let nice = |r: u32| -> f64 {
        let mut v = 0.0;
        for &m in &[10u32, 20, 25, 50] {
            if r % m == 0 { v += 8.0; }
        }
        v
    };
    score -= nice(pr);

    // Penalize tiny dead space (unusable slivers)
    if pr < 10 {
        score += 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size < pr {
            // next item fits: reward proportional to how much it consumes
            score -= 30.0 + (next_item_size as f64 / pr as f64) * 40.0;
            // harmonic bonus if next item also lands on a class boundary
            if (pr - next_item_size) % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 20.0 + (next_item_size as f64 - pr as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when current open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        // Open new bin when open bins are nearly full or few remain usable
        if pressure > 0.6 {
            score -= 150.0 * pressure;
        } else {
            score += 200.0 - 100.0 * progress;
        }
    }

    // Prefer bins whose residual is close to item size (tight fit)
    score += (bin_residual - item_size) as f64 * 0.3;

    // Slight preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing can ever use (below min item size 1)
    // or too small for the lookahead item are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable dead space
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 18.0; // can't host the next item
        } else if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0; // perfect fit for lookahead: strongly favored
        }
    } else {
        score -= 40.0; // perfect closure of the bin
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new/partial bins.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are already tight on average.
        score += 15.0 * pressure + mean_residual * 0.5;
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 10.0; // room for lookahead in fresh bin
        }
    } else {
        // Prefer bins whose residual is close to the item (tight fit).
        score -= 20.0 * (1.0 - (item_size as f64 / bin_residual as f64)).abs();
        score += (mean_residual - bin_residual as f64).abs() * 0.3;
    }

    // Slight late-stream tightening: keep bins closed as the stream progresses.
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by base term.

    // 2-step lookahead: strongly reward when the NEXT item exactly fits the
    // post_residual (perfect chaining), mildly reward when it fits at all.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            // reward proportional closeness of the chain fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize dead space
            score += 8.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose post_residual tracks the
    // mean residual (keeps bins homogeneous and reusable).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize creating very small unusable slivers (dead space < 10).
    if post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate (pristine bin): make it attractive only when the
    // item is large and no good chaining is possible; otherwise keep it
    // slightly worse than a decent existing fit.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 10.0; // large item into fresh bin is fine
        }
    }

    // Mild late-stream pressure to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Dead space relative to the next item.
            let dead = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.05 * dead;
        }
    }

    // Prefer bins with residuals close to the mean (balance preservation),
    // but only early-to-mid stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev * (1.0 - progress);

    // Late in the stream: consolidate aggressively into existing bins.
    if progress > 0.7 {
        score -= 6.0 * progress;
    }

    // Many open bins: discourage opening new bins further.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / item_size.max(1) as f64);
        score += 20.0 + 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        if fitting_bins_count <= 1 {
            score -= 10.0; // new bin acceptable if nothing else fits
        }
        let _ = pressure;
    } else {
        // Reward using fuller bins (larger fill fraction).
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // Slight preference for bins whose residual is awkwardly small (hard to reuse).
    if bin_residual < 20 && bin_residual >= item_size {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 40.0 * poly;

    // Penalize near-full waste nonlinearly
    score += 12.0 * norm_pr * norm_pr * norm_pr;

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= (1.0 - progress) * 0.0;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - progress + 0.5);
    }

    // Lookahead: reward leaving space close to next item size (smooth gaussian-like coupling)
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64) / cap;
        score -= 30.0 * (-40.0 * d * d);
    }

    // Many open bins: discourage spreading, favor filling existing ones
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins whose residual is near the mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: make it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: dead space classes (1..=9) are poison,
    // class 0 (exact fill) is perfect.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr < 10 {
        // unusable dead space for items >= 10 (but sizes can be >=1 here)
        let usable = if next_item_size > 0 && (next_item_size as u32) <= pr { 1.0 } else { 0.0 };
        score += 25.0 - 30.0 * usable;
    }

    // Integer-division thresholds: how many size-10 slots remain
    let slots10 = pr / 10;
    score -= (slots10 as f64) * 4.0;

    // Lookahead coupling: reward if next item fits exactly into post-residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            let r2 = pr - next_item_size;
            if r2 < 10 { score += 12.0; } else { score -= 8.0; }
        } else {
            // next item won't fit here: post residual becomes final dead space
            score += 10.0;
        }
    }

    // Fractional capacity coupling
    let frac = (post_residual as f64) / cap;
    score += 20.0 * frac * frac; // penalize large leftover quadratically

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / cap;
        // base penalty so new bins are opened only when needed
        score += 60.0 + 30.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer fuller bins when many bins are open
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 15.0 * fill * (open_bins_count.min(20) as f64) / 20.0;

    // Mean-residual anchoring: bins deviating above mean residual are worse targets
    score += 0.5 * ((bin_residual as f64) - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0 + progress * 15.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (small gap), mild penalty for stranding it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 5 {
        score += 8.0;
    }

    // Prefer bins below the mean residual (consolidating space).
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item exactly fills the post residual
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        if post_residual == next_item_size {
            // perfect 2-chain: huge reward
            score -= 60.0 + pr * 0.5;
        } else if next_item_size <= post_residual {
            // next item fits in leftover: reward proportional to tightness
            let tight = 1.0 - (pr - nx) / (bin_capacity as f64);
            score -= 5.0 + 25.0 * tight;
        } else {
            // dead space for the next item: penalize
            let gap = nx - pr;
            score += 2.0 + gap * 0.15;
        }
    } else {
        // last item: prefer minimal post residual (already base term)
        score += 0.0;
    }

    // Prefer bins whose residual is tighter than the mean (best-fit flavor)
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size >= item_size {
            // new bin could host current then next item chain
            let chain = item_size as f64 + next_item_size as f64;
            if chain <= bin_capacity as f64 {
                score -= 4.0;
            } else {
                score += 6.0;
            }
        } else {
            score += 10.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Slight early-stream preference to open bins (build variety)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty for small leftovers
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if the next item fits into the post-residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.4 * (next_item_size as f64);
        } else {
            // dead-space penalty scaled by how much of the leftover is wasted
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score -= 0.2 * (residual_f - mean_residual);
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let open_fit_penalty = (open_bins_count as f64) * 8.0;
        score = bin_capacity as f64 * 0.9 + open_fit_penalty;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can host next item too
        }
    }

    // Late-stream urgency: consolidate aggressively near the end
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    let mut score = pr;

    // Tight-fit reward: strongly favor bins with small post residual (non-linear).
    let tightness = 1.0 - (pr / cap);
    score -= 30.0 * tightness * tightness;

    // Exact-ish fit bonus when post residual is below typical small item size.
    if pr > 0.0 && pr < 10.0 {
        score -= 20.0;
    }

    // Lookahead coupling: reward if the next item fits into the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // smooth coupling: reward proportional to how well next item nests
            let nest = 1.0 - (pr - nxt) / cap;
            score -= 12.0 * nest * (1.0 + progress);
        } else {
            // penalize creating residual that dead-ends relative to next item
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid new-bin penalty dominating).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: a fresh bin has residual == capacity.
    // Penalize opening a new bin unless current bins are nearly full or very fragmented.
    if bin_residual == bin_capacity {
        let mean_tight = 1.0 - (mean_residual / cap);
        // If open bins are on average tight, opening a new bin is fine.
        score += 15.0 + 20.0 * mean_tight;
        // Late in the stream, slightly discourage proliferation of open bins.
        score += 5.0 * progress;
    }

    // Mild penalty for wasting space relative to mean residual of the fleet.
    score += 0.05 * (pr - mean_residual).max(0.0);

    // Small non-linear stream-progress coupling on post residual:
    // later in the stream, dead space matters more.
    score += 6.0 * progress * (pr / cap) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo buckets on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals that are "awkward" (not expressible as a
    // sum of typical item sizes) get penalized via modulo classes.
    let class = post_residual % 10;
    let awkward = match class {
        0 => 0.0,          // perfectly harmonic
        1 | 2 => 2.0,      // near-perfect slivers, unusable
        9 => -1.0,         // one unit away from a class boundary
        _ => 1.0,
    };
    score += awkward;

    // Integer-division thresholds: how many "unit chunks" of 10 remain.
    let chunks = post_residual / 10;
    score -= chunks as f64 * 0.5;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 20.0; // near-perfect: effectively dead space eliminated
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_class = (post_residual - next_item_size) % 10;
            score -= 5.0 - next_class as f64 * 0.3;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: prefer filling existing ones over opening new.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current bins are crowded.
        let crowded = (open_bins_count as f64) * (mean_residual / cap);
        score += 20.0 + crowded * 5.0;
        // If item is large relative to capacity, a fresh bin is more attractive.
        score -= (item_size as f64 / cap) * 15.0;
    } else {
        // Existing bin: reward closeness to mean residual (balance) slightly.
        let dev = (pr - mean_residual).abs();
        score += dev * 0.05;
    }

    // Stream progression: later in the stream, be more aggressive about
    // filling bins tightly (avoid leftover fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<=10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gap: likely dead space unless it exactly fits a future item.
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap can't host next item: mild penalty scaled by gap smallness.
        score += 6.0 * (1.0 - post_residual as f64 / 100.0);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 50.0);
    score += 0.05 * pressure;

    // New-bin candidate: prefer it only when existing bins would leave bad gaps
    // (its post_residual is large, so base score is high; add a mild bias that
    // shrinks as the stream progresses and consolidation matters more).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        score += 10.0 * progress;
    }

    // Deviation from mean residual: penalize creating outliers (fragmentation).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches with next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize residuals that cannot host the next item
        score += 12.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (below min item size 1..100 heuristic: < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Coupling with mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Prefer reusing bins when many are open (bin consolidation pressure)
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Late-stream urgency: fill existing bins harder as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate should only win when open bins are badly fragmented
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers are wasted space
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving awkward residual.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate logic: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // Cheaper to open a new bin early when many items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        // If item fills a fresh bin well, opening is attractive.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 15.0 * fill;
        // If no open bin fits (this is the only candidate), new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Reward using existing bins when they are already fragmented (high mean residual usage).
        let usage = 1.0 - mean_residual / bin_capacity as f64;
        score -= 10.0 * usage;
        // Slight penalty for spreading across too many open bins.
        score += 0.3 * open_bins_count as f64;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, tolerate larger residuals; later, penalize dead space more.
    let progress_curve = 0.5 + progress * progress;
    let mut score = post * (1.0 + progress_curve * norm_post);

    // Perfect fit bonus (non-linear in post_residual).
    if post == 0.0 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead coupling: reward residual that fits the next item exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            // Post-residual too small for next item: smooth penalty.
            let gap = (nxt - post) / cap;
            score += 8.0 * gap * (1.0 - gap);
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 18.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild competition term: prefer bins with less residual among many options.
        score += (mean_residual - post) * 0.15;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Cost of opening a new bin grows with number of open bins and stream progress,
        // but is discounted when the item is large relative to capacity.
        let item_frac = item_size as f64 / cap;
        let open_cost = 30.0 * (1.0 + (open_bins_count as f64).ln().max(0.0)) * (0.4 + 0.6 * progress);
        score += open_cost * (1.0 - 0.5 * item_frac * item_frac);
    }

    // Mild preference for bins whose residual deviates from the mean in a useful way:
    // favor bins with residual close to item_size (tight fit).
    let tightness = 1.0 - ((bin_residual as f64 - item_size as f64) / cap).abs();
    score -= 6.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "small" classes
    // (hard to fill later) are penalized; residuals near nice fractions of capacity
    // (matching common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // dead-space penalty grows for awkward classes (7,8,9 -> hard to fill)
        let class_penalty: f64 = match class {
            0 => -8.0,
            1 | 2 => -4.0,
            3 | 4 => -2.0,
            5 | 6 => 0.0,
            7 => 3.0,
            8 => 5.0,
            9 => 7.0,
            _ => 0.0,
        };
        score += class_penalty;

        // Integer-division thresholds: residual <= 10 is essentially perfect
        if pr <= 10 { score -= 15.0; }
        // residual in [11..=20] still useful for small items
        else if pr <= 20 { score -= 6.0; }
        // residual > 50: bin stays flexible, mildly rewarded
        else if pr > 50 { score -= 2.0; }
        // 30..50 is the dead zone: too big to waste, too small to be flexible
        else if pr >= 30 && pr <= 50 { score += 4.0; }
    } else {
        // perfect fill
        score -= 40.0;
    }

    // Lookahead: reward if next_item_size fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score -= 6.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item won't fit here: penalize proportionally
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer it only when open bins are mostly full
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // early on, opening bins is cheap; later, avoid fragmentation
        score += 25.0 - 30.0 * mean_fill - 10.0 * progress;
        if open_bins_count == 0 { score -= 30.0; }
    }

    // Tie-break: prefer fuller bins (smaller residual before placement)
    score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item (1..=100)
    // are pure waste. Penalize gaps in the "dead zone" (1..10) heavily, with a
    // super-linear ramp so near-zero gaps are worst.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual == 0 {
        // Perfect fit is the ideal outcome: strong reward.
        score -= 40.0;
    }

    // Penalize large leftover space mildly when the next item cannot use it:
    // wasted capacity that lookahead can't rescue.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u32) > post_residual {
            score += (post_residual as f64) * 0.8; // gap unusable by lookahead -> dead space
        } else {
            score -= 6.0; // lookahead fits into the gap -> good chaining
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 as u32 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // making the new-bin candidate (residual == capacity) unattractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure so it loses unless all
        // alternatives create worse dead space.
        score = 100.0 + pressure * 3.0;
        // Early in stream with few bins, opening a new bin is cheaper.
        score -= (total_items.max(1) - step_index.min(total_items)) as f64 * 0.01;
        // If next item is large, a fresh bin may be valuable.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    } else {
        // Slight preference for bins with residual close to the mean (balance).
        score += (bin_residual as f64 - mean_residual).abs() * 0.05;
        // Prefer tighter bins overall (best-fit flavor) scaled by pressure.
        score += (bin_residual as f64) * 0.02 * (1.0 + pressure * 0.05);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: residual consumed entirely by next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits; reward closeness of the fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit in the leftover: penalize dead space,
            // scaled by how close post_residual is to being useless.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    } else {
        // Last item: pure best-fit behavior.
        score -= 10.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual is below mean
    // (tight bins) so large residuals stay available for large future items.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, but allow it when
    // the item fits very poorly everywhere (post_residual near capacity).
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral base; slight penalty that shrinks as
        // the stream progresses (early on, opening bins is cheap).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - 0.5 * progress);
        // But if item would leave a near-perfect slot for next item in a fresh bin, reward.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 55.0;
        }
    }

    // Small nonlinearity: discourage leaving residuals in the awkward
    // 1..=9 range (unusable for items >= 10... but sizes 1..100 allowed).
    if post_residual >= 1 && post_residual <= 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving exactly enough room for the next item (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // If many bins fit the item, mild penalty to encourage spreading load among few bins.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, decaying as stream progresses (sunk capacity amortizes).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 30.0 - 12.0 * progress;
        // Opening is more attractive when mean residual is large (bins are full of holes).
        open_cost -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
        // If this bin is the only fitter, opening is bad.
        if fitting_bins_count == 1 {
            open_cost += 40.0;
        }
        // Perfect-fit potential: opening a fresh bin leaves residual = capacity - item.
        if next_item_size > 0 && post_residual == next_item_size {
            open_cost -= 20.0;
        }
        score += open_cost.max(0.0);
    } else {
        // Prefer bins whose residual is close to the item (minimal waste) among open bins.
        let fit_gap = (bin_residual as f64 - item_size as f64);
        score += 0.08 * fit_gap;
        // Reward using bins below mean residual (draining fragmented bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Late-stream consolidation: favor filling bins completely as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    // Small nudge toward fewer open bins when many are open.
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64 - 4.0).min(6.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) growth
    let mut score = pr + 2.0 * norm_pr * pr;

    // Smooth coupling: late in the stream, waste matters more (quartic ramp on progress)
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * late * norm_pr * norm_pr;

    // Reward tight fits: if post_residual is small relative to capacity, subtract bonus
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if (next_item_size as u32) <= post_residual {
            score -= 15.0 * (next_item_size as f64 / cap);
        } else {
            // post_residual too small for next item: penalize dead space smoothly
            let unusable = (next_item_size as f64 - pr) / cap;
            score += 20.0 * unusable * (1.0 + late);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - late);
    }

    // New-bin candidate handling: empty bin gets a mild default score so it wins
    // only when no open bin offers a good fit
    if bin_residual == bin_capacity {
        score = cap * (1.0 + late) + 10.0 * (open_bins_count as f64).sqrt();
    }

    // Smooth global pressure: many open bins with high mean residual -> prefer reusing
    score += 0.5 * mean_residual / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into coarse buckets.
    let pr = post_residual;
    let class = pr / 10; // 0..=10 harmonic class

    // Dead space penalty: residuals that are small but unusable (below typical item range)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic class bonuses: residuals that are multiples of common item sizes
    // are more likely reusable (modular arithmetic on capacity fractions).
    if pr % 20 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 50 == 0 && pr > 0 {
        score -= 10.0;
    }

    // Penalize mid-range classes (30..70) lightly; they are awkward leftovers.
    if class >= 3 && class <= 6 && pr > 0 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Prefer new bin when current open bins are nearly full on average
        // and this item would leave a bad harmonic class behind.
        let tight = mean_residual / bin_capacity as f64;
        if tight < 0.25 {
            score -= 12.0;
        }
        // Don't open new bins early in the stream when plenty of open bins exist
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 2 && progress < 0.5 {
            score += 10.0;
        }
        // A new bin is attractive if item is large (would fragment an open bin)
        if item_size > 60 && tight < 0.4 {
            score -= 8.0;
        }
    }

    // Mild preference for filling fuller bins first (best-fit flavor via residual).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Small tie-break noise-free structural nudge by open bin count.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual > 0 && post_residual < item_size.min(20) as f64 {
        // gap smaller than a plausible future item -> likely dead space
        score += (20 - post_residual.min(20)) as f64 * 4.0;
    }

    // Reward tight fits (small but well-used residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 6.0;

    // Reward filling bins that are already fairly full (consolidation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 4.0;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bin pressure: with many open bins, discourage spreading; prefer new bin only if fit is bad.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 0.35;

    // New-bin candidate handling: only attractive if current fit is terrible.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = bin_capacity as f64 * 0.5;
        // penalize opening a new bin when a decent fit exists elsewhere
        if post_residual >= 0 && fitting_bins_count > 0 && item_size as f64 <= mean_residual {
            score += 20.0;
        }
        // if the next item is large, a fresh bin is more valuable
        if next_item_size >= 50 {
            score -= 15.0;
        }
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 18.0;
        } else {
            score -= 4.0;
        }
    }
    // If next item would not fit here but this bin gets perfectly filled, small bonus.
    if next_item_size > 0 && post_residual == 0 {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (more full than average).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.02;
