pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Exact fit: massive reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Bonus if next item then fits very snugly
        let next_left = post_residual - next_item_size;
        if next_left <= 10 {
            score -= 10.0;
        }
    }
    // Penalize leaving a residual just below the next item (dead space)
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize opening new bins, more so early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 30.0 * (1.0 - progress);
        // But if existing bins leave bad residuals, new bin is more acceptable
        if mean_residual > 0.0 && (mean_residual < item_size as f64) {
            score -= 20.0;
        }
        // If no open bin fits, new bin is necessary
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balance usage)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Slight preference for fuller bins (smaller residual) when many bins open
    if open_bins_count > 3 {
        score += (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer bins with smaller post-residual (tighter fit)
    let mut score = pr;

    // Non-linear penalty for medium dead space: residual that is too large wastes capacity,
    // too small is fine (tight fit). Smooth cubic coupling with stream progress.
    let dead = norm_pr * (1.0 - norm_pr);
    score += 40.0 * dead * (1.0 + 2.0 * progress);

    // Strong quadratic penalty for large leftover space (wasted capacity), growing over stream
    score += 0.35 * pr * pr / cap * (0.5 + progress);

    // Reward if the next item fits into the post-residual (lookahead chaining)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            // Exact-ish fit for next item: big reward
            let tightness = 1.0 - ((pr - ns) / cap);
            score -= 25.0 * tightness * (1.0 + progress);
        } else {
            // Next item won't fit: mild penalty proportional to unusable excess
            score += 0.15 * (ns - pr);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // New-bin candidate (empty bin): penalize unless open bins are few or fit is poor,
    // so we prefer filling existing bins when possible
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins deviating below mean (concentrate waste)
    score += 0.5 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 10 are
    // "usable" for typical items; odd/tiny residues are dead space.
    let pr = post_residual;
    let cls = pr % 10;
    if pr > 0 {
        // Penalize awkward residues (1..2, 6..9 away from decade marks)
        if cls >= 1 && cls <= 2 { score += 6.0; }
        if cls >= 6 && cls <= 9 { score += 3.0; }
        // Perfect decade residuals are prime targets
        if cls == 0 && pr >= 10 { score -= 8.0; }
    }

    // Exact fit is always excellent
    if pr == 0 { score -= 25.0; }

    // Dead-space threshold: residual too small for the smallest item
    if pr > 0 && pr < 10 { score += 15.0 + pr as f64; }

    // Integer-division harmonic classes on post_residual
    let q = pr / 10; // decade class
    match q {
        0 => score += 2.0,          // sliver
        1 => score -= 3.0,          // 10-19: fits small items
        2 => score -= 5.0,          // 20-29
        3 => score -= 4.0,          // 30-39
        _ => score -= 2.0,          // large residual: keep for big items
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 8.0 - (slack as f64).min(8.0);
            if slack < 10 { score -= 4.0; }
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += (next_item_size - pr).min(40) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: discourage fragmentation, prefer tight fills
    if open_bins_count > 6 {
        score += mean_residual * 0.05;
    }

    // Early stream: keep bins flexible (prefer larger post_residual slightly)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        score += (bin_capacity as f64 - pr as f64) * 0.02;
    }

    // New-bin candidate handling: an empty bin has neutral baseline; make it
    // attractive only when no open bin offers a good (near-exact) fit.
    if bin_residual == bin_capacity {
        score = 45.0 + item_size as f64 * 0.1;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            score -= 3.0;
        }
        if fitting_bins_count == 1 { score += 20.0; } // keep last-chance bin preferred
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable.
    if post_residual < 10 {
        score += 150.0;
    } else if post_residual < 20 {
        score += 60.0;
    } else if post_residual < 30 {
        score += 25.0;
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 40.0 + 0.5 * post_residual as f64;
    }
    // Reward if next item fits snugly in the resulting gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.4 * next_item_size as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: mostly attractive when open-bin pressure is high
    // or residuals are already fragmented; otherwise prefer reusing bins.
    if bin_residual == bin_capacity {
        score = 80.0 + 10.0 * open_bins_count as f64 - 0.3 * mean_residual;
        if fitting_bins_count == 1 {
            score += 300.0; // don't abandon the only fitting bin
        }
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 50.0; // reserve fresh capacity for big next item
        }
    }

    // Mild pressure: consolidating into fewer bins is preferred.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit, slightly super-linear penalty on wasted space.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual >= next_item_size {
            // Exact match for next item is highly desirable.
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect chaining: post_residual == next_item_size exactly.
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else {
            // Post-residual too small for next item: mild penalty proportional to dead space.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: only tightness matters.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" —
    // filling them further is good if it leaves small waste.
    let rel = post_residual as f64 - mean_residual;
    score += 0.08 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // (avoids opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bins should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; the penalty shrinks when many bins are open
        // (consolidation pressure) and late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 10.0 * (1.0 - progress);
        // But if the item is large and would leave a tiny residual in open bins,
        // a fresh bin may be better — soften penalty for large items.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Slight preference for keeping fewer open bins (encourage filling existing bins).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize proportional wasted fraction
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Small post-residuals that are dead space (nothing in [1..post_residual] range likely fits)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // Lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (-slack / 20.0).exp();
        } else {
            // next item cannot use the leftover: penalize proportionally
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin
        score = bin_capacity as f64 - 5.0;
        // Early in the stream with many open bins, opening new bins is wasteful
        score += 15.0 * (1.0 - progress);
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // If any open bin could fit, make new bin less attractive unless fit is bad
            let avg_fit = mean_residual.max(1.0);
            let open_fit_quality = item_size as f64 / avg_fit;
            if open_fit_quality > 0.7 {
                score += 40.0; // open bins fit well enough; keep new bin closed
            }
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
    }

    // Global pressure: when many bins are open, discourage leaving scattered residuals
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: penalize placements that diverge from current mean state
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.03 * deviation;

    // Late-stream consolidation: prefer filling existing bins tighter as stream ends
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
