    // non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += poly * cap * (0.6 + 0.8 * progress);
    // reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 40.0 * progress);
    // penalize near-full residuals that waste little space but block future items late
    score += (norm_pr * norm_pr * norm_pr) * 30.0 * progress;
    // lookahead: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        let fit = 1.0 / (1.0 + diff * diff * 25.0);
        score -= 15.0 * fit * (1.0 - progress * 0.5);
        if nx > pr {
            score += 8.0 * (nx - pr) / cap;
        }
    }
    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }
    // many open bins: mild penalty to consolidate
    score += 0.5 * open_bins_count as f64 * (norm_pr + 0.1);
    // spread from mean residual: prefer bins near the mean (balance)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;
    // new-bin candidate: make it moderately attractive only when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins whose residual falls into
    // "usable" classes (multiples of common small item sizes) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class bonus: residual divisible by 10/20/25/50 is reusable by many item sizes.
    let r = post_residual;
    let class_bonus = if r == 0 {
        40.0 // perfect fit: strongly favored
    } else if r % 50 == 0 {
        25.0
    } else if r % 25 == 0 {
        18.0
    } else if r % 20 == 0 {
        14.0
    } else if r % 10 == 0 {
        10.0
    } else if r % 5 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Penalize dead space that no plausible item (>=1, up to 100) can use well:
    // tiny residuals (1..10) are near-waste unless post_residual == 0.
    if r > 0 && r < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward strongly; if it cannot fit at all, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Harmonic threshold: next item in a "large class" (>50) makes tight fits valuable
        if next_item_size > 50 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream or with many bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 + 20.0 * progress - 2.0 * (open_bins_count.min(20) as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin is attractive if current bins are crowded
            if mean_residual < next_item_size as f64 {
                score -= 25.0;
            }
        }
    }

    // Mild preference for filling fuller bins (low post_residual relative to capacity).
    score += 0.05 * (1.0 - pr / cap) * (pr / cap) * 100.0;

    // Tie-break with mean residual deviation: prefer bins close to average state.
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        // perfect or near-perfect fill: reward strongly
        score -= 40.0;
    } else if (post_residual as f64) < dead_threshold * 2.0 {
        // small gap likely wasted: penalize
        score += 15.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Penalize creating a gap that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // gap remains usable for the next item: reward
            score -= 8.0;
        } else if post_residual > 0 {
            // gap too small for the next item: dead space risk
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to the mean residual (harmonized fill).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin grows with the number of open bins
        // and with stream progression (late stream: consolidate more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // if the item is large, a fresh bin is more acceptable
        score -= 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (dead space elimination)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack.min(150.0);
        } else {
            // penalize blocking the next item
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Coupling with mean residual: prefer bins close to mean residual (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let base_penalty = 250.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // slightly cheaper to open bins late in stream
        score += base_penalty * (1.0 - 0.3 * progress);
        // if next item is large and this bin would be nearly filled, allow it
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 120.0;
        }
    }

    // prefer fuller bins as stream progresses
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tight * tight * tight;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64) < n && post_residual > 0 {
            score += 12.0 * (n - post_residual as f64) / cap;
        }
        // Reward leaving exactly enough room for the next item.
        if (post_residual as f64) >= n && (post_residual as f64 - n) < 10.0 {
            score -= 15.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin: penalize unless nothing fits well (post_residual near cap means bad fit).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = (post_residual as f64) / cap; // 1.0 - item/cap
        score += 25.0 + 20.0 * (1.0 - bad_fit) + 10.0 * (1.0 - progress);
        // If existing bins are fragmented, opening a fresh bin is more acceptable.
        if mean_residual < cap * 0.35 {
            score -= 30.0;
        }
    }

    // Prefer filling bins that deviate from the mean residual (balance consolidation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins with low residual relative to open set size.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / cap);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual^2 scaled, modulated by progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * 0.5;
    score += poly * cap;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 40.0 * progress;
    }

    // Penalize opening new bins when open bins fit, mildly increasing with progress
    if bin_residual == bin_capacity {
        let waste_penalty = (item_size as f64 / cap).powi(2) * 25.0;
        score += 15.0 + waste_penalty + 20.0 * progress;
    } else {
        // Lookahead: reward leaving space that fits the next item
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 {
            score += (next_item_size as f64 - pr) * 0.3;
        }
        // Divergence from mean residual penalizes outliers
        score += (mean_residual - pr).abs() * 0.15;
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer-division thresholds.
    // Class 0: residual <= 10 (near-perfect fill) -> strong reward.
    // Class 1: 10 < residual <= 20 (still usable by smallest items) -> mild reward.
    // Class 2: 20 < residual <= 50 (dead zone) -> penalty.
    // Class 3: residual > 50 (large, flexible) -> mild reward.
    let cls = post_residual / 10;
    match cls {
        0 => score -= 30.0,
        1 => score -= 8.0,
        2 => score += 25.0 + (post_residual as f64 - 20.0) * 0.4,
        _ => score -= 5.0,
    }

    // Exact harmonic coupling: does post_residual match the next item size?
    // Perfect pairing -> big reward; near-miss -> slight penalty (wasted lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how "tight" the leftover-after-next would be
            let after_next = post_residual - next_item_size;
            if after_next <= 10 {
                score -= 25.0;
            } else if after_next <= 25 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: penalty scaled by wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 + gap * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // granularities (10, 20, 25) are more reusable.
    if post_residual > 0 && (post_residual % 10 == 0) {
        score -= 6.0;
    }
    if post_residual > 0 && (post_residual % 25 == 0) {
        score -= 4.0;
    }

    // New-bin candidate: only attractive when open bins are congested or
    // this bin's post-fit residual falls in the dead zone.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 100.0);
        // Penalize new bins moderately; relax late in stream or when residuals are fragmented.
        score += 35.0 - progress * 10.0 - congestion.min(20.0);
        if post_residual <= 20 {
            score -= 15.0; // fresh bin still beats dead-zone placement
        }
    }

    // Mild preference for filling more-congested bins (reduce open bin count).
    score -= (open_bins_count.min(50) as f64) * 0.2;

    // Small tie-breaker against large waste relative to capacity fraction.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    let min_item = 1u32; // items in [1,100]; treat tiny gaps (<10) as near-dead
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0; // unusable sliver penalty
    }
    // Medium gaps (10..30) are only usable by small items; mild penalty scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual >= 10 && post_residual < 30 {
        score += 8.0 + 12.0 * progress;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residual that still accommodates the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // would strand the next item's placement options
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: prefer bins whose residual is close to the mean (balance).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let waste_now = (bin_residual - item_size) as f64;
        if fitting_bins_count == 0 || waste_now < 10.0 || (next_item_size > 0 && waste_now < next_item_size as f64 && waste_now < 20.0) {
            score -= 15.0; // opening fresh is fine when nothing is wasted
        } else {
            score += 30.0 + waste_now; // don't open new bin when open bins fit well
        }
        score += open_bins_count as f64 * 2.0; // extra caution against bin sprawl
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 15 {
        score -= 120.0;
    }

    // 2-step lookahead: if next item exactly matches the post residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
            // extra reward when the pair nearly fills the bin
            if slack <= 10 {
                score -= 80.0;
            }
        } else {
            // next item will NOT fit here: penalize leaving a residual
            // that strands the lookahead item.
            score += 60.0;
        }
    }

    // Compare post residual against mean residual of open bins:
    // leaving less residual than average is good (bin nearly consumed).
    let cap = bin_capacity as f64;
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 0.5 {
            score -= 60.0 * (0.5 - ratio);
        } else if ratio > 1.5 {
            score += 40.0 * (ratio - 1.5);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is
    // large and would leave a very small residual in existing bins anyway.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // residual of fresh bin
        score += 300.0;                 // base cost of opening a new bin
        if item_size >= 80 {
            score -= 250.0;             // large items justify fresh bins
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 100.0;             // fresh bin can host the next item too
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 30.0 * progress * (open_bins_count as f64 / (cap / 10.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Base preference: tight fits (low post_residual) already favored.

    // Reward near-perfect fits strongly (post_residual small relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that cannot fit the average next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item
        score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of all open bins; penalize more
        // when many bins are open and residuals are large.
        let waste = open_bins_count as f64 * mean_residual;
        score += 12.0 + 0.05 * waste;
        // Late in the stream, prefer consolidating into open bins
        score += 10.0 * progress;
        // But if the item is huge, a fresh bin is natural
        score -= (item_size as f64 / bin_capacity as f64) * 8.0;
    }

    // Mild preference for bins below mean residual (balancing residuals)
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Discourage leaving exactly awkward small residuals (hard to fill later)
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping
    let base = pr * (1.0 + 0.8 * norm_pr * norm_pr) - 0.35 * norm_pr * cap;

    // Smooth progress coupling: later in stream, tighter packing preferred
    let progress_coupling = -8.0 * (progress * (1.0 - progress) * 4.0) * (1.0 - norm_pr);

    // Dead-space penalty: small post-residual that can't fit typical items
    let dead = if pr > 0.0 { -6.0 * (-pr / 15.0).exp() } else { -4.0 };

    // Last-chance bonus
    let last_chance = if fitting_bins_count == 1 { -12.0 } else { 0.0 };

    // Lookahead: reward residual that fits next item
    let lookahead = if next_item_size > 0 && pr >= next_item_size as f64 {
        -5.0 * (1.0 - pr / cap)
    } else if next_item_size > 0 {
        3.0 * (next_item_size as f64 - pr) / cap
    } else {
        0.0
    };

    // Mean residual deviation coupling
    let dev = (pr - mean_residual) / cap;
    let dev_term = 4.0 * dev * dev - 3.0 * dev;

    // Open bins pressure: many open bins -> discourage spreading
    let spread = 0.05 * open_bins_count as f64 * norm_pr;

    base + progress_coupling + dead + last_chance + lookahead + dev_term + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on a
    // "clean" residue class (multiples of 10 / small remainders) are more
    // reusable, so reward them.
    let r = post_residual % 10;
    score -= match r {
        0 => 8.0,
        1..=3 => 2.0,
        _ => 0.0,
    };

    // Penalize large-but-awkward dead space (too big to waste, too small to use).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect or near-perfect fills are gold.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely: reward proportionally to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 15.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this bin's leftover: penalize dead space.
            score += 6.0 + 0.1 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded or
    // the fit here is terrible. Base cost of opening a bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / 8.0;
        let poor_fit = if post_residual < 20 { 15.0 } else { 0.0 };
        score += 60.0 + crowding * 5.0 - poor_fit - 20.0 * progress;
        // Empty bin wastes full capacity unless item is huge.
        score += 0.3 * (bin_capacity - item_size) as f64;
    }

    // Prefer tighter fits among open bins: reward small post residual
    // relative to current residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Mean residual context: if this bin is below-average residual (tighter),
    // favor filling it.
    score += 0.15 * (mean_residual - post_residual as f64);

    // Harmonic threshold classes on post_residual via integer division.
    let class = post_residual / 25; // 0..4
    score -= match class {
        0 => 5.0,          // nearly full bin: great
        1 => 2.0,
        2 => 0.0,
        _ => -1.0,         // mostly empty open bin: mild reward to fill it
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins and encourage consolidation.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        score += 35.0 * pressure;
    } else {
        score -= 8.0 * pressure;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap that barely misses the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (keeps balance).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Late in the stream, avoid opening new bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack (<= 10)
    else if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
        score -= 35.0 - (post_residual - next_item_size) as f64 * 2.0;
    }
    // Next item cannot use this residual: penalize proportionally
    else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Dead space: unusable residual (smallest item is ~1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Zero residual is a perfect closure
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current residuals are large/wasted
    if bin_residual == bin_capacity {
        score = 100.0 + mean_residual * 0.5 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 80.0; // big next item: fresh bin may be wise
        }
    }

    // Mild pressure toward consolidating into fuller bins over time
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is already low; amplify.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill bonus
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 4.0; // awkward dead zone
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 2.0 * ((next_item_size - post_residual) as f64 / (bin_capacity as f64));
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (bin_residual - item_size) as f64 / (bin_capacity as f64);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when few bins are open or mean residual is low
        // (existing bins are nearly full). Penalize when open bins have slack.
        score += 20.0;
        score -= 1.5 * mean_residual;
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Early in stream, new bins are cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= 0.05 * item_size as f64;
    }

    // Prefer filling bins that already deviate below mean residual (balance avoidance):
    // bins with residual below mean are "committed" — finishing them is good.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.5 * dev;
    }

    // Mild penalty for very large post_residual left in a mostly-empty bin
    // when many bins are already open (fragmentation control).
    if open_bins_count > 4 && post_residual > 50 {
        score += 0.1 * (post_residual - 50) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;
    // Smooth non-linear coupling: quadratic dead-space penalty scaled by progress
    let dead = fit_ratio * fit_ratio * (0.5 + progress);
    // Reward tight fits (low post_residual) more strongly as stream progresses
    let tight_reward = (1.0 - fit_ratio).powi(3) * (2.0 + 3.0 * progress);
    // Last-chance bonus: strongly favor the only fitting bin
    let last_chance = if fitting_bins_count == 1 && bin_residual < bin_capacity { 6.0 } else { 0.0 };
    // Lookahead: penalize if post_residual can't fit next item but could have
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx && bin_residual >= nx { 2.0 * (1.0 - progress) } else { 0.0 }
    } else { 0.0 };
    // Slight preference for bins with lower residual than mean (consolidation)
    let mean_term = (mean_residual - bin_residual as f64) / cap * 0.5;
    // New-bin candidate: mild penalty so open bins are preferred unless very poor fit
    let new_bin = if bin_residual == bin_capacity { 3.0 + 4.0 * progress } else { 0.0 };
    base + dead * cap * 0.2 - tight_reward + last_chance + lookahead - mean_term + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: which capacity fraction band does it land in?
    let q = post_residual / (bin_capacity / 4); // 0..=4 integer class
    match q {
        0 => score -= 12.0,               // nearly perfect fit: residual < C/4
        1 => score -= 4.0,                // decent
        2 => {}                           // neutral
        3 => score += 3.0,                // wasteful band
        _ => score += 6.0,                // huge leftover
    }

    // Lookahead: does next item fit exactly / well into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin's leftover: penalize by how much dead space remains
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += cap * 0.6;
        // early in stream: more willing to open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= (1.0 - progress) * cap * 0.35;
        // many open bins with high mean residual: discourage adding another
        score += open_bins_count as f64 * 0.8;
        if mean_residual > item_size as f64 {
            score += 10.0; // existing bins have room; use them
        }
        // large next item: opening fresh bin may pay off
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Modulo-5 harmonic tiebreak on post_residual to break ties consistently
    let m = post_residual % 5;
    score -= m as f64 * 0.3;

    // Mild preference for fuller bins overall
    score -= (bin_residual as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 10, or known next item)
    // can ever use are pure waste — penalize them hard.
    let min_item = 10u32;
    let usable_floor = if next_item_size > 0 && next_item_size <= post_residual {
        next_item_size
    } else {
        min_item
    };
    if post_residual < usable_floor {
        // dead space: gap too small for anything useful
        score += 60.0 + (usable_floor - post_residual) as f64 * 4.0;
    }

    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= min_item {
        score -= 80.0;
    } else if post_residual == next_item_size && next_item_size > 0 {
        score -= 70.0; // leaves exactly the room the next item needs
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < min_item {
        score -= 40.0; // next item makes this bin perfect
    }

    // Reward filling a large fraction of the bin.
    let fill = (item_size as f64) / (bin_capacity as f64);
    score -= fill * 30.0;

    // Last-chance bonus: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins;
    // with few open bins, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (6.0 + 8.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when current bin fit is bad,
        // penalized when open bins are numerous.
        score += 18.0 + pressure;
        // A new bin is fine if the item is large and would leave a clean residual.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Existing bin: mild reward scaling with open-bin pressure (consolidation).
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual is already tight (waste containment).
    if bin_residual < mean_residual {
        score -= (mean_residual - bin_residual).min(30.0) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0; // perfect chain: this bin then next item fills it completely
    } else if next_item_size > 0 && post_residual > next_item_size {
        // next item still fits after: partial reward, closer match = better
        let slack = (post_residual - next_item_size) as f64;
        score -= 45.0 * (-slack / 25.0) * (1.0 - slack / (bin_capacity as f64)).max(0.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot follow in this bin: penalize small dead space
        let dead = (next_item_size - post_residual) as f64;
        score += 12.0 * (1.0 - dead / 100.0); // small gaps are the worst waste
    }

    // Reward bins whose residual is already tight relative to mean residual
    if mean_residual > 0.0 {
        let tightness = 1.0 - (post_residual as f64 / mean_residual).min(2.0) / 2.0;
        score -= 8.0 * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be
    // left with unusable tiny residual or the lookahead fits perfectly in new bin
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size >= item_size && item_size + next_item_size <= bin_capacity {
            score -= 25.0; // fresh bin can host a perfect pair
        }
    } else if post_residual < 10 {
        score -= 15.0; // nearly full bin: great outcome, lock it in
    }

    // Early in stream, be slightly more willing to open bins (build diversity)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress);

    // Many open bins: prefer consolidation into existing bins
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 25.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 10.0 * fit_ratio;
    }

    // Dead-space penalty: small post_residual that cannot fit typical future items is fine,
    // but mid-range waste is bad. Penalize post_residual in the "awkward" zone.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 15.0; // nearly perfect closure
    } else if pr >= 10.0 && pr <= 30.0 {
        score += 8.0; // awkward dead space
    }

    // Lookahead: reward if the next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // mild bias against opening new bins early; stronger when many bins are open
        score += 20.0 + 2.0 * open_bins_count as f64;
        // but if the item is huge, a fresh bin is natural
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer consolidating into
    // bins with large residuals (spread usage evenly).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in the stream, be more conservative — prefer tight fits
    // and discourage new bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * fit_ratio;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) + norm_post * (1.0 - progress) * (1.0 - progress);
    let mut score = post * (1.0 + 0.5 * poly);
    // Penalize large dead space late in the stream (smooth cubic coupling)
    score += 20.0 * norm_post.powi(3) * progress;
    // Reward tight fits, stronger when this is the only fitting bin
    let tightness = 1.0 - norm_post;
    score -= 15.0 * tightness * tightness * (1.0 + (fitting_bins_count == 1) as i32 as f64);
    // Lookahead: favor bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score += 0.3 * gap * gap / cap;
    }
    // Slight penalty for opening a new bin when open bins exist and stream is early
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 * (1.0 - progress);
    }
    // Mild diversity term relative to mean residual
    score += 0.05 * (post - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot size" class it falls into.
    // Small post_residuals are good (tight fit); residuals that align with common
    // item-size classes (multiples of 10, 25, 50) remain reusable.
    let harmonic_class = post_residual / 10; // 0..=10 classes
    let class_bonus = match harmonic_class {
        0 => 60.0,               // perfect fit
        1 => 30.0,               // residual 10..19, still very reusable
        2 => 18.0,
        3 => 12.0,
        4 => 8.0,
        5 => 6.0,                // half-full: very flexible
        6 | 7 => 3.0,
        8 | 9 => 1.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Penalize post_residuals that are "dead space": too small for the smallest
    // plausible item but nonzero. Harmonic dead-zone: 1..=9 residual is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how well next item fits
            let next_post = post_residual - next_item_size;
            if next_post < 10 {
                score -= 20.0;
            } else {
                score -= (next_post as f64).recip() * 40.0;
            }
        } else {
            // next item cannot follow into this bin; mild penalty if post_residual
            // is small (bin nearly sealed is fine, but wasted small gap is bad)
            if post_residual > 0 && post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // existing bin gives a tight fit. Make the empty-bin candidate moderately
    // attractive so it beats very loose fits but loses to tight fits.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: its residual is maximal (100) which already
        // scores high; add a fixed opening penalty modulated by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 20.0 * (1.0 - progress);
        // if many bins are open and mean residual is high, prefer reusing
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Modulo-25 harmonic alignment: residuals divisible by 25 pair well with
    // medium items (25/50/75).
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Mild preference to keep many open bins balanced when few bins exist.
    if open_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Tight-fit bonus scaled by item size class (larger items deserve tighter fits).
    let item_class = item_size / 20; // 0..4
    score -= (100 - post_residual.min(100)) as f64 * (0.05 + 0.02 * item_class as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // the smallest possible item (size 1..10) are pure waste; penalize
    // the "unusable gap" band aggressively.
    let gap = post_residual as f64;
    if post_residual < 10 {
        score += 60.0 * (10.0 - gap); // tiny dead space is very costly
    } else if post_residual < 20 {
        score += 25.0 * (20.0 - gap);
    } else {
        // Smooth quadratic penalty for larger leftovers, scaled by how
        // far below the mean residual this bin sits (tight bins rewarded).
        score += 0.05 * gap * gap / bin_capacity as f64;
    }

    // Reward filling bins that are already quite full (post_residual small
    // relative to residual => high utilization of remaining space).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fill_ratio * fill_ratio;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into new bins; with few open bins, be more permissive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // unless the current bin would leave a terrible gap.
        score += 30.0 + 8.0 * pressure;
    } else {
        score -= 5.0 * pressure;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0; // next item fills this bin almost perfectly
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0; // next item cannot use the tiny gap we leave behind
    }

    // Mild tie-break toward bins below mean residual (keep tight bins tight).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual gets extra discount).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64);
        score -= 10.0 * (1.0 - gap * gap).max(0.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating dead space that cannot host the next item.
        score += 4.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (concentrating waste in few bins) when post_residual is large.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize slightly so it's chosen only when
    // open bins would create large dead space; relax late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 3.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Perfect or near-perfect fit gets an extra bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Penalize leaving large awkward dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead * dead;

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // since that chains two items into one bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 14.0 * chain_fit;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize creating a residual that is too small for anything useful
        // (below the minimum plausible item size range).
        if post_residual < 8 {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global state: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    if open_bins_count > 2 {
        let consolidation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 8.0 * consolidation * (open_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals flexible); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * (1.0 - progress) * dead;      // early: penalize bad fits more mildly
    score -= 6.0 * progress * fill_ratio;         // late: reward tight fills more

    // New-bin candidate handling: an empty bin has neutral baseline; make it
    // attractive only when it would waste less than using a poorly-fitting bin.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.4 * (post_residual as f64);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 60.0; // must open first bin
        }
        if fitting_bins_count == 0 {
            score -= 15.0; // no open bin fits anyway
        }
        // Late in the stream, discourage opening new bins unless necessary.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with smooth non-linear shaping.
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate larger residuals; late, penalize waste more aggressively.
    let waste_penalty = (pr / cap).powi(2) * (1.0 + 2.0 * progress);
    score += waste_penalty * cap * 0.5;

    // Reward near-perfect fits with a smooth superlinear discount.
    let tightness = 1.0 - (pr / cap);
    score -= tightness.powi(3) * cap * 0.3;

    // Lookahead: reward residual that can still fit the next item (keeps bins usable),
    // penalize residuals that strand space smaller than the next item's need.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= (nx / cap) * 15.0;
        } else {
            score += (1.0 - pr / nx.max(1.0)) * 10.0 * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Slight preference for bins with residuals close to the mean (balance load),
    // smoothly scaled by number of open bins.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * (1.0 + (open_bins_count as f64).ln().max(0.0)) * 3.0;

    // New-bin candidate: penalize mildly so it's chosen only when no bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Harmonic class of post_residual: integer division thresholds (capacity fractions).
    // Classes: dead zone (1..=9), small (10..=19), medium (20..=49), large (50..=100).
    let class = if post_residual == 0 { 0u32 }
        else if post_residual < 10 { 1 }
        else if post_residual < 20 { 2 }
        else if post_residual < 50 { 3 }
        else { 4 };

    // Reward exact fit and near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 120.0 + (10 - post_residual) as f64 * 10.0;
    }

    // Modulo arithmetic on post_residual: residual divisible by common item sizes
    // (10, 20, 25, 50) is more likely reusable by future items.
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
    if reusable {
        score -= 15.0 + post_residual as f64 * 0.1;
    } else {
        // Penalize awkward residuals in the dead zone (1..=9) — likely wasted.
        if post_residual >= 1 && post_residual <= 9 {
            score += 40.0;
        }
    }

    // Coupling with next_item_size: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + (next_item_size as f64) * 0.2;
        } else {
            // Penalize creating residual just below the next item's need (near-miss waste).
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 25.0 + (10 - gap) as f64 * 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // With several options, tighten competition: weight post_residual more.
        score += post * 0.3;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    // or mean residual across open bins is very low (fragmented bins).
    if bin_residual == bin_capacity {
        // Fresh bin gets post_residual = capacity - item; make it moderately attractive
        // only if the item is large relative to capacity or open bins are fragmented.
        let fragmentation = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item / cap;
        let attractiveness = 60.0 * fragmentation + 40.0 * large_item;
        // Fresh bin baseline: slightly worse than a well-fitting open bin.
        score += 50.0 - attractiveness;
    }

    // Progression-based modulation: late in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (cap - post) * 0.2;

    // Mean residual coupling: if open bins already hold lots of residual space,
    // discourage adding another loose bin (prefer filling existing space).
    if bin_residual != bin_capacity {
        score += (mean_residual - post).max(0.0) * 0.15;
    }

    // Harmonic penalty via modulo class of item size: items ≡ 0 mod 10 pack classically well.
    if item_size % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Medium dead space (10..20) is risky: only items >=10 fit, penalize mildly.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }
    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Reward if the leftover gap can fit the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if leftover gap is smaller than the minimum plausible item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose residual is close to the item need
    // (tight packing), penalize wasting large-residual bins on small items.
    let waste = bin_residual as f64 - item_size as f64;
    score += 0.15 * (waste - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when no tight fit exists
    // (i.e., this placement would leave a large awkward residual in an existing bin).
    if bin_residual == bin_capacity {
        // Baseline: new bin is neutral-ish; reward scales with how bad existing fits are.
        score = 55.0 + 0.2 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // lookahead suggests pairing similar items in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            // Perfect chain: this bin will be exactly filled by the next item.
            score -= 60.0 + 0.5 * item_size as f64;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mild reward proportional to tightness.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize dead space relative to next size.
            score += 0.25 * (nxt - post_residual as f64);
        }
    }

    // Favor tight fits overall (small post_residual relative to item size).
    score -= 0.6 * (item_size as f64 / bin_capacity as f64) * (bin_capacity as f64 - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins unless current bins fit poorly.
        score = 55.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits, must open
        } else if next_item_size > 0 && post_residual >= next_item_size as u32 {
            // Opening a fresh bin guarantees room for the next item.
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    } else {
        // Coupling with mean residual: bins deviating above mean waste space.
        score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
