    // fits are poor or mean residual is high (fragmented bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = fitting_bins_count == 0 || fit_ratio < 0.35;
        if poor_fits || mean_residual < item_size as f64 {
