pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 30.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }
    // Reward tight fits generally: residual close to zero relative to capacity.
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(2) * 40.0;

    // Dead space is worse if the next item cannot use it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    }
    // Bonus if the leftover exactly accommodates the next item (chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (8.0 + 10.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is already below the mean (consolidating fuller bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: open a fresh bin only when no decent fit exists.
    if bin_residual == bin_capacity {
        // Penalize new bins when the item fits reasonably well somewhere else.
        let decent_fit = post_residual >= 0 && item_size as f64 >= 0.5 * bin_capacity as f64;
        if fitting_bins_count > 0 {
            score += if decent_fit { 250.0 } else { 60.0 };
        } else {
            score -= 150.0; // forced opening anyway
        }
        // Late in the stream, opening new bins is more costly.
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 200.0;
        // Extra reward for near-exact match with next item
        let gap = post_residual - next_item_size;
        score -= (bin_capacity as f64 - gap as f64) * 0.5;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use
        score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.3;
    }

    // Penalize small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare residual to mean residual: prefer filling fuller bins
    score -= (bin_capacity as f64 - mean_residual) * 0.2;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New bin candidate handling: penalize opening a new bin mildly unless current residuals are poor
    if bin_residual == bin_capacity {
        score += 50.0;
        // But if open bins have high mean residual mismatch, new bin is fine
        if mean_residual > (bin_capacity as f64) * 0.5 {
            score -= 80.0;
        }
    }

    // Progression: later in stream, slightly prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0;

    // Large item in nearly full bin is good (wastes less)
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual < 10 && post_residual > 0 {
        score += 18.0; // near-full bin is fine, but tiny slivers are wasted
    }
    if post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Perfect chain fit bonus
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // This placement blocks the next item slightly; penalize proportionally.
            let blocked = (next_item_size - post_residual) as f64;
            score += 0.15 * blocked;
        }
        // If next item is large, prefer leaving large residuals.
        if next_item_size >= 50 {
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_f = open_bins_count as f64;
    score -= 0.05 * open_f;

    // Mean residual coupling: prefer bins whose residual is close to the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: early in the stream, be conservative (favor new bins
    // less); late in the stream, squeeze existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - tightness);

    // New-bin candidate handling: penalize opening a new bin, but allow it
    // when existing bins would leave very poor fits or when the item is large
    // and no bin is tight.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 20.0;
        // If item is large and would leave a big residual anyway, new bin is attractive.
        if item_size >= 60 {
            new_bin_penalty -= 8.0;
        }
        // If all fitting bins are poor (this bin is one of few options), soften.
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 10.0;
        }
        // Early stream: opening bins is cheap; late stream: avoid it.
        new_bin_penalty *= (1.0 + 1.5 * progress);
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post residual, normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let poly = prn * prn * (1.0 - prn); // peaks at prn = 2/3, penalizes mid-range waste
    score += 12.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - prn;
    score -= 4.0 * tightness * tightness * (0.5 + progress);

    // Penalize post residual that cannot fit the next item (dead space coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (1.0 - pr / nxt) * (1.0 - 0.5 * progress);
        } else {
            // Reward leaving exactly enough room for the next item
            let slack = (pr - nxt) / cap;
            score -= 2.0 * (1.0 - slack * slack);
        }
    }

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.3 * progress);
    }

    // Mild pressure to consolidate into many open bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near the mean (balance)
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // New-bin candidate: strong penalty so it is chosen only for large items
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // residue classes (multiples of small divisors) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 3.0; }
        if pr % 5 == 0 { bonus += 1.5; }
        // dead-space penalty for tiny unusable residues
        if pr < 10 { bonus -= 8.0; }
        else if pr < 20 { bonus -= 3.0; }
        score -= bonus;
    } else {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // fraction of post_residual consumed by next item
            let frac = next_item_size as f64 / pr.max(1) as f64;
            score -= 10.0 * frac;
            // harmonic coupling: next item leaves a multiple-of-10 residue too
            if (pr - next_item_size) % 10 == 0 { score -= 3.0; }
        } else {
            // next item cannot use this bin's remainder: penalize leftover
            score += 0.05 * (pr as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when current item
    // is large relative to capacity and open bins are fragmented.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap_f;
        let fragmentation = (mean_residual / cap_f).clamp(0.0, 1.0);
        // open new bin when item is big and existing residuals are small
        score = 30.0 - 20.0 * item_frac - 10.0 * fragmentation
            + 0.3 * open_bins_count as f64;
        // late in the stream, avoid spawning extra bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Mild preference for tighter existing bins overall
    score += 0.02 * (bin_residual as f64 - mean_residual);

    // Progress-based mild consolidation pressure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps (10..30) are only usable by small items; mild penalty.
    else if post_residual >= 10 && post_residual < 30 {
        score += 6.0;
    }

    // Reward tight fits (exact or near-exact).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score -= 10.0; // tolerate dead space rather than open a bin
        }
    }

    // New-bin candidate: opening a new bin is a last resort; add pressure that grows
    // with the number of open bins only mildly, but keep it costly overall.
    if bin_residual == bin_capacity {
        score += 60.0 + 2.0 * open_bins_count as f64;
        // If the next item is small, a fresh bin is slightly more attractive.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 15.0;
        }
    }

    // Lookahead: penalize placements that leave a residual just barely unable
    // to fit the next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        let miss = next_item_size as f64 - post_residual as f64;
        if miss <= 10.0 {
            score += 8.0 * (10.0 - miss);
        }
    }
    // Reward if next item fits exactly in the post residual.
    if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
        score -= 20.0;
    }

    // Open-bin count pressure: mildly discourage spreading across many bins.
    score += 0.3 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is below average
    // (fill the emptier-feeling bins first keeps big gaps consolidated).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
