pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize leaving residual that neither fits next item well
    // nor is useful; reward residual that can exactly host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.3 * slack; // residual slightly above next item is wasteful
            if post_residual == next_item_size {
                score -= 20.0; // chain exact fits
            }
        } else {
            // next item won't fit here; small residual is dead space
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Dead-space penalty: residuals too small for the minimum item (size 1..)
    // are less costly, but residuals in a "useless middle band" are penalized.
    let r = post_residual as f64;
    if r > 0.0 && r < 40.0 {
        score += 0.5 * (40.0 - r);
    }

    // Prefer filling bins with larger residuals (consolidate space) early;
    // late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0 * (1.0 - progress);

    // Global state: many open bins with high mean residual -> prefer reusing
    // existing bins over opening new ones.
    if bin_residual < bin_capacity {
        score -= 5.0 * (mean_residual / bin_capacity as f64).min(1.0);
        score -= 0.2 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when existing bins would leave
    // large post_residual or none fit well.
    if bin_residual == bin_capacity {
        let waste_elsewhere = mean_residual - item_size as f64;
        let penalty = if waste_elsewhere > 0.0 { 12.0 } else { 40.0 };
        score += penalty;
        // Early in stream, opening bins is fine; late, avoid fragmentation.
        score += 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, mildly compressed non-linearly
    let mut score = pr * (1.0 + 0.35 * norm_pr * (1.0 - norm_pr));

    // Smooth polynomial coupling of post_residual with stream progress
    let p_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += pr * (0.5 * p_poly - 0.25 * (1.0 - p_poly)) * norm_pr;

    // Penalize large dead space late in the stream (quadratic in progress)
    score += norm_pr * norm_pr * cap * (0.4 * p_poly + 0.2);

    // Reward tight fits: low post-residual gets subtractive bonus, stronger mid-stream
    score -= (cap - pr) * 0.15 * (1.0 - norm_pr) * (0.5 + p_poly);

    // Last-chance bin: strong reward so we don't open a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * p_poly;
    }

    // Lookahead: reward if next item fits in post-residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let fit_slack = (pr - ni) / cap;
            score -= 8.0 * (1.0 - fit_slack) * (0.4 + 0.6 * p_poly);
        } else {
            score += 5.0 * (ni - pr) / cap;
        }
    }

    // Mean residual coupling: prefer bins near mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Many open bins: prefer filling existing ones rather than opening more
    score += 2.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0) * norm_pr;

    // New-bin candidate: keep it slightly penalized unless post-residual advantage is big
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * p_poly;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Small post_residual = tight fit: reward strongly
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 40.0;
    } else if pr <= 20 {
        score -= 20.0;
    } else {
        // dead-space penalty grows for awkward residual sizes
        score += 0.15 * prf;
    }

    // Modulo arithmetic: residual classes that combine well with common item sizes
    // Items 1..100; residuals divisible into 4ths of capacity are "harmonic"
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr % quarter == 0 && pr > 0 {
        score -= 8.0; // harmonic residual, likely reusable
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }
    // Odd residuals in dead zone (just above half) are hard to fill
    if pr > half && pr < half + 20 {
        score += 6.0;
    }

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly-ish: reward if near-exact
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 30.0;
            } else if gap <= 10 {
                score -= 15.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: penalize if this bin was "reserved"
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin when current open bins are fragmented
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted when existing bins fit poorly
        score = cap * 0.5;
        let fragmentation = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 0.0 };
        // if mean residual is small (fragmented), new bin is attractive
        score -= 30.0 * (1.0 - fragmentation);
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 15.0; // nothing can take the next item anyway
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // forced new bin
        }
    }

    // Slight preference for fuller bins overall (best-fit flavor)
    score -= 0.05 * (cap - prf);

    // Stream progression: later in stream, be more conservative about new bins
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space below minimum item size
        } else if post_residual < 20 {
            score += 25.0; // nearly dead space for most distributions
        } else if post_residual < 30 {
            score += 10.0;
        }
    } else {
        score -= 40.0; // perfect fill: strongly reward
    }

    // Lookahead: penalize residuals that cannot host the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 18.0;
        } else {
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 30.0; // new-bin candidate penalty
        if fitting_bins_count > 0 {
            score += 12.0; // extra pressure when alternatives exist
        }
    } else {
        score -= 15.0;
        // Last-chance bin: using it avoids opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Tight-fit bonus: residual barely above item size means efficient packing.
    let slack = (bin_residual - item_size) as f64;
    if slack > 0.0 {
        score += slack * 0.1;
    }

    // Late-stream urgency: fill bins harder as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Reward bins already below average residual (consolidation).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core archetype: 2-step lookahead matching.
    // Reward placements where post_residual closely matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match (post_residual == next_item_size) gets a strong bonus.
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Exact 2-step chain: item + next fills the bin completely.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item cannot fit in the residual: dead space penalty, worse if large.
        if next_item_size > post_residual {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize waste directly.
        score += 5.0;
    }

    // Relative-to-mean coupling: bins with residual above mean are more valuable
    // to fill; bins already tight get a mild penalty for fragmenting further.
    let res = post_residual as f64;
    if res < mean_residual {
        score += 0.25 * (mean_residual - res);
    } else {
        score -= 0.15 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize creating tiny unusable slivers (dead space below typical item sizes).
    if res > 0.0 && res < 10.0 {
        score += 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in
    // the stream or when few bins are open; otherwise make it costly so existing
    // bins with decent fits are preferred.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // But if no open bin leaves room for the next item, opening fresh helps.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 20.0;
        }
    }

    // Slight preference for tighter fills overall (waste minimization).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let t = progress;
    // smooth interaction: dead-space penalty grows with progress
    score += prn * prn * (0.5 + 3.0 * t) * cap * 0.1;
    score -= (1.0 - prn) * (1.0 - prn) * (1.0 + 2.0 * t) * cap * 0.05;

    // Tight-fit reward (post residual near zero), stronger late in stream
    let tight = (-prn * 6.0).exp();
    score -= tight * (2.0 + 6.0 * t);

    // Lookahead: penalize if post residual can't fit next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (1.0 + 3.0 * t) * (ni - pr) * 0.5;
        } else {
            score -= (1.0 - (pr - ni) / cap) * 2.0 * (1.0 + t);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 4.0 + 4.0 * t;
    }

    // Mild preference for fuller bins relative to mean residual
    score -= (mean_residual - pr) * 0.15;

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * t + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: residues modulo 10 (dead-space granularity).
    let pr = post_residual;
    let class = pr % 10;
    // Perfect fits / tiny residuals are golden: strongly reward.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    } else if class == 0 {
        // post_residual is a multiple of 10: still a "harmonic" slot for typical items.
        score -= 8.0;
    } else if class <= 3 {
        score += 3.0 + class as f64;
    } else {
        // Large odd dead space is bad.
        score += (class as f64 - 5.0) * 2.5;
    }

    // Harmonic coupling: does next_item_size exactly consume post_residual, or its class?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == pr {
            score -= 45.0; // chain fit
        } else if next_item_size <= pr {
            // next item fits in the leftover: reward proportionally
            score -= 12.0 * (nx / (pr as f64));
        } else {
            // next item cannot use this residual: penalize large unusable leftovers
            score += 0.15 * (pr as f64).min(nx);
        }
        // Harmonic divisibility: next item divides capacity nicely
        if bin_capacity % next_item_size.max(1) == 0 {
            score -= 3.0;
        }
    }

    // Tight fit reward: item nearly fills the bin.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 20.0 * fill * fill;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open residuals are poor.
    if bin_residual == bin_capacity {
        // neutral baseline; open bins with decent residuals should beat it
        score = cap * 0.55 + mean_residual * 0.4;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits elsewhere: new bin is mandatory
        }
        if pr == bin_capacity {
            // empty-bin call: post_residual == capacity; keep it competitive but not dominant
            score = cap * 0.5 + mean_residual * 0.5;
        }
    }

    // Late in the stream, consolidate: favor bins close to mean residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space that likely can never be used
    } else if post_residual >= 10 && post_residual <= 25 {
        // small gaps that only fit the tiniest items: moderate penalty
        score += 15.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward closing the bin
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * next_tight;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // next item cannot use this gap: penalize leaving a gap
        score += 12.0;
    }

    // Open bins pressure: discourage spreading across many bins lightly.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Last-chance bin: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when
    // existing bins would leave bad dead space or the fit is poor.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; slight penalty so decent fits win,
        // but bonus removed when existing fits are terrible.
        score += 5.0;
        if post_residual < 20 {
            // item barely fits in fresh bin (huge item) — fine, no extra penalty
            score -= 10.0;
        }
    }

    // Stream progression: later in the stream, be slightly more conservative
    // about opening bins (fewer chances to fill leftovers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0;

    // Mean residual coupling: if average residual is high, prefer using
    // existing bins rather than opening new ones.
    score -= (mean_residual / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

