    // Mild preference for using existing bins over opening new ones early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

