}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits strongly (non-linear).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tight * tight * 30.0;

    // Penalize creating awkward dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // This bin could have held the next item but won't after placement.
        score += 8.0;
    }

    // Relative comparison to mean residual of open bins.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Prefer filling bins with many open bins (consolidation pressure).
    score += open_bins_count as f64 * 0.5;

    // Late in the stream, be more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., bin_residual == bin_capacity implies fresh bin).
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        // Fresh bin baseline: slightly worse than a decent fit, better than a bad one.
        score += 20.0 + early * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: raw post residual (waste after placement)
    let mut score = pr;

    // Non-linear penalty on large residuals: waste grows super-linearly
    let norm_pr = pr / cap; // 0..1
    score += 18.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Reward tight fits: small post_residual gets a smooth quadratic discount
    score -= 14.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: strongly reward if next item fits exactly in post_residual,
    // penalize if next item fits but leaves nothing, slight penalty otherwise
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let next_norm = next_item_size as f64 / cap;
        let leftover = pr - next_item_size as f64;
        score -= 10.0 * next_norm * (1.0 - leftover / cap);
    } else if next_item_size > 0 {
        // next item cannot use this residual: mild penalty scaled by progress
        score += 4.0 * progress * (pr / cap);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 - progress);
    }

    // Coupling with mean residual across open bins: prefer bins below mean residual
    // (fill the emptier bins first, keep tight bins for small items)
    score += 2.5 * (pr - mean_residual) / cap;

    // Many open bins: encourage consolidation into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes.
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty grows for "awkward" residual classes (1..9 non-zero remainders
    // are harder to fill with items >= 10, so penalize, but small nonzero remainders
    // (< 10) are pure dead space -> heavy penalty).
    if pr > 0 && pr < 10 {
        score += 40.0; // unusable sliver
    } else {
        // penalty by harmonic class distance from multiples of 10
        let m = class.min(10 - class) as f64;
        score += m * 1.5;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 60.0;
    }

    // Reward if next item fits exactly into post_residual (chained perfect fit)
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            // next item fits: penalize by leftover after next placement
            let pr2 = pr - next_item_size;
            score += pr2 as f64 * 0.4;
            if pr2 > 0 && pr2 < 10 {
                score += 15.0;
            }
        } else {
            // next item won't fit here: mildly reward closing bin with small residual
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when residuals are large/fragmented
    if bin_residual == bin_capacity {
        // baseline attractiveness of a fresh bin
        score = (bin_capacity - item_size) as f64;
        // open new bin early in stream or when many bins are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // if mean residual is small (bins nearly full), fresh bin is attractive
        score -= (bin_capacity as f64 - mean_residual) * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    } else {
        // prefer tighter existing bins: subtract for small bin_residual relative to item
        let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= tightness * 8.0;
    }

    // Mild bonus for placing into bins whose residual is in the same harmonic class as item
    if bin_residual % 10 == item_size % 10 && bin_residual >= item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

