    let dead_threshold = 10.0; // smallest item size historically
    if (post_residual as f64) < dead_threshold {
        score += 30.0 * (dead_threshold - post_residual as f64);
    }

    // Soft penalty for "awkward" residuals: gap barely above dead zone is risky.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 0.5 * (item_size as f64) / ((bin_residual as f64) + 1.0);
    }

    // Perfect fit: near-zero post residual gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing ones
    // (penalize the new-bin candidate, which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
