    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item fits within post_residual, mild bonus.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // Next item does NOT fit in the leftover: this bin's residual is likely
    // dead space for the next step -> penalize proportional to the gap.
    else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Late in the stream, avoid opening new bins even more (fewer chances
    // to fill them).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Mild tie-break: prefer bins with residual far below mean (consolidate
    // large gaps into few bins, keep near-full bins for small items).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

