    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: bin becomes exactly full after next item
        } else if post_residual >= next_item_size {
            // next item fits here too: mild reward scaled by how much slack remains after both
            let after_next = post_residual - next_item_size;
            score -= 25.0 - (after_next as f64 * 0.25);
        } else {
            // next item will NOT fit in this residual: penalize dead space that blocks the chain
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // last item: just prefer tightest fit
        score -= 10.0;
    }

    // Compare residual against mean residual across open bins:
    // favor bins whose residual deviates favorably (smaller residual = tighter bin).
    score += (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive late in the stream or when
    // the current bin would leave large unusable dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead_space = if next_item_size > 0 && post_residual < next_item_size {
            post_residual as f64
        } else {
            0.0
        };
        // New bin is penalized by default, but the penalty shrinks when the
        // alternative creates significant dead space relative to next item.
        let mut new_bin_score = 55.0 - progress * 15.0 - dead_space * 0.8;
        // If many bins are open and residuals are large, new bin is less costly.
        new_bin_score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        // If next item fits perfectly in the residual of a fresh bin, boost appeal slightly.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 5.0;
        }
        score = score.min(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
