    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Many open bins: prefer consolidating into existing bins
    let open_f = open_bins_count as f64;
    score += 0.3 * open_f;

    // Compare against mean residual: bins with residual near mean are neutral,
    // bins far below mean (nearly full) are preferred targets
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in stream, be more conservative (penalize tight packing
    // that could waste space later); late in stream, close bins aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * fill;
    score += (1.0 - progress) * 0.02 * post_residual as f64;

    // New-bin candidate handling: only attractive when item is huge relative to
    // capacity or no good existing option exists (encoded via high base cost)
    if bin_residual == bin_capacity {
        score += 25.0; // default: prefer existing bins
        if item_size as f64 > 0.8 * cap && fitting_bins_count == 0 {
            score -= 40.0; // huge item with no alternatives: open new bin
        }
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // that grows super-linearly for large wasted space.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: early in the stream, keep bins flexible
    // (penalize tight fits slightly); late in the stream, reward tight fits.
    let flex = (1.0 - progress) * (1.0 - progress);
    let tight_bonus = (1.0 - norm_pr) * (1.0 - norm_pr) * cap;
    score += flex * 0.6 * (norm_item * cap) - (1.0 - flex) * 0.8 * tight_bonus;

    // Dead-space penalty: post-residual that is too small to be useful later
    // (smooth sigmoid-like term around half the mean item scale).
    let dead = (pr as f64 / (mean_residual.max(1.0))) ;
    score -= 5.0 * (dead / (1.0 + dead)) * (1.0 - norm_pr);

    // Lookahead coupling: reward if post-residual can accommodate the next item
    // (smooth kernel rather than hard comparison).
    if next_item_size > 0 {
        let fit_kernel = (norm_pr / (norm_next + 0.05)).tanh();
        score -= 6.0 * fit_kernel * (1.0 - progress);
    }

    // Last-chance bin: if only this bin fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: bins partitioned by residual class via integer division.
    // Class width 10; classes with small residuals are "dead zones" -> penalize leaving them.
    let class = post_residual / 10; // 0..=10
    // Dead-space penalty grows sharply for tiny residuals (unusable slivers).
    if post_residual > 0 {
        score += match class {
            0 => 8.0,
            1 => 4.0,
            2 => 2.0,
            3 => 1.0,
            _ => 0.0,
        };
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Reward exact harmonic alignment: post_residual divisible by common item sizes.
    if post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual class?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can follow here: reward proportionally to tightness of the pair.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 6.0;
            score += pair_waste * 0.08;
            // Harmonic bonus: next item lands in a "clean" class too.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here: this bin likely becomes a stranded small residual.
            score += 3.0 + (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bonus: only this bin fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin only when current item is large and open bins are fragmented,
        // or late in stream with many open bins (avoid needless fragmentation early).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize opening a new bin mildly; heavier when bins are still roomy.
        score += 15.0 + fragmentation * 20.0 + progress * 5.0;
        // But if item is huge (>70), a fresh bin is often best.
        if item_size > 70 {
            score -= 10.0;
        }
    }

    // Mild pressure to use bins with residuals close to mean (balance load).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.02;

    // Prefer using more-opened bins rather than proliferating.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, item_size) are unusable
    // for any realistic item (min size 1..100 unknown, but small gaps waste).
    // Penalize sharply when post_residual is small but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        // awkward mid zone: mildly penalize
        score += 0.6 * (post_residual as f64 - 10.0);
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing bins fit poorly and open-bin pressure is low.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // more open bins -> more pressure to fill them, penalize new bin
        score += 3.0 * (open_bins_count as f64).sqrt();
        // if other bins fit, discourage new bin unless item is large
        if fitting_bins_count > 1 {
            score += 20.0;
        }
        // early in stream, new bins are cheap; later, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Coupling with mean residual: if this bin's post placement leaves it
    // far below the mean residual, it's a wasteful placement.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space guaranteed for next item
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly fit the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Residual can host next item; mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 / (1.0 + slack / 10.0);
        } else {
            // Dead space relative to next item: penalize small leftovers harder.
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.8;
        }
    }

    // Penalize tiny unusable residuals (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 15.0;
    }

    // Relative-to-mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current bin would leave big waste
    // or no open bin fits well; make the empty bin moderately costly otherwise.
    if bin_residual == bin_capacity {
        score += 50.0;
        if next_item_size > 0 && post_residual as f64 > mean_residual + 30.0 {
            score -= 60.0;
        }
        if open_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Early in stream, be slightly more open to new bins (exploration of capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit preference: tighter residual wins (non-linear).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that no future item can plausibly fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 10.0; // next item won't fit here after placement
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // Prefer new bin when mean residual is low (bins nearly full)
        // and there are already many bins; otherwise penalize opening.
        score += 55.0 - 45.0 * (1.0 - crowding) + 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if post_residual < item_size {
            score += 80.0; // empty bin always leaves good residual; keep stable
        }
    }

    // Prefer bins below mean residual (consolidate fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for fewer open bins late in the stream.
    score += open_bins_count as f64 * 0.05 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = base * base * (1.0 + 3.0 * progress) + base * (1.0 - progress);

    let mut score = pr as f64 * (1.0 + 0.5 * progress) + 40.0 * poly;

    // Penalize wasted space relative to mean residual
    score += 0.3 * (pr as f64 - mean_residual).abs();

    // Reward tight fits (low post residual), stronger late in stream
    score -= (1.0 - base) * (10.0 + 30.0 * progress);

    // Last-chance bin: strong bonus to use it
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 15.0 * (1.0 - diff / cap).max(0.0);
        // penalize leaving residual too small for next item
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 8.0 * (1.0 - pr / cap);
        }
    }

    // New-bin candidate: prefer opening a new bin only when fits are poor
    if bin_residual == bin_capacity {
        let badness = if fitting_bins_count > 0 {
            (mean_residual / cap).max(0.0)
        } else { 1.0 };
        score = cap * (0.6 + 0.4 * progress) - 30.0 * badness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction does it fall in?
    let eighth = (bin_capacity / 8).max(1);
    let class = match post_residual / eighth {
        0 => 0.0,              // near-perfect fit
        1 => -0.5,
        2 => 0.5,
        3 => 1.5,
        4 => 2.0,              // half-empty bin: worst dead space
        5 => 1.0,
        6 => 0.0,
        _ => -1.0,             // nearly empty bin (fresh or barely used)
    };
    score += class * (cap * 0.08);

    // Reward exact fit strongly
    if post_residual == 0 {
        score -= cap * 1.5;
    }

    // Lookahead coupling: does post_residual still fit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic sub-class: how well does next item fill leftover?
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= ratio * cap * 0.35;
        } else {
            // dead space for the lookahead item: penalize more when gap is small
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
            score += (gap as f64).min(20.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.6;
    }

    // New-bin candidate: give it a moderate score so it wins only over bad fits
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64).ln().max(0.0) * 4.0;
    } else {
        // Slight bonus for packing into fuller bins (waste-minimizing)
        let fullness = 1.0 - (bin_residual as f64) / cap;
        score -= fullness * cap * 0.25;
    }

    // Mild early-stream preference for consolidating into few bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize medium dead space less harshly; tiny gaps are the worst.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.5 * open_bins_count as f64;
        // But allow new bin if no existing bin fits well (last-chance logic).
        if fitting_bins_count == 1 && post_residual < 30 {
            score -= 35.0;
        }
    }

    // Last fitting bin: strong reward to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward leaving space that can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Slight preference for using bins with lower mean residual (tighter bins).
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Late-stream consolidation: favor existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Post residual large enough for next item: good, mild reward scaled by slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack.min(10.0) * 0.3;
    }
    // Dead space: post_residual too small for next item -> penalize proportionally.
    else if next_item_size > 0 {
        let waste = next_item_size as f64 - post_residual as f64;
        score += waste * 0.8;
    }

    // Penalize tight fits that leave near-zero unusable residue when next item exists.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 5.0;
    }
    // Exact fill (no waste) is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Compare post_residual against mean residual: leaving more than average is wasteful.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if no open bin fits well (item large relative to capacity), opening is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Late in the stream: consolidate, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on leftover space.
    let pr = post_residual as f64;
    score += 0.65 * pr * pr / cap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Mild bonus when several bins compete; tightness already decides.
        score -= 3.0;
    }

    // Lookahead (k=2): penalize creating residual that cannot host the next item
    // (dead space), but reward residual that can exactly host it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = pr - ni;
            score -= 8.0;
            score += 0.25 * slack; // prefer next-item fit with minimal extra slack
        } else if pr > 0.0 {
            // dead space for the lookahead item
            score += 0.9 * (ni - pr);
        }
    }

    // Penalize bins far from the mean residual when they are wasteful,
    // favor bins whose residual is close to the item (best-fit style).
    let fit_gap = (bin_residual as f64 - item_size as f64);
    score += 0.35 * fit_gap;

    // Global-state coupling: when many bins are open and mean residual is small,
    // discourage fragmenting; when mean residual is large, encourage consolidation.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual - pr).abs();
    score += 0.20 * consolidation * (0.5 + t);

    // Time horizon: late in the stream, be greedier about tight fits.
    score -= 10.0 * t * (1.0 - pr / cap);

    // New-bin candidate: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * item_size as f64 - 20.0 * t;
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 6.0; // a fresh bin also accommodates the next item
        }
        if fitting_bins_count <= 1 {
            score -= 55.0; // opening a bin is clearly better than forced fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let t = progress;
    score += 12.0 * norm_pr * norm_pr * (0.5 + t);
    score -= 6.0 * norm_pr * t * (1.0 - t);
    // penalize large dead space as stream advances
    score += 8.0 * norm_pr * t * t;
    // reward tight fits
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - t);
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 4.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 5.0;
        }
    }
    // discourage opening new bins when open bins are roomy
    score += (open_bins_count as f64) * 0.3 * (1.0 - t);
    // deviation from mean residual
    score += 0.5 * (pr - mean_residual).abs() / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small dead-space" classes (0..=10, or exact multiples of 10) are ideal.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fit
    } else if pr <= 10 {
        score -= 12.0 + (10 - pr) as f64;
    } else {
        // dead-space class: how far post_residual is from the next multiple of 10
        let class_off = 10 - (pr % 10);
        score += class_off as f64 * 0.8;
        // large unusable residuals are dangerous
        if pr > 50 {
            score += (pr - 50) as f64 * 0.3;
        }
    }

    // Lookahead: if next item can fit into post_residual, reward keeping this bin usable.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: next item pairs well with leftover
            let pair = pr - next_item_size;
            score -= 8.0;
            if pair % 10 == 0 && pair > 0 {
                score -= 5.0; // harmonic completion
            }
            if pair <= 10 {
                score -= 4.0;
            }
        } else {
            score += 6.0; // leftover likely becomes dead space
            // penalize more if leftover is in awkward class
            if pr % 10 != 0 && pr > 10 {
                score += 3.0;
            }
        }
    }

    // Last chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing ones rather than opening new.
    if open_bins_count > 3 {
        score -= 2.0;
    }

    // Early in stream, keep flexibility: penalize near-full fills less later on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if pr > 0 && pr < 5 {
        score += 5.0 * (1.0 - progress); // tiny residuals less useful early
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    // New-bin candidate: neutral-ish baseline; only win when all open bins are bad.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 30.0;
    }
    // Perfect fit gets strong reward
    if post_residual == 0 {
        score -= 200.0;
    }
    // Post residual that can fit the lookahead item is valuable
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.8 + 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space relative to next item
        score += next_item_size as f64 * 0.5;
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 2.5 * (0.5 + progress);

    // Prefer bins tighter than average (good fits)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it unattractive unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * -1.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, opening new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral baseline, slightly penalized so
    // decent fits in open bins win, but competitive when fits are bad.
    if bin_residual == bin_capacity {
        return score + 8.0;
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual
    // to the next item (perfect two-item packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 14.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize creating dead space smaller than the next item (unusable).
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins with residuals above the mean (keep large spaces alive),
    // penalize consuming below-mean residual space.
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Tight fits are good: reward small post residuals non-linearly.
    score -= 10.0 * (-post_residual as f64 / 25.0).exp();

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual (dead-space suppression).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness) * (item_size as f64 / bin_capacity as f64);

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead (k=2): reward if the next item also fits in the post-residual (chaining),
    // penalize if post-residual is a "trap" that fits nothing useful.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        }
        // Dead space trap: post-residual too small for next item but non-zero.
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size.max(1) as f64));
        }
    } else {
        // Last item: absolutely prefer zero post-residual.
        score += (post_residual as f64) * 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when global
    // residuals are large (existing bins are fragmented) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / (bin_capacity as f64);
        // Penalize new bin when open bins are roomy on average.
        score += 25.0 * (1.0 - fragmentation);
        // Slightly more willing to open bins early (build inventory of empty space)
        // and when few bins are open.
        score -= 10.0 * (1.0 - progress) * (1.0 / (1.0 + open_bins_count as f64));
        // If no open bin fits at all, opening is mandatory anyway; neutralize penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild preference for filling bins that are already well-loaded (reduces bin count pressure).
    let load_frac = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
    score -= 6.0 * load_frac * load_frac;

    // Penalize creating residuals that are awkward sizes (small odd leftovers 1..10)
    // which are unlikely to fit future items in the 10..80 range.
    if post_residual >= 1 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr + 40.0 * poly;

    // Penalize dead space more strongly later in the stream
    score += progress * norm_pr * 25.0;

    // Reward tight fits (small post residual) with smooth quadratic term
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 10.0 * (1.0 - progress);

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless existing residuals are poor
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score = cap * (0.6 + 0.4 * progress) - 20.0 * mean_norm * mean_norm;
    }

    // Mild penalty for many open bins with large mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * mean_residual / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible into nice chunks is good.
    let pr = post_residual;
    if pr > 0 {
        // Perfect-fit classes: post residual that could host common item sizes.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 2.5;
        }
        // Small dead space penalty grows superlinearly below threshold 10.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
        // Integer-division threshold: residual in [10,20] is a "half-slot" class.
        let slot_class = pr / 20; // 0..5 harmonic bands
        score += slot_class as f64 * 1.5;
    } else {
        score -= 12.0; // exact fill is excellent
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize leaving large awkward residual
            score += (next_item_size - pr) as f64 * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // Fraction-of-capacity coupling for tight fits.
    let fill_ratio = item_size as f64 / cap;
    if fill_ratio > 0.8 {
        score -= 5.0 * (fill_ratio - 0.8) / 0.2;
    }

    // New-bin candidate (empty bin): should only win when no decent fit exists.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score += 4.0; // mildly discourage abandoning the last fitting bin
        }
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mean-residual context: if this bin's residual is far below mean, it's already tight; prefer it.
    let diff = mean_residual - bin_residual as f64;
    score += 0.05 * diff;

    // Many open bins: encourage consolidation into existing bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful are heavily penalized.
    // A residual gap is "dead" if it's smaller than the smallest plausible item (<= ~10% of capacity).
    let dead_threshold = (bin_capacity as f64 * 0.1).max(1.0);
    if (post_residual as f64) > 0.0 && (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Prefer tight fits: reward small post_residual relative to capacity (non-linear).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * tightness * tightness;

    // Open-bin pressure: discourage scattering items across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize unless nothing fits well,
    // so we only open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no other option: new bin is fine
        } else if post_residual as f64 > dead_threshold * 2.0 {
            score -= 10.0; // existing fits are loose; a fresh bin may be better
        }
    }

    // Lookahead: if the next item fits snugly into the resulting residual, reward it.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack < dead_threshold {
            score -= 12.0; // next item will nearly fill this bin perfectly
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is already low, but amplify.
    if post_residual == 0 {
        score -= 200.0; // perfect fit: strongly favored
    } else if post_residual <= 5 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Penalize leaving dead space that is hard to reuse (large residual but small next item won't fill).
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Dead-space penalty grows if residual is in an awkward band (e.g. 30..60) that few items fill.
        if pr >= 30.0 && pr < 60.0 {
            score += 15.0;
        }
    }

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if (n - pr).abs() < 1.0 && pr > 0.0 {
            // Next item exactly fills this bin: excellent plan.
            score -= 120.0;
        } else if pr >= n {
            // Next item fits here too: good chaining, reward proportionally.
            score -= 20.0 + (n / pr) * 30.0;
        } else {
            // Next item does NOT fit after placement: mild penalty proportional to mismatch.
            score += (n - pr) * 0.5;
        }
        // Compare post_residual relative to mean residual: prefer bins whose
        // remaining space tracks the mean (keeps bin pool homogeneous).
        let dev = (pr - mean_residual).abs();
        score += dev * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): penalize so we only open a new bin when
    // no open bin offers a decent fit. The penalty must exceed the natural
    // advantage of a full empty bin (post_residual = capacity).
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        // If many bins fit the item, opening a new bin is wasteful.
        let crowding = fitting_bins_count as f64 * 25.0;
        // Early in stream, tolerate new bins more (bin pool still growing).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let early_bonus = (1.0 - progress) * 30.0;
        // If next item is small, an empty bin wastes future potential less.
        score += base_penalty + crowding - early_bonus;
    }

    // Slight preference for fuller bins (lower residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Tie-breaker: mildly prefer bins with fewer open bins overall (consolidation).
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: strongly discount small post-residuals.
    let tightness = 1.0 - (post / cap);
    score -= 2.5 * tightness * tightness * cap;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space: residuals too small for any plausible item (1..100 unknown, assume >=10-ish usable chunk).
    if post_residual > 0 && post_residual < item_size {
        score += 8.0; // fragment likely unusable
    }

    // Lookahead: reward if next item fits into post-residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // extra reward for near-exact two-item packing
            let slack = post_residual - next_item_size;
            if slack == 0 { score -= 12.0; }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is expensive early, cheaper late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, modulated by how many bins are open and time
        score = cap - 20.0 * (1.0 - progress) - 1.5 * (open_bins_count as f64);
        if fitting_bins_count <= 1 {
            score += 60.0; // don't open new bin when a usable bin exists
        }
    }

    // Global state: prefer bins with residuals far from the mean (balance residual pool).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for more-filled bins overall.
    score += 0.1 * (bin_residual as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * (1.0 + 0.8 * progress * norm_pr + 0.6 * progress * progress);

    // Penalize residuals too small to hold even the smallest plausible item.
    let dead = if pr < 10.0 { (10.0 - pr) * 3.0 } else { 0.0 };

    // Lookahead: reward residual that can still host the next item.
    let look = if next_item_size > 0 && pr >= next_item_size as f64 {
        -1.5 * (1.0 - (next_item_size as f64 / cap))
    } else if next_item_size > 0 {
        1.0
    } else {
        0.0
    };

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    let last_chance = if fitting_bins_count == 1 { -4.0 } else { 0.0 };

    // Mild preference against spreading across many bins when residuals are ample.
    let crowd = 0.02 * open_bins_count as f64 * (1.0 - norm_pr);

    // New-bin candidate: neutral baseline slightly above well-packed fits.
    let new_bin_bias = if bin_residual == bin_capacity { 0.5 + 0.5 * progress } else { 0.0 };

    let mut score = poly * 10.0 + dead + look + last_chance + crowd + new_bin_bias
        - 0.3 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: dead space classes.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Integer-division thresholds on post_residual: classify dead space.
        // Small residuals (<10) are nearly unusable for future items (min size 1..100
        // but typical items are chunky) -> penalize proportionally.
        let pr = post_residual;
        if pr < 10 {
            score += 25.0; // near-dead space
        } else if pr < 20 {
            score += 8.0;
        } else if pr < 35 {
            score += 2.0;
        } else if pr < 60 {
            score -= 3.0; // flexible mid-range residual
        } else {
            score -= 1.0;
        }

        // Harmonic residue class: post_residual mod 10 -> prefer round residuals
        // that align with common item sizes (multiples of 5/10).
        let r = pr % 10;
        if r == 0 {
            score -= 4.0;
        } else if r == 5 {
            score -= 2.0;
        } else if r <= 2 || r >= 8 {
            score += 1.5;
        }
    }

    // Tightness reward: fraction of bin filled by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra harmonic bonus if next item leaves another round residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else if next_item_size > post_residual && post_residual > 0 {
            // residual too small for the known next item -> dead space penalty
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // competition: mild bonus, selection among many is fine
        score -= (fitting_bins_count as f64).ln() * 0.5;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Prefer new bin only when no open bin gives a good fit; make the empty-bin
    // score sit at a calibrated level: base cost of opening a bin plus its
    // flexibility, adjusted by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 20.0 * progress + 0.15 * open_bins_count as f64;
        // If the next item is large, an empty bin is more valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Mean residual context: when open bins are on average loose, tolerate
    // imperfect fits; when they are tight, penalize waste.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    let dead_zone_low = 1.0;
    let dead_zone_high = 9.0;
    if post_residual >= dead_zone_low as u32 && post_residual <= dead_zone_high as u32 {
        score += (dead_zone_high - post_residual as f64) * 18.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Penalize creating residuals that cannot fit typical future items
    // (items are 1..100, but small residuals waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Open bins pressure: prefer spreading load when many bins are open,
    // prefer tightening existing bins when few are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 8.0);
    score += bin_pressure * 1.5;

    // Coupling with mean residual: if this bin's post-residual is far below mean,
    // it's a tight fit — reward it; far above mean — penalize fragmentation.
    let pr = post_residual as f64;
    score += (pr - mean_residual) * 0.35;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only allow opening a new bin when the fit is poor
    // or the next item would benefit from a fresh bin.
    if bin_residual == bin_capacity {
        let poor_fit = pr > 40.0;
        let lookahead_waste = next_item_size > 0 && next_item_size > post_residual && post_residual < 10;
        if !(poor_fit || lookahead_waste) {
            score += 60.0; // discourage opening new bins on decent fits
        } else {
            score += 5.0; // mild preference for fresh bin when fit is bad
        }
    }

    // Lookahead synergy: if next item exactly fills the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size <= 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when the next item fits snugly into post_residual (2-step lookahead match)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly fills the bin
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_gap / bin_capacity as f64);
            // Extra bonus for exact fill (post_residual == next_item_size)
            if chain_gap == 0.0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; penalize large leftover dead space
            score += 0.15 * (post_residual as f64 - mean_residual).abs();
        }
    } else {
        // Last item: strongly prefer minimal leftover
        score += 10.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: this is the only bin that fits; avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize opening a brand-new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        // But if item is huge and nothing tight exists, new bin is less bad
        if item_size > bin_capacity / 2 {
            score -= 4.0;
        }
    }

    // Late in the stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of fit: fraction of bin consumed by this item
    let fill_frac = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward near-perfect fits strongly (dead space is the enemy)
    let tight_bonus = -(1.0 - post_frac).powi(3) * 30.0;
    score += tight_bonus;

    // Penalize leaving residuals that are "awkward" (small but nonzero):
    // residuals below the minimum item size are dead space; residuals just
    // above common item sizes are likely reusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward if next item fits in the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - post_frac);
        } else {
            score += 6.0; // blocks the natural follow-up item
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive early, cheap late.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_cost = 18.0 * (1.0 - 0.5 * progress);
        score += open_cost;
        // If no existing bin fits, opening is unavoidable: neutralize cost.
        if fitting_bins_count == 0 {
            score -= open_cost;
        }
        // Late in the stream, avoid scattering items across many bins.
        if progress > 0.7 {
            score += 10.0 * progress;
        }
    }

    // Global state: if mean residual across open bins is large, we have slack;
    // be pickier (penalize loose fits). If mean residual is small, accept more.
    let mean_frac = mean_residual / bin_capacity as f64;
    score += mean_frac * post_frac * 10.0;

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * post_frac * 2.0;

    // Slight preference for filling larger items into emptier bins
    score -= fill_frac * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    // As stream progresses, penalize larger residual more aggressively (waste matters more).
    let coupling = 1.0 + 2.5 * t * t + 1.5 * t * norm_pr;
    score *= coupling;

    // Smooth reward for tight fits (small post_residual), stronger later in stream.
    let tightness = 1.0 - norm_pr;
    score -= (20.0 + 60.0 * t) * tightness * tightness * tightness;

    // Penalize residual that cannot fit the lookahead item (dead space), smoothly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let shortfall = ((ni - pr).max(0.0)) / cap;
        score += (15.0 + 35.0 * t) * shortfall * shortfall;
        // Reward residual that nicely accommodates the next item.
        let slack = ((pr - ni).max(0.0)) / cap;
        score += 8.0 * slack * slack;
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * t;
    }

    // Mild penalty for bin proliferation, scaled by progress.
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * t);

    // Pull score toward mean residual context: bins far from mean residual get
    // a smooth quadratic penalty (favor homogeneity of open bins).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: neutral-ish baseline that becomes attractive only when
    // no existing bin offers a good fit (its post_residual is max, so coupling
    // already penalizes it; add slight progress-dependent penalty).
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (capacity fractions).
    let residue_class = post_residual % 10;
    // Penalize awkward residues (hard-to-fill leftovers like 1..9)
    if residue_class > 0 {
        score += (10 - residue_class) as f64 * 1.5;
    } else {
        // Perfect harmonic alignment: strong reward
        score -= 12.0;
    }

    // Integer division threshold: post_residual bucketed by quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score -= 6.0; // bin nearly full, good
    } else if post_residual <= 2 * quarter {
        score += 2.0;
    } else {
        score += 5.0; // large leftover, mild penalty beyond raw residual
    }

    // Next-item coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward if next item leaves a harmonic residue again
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 { score -= 8.0; } else if nr <= quarter { score -= 4.0; }
            else { score += (nr % 10) as f64 * 0.5; }
        } else {
            // next item won't fit here: penalize proportionally to wasted lookahead
            score += 3.0 + (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Early stream: be more tolerant of spreading (favor new bins less penalized later)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 || (mean_residual < item_size as f64 && open_bins_count > 0) {
            score -= 10.0; // open fresh bin when open bins are poor
        } else {
            score += 20.0; // discourage wasting a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0;
    }

    // Reward near-perfect fits (post_residual very small but nonzero is
    // already low; a perfect zero residual is ideal).
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // Next item fits: the smaller the leftover after that, the better.
            let post2 = post_residual - next_item_size;
            score -= 15.0 + 0.4 * (post2 as f64).min(30.0);
            if post2 < 10 {
                score += 20.0; // creates a fresh dead gap
            }
        } else {
            // Next item cannot use this residual: penalize proportional to waste.
            score += 0.3 * (next_item_size as f64).min(post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones; make the empty-bin candidate less attractive.
    if bin_residual == bin_capacity {
        score += 25.0 + 4.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    } else {
        // Slight reward for filling existing bins when pressure is high.
        score -= 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: placing into a bin whose residual is far
    // below the mean reduces fragmentation spread.
    score -= 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let gap = (post_residual as f64 - nr).abs();
        if post_residual as f64 >= nr {
            // next item fits exactly-ish: reward tight match
            score -= 300.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual: bins with residual near mean are "typical";
    // prefer deviating from mean only when it reduces waste
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when a reasonable existing fit exists
    if bin_residual == bin_capacity {
        score += 50.0 + post_residual as f64;
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on post-residual
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward exact/very tight fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize residuals too small to hold any item (dead space), item sizes >= 1
    if post_residual >= 1 && post_residual < 10 {
        score += 20.0; // unusable sliver
    }

    // Lookahead coupling: if post_residual can exactly/nearly fit the next item, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 30.0; // perfect chain fit
            } else if slack <= 5.0 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // residual can't hold next item; penalize proportionally
            score += (nxt - pr) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // competition: mild penalty to spread load based on residual vs mean
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        } else {
            score -= 3.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, decaying with stream progress
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // cheaper to open a new bin when many bins are open (spread residual diversity)
        if open_bins_count > 3 {
            score -= 8.0;
        }
        // if next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 5.0;
        }
    }

    // Global load balancing: prefer bins whose residual deviates favorably from mean
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Late-stream conservatism: as stream nears end, avoid opening slack
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let p1 = progress;
    let p2 = p1 * p1;
    let coupling = prn * (1.0 + 2.0 * p1) * (1.0 + 1.5 * p2);
    score += 3.0 * (coupling - prn);

    // Penalize waste more aggressively as stream progresses
    score *= 1.0 + 0.8 * p2;

    // Reward tight fits (small post_residual) with smooth non-linear bonus
    let tightness = 1.0 - prn;
    score -= 10.0 * tightness * tightness * tightness;

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + p1);
    }

    // Lookahead: penalize leaving residual just below next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0);
        let smooth = gap / (gap + 10.0);
        score += 5.0 * smooth * (1.0 - prn);
        // Reward if next item fits exactly in the post residual
        if pr >= nxt {
            score -= 4.0 * (1.0 - (pr - nxt).abs() / cap);
        }
    }

    // Mild penalty for opening new bins relative to open bin count
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // But late in the stream, prefer compacting into open bins less strongly
        score -= 8.0 * p1;
    }

    // Deviation from mean residual: prefer bins with residual near mean (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of post_residual: dead space that no item (min size 1..100) can use
    // Class residual into usable bands via integer division on half-capacity
    let half = bin_capacity / 2;
    let usable_class = if post_residual >= half { 2 } else if post_residual >= bin_capacity / 4 { 1 } else { 0 };
    score += usable_class as f64 * 8.0;

    // Modulo-class coupling: residual % 10 quantization of leftover attractiveness
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.4;

    // Lookahead: reward if next item fits exactly into the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.5;
        } else {
            // next item cannot fit here; leftover is dead unless small
            score += 6.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets baseline penalty so it is
    // chosen only when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 0.3;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, opening is fine
        }
    }

    // Progress-aware mild pressure to consolidate early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // A residual gap is "dead" if no plausible future item (min size 1..10) fits well.
        // Penalize gaps in the awkward small range (1..=15) super-linearly.
        if post_residual < 15 {
            score += (15.0 - post_residual as f64) * 12.0;
        } else if post_residual < 30 {
            score += (30.0 - post_residual as f64) * 3.0;
        }
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement chains perfectly — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap == 0 {
            score -= 90.0;
        } else if chain_gap <= 10 {
            score -= 30.0;
        }
    }
    // If next item can NOT fit in post residual, this bin becomes less attractive
    // only mildly (item may still be followed by others).
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid fragmentation); opening new bins should be discouraged.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 2.5;

    // Mean residual coupling: placing into a bin far below the mean residual
    // (i.e., a fuller bin) is good — reward closeness to zero residual.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        if post_residual < 10 {
            score -= 35.0; // extra reward for squeezing into last chance with tiny waste
        }
    }

    // New-bin candidate (empty bin): penalize so it's chosen only when all fits are bad.
    if bin_residual == bin_capacity {
        score += 70.0 + open_bins_count as f64 * 3.0;
        // But if next item is large and this item leaves a large gap elsewhere,
        // a fresh bin is still penalized — keep strictness.
    }

    // Prefer bins whose residual is close to item size (tight fit) — smooth coupling.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly equals next item.
            if post_residual == next_item_size {
                score -= 250.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                score -= 120.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Dead space relative to the lookahead item: penalize.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Compare post_residual against mean residual: prefer bins that end below-average residual
    // (tight packing), penalize leaving above-average residual.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 200.0;
        } else {
            score -= 40.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 90.0;
        // If lookahead chains perfectly into a fresh bin, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Mild preference for filling older bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by how full the bin already is.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += post_residual as f64 * (0.5 + 0.5 * fill_ratio);

    // Reward bins that become exactly full (perfect closure).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 + 10.0 * (1.0 - chain_fit / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement: mild penalty for wasting space.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize bins whose residual is far from mean residual (avoid fragmenting many bins evenly).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Time horizon: late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill_ratio);

    // If many bins are open, prefer filling existing ones rather than opening more.
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).ln() * (1.0 - fill_ratio);
    }

    // New-bin candidate: only attractive when current item is large or no tight fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for big items or when many bins compete poorly.
        let openness = large_item * 60.0
            - (fitting_bins_count as f64) * 8.0
            + 20.0 * (1.0 - progress);
        score = 40.0 + openness + post_residual as f64 * 0.5;
        // Never open a new bin if the item closes an existing bin perfectly.
        if item_size == bin_capacity {
            score = 1e9;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tight fits are always good: reward small post_residual quadratically.
    let pr = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - pr) * (1.0 - pr) * (1.0 - pr);

    // Penalize dead space: residual too small for the next item is likely wasted,
    // unless it is very small (already near-perfect fill).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 1.0 {
            // perfect follow-up fit: strong reward
            score -= 25.0;
        } else if next_item_size > post_residual {
            let dead = (post_residual as f64) / nxt;
            score += 15.0 * dead * dead;
        } else {
            // next item fits: mild reward scaled by how well it fills
            let fill_after = (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 10.0 * (1.0 - fill_after);
        }
    }

    // Smooth non-linear coupling with stream progress:
    // early on, be conservative (favor spreading into new bins less),
    // late in the stream, strongly prefer closing bins tight.
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += progress_coupling * (post_residual as f64 * 0.5);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * progress_coupling;
    }

    // New-bin candidate: make it unattractive unless no good fit exists.
    if bin_residual == bin_capacity {
        let base_penalty = 40.0 + 0.3 * mean_residual;
        score += base_penalty * (1.0 - 0.5 * progress_coupling);
        // If the new bin would give a great immediate + next-item packing,
        // soften the penalty so we can still open when it's genuinely better.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate emptier bins).
    score += 0.05 * (mean_residual - bin_residual as f64).abs().signum()
        * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into "useful"
    // residue classes (small remainders = tight fits), penalize dead zones.
    let post = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = post % quarter.max(1);
    let tiny = post % eighth.max(1);

    // Reward tight fits: small post_residual, and post_residual near a
    // divisor-friendly class (e.g. 0 mod 25 leaves room for 25-sized items).
    if post == 0 {
        score -= 60.0; // perfect fit
    } else if post <= eighth {
        score -= 25.0;
    } else if class == 0 {
        score -= 15.0; // residual divisible by quarter: reusable slot
    } else if class <= eighth {
        score -= 8.0;
    } else {
        score += 6.0; // awkward dead zone
    }
    if tiny == 0 && post > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: does next item fit the post_residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0; // exact chain
        } else if next_item_size <= post {
            let waste = (post - next_item_size) as f64;
            score -= (20.0 * (1.0 - waste / cap_f)).max(0.0);
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // or the stream is early and spreading capacity is valuable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread_bonus = 12.0 * (1.0 - progress);
        score += 35.0 - spread_bonus;
        if post > 20 {
            score += (post as f64) * 0.3;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.15;

    // Prefer bins with residual close to item (best-fit core, sharpened).
    score += ((bin_residual - item_size) as f64 - post as f64).abs() * 0.0;

    // Mean-residual alignment: bins whose residual deviates from mean residual
    // are slightly penalized to keep the pool homogeneous.
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Penalize mid-range dead space proportionally (wasted capacity).
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 35.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual cannot host next item: mild penalty.
        score += 6.0;
    }

    // Prefer keeping new empty bins as a last resort unless current bin is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Stream progression: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the bin after this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly (small leftover after both).
    if next_item_size > 0 && next_item_size <= post_residual {
        let two_step_leftover = post_residual - next_item_size;
        score -= 30.0 * (1.0 - two_step_leftover as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how much it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.4 * miss;
    }

    // Compare post_residual against mean residual: prefer leaving residuals near the mean
    // (keeps open bins homogeneous), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize unless current placement would waste a lot.
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 45.0 * waste_ratio;
        // If the item is large relative to capacity, opening a new bin is reasonable.
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 30.0;
        }
        // With many open bins, prefer reusing existing capacity.
        score += 2.0 * open_bins_count as f64;
    }

    // Favor tight fits overall.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Reward placements where the lookahead item can still fit into the leftover.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize creating dead space that the next item cannot use,
        // more strongly when the dead space is small (unusable slivers).
        let dead = post_residual as f64;
        score += 6.0 * (1.0 - dead / (bin_capacity as f64));
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Penalize spreading across too many open bins relative to progress;
    // early in the stream, consolidation is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_pressure = (open_bins_count as f64) / (1.0 + 40.0 * (1.0 - progress));
    score += 0.6 * open_pressure;

    // Prefer bins whose residual is close to the mean residual (balance),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // this bin's fit is poor (large post_residual) or it is a last-resort situation.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, reduced when the item is large
        // and no existing bin fits it well.
        let poor_fit_elsewhere = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let size_factor = (item_size as f64) / (bin_capacity as f64);
        score += 20.0 - 25.0 * poor_fit_elsewhere * size_factor;
        // If the next item is large, a fresh bin with room is valuable.
        if next_item_size > 0 && next_item_size > post_residual.max(1) && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Slight time-dependent annealing: late in the stream, be greedier about
    // filling bins tightly.
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: post_residual weighted by progress
    let coupling = pr_norm * pr_norm * (1.0 + progress) * cap;
    score += 0.35 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit typical next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) / cap;
        score += 20.0 * waste * waste * cap;
        // Reward bins whose post-residual exactly accommodates next item
        let fit_next = (pr >= nx) as i32 as f64;
        score -= 6.0 * fit_next * (pr_norm) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mean residual alignment: prefer bins near the mean residual (smooth gaussian-like)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // Mild penalty for spreading across many bins late in stream
    score += 0.5 * open_bins_count as f64 * pr_norm * progress;

    // New-bin candidate: penalize slightly unless open bins are all poor fits
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality depends on divisibility
    // by common item-size classes (residuals divisible by 10 or 5 pair better
    // with future items in the 1..100 range).
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual < 10 { score += 15.0; } // unusable sliver
        if post_residual > 50 { score -= 2.0; } // still flexible
    }

    // Small residual relative to capacity fraction: penalize near-full-but-not-full
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.1 { score += 10.0; }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item cannot use this residual: dead space penalty scaled
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let base = 20.0 + 0.5 * open_bins_count as f64;
        // opening a new bin is penalized; allow it only if item is large
        score = base + item_size as f64 * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // room for the next item too
        }
        if fitting_bins_count == 1 {
            score += 18.0; // don't abandon the only fitting bin
        }
    }

    // Progress: late in the stream, prefer tighter packing (waste matters more)
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.3 * progress;

    // Mean residual context: if this bin is far from mean residual, slight penalty
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= ~10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals slightly larger than tiny items are also awkward.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 25.0; // creates dead space after next placement
    }

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins below mean residual (denser bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0 + 1.5 * open_bins_count as f64;
        if post_residual == bin_capacity - item_size {
            // empty bin residual = capacity - item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: strongly favor bins that get filled exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact two-item fill is excellent.
            if post_residual == next_item_size {
                score -= 500.0;
            } else {
                // Reward proportional to how well the next item fits the leftover.
                let fit_ratio = next_item_size as f64 / post_residual as f64;
                score -= 200.0 * fit_ratio;
            }
        } else {
            // Penalize leftovers too small for the next item (likely dead space),
            // but less when the leftover is tiny (near-full bin is still good).
            let waste = post_residual as f64;
            score += 0.5 * waste * (1.0 - (waste / bin_capacity as f64));
        }
    }

    // Prefer tighter fits relative to other open bins' mean residual.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin unless the current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        // New bin: baseline cost; make it attractive only if no tight fits exist.
        score += 50.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pairing both items in a fresh bin is decent.
            score -= 100.0;
        }
    }

    // Early in the stream, slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strongly reward tight fits (low post_residual) with a non-linear bonus.
    let tightness = 1.0 - post / cap;
    score -= 30.0 * tightness * tightness * tightness;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post > 0.0 && post < nxt {
            score += 12.0 * (nxt - post) / cap;
        } else if post >= nxt {
            // Reward bins whose leftover can host the lookahead item.
            score -= 8.0 * (nxt / cap) * (post / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize fragmenting bins when many bins already fit the item,
    // encouraging spreading load across bins.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when open bins have poor fit potential
    // or the stream is early and we can amortize a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_gap = (mean_residual - post).abs();
        // Prefer new bin when mean residual is small (open bins nearly full)
        // or when the item would leave a big awkward gap in existing bins.
        let awkward = if bin_residual > item_size {
            (bin_residual - item_size) as f64 / cap
        } else { 0.0 };
        let mut nb = 10.0 - 18.0 * (1.0 - mean_residual / cap);
        nb -= 6.0 * progress;
        if awkward > 0.5 { nb -= 5.0; }
        if mean_gap > 20.0 { nb -= 4.0; }
        score += nb;
    }

    // Mild global pressure: with many open bins, consolidate to close them.
    score += 0.05 * open_bins_count as f64;

    // Small time-dependent tie-breaker for diversity across the stream.
    score += 0.001 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;

    // Smooth penalty for leaving dead space: quadratic in normalized residual
    let dead_penalty = norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);
    score += dead_penalty;

    // Reward tight fits: cubic falloff of reward as residual grows
    let tight_reward = (1.0 - norm_pr).powi(3) * cap * (1.0 - fit_ratio);
    score -= tight_reward;

    // Interaction: residual x progress polynomial
    score += norm_pr * (1.0 - progress) * 10.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: penalize if next item can't use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += (nx - pr) * 0.3;
        } else {
            let nx_fit = (pr - nx) / cap;
            score -= nx_fit * nx_fit * cap * 0.5;
        }
    }

    // New-bin candidate: mildly penalize late in the stream to encourage packing into open bins
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress + open_bins_count as f64 * 0.5;
    }

    // Mean residual alignment: prefer bins close to the mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls
    // just below useful item sizes (1..100 unknown distribution).
    let pr = post_residual;
    if pr > 0 {
        // Fraction of capacity wasted
        let waste_frac = pr as f64 / cap_f;
        score += waste_frac * 40.0;

        // Dead-space penalty: residual too small for even the smallest item (1)
        if pr < 1 {
            score += 100.0;
        }
        // Residual that cannot fit the lookahead item is partially dead
        if next_item_size > 0 && pr < next_item_size {
            score += (next_item_size - pr) as f64 * 0.6;
        }

        // Integer-division thresholds: classify residual into harmonic bands
        let band = pr / 10; // 0..=10
        score += match band {
            0 => 25.0,                 // tiny unusable sliver
            1 => 12.0,                 // fits only very small items
            2 => 5.0,
            3 => 0.0,                  // sweet spot ~30-39
            4 => 2.0,
            5 => 6.0,                  // half-bin: awkward class
            6 => 3.0,
            7 => 0.0,                  // ~70-79: good complement class
            _ => 4.0,
        } as f64;

        // Modulo coupling: residuals near multiples of common item sizes
        // (e.g., 25, 50) pair well with quarter/half items.
        let m = pr % 25;
        if m == 0 {
            score -= 8.0;
        } else if m < 5 {
            score += 4.0;
        }
    } else {
        // Perfect fit: heavily reward
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / cap_f;
    score -= fill * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let mut new_bin_score = 55.0;
        // Prefer a new bin when existing fits are poor (high post_residual spread)
        if post_residual as f64 > mean_residual {
            new_bin_score -= 10.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            new_bin_score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 10.0;
        // Many open bins: discourage one more
        new_bin_score += open_bins_count as f64 * 0.8;
        return new_bin_score;
    }

    // Reward good residual match with mean (keeps bins balanced)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small residuals that are likely dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so it's only chosen when fits are terrible.
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    // Mild preference for tighter bins early in the stream.
    let progress = step_index as f64 / total_items as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (5.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect chain fit (post_residual == next_item_size) gets a big reward.
        if slack == 0.0 {
            score -= 40.0;
        } else {
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > post_residual {
        // Next item cannot follow in this bin: penalize proportionally.
        score += 10.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Tight fit reward: small post residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Prefer bins whose residual is below mean residual (denser bins first).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless the fit is perfect.
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size == 0 {
            score -= 3.0;
        }
    }

    // Late in the stream, be greedier about tightness.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 60.0;
        } else {
            // Next item won't fit here; penalize wasting residual it could have used elsewhere.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: prefer existing bins unless fit is poor and
    // mean residual across open bins is small (fragmented state).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.5;
        // If the current bin would leave a tight, unusable residual, allow a new bin.
        let tight_fit = post_residual > 0 && post_residual < 12 && next_item_size > post_residual && next_item_size > 0;
        if tight_fit {
            score -= 80.0;
        }
        // If many bins are open and mean residual is high, prefer reusing them.
        score += mean_residual * 0.3 + (open_bins_count as f64).sqrt() * 5.0;
    } else {
        // Slight bonus for filling bins that are already relatively full.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fullness * 20.0;
    }

    // Time horizon: as the stream progresses, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 20 {
        score -= progress * 30.0;
    }

    // Mild penalty when many bins fit the item: prefer the tightest, handled by
    // base post_residual, but nudge against scattering across many open bins.
    if fitting_bins_count > 3 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let progress = progress.clamp(0.0, 1.0);

    // Smooth non-linear coupling: as the stream progresses, penalize leaving
    // awkward mid-range residual gaps more strongly (dead space becomes costly).
    let gap_norm = post_residual as f64 / bin_capacity as f64;
    let awkwardness = 4.0 * gap_norm * (1.0 - gap_norm); // peaks at half-full residual
    score += awkwardness * (0.5 + 2.0 * progress) * 10.0;

    // Reward tight fits (small post_residual) with a smooth inverse term.
    if post_residual > 0 {
        score -= 20.0 / (post_residual as f64).sqrt();
    } else {
        score -= 30.0; // perfect fit bonus
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post_residual as f64;
        if next_fits {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Smooth penalty proportional to how far short the bin falls.
            let miss = next_item_size as f64 - post_residual as f64;
            score += 4.0 * (miss / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, scaled by how many
    // existing bins could fit and how dispersed the residuals are.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count > 0 {
            score += 30.0 * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // Early in the stream, opening bins is cheaper (more items to fill them later).
        score -= 20.0 * (1.0 - progress);
        // If mean residual across open bins is small, a new bin is more attractive.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 10.0;
    } else {
        // Mild preference for bins whose residual deviates from the mean (balance).
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // --- Harmonic class of post_residual (modulo-10 bands) ---
    // Perfect fit is heavily rewarded.
    if pr == 0 {
        score -= 30.0;
    } else {
        // Dead-space penalty: residuals too small to hold typical items are wasted.
        if pr < 10 {
            score += (10 - pr) as f64 * 2.5;
        }
        // Harmonic band bonus: residuals in "half" and "third" capacity classes
        // are more reusable by future items (mod-10 residue 0 band is efficient).
        let band = pr % 10;
        score += band as f64 * 0.4;
        if pr % 25 == 0 {
            score -= 6.0; // quarter/half capacity classes are valuable
        } else if pr % 20 == 0 {
            score -= 4.0;
        }
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if pr >= next_item_size {
            // This bin can also swallow the next item: chain reward.
            score -= 8.0 + (next_item_size as f64) * 0.25;
        } else if pr > 0 {
            // Residual just below next item: near-miss dead space penalty.
            let gap = next_item_size as f64 - pr as f64;
            score += gap.min(25.0) * 0.8;
        }
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin fits: opening a new bin is mandatory.
            score -= 50.0;
        } else if fitting_bins_count == 1 {
            // One open bin fits: strongly prefer using it over opening a new bin.
            score += 25.0;
        } else {
            // Multiple alternatives: new bin only attractive if open bins are fragmented.
            score = score.max(mean_residual * 0.5 + 20.0);
        }
    }

    // --- Last-chance bin reward ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // --- Fragmentation-aware nudge toward bins below mean residual ---
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Slight late-stream tightening: prefer tight packing as stream progresses.
    score += progress * (pr as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

