    // are worthless; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps too small for the lookahead item are also weakly penalized
    // (they may still be usable by future items, so softer penalty).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the next item (chaining).
        score -= 6.0;
    }

    // Perfect or near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer compacting into
    // existing ones rather than spreading; open fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + 0.5 * progress) * 0.15;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // More open bins -> new bin slightly cheaper relative to crowding.
        score -= open_bins_count.min(10) as f64 * 1.0;
        // If current bin would leave a big unusable gap, opening a new
        // bin becomes more competitive.
        if post_residual < item_size && post_residual > 0 {
            score -= 20.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (tight fit),
        // i.e. low post_residual relative to bin_residual.
        let tightness = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
        score += tightness * 10.0;
        // Slight preference for bins already below mean residual (fill laggards).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
