pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            score -= 25.0; // perfect pairing with lookahead item
        } else {
            score -= 6.0; // next item can still fit here afterwards
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64; // how much worse open bins are
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: must open
        } else {
            // Opening a new bin is penalized more when open bins are tight/scarce.
            score += 20.0 + 15.0 * (1.0 - progress) + 5.0 * pressure;
            if spread > 0.0 {
                score -= 10.0 * spread.min(3.0); // allow opening when mean residual is large
            }
        }
    }

    // Mild global regularization: favor filling bins with large mean residual
    // (drain the "loosest" bins first).
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
    }

    // Reward near-exact fills.
    if post_residual <= 2 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual, slightly damped early so filling bins is encouraged via interactions
    let mut score = pr;

    // Smooth polynomial coupling: residual waste penalized more as stream progresses
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * progress_poly * norm_pr * norm_pr;

    // Reward tight fits with smooth non-linear term
    score -= 30.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);

    // Lookahead coupling: bonus if next item fits in post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let nx = next_item_size as f64 / cap;
        score -= 15.0 * (1.0 - nx) * (1.0 - progress_poly);
    } else if next_item_size > post_residual {
        score += 8.0 * progress_poly;
    }

    // Penalize proliferation of open bins mildly, smooth in progress
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress_poly);

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress_poly);
    }

    // New-bin candidate: score relative to mean residual of open bins
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress_poly) + 0.5 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Reward tight fits strongly (small post_residual => low score).
    score -= 30.0 * (-frac * 6.0).exp();

    // Harmonic class bonus: residuals that are multiples of small integers (2,4,5,10)
    // are more likely reusable by future items drawn from integer distributions.
    let pr_u = post_residual;
    if pr_u > 0 {
        if pr_u % 10 == 0 { score -= 6.0; }
        else if pr_u % 5 == 0 { score -= 4.0; }
        else if pr_u % 2 == 0 { score -= 2.0; }
        if pr_u % 4 == 0 { score -= 1.5; }
        if pr_u % 20 == 0 { score -= 2.0; }
    }

    // Penalize "dead" residuals that no plausible item (1..=100) can use well:
    // a residual r is only usable by items <= r; tiny residuals are waste.
    if pr_u > 0 && pr_u < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this bin is a perfect two-item chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (-slack / 15.0).exp();
            // Harmonic match between next item and residual class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here anyway; mild penalty scaled by overflow
            let over = (next_item_size - post_residual) as f64;
            score += 2.0 * (over / 50.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it attractive
    // only when no open bin offers a good fit (i.e., when best open fit would leave
    // large waste). Compare post_residual against mean residual of open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin (bin count is costly).
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if open bins are nearly full (small mean residual), opening fresh
        // is better: subtract to compensate.
        score -= 0.5 * mean_residual;
        // If item is large relative to capacity, fresh bin is fine.
        score -= 10.0 * (item_size as f64 / cap);
        // Early in stream, prefer consolidating; late, opening is cheaper per item.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    } else {
        // Filling existing bins is generally good; scale with how full the bin was.
        score -= 5.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Mild global pressure to prefer bins with residual close to item_size (best fit).
    let waste = (bin_residual - item_size) as f64;
    score += 0.1 * waste;

    // Small tie-break noise via deterministic coupling (no RNG).
    score += ((step_index as f64 * 0.6180339887).fract() - 0.5) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead reward: next item fits in the post residual
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 10.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    }
    // Penalize post residual that is small but cannot fit next item (dead space)
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Penalize residuals far below the mean residual (fragmentation)
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score -= 0.15 * (-dev);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Slight bias toward new bins early in the stream
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post_residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        if next_item_size > 0 && next_item_size <= post_residual {
            // Lookahead bonus: this bin can also host the next item.
            score -= 12.0 + 8.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual < 10 {
            score -= 6.0; // tiny slivers are nearly free
        } else {
            // medium unusable gap: penalize, more so early in stream
            let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score += (post_residual as f64) * 0.15 * (1.0 - 0.5 * t);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.6;

    // Deviation from mean residual: prefer bins whose residual is close to item
    // (best-fit-like) and discourage dumping into unusually large-residual bins.
    let diff = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.08 * diff.abs();

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits very poorly everywhere else (large item, big leftover risk).
    if bin_residual == bin_capacity {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = (bin_capacity - item_size) as f64;
        let poor_fit_elsewhere = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).recip()
        } else { 1.0 };
        let base = cap * 0.55
            + waste * 0.35
            - 30.0 * poor_fit_elsewhere
            - 10.0 * (1.0 - t);
        // If lookahead item fits nicely in the fresh bin too, mild bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score = base - 8.0;
        } else {
            score = base;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: waste left behind, smoothed polynomial shaping of small residuals
    let mut score = norm_pr * (1.0 + 0.6 * (1.0 - norm_pr) * (1.0 - norm_pr));

    // Non-linear coupling of post_residual with stream progress:
    // early on tolerate slack; late in the stream punish it quadratically.
    let coupling = norm_pr * (1.0 - progress) - norm_pr * norm_pr * progress;
    score += 2.0 * coupling;

    // Tight fit reward, smoothly modulated by progress
    let tightness = 1.0 - norm_pr;
    score -= 1.5 * tightness * tightness * (0.5 + 0.5 * progress);

    // Lookahead synergy: bonus if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.2 * (next_item_size as f64 / cap) * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize proportionally to how many bins are open,
    // unless the item fits poorly everywhere (handled by comparison).
    if bin_residual == bin_capacity {
        score += 4.0 + 0.5 * open_bins_count as f64;
        score -= 2.0 * (item_size as f64 / cap);
    }

    // Slight preference for bins deviating from mean residual (balance)
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 8 harmonic
    // octaves. Leftovers in the same octave behave alike; reward small classes.
    let octave = post_residual / (bin_capacity / 8).max(1);
    score += octave as f64 * 3.0;

    // Perfect fit: residual is an exact divisor class of capacity (0, 25, 50, 75).
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    // Exact zero residual is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: penalize leaving a residual that cannot host the next item
    // (dead space), reward residuals that can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic coupling: how many copies of next item fit in leftover.
            let copies = post_residual / next_item_size;
            score -= 2.0 + copies as f64;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && post_residual < 15 { 1.0 } else { 0.0 };
        score += 30.0 - bad_fit * 40.0
            + (open_bins_count as f64) * 0.5;
    }

    // Slight preference to fill bins that are already mostly full
    // (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Mean residual coupling: prefer bins close to the mean residual
    // to keep bin states balanced, unless it's the last chance.
    if fitting_bins_count > 1 {
        score += ((bin_residual as f64) - mean_residual).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, the classic min item)
    // are pure waste; escalate penalty for residuals in the "dead zone".
    if post_residual < 10 {
        score -= 1000.0; // near-perfect fit, essentially zero waste
    } else if post_residual <= 15 {
        score -= 50.0;   // tiny gap, hard to fill later
    } else if post_residual <= 30 {
        score -= 10.0;
    }

    // Reward if the leftover gap can exactly host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Mild reward if leftover can fit the next item (keeps chain packing alive).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // but allow it when open-bin pressure is low (early stream / few bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 * 3.0 + progress * 20.0;
        score += 60.0 + pressure;
        // Exception: if this bin is the last chance anyway, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is far below the mean (tight bins first),
    // keeping loose bins available for larger future items.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for more-filled bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff < 0.5 {
            // Perfect chain: this bin will be exactly filled by next item
            score -= 60.0;
        } else if pr >= nxt {
            // Next item still fits after this placement
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential
            score += 8.0 * (diff / bin_capacity as f64);
        }

        // Coupled chain: post_residual == item_size + next_item_size (two-item exact fill)
        let chain = item_size as f64 + nxt;
        if (bin_residual as f64 - chain).abs() < 0.5 {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual is already below average (tight bins)
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating tiny unusable slivers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate as stream progresses
    score += 0.05 * (step_index as f64 / total_items.max(1) as f64) * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space relative to capacity).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 60.0;          // quadratic penalty on dead space
    score -= fill_ratio * 25.0;             // reward filling bins heavily

    // Lookahead: reward leaving room exactly for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;                  // perfect pairing
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + gap / 10.0); // next item still fits well
        } else {
            // next item won't fit here: penalize slightly if gap is small (near miss)
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.2;
        }
    } else {
        // last item: just minimize waste, no lookahead concerns
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: discourage spreading, prefer tight bins.
    if open_bins_count > 2 {
        let pressure = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += pressure * 20.0; // prefer bins tighter than average
    }

    // Time horizon: early in stream, keep flexibility (favor mid residuals);
    // late in stream, pack aggressively (favor small post_residual extra).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.15;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // baseline cost of opening a new bin; discount when current best
        // residual would be very poor or few bins fit.
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        let threshold = 0.55 + 0.2 * (1.0 - progress);
        if poor_fit > threshold || fitting_bins_count == 0 {
            score -= 70.0; // opening fresh bin is better than cramming
        } else {
            score += 80.0; // prefer existing bins when fit is decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: quadratic penalty on wasted space, normalized by capacity.
    let mut score = post * post / cap;

    // Smooth non-linear coupling of waste with stream progress:
    // late in the stream, waste matters more (fewer chances to fill gaps).
    let progress_coupling = (1.0 + progress * progress);
    score *= progress_coupling;

    // Perfect fit reward (smooth, not piecewise).
    let tightness = 1.0 - post / cap;
    score -= 8.0 * tightness * tightness * tightness;

    // Penalize bins whose residual is far from the mean (fragmentation signal).
    score += 0.15 * (post - mean_residual).abs();

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            // reward if next item fits snugly into the post-residual
            score -= 4.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // penalize near-miss: residual just below next item size
            let gap = nxt - post;
            score += 0.05 * gap * gap / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 5.0 * tightness;
    }

    // New-bin candidate: neutral baseline with mild penalty so we only open
    // new bins when existing fits are genuinely bad. Its post_residual == cap,
    // so the quadratic term already gives it a high base; add a progress-scaled
    // reluctance to open bins late in the stream.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    } else {
        // Mild reward for keeping the number of open bins low.
        score -= 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Dead-space penalty: residuals that are unusable by typical items.
    if post_residual > 0 {
        // Harmonic classes via integer division thresholds on post_residual
        let q = post_residual / (bin_capacity / 4); // class 0..4
        let class_penalty: f64 = match q {
            0 => 0.0,          // residual < 25: mostly dead space
            1 => -2.0,         // 25..49: fits small items
            2 => -5.0,         // 50..74: good leftover
            _ => -8.0,         // >=75: excellent leftover
        };
        score += class_penalty;

        // Non-linear tightness reward: exact-ish fits
        score -= 6.0 / (1.0 + post * 0.15);
    } else {
        score -= 20.0; // perfect fill
    }

    // Lookahead coupling: does leftover fit the next item exactly?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap);
            // Harmonic match: next item divides leftover nicely
            if post_residual % next_item_size.max(1) == 0 && next_item_size <= post_residual {
                score -= 3.0;
            }
        } else {
            score += 2.0; // leftover too small for next item
        }
    }

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize opening new bins when plenty of open bins have room
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open = open_bins_count as f64;
        score += 6.0 + 4.0 * (1.0 - progress) + 0.05 * avg_open;
        // But allow new bin if item is huge and mean residual is small
        if item_size as f64 > 0.8 * cap && mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Mild tie-breaking toward balanced residuals across bins
    score += 0.02 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps that no future item
    // (10..80 typical, but allow 1..100) can use are pure waste.
    let dead_threshold = 9.0; // gaps <= 9 are almost certainly unusable
    if (post_residual as f64) <= dead_threshold {
        score += 40.0; // heavy penalty for near-unusable slivers
    }

    // Penalize gaps that the lookahead item cannot fit into.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 20.0 * tightness * tightness; // quadratic reward for tight packing
    }

    // Reward filling bins that are already quite full (close the bin out).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating;
    // when few bins are open, spreading is cheaper so soften the penalty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 1.5 * open_bins_count as f64 * (0.5 + progress);

    // Slight preference for bins below mean residual (keeps residuals uniform,
    // preserving flexibility for future items).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: mild baseline so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base preference for tight fits: relative residual vs mean residual.
    let rel = post / cap;
    let mean_rel = mean_residual / cap;
    score += 20.0 * (rel - mean_rel);

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // or nearly matches the next item size (chain two items into one bin).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            // Next item can also fit here: strong reward for good chaining.
            score -= 30.0 * (1.0 - gap / cap);
            if gap == 0.0 {
                score -= 15.0; // perfect 2-item chain
            }
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 10.0 * (post / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Allow new bin if remaining open bins are very full already.
        if mean_residual < 0.15 * cap {
            score -= 30.0;
        }
    }

    // Late in stream, tighten packing (avoid leftover fragments).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * rel;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but with diminishing returns
    // so that leaving 0 residual is heavily favored over leaving 5.
    let pr = post_residual as f64;
    score = pr * (1.0 + 0.015 * pr / (bin_capacity as f64).sqrt());

    // Tight-fit reward: quadratic bonus for very small post residual.
    if post_residual <= 12 {
        score -= 8.0 * (12.0 - pr);
    }

    // Dead-space penalty: post residual too small for the smallest plausible
    // future item is nearly worthless space.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Lookahead: reward if the next item fits exactly-ish into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Chain-fit bonus, stronger when slack is tiny (perfect 2-chain).
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: post residual is likely dead space
            // unless it's near zero. Penalize proportionally to wasted space.
            let waste = pr.min(nxt - post_residual as f64);
            score += 0.35 * waste;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, avoid opening
    // a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
        // But if the new-bin option would give a perfect fit for the next
        // item too, soften the last-chance bonus.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // New-bin candidate handling: an empty bin starts at score = capacity-ish;
    // make it attractive only when existing residuals are fragmented or few
    // bins can fit the item.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score = bin_capacity as f64 * 0.9;
        // Attractive when open bins are mostly full (low mean residual).
        score -= 0.8 * (bin_capacity as f64 - mean_residual);
        // Attractive when few alternatives exist.
        if fitting_bins_count <= 1 {
            score -= 14.0;
        }
        // Early in stream: opening bins is cheap and useful for future freedom.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // Large current item: fresh bin guarantees fit without fragmenting.
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // => prefer consolidating into existing bins (non-new-bin candidates).
    if bin_residual < bin_capacity {
        score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // Reward using bins whose residual is close to the item (good match).
        let match_quality = 1.0 - ((bin_residual - item_size) as f64 / bin_capacity as f64).abs();
        score -= 5.0 * match_quality;
    }

    // Late-stream consolidation: near the end, avoid leaving tiny residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && post_residual > 0 && post_residual < 15 {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, small residuals matter less; late, tight packing matters more.
    let progress_coupling = 1.0 + 1.2 * progress * progress;
    score *= progress_coupling;

    // Reward bins whose residual aligns with the next item (lookahead fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let match_bonus = (1.0 - gap / cap).max(0.0);
        score -= 6.0 * match_bonus * match_bonus;
    }

    // Penalize creating dead space relative to mean residual of open bins.
    let dead = (pr - mean_residual).abs();
    score += 0.15 * dead * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Mild penalty when many bins are open — encourage consolidation.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are poor.
    if bin_residual == bin_capacity {
        score = pr + 8.0 - 4.0 * progress - (mean_residual / cap) * 4.0;
        if fitting_bins_count <= 1 {
            score -= 6.0; // opening a bin is fine when alternatives are exhausted
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: an empty bin is only attractive when the item
    // fits badly everywhere else or nothing is open.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        if open_bins_count == 0 || fitting_bins_count == 0 {
            return -1000.0; // must open a bin
        }
        // Penalize opening a new bin; relax if this bin is the last chance.
        let mut nb = 250.0 + (open_bins_count as f64) * 20.0;
        if fitting_bins_count == 1 {
            nb -= 300.0;
        }
        // If item + next item pack perfectly into a fresh bin, reward it.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            nb -= 400.0;
        }
        return nb + (post_residual as f64) * 0.01;
    }

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let cap = bin_capacity;
    let quarter = cap / 4;
    let eighth = cap / 8;

    // Perfect fit -> strong reward.
    if pr == 0 {
        score -= 500.0;
    } else {
        // Reward residuals that are "harmonic" multiples of small divisions of
        // capacity: these are likely to be exactly filled by future items.
        let mut harmony = 0.0;
        if pr % quarter == 0 { harmony += 120.0; }
        if pr % eighth == 0 { harmony += 60.0; }
        if pr % 10 == 0 { harmony += 40.0; }
        if pr % 5 == 0 { harmony += 15.0; }
        score -= harmony;

        // Dead-space penalty: tiny residuals are hard to fill.
        if pr < 10 {
            score += 200.0;
        } else if pr <= 20 {
            score += 60.0;
        }

        // Harmonic class via integer division thresholds on post_residual.
        let class = pr / eighth; // 0..=12
        score += (class as f64) * 3.0;
    }

    // Lookahead coupling: if the next item exactly fills the post-residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 350.0;
        } else if next_item_size < pr {
            score -= 25.0;
        } else {
            // Next item cannot use this bin's leftover; slight penalty if it
            // also cannot fit the remaining residual class.
            score += 15.0;
        }
    }

    // Last-chance bin: using the only bin that fits avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= fill_frac * 100.0;

    // Stream progression: early on, keep bins balanced with mean residual;
    // later, prefer aggressive consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (0.3 * (1.0 - progress));
    score -= progress * 30.0;

    // Mild preference to spread across fewer bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (1..10)
    // are truly unusable -> heavy penalty for creating tiny dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits (waste 0 is ideal, small waste slightly rewarded).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Coupling: dead space is worse when the bin is already sparse.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill_ratio;

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage opening a new bin.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 8.0 + 2.5 * open_bins_count as f64;
        // But allow a new bin if no existing bin fits well and lookahead
        // item is large relative to this bin's residual.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let avg_fit = mean_residual / open_bins_count.max(1) as f64;
            if avg_fit - item_size as f64 > 25.0 {
                score -= 15.0;
            }
        }
    } else {
        // Favor bins whose residual matches the item closely (best-fit flavor).
        score -= 6.0 * (1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64);
    }

    // Lookahead synergy: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // dead space unusable for the known next item -> extra penalty
        score += 10.0;
    }

    // Slight progression term: later in the stream, be more conservative
    // (prefer filling existing bins over spreading).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !new_bin {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving awkward gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 50.0 * tightness;

    // Penalize post_residual relative to mean residual (dead space above average).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are poor,
    // but allow opening when residuals are getting fragmented.
    if bin_residual == bin_capacity {
        score += 120.0 + 20.0 * (open_bins_count as f64);
        // If next item is large and nothing fits well, new bin more attractive.
        if next_item_size > 60 {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 80.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.93;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;

    // Base: quadratic polynomial in post_residual, scaled by stream progress.
    let mut score = x * (1.0 + 1.3 * progress) * 40.0
        + 0.9 * x * x * cap * (0.5 + progress)
        - 0.35 * x * x * x * cap * (1.0 - progress);

    // Tight fits are rewarded more strongly as the stream progresses.
    let tightness = 1.0 - x;
    score -= 12.0 * tightness * tightness * (0.6 + progress);

    // Dead space that cannot fit the lookahead item is penalized smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.4 + 0.8 * progress);
        } else {
            score -= 0.25 * (1.0 - (pr - nx) / cap) * progress;
        }
    }

    // Last-chance bin before opening a new one gets a bonus.
    if fitting_bins_count == 1 {
        score -= 8.0 * (0.5 + 0.5 * progress);
    }

    // Mild pressure toward consolidation when many bins are open.
    score += 0.15 * open_bins_count as f64 * x;

    // Alignment with mean residual: prefer residuals near the mean early.
    let dev = (pr - mean_residual) / cap;
    score -= 5.0 * dev * dev * (1.0 - progress);

    // New empty bin candidate: penalize opening unless residual is unusable.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fill (0) strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: residuals that no plausible item (1..=100) can
        // split well are penalized. A residual r is "usable" if some small
        // item can fill it; small residuals are the worst dead space.
        let r = post_residual;
        if r < 10 {
            score += 60.0; // tiny unusable sliver
        } else if r <= 25 {
            score += 15.0; // only small items fit
        }
        // Harmonic tier: bucket residual by integer division of capacity/4.
        let tier = r / (bin_capacity / 4);
        score -= tier as f64 * 8.0; // larger leftover space is more flexible
    }

    // Modulo-classes coupling: next_item_size divides residual space nicely?
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 500.0; // lookahead perfect fit: reserve this bin
        } else {
            // reward when gap falls into "harmonic" small classes
            let gmod = gap % 10;
            if gmod == 0 {
                score -= 20.0;
            } else if gap < 10 {
                score += 30.0; // creates sliver after lookahead item
            }
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // bin becomes dead for the lookahead item; penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / cap;
    score -= fill * 25.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    // and many bins are already open (avoid bin proliferation).
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64) * 2.0;
        if mean_residual > 20.0 {
            score += 10.0;
        }
    }

    // Mild stream-progression term: early on, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any future item (min size 1,
    // but practically small gaps are waste). Penalize tiny gaps super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 8.0; // unusable sliver -> heavy penalty
        } else if pr < 20.0 {
            score += (20.0 - pr) * 3.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 40.0 - slack * 2.0; // chains a near-perfect follow-up
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item would have fit before this placement but not after: penalty
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * (2.0 + 4.0 * progress);

    // New-bin candidate: make empty bin attractive only when current bin's
    // post-fit residual is a dead sliver and no other bin is a last chance.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10 && fitting_bins_count > 1;
        if poor_fit {
            score -= 30.0; // allow escape from creating dead space
        } else {
            score += 25.0 + open_bins_count as f64 * 3.0; // default: prefer open bins
        }
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize wasted residual quadratically (dead space is unusable space).
    score += 0.02 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward near-perfect fits strongly.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can still fit here: strong reward scaled by tightness of the chain.
            score -= 25.0 - 0.4 * gap;
        } else {
            // Next item won't fit: mild penalty proportional to overflow gap.
            score += 0.3 * gap;
        }
        // Exact chain match: post_residual == next_item_size is ideal.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; penalize so only genuinely bad fits trigger it.
        score = post_residual as f64 + 45.0;
        if next_item_size > 0 {
            // A fresh bin can chain well if the next item is large.
            if next_item_size >= 60 {
                score -= 30.0;
            }
        }
        // Late in the stream, avoid accumulating many nearly-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins already fit the item, opening another is wasteful.
        score += 8.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of residual penalizes wasted space harder.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Perfect or near-perfect fit gets strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.5 * (post_residual - next_item_size).min(30) as f64;
        } else {
            // leftover too small for next item: penalize dead space unless tiny
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Cost of a new bin grows with how many bins are already open and stream progress.
        score += 30.0 + 3.0 * open_bins_count as f64 + 10.0 * progress;
        // But if this bin would be a great fit and existing bins are fragmented, discount.
        if post_residual <= 10 && mean_residual < 15.0 {
            score -= 35.0;
        }
    } else {
        // Prefer bins already below mean residual (consolidation), penalize outliers.
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Early in stream: be slightly more willing to spread out (keep flexible bins).
    if progress < 0.2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits via non-linear post_residual penalty
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, demand tight packing.
    let prog2 = progress * progress;
    score += pr * (0.5 + 1.5 * prog2);

    // Reward high fill ratio, amplified as stream progresses
    score -= fill * fill * (1.0 + progress) * cap * 0.3;

    // Dead-space penalty: residuals too small for typical items are wasted
    if pr > 0.0 {
        let dead = (pr / 10.0).floor() * 10.0;
        score += dead * dead * 0.002 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 8.0 * prog2;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - pr).max(0.0) * 0.05;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.1;

    // Prefer bins below mean residual (consolidating slack)
    score += (pr - mean_residual) * 0.05;

    // New-bin candidate: penalize slightly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - prog2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // "usable" classes (divisible by common item sizes) are favored.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus -= 60.0; // perfect fit
    } else if pr <= 10 {
        class_bonus -= 25.0; // near-perfect, dead space tiny
    } else {
        // divisibility by common harmonic denominators (10,20,25,50)
        if pr % 10 == 0 { class_bonus -= 12.0; }
        if pr % 25 == 0 { class_bonus -= 8.0; }
        if pr % 50 == 0 { class_bonus -= 6.0; }
        // integer-division thresholds: leftover in [11,20] is a "half-slot"
        let slot = pr / 10;
        class_bonus -= (slot as f64) * 1.5;
        // penalize awkward leftovers in (10, 20) modulo bands
        if pr % 20 > 10 && pr % 20 < 15 { class_bonus += 6.0; }
    }
    score += class_bonus;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 15.0 - (slack as f64) * 0.3;
        } else {
            // next item won't fit here: mild penalty proportional to overshoot class
            score += ((next_item_size - pr) / 10) as f64 * 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or the bin is nearly full anyway.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.8;
        let open_pressure = (open_bins_count as f64) / 20.0;
        score += 45.0 + open_pressure - if tight_fit { 20.0 } else { 0.0 } - progress * 10.0;
    }

    // Slight preference for filling bins below mean residual (balancing).
    score += (mean_residual - post_residual as f64) * 0.1;

    // Tie-break with harmonic class of item itself.
    score += ((item_size % 10) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can't hold even the smallest
    // plausible item (<= 10) are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Small gaps that only fit tiny items are semi-dead.
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Tightness ratio: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; when few,
    // opening a new bin (empty candidate) is more acceptable.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, escalating with open bins count,
        // but relax if the fit into existing bins would leave large dead space.
        score += 20.0 + 6.0 * pressure;
        if post_residual >= 40 {
            score -= 25.0; // a fresh bin with room for big future items is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= next_item_size as f64 * 0.3;
        }
    } else {
        // Existing bin: bonus for keeping the item in an already-open bin,
        // stronger when many bins are open.
        score -= 8.0 + 4.0 * pressure;
    }

    // Lookahead coupling: if next item fits exactly into the post-residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual && post_residual - next_item_size < 10 {
            score -= 20.0;
        }
    }

    // Late in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    // Mean-residual alignment: bins whose residual deviates strongly from the
    // mean residual landscape are less predictable; slight penalty.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual
    // with next_item_size (perfect two-item fill).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();

        // Perfect match: huge reward.
        if diff == 0.0 {
            score -= 500.0;
        } else if post_residual as f64 > nxt {
            // Item fits now, next item could still fit here: moderate reward,
            // scaled by how close the residual is to the next item.
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space: residual too small for the next item. Penalize
            // proportionally to wasted space relative to next item size.
            let waste = nxt - post_residual as f64;
            score += 25.0 * (waste / nxt.max(1.0));
        }

        // Extra bonus if post_residual can host next item AND mean residual
        // suggests other bins are tighter (keep this bin for chaining).
        if post_residual as f64 >= nxt {
            score -= 10.0 * (mean_residual / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize residual.
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate penalty: only open a new bin when the item is large
    // relative to capacity (poor fits elsewhere are likely) or many bins exist.
    if bin_residual == bin_capacity {
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 100.0 * large_item_bonus
            + 5.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 50.0 * progress;
    }

    // Prefer bins with tighter residuals (best-fit flavor) among open bins.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference for bins that leave round residuals (multiples of 10),
    // which tend to pair well with typical item granularities.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with non-linear shaping.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving residuals that no plausible future item can use well.
    // Dead space: residual too small to be useful (< ~10) or awkward band.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0; // nearly unusable sliver
    } else if post_residual >= 12 && post_residual < 25 {
        score += 15.0; // awkward band
    }

    // Reward exact/near-exact closures.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize placements that strand space just above it.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        }
    }

    // Time horizon: early in the stream, prefer consolidating into existing bins
    // (keep flexibility); late in the stream, be more tolerant of new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (fitting_bins_count as f64);

    // Global state: many open bins with high mean residual -> discourage new bins,
    // encourage packing into bins with residual near mean (balanced packing).
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score -= 8.0;
    }
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate logic: opening a new bin costs ~1 bin; make it attractive
    // only when this bin would be badly fragmented or no real fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = 55.0 + 0.3 * (item_size as f64);
        // Attractive when item is large relative to capacity (fills new bin well).
        score -= 40.0 * (item_size as f64 / bin_capacity as f64);
        // Less attractive if existing bins are plentiful with room.
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // Early stream: new bins are cheaper (more future items to fill them).
        score -= 25.0 * (1.0 - progress);
        // If next item is large and current item small, new bin preserves space.
        if next_item_size > item_size && next_item_size > bin_residual - item_size {
            score -= 20.0;
        }
        // Perfect-fit alternative exists elsewhere: don't open a new bin.
        if post_residual == 0 && fitting_bins_count > 0 {
            score += 200.0;
        }
    }

    // Mild preference for bins that are already fairly full (waste little overall).
    score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (larger leftover = better packing)
    let mut score = pr;

    // Smooth non-linear coupling: post_residual shaped by stream progress.
    // Late in the stream, waste is more costly -> penalize residuals quadratically.
    let progress_shape = 0.5 + progress * progress;
    score -= (pr * pr / cap) * 0.8 * progress_shape;

    // Reward tight fits: cubic decay of normalized residual near zero
    score += 12.0 * (1.0 - norm_pr).powi(3) - 12.0 * (1.0 - norm_pr).powi(4);

    // Penalize residuals that are too small to be useful later, scaled by progress
    let dead = if pr > 0.0 { (1.0 - norm_pr).max(0.0) } else { 0.0 };
    score += progress * 20.0 * dead * dead;

    // Lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (nxt - pr) * (0.4 + 0.6 * progress);
        } else {
            score -= 4.0 * (pr - nxt).min(20.0) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty tied to crowding relative to mean residual
    score += (mean_residual - pr) * 0.05;

    // Slight preference for keeping few bins open early on
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: prefer residuals in "usable" classes.
    // Class 0 (perfect fit) is best; small residuals (1..=9) are dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit bonus
    } else if post_residual <= 9 {
        score += 25.0; // tiny dead space penalty
    } else {
        // modulo-10 harmonic class: residuals divisible by 10 pair well with
        // typical item granularity
        let cls = post_residual % 10;
        score -= (10 - cls) as f64 * 0.8;
        // reward residuals that can host a mid/large item later
        if post_residual >= 40 {
            score -= 8.0;
        }
        if post_residual >= 70 {
            score -= 6.0;
        }
    }

    // Fractional capacity logic: how full the bin becomes
    let fill = (bin_residual as f64 - post_residual as f64) / cap;
    score -= fill * fill * 20.0; // convex reward for high fill fraction

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let nxt_fill = next_item_size as f64 / post_residual as f64;
            score -= nxt_fill * 15.0;
            // penalize leaving a residual that next item splits badly
            if post_residual > next_item_size && (post_residual - next_item_size) <= 9 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave bad (small) residuals.
    if bin_residual == bin_capacity {
        // fresh bin baseline: residual after = capacity - item_size
        let fresh_post = cap - item_size as f64;
        let mut fresh_score = fresh_post;
        if fresh_post >= 40.0 { fresh_score -= 8.0; }
        if fresh_post >= 70.0 { fresh_score -= 6.0; }
        if fresh_post % 10.0 == 0.0 { fresh_score -= 4.0; }
        // scale by how crowded current bins are
        let crowd = mean_residual / cap;
        fresh_score -= (1.0 - crowd) * 10.0;
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        fresh_score += progress * 25.0;
        fresh_score += open_bins_count as f64 * 1.5;
        score = score.max(fresh_score) - (score - fresh_score).abs() * 0.0;
        score = fresh_score + 5.0; // slight bias against opening bins by default
    }

    // Mean-residual harmony: bins far from the mean residual get a nudge toward reuse
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.15;

    // Integer division threshold on post_residual: quarters of capacity
    let q = post_residual / (bin_capacity / 4);
    match q {
        0 => score += 10.0,   // < 25 left: mostly dead
        1 => score += 2.0,
        2 => score -= 3.0,
        _ => score -= 6.0,    // >= 75 left: very reusable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead space is nearly worthless
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // small gap, only fits few item sizes
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit, eliminate a residual entirely
    }

    // Favor bins whose post residual still matches a plausible next item (lookahead k=2)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // extra reward for near-exact match with next item
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / 50.0).max(0.0);
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // next item can't fit anywhere in this bin anyway; neutral
        score += 0.0;
    } else if next_item_size > 0 {
        score += 6.0; // this placement wastes space the next item could have used
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer tight fills
    let ob = open_bins_count as f64;
    score += 0.8 * ob * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (good fits)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when current fit is bad or no real alternative
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && post_residual < 25 { 1.0 } else { 0.0 };
        score += 55.0 - 45.0 * bad_fit;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: opening new bin is correct
        }
        if open_bins_count == 0 {
            score -= 60.0; // must open
        }
    }

    // Slight progression bias: late in stream, prefer closing bins out (perfect fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual strongly (non-linear).
    if post_residual > 0 {
        score -= 30.0 / (post_residual as f64).sqrt();
    } else {
        score -= 60.0; // perfect fit
    }

    // 2-step lookahead: reward when next item matches the post_residual well.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if next_item_size <= post_residual {
            score -= 25.0 / (1.0 + diff as f64);
        } else {
            // next item won't fit in leftover; penalize large dead space relative to next item
            score += 0.15 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Compare against mean residual of open bins: prefer bins below mean residual
    // (i.e., fuller bins) to keep large residuals available for large future items.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only attractive
    // when no existing bin fits well (item is large relative to residuals) or
    // early in the stream when we can afford spreading.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = (item_size as f64 / bin_capacity as f64) > 0.6;
        let poor_alternatives = fitting_bins_count == 0;
        if poor_alternatives || (tight && progress < 0.5) {
            score -= 50.0;
        } else {
            score += 45.0; // discourage wasting a fresh bin
        }
    }

    // Mild reward for keeping many open bins balanced (avoid fragmentation).
    if open_bins_count > 0 {
        score -= 2.0 * (post_residual as f64 / bin_capacity as f64).ln().max(-3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 5 {
        score += 50.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score += 20.0 + 60.0 * (1.0 - fit_quality);
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation_pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    score += consolidation_pressure * 8.0 * (1.0 - progress);

    // Late in the stream, prefer placements minimizing residual even more.
    score -= progress * (bin_capacity - post_residual) as f64 * 0.2;

    // Mild penalty for wasting a large bin residual on a small item.
    if (item_size as f64) < 0.35 * bin_residual as f64 && bin_residual != bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: quadratic in post_residual, damped by progress
    let mut score = pr * (1.0 + 0.9 * pr / cap) * (1.0 - 0.5 * progress);

    // Tight-fit reward: smooth coupling of fit fraction with progress
    score -= fit_frac * fit_frac * cap * (0.6 + 0.8 * progress);

    // Penalize residuals that are smooth dead space: residual^3 normalized
    score += (pr / cap).powi(3) * cap * (0.4 + 0.6 * progress);

    // Last-chance bonus: strongly favor the only fitting bin, scaled by progress
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // New-bin candidate: mildly penalize early, allow late when fits are poor
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 18.0 * (1.0 - progress) * pressure
            - 8.0 * progress * (1.0 - fit_frac);
    }

    // Lookahead coupling: reward if next item fits the post residual (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0) * (pr >= nxt) as i32 as f64;
        score += 4.0 * (gap / cap) * (pr < nxt) as i32 as f64;
    }

    // Mean residual alignment: penalize bins far from the fleet mean
    score += 0.15 * (pr - mean_residual).abs();

    // Slight penalty for many open bins to discourage sprawl
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by capacity fraction.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c;

    // Class boundaries: perfect fit (0), tiny (<=10), small (<=25), mid (<=50), large (>50)
    if post_residual == 0 {
        score -= 100.0; // perfect fit, best possible
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 25 {
        score -= 20.0;
    } else if post_residual <= 50 {
        score -= 5.0;
    } else {
        // large leftover: penalize proportionally above baseline
        score += (frac - 0.5) * 30.0;
    }

    // Modulo arithmetic on post_residual: residues that pair well with common item sizes
    // (items 1..100, small residuals like 10/20/25/50 are reusable)
    let mod10 = post_residual % 10;
    if mod10 == 0 && post_residual > 0 {
        score -= 8.0; // residual is a multiple of 10: likely reusable
    } else if mod10 != 0 {
        score += mod10 as f64 * 0.5; // awkward residue: dead-space penalty
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 25.0 / (1.0 + gap as f64);
            // harmonic class of the gap
            if gap % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by wasted potential
            score += 4.0;
        }
    } else {
        // last item: any fit is fine, prefer tightest
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / c; // average fill opportunity in open bins
        if pressure < 0.15 {
            score -= 15.0; // open bins nearly full: new bin is fine
        } else {
            score += 25.0 + pressure * 40.0; // discourage wasting fresh capacity
        }
    }

    // Progress-based mild preference for filling older bins as stream advances
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter than average)
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3; // tighter-than-average bins get lower score
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (too small for typical items) are heavily penalized.
    let dead_zone_low = 1.0f64;
    let dead_zone_high = 12.0f64;
    if post_residual >= 1 {
        let pr = post_residual as f64;
        if pr <= dead_zone_high && pr >= dead_zone_low {
            // Deeper in the dead zone => worse. Peak penalty mid-zone.
            let depth = 1.0 - ((pr - dead_zone_low).abs() / (dead_zone_high - dead_zone_low));
            score += 40.0 * depth + 25.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size as f64 + post_residual as f64);
    score -= 18.0 * tightness;

    // Exact fill is excellent.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open bins pressure: discourage opening new bins when many bins are open,
    // unless the fit is very tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 8.0 * bin_pressure * (0.4 + 0.6 * progress);
        // If this is the only fitting option, opening a new bin is acceptable.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    } else {
        // Reward using existing bins, more so when they are below mean fullness.
        let rel = if mean_residual > 0.0 { (bin_residual as f64) / mean_residual } else { 1.0 };
        score -= 6.0 * rel.min(2.0);
        // Last-chance bin: strong reward to use it rather than open a new one.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item fits the post-residual, this placement
    // leaves a useful gap -> reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap useless for next item: mild penalty scaled by gap smallness.
        let gap_uselessness = 1.0 - (post_residual as f64 / next_item_size as f64).min(1.0);
        score += 8.0 * gap_uselessness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-gap / 8.0).exp();          // strong bonus for exact chain fit
        score -= 12.0 * (-gap / 25.0).exp();         // softer bonus for near fit
        // Penalize leaving residual that next item cannot use at all
        if post_residual < next_item_size {
            score += 6.0;
        }
    } else {
        // Last item: pure tight-fit mode
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "waste traps" unless the item fits very well; bins far above mean
    // are good candidates to consume.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep the empty bin available but not
    // dominant when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If no open bin fits, the new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure against accumulating many open bins with stale space.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize bins whose residual is small but not zero (dead space waste).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward if next item fills bin nearly completely after.
            let nr = post_residual as f64 - next_item_size as f64;
            if nr <= 10.0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; mild penalty for leaving awkward residual.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    // or no good alternative exists.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score = bin_capacity as f64 * 0.75;
        // Less eager to open new bins when many open bins already have room.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // If this is the only option, opening is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Prefer bins below mean residual (balancing open bins toward fuller ones).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Slight preference to keep number of open bins low early on.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = 1.0 - pr / cap; // fill ratio after placement

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score -= 18.0 * tight * tight * (0.5 + prog2);
    score -= 12.0 * tight * prog3;

    // Penalize large dead space, amplified late in the stream
    let waste = pr / cap;
    score += 10.0 * waste * waste * (1.0 + progress);

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let gap = (pr - ns) / cap;
            score -= 8.0 * (1.0 - gap * gap);
            score += 2.0 * gap * gap * (1.0 + progress);
        } else {
            score += 6.0 * (ns - pr) / cap * (0.5 + progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild pressure from bin count and mean residual
    score += (open_bins_count as f64).ln() * 1.5 * (1.0 - tight);
    score -= 2.0 * (mean_residual / cap - pr / cap);

    // Perfect-fit reward
    if pr == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space penalty: residuals too small to fit typical items are worthless.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0;
    }

    // Modulo-harmonic classes on post_residual: residuals that divide capacity
    // nicely (e.g. 50, 25, 20, 10) are reusable "harmonic" slots.
    let harmonic_divisors: [u32; 6] = [50, 25, 20, 10, 5, 2];
    for (k, &d) in harmonic_divisors.iter().enumerate() {
        if post_residual % d == 0 {
            score -= (6.0 - k as f64) * 12.0;
            break;
        }
    }

    // Reward when the next item fits exactly into the post residual (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            // Harmonic check: does next item leave another clean residual?
            let post2 = post_residual - next_item_size;
            if post2 % 10 == 0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += 10.0 + 20.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins when open bins already have low mean residual usage.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin.
        score = bin_capacity as f64 * 0.9 + 30.0;
        // Early in stream, prefer consolidation into existing bins.
        score += 80.0 * (1.0 - progress);
        // If existing bins fit poorly (few fitting bins), new bin less bad.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        return score;
    }

    // Prefer bins whose residual is close to item size (tight fit) beyond raw post_residual.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness);

    // Mild penalty when this bin's residual deviates from mean residual (imbalance).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Late in stream, consolidate aggressively.
    score -= 40.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (or for the known next item) are wasted space.
    let min_item = 1u32;
    let dead = post_residual > 0 && post_residual < min_item.max(next_item_size.min(20));
    if dead {
        // The smaller the dead gap relative to capacity, the harsher the penalty.
        let gap_frac = post_residual as f64 / bin_capacity as f64;
        score += 60.0 * (1.0 - gap_frac) + 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // If this bin's residual can host the next item exactly, keep it usable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Post-residual too small for the lookahead item: future dead space risk.
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer new-bin
    // consolidation only when the current fit is poor.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * pressure;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., when mean residual is small and this is a fresh empty bin.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / bin_capacity as f64;
        // Penalize opening a new bin normally...
        score += 30.0;
        // ...but reward it when open bins are nearly full (poor fits remain).
        score -= 45.0 * (1.0 - mean_frac).min(1.0);
        // Slightly cheaper to open bins early in the stream.
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Mild bias toward filling fuller bins first (best-fit flavor).
    score -= 0.3 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: zero waste is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills the new residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item still fits: mild reward proportional to tightness.
            let tight = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // Dead space: next item cannot use the leftover; penalize.
            let dead = (next_item_size - post_residual) as f64;
            score += 2.0 * dead;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // wasting them hurts more. Bins above mean residual are safer to consume.
    let mean_gap = post_residual as f64 - mean_residual;
    if mean_gap < 0.0 {
        score += 1.5 * (-mean_gap);
    } else {
        score -= 0.5 * mean_gap;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when open bins would leave large waste.
    if bin_residual == bin_capacity {
        // Neutral baseline; slight penalty so tight fits in open bins win.
        score += 40.0;
        // But if the item is large relative to capacity and no tight option
        // exists, the mean-residual logic above already pushes new bins.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Late in the stream: consolidate more aggressively (fewer bins at the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: residuals too small to fit the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Lookahead: reward if the next item can still fit into the leftover space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            score += 8.0;
        }
        // Perfect two-item packing bonus
        if item_size + next_item_size == bin_residual {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Crowd control: with many open bins, prefer filling existing ones.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins whose residual is near the item (tight fit) beyond raw post_residual.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Time horizon: early on, keep bins flexible (favor larger leftovers); late, pack tight.
    score -= (1.0 - progress) * 0.2 * post_residual as f64;
    score += progress * 0.3 * post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless it beats existing fits clearly.
    if is_new_bin {
        score += 55.0 + 0.4 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0; // new bin pairs well with the next item
        }
    } else if bin_residual - item_size == 0 {
        score -= 50.0; // perfect fill
    }

    // Mild alignment with global mean residual: prefer bins close to average state.
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on post-residual (waste minimization), smoothed
    let mut score = pr * (1.0 + 0.5 * pr_norm);

    // Non-linear coupling of post-residual with stream progress:
    // later in the stream, tight fits matter more (dead space is costlier)
    let coupling = pr_norm * pr_norm * progress;
    score += 30.0 * coupling;

    // Reward near-perfect fits with a smooth saturating term
    let fit_quality = 1.0 - pr_norm;
    score -= 15.0 * fit_quality * fit_quality * (1.0 + progress);

    // Penalize bins whose residual diverges from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward if next item fits into post-residual (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Mild pressure to consolidate into fewer bins as open-bin count grows
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes of capacity fraction
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (post_residual % 10) as f64;
    let quot = (post_residual / 10) as f64;

    // Reward residuals that form "harmonic" sizes (nice divisors of 100)
    let harmonic = matches!(post_residual, 0 | 20 | 25 | 50 | 100);
    if harmonic {
        score -= 6.0;
    } else {
        score += class * 0.15; // penalize awkward fractional classes
    }

    // Dead-space penalty: small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 + 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mildly penalize leaving large residual
            score += (post_residual as f64) * 0.05;
        }
    }

    // Prefer tight fits: closeness of item to residual
    score += (bin_residual - item_size) as f64 * 0.3;

    // New-bin candidate handling: neutral-ish, but open new bin when all fits are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + frac * 10.0 - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 6.0; // big next item: fresh bin attractive
        }
    }

    // Slight preference for filling already-open bins when many are open
    score += open_bins_count as f64 * 0.05;

    // Mean residual coupling: penalize adding to bins far from mean residual class
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    // Integer-division threshold on quotients of post_residual
    if quot >= 5.0 && next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for the smallest
    // possible future item (size 1) are still usable, but gaps below a
    // "usefulness threshold" relative to typical item sizes are waste.
    // Penalize unusable gaps harshly with a quadratic term.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 0.8;
    }

    // Perfect-fit reward: leave zero residual.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual (small waste fraction).
    let waste_frac = post_residual as f64 / bin_residual.max(1) as f64;
    score += waste_frac * 15.0;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot use the leftover: mild dead-space penalty.
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: penalize placements that keep many bins open,
    // encouraging consolidation into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit. Make the empty bin moderately costly
    // so it wins only when all fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the mean residual across open bins is very low (all nearly
        // full), opening fresh capacity is reasonable.
        score -= mean_residual * 0.3;
    }

    // Reward using bins whose residual is close to the item (best-fit core).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.4;

    // Progress scaling: early in the stream, be more conservative about
    // opening bins; later, allow more aggressive consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 500.0; // chain perfect fit
        } else {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // penalize creating dead space unusable by next item
        score += 30.0;
    }

    // Penalize small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Mean residual coupling: prefer bins near the mean residual
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0; // pair packing in fresh bin is good
        }
        if fitting_bins_count == 1 {
            score -= 250.0; // but better than wasting last-chance bin? no: keep open bin
            score += 250.0;
        }
    }

    // Early stream: be frugal with bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 200.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Reward tight fits: waste fraction penalty (quadratic).
    let waste_frac = post_residual as f64 / cap;
    score += 30.0 * waste_frac * waste_frac;

    // Lookahead: if next item fits into post_residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Slight penalty if this placement strands space too small for the lookahead item.
        if post_residual < next_item_size {
            score += 5.0 * (1.0 - progress);
        }
    }

    // New-bin candidate: penalize opening a new bin unless necessary.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Must open a new bin: strong reward.
            score -= 1000.0;
        } else {
            // Opening a new bin while existing bins fit: penalize, more so early on.
            score += 40.0 * (1.0 - progress) + 10.0;
        }
    }

    // Last chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (fill below-average-residual bins).
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64 * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized residual
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Tight fits (small residual) are increasingly valuable as stream progresses.
    let tightness = (1.0 - prn) * (1.0 - prn);
    score -= 18.0 * tightness * (0.4 + 0.6 * progress);
    // Penalize mid-range residual dead space with a smooth bump, stronger late.
    let bump = 4.0 * prn * (1.0 - prn);
    score += 12.0 * bump * (0.3 + 0.7 * p2);

    // Lookahead: reward residuals that can host the next item, smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs();
        score -= 10.0 * fits_next * (1.0 - gap / cap) * (0.5 + 0.5 * progress);
        score += 6.0 * (1.0 - fits_next) * (prn * prn) * (0.5 + 0.5 * p3);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when many bins are open and this placement wastes space.
    let waste = prn.max(0.0);
    score += 3.0 * waste * (open_bins_count as f64).sqrt() / (1.0 + progress);

    // Slight preference to keep residuals near the mean (balance).
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap;

    // New-bin candidate: neutral-ish but penalized slightly so it only wins
    // when all open bins fit poorly (their scores will be higher).
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes (mod 10) are more likely to be filled by future items.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // classes 1..3 are nearly dead space -> penalize; classes 8..9 easily reused
        let class_penalty = match class {
            0 => -6.0,
            8 | 9 => -4.0,
            4 | 5 | 6 | 7 => 0.0,
            1 | 2 => 6.0,
            3 => 3.0,
            _ => 0.0,
        };
        score += class_penalty;

        // Integer-division thresholds: leftover divisible into halves/quarters
        // of capacity is reusable by mid-size items.
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 20 == 0 { score -= 3.0; }
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Tightness: reward small post_residual relative to capacity.
    let tight = 1.0 - (pr as f64 / cap);
    score -= 12.0 * tight * tight;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            score -= 6.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here; penalize large leftovers mildly
            score += 2.0 * (pr as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): make it attractive only when no open bin
    // is a good fit; default slightly above well-fitting open bins.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing large item with large next item is fine
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // poor alternatives exist -> open new bin
        }
    }

    // Mild stream-progression pressure: later in stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (mean_residual / cap).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0 + (20 - post_residual) as f64;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage opening new bins when bins exist.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64;
    } else {
        score -= 8.0;
    }

    // Last-chance bonus: only one bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Prefer bins with lower residual relative to mean (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late-stream consolidation pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size is perfect.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Slight preference when next item fits exactly vs overshoot
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 12.0; // next item cannot follow here
        }
    } else {
        // Last item: minimize leftover aggressively
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny unusable dead space (nonzero but small post_residual)
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Prefer bins with residuals below mean (tighter packing candidates)
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Late in stream: be more conservative, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 10.0 + 40.0 * progress;
    } else {
        score -= 8.0 * progress;
    }

    // Mild pressure against accumulating too many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 4.0 * tightness * tightness * bin_capacity as f64;

    // Penalize dead space that can't hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 1.5 * dead;
        } else {
            // Reward leaving exactly enough room for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 0.8 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Penalize creating very small unusable slivers (< 10-ish dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or the item is large and no bin is tight.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score += 18.0;
        if item_size > 60 {
            score -= 10.0; // large items pair well with fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
        if fit_quality > 0.5 && fitting_bins_count > 0 && item_size <= 60 {
            score += 15.0; // avoid wasting a fresh bin on small items
        }
    }

    // Prefer filling bins whose residual is close to the mean (balance), but
    // lean toward using bins with less residual as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.3 * residual_gap * (1.0 - progress);

    // Late in the stream, discourage opening extra bins.
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // Mild penalty per open bin for spreading items too thin.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let ni = next_item_size as f64;

    // Core: quadratic waste penalty, normalized
    let mut score = (pr / cap) * (pr / cap) * 100.0;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (waste is costlier)
    let progress_coupling = 1.0 + 2.0 * progress * (pr / cap);
    score *= progress_coupling;

    // Lookahead: reward residual that can host the next item (smooth sigmoid-ish match)
    if next_item_size > 0 && pr > 0.0 {
        let match_deg = (pr / (ni + 1.0)).min(1.5);
        let affinity = match_deg * (-match_deg * match_deg * 0.5).exp();
        score -= 40.0 * affinity;
    }

    // Penalize residual that cannot fit the next item at all (dead space)
    if next_item_size > 0 && pr < ni {
        score += 0.3 * (ni - pr);
    }

    // Last-chance bin: strong reward, scaled by how tight the fit is
    if fitting_bins_count == 1 {
        let tightness = 1.0 - (pr / cap);
        score -= 25.0 + 30.0 * tightness;
    }

    // Mild penalty when many bins are open and this placement leaves a large residual
    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * crowding * (pr / cap);

    // Deviation from mean residual: prefer bins near the average (balance workload)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: neutral baseline that must be beaten only by good fits
    if bin_residual == bin_capacity {
        score = 45.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over a small quantum.
    // Residuals in low classes (small leftover) are good; large leftovers are dead space.
    let quantum = 10u32;
    let class = post_residual / quantum; // 0..=10
    // Non-linear penalty on class: quadratic growth of dead space.
    score += (class as f64).powi(2) * 1.5;

    // Reward near-perfect packing: post_residual in lowest classes get strong subtraction.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // Harmonic class of the slack after the follow-up item.
            let next_class = slack / quantum;
            score -= 12.0 / (1.0 + next_class as f64);
        } else {
            // Next item cannot follow into this bin; slight penalty if it could
            // have fit had we chosen a tighter bin. Penalize wasted potential.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: proportional to remaining stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 70.0 + 60.0 * (1.0 - progress);
        // If many bins already fit the item, opening a new one is clearly worse.
        score += 30.0 * (fitting_bins_count as f64);
        // If the next item is huge and this item is small, a fresh bin keeps a
        // large contiguous block: mild discount.
        if next_item_size > 60 && item_size < 30 {
            score -= 25.0;
        }
        // Late in the stream, opening bins is expensive; discourage further.
        if progress > 0.8 {
            score += 20.0;
        }
    } else {
        // Existing-bin placements: reward using bins whose residual is far from
        // the mean (consolidating fragmentation), penalize when mean is small already.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= dev * 0.3;
        // Slight preference for bins with small residuals overall (tight bins first).
        score += (bin_residual as f64 / bin_capacity as f64) * 6.0;
        // Many open bins: encourage filling existing ones rather than spreading.
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Integer-division threshold: post_residual below half the smallest item
    // (size 1 min, but practical quantum 10) is nearly dead — extra penalty.
    if post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit even the
    // smallest plausible item (<= 1) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Residuals that can't fit the lookahead item are less useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.3 * open_bins_count as f64;
    }

    // Open-bin pressure: mild penalty per open bin encourages consolidation.
    score += 0.15 * open_bins_count as f64;

    // Mean-residual coupling: bins far below mean residual are less attractive
    // (keep big residuals for big future items).
    if (bin_residual as f64) < mean_residual - 15.0 {
        score += 3.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. keep it slightly worse than a decent existing fit but better
    // than forcing an item into a bin with bad dead space.
    if bin_residual == bin_capacity {
        score += 14.0 + 0.5 * open_bins_count as f64;
        // Large items justify a fresh bin more readily.
        if item_size > 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // fresh bin can pair current + next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else {
        // Penalize dead space quadratically, normalized by capacity.
        let waste = (post_residual as f64) / (bin_capacity as f64);
        score += waste * waste * 150.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 350.0; // perfect pair
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit: penalize proportionally to leftover gap
            let gap = (next_item_size - post_residual) as f64;
            score += 60.0 * (gap / 100.0);
        }
    }

    // Compare residual against mean residual across open bins.
    if post_residual as f64 > mean_residual + 25.0 {
        score += 40.0; // leaving this bin unusually full of space is wasteful
    } else if (post_residual as f64) < mean_residual - 25.0 {
        score -= 25.0; // tightening a loose bin is good
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., current bin residual is small relative to item) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (bin_residual as f64 - item_size as f64) < 0.5 * mean_residual.max(1.0);
        if poor_fit || open_bins_count == 0 {
            score -= 180.0 + 100.0 * (1.0 - progress);
        } else {
            score += 250.0; // discourage opening new bins when decent fits exist
        }
    }

    // Mild preference to fill older/more bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills.
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that can never host a typical small item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 2.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits via competition term.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: make it costly unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 12.0;
        if fragmentation > 0.5 * bin_capacity as f64 {
            score -= 14.0; // open bins too full/empty; new bin justified
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big item coming, keep fresh capacity
        }
    }

    // Time horizon: early stream, be conservative with bins; late stream, exploit tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * tightness;
    score += 2.0 * (1.0 - progress) * (open_bins_count as f64 / (total_items.max(1) as f64).sqrt());

    // Global residual alignment: prefer bins whose residual is close to the mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * pr_norm * pr_norm          // penalize large leftover space quadratically
        - 60.0 * pr_norm * pr_norm * pr_norm; // but very tight fits (tiny pr) get slight reward

    // Smooth interaction: progress amplifies the value of tight fits
    score -= 30.0 * progress * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Penalize dead space relative to mean residual (smooth quadratic coupling)
    let dead = (pr - mean_residual) / cap;
    score += 25.0 * dead * dead;

    // Lookahead: reward if next item fits in post residual (smooth sigmoid-like)
    if next_item_size > 0 {
        let fit = next_item_size as f64 / cap;
        let margin = (pr - next_item_size as f64) / cap;
        let s = 1.0 / (1.0 + (-8.0 * margin).exp());
        score -= 35.0 * s * (1.0 - fit);
        // penalize if post residual too small for next item (near-miss waste)
        let miss = ((next_item_size as f64 - pr) / cap).max(0.0);
        score += 20.0 * miss * miss * (1.0 - progress);
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - item_norm) * (1.0 - 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress * item_norm;

    // New-bin candidate: prefer opening a fresh bin only when current fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - item_norm) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward post_residuals that belong to "usable" harmonic classes:
    // residuals in [1..=eighth] are near-perfect fills (dead space minimal).
    if post_residual >= 1 && post_residual <= eighth {
        score -= 12.0;
    } else if post_residual > eighth && post_residual <= quarter {
        score -= 6.0;
    } else if post_residual > quarter && post_residual <= bin_capacity / 2 {
        score += 4.0;
    } else {
        // Large leftover: penalize unless it matches next item size class.
        score += 8.0;
    }

    // Integer-division harmonic class of post_residual w.r.t. next_item_size:
    // if next item fits exactly into the leftover (post_residual / next_item_size >= 1),
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual / next_item_size;
        score -= 10.0 + 4.0 * (chain.min(4) as f64);
        // Exact fit of next item into leftover: big reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover too small for the next item: dead-space penalty scaled by class.
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.15;
    }

    // Modulo-16 harmonic class of post_residual: some classes are known-tight.
    match post_residual % 16 {
        0 => score -= 5.0,      // perfectly divisible residual, reusable
        1..=5 => score -= 2.0,  // small crumbs, still acceptable
        _ => {}
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // if current item is large and no good fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_pressure = (post_residual as f64) / cap; // = 1.0 for empty bin
        // Prefer new bin when item is huge and few bins fit it.
        if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 1 {
            score -= 25.0 * (item_size as f64 / cap) - 5.0 * progress;
        } else {
            // Penalize opening a new bin otherwise.
            score += 15.0 + 10.0 * (1.0 - waste_pressure) + 8.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Coupling with mean residual: prefer bins below mean (tighter packing).
    let dev = mean_residual - post;
    score += 0.10 * dev;

    // Slight preference for tighter bins overall.
    score += 0.05 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps smaller than the minimum item size (1..100 range, small gaps < 8 are near-useless)
    if post_residual > 0 && post_residual < 8 {
        score += 60.0 + (8.0 - post_residual as f64) * 10.0;
    }
    // Perfect fit strongly rewarded
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual after placement can still host the next item (lookahead k=2)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when other bins fit and few bins are open
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(1.0);
        let base = 25.0 + 8.0 * pressure;
        score += if fitting_bins_count == 0 { -10.0 } else { base };
        // If next item is large and this fresh bin keeps flexibility, soften the penalty
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Mild open-bin pressure: prefer spreading load when many bins already open
    score += (open_bins_count as f64) * 0.5;

    // Slight preference for bins tighter than average (better packing)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty for post-fit waste, superlinear to discourage dead space.
    score += 0.8 * (post_residual as f64).powf(1.35);

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain (post_residual == next_item_size) heavily rewarded.
            if slack < 0.5 {
                score -= 25.0;
            } else {
                // Reward proportional to how close next item fills the leftover.
                let fill_ratio = next_item_size as f64 / post_residual as f64;
                score -= 18.0 * fill_ratio;
            }
        } else {
            // Next item cannot follow in this bin: penalize small leftovers that
            // are likely unusable relative to typical item sizes.
            score += 6.0;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving more than average waste is penalized; tight fits favored.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, encouraging spreading.
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when current bin would leave
    // a very poor fit or the item is large relative to residual.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Empty bin is a good choice for very large items or when no good fit exists.
        if tightness > 0.7 || (fitting_bins_count <= 1 && post_residual as f64 > mean_residual) {
            score -= 15.0;
        } else {
            // Prefer existing bins otherwise.
            score += 12.0;
        }
    }

    // Late in the stream, consolidate: penalize opening bins and reward tight fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);
    if open_bins_count > 3 {
        score += 0.15 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post residuals that are too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward heavily
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0;
        } else {
            // penalize wasting post space the next item could nearly use
            let miss = next_item_size as f64 - post_residual as f64;
            if miss < 15.0 {
                score += 0.8 * miss;
            }
        }
    }

    // New-bin candidate handling: discourage opening a new bin unless current bin is a poor fit
    if bin_residual == bin_capacity {
        // base new-bin score is post_residual == capacity; adjust with global state
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let crowding = (open_bins_count as f64).max(1.0);
        // open new bin when open bins are mostly full (low mean residual) or late in stream
        let pressure = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score -= 40.0 * pressure * pressure;
        score -= 10.0 * progress;
        score += 2.0 / crowding;
        // if many bins fit already, opening a new one is wasteful
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild preference for fuller bins relative to the fleet mean
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Time-horizon term: late in stream, be greedier (minimize residual now)
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on (progress ~ 0): prefer tight fits but tolerate leftovers.
    // Late (progress ~ 1): strongly punish leftover space (dead space matters more).
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Cubic smoothing term: small residuals are heavily rewarded late in stream.
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Interaction with mean residual: penalize bins far from the fleet mean
    // unless the fit is very tight (smooth sigmoid-like weight).
    let mean_gap = (pr - mean_residual) / cap;
    let tightness = 1.0 - norm_pr;
    score += 12.0 * mean_gap * (1.0 - tightness * tightness);

    // Last-chance bonus: if this is the only fitting bin, reward using it
    // smoothly, stronger as the stream progresses.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.3 + 0.7 * progress) * tightness;
    }

    // Lookahead coupling: if next item could use the post residual exactly-ish,
    // reward leaving that much space (smooth Gaussian-like affinity).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let affinity = ((pr - nx) / cap).powi(2);
        score -= 20.0 * (-8.0 * affinity) * (0.4 + 0.6 * progress);
    }

    // Mild penalty for spreading across many open bins (encourages consolidation),
    // scaled smoothly by how loose this bin's fit is.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Slight bias toward opening a new bin early when the fit is poor.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 5.0 * (1.0 - progress) * norm_pr - 10.0 * progress * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class A: post_residual is a multiple of 25 (perfect harmonic slots: 25/50/75).
    let harmonic = post_residual % 25 == 0;
    if harmonic {
        score -= 18.0 + post_residual as f64 * 0.1;
    }

    // Class B: post_residual divisible by 10 (nice round leftover).
    if post_residual % 10 == 0 && !harmonic {
        score -= 7.0;
    }

    // Penalize awkward leftovers: prime-ish / non-divisible-by-5 residuals.
    if post_residual % 5 != 0 {
        score += 6.0;
    }

    // Integer-division thresholds: can the lookahead item fit in the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect pair: item + next item exactly fills the bin.
            if next_item_size == post_residual {
                score -= 40.0;
            } else {
                score -= 12.0;
            }
        } else {
            // Lookahead won't fit here; penalize more if post_residual is small (dead space).
            let dead = post_residual as f64 / next_item_size as f64;
            score += 10.0 * (1.0 - dead.min(1.0));
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when existing residuals are tight
    // or the fit is bad.
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 0.5;
        let bad_fit = post_residual > 0 && post_residual < 10;
        if tight || bad_fit {
            score -= 15.0;
        } else {
            score += 30.0 + 0.05 * open_bins_count as f64;
        }
    }

    // Prefer filling bins whose residual is close to the item (tight fit).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 10.0;

    // Mild stream-progression pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight pull toward the mean residual: avoid outlier bin choices.
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste; penalize them quadratically.
    let min_item = 1u32;
    if post_residual < min_item.max(next_item_size.min(10)) && post_residual > 0 {
        score += 40.0 + (post_residual as f64) * 2.0;
    }

    // Reward near-perfect fits (small post_residual) super-linearly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Perfect fill: bin closed exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual <= 20 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins, especially ones below mean residual (i.e. emptier).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (2.0 + 4.0 * progress);

    // Prefer bins whose residual is close to the item (tight relative fit).
    let rel_fit = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += rel_fit * 30.0;

    // Mean-residual coupling: placing into a bin above mean residual keeps the
    // distribution of gaps balanced; slight reward for that.
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 35.0;
    }
    // If next item almost fits but leaves dead space, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or too many
    // bins already carry awkward residuals. Baseline cost of opening a bin.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is mandatory anyway
        } else if fitting_bins_count == 1 {
            score += 25.0; // resist abandoning the single fitting bin
        }
        if open_bins_count > 8 {
            score -= 10.0; // many open bins: consolidation already happened
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when the next item fits exactly into the post-residual (2-step lookahead match).
    if next_item_size > 0 {
        let gap = if (post_residual as u32) >= next_item_size {
            (post_residual as u32) - next_item_size
        } else {
            next_item_size - (post_residual as u32).min(next_item_size)
        };
        // Perfect 2-step chain match: strong reward.
        if post_residual as u32 == next_item_size {
            score -= 40.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item fits: reward proportional to tightness.
            score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize by how much dead space remains.
            score += 8.0 * (next_item_size - post_residual as u32) as f64 / bin_capacity as f64;
        }
    }

    // Tight fit reward relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 12.0 * (fill_ratio - 0.8);
    }

    // Penalize bins deviating from the mean residual (prefer balanced residual pools),
    // but only mildly, so tight fits dominate.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item leaves a large, reusable residual
    // or the item is huge (near-full new bin) — otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let base_penalty = 22.0 + 0.3 * open_bins_count as f64;
        let reuse_bonus = if next_item_size > 0 && post_residual as u32 >= next_item_size {
            18.0
        } else {
            0.0
        };
        score += base_penalty - reuse_bonus - 0.2 * post_residual as f64;
    }

    // Late in the stream, consolidation matters more: slightly favor existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild convex penalty
    // so that leaving exactly zero residual is strongly favored.
    let pr = post_residual as f64;
    score += 0.5 * (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * bin_capacity as f64;

    // Lookahead coupling: reward bins whose post_residual exactly (or nearly)
    // accommodates the next item (k=2 lookahead chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            // Perfect chain: post_residual == next item size -> big reward.
            if slack == 0.0 {
                score -= 25.0;
            } else {
                // Gradual reward decaying with slack, capped.
                let reward = 18.0 * (-slack / 30.0).exp();
                score -= reward;
            }
        } else {
            // Post-residual too small for the next item: penalize dead space
            // proportionally to how close-but-failed the fit was.
            let miss = nxt - pr;
            if miss <= 10.0 {
                score += 6.0 * (1.0 - miss / 10.0);
            }
        }
    } else {
        // Last item: just minimize residual, already handled by base term.
        score -= 5.0;
    }

    // Last-chance dynamics: if this is the ONLY bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item.
    // Penalize opening a new bin unless current open bins are poor fits
    // (large mean residual mismatch) or many bins are already open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // If the item is large relative to capacity, opening fresh is safer
        // (avoids fragmentation): reduce the penalty.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 15.0 * fill_ratio;
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin is more justified.
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score -= 12.0 * mean_fill;
        // If no open bin fits (this call is the only fitting option), allow it.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Early in the stream, be more willing to open bins (build diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Global state: with many open bins, prefer consolidating into existing
    // bins to close them out sooner; scale with open_bins_count.
    if bin_residual != bin_capacity {
        let consolidation = 0.15 * open_bins_count as f64;
        score -= consolidation * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Mean-residual anchoring: bins deviating far below the mean residual
    // (i.e., unusually tight) are precious; reward using them.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= 3.0 * (dev / bin_capacity as f64).min(1.0);
        }
    }

    // Time horizon: late in the stream, be greedier (minimize residual hard);
    // early, keep flexibility by mildly penalizing very small post_residuals
    // that could fragment future large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr > 0.0 && pr < 10.0 && progress < 0.5 {
        score += 4.0 * (1.0 - progress) * (1.0 - pr / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let mut score = r * (1.0 + 0.9 * rn * rn);

    // Stream-progress coupling: later in the stream, tighten residual tolerance
    // more aggressively (smooth cubic modulation).
    let tight = progress * progress * (3.0 - 2.0 * progress);
    score += 12.0 * tight * rn * r;

    // Reward tight fits (small waste) with a smooth quadratic bonus.
    score -= 8.0 * (1.0 - rn) * (1.0 - rn);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Penalize bins whose residual is far below the mean (poor relative fit),
    // and mildly reward above-mean residuals.
    let dev = (r - mean_residual) / cap;
    score += 6.0 * dev * dev - 3.0 * dev;

    // Lookahead: penalize creating residual that cannot hold the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if r < nx {
            score += 5.0 + 0.1 * nx;
        } else {
            let fit_after = if r >= nx { 1.0 } else { 0.0 };
            let _ = fit_after;
            score -= 4.0 * (1.0 - ((r - nx) / cap).abs());
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Mild pressure against keeping many bins open early (encourage consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // New-bin candidate: make it slightly unattractive unless residual is huge.
    if bin_residual == bin_capacity {
        score += 3.0 + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: which "capacity fraction band" it lands in.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Class boundaries via integer division thresholds (harmonic classes 1/1, 1/2, 1/3, 1/4, 1/6)
    let class = if post == 0 { 0 }
        else if post > bin_capacity / 2 { 1 }        // > 1/2 : very usable
        else if post > bin_capacity / 3 { 2 }        // (1/3, 1/2]
        else if post > bin_capacity / 4 { 3 }        // (1/4, 1/3]
        else if post > bin_capacity / 6 { 4 }        // (1/6, 1/4]
        else { 5 };                                  // tiny dead space

    // Reward big residuals left over (score already grows with post_residual).
    // Add class-dependent shaping: dead space classes get extra penalty.
    let class_penalty = match class {
        0 => -40.0, // perfect fill
        1 => -10.0,
        2 => 5.0,
        3 => 15.0,
        4 => 25.0,
        _ => 35.0,
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: multiples of common item sizes are reusable.
    let m = post_residual % 10;
    if m == 0 { score -= 8.0; }        // aligns with 10-grid items
    else { score += m as f64 * 0.6; }  // ragged remainder penalized

    // Lookahead: if next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 { score -= 30.0; }
        else if next_fit_gap <= bin_capacity / 4 { score -= 12.0; }
        else { score -= next_fit_gap as f64 * 0.15; }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's leftover; penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive if all open bins are nearly full
    // (mean residual low) or there are no open bins.
    if bin_residual == bin_capacity {
        let openness = mean_residual / cap;
        // new bin starts with full residual; score it relative to average leftover utility
        score = 25.0 - openness * 20.0 + (open_bins_count as f64) * 0.5;
        if open_bins_count == 0 { score = -50.0; }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Small coupling: crowded bin pool -> prefer filling existing bins tighter.
    score -= (open_bins_count as f64).ln().max(0.0) * (post / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residual below the minimum item size harder as it's pure waste
    let min_item = 1u32;
    if post_residual < min_item {
        score += 60.0;
    }

    // Reward tight fits: post_residual == 0 is perfect
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open bins pressure: more open bins -> prefer consolidating into existing bins
    score += open_bins_count as f64 * 2.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Dead space relative to bin capacity
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Prefer bins whose residual after placement stays usable for typical items
    if post_residual >= 10 && post_residual <= 50 {
        score -= 5.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // New bin candidate: make it less attractive unless existing bins are very fragmented
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.5;
    }

    // Stream progression: later in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 - post_residual as f64) * (1.0 - progress) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good via base score.

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leaving a gap smaller than the smallest item
            if post_residual < next_item_size {
                score += 8.0;
            }
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // brand-new bin candidate: only attractive if item is large relative to capacity
        let fill = item_size as f64 / bin_capacity as f64;
        score += 20.0 * (1.0 - fill);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Dead-space penalty: post_residual too small for any plausible future item (min size 1).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Slight pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 0.6 * (item_size as f64) * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Perfect-fit bonus: leave nothing behind.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving small dead space that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose residual after placement matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 3.0; // next item won't fit here after placement
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Discourage opening new bins when many bins are already open and fit exists.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // But early in stream, or when open bins are crowded, a new bin is fine.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 6.0;
        }
    }

    // Prefer filling bins that are already below-average residual (packing dense bins first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = item_size;
    let _ = bin_residual;
    let _ = bin_capacity;
    let _ = step_index;
    let _ = total_items;
    let _ = open_bins_count;
    let _ = mean_residual;
    let _ = next_item_size;
    let _ = fitting_bins_count;
    post_residual
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by small capacity
    // fractions (10, 20, 25, 50) is more likely reusable by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward reusable residual classes (subtract for low score).
    let class_bonus = if post_residual == 0 {
        60.0 // perfect fill
    } else if post_residual % 50 == 0 {
        40.0
    } else if post_residual % 25 == 0 {
        30.0
    } else if post_residual % 20 == 0 {
        25.0
    } else if post_residual % 10 == 0 {
        18.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Penalize dead space: residual smaller than the smallest plausible item (10)
    // but nonzero is nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Penalize awkward mid-range residual (dead zone between item classes).
    if post_residual > 10 && post_residual < 20 {
        score += 12.0;
    }
    if post_residual > 80 && post_residual < 90 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves a residual; reward proportional fit
            let next_fit_frac = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * next_fit_frac;
            // harmonic bonus if chained post-post residual is a nice class
            let post2 = post_residual - next_item_size;
            if post2 % 10 == 0 || post2 == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: mild penalty for wasting the class
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer filling it rather than leaving it open.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // poorly utilized (tight streams benefit from closing out bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < 0.25 * cap;
        // base cost of a new bin, discounted early in the stream or when
        // open bins have high mean residual (fragmented state)
        let mut new_bin_cost = 70.0;
        if tight {
            new_bin_cost -= 25.0;
        }
        if open_bins_count > 4 {
            new_bin_cost += 10.0 * (open_bins_count as f64 - 4.0).min(6.0);
        }
        if progress < 0.2 {
            new_bin_cost -= 8.0;
        }
        // if item fills a fresh bin substantially, opening is cheaper
        let fill_frac = item_size as f64 / cap;
        new_bin_cost -= 25.0 * fill_frac;
        score += new_bin_cost;
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score += 0.05 * ((bin_residual as f64) - pr);

    // Small tie-breaker on mean residual: prefer bins below mean (tighter).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small nonzero leftovers are least reusable (items >= 1..100).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable crumb gap
        } else if post_residual < 25 {
            score += 30.0; // very hard to fill
        } else if post_residual < 50 {
            score += 10.0; // moderately awkward
        }
    } else {
        score -= 40.0; // perfect fit: fully close the bin
    }

    // Reward tight fits relative to item size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bonus: only bin that fits -> avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins below mean residual (keeps residuals balanced) unless it's a new bin.
    if bin_residual != bin_capacity {
        score += ((bin_residual as f64 - mean_residual) * 0.3).max(-10.0).min(10.0);
    }

    // Lookahead: if next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0; // leftover too small for the next item
    }

    // New-bin candidate: acceptable early or when current bin residual is unusable,
    // penalized when many bins are open and residual is still usable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let usable = if bin_residual >= item_size { 1.0 } else { 0.0 };
        score += 25.0 - 20.0 * (1.0 - progress) - (open_bins_count as f64) * 2.0
                 - usable * (if post_residual < 10 { 20.0 } else { 0.0 });
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post residual) superlinearly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            let gap = post_residual as f64 - next;
            if gap == 0.0 {
                score -= 40.0; // perfect two-item match
            } else if gap <= 10.0 {
                score -= 20.0 - gap;
            } else {
                score -= 8.0 * (1.0 - gap / cap);
            }
            // Extra reward if the pair nearly fills the bin.
            if post_residual as f64 + item_size as f64 >= 0.95 * cap {
                score -= 10.0;
            }
        } else {
            // Next item cannot fit here: penalize proportionally to the overflow.
            let overflow = next - post_residual as f64;
            score += 0.5 * overflow.min(30.0);
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins with reasonable residual exist,
    // unless this truly is the new-bin candidate and it's a big item.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's chosen only when fits are bad.
        score += 30.0;
        if item_size >= 60 {
            score -= 10.0; // big items are fine in fresh bins
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for leaving awkward dead space (11..=49 residual is hard to fill).
    if post_residual >= 11 && post_residual <= 49 {
        score += 0.1 * (post_residual as f64 - 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post_residual by capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 6.0 * (next_item_size as f64 / post_residual as f64);
    }
    // Penalize leaving a gap the next item nearly fits (dead space risk)
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        let waste = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 6.0 * waste;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist and fit well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New bin only attractive if existing bins have poor fit potential
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        score += 20.0;
        if mean_fit_gap > 30.0 {
            score -= 15.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for bins with residuals far from mean (outliers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Prefer larger residuals when many bins are open (balance load)
    score += 0.05 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    // Base: tight fits favored (low post_residual)
    let mut score = pr * (1.0 + 0.5 * progress);

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = (pr_norm * pr_norm) * (1.0 - progress) + (pr_norm * pr_norm * pr_norm) * progress;
    score += 120.0 * coupling;

    // Penalize dead space relative to mean residual across open bins
    score += 0.3 * (pr as f64 - mean_residual).abs();

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 60.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: penalize early, allow late when residuals are fragmented
    score += is_new * (80.0 - 60.0 * progress * progress);

    // Lookahead: reward bins whose post_residual still fits the next item
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as f64;
        score -= 25.0 * fits_next * (1.0 - progress);
        // Penalize leaving a sliver just below the next item size
        let gap = (next_item_size as f64 - pr).abs();
        score += 10.0 * (-gap / 20.0).exp() * (1.0 - fits_next);
    }

    // Mild penalty for bin proliferation early in the stream
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity quantization
    let q = post_residual / (bin_capacity / 10); // decile class of leftover
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward small leftover classes (tight fits) with non-linear bonus
    let class_bonus = match q {
        0 => 25.0,                       // near-perfect fit
        1 => 12.0,
        2 => 6.0,
        3 => 2.0,
        4 => -1.0,
        _ => -3.0,                       // large leftover is wasteful
    };
    score -= class_bonus;

    // Harmonic coupling: does the next item fit into the post residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - pair_waste / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot follow here: penalize proportional to unusable space
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current residual is fragmented
    if bin_residual == bin_capacity {
        let stream_pos = step_index as f64 / total_items.max(1) as f64;
        // opening new bins is cheap early, expensive late
        score += 20.0 + 30.0 * stream_pos;
        // but if mean residual is very low, new bin may be needed
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Modular dead-space penalty: residuals in awkward classes (e.g. 51..59) are hard to fill
    let m = post_residual % 10;
    if m >= 1 && m <= 4 && post_residual < 20 {
        score += 5.0;
    }

    // Fractional capacity coupling: reward filling toward exact capacity fractions
    score -= 4.0 * (frac * std::f64::consts::PI).sin().abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1,
    // but practically small gaps < 12 are near-unusable) are heavily penalized.
    if post_residual < 12 && post_residual > 0 {
        score += 40.0 + (12 - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins over opening new ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when the fit
    // elsewhere is poor. Give it a moderate baseline plus mean-residual
    // coupling (if open bins are already full-ish, new bin is fine).
    if bin_residual == bin_capacity {
        score += 10.0 - mean_residual * 0.2;
        if post_residual < 12 {
            score += 50.0; // avoid opening a bin for a near-unusable leftover
        }
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Late-stream tightening: as the stream progresses, prioritize perfect fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: strongly favor bins that end exactly full.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a golden chain placement — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits: mildly good, scaled by tightness of fit.
        let slack = (post_residual - next_item_size) as f64;
        score -= 150.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize dead space creation.
        score += 60.0 * (next_item_size as f64 - post_residual as f64) / item_size as f64;
    }

    // Tightness of current placement: smaller post_residual is better (base term).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Compare against mean residual across open bins: prefer bins tighter
    // than average (concentrate waste in few bins, keep roomy bins flexible).
    score += 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize placing into a fresh empty bin unless the item is huge
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 120.0; // big item: opening a fresh bin is reasonable
        } else {
            score += 80.0 + 0.3 * item_size as f64; // discourage wasting fresh bins
        }
    }

    // Late in the stream: consolidate harder, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    }

    // Many open bins: favor filling existing ones to reduce spread.
    score += 3.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    }
    // If next item would leave a tiny unusable gap, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin more acceptable early or when mean residual is high (fragmented state).
        score += 40.0 - 20.0 * progress;
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
        // If item is large relative to capacity, new bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Slight preference for bins with larger residual among equally tight fits (consolidation).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Mild pressure to close nearly-full bins.
    if bin_residual as f64 <= mean_residual * 0.5 && bin_residual >= item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: reward tight fits via non-linear (quadratic + cubic) coupling with progress.
    let x = pr / cap; // normalized post residual in [0,1]
    let mut score = x * (1.0 + 0.8 * progress) + 2.5 * x * x * (0.5 + progress) + 1.5 * x * x * x;

    // Penalize dead space that is too small to be useful later, smoothly.
    let small_gap = (1.0 - (pr / 10.0).min(1.0)).max(0.0);
    score += 3.0 * small_gap * small_gap * (1.0 + progress);

    // Lookahead: reward bins whose post residual fits the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            let tight = 1.0 - ((pr as f64 - nx) / cap);
            score -= 2.0 * tight * tight;
        } else {
            score += 1.0 * (nx - pr as f64) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 0.3 * (fitting_bins_count as f64 - 2.0);
    }

    // Mild preference for bins below mean residual (fill emptier bins first) with smooth coupling.
    score += 0.5 * ((mean_residual - bin_residual as f64) / cap).abs();

    // New-bin candidate: penalize opening a new bin unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score += 6.0 - 5.0 * large * large;
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10 / small remainders) are rewarded.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= (cap - post_residual as f64).powi(2) / (4.0 * cap);

    // Penalize "dead zone" leftovers: too small to ever hold a typical item
    // (sizes 1..100 unknown, so treat < 15 as dead) but not zero.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Harmonic class: post_residual divisible by 10 pairs well with
    // next items in the same class; reward class match with lookahead.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let class_match = (post_residual % 10) == (next_item_size % 10);
            if class_match {
                score -= 12.0;
            }
            // Exact lookahead fit bonus.
            if next_item_size == post_residual {
                score -= 30.0;
            }
            // Penalize leaving just-below-lookahead slivers.
            if post_residual > next_item_size && post_residual < next_item_size + 8 {
                score += 10.0;
            }
        } else {
            // Lookahead cannot use this bin's leftover: mild penalty scaled by gap.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer zero waste.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (subtract enough to beat empty-bin score ~0).
    if fitting_bins_count == 1 {
        score -= 20.0 + 0.5 * (bin_residual - item_size) as f64;
    }

    // New empty bin candidate: neutral-ish baseline, but discourage opening
    // new bins when existing residual is plentiful and item is small.
    if bin_residual == bin_capacity {
        score = 5.0 + 0.3 * item_size as f64
            + if item_size > 60 { -15.0 } else { 0.0 }
            + (open_bins_count as f64) * 0.2;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open
        }
    }

    // Capacity-fraction thresholds: leftover in (0.5,0.7] of capacity is
    // highly reusable; leftover in (0.0,0.2] is poor.
    if frac > 0.5 && frac <= 0.7 {
        score -= 8.0;
    } else if frac > 0.0 && frac <= 0.2 {
        score += 6.0;
    }

    // Slight preference to fill bins below mean residual (balance avoidance
    // of many half-empty bins): tighter than mean is good.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Integer-division threshold: bins whose residual // 20 is small are
    // closer to closure; nudge them to be filled first.
    score += (post_residual / 20) as f64 * 1.5;

    // Stream progression: late in stream, be greedier (minimize waste now).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept a meaningful future item are heavily penalized dead space.
    let dead_threshold: f64 = 20.0;
    if (post_residual as f64) < dead_threshold {
        // The smaller the leftover, the worse (unusable gap).
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fills that leave a still-usable residual.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 8.0 - slack as f64 * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty.
        score += 2.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading into more
    // open bins; fewer open bins -> allow it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.3 * (0.5 + progress);

    // Mean residual coupling: bins far below mean residual are less
    // attractive targets than bins near/above the mean.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate handling: a fresh empty bin should only win when
    // the fit into open bins would create bad dead space.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Early in the stream, new bins are cheap (room to consolidate).
        score -= (1.0 - progress) * 15.0;
        // Many open bins -> opening another is costly.
        score += open_bins_count as f64 * 0.5;
        // If no open bin fits well (post residual would be dead space),
        // opening a new bin is fine.
        if post_residual < dead_threshold && fitting_bins_count >= 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward if the lookahead item also fits after this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if it fits snugly (small leftover after the lookahead item).
        let second_left = post_residual as f64 - next_item_size as f64;
        if second_left < 10.0 {
            score -= 10.0;
        }
    }

    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Penalize large residuals relative to mean residual across open bins (wasteful bin).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.3;

    // Early in the stream, be slightly more willing to open fresh bins with good structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: attractive if item is large and current fits are poor.
        let poor_fit_penalty = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score = score - 8.0 * poor_fit_penalty + 5.0 * (1.0 - progress) - 0.5 * (item_size as f64 / 100.0) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space: post_residual too small to ever be useful.
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: baseline high cost, but attractive when current open bins
    // would all be poor fits or mean residual is large (fragmented bins).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: must open new bin
        }
        if mean_residual > 40.0 {
            score -= 10.0; // existing bins fragmented; fresh bin may be fine
        }
        // Early in stream, opening bins is cheaper; late in stream prefer packing.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight preference for bins with residual close to item size (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    // Global pressure: many open bins -> favor filling existing ones.
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap; // normalized post residual in [0,1)

    // Base: prefer tight fits (low post residual), with a convex non-linear penalty
    // so that tiny residuals are strongly favored (quadratic coupling).
    let mut score = pr as f64 * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth interaction with stream progress: late in the stream, waste matters more,
    // so amplify the residual penalty with a smooth progress term.
    score += norm_pr * norm_pr * (progress * 30.0 + 5.0);

    // Cubic smooth coupling between residual and item size ratio:
    let it = item_size as f64;
    let fill = (r - pr) / cap; // fraction of residual consumed by this item
    score -= fill * fill * fill * 20.0; // reward consuming a large fraction of the bin

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (smoothly scaled by how much residual remains).
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - norm_pr);
    }

    // Lookahead coupling: if the next item fits in the post residual, reward this placement
    // smoothly (scaled by how well it fits).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // penalize placements that leave a residual just barely too small for next item
            score += 4.0 * (1.0 - (nxt - pr) / cap).max(0.0);
        }
    }

    // Global balance: prefer bins whose residual is below the mean residual
    // (consolidating waste), smooth quadratic deviation penalty.
    score += ((pr - mean_residual) / cap) * ((pr - mean_residual) / cap) * 10.0;

    // New-bin candidate handling: an empty bin has huge residual; make it mildly
    // unattractive unless the item is large relative to capacity (smooth term).
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (it / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // "usable" residue classes. Leftovers in [1..10] are near-dead space;
    // leftovers that are multiples of 10 (or >= 20) can host future items.
    let pr = post_residual;
    let dead = if pr == 0 {
        -60.0 // perfect fit: strongly reward
    } else if pr < 10 {
        40.0 + (10 - pr) as f64 * 3.0 // tiny unusable sliver: penalize
    } else {
        0.0
    };
    score += dead;

    // Modulo-10 harmony: residual divisible by 10 pairs well with the
    // decile-quantized item sizes.
    if pr > 0 && pr % 10 == 0 {
        score -= 12.0;
    } else if pr > 0 {
        score += (pr % 10) as f64 * 0.8;
    }

    // Integer-division thresholds: how many "average small items" fit?
    let fits_k = pr / 15; // coarse granularity
    score -= fits_k as f64 * 4.0;

    // Lookahead coupling: does the next item fit the post-residual class?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0;
            // exact decile match bonus
            if pr % 10 == 0 && (pr - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: avoid wasting the only fitting bin on a bad class.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer existing bins unless this bin is
    // fresh and the item fills it harmonically.
    if bin_residual == bin_capacity {
        // empty bin: neutral baseline, slight penalty so we only open when
        // existing bins score poorly
        score += 25.0;
        if item_size % 10 == 0 {
            score -= 10.0; // decile item into fresh bin is fine
        }
    }

    // Tight fit reward: fraction of bin consumed.
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Late in stream: consolidate, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (open_bins_count as f64).ln().max(1.0);

    // Spread-aware: if mean residual is high, prefer bins far from mean
    // (keeps a diversity of gap classes).
    score += ((post_residual as f64 - mean_residual) * 0.15).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for future items (which can be as small as 1..10) are heavily penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 200.0 * (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Reward bins that can also fit the lookahead item (chaining placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Extra reward for exact chain fill.
        if next_item_size == post_residual {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving a gap the next item cannot use.
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, tolerate opening new bins.
    let pressure = open_bins_count as f64 * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; discount when the
        // current item is large and open bins are scarce.
        score += 30.0 + pressure;
        if item_size > 60 && open_bins_count < 4 {
            score -= 50.0;
        }
    } else {
        // Fitting an existing bin gets a mild bonus, amplified by pressure.
        score -= pressure * 0.5;
    }

    // Prefer bins tighter than the mean residual (consolidating space).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Slight phase awareness: late in the stream, avoid opening new bins.
    if total_items > 0 && bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits: low post_residual is good.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 15.0 - slack as f64 * 0.3;
        if slack == 0 {
            score -= 25.0; // chain of perfect fits
        }
    }
    // Penalize if next item cannot fit here (bin becomes dead space for lookahead).
    else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0 + (post_residual as f64) * 0.1;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when good open bins exist, especially early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    // Prefer filling bins with large residuals (reduce fragmentation).
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill is always best
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    }

    // Penalize dead space that no future item can use: residual below the
    // minimum item size is wasted, residual below next_item_size is likely wasted.
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score += 500.0;
    }
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 15.0; // residual unusable by the lookahead item
    } else if next_item_size > 0 {
        // Reward residuals that can still host the next item comfortably.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // would leave very large unusable leftovers. Penalize the empty bin so it
    // is chosen only when alternatives are bad, less so late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 60.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > bin_capacity / 2 {
            new_bin_penalty -= 20.0;
        }
        // Late in the stream, consolidating into existing bins matters more.
        new_bin_penalty *= 1.0 - 0.5 * progress;
        // Many open bins with large mean residual => prefer using them.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            new_bin_penalty += 10.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for bins below mean residual (balance load across bins).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Slight penalty for creating very small leftover slivers (unusable gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * norm_post * norm_post);

    // Stream-progress coupling: early on, tolerate slack (favor filling new bins);
    // late in the stream, strongly penalize wasted residual via smooth polynomial ramp
    let ramp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += ramp * 40.0 * norm_post * norm_post;

    // Dead-space penalty: residuals too small for typical future items
    let dead_threshold = 12.0;
    if pr < dead_threshold && pr > 0.0 {
        score += (dead_threshold - pr) * (2.0 + 3.0 * ramp);
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * ramp;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (1.0 - pr / cap);
    }
    // If next item would leave this bin's residual useless, mild penalty
    if next_item_size > 0 && (next_item_size as f64) > pr && pr < next_item_size as f64 {
        score += 3.0 * ramp;
    }

    // New-bin candidate handling: opening a new bin is attractive early or when
    // mean residual across open bins is already high (poor fits available)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_norm = mean_residual / cap;
        let attraction = (1.0 - progress) * 20.0 + mean_norm * 25.0;
        score = cap - attraction; // competes via low score when attractive
        if fitting_bins_count <= 1 {
            // must not beat the only usable bin too easily
            score += 10.0;
        }
    }

    // Slight preference to consolidate into fewer bins
    score += 0.05 * open_bins_count as f64 * (1.0 - ramp);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Dead space too small to be useful (below eighth) is wasted capacity.
    if pr > 0.0 && pr < eighth {
        score += 30.0;
    }
    // Residual in (eighth, quarter] can still host small items — mild reward.
    if pr > eighth && pr <= quarter {
        score -= 5.0;
    }

    // Integer-division harmonic classes on post_residual (classes of size 10).
    let class = post_residual / 10;
    match class {
        0 => score -= 20.0,      // tiny residual, near-perfect packing
        1 => score -= 10.0,      // good
        2 | 3 => score -= 3.0,   // acceptable
        4 | 5 => score += 4.0,   // mediocre
        _ => score += 8.0,       // large residual left behind
    }

    // Lookahead coupling: reward if next item fits in the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportionally to how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; penalize more the smaller the leftover.
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately unattractive unless open bins are scarce
    // or mean residual across open bins is very low (all bins nearly full).
    if bin_residual == bin_capacity {
        let scarcity = if open_bins_count == 0 { 1.0 } else { 0.0 };
        let fullness = if mean_residual < 5.0 { 1.0 } else { 0.0 };
        score += 25.0 - 60.0 * scarcity - 40.0 * fullness;
    }

    // Prefer spreading across bins early when many bins are open and mean residual is high.
    if open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread_bonus = (mean_residual - pr).max(0.0) * 0.05 * (1.0 - progress);
        score -= spread_bonus;
    }

    // Mild tie-break: slight preference for bins whose residual exceeds item size comfortably.
    score += (bin_residual - item_size).min(20) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would not fit and post_residual is small, penalize slightly.
    if next_item_size > post_residual && post_residual < 25 {
        score += 10.0;
    }

    // Open bins pressure: with many open bins, discourage spreading into new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins tighter than the mean residual (consolidate space).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count == 0 { 0.0 } else { 40.0 };
        score += escape + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post residual exactly matches next item -> strong reward.
            let match_gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 40.0 - 0.5 * match_gap;
        } else {
            // Post residual too small for next item: penalize dead space, worse when close to next size.
            let waste = post_residual as f64;
            score += 10.0 + 0.3 * waste;
        }
    }

    // Tight fits are good: small post residual preferred (scaled by item size).
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Relative to mean residual: prefer bins tighter than the average.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.4 * (resid_f - mean_residual);
    }

    // Last-chance bin (only fitting bin): strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits even more.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize opening a brand-new empty bin unless current bins are quite full.
    if bin_residual == bin_capacity {
        let fullness = 1.0 - (mean_residual / bin_capacity as f64);
        score += 55.0 - 40.0 * fullness;
        // Early in stream, new bins are cheap; later, avoid fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Slight bonus for using bins when many are open (consolidation pressure).
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a non-linear tightening.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty scaled by how much we "wasted"
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Time horizon: early in the stream, be conservative and keep bins flexible;
    // late in the stream, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fit_ratio; // late stream: tolerate residual waste less strictly
    score += 15.0 * (1.0 - progress) * fit_ratio; // early stream: punish large residuals

    // Global state: many open bins -> prefer consolidating into existing bins.
    let open_norm = open_bins_count as f64;
    score += 0.5 * open_norm * fit_ratio;

    // Mean residual coupling: if this bin's residual is far below mean, it's already tight;
    // filling it further is good. If it's above mean, opening fresh space may be better.
    let bin_res_f = bin_residual as f64;
    let dev = (bin_res_f - mean_residual) / bin_capacity as f64;
    score += 12.0 * dev;

    // New-bin candidate handling: empty bin gets a moderate default penalty,
    // overridden only when no existing bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // With lookahead knowledge: if next item is large and current item small,
        // a fresh bin may preserve large contiguous space.
        let lookahead_pressure = if next_item_size > item_size && item_size <= bin_capacity / 4 {
            0.6
        } else {
            0.0
        };
        score = 55.0 + 30.0 * (1.0 - progress) - 80.0 * pressure - 50.0 * lookahead_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * (0.5 + progress);
    score += 20.0 * poly;

    // Penalize near-full waste more strongly as stream progresses
    score += 15.0 * progress * norm_pr * norm_pr * norm_pr;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: penalize if post residual cannot fit next item but residual could
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx && (bin_residual as f64) >= nx {
            score += 10.0 + 10.0 * progress;
        }
        // reward leaving room exactly useful for next item
        if (pr - nx).abs() < 5.0 {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Deviation from mean residual: prefer bins whose usage keeps residuals balanced
    let dev = pr - mean_residual;
    score += 0.5 * dev * dev / cap;

    // Slight preference for filling existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals in "useful" classes.
    // Residuals divisible by 10 (or >= 20) stay reusable; tiny residuals are dead space.
    let pr = post_residual;
    if pr > 0 {
        let cls = pr % 10;
        // Penalize awkward residuals (1..9) unless they can host next item
        if cls > 0 {
            score += 6.0 * (1.0 - cls as f64 / 9.0);
        }
        if pr < 10 {
            score += 12.0; // dead space penalty
        }
    }

    // Exact fit is excellent
    if pr == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && pr >= next_item_size {
        let nxt_pr = pr - next_item_size;
        score -= 8.0;
        if nxt_pr == 0 {
            score -= 15.0;
        } else if nxt_pr < 10 {
            score += 5.0; // would leave dead space for the following step
        }
        // harmonic bonus: residual after next fits a tenth-class
        if nxt_pr % 10 == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && pr < next_item_size {
        // next item won't fit here; slight penalty unless this is an exact-ish fit now
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only good when the current
    // item is large and mean residual across open bins is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // reward opening when item is big and open bins are congested
        score -= 25.0 * item_frac * (mean_residual / bin_capacity as f64);
        // penalize opening early in the stream when many bins exist
        score += 10.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
        // large items with no good fit deserve a fresh bin
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Prefer tighter bins overall (small residual before placement)
    score += 0.05 * bin_residual as f64;
    // Slight preference for bins below mean residual (filling the fullest first)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // Penalize small unusable gaps (dead space) more aggressively
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
