    }
    // New-bin candidate: neutral-ish baseline, penalize slightly to prefer reuse
    if bin_residual == bin_capacity {
        score += 12.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a mild quadratic penalty
    // on wasted space to strongly discourage large dead zones.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual as f64 - next_item_size as f64;
        // Perfect chain fit (post_residual == next_item_size) gets a big bonus.
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize, scaled by how much it misses.
        let miss = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        score += 6.0 * miss;
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving this bin below-average residual (tighter than average) is good.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately unattractive unless everything else is bad,
    // but allow it late in the stream when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (open_bins_count as f64).ln() + 1.0;
        score += 18.0 - 8.0 * progress * fragmentation;
    }

    // Slight preference for keeping many small residual bins consolidated early.
    if open_bins_count > 0 && bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize creating dead space that likely cannot fit the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
        // Bonus if the next item exactly fits the post residual.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving residuals that are awkwardly small (dead space).
    if post_residual > 0 && post_residual < 15 {
        score += 8.0;
    }

    // Time horizon: late in the stream, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - tightness);

    // When many bins are open with slack, prefer filling existing bins over new ones.
    if bin_residual != bin_capacity {
        score -= 0.5 * (open_bins_count as f64).sqrt();
        score += 0.05 * (mean_residual - post_residual as f64).abs();
    } else {
        // New-bin candidate: penalize it mildly, more so if decent fits exist.
        score += 10.0 + 2.0 * fitting_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 5.0;
        }
    }

    // Prefer bins whose residual was already small (fragment avoidance).
    score += 0.1 * (bin_residual as f64 - post_residual as f64).signum() * (item_size as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = pr / cap;

    // Smooth non-linear penalty on wasted residual, amplified by stream progress
    score += 8.0 * fit * fit * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item)
    score -= 6.0 * (1.0 - fit) * (1.0 - fit);

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Prefer bins with residual below mean (consolidate large gaps)
    score += 0.3 * (pr - mean_residual);

    // Dead-space penalty: residual that cannot fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 5.0 * (nx - pr) / cap;
        } else {
            score -= 3.0 * (1.0 - (nx / pr).min(1.0));
        }
    }

    // Mild preference for keeping few open bins early, tolerating more later
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Slight bias against opening a new bin when fitting bins exist
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "reusable"
    // class (multiples of 10) are favored; odd fragments are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let class_mod = pr % 10;
    if class_mod == 0 {
        score -= 6.0; // perfectly harmonic leftover, easy to refill
    } else if class_mod <= 3 {
        score += 4.0; // awkward sliver -> dead space
    } else if class_mod >= 7 {
        score += 2.0; // near-harmonic but off-grid
    }

    // Integer-division thresholds: leftover big enough to hold a medium item is valuable.
    if pr >= 50 { score -= 5.0; }
    else if pr >= 30 { score -= 2.0; }
    else if pr < 10 && pr > 0 { score += 6.0; } // tiny useless residue

    // Tight fit reward: filling a bin almost exactly is excellent.
    let fill_frac = item_size as f64 / cap;
    if fill_frac > 0.9 { score -= 12.0; }
    else if fill_frac > 0.7 { score -= 6.0; }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.1;
        } else {
            score += 3.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when item is huge and no tight option exists,
    // or late in the stream when consolidation is done.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = (open_bins_count as f64).sqrt();
        score += 18.0 - 14.0 * fill_frac - 2.0 * openness - 6.0 * progress;
        if item_size >= 80 { score -= 8.0; }
    }

    // Mild pressure toward bins below mean residual (balance fragmentation).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (dead space in (0, 10) is nearly wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Slight penalty for medium-small gaps that few items can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward exact/tight fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // New-bin candidate handling: empty bin gets a baseline cost that rises with open bins,
    // but is attractive when this placement would leave large dead space elsewhere.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 1.5;
        // If no open bin can take the item, opening a new bin is necessary and cheap.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins below mean residual (filler bins) when residuals are small.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain: this bin will be perfectly consumed next step
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev.max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize opening a new bin when existing bins fit well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + discourage early in stream, discourage when open bins have slack.
        score += 50.0;
        score += 0.1 * mean_residual;
        if fitting_bins_count > 0 {
            score += 80.0;
        }
        // Late in stream, opening a fresh bin is less harmful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * progress;
    }

    // Mild penalty for many open bins (consolidation pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to item size).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * item_size as f64 * 0.5;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 30.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 10.0; // sealing bin with unusable space before a big next item
        }
    }

    // New-bin candidate handling: discourage opening new bins unless current fit is bad.
    if bin_residual == bin_capacity {
        // Base penalty for new bin, reduced when existing fits are loose.
        score += 60.0;
        let waste = post_residual as f64 - (bin_residual as f64 - item_size as f64);
        let _ = waste;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        } else {
            // If best existing fit would leave tiny residual, opening may be better.
            let avg_fit_waste = mean_residual - item_size as f64;
            if avg_fit_waste > 0.0 && avg_fit_waste < item_size as f64 * 0.15 {
                score -= 55.0;
            }
        }
    }

    // Time horizon: early in stream, be pickier about tight fits; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * tightness * 10.0;
    score += progress * (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Global pressure: many open bins with high mean residual -> prefer filling those.
    if mean_residual > item_size as f64 * 2.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap; // normalized post residual in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = base * (1.0 + 0.8 * progress + 0.6 * progress * progress);

    // Reward tight fits: quadratic bonus for small post residual
    score -= 2.5 * (1.0 - base) * (1.0 - base);

    // Penalize dead space that cannot fit a typical next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 0.5 + 0.5 * (ns - pr) / cap;
        } else {
            // small reward if next item fits snugly
            score -= 0.4 * (1.0 - (pr - ns) / cap);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Prefer bins below mean residual (fills emptier bins first)
    score += 0.3 * (pr as f64 - mean_residual) / cap;

    // Mild penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64 / (1.0 + progress);

    // Slight preference for opening a new bin early vs late
    if bin_residual == bin_capacity {
        score += 0.2 + 0.8 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse integer division on size
    let item_class = item_size / 10;             // 0..10
    let next_class = next_item_size / 10;        // 0..10 (0 if lookahead absent)
    let cap_frac = bin_capacity / 10;            // = 10

    // Reward bins whose post_residual matches the NEXT item's harmonic class
    // (post_residual mod 10 == next size mod 10 implies exact future fit potential)
    if next_item_size > 0 {
        let pr_class = post_residual / 10;
        if pr_class >= next_class {
            score -= 6.0 + (pr_class - next_class) as f64 * 0.5;
        } else {
            score += (next_class - pr_class) as f64 * 1.5;
        }
        // Exact pairing: post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // Modulo harmony: post_residual % 10 == next_item_size % 10
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Penalize dead space in low harmonic classes (unusable small gaps)
    let dead_zone = post_residual < 10;
    if dead_zone {
        score += 15.0;
    } else if post_residual < 20 {
        score += 5.0;
    }

    // Integer-division threshold: bins whose residual is in a "good" band
    let band = bin_residual / cap_frac;          // 0..10 tenths of capacity
    match band {
        0 => score += 10.0,                      // nearly full bin: little use
        1 => score -= 3.0,
        2 => score -= 5.0,
        3 | 4 => score -= 2.0,
        _ => {}
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: neutral-ish but discourage unless current bin is poor
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Progress coupling: late in the stream, prefer tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (100.0 - post_residual as f64) * 0.05 * progress;

    // Slight preference for bins below mean residual (rebalance spread)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space zone: residuals 1..=9 are unusable for items >=10 but
    // still count as waste in the new interface (items 1..100).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits: the closer post_residual is to 0, the better.
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.3;

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + slack * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the residual: penalize proportionally.
        score += post_residual as f64 * 0.15;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 35.0;
        // If some other bin is a tight fit, keep new bin expensive.
        if item_size > 0 && (bin_capacity as f64 - mean_residual).abs() > 0.0 {
            score = base + mean_residual * 0.1;
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't open a new bin when one bin barely fits
        }
        // Late in stream, prefer consolidating.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Slight preference for filling bins below mean residual (balance).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.6 * slack; // perfect chain (slack 0) rewarded most
    } else if next_item_size > 0 {
        // next item won't fit here; penalize dead space relative to next item
        score += 0.4 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Compare post_residual against mean residual: avoid making bin worse than average
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr);
    } else {
        score -= 0.3 * (pr - mean_residual);
    }

    // Tight fits are valuable: reward small post residual
    score -= 0.3 * (bin_capacity as f64 - pr) / bin_capacity as f64 * (item_size as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a new bin only when fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.45 * bin_capacity as f64
            && (next_item_size == 0 || post_residual < next_item_size);
        if poor_fit {
            score -= 40.0;
        } else {
            score += 30.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that no future item can use (items >= 1, so any residual is usable,
    // but very small residuals are near-waste).
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the one that keeps future flexibility (larger post_residual).
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: penalize adding to bins whose residual is far from mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: late in the stream, be more conservative — favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Opening a new bin: it's an empty bin with full residual. Only attractive when current
    // item is large relative to capacity or few bins fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64);
        score += 20.0 - 25.0 * large_item_bonus;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Smooth polynomial coupling: post_residual shaped by stream progress.
    // Early on, prefer tight fits (low post_residual); later, tolerate larger residuals
    // to keep bins flexible, so scale the residual reward non-linearly with progress.
    let progress_coupling = 1.0 + 0.6 * progress * norm_post - 0.4 * (1.0 - progress) * norm_post * norm_post;
    score *= progress_coupling;

    // Penalize dead space quadratically, but relax as stream progresses.
    let dead = norm_post * norm_post;
    score += 30.0 * dead * (1.0 - 0.5 * progress) * cap * 0.01;

    // Reward near-perfect fits with a smooth bump around post_residual ~ 0.
    score -= 15.0 * (1.0 - norm_post).powi(6);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let fit_bonus = (1.0 - gap / cap).max(0.0);
        score -= 10.0 * fit_bonus * fit_bonus * fit_bonus;
    }

    // Last-chance bin: if this is the only fitting bin, penalize wasting it slightly,
    // unless the fit is very tight (smooth interaction with dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - norm_item) * (1.0 - progress);
    }

    // New-bin candidate: mild penalty so we prefer existing bins unless they fit poorly;
    // the penalty fades as mean residual across open bins grows (bins are fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 12.0 - 10.0 * fragmentation * fragmentation;
    }

    // Slight preference for bins with residual near the mean (keeps balance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of small divisors) are preferred.
    let pr = post_residual as i64;
    if pr > 0 {
        let class_bonus: f64 = if pr % 10 == 0 {
            -6.0
        } else if pr % 5 == 0 {
            -3.0
        } else if pr % 2 == 0 {
            -1.5
        } else {
            2.0
        };
        score += class_bonus;

        // Integer-division thresholds: leftover in [1,9] is near-dead space.
        if pr / 10 == 0 {
            score += 8.0;
        }
    } else {
        // Perfect fit is always excellent.
        score -= 15.0;
    }

    // Fraction-of-capacity coupling: reward filling large fractions.
    let fill_frac = item_size as f64 / cap;
    score -= 10.0 * fill_frac;

    // Lookahead harmonic: if next item divides the post residual evenly
    // (post_residual % next_item_size == 0), this bin chains perfectly.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 7.0;
        } else if post_residual - next_item_size <= 9 {
            score += 3.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: leftover is likely dead space.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when open bins are already tight on average.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let tight = mean_residual < 1.5 * item_size as f64;
        if tight || progress < 0.05 {
            score -= 4.0;
        } else {
            score += 10.0 + 20.0 * progress;
        }
    }

    // Slight preference for bins tighter than the mean (best-fit flavor).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap;

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residual gaps are
    // nearly unusable dead space -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Perfect fit gets a big reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residual that can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size {
            // bin could fit next item only if we DON'T place here -> mild penalty
            score += 8.0;
        }
    }

    // Open-bin pressure: more open bins -> favor filling existing ones
    // (i.e., penalize the fresh-bin candidate more as open_bins_count grows).
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // Early stream: allow opening bins more freely.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than average (concentrate waste in few bins).
    if bin_residual < bin_capacity {
        score += 0.3 * ((bin_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weight it less than
    // a perfect 2-step lookahead match.
    score = post_residual as f64 * 1.0;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: the next item exactly fills what remains.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits inside the remaining space: mild reward,
            // stronger the tighter the fit for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit in this bin's remainder: penalize dead
            // space proportionally to how much of it is unusable.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
            // Extra penalty if the dead space is large enough to be truly
            // unusable for typical items (>= 10).
            if post_residual < 10 {
                score += 15.0;
            }
        }

        // Chain check: would the post-residual allow a near-perfect second
        // pairing relative to the current item too?
        if bin_residual == item_size {
            score -= 40.0;
        }
    } else {
        // Last item: pure tightness matters most.
        score = post_residual as f64 * 2.0;
    }

    // --- Contextual coupling with mean residual ---
    // If this bin's residual is far below the mean, it's a "small" bin that
    // should be consumed now rather than left as fragmented space.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    } else {
        score += 0.2 * (res - mean_residual);
    }

    // --- Last-chance bin: strongly prefer using the only fitting bin ---
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Penalize the new bin so it is chosen only when no open bin gives a
        // good fit; the penalty shrinks as the stream progresses and residual
        // space across bins looks fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 80.0;
        // If next item is large, a fresh bin with room is valuable.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            penalty -= 20.0;
        }
        // If many open bins and mean residual is high, fragmentation is low;
        // keep the penalty high. If mean residual is low, prefer new bin.
        if mean_residual < 20.0 {
            penalty -= 15.0;
        }
        penalty -= 10.0 * progress;
        score += penalty;
    }

    // Slight preference for bins with larger residual when all else equal
    // (keeps small slivers from accumulating), scaled by open bin count.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead item can still fit here: strong reward.
            score -= 25.0;
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next == 0 {
                score -= 30.0; // perfect pair placement
            }
        } else {
            // Dead space for the next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64 / cap;
            score += 40.0 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // When many bins are open, prefer consolidation onto fuller bins.
    let open_f = open_bins_count as f64;
    if open_f > 1.0 {
        let fullness = 1.0 - (bin_residual as f64) / cap;
        score -= 20.0 * fullness * (open_f / (open_f + 5.0));
    }

    // Global pressure: if mean residual is low, conserve space more aggressively.
    let mr = mean_residual.max(0.0);
    score += 0.05 * (mr - post_residual as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals flexible); late, squeeze everything in.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above good fits, but attractive
        // early or when no open bin fits well.
        score = cap * 0.9 - 35.0 * (1.0 - t);
        if fitting_bins_count == 0 {
            score -= 1000.0; // must open a new bin
        }
    } else {
        score -= 15.0 * t * (item_size as f64 / cap);
    }

    // Mild penalty for very large leftover slivers (< 10 units) that likely waste space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with non-linear sharpening.
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Stream-progress coupling: later in the stream, dead space matters more.
    let prog_coupling = 2.0 * progress * norm_post * (1.0 - norm_post);
    score += 20.0 * prog_coupling;

    // Penalize near-full-but-wasteful residuals quadratically as stream advances.
    score += progress * norm_post * norm_post * 30.0;

    // Last-chance bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate handling: allow opening a new bin when item fits
    // poorly relative to mean residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = item_size as f64 / cap;
        let poor_fit = (fit_ratio - 0.5).abs() * 2.0; // 0 for half-fill, 1 for extremes
        score = 40.0 + 30.0 * poor_fit * (1.0 - 0.5 * progress);
        // Early stream: opening new bins is cheap; late: expensive.
        score += 30.0 * progress;
        // If next item is large and current fit is bad, favor new bin less.
        if next_item_size > 0 {
            let next_big = next_item_size as f64 / cap;
            score -= 10.0 * next_big * (1.0 - poor_fit);
        }
    } else {
        // Reward bins whose residual stays compatible with the next item.
        if next_item_size > 0 && (post as u32) >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 {
            score += 6.0 * (next_item_size as f64 - post) / cap;
        }
        // Slight penalty when many bins are open (encourage consolidation).
        score += 0.3 * open_bins_count as f64 * norm_post;
        // Mean-residual coupling: prefer bins near the mean (balanced packing).
        score += 2.0 * (post - mean_residual).abs() / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" classes (large enough for typical small items) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class boundaries via integer division on post_residual (harmonic buckets).
    let class = post_residual / 10; // 0..10 harmonic classes
    let class_bonus: f64 = match class {
        0 => -18.0,                       // near-perfect fit, dead space ~0
        1 => -12.0,                       // leftover 10-19: still usable for small items
        2 => -8.0,                        // leftover 20-29
        3 => -4.0,                        // leftover 30-39
        4 => 0.0,                         // neutral
        5 => 3.0,                         // leftover 50-59: awkward class
        6 => 5.0,
        7 => 6.0,
        8 => 4.0,                         // leftover 80-89: big space, fine
        _ => -6.0,                        // leftover 90+: nearly empty bin
    };
    score += class_bonus;

    // Pairing potential: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // Reward proportionally to how snugly the next item will fit.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 10.0 + 8.0 * snug;
        } else {
            // Next item cannot follow here: penalize mildly, stronger if the
            // leftover is small-but-not-zero (worst dead-space class).
            if post_residual > 0 && post_residual < 10 {
                score += 9.0;
            } else {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // would create bad harmonic classes. Penalize the fresh bin by default,
    // scaled by stream progress and current congestion.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 14.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // If the item is huge relative to capacity, opening fresh is less bad.
        if item_size as f64 > 0.6 * cap {
            score -= 10.0;
        }
    }

    // Deviation from mean residual: prefer bins already tighter than average
    // (first-fit-decreasing-like concentration of small leftovers).
    score += 0.15 * (post - mean_residual);

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Slight preference for tighter residual overall (non-linear squash).
    score += 2.0 * (post / cap).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Small-but-usable gaps are also risky: penalize progressively.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (waste-to-residual ratio low).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, mildly prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin (guaranteed extra bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // of all open bins; make the empty-bin candidate less attractive unless
    // existing residuals are nearly exhausted or item is large relative to gaps.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
        // But if item barely fits nowhere well (post_residual small in all bins),
        // mean_residual low means bins are full -> opening new bin is fine.
        if mean_residual < item_size as f64 * 0.35 {
            score -= 30.0;
        }
        // Large items (>60) fragment bins badly; prefer a fresh bin when
        // existing residuals are modest.
        if item_size > 60 && mean_residual < item_size as f64 * 1.2 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    // leaving that shaped gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_diff = post_residual - next_item_size;
        if gap_diff < 10 {
            score -= 10.0;
        }
    }
    // Penalize creating a gap just larger than the next item (dead space).
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 8.0;
    }

    // Prefer bins whose residual is below the mean (fill fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: squash post-residual aggressively.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 120.0;
    } else if post_residual < 25 {
        score -= 40.0;
    }

    // 2-step lookahead: reward if next item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 180.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 15.0 {
                score -= 90.0 - slack * 4.0;
            } else {
                score += slack * 0.6;
            }
        } else {
            // next item cannot fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.2;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize wasteful use of a nearly full bin when other bins could take it.
    if fitting_bins_count > 2 {
        score += 10.0;
    }

    // Late in stream: consolidate; early: allow spreading slightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0;

    // New-bin candidate: only attractive when current bin would leave large dead space
    // and next item is large.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual < next_item_size as u32 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 8.0; // perfect fill
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 15.0;
            // Extra reward if next item fills the bin after this placement.
            let post2 = post_residual as i64 - next_item_size as i64;
            if post2 == 0 {
                score -= 10.0;
            } else if post2 < 12 {
                score += 8.0; // leaves tiny dead space for next item
            }
        } else {
            // Next item won't fit here; mild penalty unless post_residual is tiny.
            score += 5.0;
        }
    }

    // Time horizon: early in stream, be conservative (favor filling open bins);
    // late in stream, tight fits matter more.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * tightness;

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with below-average residual (reduce fragmentation).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
        // If lots of open bins, discourage opening new ones.
        if bin_residual == bin_capacity {
            score += 6.0 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // and current bin fits are poor, or nothing fits well.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let poor_fits = fitting_bins_count <= 1;
        if poor_fits && large_item > 0.6 {
            score -= 20.0;
        } else {
            score += 15.0 + 20.0 * (1.0 - large_item);
        }
    }

    // Slight preference for bins with residual close to item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; late, punish wasted space more.
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score += progress_weight * norm_pr * norm_pr * 20.0;

    // Penalize dead space that cannot fit the next item (smooth quadratic gap term)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let g = gap / cap;
            score += 15.0 * g * g * (1.0 + progress);
        } else {
            // next item fits: reward
            score -= 5.0 * (-gap / cap).min(1.0);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Slight preference for bins deviating from mean residual (consolidation)
    score -= 2.0 * (pr - mean_residual).abs() / cap;

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits (0) and small residues
    // divisible into common item sizes are valuable.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else {
        // Residues that are multiples of common item sizes (10..=100 step 10)
        // are "reusable" classes; reward them.
        let mut reusable = false;
        for k in 10..=100u32 {
            if post_residual >= k && post_residual % k == 0 {
                reusable = true;
                break;
            }
        }
        if reusable {
            score -= 30.0;
        }
        // Penalize awkward dead space in (0,10) which almost nothing fits.
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Integer-division threshold coupling: how well does next_item_size divide
    // into post_residual? Exact division means lookahead fits perfectly.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 60.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    } else if next_item_size > post_residual {
        // Lookahead cannot use this residual: penalize proportionally.
        score += 15.0 + 0.25 * (next_item_size as f64);
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer filling bins with low residual relative to mean (tight packing).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in the stream, tolerate new bins; late, discourage them.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 60.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin always fits the next item.
            score -= 10.0;
        }
    }

    // Mild preference to keep the number of open bins stable.
    if open_bins_count > 10 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward filling a bin deeply (tight packing).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, but allow it when the
    // item would leave a dead gap in every existing bin.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        if post_residual < 10 {
            score -= 45.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 35.0;
    }
    // Penalize post-residuals that cannot host the next item (waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: mild preference to reuse bins over proliferating.
    score += 0.5 * open_bins_count as f64;

    // Late in stream: be more conservative, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly or well
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as u32 - next_item_size) as f64;
        score -= 20.0 - gap.min(30.0) * 0.5;
        if gap == 0.0 {
            score -= 15.0; // exact 2-chain match
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize dead space proportionally
        score += (post_residual as f64).min(next_item_size as f64) * 0.4;
    }

    // Penalize residuals too small for the smallest plausible item (dead space)
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean when fit is good
    score += (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: discourage opening a new bin unless item is huge or fits are terrible
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size > 60 {
            score -= 20.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 15.0;
        }
    }

    // Late in stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residual too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item won't fit here; penalize leaving awkward gap
        score += 6.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        // opening a new bin gets more attractive later and with many open bins
        score += 35.0 - 20.0 * progress - pressure.min(25.0);
        // if the only fitting bin is this new bin, make it cheap
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Prefer filling bins with low residual among open bins (waste minimization)
    if !is_new_bin {
        let gap = mean_residual - post_residual as f64;
        score += gap * 0.15;
    }

    // Mild time horizon modulation: early on, keep bins open (spread), late, consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
