pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse buckets via integer division (capacity / 5 = 20 units each).
    let class_size = (bin_capacity / 5).max(1);
    let post_class = post_residual / class_size;
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / class_size };

    // Perfect fit: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0;
        // Exact harmonic match of classes: next item leaves a similar class.
        if next_item_size == post_residual {
            score -= 150.0;
        }
        // Reward proportional to how well next item consumes the leftover.
        let fill_ratio = next_item_size as f64 / post_residual as f64;
        score -= 40.0 * fill_ratio;
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover: penalize dead space creation.
        score += 25.0;
        // Extra penalty for large unusable gaps (high post class with no fit).
        score += 8.0 * post_class as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else {
        // Mild preference for tighter bins when alternatives exist.
        score += 0.5 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Penalize bins whose residual is far from the mean residual
    // (prefer placements that keep open-bin residuals homogeneous).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Progress coupling: early in the stream, be conservative about
    // fragmenting bins; late in the stream, pack greedily.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (1.0 - progress) * 0.4 * post_residual as f64;
    score -= progress * 0.2 * post_residual as f64;

    // Modulo arithmetic on post_residual: leftovers that are multiples
    // of common small item sizes (10, 20, 25) are more reusable.
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual > 0 && post_residual % 10 != 0 && post_residual < 10 {
        score += 10.0; // tiny sliver, essentially dead space
    }

    // New-bin candidate handling: only prefer a fresh bin when existing
    // residuals are all badly fragmented relative to the item.
    if bin_residual == bin_capacity {
        // Slight inherent bias against opening new bins.
        score += 30.0;
        // But if the stream is early and open bins are very full, allow it.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > 80 {
            score -= 10.0; // big item coming, keep room
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful later are heavily penalized.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize waste proportional to how much of the bin stays unused
    // relative to capacity (encourages dense packing).
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones and favor consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + pressure;
    } else {
        score -= pressure.min(20.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 3 {
            score -= 8.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            // Dead space relative to the known next item: mild penalty.
            score += 5.0;
        }
    }

    // Slight preference for bins with below-average residual (tighter bins
    // get closed out sooner).
    if !is_new_bin {
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff); // strong bonus for perfect follow-up fit
        // Slight penalty if the next item cannot fit here (dead space for the future)
        if next_item_size > post_residual {
            score += 6.0;
        }
        // Bonus if next item fits tightly too (post_residual - next stays small)
        if next_item_size <= post_residual {
            let second_post = post_residual - next_item_size;
            score -= 15.0 * (1.0 - second_post as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer filling bins as tightly as possible
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize creating tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward using relatively full bins (best-fit flavor)
    score -= 20.0 * (item_size as f64 / bin_residual as f64);

    // Compare against mean residual: prefer bins below mean residual (tighter bins)
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-penalized so it's chosen only
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Mild stream progression bias: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // lookahead item can fill leftover
        } else {
            score += 0.35 * (post_residual as f64); // dead space penalty
        }
    }

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Discard fragmentation when many bins already open
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with residual below mean (pack small leftovers together)
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Time horizon: early on, be picky; late, accept more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    // New-bin candidate: only attractive when current bin is a bad fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0;
        if fitting_bins_count == 1 {
            score -= 40.0; // then new bin is actually better than last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: dead space penalty grows quadratically with
    // small residuals, modulated by stream progress.
    let dead = (1.0 - norm_pr).powi(2);
    score += 4.0 * dead * (0.3 + 0.7 * progress);

    // Reward tight fits: subtract when post_residual is small but nonzero.
    if post_residual > 0 {
        let tight = (1.0 - norm_pr).powi(3);
        score -= 6.0 * tight;
    }

    // Penalize bins whose residual diverges from the mean (avoid fragmented space).
    score += 0.05 * (pr - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: reward if next item can fit into post_residual.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 2.0 * (next_item_size as f64 / cap);
        } else {
            score += 1.5 * ((next_item_size as f64 - pr) / cap);
        }
    }

    // Mild pressure to consolidate into open bins as stream progresses.
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate (empty bin): post_residual == cap, make it less attractive
    // than a decent fit but viable when no good fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 20
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class20 = (pr % 20) as f64;

    // Penalize awkward residues: post-residual not near a multiple of 10/20
    score += class10 * 0.8;
    score += (10.0 - class20).abs() * 0.3;

    // Dead-space classes: tiny unusable leftovers are bad
    if pr > 0 && pr < 10 {
        score += 25.0; // dead space below min item size
    }
    if pr == 0 {
        score -= 15.0; // perfect fill
    }

    // Integer division thresholds on post_residual
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr > half {
        score -= 8.0; // still roomy, flexible bin
    } else if pr > quarter {
        score += 2.0;
    }

    // Lookahead coupling: harmonic class of next item vs post_residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 6.0; // next item fits here too
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 4.0; // harmonious leftover
            }
        } else {
            score += 5.0; // next item won't fit after this placement
        }
    }

    // Last-chance bin: strongly favor using it before opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize mildly so
    // it only wins when open bins are truly bad fits
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Stream progression: tighten packing near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 5.0 * post_residual as f64; // gap of 1 is worst
    } else if post_residual > 10 && post_residual < 20 {
        score += 10.0; // moderately awkward gap
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when other
    // fitting bins exist and open-bin count is low.
    if bin_residual == bin_capacity {
        score += 70.0 + 8.0 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 30.0;
        }
        // Lookahead: if next item fits comfortably in a fresh bin's residual
        // after this placement, soften the penalty slightly.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose post-residual can still host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size && next_item_size >= 1 {
            score -= 12.0;
        }
        // Penalize bins that are much emptier than average (poor consolidation).
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += dev * 0.15;
        }
    }

    // Open-bin pressure: with many open bins, consolidate into existing ones.
    score += 0.5 * open_bins_count as f64;

    // Late in the stream, tighten up: avoid leaving scattered residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
