    }

    // New-bin candidate: discourage opening a new bin unless it enables a
    // perfect future pairing with the next item.
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        let lookahead_pair = if next_item_size > 0 {
            (next_item_size as f64 + item_size as f64) / bin_capacity as f64
        } else {
            0.0
        };
        score += base_penalty - 30.0 * lookahead_pair;
        // Later in the stream, be more conservative about new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for contributing to bin sprawl.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable dead space (1..=10) — wasted capacity
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits generally: score scales with how much of the bin gets used
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // mild reward for leaving space usable by next item
            score -= 6.0;
        } else {
            // penalize leaving a gap smaller than next item (dead space for lookahead)
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer placing into bins with residual below mean residual (consolidating small spaces)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, be more willing to open new bins to create flexibility
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late
        score = 30.0 + 60.0 * progress - 10.0 * (1.0 - progress);
        // Never open a new bin when a perfect fit exists elsewhere (score would be very low there)
        if post_residual == 0 { score = 0.0; }
        // If many open bins already, opening another is fine early on
        if open_bins_count > 3 && progress < 0.5 { score -= 8.0; }
    } else {
        // Late in stream, avoid leaving many fragmented bins: reward filling existing bins more
        score += 10.0 * progress;
    }

    // Mild penalty for too many open bins (fragmentation control)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr as f64;
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Smooth progress coupling: later in stream, penalize loose fits more
    score += 25.0 * progress * norm_pr;

    // Reward near-perfect fits via smooth decay of wasted space
    let waste_frac = pr as f64 / cap;
    score -= 30.0 * (1.0 - waste_frac).powi(6);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving awkward space
        score += 8.0 * (pr / cap);
    }

    // Mean-residual coupling: penalize bins far from the mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Open-bin pressure: with many open bins, discourage spreading
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 55.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25.
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Dead-space penalty: residues 1..9 (mod 10) are hard to fill with integer items.
    if r10 > 0 {
        score += 3.0 + 0.5 * r10 as f64;
    }
    // Residues mod 25 that are small but nonzero are worst (near-unusable).
    if r25 > 0 && r25 < 10 {
        score += 4.0;
    }

    // Reward small post_residual (tight fit) super-linearly.
    if post_residual <= 10 {
        score -= 8.0;
    } else if post_residual <= 25 {
        score -= 4.0;
    } else if post_residual <= 50 {
        score -= 1.0;
    }

    // Perfect-fill harmonic classes: post_residual in {0, 25, 50} is highly reusable.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual == 25 || post_residual == 50 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let nr10 = next_item_size % 10;
            // Prefer bins whose post_residual is in the same decade class as next item.
            if post_residual / 10 == (post_residual - next_item_size) / 10 {
                score -= 2.0;
            }
            if nr10 == 0 {
                score -= 1.5;
            }
            // Penalize if next item leaves another tiny residue.
            let next_post = post_residual as i64 - next_item_size as i64;
            if next_post > 0 && next_post < 10 {
                score += 2.0;
            }
        } else {
            // Next item won't fit here; penalize large leftover.
            score += 1.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins are fragmented.
    if bin_residual == bin_capacity {
        // Base neutral score: slightly worse than a tight fit, better than garbage fits.
        score = 60.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 15.0; // open bins nearly full anyway
        }
        if next_item_size > 80 {
            score -= 5.0; // big next item benefits from fresh bin
        }
    }

    // Stream progression: later in stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    // Mean residual coupling: if this bin is far below mean residual, it's a good donor.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 2.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Unusable sliver: heavily penalize (below the minimum item size).
            score += 60.0 * (10.0 - gap) / 10.0;
        } else if gap < 25.0 {
            // Small gap usable only by tiny items: moderate penalty.
            score += 15.0 * (25.0 - gap) / 15.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (post_residual small relative to residual).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill_ratio;
    }

    // Open-bin pressure: discourage spreading across many bins early.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or bins are crowded.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when justified.
        score += 30.0;
        // Less penalty when many bins are open (consolidation is hopeless).
        score -= (open_bins_count as f64).min(20.0);
        // If the current bin is the only fitter, opening new bins is wasteful.
        if fitting_bins_count <= 1 {
            score += 40.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let lookahead_fit = 1.0 - (post_residual - next_item_size) as f64 / post_residual as f64;
        score -= 12.0 * lookahead_fit;
    }
    // Penalize if next item cannot use the leftover gap (dead space likely).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild stream progression effect: late in the stream, favor consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Mean residual coupling: when mean residual is high, prefer filling fuller bins.
    score += 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can still host the next item (chain-packing), penalize near-misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits: reward proportionally to tightness of the future fit
            let future_tight = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.35 * future_tight;
        } else {
            // next item does not fit: penalize, worse if the gap is small (near miss)
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.5 * gap;
        }
    } else {
        // last item: prefer minimal leftover
        score += 0.0;
    }

    // Penalize creating unusable dead space (very small leftovers that nothing can use)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin
    // offers a good (tight) fit. Penalize new bins unless the current item
    // is large relative to capacity (poorly fittable elsewhere).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // big items justify a fresh bin; small items should go into open bins
        score += 45.0 - 40.0 * tightness;
        // if no open bin fits at all, opening is mandatory
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild preference for bins tighter than the mean residual (good fits concentrate)
    let mr = mean_residual;
    if (bin_residual as f64) < mr {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Slight stream-phase adaptation: early on, be more open to spreading items
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - phase);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly / well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect pairing
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0; // next item won't fit here; mild penalty
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0 * (1.0 - fill_ratio);
    score -= progress * 5.0;

    // Global pressure: when many bins are open relative to progress, discourage
    // opening new bins; when few bins are open, a new bin is cheap.
    let new_bin_penalty = (open_bins_count as f64) * (1.0 - progress) * 2.0;
    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: base cost plus pressure, small discount
        // if the item is large relative to capacity (hard to place later).
        score += 15.0 + new_bin_penalty - 10.0 * (item_size as f64 / bin_capacity as f64);
    } else {
        score -= new_bin_penalty * 0.5;
    }

    // Deviation from mean residual: prefer bins with residuals close to the mean
    // (keeps residual distribution balanced) but favor slightly-lower-than-mean
    // bins for large items.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs() - 0.1 * dev * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: post residual (prefer tight fits)
    let mut score = pr;

    // Non-linear coupling: dead-space penalty grows superlinearly with progress
    let dead = (x * x) * (1.0 + 2.0 * progress);
    score += 60.0 * dead;

    // Reward near-perfect fits smoothly (small post residual favored non-linearly)
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (1.0 + progress);

    // Lookahead: reward if next item can fit into post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr as f64 {
            score -= 12.0 * (1.0 - ns / cap) * (1.0 + progress);
        } else {
            // penalize leaving a residual too small for the next item
            score += 8.0 * (ns - pr as f64) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Prefer bins below mean residual slightly (balance load), smooth interaction
    score += 3.0 * ((pr as f64 - mean_residual) / cap) * (1.0 - progress);

    // Mild preference for using existing bins over opening new ones as stream progresses
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets (dead-space severity classes).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left over
    // Penalize leftovers that are "almost useless" — small but nonzero.
    // Class thresholds via integer division on post_residual.
    let class = post_residual / 10; // 0..=10 harmonic classes
    match class {
        0 => score += 30.0,                 // 0-9 left: near-perfect fill
        1 => score += 12.0,                 // 10-19: small usable sliver
        2 => score += 2.0,                  // 20-29: good
        3 => score += 0.0,                  // 30-39: ideal zone
        4 => score -= 1.0,                  // 40-49: fine
        5 => score -= 2.0,                  // 50-59: half-full, still useful
        _ => {}                             // 60+: large residual, neutral
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0; // perfect chaining
        } else {
            score -= 10.0 * (1.0 - slack as f64 / cap);
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize proportionally
        // to how dead the leftover is for the lookahead.
        score += 6.0 * frac;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream
        // and when many bins are already open (consolidation less valuable).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 - 20.0 * progress - 2.0 * open_bins_count as f64;
        // If item leaves a harmonic-good residual in a fresh bin, slightly better.
        let fresh_class = (bin_capacity - item_size) / 10;
        if fresh_class <= 2 { new_bin_score += 10.0; }
        // If no open bin fits at all, new bin must win.
        if fitting_bins_count == 0 { new_bin_score -= 100.0; }
        score = score.min(new_bin_score);
        score = new_bin_score;
    }

    // Mild preference for tighter fits among comparable residuals.
    score += (bin_residual as f64 - item_size as f64) * 0.05;
    // Tie-break toward bins below mean residual (consolidate emptier bins).
    score -= 0.02 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residual that no plausible item (1..=100) can use efficiently.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Pressure from number of open bins: prefer filling existing bins
    // when many are already open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
        // But if next item is large and this item is small, a fresh bin is fine.
        if next_item_size >= 70 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (use the tightest bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the residual left behind matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit in this bin afterwards; penalize wasted space.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.6 * miss;
        }
    }

    // Penalize residuals that are small and unusable (dead space relative to item scale).
    if post_residual > 0 && post_residual < item_size {
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing bins have poor fits. Penalize the empty bin mildly so it loses
    // to good fits, but let it win when all open bins would leave huge waste.
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin perfectly sequenced for the next item is attractive.
            if bin_capacity - next_item_size <= item_size {
                score -= 90.0;
            }
        }
    }

    // Context coupling: prefer filling bins whose residual is above mean
    // (drain large-residual bins first), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - bin_residual as f64) * (0.3 + 0.5 * progress);

    // Slight preference to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space with non-linear growth
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fit bonus
    }
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Lookahead: reward bins whose post_residual can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        // perfect two-item packing bonus
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Time horizon: early in stream, be more willing to open new bins;
    // late in stream, squeeze into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate
        score = 100.0 * (1.0 - progress * 0.5) + post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        if fitting_bins_count <= 2 {
            score += 40.0; // only open new bin if alternatives are scarce
        }
    } else {
        score -= progress * 8.0; // late stream favors filling existing bins
    }

    // Many open bins: discourage spreading items across bins
    if open_bins_count > 10 {
        score += (open_bins_count as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 0.5 * progress) - norm_pr * norm_pr * norm_pr * (1.0 - progress);
    score += poly * 40.0;

    // Reward tight fits more strongly as stream progresses (smooth sigmoid-ish coupling)
    let tight = 1.0 - norm_item;
    score -= tight * tight * (1.0 + progress) * 10.0;

    // Penalize dead space that cannot fit the next item, smoothly scaled by progress
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score -= gap * gap * (0.5 + progress) * 15.0;
        score += (pr - norm_next * cap).abs() / cap * (1.0 - progress) * 5.0;
    }

    // Last-chance bonus: strongly favor using the only fitting bin, smoothed
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when many bins are open (encourage consolidation), non-linear in count
    score += (open_bins_count as f64).powf(0.5) * (1.0 - progress) * 2.0;

    // Coupling with mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 8.0;

    // New-bin candidate: penalize opening a new bin, more so early and when fits exist
    if bin_residual == bin_capacity {
        let new_bin_bias = 25.0 + 30.0 * (1.0 - progress) + 15.0 * (fitting_bins_count as f64).min(5.0) / 5.0;
        score += new_bin_bias;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but strongly punish
    // tiny unusable slivers that waste capacity ("dead space").
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // sliver: worse than leaving a usable 10+ gap
    }

    // Harmonic class of post_residual: group residual into capacity-fraction
    // classes (1/2, 1/3, 1/4 of capacity). Residuals near class boundaries
    // are more reusable by future items.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;
    if post_residual >= half {
        score -= 6.0; // roomy bin stays flexible
    } else if post_residual >= third {
        score -= 3.0;
    } else if post_residual >= quarter {
        score -= 1.0;
    }

    // Modulo-class coupling: if the next item exactly divides into the
    // post_residual (same harmonic class), reward heavily (lookahead fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 12.0; // perfect two-item closure
        } else if gap < 10 {
            score += 8.0; // would create a sliver for next item
        } else {
            score -= gap as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + (bin_capacity - post_residual) as f64 * 0.05;
    }

    // New-bin candidate handling: empty bin should only win when no open
    // bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 5.0;
        if post_residual as f64 > mean_residual {
            score += 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.03;

    // Penalize bins whose residual deviates from the mean (keep pool uniform).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Large items: prefer bins where they dominate the fill.
    if item_size > bin_capacity / 2 {
        score -= 4.0;
    }

    // Modulo threshold on post_residual: multiples of common item sizes
    // (10..80 grid) are reusable; odd remainders are not.
    if post_residual % 10 != 0 && post_residual > 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item (1)
    // are pure waste; penalize non-linearly in the "awkward gap" zone.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps (10..=20) are only usable by small items; mild penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += 0.5 * (20 - post_residual) as f64;
    }

    // Reward tight fits: fill fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.15 + 0.35 * progress);

    // Lookahead: if next item can use the post residual, reward leaving it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.2 * (next_item_size as f64);
        } else if post_residual > 0 {
            // Next item can't use the gap -> dead space likely; penalize.
            score += 0.3 * post_residual as f64;
        }
    }

    // New-bin candidate handling: a fresh bin is attractive when current fit
    // is loose (large post_residual relative to next item) or bins are few.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5
            + 10.0 * (open_bins_count as f64)
            - 0.5 * (post_residual as f64);
        if fitting_bins_count <= 2 {
            score -= 25.0; // few alternatives -> opening new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual can still fit the next item comfortably
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(25.0); // reward, decaying with slack
    }

    // Penalize dead space: post_residual too small for any plausible item (min size 1..100 unknown; use item_size as hint)
    let min_hint = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size.min(20) };
    if post_residual > 0 && (post_residual as f64) < (min_hint as f64) * 0.5 {
        score += 25.0; // unusable sliver
    }

    // Compare against mean residual: placing in a bin with residual far above mean wastes tight bins
    score += 0.35 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: only bin that fits — strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        score += 35.0 + 2.0 * open_pressure;
        // but if next item is huge and no bin pairs well, new bin is fine
        if next_item_size >= 70 {
            score -= 20.0;
        }
        // late in stream, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild bonus for tight fills (low post residual already does this via base term)
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling: quadratic + cubic in normalized post residual,
    // modulated by stream progress.
    let poly = norm_post * norm_post * (1.0 - norm_post) * (1.0 - norm_post);
    score += 30.0 * poly * (1.0 - progress);

    // Penalize large dead space late in the stream (smooth cubic in progress).
    score += 40.0 * progress * norm_post * norm_post;

    // Reward tight fits smoothly (post residual near zero).
    score -= 20.0 * (1.0 - norm_post).powi(3);

    // Lookahead: reward if next item fits the post residual (smooth coupling).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let fit_ratio = ns / cap;
            score -= 15.0 * fit_ratio * (1.0 - norm_post) * (1.0 - progress);
        } else {
            let gap = (ns - pr) / cap;
            score += 12.0 * gap * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins early.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins with large mean residual.
    score += 0.5 * (mean_residual - pr).abs() / cap * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as i64;
    let item = item_size as i64;

    // Reward tight fits: post_residual in small harmonic classes
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for any plausible item
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Modulo-class coupling: residual divisible classes (harmonic fractions)
    let quarter = (bin_capacity / 4) as i64;
    let half = (bin_capacity / 2) as i64;
    if pr % quarter == 0 && pr > 0 {
        score -= 8.0; // quarter-aligned residual is reusable
    }
    if pr > half {
        score -= 6.0; // keep half-full bins attractive
    }

    // Lookahead: does next item fit the post-residual?
    if next_item_size > 0 {
        if (next_item_size as i64) <= pr {
            score -= 12.0; // chain placement possible
            // harmonic match: next item leaves another small residual
            let next_pr = pr - next_item_size as i64;
            if next_pr < 10 && next_pr >= 0 {
                score -= 10.0;
            }
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer it late or when residual is huge
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item > 60 {
            score -= 20.0; // big item deserves fresh bin
        } else {
            score += 25.0 - 20.0 * progress; // early: discourage new bins
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Spread penalty: bin far from mean residual is less predictable
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild pressure to consolidate when many bins open
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Penalize bins whose residual is barely larger than the item (tight fits
    // that leave almost nothing usable), but reward genuinely tight fits.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than opening new bins.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item leaves
    // a very large residual in the new bin or current bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If the next item is small enough to use leftover space elsewhere,
        // opening a new bin is slightly less bad.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        // Late in the stream, avoid opening new bins even more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 25.0;
        }
    }

    // Lookahead: if next item exactly matches post_residual, reward heavily
    // (this bin's leftover will be perfectly consumed).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (smaller
    // residuals = closer to full) to consolidate fullness.
    score += (mean_residual - post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect 2-step lookahead match (next item exactly fills this bin after ours)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // next item can also fit here later; mild reward proportional to closeness
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 / (1.0 + gap * 0.25);
        } else {
            // dead space that next item cannot use: penalize dead space amount
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5;
        }
    } else {
        // last item: reward tight fit
        score -= 200.0 / (1.0 + post_residual as f64);
    }

    // Reward bins whose residual is already small (good compaction relative to mean)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.8;
    } else {
        score += (res - mean_residual) * 0.4;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when other bins could fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 150.0 + 100.0 * progress };
        // New bin is attractive only if the item leaves a huge hole elsewhere or no bin fits
        let waste_elsewhere = if fitting_bins_count > 0 {
            // approximate: min residual among fittings unknown; use mean residual proxy
            (mean_residual - item_size as f64).max(0.0)
        } else { 0.0 };
        score += pressure - waste_elsewhere * 1.2;
        // occasionally good to open fresh bin for large items leaving small post_residual
        score -= (50.0 - res.min(50.0)) * 0.5;
    }

    // Slight preference for tighter fits overall
    score += (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Lookahead: penalize if the next item cannot use the post_residual.
    if next_item_size > 0 {
        if next_item_size as f64 > post_residual as f64 {
            score += 12.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        } else {
            // Next item fits: reward leaving just enough room.
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (10.0 + 20.0 * (1.0 - progress)) * (mean_residual / bin_capacity as f64);

    // Mild preference for filling bins with low residual relative to the mean.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Small time-horizon term: late in the stream, prefer tighter packing.
    score -= 5.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress) - 1.5 * norm_pr * norm_pr * (0.5 + progress);
    let cubic = 2.0 * norm_pr * norm_pr * norm_pr * progress * (1.0 - progress);

    // Reward tight fits (low post_residual), penalize dead space more as stream progresses
    let mut score = pr - 30.0 * poly - 20.0 * cubic;

    // Lookahead coupling: reward leaving space for the next item, smooth interaction
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = ((pr - next_item_size as f64) / cap).max(0.0);
        let coupling = nx * (1.0 - (pr / cap)) * (1.0 + progress);
        score -= 12.0 * fit * (1.0 - nx) - 8.0 * coupling;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balance)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs() * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize slightly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) + 5.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity fractions
    let frac = (post_residual as f64) / (bin_capacity as f64);
    let mut class = 0.0;
    if post_residual == 0 {
        class = -1.0; // perfect fill
    } else {
        let q = post_residual / 10; // integer division thresholds (decile classes)
        class = q as f64;
        // modulo arithmetic: penalize "awkward" residuals (odd, prime-ish zones)
        if post_residual % 2 == 1 {
            class += 0.5;
        }
        if post_residual % 5 == 0 {
            class -= 0.3;
        }
    }
    score = score * 0.5 + class * 2.0;

    // Reward tight fits (small post_residual) with harmonic bonus
    if post_residual <= 10 {
        score -= 8.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    } else if post_residual <= 30 {
        score -= 2.0;
    }

    // Coupling with next item: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 6.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score -= 3.0; // acceptable dead space if tiny
        } else if post_residual < next_item_size {
            score += 4.0; // dead space blocking lookahead item
        }
        // modulo harmony between post_residual and next_item_size
        let g = gcd(post_residual.max(next_item_size), post_residual.min(next_item_size).max(1));
        if g > 1 && post_residual > 0 && next_item_size > 0 {
            score -= (g as f64).min(5.0) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big lookahead item benefits from fresh bin
        }
    }

    // Progress-based calibration: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (30.0 - post_residual.min(30) as f64) * 0.15;

    // Penalize bins whose residual is far from mean residual (imbalance)
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 40.0;
    } else {
        // Reward leaving gaps that can plausibly host future items (>=10).
        score -= 5.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize creating a residual that is smaller than the next item
    // when the gap is unusable for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size as u32 && post_residual < next_item_size as u32 + 10 {
        score -= 10.0; // gap is immediately reusable
    }

    // Last-chance bin pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when the stream is young and few bins exist.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Prefer bins with residual close to the item (minimal waste).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * waste;

    // Slight preference for bins whose residual deviates from mean
    // toward smaller residuals (consolidate space).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits tightly into the leftover space.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * tightness;
    }

    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Penalize leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward tight fits overall (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (residual far from item size) or when the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_fit_exists = (bin_residual as i64 - item_size as i64).abs() as f64;
        let _ = good_fit_exists;
        score += 30.0 + 40.0 * (1.0 - progress) - mean_residual * 0.3;
        // If the new bin would enable a perfect next-item match, discount the penalty.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 80.0;
        }
    }

    // Mild preference for balancing residuals against the mean.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful (below min item size 1..100 heuristic band).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item could co-fit in the post residual, reward.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 10.0;
        } else {
            // Penalize leaving residuals that waste the next item's fit options.
            let waste = (next_item_size as f64 - post_residual as f64).min(50.0);
            score += 0.15 * waste;
        }
    }

    // Global state: prefer filling bins when many bins are open (consolidation pressure).
    let open_pressure = (open_bins_count as f64 / (1.0 + total_items as f64 * 0.05)).min(3.0);
    score -= 3.0 * open_pressure * fit_ratio;

    // Time horizon: early in stream, be conservative (favor new bins for large items);
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 8.0 * progress * fit_ratio;
    score += 6.0 * (1.0 - progress) * (1.0 - fit_ratio);

    // Mean residual anchoring: bins far below mean residual are "leftover" bins; prefer to consume them.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.05 * dev;

    // New-bin candidate handling: neutral-ish score for empty bin, but discourage opening
    // a new bin when the item fits well somewhere or many bins already exist.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64 - 10.0 * fit_ratio;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post residual), with non-linear shaping
    let mut score = pr as f64;

    // Smooth non-linear coupling: polynomial in x modulated by stream progress
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like in [0,1]
    score += 12.0 * poly * (0.5 + progress);

    // Penalize residuals that neither fit the next item nor vanish
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) as f64;
        score += 0.35 * waste * (1.0 - progress);
        // Reward if next item fits exactly-ish
        let gap = (pr - nx).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0);
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for fragmenting when many bins are open
    score += 0.02 * (open_bins_count as f64) * x * x;

    // New-bin candidate handling: make empty bin attractive only for large items
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: reward residuals that are
    // "clean" fractions of capacity (0, small, or exact multiples of 10),
    // penalize awkward mid-range dead space.
    let pr = post_residual;
    let class_mod = pr % 10;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else if pr < 10 {
        score -= 8.0; // near-perfect, nearly unusable anyway
    } else if class_mod == 0 {
        score -= 4.0; // decade-aligned residual, easy to fill
    } else if class_mod <= 2 || class_mod >= 8 {
        score -= 1.5; // near decade boundary
    } else {
        score += 3.0; // awkward mid-class dead space
    }

    // Penalize large residuals more aggressively as stream progresses
    // (less opportunity to recover waste later).
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (pr as f64 / bin_capacity as f64) * 12.0 * progress;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if next item cannot possibly fit here, slight penalty.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr && (pr - next_item_size) % 10 == 0 {
            score -= 6.0;
        } else if next_item_size > pr {
            score += 2.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when no open bin offers a tight fit (post_residual small).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins are open
        // (consolidation pressure) or early in the stream.
        let base = 14.0 - 6.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        score = base + item_size as f64 * 0.15 + progress * 4.0;
        if next_item_size > 0 && next_item_size <= pr && (pr - next_item_size) % 10 == 0 {
            score -= 5.0; // next item will slot cleanly into this fresh bin
        }
    }

    // Mild consolidation: prefer bins whose residual is below the mean
    // (tighter bins get priority).
    score += ((mean_residual - bin_residual as f64) * 0.05).max(-3.0).min(3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical
    // items are heavily penalized (unusable space).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // awkward small gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill, reward strongly
    } else if post_residual >= 20 && post_residual <= 35 {
        score -= 10.0; // usable gap for medium items
    }

    // Fit tightness: reward bins whose residual is close to the item size.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;

    // Last-chance pressure: if this is the only fitting bin, strongly favor
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // low-fill bins; encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // Prefer bins whose residual is below the mean residual (denser bins),
    // penalize sparse bins when many bins are open.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.15 * (1.0 + open_bins_count as f64 * 0.05);
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.05;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // blocks the lookahead item
    }

    // New-bin candidate handling: an empty bin has neutral base (residual=100).
    // Make it attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        } else {
            // Opening a new bin competes with existing bins; make it slightly
            // unattractive unless the existing fits are terrible.
            score += 20.0 + progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but heavily penalize
    // dead space that is too small to ever be useful.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // 2-step lookahead: reward when next item exactly fills the post_residual,
    // penalize when next item cannot fit here at all (forcing future new bin).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();
        score -= 15.0 * (1.0 - diff / cap).max(0.0); // near-perfect chaining bonus
        if next_item_size > post_residual && post_residual > 0 {
            score += 12.0; // next item won't fit here: residual likely wasted
        }
        if (pr - ni).abs() <= 2.0 {
            score -= 20.0; // exact two-item fill
        }
    } else {
        // Last item: just minimize waste
        score += 5.0 * pr / cap;
    }

    // Compare against mean residual: placing in a bin with below-average residual
    // (i.e. already partially filled) keeps spread of residuals tight.
    score += 0.3 * (pr - mean_residual);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // is large and current residuals are all poor fits.
    if bin_residual == bin_capacity {
        let poor_fits = if next_item_size > 0 {
            (mean_residual - item_size as f64).abs() < 5.0
        } else {
            false
        };
        let large_item = item_size as f64 > 0.7 * cap;
        if large_item || poor_fits {
            score -= 10.0;
        } else {
            score += 15.0; // discourage opening bins when existing fits exist
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0 is ideal).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powf(1.8);
        score += 8.0 * dead;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // if next item almost fits (small gap), mildly penalize wasted opportunity.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 6.0 * (1.0 - (post_residual as f64 - n) / bin_capacity as f64);
        } else {
            let gap = next_item_size as u32 - post_residual;
            if gap <= 10 {
                score += 3.0 * gap as f64 / 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing bins,
    // discourage opening new bins when fragmentation is already high.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.35 * crowding * (0.5 + progress);

    // New-bin candidate handling: empty bin gets a baseline penalty that
    // shrinks when mean residual is low (few usable leftovers).
    if bin_residual == bin_capacity {
        let scarcity = (mean_residual / bin_capacity as f64).max(0.0);
        score += 20.0 * (1.0 - scarcity.min(1.0)) + 5.0 * progress;
    }

    // Prefer bins whose residual is close to the item (minimizes leftover).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * fit_gap * fit_gap;

    // Mild global balance: bins far from mean residual get slight penalty.
    score += 0.05 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.6 * x * x);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, waste is cheap; later, tight fits matter more.
    let progress_coupling = pr * (t * t + 0.5 * t * (1.0 - t) * x);
    score += 2.0 * progress_coupling;

    // Dead-space penalty: post residual too small for typical future items
    let dead = (x * (1.0 - x)).powi(2) * cap; // peaks at x=0.5 (awkward leftover)
    score += 3.0 * dead * (0.5 + t);

    // Lookahead: reward bins that can also fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 * (nx / cap) * (1.0 + t);
        } else {
            score += 4.0 * (nx / cap) * (1.0 - t);
        }
    }

    // Last-chance bonus: only fitting bin -> strong incentive to use it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x);
    }

    // Mild pressure toward consolidating into bins below mean residual
    score -= 0.5 * (mean_residual - pr) / cap;

    // Slight penalty for many open bins to discourage fragmentation
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "clean" is the leftover space?
    // Residuals that are multiples of common item sizes are reusable; odd ones are dead space.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit is ideal
    } else if pr % 10 == 0 {
        -25.0
    } else if pr % 5 == 0 {
        -10.0
    } else if pr >= 10 {
        0.0
    } else {
        15.0 // tiny unusable sliver
    };
    score += harmonic_bonus;

    // Integer division thresholds: classify post_residual into usable size bands
    let band = pr / 20; // 0..5
    score += match band {
        0 => 20.0,           // 0..19: mostly dead space unless zero
        1 => 5.0,            // 20..39
        2 => -3.0,           // 40..59
        3 => -6.0,           // 60..79
        _ => -8.0,           // 80+: very reusable
    };

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward proportional closeness of fit for the next item
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; mild penalty for wasting large residual
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when plenty of open bins exist with room
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus crowding penalty
        score += 25.0 + 2.0 * open_bins_count as f64;
        // But if mean residual is small (bins nearly full), a new bin is fine
        score -= 0.3 * mean_residual;
        // Early in the stream, allow new bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for fuller bins as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0; // heavy penalty for tiny dead space
    }
    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual >= 50 {
        // large leftover is still usable; mild reward relative to baseline
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 150.0;
        } else if gap < 10 {
            score -= 40.0;
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // dead space that the next item cannot use: extra penalty
        score += 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins over spawning new ones.
    if bin_residual == bin_capacity {
        // brand-new bin candidate: penalize proportionally to number of open bins,
        // but allow it when existing residuals are large and fragmented.
        score += 90.0 + 15.0 * open_bins_count as f64;
        if mean_residual > 40.0 {
            score -= 50.0; // existing bins too full/fragmented anyway
        }
    } else {
        score -= 5.0 * (open_bins_count as f64).ln().max(1.0);
    }

    // Mean residual coupling: bins far below mean residual (fresher) are slightly favored
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Late-stream tightening: as stream progresses, avoid waste more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item exactly fills the post residual (perfect 2-step match)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
