            post_residual as f64
        } else {
            0.0
        };
        score += 1.5 * dead;
    }

    // Relative to mean residual: prefer bins tighter/worse than average being filled
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mildly discourage opening new bins early in the stream,
    // more acceptable late when residuals are fragmented
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 - 40.0 * progress;
        // opening a new bin is fine if it enables a perfect next-item fit
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 20.0;
        }
    }

    // Prefer packing into bins with small residual overall (tight fit preference)
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize creating dead space that cannot plausibly be reused:
    // dead space is "unusable" if it's smaller than the smallest plausible item (1)
    // or if it's smaller than the lookahead item but nonzero.
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 15.0;
    }

    // Lookahead synergy: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Mild reward if next item can still fit after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so it is
    // chosen only when open bins fit poorly, but reward it when the stream is
    // young and many items remain (future flexibility is valuable).
    if bin_residual == bin_capacity {
        score += 40.0;
        let progress = step_index as f64 / total_items as f64;
        score -= 50.0 * (1.0 - progress);
        // If no open bin fits well, opening a new bin is attractive.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Penalize opening new bins when many bins are already open with slack.
        score += 3.0 * open_bins_count as f64;
    }

    // Global slack coupling: prefer bins whose residual deviates from the mean
    // in a way that consolidates waste (fill the emptiest bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Late in the stream, be greedy: minimize post-residual hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Base: post residual, with non-linear polynomial shaping of waste
    let mut score = post * (1.0 + 0.8 * post_norm * post_norm);

    // Smooth coupling: prefer tight fits as stream progresses
    let fit_ratio = item_size as f64 / residual.max(1.0);
    score -= 12.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Dead-space penalty: residual too small for plausible future items
    let small_floor = 10.0;
    if post < small_floor {
        score += 25.0 * (small_floor - post) / small_floor;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - post / cap) * (1.0 - progress);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post_norm);
    }

    // Pressure from many open bins vs mean residual: encourage consolidation
    let mean_gap = (mean_residual - post) / cap;
    score += 5.0 * mean_gap * mean_gap * (open_bins_count as f64).ln().max(1.0);

    // Mild new-bin caution grows late in stream
    if bin_residual == bin_capacity {
        score += 3.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: reward residuals that belong to
    // "usable" classes (large enough to fit small future items), penalize
    // dead-space classes.
    let pr = post_residual as f64;

    // Perfect fit gets a massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class reward by integer division thresholds on post_residual.
    // Residuals in [1..=10] are nearly dead space -> penalize.
    // Residuals in [11..=30] can host small items -> mild reward.
    // Residuals > 30 keep flexibility.
    let cls = post_residual / 10;
    match cls {
        0 => score += 40.0,               // dead space class (1..=9)
        1 => score -= 5.0,                // 10..=19
        2 => score -= 10.0,               // 20..=29
        3 => score -= 12.0,               // 30..=39 sweet spot
        _ => score -= 6.0,                // large residual, moderately good
    }

    // Harmonic (modulo) coupling: residuals that are multiples of common
    // small item sizes (10, 20, 25, 50) are more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize small leftovers more
            let waste = post_residual as f64 / cap;
            score += 15.0 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer open bins with reasonable fits; only choose a new bin when
    // nothing else is attractive. Add a fixed penalty to the empty bin.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (build a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If many open bins with lots of mean residual, discourage new bin.
        score += 0.15 * mean_residual;
        score += 2.0 * open_bins_count as f64;
    }

    // Slight preference to fill bins that are already relatively full
    // (tight fit preference beyond raw post_residual).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 10.0 * fill_ratio;

    // Penalize very loose fits (wasting a big bin on a small item).
    if post_residual > 60 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
