    }

    // Late in the stream, consolidate: favor filling existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    } else {
        // New-bin candidate: mild penalty so it's only chosen when fits are terrible.
        score += 5.0 + progress * 10.0;
    }

    // Squared dead-space penalty for very small leftovers (unusable slivers).
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

