    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // Progress-scaled tie-break toward consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (items are >= 1, but small residuals waste capacity). Penalize hard.
    let pr = post_residual as f64;
    if post_residual < 10 {
        score += (10.0 - pr) * 12.0; // dead space penalty
    } else if post_residual < 20 {
        score += (20.0 - pr) * 4.0;
    }

    // Reward tight fits: near-zero post_residual is excellent.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + open_bins_count as f64 * 6.0;
    } else {
        score -= open_bins_count as f64 * 1.5;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward; if post residual is smaller than next item but nonzero, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 20.0;
        } else if pr >= nxt && pr - nxt < 10.0 {
            score -= 10.0;
        } else if pr > 0.0 && pr < nxt {
            score += 8.0;
        }
    }

    // Prefer bins with residual below mean (consolidate emptier space usage).
    score -= (mean_residual - pr) * 0.3;

    // Progress-aware mild tightening as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * (0.15 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 0.9;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Perfect chain bonus: next item fills bin exactly.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space next item can't use (waste unless tiny).
        if next_item_size > post_residual && post_residual > 0 {
            let waste_frac = post_residual as f64 / bin_capacity as f64;
            score += 25.0 * waste_frac;
        }
    }

    // Relative to mean residual: prefer bins deviating appropriately from mean.
    let resid_f = post_residual as f64;
    let mean_dev = resid_f - mean_residual;
    score += 0.15 * mean_dev;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-worse unless current fit is bad.
    if bin_residual == bin_capacity {
        // Fresh bin: score equals leftover space after item; add mild penalty so
        // we only open new bins when open bins leave large dead space.
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can also chain next item
        }
    }

    // Penalize very small dead space that is unusable (0 < post < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Late-stream tightening: as stream progresses, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when existing fits are poor or
        // the item would leave a large unusable gap in an open bin.
        let poor_fit = fit_ratio < 0.55 || post_residual > 35;
        let last_resort = fitting_bins_count == 1 && post_residual > 45;
        if poor_fit || last_resort {
            score -= 18.0;
        } else {
            score += 25.0; // keep using open bins when they fit well
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 4.0; // wasted gap for the known next item
        }
    }

    // Global state coupling: when many bins are open with slack, prefer
    // consolidating into low-residual bins; early stream favors spread.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.08 * (mean_residual - post_residual as f64) * (1.0 - progress);
    score -= 0.05 * progress * (bin_residual as f64 - mean_residual);

    // Slight penalty for proliferating bins late in the stream.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;
    score += 18.0 * norm_post * norm_post * (0.5 + prog_sq);
    score -= 12.0 * norm_post * (1.0 - prog_cu) * (1.0 - norm_post);

    // Reward tight fits more strongly as the stream advances
    let tightness = 1.0 - norm_post;
    score -= 10.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Dead-space penalty: small post_residual that next item cannot use
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap < 0.0 {
            score += 6.0 * (-gap / cap) * (0.5 + prog_sq);
        } else {
            // residual that can host the next item is valuable
            score -= 4.0 * (1.0 - (gap / cap)) * progress;
        }
    }

    // Last-chance bonus: only one fitting bin -> strong incentive to use it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.6 + 0.4 * progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0) * norm_post;
    }

    // Discourage spreading residual when many bins are open with high mean residual
    let mean_norm = mean_residual / cap;
    score += 5.0 * mean_norm * norm_post * progress;

    // Mild preference for larger item consolidation early on
    score -= 3.0 * norm_item * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless it enables a good future fit
    if bin_residual == bin_capacity {
        let future_use = if next_item_size > 0 { (next_item_size as f64 / cap).min(1.0) } else { 0.0 };
        score += 14.0 - 10.0 * future_use * (1.0 - progress) - 6.0 * norm_item;
        score += 3.0 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals in "dead" harmonic classes (hard to fill later)
    let class = (post_residual * 4) / bin_capacity; // 0..=3 integer division class
    score += match class {
        0 => 6.0,   // very small residual -> likely dead space
        1 => 0.0,
        2 => -1.0,
        _ => -3.0,  // large residual still useful
    };

    // Modulo-based fit quality: residuals divisible by common item sizes are reusable
    if post_residual > 0 {
        let mut harmony = 0.0f64;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                harmony += 2.5;
            }
        }
        score -= harmony;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if next item can fit into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space relative to lookahead
        score += 4.0;
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open
        } else if crowded < 0.25 || item_size > 60 {
            score -= 5.0;
        } else {
            score += 15.0; // prefer existing bins when they have room
        }
    }

    // Slight preference to fill emptier bins early (balance load)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Tightness coupling: reward small waste relative to item size
    score -= (item_size as f64) / (1.0 + post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps that few item sizes can use.
    if post_residual >= 10 && post_residual <= 25 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (large item relative to residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= 5.0;
    }

    // Lookahead: favor bins that leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled.
    score *= 1.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chaining: this bin becomes exactly full after next item
        } else if next_item_size < post_residual {
            // next item fits; reward proportionally to how well it fills
            let fill_frac = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill_frac;
        } else {
            // next item does NOT fit in the leftover: penalize dead space
            score += 6.0 + 0.15 * (post_residual as f64);
        }
    } else {
        // last item: strongly prefer minimal leftover
        score -= 10.0;
    }

    // Coupling with mean residual: bins far below mean residual are "wasted" candidates
    // unless the fit is tight; penalize spreading waste across bins.
    let res_f = post_residual as f64;
    if res_f > mean_residual {
        score += 0.25 * (res_f - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - res_f);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit. Penalize new bin unless item is large relative
    // to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bin starts with residual (capacity - item_size); compare vs mean_residual.
        if res_f > mean_residual + 5.0 {
            score += 15.0 + 10.0 * progress; // keep using open bins when they're roomy
        } else {
            score -= 3.0; // open bins are tight; fresh bin is competitive
        }
        // slight preference for new bins early (build flexible pool)
        score -= 2.0 * (1.0 - progress);
    }

    // Mild penalty for leaving very small unusable slivers (< 10% of capacity)
    if res_f > 0.0 && res_f < 0.1 * bin_capacity as f64 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post-residual is good, but near-zero is best).
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that is too small to be useful later (unusable gap).
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 40.0; // creates nearly unusable sliver
        } else {
            // Mild reward for leaving space usable by typical items.
            score -= (gap / bin_capacity as f64) * 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual <= 5 {
            score += 30.0; // unless it creates a dead sliver
        }
    }

    // Lookahead: if next item can fit into post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0;
            // Extra reward if next item exactly fills the remainder.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Penalize placements that leave a gap the next item cannot use.
            score += 6.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins rather than spreading.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score += residual_gap * 0.3; // prefer bins tighter than average
    } else {
        score += residual_gap * 0.1; // slight bonus for roomier bins when below mean
    }

    // Time horizon: early in stream, be more willing to open new bins;
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (fitting_bins_count as f64).min(3.0);

    // New-bin candidate handling: an empty bin gets a moderate default score;
    // only beat it when an open bin offers a genuinely good fit.
    if bin_residual == bin_capacity {
        score = 45.0 - progress * 10.0
            - if next_item_size > 0 && next_item_size >= item_size { 5.0 } else { 0.0 };
    }

    // Penalize opening bins when many are already open with usable space.
    if open_bins_count > 4 && bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let irn = item_size as f64 / cap;

    // Base: quadratic dead-space penalty, modulated by stream progress.
    let mut score = prn * prn * (1.0 + 2.0 * progress) * 100.0;

    // Smooth coupling: reward tight fits more strongly later in the stream.
    score -= (1.0 - prn).powi(3) * (20.0 + 60.0 * progress);

    // Interaction term: post_residual vs item size ratio (non-linear).
    score += prn * irn * (1.0 - prn) * 50.0 * (1.0 - progress);

    // Last-chance bonus: smooth exponential reward when few fitting bins.
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= scarcity * (30.0 + 40.0 * (1.0 - prn));

    // Lookahead: penalize if next item would not fit in post_residual (smooth).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (nx - prn).max(0.0);
        score += gap * gap * 80.0;
        score -= (1.0 - gap).max(0.0) * 25.0;
    }

    // Mean residual divergence: prefer bins close to the mean state (smooth).
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * 10.0;

    // New-bin candidate: penalize opening a new bin, decaying with progress
    // and with how poor fits are among existing bins.
    if bin_residual == bin_capacity {
        let fit_pressure = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 45.0 * (1.0 - 0.5 * progress) * (1.0 - 0.6 * fit_pressure);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that fall into "dead space" harmonic classes:
    // residuals that no plausible item (1..=100) can pair with efficiently.
    // Best fits leave post_residual near 0 or large enough to host a next item.
    if post_residual == 0 {
        score -= 50.0; // perfect fit: strongly reward
    } else {
        // Harmonic penalty: residual in (0, 10] is nearly unusable dead space.
        if post_residual <= 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 30 {
            score += 8.0;
        }
    }

    // Modulo-class logic on post_residual: multiples of common item sizes (10, 20, 25)
    // are "harmonious" residuals likely to be exactly filled by future items.
    let harmonic_bonus = if post_residual % 10 == 0 {
        12.0
    } else if post_residual % 5 == 0 {
        6.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // If the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Reward proportionally to how well next item fits.
            let nxt_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * nxt_fit;
        } else {
            // Next item won't fit here: mild penalty proportional to waste.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it if all open bins would leave very tight/dead residuals.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If stream is early, opening fresh bins is cheaper (more future to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // If mean residual across open bins is small, a new bin is attractive.
        score -= 0.3 * mean_residual;
    }

    // Mild global pressure: prefer tighter bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest item (1..100 range, min item 1)
    // Treat post_residual < 10 as near-dead space (items are typically >= 10 in classic streams, but be safe).
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // dead space penalty
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.6;

    // Prefer bins with residual close to mean (balanced packing) mildly
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Lookahead: if next item fits into the post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0; // blocks the next item
    }

    // New-bin candidate: discourage opening a new bin unless residual would be large and pressure low
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.0 - (bin_capacity as f64 * 0.0);
        // opening a new bin is fine when no open bin fits well
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual relative to item size (non-linear).
    let item = item_size as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += (post * post) / cap; // squared dead-space penalty

    // Reward filling a bin completely (perfect fit bonus).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item also fits in the resulting residual, reward this bin.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 12.0;
        // Extra reward if next item fills the bin almost perfectly afterwards.
        let two_step_waste = post_residual as f64 - next_item_size as f64;
        score -= (cap - two_step_waste.abs()) * 0.05;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving a stranded mid-size residual.
        score += 6.0;
    }

    // Global state coupling: prefer bins below mean residual (keep spread even),
    // but when many bins are open, tighten preference for high-fill bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mean_gap = mean_residual - post;
    score += mean_gap * (0.3 + 0.4 * progress);

    // Early in stream: be more willing to open new bins (exploration);
    // late in stream: strongly prefer existing bins to avoid bin inflation.
    if bin_residual == bin_capacity {
        let exploration = (1.0 - progress) * 8.0 - progress * 15.0;
        score -= exploration + open_bins_count as f64 * 0.5;
        // Never open a new bin for a tiny item when residuals are plentiful.
        if item < 0.25 * cap && mean_residual > 2.0 * item {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let poly = prn * prn * (1.0 + progress) + prn * progress * progress;
    score += 20.0 * poly;

    // Penalize small dead space more aggressively as stream progresses
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (1.0 + 2.0 * progress);
    }

    // Reward tight fits
    score -= item_size as f64 * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: penalize if next item cannot fit in post residual
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += (next_item_size as f64 - pr) * (0.3 + progress);
    }

    // Favor bins below mean residual (more filled bins) with smooth coupling
    score += (mean_residual - bin_residual as f64) * (0.1 + 0.2 * progress);

    // Mild penalty for opening new bins late in stream
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quanta of capacity/8.
    let quantum = bin_capacity / 8;
    let harmonic = post_residual / quantum;

    // Reward small post-residuals (tight fits) with a harmonic discount.
    let tight_bonus = match harmonic {
        0 => 25.0,
        1 => 15.0,
        2 => 8.0,
        3 => 3.0,
        _ => 0.0,
    };
    score -= tight_bonus;

    // Modulo penalty: residuals that are awkward remainders (mod 10) are dead space.
    let rem = post_residual % 10;
    if rem != 0 && rem < 5 {
        score += 6.0 - rem as f64; // tiny remainders 1..4 are hard to fill
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; mildly penalize leaving this residual
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // (would otherwise create a bad fit) or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 35.0 - 10.0 * progress;
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 15.0;
        }
        if post_residual < quantum {
            new_bin_penalty -= 20.0; // perfectly tight new bin
        }
        score += new_bin_penalty.max(0.0);
    }

    // Prefer filling bins with below-average residual (balance consolidation).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps below typical item floor).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium gaps (10..20) are semi-dead: moderate penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }
    // Reward exact fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot use the gap and gap is small, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 25 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer tighter bins.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += pressure * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual close to mean residual (keeps balance, avoids fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when item is large relative to capacity
    // and no good fit exists; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.7 && (fitting_bins_count == 1 || post_residual < 15) {
            score -= 10.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post_residual as f64 - next).abs();
            // Exact or near-exact match for the next item is highly desirable
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect chain: post_residual == next_item_size
            if post_residual == next_item_size {
                score -= 80.0;
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally
            score += 25.0 * ((next - post_residual as f64) / bin_capacity as f64);
        }
    }

    // Compare against mean residual: avoid bins far from the average state
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // Late in the stream, consolidation matters more: penalize leaving large residuals
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.5;

    // Many open bins: discourage spreading, favor filling existing ones
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 2.0;
    }

    // New-bin candidate: only attractive when current bin would leave a big dead gap
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized unless it gives a perfect fit for item + next
        score += 90.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 85.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize leaving dead space that no future small item could use well.
    if post_residual > 0 {
        let waste = (post_residual as f64).ln();
        score += 6.0 * waste;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for blocking.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (reduce bin spread).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Global state coupling: if mean residual is high, discourage adding to scattered space.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 20.0 * progress;
        if post_residual > 0 && fitting_bins_count == 0 {
            score -= 10.0; // no alternative exists
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for very small post residuals that create near-useless slivers
    // unless a known next item uses them.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.35 * progress * x) + 12.0 * x * x * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 20.0 * progress);

    // Lookahead: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let fit_q = 1.0 - (pr - n) / cap;
            score -= 6.0 * fit_q * fit_q * (0.4 + 0.6 * progress);
        } else {
            let gap = (n - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x) * (1.0 + progress);
    }

    // Many open bins: penalize spreading residual thin
    let ob = open_bins_count as f64;
    score += 0.4 * (ob.ln() + 1.0) * x * x;

    // Mean residual deviation: prefer bins near mean (balance preservation)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (0.5 + 0.5 * progress);

    // New-bin candidate: smooth penalty tuned by progress and mean residual
    if bin_residual == bin_capacity {
        score = cap + 25.0 * (1.0 - progress) + 0.5 * mean_residual;
        if fitting_bins_count <= 1 && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes (integer division thresholds)
    let item_class = item_size / 20;               // 0..4 (0=tiny,4=huge)
    let post_class = post_residual / 10;           // dead-space class of leftover

    // Reward tight fits: small post_residual is good.
    score -= (cap - post_residual as f64) * 0.05;  // fuller bin => lower score

    // Penalize dead space quadratically, especially in "awkward" classes.
    // Residuals in (0, 10) are nearly unusable (items >= 10 typically, but sizes 1..100 allowed).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus (post_residual == 0)
    if post_residual == 0 {
        score -= 50.0;
    }

    // Modulo arithmetic on post_residual vs common item sizes: harmonic compatibility.
    // If leftover residue is congruent to typical small item sizes, it's reusable.
    let reusable = (post_residual % 25 == 0)
        || (post_residual % 20 == 0)
        || (post_residual % 10 == 0 && post_residual >= 10);
    if reusable {
        score -= 10.0;
    } else if post_residual > 0 {
        score += (post_residual % 10) as f64 * 0.5; // ragged remainder penalty
    }

    // Lookahead: does next item fit into post_residual? If yes, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward if next item exactly fills the remaining space (chain of perfect fits)
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here: leftover is likely dead space; penalize proportionally.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it moderately
    // attractive only when current bins would leave bad residue or item is huge.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac > 0.8 {
            score -= 40.0; // huge items deserve a fresh bin
        } else if frac < 0.3 && mean_residual > item_size as f64 * 1.5 {
            score += 20.0; // small items should use existing space
        } else {
            score += 10.0; // default: prefer existing bins slightly
        }
    }

    // Stream progression: late in stream, consolidate harder (avoid opening bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a good
    // "garbage collector" for the item; nudge score accordingly.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.02;

    // Huge item class: prefer bins where it fits snugly (post_residual small).
    if item_class >= 3 {
        score += (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are ideal: reward post_residual near 0 superlinearly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Strict dead-space avoidance: small unusable gaps (< 10) are worse
        // than proportionally larger gaps, so penalize the small-gap zone hard.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 6.0;
        }
        // Penalize residual that cannot fit a typical future item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Perfect reuse of a nearly-full bin: bonus proportional to fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more costly.
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + ob * 3.0;
        // But if no existing bin fits well, allow opening: relax when the
        // only fitting bin would leave a big dead gap.
        if fitting_bins_count <= 1 && post_residual as f64 > 0.0 {
            let worst_gap = bin_residual as f64 - item_size as f64 - post_residual as f64;
            let _ = worst_gap;
            score -= 20.0 + ob * 2.5;
        }
    } else {
        // Existing bin: reward using it, more so when bins are plentiful.
        score -= 5.0 + ob * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 4.0;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening bins (fewer chances to amortize).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) — already the base term.

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post residual, strongly reward this bin.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next == post {
            score -= 60.0;
        } else if next <= post {
            // Next item fits here: reward proportionally to how well it fills.
            score -= 25.0 * (next / post);
        } else {
            // Next item does NOT fit into this bin's residual: penalize
            // placements that leave residual just barely below the next item
            // (wasted near-miss space), scaled by how close the miss is.
            let miss = (next - post) / next;
            if miss < 0.25 {
                score += 20.0 * (1.0 - miss / 0.25);
            }
        }
    }

    // Penalize leaving residual that is likely dead space: small residuals
    // below the minimum plausible item size (relative to capacity).
    let min_item = (bin_capacity / 10).max(1) as f64;
    let post = post_residual as f64;
    if post > 0.0 && post < min_item {
        score += 15.0 * (1.0 - post / min_item);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins fit
    // poorly (post_residual high relative to mean residual) or it's the last
    // chance bin situation for future items.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 30.0;
        // But if all open bins would leave large residuals, opening a fresh
        // bin becomes attractive: subtract based on mean residual tightness.
        let tight = mean_residual / bin_capacity as f64;
        if tight < 0.30 {
            score -= 55.0 * (1.0 - tight / 0.30);
        }
        // Early in the stream, prefer opening bins (more future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference for bins with below-average residual (consolidation),
    // keeping large-residual bins available for future large items.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild penalty per open bin to discourage bin sprawl.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size is worthless.
    let dead = if post_residual > 0 && post_residual < 10 { (10 - post_residual) as f64 * 1.5 } else { 0.0 };
    score += dead;

    // Slight preference for fuller bins (larger item_size relative to residual).
    score -= (item_size as f64 / bin_capacity as f64) * 6.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Many open bins with large mean residual: discourage spreading into
    // already-loose bins; encourage consolidating.
    if open_bins_count > 3 && mean_residual > 40.0 {
        score += (mean_residual - 40.0) * 0.15;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (favor balance); late, consolidate aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward late consolidation pressure.
        score += 8.0 * (1.0 - t) - 6.0 * t;
        // If no open bin fits well, opening new bin is fine.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        score -= 2.0 * t;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr;

    // Reward tight fits, scaled smoothly by stream progress
    score -= 30.0 * fit * fit * (0.5 + 0.5 * progress);

    // Non-linear polynomial coupling: residual squared penalty grows with progress
    score += 20.0 * norm_pr * norm_pr * (1.0 + progress);

    // Cubic interaction of progress with normalized residual
    score += 15.0 * norm_pr * norm_pr * norm_pr * progress;

    // Dead-space penalty: small post-residual that next item cannot use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 12.0 * (1.0 - pr / nx) * (1.0 + progress);
        } else {
            score -= 8.0 * (nx / pr.max(1.0)) * (1.0 - progress);
        }
    } else {
        // last item: prefer fullest packing
        score -= 10.0 * fit;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Prefer bins below mean residual when many bins open
    score += 5.0 * ((pr as f64) - mean_residual) / cap * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: only attractive late or when fit is terrible
    if bin_residual == bin_capacity {
        let open_penalty = 6.0 * (open_bins_count as f64).ln();
        score = pr + open_penalty + 40.0 * (1.0 - progress) + 60.0 * fit * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors
    // classify "usable" leftovers. Residues divisible by 5 or 10 pair
    // well with typical item sizes, so reward them.
    let r = post_residual;
    if r > 0 {
        let mod10 = (r % 10) as f64;
        let mod5 = (r % 5) as f64;
        score += mod10 * 0.6 + mod5 * 0.4; // penalize awkward residues
        // Integer-division classes: leftovers in [1..10] are dead space
        let class = r / 10; // 0 => dead, 1..=10 => usable tiers
        score -= class as f64 * 2.0;
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Large post_residual means wasteful placement; mildly penalize
    score += (r as f64).powi(2) * 0.004;

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= r {
        let slack = (r - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
        if slack == 0.0 {
            score -= 30.0; // exact pair fit
        }
    } else if next_item_size > r && r > 0 {
        // next item won't fit here; penalize small leftovers a bit more
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin starts with base score
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when few bins fit the item
        // or mean residual is low (existing bins are nearly full).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0
            + (fitting_bins_count as f64) * 3.0
            - mean_residual * 0.15
            - progress * 10.0;
        // Never prefer a fresh bin if the item fits with small leftover elsewhere
        if r < bin_capacity && r < 15 {
            score += 100.0;
        }
    }

    // Slight preference for bins tighter than the mean residual
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect or near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Penalize large leftover space (wasteful use of a big bin) mildly.
    score += (post_residual as f64) * 0.05;

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 2.0;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits, small penalty to discourage near misses.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Compare against mean residual: bins already tighter than average are good targets.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New bin candidate: only attractive when current bin would leave bad dead space
    // or open bins are few; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        if post_residual >= 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in post_residual,
    // this is a chain-perfect placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 150.0;
        } else if next_item_size > post_residual {
            // Next item cannot follow here; penalize leaving a gap that wastes space
            // relative to what the next item would need.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Penalize creating dead space that no small item (min size 1) can still use poorly.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny slivers are hard to fill
    }

    // Relative-to-mean coupling: prefer bins whose residual is already tight vs. average.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive early in the stream or when all open bins fit badly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_penalty = if next_item_size > 0 && next_item_size <= bin_capacity {
            0.0
        } else { 0.0 };
        score = 120.0 + 100.0 * progress + fit_penalty;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, new bin is fine
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 5 {
            score -= 120.0; // fresh bin chains nicely with next item
        }
    }

    // Slight preference to fill larger residuals when many bins are open (bin consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize unusable dead space: residuals too small for typical items.
    if post_residual < 10 {
        score -= 8.0; // perfect fill is great
    } else if post_residual < 20 {
        score += 3.0;
    } else if post_residual < 40 {
        score += 6.0 * (1.0 - fit_ratio);
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 10.0 + 5.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to leftover waste.
        score += 2.0;
    }

    // Time horizon: early in the stream, be more conservative (favor new bins
    // to create flexibility); late in stream, consolidate into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: cheaper early, expensive late.
        score += 20.0 * (1.0 - progress) - 5.0 * progress;
        // Prefer new bin if open bins are all nearly full on average.
        score -= 4.0 * (mean_residual / bin_capacity as f64);
    } else {
        // Existing bin: reward more as stream progresses.
        score -= 6.0 * progress;
    }

    // Many open bins: encourage consolidation.
    score += 0.8 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Deviation from mean residual: prefer bins with less residual than average
    // (fill the emptier-feeling bins first when they fit well).
    score += 0.05 * (bin_residual as f64 - mean_residual) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear coupling: quadratic dead-space penalty grows with stream progress.
    let norm_pr = pr / cap;
    score += (norm_pr * norm_pr) * (100.0 + 200.0 * progress);

    // Reward tight fits (small post_residual) with smooth saturating term.
    score -= 20.0 * (1.0 - (norm_pr * 3.0).tanh());

    // Penalize opening a new bin (residual == capacity) increasingly as stream progresses.
    if bin_residual == bin_capacity {
        score += 60.0 + 120.0 * progress;
    } else {
        // Reward reusing existing bins, stronger when few fitting bins remain.
        score -= 15.0 + 10.0 * (1.0 / fitting_bins_count.max(1) as f64);
    }

    // Lookahead: if next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot fit here: penalize leaving residual that is too small to matter.
        score += 10.0 * (1.0 - pr / cap);
    }

    // Mild coupling with mean residual: prefer bins below mean (tighter bins) early, relax later.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that stay "usable"
    // (multiples of common size classes 10/20/25/50 are reusable later).
    let usable = |r: u32| {
        if r == 0 { 3.0 }
        else if r % 10 == 0 && r % 50 != 0 && r % 25 != 0 { 2.0 }
        else if r % 25 == 0 || r % 20 == 0 { 1.5 }
        else if r % 10 == 0 { 1.0 }
        else { 0.0 }
    };
    score -= 6.0 * usable(post_residual);

    // Integer-division thresholds: dead space penalty grows in quanta of 10.
    let dead_quanta = post_residual / 10;
    if post_residual > 0 && post_residual % 10 != 0 {
        score += 2.0 + dead_quanta as f64 * 0.5;
    }
    // Very small dead space (< 10) is nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: harmonic match between post_residual and next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward, scaled by how "clean" the fit is
            let slack = post_residual - next_item_size;
            score -= 5.0;
            if slack % 10 == 0 { score -= 3.0; }
            if slack == 0 { score -= 4.0; }
        } else {
            // next item won't fit: penalize residuals that trap the stream
            let gap = next_item_size - post_residual;
            score += (gap as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        let avg_open_fit = mean_residual;
        if avg_open_fit < item_size as f64 + 5.0 {
            score -= 10.0; // open bins are nearly full -> fresh bin is good
        } else {
            score += 8.0; // keep packing existing bins
        }
        score += open_bins_count as f64 * 0.3;
    }

    // Tight fits (small post_residual relative to item) are ideal.
    let tightness = post_residual as f64 / (bin_capacity as f64);
    score += tightness * 4.0;

    // Early stream: be slightly conservative, keep residuals flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 2.0 * (1.0 - usable(post_residual) / 3.0);
    }

    // Prefer bins whose residual is far below mean (consolidate emptier space).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space avoidance: small unusable gaps (1..10) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Post-residual that can still fit the lookahead item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 1.5 + 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last chance: only this bin fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or
    // the fit here would leave a large unusable remainder.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) - (item_size as f64);
        if open_bins_count == 0 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if mean_residual < (item_size as f64) + 5.0 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Prefer bins tighter than the mean (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Exact match: next item fills this bin perfectly -> strongly favored.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits: reward closeness of fit.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted near-capacity residual unless tiny.
            score += 8.0 * (1.0 - post / bin_capacity as f64);
        }
        // If next item fits EXACTLY into current residual (before placement), this is
        // a two-item perfect fill: extremely desirable.
        if bin_residual == next_item_size && post_residual > 0 {
            score += 15.0; // placing current item would destroy a perfect next fit
        }
    } else {
        // Last item: prefer minimal leftover.
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean-residual coupling: prefer bins tighter (smaller residual) than average.
    let resid = bin_residual as f64;
    score += 0.3 * (resid - mean_residual);

    // Reward high fill ratio (small post-residual relative to capacity).
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (item_size as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64;
        score -= 30.0 - 0.25 * waste;
    }

    // Penalize opening a new bin when decent open bins exist and stream is progressing.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let decent_open = (fitting_bins_count > 0) as f64;
        score += 10.0 + 15.0 * decent_open * (1.0 - progress * 0.5);
        // Opening a fresh bin is fine if item is large and fit elsewhere would be awful.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 12.0;
        }
    }

    // Slight penalty for creating very small unusable slivers (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space, amplified early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste * waste * (1.6 - progress);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / 100.0);
    }
    // Penalize leaving a sliver the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 3.0 * (post_residual as f64 / 100.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a bin is expensive; make it attractive
    // only when the item is large (little waste anyway) or fits are scarce.
    if bin_residual == bin_capacity {
        let open_cost = 8.0 + 0.15 * open_bins_count as f64;
        let scarcity = if fitting_bins_count == 0 { 14.0 } else { 0.0 };
        let large_item_pull = (item_size as f64 / 100.0) * 10.0;
        score += open_cost - scarcity - large_item_pull;
        // Late in the stream, waste in fresh bins matters less.
        score -= 6.0 * progress;
    }

    // Mild preference for bins below mean residual (balance fragmentation).
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, penalize residual more aggressively
    score += 20.0 * norm_pr * progress * progress;

    // Interaction with mean residual: if this bin's residual is far above mean, slight penalty
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a new bin early or when post-residual would be large
    if bin_residual == bin_capacity {
        score = pr + 25.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size as f64 <= pr {
        // Reward bins that can also accommodate the lookahead item (smooth decay)
        let ratio = next_item_size as f64 / pr;
        score -= 15.0 * (1.0 - ratio) * (1.0 - ratio);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).sqrt() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    // Small post_residual = tight, efficient fit -> reward (subtract).
    let frac = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    } else if post_residual <= 50 {
        score += 5.0;
    } else {
        score += 15.0; // large dead space
    }

    // Lookahead: does next item fit in the post-residual? Reward if yes.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 10.0 + (slack_after_next as f64).min(15.0) * 0.4;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins -> prefer consolidating into existing bins over new bins.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Mean residual coupling: if this bin is far below mean residual,
    // using it reduces fragmentation variance.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // New-bin candidate: penalize mildly so we only open when existing bins are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 0.5;
        // But late in stream with large next item, opening may be fine.
        if next_item_size >= 50 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Modulo harmonic: residual in "good" residue classes (multiples of 10)
    // are more reusable by typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space avoidance: penalize small unusable gaps (1..=9) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Gaps that could still fit a typical small item are less harmful.
    if post_residual >= 10 && post_residual <= 20 {
        score += 5.0; // mild penalty: mediocre leftover
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, but discount the penalty
    // when the current item is large relative to residual (poor fits elsewhere)
    // or when lookahead suggests a big next item that would prefer fresh space.
    if bin_residual == bin_capacity {
        score += 30.0;
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.6;
        if tight_fit {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size > bin_residual {
            // next item won't fit here anyway; fresh bin may be fine
            score -= 10.0;
        }
        // pressure: many open bins already -> discourage more bins
        score += open_bins_count as f64 * 2.0;
    } else {
        // Mild pressure against stuffing many bins: prefer compacting when
        // residuals are large (high fragmentation risk otherwise).
        if (mean_residual - bin_residual as f64).abs() < 5.0 && post_residual >= 10 {
            score -= 8.0; // aligning with mean residual keeps bins balanced
        }
    }

    // Lookahead: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0; // bin remains usable for the next item
    }

    // Late in stream: be more conservative, avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space that next item cannot use
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals far below mean (wasting space relative to fleet average)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 25.0 + 0.2 * mean_residual;
    }

    // Late stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual more when the item is large relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Penalize dead space: small post_residual is good, but post_residual below next item's
    // requirement is wasted if lookahead item can't use it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: reward chain potential.
            score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // Dead space that the next item cannot use.
            score += 5.0 + 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 60.0 - 30.0 * fit_ratio;
        // Early in the stream, opening new bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
    }

    // Global state coupling: when open bins have large mean residual, prefer spreading load
    // into existing bins rather than fragmenting.
    score += 0.05 * mean_residual * (open_bins_count as f64).sqrt() * 0.1;

    // Mild preference for bins whose residual is close to item size (best-fit style).
    let diff = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post_residual (tight packing), normalized.
    let mut score = post / cap;

    // Non-linear polynomial coupling: quadratic+quartic shaping of post_residual
    // modulated by stream progress. Early on, tolerate slack; later, penalize it strongly.
    let x = post / cap; // in [0,1]
    let poly = x * x * (1.0 - x) * (1.0 - x); // peaks at moderate waste
    score += 2.5 * poly * (1.0 - progress) - 1.2 * poly * progress;

    // Cubic waste penalty that grows with progress: dead space is costly late in the stream.
    score += 3.0 * x.powi(3) * (0.5 + progress);

    // Lookahead coupling: reward residual that can host the next item (smooth kernel),
    // penalize residuals that strand the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = x - nx;
        // smooth bump when post_residual >= next_item_size
        let fits_next = 1.0 / (1.0 + (-8.0 * diff).exp());
        score -= 1.5 * fits_next;
        // penalize near-miss residuals (just below next item size) — dead space
        let near_miss = (-diff / (0.05 + nx)).exp();
        score += 1.8 * near_miss * (1.0 - fits_next) * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (unless waste would be enormous).
    if fitting_bins_count <= 1 {
        score -= 1.0 + 0.8 * progress - 1.5 * x * x;
    }

    // Crowd penalty: many open bins with low mean residual -> prefer consolidation.
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    let mean_norm = mean_residual / cap;
    score += 0.6 * crowd * (1.0 - mean_norm);

    // Empty new-bin candidate: allow opening fresh bins early or when item is large
    // and would leave awkward residual in existing bins.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let item_frac = item_size as f64 / cap;
        // new bin attractive when progress low or item big relative to typical residual
        let awkward = (x - item_frac).abs(); // == item_frac for new bin
        score -= 0.9 * (1.0 - progress) * (1.0 - awkward);
        score -= 0.4 * item_frac * (1.0 - item_frac) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead-space quality classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Quotient class: how many "small item slots" (size <= 10) fit in the leftover
    let slots = post_residual / 10;
    // Modulo classes on post_residual relative to capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Penalize residuals that fall into awkward modulo classes (not multiples of 10)
    if post_residual % 10 != 0 {
        score += 6.0;
    }
    // Reward residuals that are multiples of common item-size harmonics
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Big leftover chunks are fine; tiny unusable chunks are dead space
    if pr > 0.0 && pr < 10.0 {
        score += 40.0;
    }
    // Medium-dead zone: too small for typical mid items, too big to ignore
    if post_residual >= 10 && post_residual < quarter {
        score += 12.0;
    }
    // Residual in [quarter, half) is a healthy working zone
    if post_residual >= quarter && post_residual < half {
        score -= 2.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward proportional to how snugly next item fits
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 15.0 * snug;
            // harmonic bonus if next item divides residual cleanly
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-good only when
    // current open bins are fragmented or item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - pr).abs();
        // prefer new bin when open bins are already fragmented or item huge
        if item_size > half {
            score -= 10.0 + 20.0 * progress;
        }
        if open_bins_count > 0 && mean_residual < (item_size as f64) {
            score -= 25.0; // no open bin really usable
        }
        if fragmentation < 5.0 && open_bins_count > 0 && item_size <= half {
            score += 30.0; // existing bins are healthy, discourage new bin
        }
    } else {
        // Slight preference for tighter existing bins (smaller residual before placement)
        score += 0.1 * (bin_residual as f64 - item_size as f64).max(0.0) / cap;
        // Encourage packing into bins when many bins can fit (reduce bin count pressure)
        if fitting_bins_count > 2 {
            score += 3.0;
        }
    }

    // Slot-count harmonic: residual that hosts many future small items is valuable
    score -= 1.5 * slots as f64;

    // Mild stream-progress adaptation: tighten standards as stream advances
    score *= 1.0 + 0.1 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // dead space that likely can never be reused
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // blocks the next item into a new bin
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: fewer open bins is better; discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
    } else {
        score += 2.0 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably (tighter than average) to consolidate packing.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight phase pressure: as the stream progresses, prefer tightening fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-step chain: excellent
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover slack after hypothetical next placement
            score += slack * 0.35;
            if slack <= 10.0 {
                score -= 25.0; // near-perfect chain
            }
        } else {
            // next item cannot fit here; residual is dead space
            score += 12.0;
        }
    } else {
        // last item: minimize post residual aggressively
        score += post_residual as f64 * 0.2;
    }

    // Reward tight fits relative to current residual
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 18.0;

    // Penalize bins with residuals far below mean (fragmented bins)
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.15;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.05;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: prefer keeping it closed early, allow late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress) - 10.0 * progress;
        // never open a new bin if an exact lookahead chain exists elsewhere
        if next_item_size > 0 && post_residual == next_item_size {
            score += 100.0;
        }
    }

    // Mild penalty for proliferation of open bins
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: post_residual near zero is ideal.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * (1.0 - tightness * tightness);

    // Penalize small unusable residuals (dead space): residuals too small
    // for typical items (1..100 unknown distribution) are wasted.
    if post_residual > 0 && post_residual < item_size.min(40) {
        score += 12.0 * (1.0 - post_residual as f64 / 40.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 0.2 * (bin_residual - item_size) as f64;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.25 * next_item_size as f64;
        } else if post_residual > 0 {
            // Post-residual too small for next item: mild penalty for
            // stranding space that lookahead cannot use.
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Prefer bins below the mean residual (conserves large-capacity bins
    // for larger future items).
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += 0.08 * (residual_f - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - residual_f);
    }

    // Time horizon: early in the stream, be conservative with new bins
    // (penalize opening new bins); late, allow more freedom.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: open only when many bins already exist or
        // stream is far along, or when current bins are nearly full.
        score += 25.0 - 20.0 * progress - 0.5 * open_bins_count as f64;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 10.0; // existing bins are cramped; new bin is fine
        }
    } else {
        // Reward using existing bins more when few bins are open.
        score -= 0.3 * open_bins_count as f64;
    }

    // Mild diversity coupling: filling a bin whose residual is close to
    // the item size is doubly good (compound tightness).
    let gap = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: reward tight fits (low post residual) via smooth polynomial
    let mut score = 2.0 * x * x * x - 1.5 * x * x + 0.5 * x + 0.9 * x;

    // Non-linear coupling: tight fits matter more as stream progresses
    let coupling = x * x * (1.0 - progress) * (0.5 + 0.5 * progress);
    score += 3.0 * coupling;

    // Lookahead: penalize leaving residual that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 1.2 * fit_quality * fit_quality * (1.0 - progress);
        } else {
            score += 0.8 * (nx / cap) * (1.0 - x);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.5 + 0.5 * progress;
    } else if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Penalize bins far from mean residual (avoid fragmentation)
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // Mild penalty for opening new bins when many are open and residual wasted
    if bin_residual == bin_capacity {
        score += 1.0 + 0.6 * (1.0 - progress) + 0.02 * open_bins_count as f64;
        // But allow new bin if item is large relative to capacity
        score -= 1.5 * (item_size as f64 / cap) * progress;
    }

    // Reward filling bins deeply as stream ends
    score -= 0.4 * progress * (1.0 - x) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small integers
    let pr = post_residual;
    let mod4 = (pr % 4) as f64;
    let mod8 = (pr % 8) as f64;
    let mod16 = (pr % 16) as f64;

    // Reward post-residuals in "usable" harmonic classes (multiples of common sizes)
    score -= 6.0 * (1.0 - mod4 / 3.0);
    score -= 3.0 * (1.0 - mod8 / 7.0);
    score -= 1.5 * (1.0 - mod16 / 15.0);

    // Integer-division thresholds: dead-space bands
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver
    } else if pr < 20 {
        score += 10.0;
    } else if pr <= 30 {
        score -= 5.0; // sweet spot for medium items
    }

    // Fraction of capacity remaining, non-linear coupling
    let frac = pr as f64 / cap;
    score -= 12.0 * frac * frac;

    // Lookahead: does post_residual fit the next item exactly / well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect follow-up
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            let nmod = (pr % next_item_size.max(1)) as f64;
            score -= 4.0 * (1.0 - nmod / next_item_size.max(1) as f64);
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when remaining open bins are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual / cap;
        if tight < 0.25 || open_bins_count == 0 {
            score -= 8.0 + 10.0 * (1.0 - tight);
        } else {
            score += 20.0 + 30.0 * progress;
        }
    }

    // Prefer filling bins below mean residual (tighter bins first)
    score -= 2.0 * (mean_residual - bin_residual as f64).max(0.0) / cap;

    // Mild exploration via harmonic phase of step index
    let phase = (step_index % 7) as f64;
    score -= 0.5 * (phase / 6.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    }

    // Reward leaving room for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap too small for next item: likely dead space
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize bins whose residual deviates badly from mean,
    // encouraging consolidation into already-strained bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Slight preference for filling the fullest bin when many bins are open.
    score -= 0.03 * (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64;

    // New-bin candidate: only attractive when item fits poorly everywhere
    // (large item, fresh bin gives full residual). Make empty-bin score neutral-high
    // unless item is big relative to capacity.
    if bin_residual == bin_capacity {
        score = 55.0 - 0.4 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if post_residual < 10 && post_residual > 0 {
            score += 40.0 * (10 - post_residual) as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect-fit bonus: post_residual of 0 or 1 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 35.0;
    }

    // 2-step lookahead: if the next item can fit into post_residual, this placement
    // is excellent (chains two items into one bin).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize dead space that blocks the lookahead item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(40.0);
        }
    }

    // Compare against mean residual: bins tighter than the mean are better targets.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 8.0 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 6.0 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening new bins is less costly (fewer future chances to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 12.0 * progress;
        // If next item is large, a fresh bin may serve it better.
        if next_item_size > item_size {
            score -= 10.0;
        }
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (perfect fits).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 2.5 * (1.0 - fit_ratio).powi(6) * (item_size as f64);

    // Dead-space penalty: residuals too small to ever hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
        // Reward residual exactly matching the next item (chain packing).
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item in stream: minimize waste aggressively.
        score += 0.5 * post_residual as f64;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Prefer using fewer open bins early; late in the stream, spread less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin, but less when the item
    // fits poorly in all existing bins or the stream is young.
    if bin_residual == bin_capacity {
        let poor_fit = (fitting_bins_count == 0) as i32;
        let big_next = (next_item_size >= 60) as i32;
        score += 30.0 - 20.0 * poor_fit as f64 - 5.0 * big_next as f64 - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = (1.0 - norm_post).powi(2) * (0.5 + progress)
        - norm_post * norm_post * (1.0 - progress);
    score += 25.0 * poly;

    // Penalize large dead space late in the stream, reward tight fits
    score += 10.0 * norm_post * norm_post * (1.0 + progress * 3.0);

    // Reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (norm_post - norm_next).abs();
        score -= 8.0 * (1.0 - gap.min(1.0)) * (1.0 - progress * 0.5);
    }

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_item * norm_item);
    }

    // Mild preference against spreading across many open bins
    score += (open_bins_count as f64).ln() * 2.0 * norm_post;

    // New-bin candidate: prefer it when item is large or stream is early
    if bin_residual == bin_capacity {
        score -= 12.0 * norm_item * (1.0 - progress) + 5.0 * (norm_item - 0.5).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1 fraction of capacity left

    // Dead-space penalty: residuals too small to fit typical small items (<=10)
    // are wasted. Penalize residuals below 10 heavily (unusable), reward clean fits.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 40.0; // unusable dead space
    } else {
        // Harmonic class bonus: residuals that are multiples of common item sizes
        // (10, 20, 25, 50) are more likely to be filled by future items.
        let pr = post_residual;
        let harmonic_bonus: f64 = if pr % 50 == 0 {
            25.0
        } else if pr % 25 == 0 {
            18.0
        } else if pr % 20 == 0 {
            14.0
        } else if pr % 10 == 0 {
            10.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Penalize very large leftover fractions mildly relative to mean residual:
        // spreading items across bins vs. compacting. If this bin's post residual
        // is far above the mean residual, it's a "loose" bin; deprioritize slightly.
        let diff = frac * cap - mean_residual;
        score += 0.15 * diff;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this is a great chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // next item still fits: mild reward proportional to tightness
            score -= 8.0;
        } else {
            // next item won't fit here: if post_residual is small (< next_item)
            // and unusable otherwise, slight penalty unless near zero
            if post_residual > 0 && post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Make the empty bin moderately expensive.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decreasing as stream progresses
        // (fewer future items to fill it) and with many open bins already.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.9 - 20.0 * progress + 2.0 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= (item_size as f64 / cap) * 30.0;
    }

    // Small penalty for very tight fits that leave awkward mid-range residuals
    // (e.g. post_residual in 11..19 is awkward for many distributions).
    if (11..20).contains(&post_residual) {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let min_useful = 10.0f64.min(bin_capacity as f64);
    if (post_residual as f64) < min_useful {
        score += 60.0 + (min_useful - post_residual as f64) * 8.0;
    } else {
        // Perfect or near-perfect fits are strongly rewarded.
        if post_residual == 0 {
            score -= 100.0;
        } else if post_residual <= 5 {
            score -= 40.0;
        }
    }

    // Tightness bonus: reward filling a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Dead-space shaping: moderate residuals that could pair with common
    // mid-size items are mildly penalized to prefer exact couplings.
    if post_residual >= 1 && post_residual <= 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Open-bin pressure: discourage scattering across many open bins.
    let pressure = (open_bins_count as f64 / 10.0).min(3.0);
    score += pressure * 4.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make the empty bin attractive only when
    // no open bin offers a good fit, and early in the stream or when mean
    // residual across open bins is small (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Base cost of a fresh bin; cheaper early, costlier later.
        score = 55.0 + progress * 30.0;
        // If open bins are fragmented (low mean residual), new bin is fine.
        score -= (1.0 - fragmentation) * 10.0;
        // If the next item is large and would not fit typical leftovers,
        // opening fresh space now is reasonable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 12.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere.
        if post_residual == 0 && bin_residual != bin_capacity {
            score += 1000.0;
        }
    } else {
        // Prefer using existing bins over the fresh-bin baseline when the
        // resulting residual is still usable.
        if post_residual >= min_useful {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item exactly matches the post residual,
    // reward leaving that gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Gap the next item cannot use: mild penalty.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // 2-step lookahead: if the next item exactly fills post_residual, strongly reward.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let next = next_item_size as f64;
        if next == post {
            score -= 40.0;
        } else if next < post {
            // Reward if next item fits well into post_residual (tight-ish).
            let fill = next / post;
            score -= 25.0 * fill * fill;
            // Penalize leaving a large awkward gap the next item barely fits into.
            if post - next <= 5.0 && post - next > 0.0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot fit: post_residual becomes dead space unless small.
            if post < 10.0 {
                score -= 5.0; // tiny dead space is fine
            } else {
                score += 0.5 * (post - 10.0); // penalize unusable space
            }
        }
    }

    // Relative to mean residual: prefer bins that are already more filled than average.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate: penalize opening a new bin unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if this item is large relative to capacity, opening fresh is less bad.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If next item is huge, a fresh bin may serve it well.
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize (subtract) when the item nearly fills the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact or near-exact fill is gold.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead-space penalty: leftover space too small for typical items.
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    } else if fitting_bins_count > 2 {
        // Plenty of alternatives; slight penalty to keep good bins open.
        score += 2.5 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // Lookahead coupling: if next item can fit into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0;
            // Bonus if next item fills even tighter after placement.
            let next_post = post_residual - next_item_size;
            score -= 10.0 * (1.0 - (next_post as f64) / (bin_capacity as f64));
        } else if next_item_size <= bin_residual {
            // Next item fits this bin only before current placement -> mild penalty.
            score += 6.0;
        }
        // If next item is huge, prefer spreading load: favor bins with more residual.
        if next_item_size >= 60 {
            score += 0.15 * post_residual as f64;
        }
    }

    // New-bin candidate logic: empty bin should win only when current fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 8.0;
        // In early stream, opening bins is cheap (build a pool).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If item fits poorly anywhere (large post_residual), new bin is attractive.
        score -= 0.12 * post_residual as f64;
        // Late stream: opening bins is expensive.
        score += 14.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer reusing.
    if open_bins_count > 3 && mean_residual > 0.0 {
        let waste = (mean_residual - post_residual as f64).abs();
        score += 0.05 * waste;
        score += 0.3 * (open_bins_count as f64).ln();
    }

    // Prefer bins whose residual is close to the item (minimal fragmentation).
    score += 0.08 * ((bin_residual - item_size) as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = item_size as f64 / bin_capacity as f64;
    let post_norm = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: subtract a non-linear bonus that grows as post_residual shrinks
    let tightness = (1.0 - post_norm).powi(3);
    score -= 30.0 * tightness * (1.0 + progress);

    // Penalize dead space quadratically, amplified by stream progress
    score += (post_norm * post_norm) * 20.0 * (0.5 + progress);

    // Penalize leaving a residual that no plausible future item could use well
    // (residual too small to be useful): smooth bump around small-but-nonzero residuals
    let small_gap = (post_norm.max(0.0) * (1.0 - post_norm.max(0.0) * 4.0)).max(0.0);
    score += 15.0 * small_gap;

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        let next_fits = (post_residual >= next_item_size) as i32 as f64;
        let chain_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64).abs();
        score -= 12.0 * next_fits * chain_quality.max(0.0);
        // Penalize if next item cannot fit (wasted lookahead opportunity)
        score += 6.0 * (1.0 - next_fits) * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * open_pressure * post_norm;

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // New-bin candidate (empty bin): make it unattractive unless nothing else works
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * (1.0 - progress);
        // Exception: very large items may warrant a fresh bin
        if fit > 0.7 {
            score -= 70.0;
        }
    }

    // Smooth non-linear coupling of progress with fit quality
    score -= 10.0 * (fit * fit) * progress * (1.0 - post_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    let class = post_residual % 10;
    // Dead space classes: tiny leftovers (1..=5) are nearly unusable -> heavy penalty
    if post_residual > 0 && post_residual <= 5 {
        score += 40.0;
    } else if post_residual >= 6 && post_residual <= 9 {
        score += 8.0;
    } else if class == 0 && post_residual > 0 {
        // Round residue classes are reusable by many item sizes -> reward
        score -= 6.0;
    }

    // Integer-division thresholds on post_residual
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 5.0; // bin nearly full, fine but low flexibility
    } else if post_residual > bin_capacity / 2 {
        score -= 4.0; // lots of room left, keep using it
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly -> strong reward, bigger if exact class match
            score -= 12.0;
            if post_residual % next_item_size == 0 && post_residual > next_item_size {
                score -= 5.0;
            }
        } else {
            // next item won't fit here -> slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins prefer tighter fits (already via post_residual)
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate: opening a new bin wastes capacity unless current fit is bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; offset by how bad the alternatives look
        score += 55.0;
        // late in stream, prefer consolidation into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
        // many open bins with low mean residual -> opening new bin is worse
        if mean_residual < 20.0 && open_bins_count > 2 {
            score += 15.0;
        }
        // huge items (>= 60) into a fresh bin is actually fine
        if item_size >= 60 {
            score -= 30.0;
        }
        // if no open bin can fit (fitting_bins_count==0 handled by new-bin call anyway)
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is close to item (tight fit) beyond raw post_residual
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 10.0;

    // Harmonic class bonus: item size divisible by 10 pairs with round residuals
    if item_size % 10 == 0 && bin_residual % 10 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size 1..=12) are pure waste.
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0;
    } else if post_residual > 12 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward very tight fits (post_residual == 0 or tiny relative to item).
    if post_residual == 0 {
        score -= 80.0;
    } else if (post_residual as f64) <= 0.05 * (item_size as f64) {
        score -= 25.0;
    }

    // Prefer bins whose residual was close to the item (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer packing into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.8 * pressure;

    // New-bin candidate handling: an empty bin should only win when the
    // current bin would leave a bad dead space or the fit is poor.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin; make it lose to good fits
        // but win over dead-space-heavy placements.
        score += 45.0 + 0.5 * pressure;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item could use the post_residual,
    // this placement is more attractive.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 20.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            // post_residual cannot host the next item: mild penalty,
            // stronger if it falls in the dead zone.
            if post_residual <= 12 {
                score += 25.0;
            }
        }
    }

    // Mean-residual coupling: bins far below mean residual are already
    // fragmented; prefer placing into them to consolidate waste.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near matches of the leftover
    // space with the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            score -= 12.0 - diff.min(12.0); // next item still fits
        } else {
            score += diff * 0.15; // next item won't fit here; penalize waste
        }
    }

    // Penalize small unusable leftovers (dead space), scaled by item size.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 2.0;
    }

    // Prefer tight fits relative to current bin residual.
    let tight = item_size as f64 / bin_residual as f64;
    score -= tight * 8.0;

    // Compare against mean residual: filling below-average-residual bins
    // (the fullest bins) is preferred.
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, be greedier about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.8;
        } else {
            // Reward bins that can also host the lookahead item.
            score -= 6.0;
            let slack = (post_residual - next_item_size as u32) as f64;
            if slack == 0.0 {
                score -= 10.0; // perfect two-item packing
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate handling: make empty bins attractive only when the
    // item fits poorly everywhere else or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        // Base cost of a fresh bin; cheaper early when fragmentation is high.
        score += 20.0 + 25.0 * (1.0 - progress) - fragmentation.min(15.0);
        // Prefer a new bin for large items that would wreck a partially full bin.
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
    }

    // Mild preference for bins with residual close to mean (keep balance),
    // avoiding extreme outliers becoming dead space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Small penalty for leaving residuals in the awkward zone (1..10)
    // that few future items (min size 1, but typical larger) can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Time-scaled urgency: late in the stream, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = post * (1.0 + 2.0 * fit_ratio * fit_ratio);

    // Smooth coupling of post_residual with stream progress:
    // early on, tolerate loose fits; late, punish dead space more strongly
    let progress_weight = 1.0 + 3.0 * progress * progress;
    score += post * fit_ratio * progress_weight;

    // Penalize residual that is too small to be useful (dead space) — smooth quadratic well
    let dead_threshold = 0.15 * cap;
    if post < dead_threshold {
        let d = (dead_threshold - post) / cap;
        score += 40.0 * d * d;
    }

    // Reward using the last fitting bin (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: reward residual that still fits the next item, more as stream progresses
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post as u32 >= next_item_size {
            score -= 4.0 * (nx / cap) * (0.5 + progress);
        } else {
            // residual can't host next item; penalize proportionally to wasted potential
            let gap = (nx - post).max(0.0) / cap;
            score += 6.0 * gap * gap;
        }
    }

    // Mild dispersion penalty: bins far from mean residual are slightly discouraged
    let dev = (post - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    // Slight preference for consolidating into fewer bins as open bins grow
    score += 0.05 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large
    // "harmonious" chunks (25, 20, 10) remain usable for future items.
    let harmonic_bonus = if post_residual == 0 {
        60.0 // perfect fit: strongly reward
    } else if post_residual % 25 == 0 {
        30.0
    } else if post_residual % 20 == 0 {
        22.0
    } else if post_residual % 10 == 0 {
        12.0
    } else if post_residual % 5 == 0 {
        5.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize small awkward dead space (1..=9) that likely cannot fit
    // anything useful; scale by how far into the stream we are.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (1.5 + 2.0 * progress);
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let waste_after_next = post_residual - next_item_size;
            score -= 18.0 - (waste_after_next as f64) * 0.3;
        } else {
            // next item cannot follow here: mild penalty for tight fills
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than average (best-fit flavor), modulated by
    // how many alternatives exist.
    let avg = mean_residual;
    if (bin_residual as f64) < avg {
        score -= (avg - bin_residual as f64).min(30.0) * 0.4;
    } else {
        score += ((bin_residual as f64) - avg).min(30.0) * 0.2;
    }

    // Integer-division threshold on post_residual: residuals >= 50 are
    // "half-class" and still very reusable.
    if post_residual >= bin_capacity / 2 {
        score -= 8.0;
    }

    // Mild preference for consolidating into existing bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers (1..=9) are nearly unusable
    // for items >= 10, so punish them far beyond their linear magnitude.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
