    }

    // New-bin candidate: only attractive when it enables a perfect 2-item pairing
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity
            && bin_capacity - item_size - next_item_size < 10 {
