    // in the stream and when many open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 45.0 * (1.0 - progress);
        new_bin_penalty += 2.0 * open_bins_count as f64;
