        }
        score += new_bin_penalty;
    } else {
        // Mild preference for bins with below-average residual (balance load).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Slight preference to fill bins that are already well-used.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
