    score -= 25.0 * x * x * x;                // smooth cubic coupling

    // Stream progress coupling: late in the stream, dead space is costlier
    let prog_term = progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score += prog_term * (pr - 0.5 * cap).abs() * 0.6;

