    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // next item leaves a further residual: prefer small chain waste
            let chain = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain / cap);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 0.5 * (next_item_size as f64 - pr).min(cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are poor
    if bin_residual == bin_capacity {
        let mean_waste = (cap - mean_residual) / cap; // fraction of mean residual usable
        let stream_frac = step_index as f64 / (total_items.max(1) as f64);
        // early stream: be lenient; late stream: conserve bins
        score += 55.0 + 90.0 * stream_frac - 60.0 * mean_waste;
        // opening new bin is attractive if next item is large and nothing fits well
        if next_item_size >= 60 && fitting_bins_count > 0 {
            score -= 45.0;
        }
    }

    // Mild preference for tighter bins overall (avoid fragmenting many open bins)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Small tie-break: keep scores distinct via residual magnitude
    score + 0.001 * pr
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // possible item (size 1) are still usable, but gaps in the "awkward zone"
    // (1..=12) are unlikely to fit typical items -> heavy penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += 25.0 * (13.0 - post_residual as f64);
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Pressure from number of open bins: prefer reusing existing bins when
    // many are open; allow new bins when few are open.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        // mild reward if next item can still fit
        score -= 5.0;
    }

    // New-bin candidate: make it attractive only when current bin would leave
    // a large unusable remainder or mean residual is already low (bins packed).
    if bin_residual == bin_capacity {
        // default neutral-ish cost; adjust with stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 10.0 + 20.0 * (1.0 - progress) - 0.5 * mean_residual;
        if post_residual <= 12 && post_residual > 0 {
            score += 25.0 * (13.0 - post_residual as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (bin_capacity as f64 - slack) * 0.4;
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize dead space.
        score += (next_item_size as f64).min(post_residual as f64) * 0.3 + 5.0;
    }

    // Perfect closure bonus: bin becomes exactly full after this item (and no next fit).
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize bins far below mean residual (fragmenting many half-empty bins),
    // but reward bins above mean residual (consolidating space).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.2;

    // New-bin candidate: mildly penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0;
        // If lookahead item is large and this bin would be fresh, opening is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual weighted more).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Penalize bins whose residual barely exceeds the item (awkward split).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward leaving residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing here would block next item from this bin
            score += 8.0;
        }
    }

    // Last-chance bonus: only one fitting bin — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fullest bins when many bins are open (reduce fragmentation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
    score -= fill_ratio * 20.0 * (open_bins_count.min(20) as f64 / 20.0);

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        let base = 30.0;
        // More likely to open early when few bins, less later (consolidate).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = base + progress * 25.0 + (mean_residual / bin_capacity as f64) * 10.0;
        // If next item is large, fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: if mean residual is high, tolerate looser fits.
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_norm = (pr / cap).clamp(0.0, 1.0);

    let mut score = pr;

    // New-bin candidate: penalize mildly so we only open when fits are poor.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        score = cap * (1.05 + 0.35 * progress);
        return score;
    }

    // Reward tight fits: non-linear quadratic coupling of post_residual with progress.
    score -= 45.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (0.6 + 0.8 * progress);

    // Penalize dead space that cannot fit typical next item (smooth coupling).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let waste = (pr - ns).max(0.0) / cap;
        score += 30.0 * waste * waste;
        // Reward leaving exactly room for the lookahead item.
        let gap = (pr - ns).abs() / cap;
        score -= 18.0 * (1.0 - gap) * (1.0 - gap) * (1.0 - gap);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Prefer bins below mean residual early (save big spaces), reversed late.
    let mr = mean_residual;
    score += (pr - mr) * (0.25 - 0.45 * progress);

    // Mild preference for fewer open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic classes: quantize post_residual into capacity-fraction buckets.
    // Small post_residual classes (<= 10) are prime real estate; larger ones waste.
    let class = post_residual / 10; // integer division threshold class 0..=10
    score += class as f64 * 12.0;

    // Non-linear penalty: quadratic in leftover beyond a small core.
    let pr = post_residual as f64;
    score += 0.08 * pr * pr / bin_capacity as f64;

    // Reward placements that leave a residual matching common item sizes
    // (harmonic residue classes of capacity): 20, 25, 30, 40, 50.
    let harmonics = [10u32, 20, 25, 30, 40, 50];
    if harmonics.contains(&post_residual) {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead (k=2): if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Next item cannot use the leftover: penalize proportionally.
            score += 0.5 * (next_item_size as f64 - pr).max(0.0);
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; softened late in the stream or when
        // few bins fit and mean residual is tight.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 55.0;
        if fitting_bins_count == 0 {
            new_bin_cost = 5.0;
        } else if fitting_bins_count == 1 {
            new_bin_cost = 90.0; // last-chance bin exists; discourage new bin
        }
        if mean_residual < 15.0 {
            new_bin_cost += 10.0; // open bins are nearly full anyway
        }
        if progress > 0.8 {
            new_bin_cost -= 10.0;
        }
        score = new_bin_cost + 0.05 * item_size as f64;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residual in the "unusable gap" band
    // (small leftovers that almost nothing can fit into later).
    let dead_lo = 1.0f64;
    let dead_hi = 9.0f64;
    let pr = post_residual as f64;
    if pr >= dead_lo && pr <= dead_hi {
        score += (dead_hi - pr + 1.0) * 12.0; // smaller dead gap = worse (more wasted)
    }

    // Reward very tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 25.0;
    } else if pr <= 3.0 {
        score -= 10.0;
    }

    // Reward residual that closely matches the next item (lookahead pairing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - diff / 100.0).max(0.0) * 8.0;
        // Penalize if leftover can't fit next item but is just above dead zone.
        if post_residual < next_item_size && post_residual > 0 {
            score += 4.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean
    // (using a fuller bin keeps mean residual high for future items).
    let dev = mean_residual - pr;
    score -= dev * 0.3;

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins have poor fits; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress) - 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Opening a new bin is fine if it would leave the item alone with lots of space
        // and next item is large.
        if next_item_size > item_size.saturating_add(post_residual.min(next_item_size)) {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff); // strong reward for post_residual ≈ next_item_size
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step fit bonus
        }
    }

    // Penalize dead space: tiny residuals that nothing can use (min item 1).
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Compare against mean residual: bins already tighter than average are
    // good targets; loose bins should stay loose for larger future items.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Last chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin when it would waste
    // capacity, unless current residuals are all poor fits.
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64 - next_item_size as f64;
        score += 45.0 + waste.max(0.0) * 0.4;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0; // fresh bin does pair well with next item, mild cost
        }
    }

    // Slight preference for compacting bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fit_ratio * post_residual as f64 / bin_capacity as f64;

    // Penalize large dead space that becomes unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0; // small slivers are fine, item nearly fills bin
    }
    if post_residual >= 10 && post_residual < 30 {
        score += 4.0; // awkward gap zone
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 2.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // If next item cannot fit anywhere else either, opening fresh space may be better.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size > mean_residual {
        score += 1.5;
    }

    // Time horizon: early in the stream, be more willing to keep bins tight;
    // late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is close to the mean (balanced usage),
    // but reward using bins with above-average residual (the roomiest ones).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff.abs();
    if diff > 0.0 {
        score -= 0.10 * diff;
    }

    // Many open bins: encourage filling them rather than opening new ones.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: only attractive when current item is large relative
    // to mean residual or nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / bin_capacity as f64) - (mean_residual / bin_capacity as f64);
        score += 5.0 - 8.0 * pressure.max(0.0);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear sharpening over stream progress
    let mut score = x * (1.0 + 2.0 * progress * (1.0 - x));
    score += 0.6 * x * x;

    // Penalize waste relative to mean residual state
    score += 0.3 * (pr - mean_residual) / cap;

    // Reward tight fits more as stream progresses
    let tightness = 1.0 - x;
    score -= 0.5 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2;
    }

    // Lookahead coupling: bonus if next item fits well in the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let nx = (pr - nxt) / cap;
            score -= 0.8 * (1.0 - nx) * (1.0 - progress);
        } else {
            score += 0.4 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.02 * open_bins_count as f64 * x;

    // New-bin candidate handling: keep it slightly unattractive unless residual is large
    if bin_residual == bin_capacity {
        score += 0.5 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 capture "dead space quality"
    let r = post_residual % 10;
    // Residue 0 (perfect multiple of 10) is most reusable given item sizes 10..80
    let residue_penalty: f64 = match r {
        0 => -12.0,
        1 | 9 => 6.0,
        2 | 8 => 3.0,
        3 | 7 => 1.0,
        _ => 0.0,
    };
    score += residue_penalty;

    // Integer-division thresholds: how many minimum-size items (10) still fit
    let slots = post_residual / 10;
    score -= (slots.min(10)) as f64 * 2.5;

    // Tight fit reward: post_residual small but nonzero is ideal
    if post_residual > 0 && post_residual <= 5 {
        score -= 15.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect closure
    }

    // Lookahead coupling: can next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic pair: post_residual mod next_item_size small => good chain
            let chain = post_residual % next_item_size;
            score -= 10.0 - (chain as f64) * 0.5;
        } else {
            // dead space for the next item
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0 + (post_residual as f64);
        // open a new bin if the item would leave very fragmented residual elsewhere
        if post_residual < 10 && post_residual > 0 {
            score -= 45.0;
        }
    }

    // Mean residual context: prefer bins close to mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Stream progression: early on, be pickier about waste; late, just fill
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (1.0 - progress) * 0.3;

    // Many open bins: encourage closing bins out
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += (11 - pr) as f64 * 8.0; // spike for tiny gaps (1..=10)
    } else if pr > 10 && pr <= 20 {
        score += (20 - pr) as f64 * 2.0; // mild penalty for near-dead zone
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 15.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral base plus pressure that grows with open bins.
        score += open_bins_count as f64 * 4.0 * (0.5 + progress);
        // Slight reward if next item is small enough to share the fresh bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    } else {
        // Reward reusing existing bins, more so as stream progresses.
        score -= 3.0 + progress * 5.0;
        // Lookahead: bonus if the post-fit gap can still hold the next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Mild global coupling: bins far below mean residual are slightly less attractive
    // (keep large gaps for large future items) unless this is a near-perfect fit.
    if (bin_residual as f64 - mean_residual) > 25.0 && pr > 15 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: prefer small post_residual.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                // Reward proportional to how well next item uses the leftover.
                let next_fit = next_item_size as f64 / post_residual as f64;
                score -= 45.0 * next_fit;
            }
        } else {
            // Leftover cannot host next item: penalize dead space.
            score += 12.0 + 0.25 * (post_residual as f64);
        }
    }

    // Relative residual coupling: prefer bins tighter than the mean.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - tightness);

    // Penalize opening new bins when many bins are open and item fits reasonably.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item leaves a useful remainder
        // for the next item or open bins are very loose.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 18.0 + 3.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already low, amplify.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space: post_residual too small to ever be useful.
    let min_future = 1u32; // smallest possible item
    if post_residual < min_future {
        score += 100.0;
    } else if post_residual > 0 {
        // Waste penalty grows if residual is awkwardly small relative to typical items
        if post_residual < 10 {
            score += 8.0 * (10.0 - post_residual as f64);
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; slight penalty proportional to mismatch
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should be discouraged unless
    // the current item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score += 20.0;
        // But if item is large relative to capacity, a fresh bin is fine
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins fit the item, opening a new one is wasteful
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0);
        }
    }

    // Global state coupling: when mean residual is high, prefer filling
    // bins with large residuals (avoid fragmentation across many bins).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel > 1.0 {
            score -= 5.0 * (rel - 1.0).min(3.0);
        } else {
            score += 3.0 * (1.0 - rel);
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage closing them out by filling.
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - progress) - pr_norm * progress;
    score += 12.0 * poly;

    // Penalize near-full-but-wasteful residuals smoothly (dead space)
    let waste = (pr / (pr + 10.0)) * (pr / bin_capacity as f64);
    score -= 8.0 * waste;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 3.0 * (gap / 50.0).tanh() - 2.0 * (-gap / 25.0);
    }

    // Mild dispersion penalty: prefer bins near the mean residual
    score += 0.4 * ((bin_residual as f64 - mean_residual) / 50.0).powi(2);

    // Discourage opening excessive new bins late in the stream
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 0.5 * open_bins_count as f64 * progress;
    } else {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: reward small post_residuals via modular structure
    let pr = post_residual;
    if pr > 0 {
        // dead-space penalty grows superlinearly for unusable slivers
        if pr < 10 {
            score += 30.0 * (10 - pr) as f64;
        }
        // mod-10 classes: residuals divisible by 10 are more reusable
        if pr % 10 == 0 {
            score -= 8.0;
        } else {
            score += 3.0;
        }
        // quarter classes of capacity
        let quarter = (cap / 4.0) as u32;
        if pr % quarter == 0 {
            score -= 5.0;
        }
    }

    // Lookahead: favor leaving room for the next item exactly
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 120.0;
        } else if pr > next_item_size {
            let slack = pr - next_item_size;
            score += slack as f64 * 0.3;
            if slack % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item can't fit here; slight penalty unless post_residual tiny
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { (item_size as f64) / cap };
        score = cap * 0.55 - pressure * cap * 0.4
            + (open_bins_count as f64) * 2.0
            - (step_index as f64 / total_items.max(1) as f64) * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin good for a big follow-up
        }
    }

    // Mild preference for fuller bins overall
    score -= (bin_residual as f64 / cap) * 5.0;
    score += (mean_residual - post_residual as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the smallest
    // item (size 1..) are pure waste; residuals below the typical item scale
    // (10) are nearly unusable. Penalize them super-linearly.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 50.0;
    } else if post_residual < 10 {
        // Unusable dead space under the minimum item size: heavy penalty.
        score += 30.0 + (10.0 - pr) * 4.0;
    } else if post_residual < 20 {
        // Marginal gap: only likely usable by tiny items.
        score += 12.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    score -= (bin_capacity as f64 - pr) / bin_capacity as f64 * 8.0;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins to avoid carrying many partial residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // If this bin is the ONLY fitting bin, strongly favor using it
    // (otherwise we open a new bin and strand this one's residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward this placement (chains two items nicely).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward proportional to how well it fills.
        score -= 5.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }

    // New-bin candidate: only attractive when current residuals are large
    // (poor fits everywhere) or nothing else fits well.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; make it slightly costly unless
        // mean residual across open bins is already large.
        score += 10.0;
        if mean_residual > 40.0 {
            score -= (mean_residual - 40.0).min(30.0);
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Coupling: penalize leaving a residual just below next_item_size
    // (a "teasing" gap that blocks the lookahead item).
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0 * (1.0 - (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tiny dead space).
    if post_residual < 5 {
        score -= 40.0;
    } else if post_residual < 15 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next && post_residual as u32 >= next_item_size {
            // Exact match bonus: next item perfectly consumes the leftover space.
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                let slack = post_residual as f64 - next;
                score -= 35.0 - slack.min(40.0) * 0.6;
            }
        } else if post_residual > 0 {
            // Penalize leaving space that the next item cannot use (dead space risk).
            let waste = post_residual as f64 - (post_residual as f64).min(next - 1.0);
            score += waste * 0.25;
        }
    }

    // Compare post_residual against mean residual: avoid bins that become outliers.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild preference for filling fuller bins (smaller residual) early vs late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (5.0 + 10.0 * progress);

    // New-bin candidate: penalize opening a new bin unless current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is huge and next item is small, a fresh bin gives flexibility.
        if item_size > bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (small post_residual)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Penalize large dead space: post_residual below smallest plausible item (~1..10)
    if post_residual < 10 {
        score -= 15.0; // perfect stuffing bonus
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // when many bins fit, prefer the tightest anyway (already via post_residual)
        score += 0.1 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item could exactly fill this bin's post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving awkward gap
            score += 0.05 * post_residual as f64;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // penalize new bin mildly by default, more when open bins are low/sparse
        let mut new_bin_penalty = 8.0 + 0.05 * open_bins_count as f64;
        if post_residual as f64 >= mean_residual {
            // current bins are quite full relative to a fresh bin -> new bin more attractive
            new_bin_penalty -= 6.0;
        }
        if fragmentation > 30.0 {
            new_bin_penalty -= 3.0;
        }
        // late in stream, avoid opening new bins
        new_bin_penalty += 5.0 * progress;
        score += new_bin_penalty.max(0.0);
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling fullest bins
    if bin_residual as f64 > mean_residual + 5.0 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post residual with stream progress
    let mut score = pr;
    score += 30.0 * x * x * (1.0 - progress);
    score -= 25.0 * x * x * progress;
    score += 10.0 * (1.0 - x) * (1.0 - x) * progress;

    // Reward tight fits, penalize dead space scaled by stream maturity
    score -= (item_size as f64 / cap) * (1.0 + progress) * 5.0;
    score += (x * x * x) * 20.0 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits the post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - progress + 0.5);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure toward consolidating open bins
    score += (open_bins_count as f64) * 0.05 * (1.0 - x);
    score += (mean_residual - pr) * 0.1;

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in low bands are "dead space".
    let class = post_residual / 10; // 0..=10 harmonic class
    score += match class {
        0 => -30.0,                       // perfect/near-perfect fit
        1 => -18.0,                       // very tight
        2 => -8.0,
        3 => 0.0,
        4 => 6.0,
        5 => 10.0,
        6 => 14.0,
        7 => 18.0,
        8 => 22.0,
        9 => 26.0,
        _ => 0.0,                         // class 10 => new empty bin (residual == capacity)
    };

    // New-bin candidate: only attractive when the item would leave a huge unusable
    // gap in every existing bin, or this is the last fitting bin.
    if post_residual == bin_capacity {
        // Base penalty for opening a new bin, discounted when fits are scarce.
        let scarcity = if fitting_bins_count <= 1 { 0.35 } else { 1.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 * scarcity + 10.0 * (1.0 - progress);
        // If no existing bin fits at all, opening is mandatory and cheap.
        if fitting_bins_count == 0 {
            score = -100.0;
        }
    } else {
        // Last-chance bonus: if this is the only bin that fits, use it strongly.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Reward when next item fits exactly into the post-residual (pairing lookahead).
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 25.0;
            } else if next_item_size <= post_residual {
                let slack = post_residual - next_item_size;
                score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
            } else {
                // Next item cannot use this bin's leftover; penalize large leftovers
                // that nothing in the near future will consume.
                let gap = next_item_size - post_residual;
                if gap <= 30 {
                    score += 5.0;
                }
            }
        } else {
            // Last item: prefer filling as tightly as possible.
            score -= 15.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below the mean
    // when placing (tighten the tight ones, keep loose bins flexible).
    score += (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.4;

    // Modulo structure: residuals divisible by common item sizes (10,20,25,50)
    // are more reusable; reward them.
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 4.0;
        }
        if post_residual % 25 == 0 {
            score -= 3.0;
        }
        if post_residual % 50 == 0 {
            score -= 3.0;
        }
    }

    // Slight pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap is "unusable" if it cannot fit even the smallest plausible item (<= 10),
    // and progressively worse the smaller it is.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    score -= item_size as f64 * 0.5;

    // Open-bins pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the mean residual (harmonized filling).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Slight preference for filling bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linearity.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        // Perfect chain (post_residual == next_item_size) gets a big bonus.
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how close it is
        // (wasted opportunity to keep the chain alive).
        let miss = (next_item_size - post_residual) as f64;
        score += 4.0 * miss / bin_capacity as f64;
    }

    // Compare bin residual to mean residual: bins below average residual are
    // "tight" and should be filled now; bins above average keep flexibility.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Slight preference for filling older/more crowded bin sets early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins moderately attractive only when the
    // item is large relative to capacity or no good open fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 10.0 - 8.0 * large_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (waste grows super-linearly).
    let dead = post_residual as f64;
    score += 0.35 * (dead * dead) / bin_capacity as f64;

    // Reward tight fits strongly.
    if post_residual < 8 {
        score -= 25.0;
    } else if post_residual < 15 {
        score -= 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual as f64 >= ni {
            let gap = post_residual as f64 - ni;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit here: mild penalty scaled by how close it was.
            score += 0.05 * (ni - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in stream, prefer spreading load (favor new bins slightly);
    // late in stream, prefer compacting into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress;

    // Global state coupling: many open bins with high mean residual -> discourage new bins,
    // encourage filling bins whose residual is above the mean.
    if bin_residual < bin_capacity {
        let above_mean = mean_residual - bin_residual as f64;
        score += 0.10 * above_mean;
        if open_bins_count > 4 {
            score -= 0.5 * open_bins_count as f64;
        }
    } else {
        // New-bin candidate: penalize when there are plenty of fitting bins or high mean residual.
        score += 20.0 + 1.5 * fitting_bins_count as f64 + 0.15 * mean_residual;
        if progress > 0.7 {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Prefer bins whose residual is just above the item size (minimal slack).
    let slack = (bin_residual - item_size) as f64;
    score += 0.02 * slack * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, small residuals are fine (tight packing); later, large residuals
    // become dead space, so penalize them progressively.
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;
    score += 40.0 * prog_sq * (pr / cap) * (pr / cap) + 25.0 * prog_cu * (pr / cap);

    // Reward tight fits: smooth quadratic bonus on small post_residual.
    score -= 30.0 * (1.0 - (pr / cap)) * (1.0 - (pr / cap)) * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item can use the post residual, reward.
    if nx > 0.0 {
        let diff = (pr - nx) / cap;
        let diff2 = diff * diff;
        score -= 20.0 * (1.0 - diff2.min(1.0)) * (1.0 - progress);
        // Penalize if post residual is just barely unusable for next item.
        if pr < nx {
            score += 15.0 * (nx - pr) / cap;
        }
    }

    // Penalize deviating from mean residual (keeps bin set balanced).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Mild penalty for spreading across many open bins.
    score += 2.0 * (open_bins_count as f64).sqrt() * (pr / cap);

    // New-bin candidate: neutral-ish baseline, penalized early, cheaper late.
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the leftover fall in?
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;

    // Dead-space penalty: leftover smaller than the smallest useful class (<= 1/10 cap) is waste.
    if post_residual > 0 && post_residual < tenth {
        score += 25.0;
    }

    // Perfect fit reward (post_residual == 0 or exact modulo class of capacity).
    if post_residual == 0 || post_residual == quarter || post_residual == fifth || post_residual == tenth {
        score -= 20.0;
    }

    // Harmonic class match: if next item exactly fits the post_residual (or its mod class), reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack < tenth {
                score -= 12.0;
            } else if slack < fifth {
                score -= 5.0;
            } else {
                score += slack as f64 * 0.15;
            }
        } else {
            // next item cannot fit here: mild penalty proportional to overflow gap class
            score += ((next_item_size - post_residual) as f64).min(40.0) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer tighter bins: reward small bin_residual (best-fit core) with harmonic scaling.
    score -= (cap - bin_residual as f64) * 0.3;

    // Penalize opening a new bin when decent fitting bins exist; new-bin candidate has full residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 20.0 * (1.0 - progress) + (open_bins_count as f64).min(10.0);
    }

    // Mean-residual coupling: when mean residual is high, waste here is less costly.
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Pressure from number of open bins: prefer compacting into fewer bins
    // when many are open, but ease off early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin unless residual is
    // genuinely poor or no good alternative exists.
    if bin_residual == bin_capacity {
        // Base penalty so new bins only win when open bins score badly.
        score += 20.0;
        // Late in the stream with many open bins, opening new bins is worse.
        score += 10.0 * progress;
        // Large items justify fresh bins more (few bins can host them).
        if item_size >= 60 {
            score -= 12.0;
        }
    }

    // Lookahead: if next item would fit the post-residual exactly-ish, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item cannot use the leftover: mild dead-space penalty.
        score += 5.0;
    }

    // Prefer bins already below mean residual (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // 2-step lookahead: reward when next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight 2-step packing (post residual nearly consumed by next item).
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize when the next item cannot use the leftover space.
            score += 15.0;
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.1;
        }
        // Perfect 2-step fill: post_residual == next_item_size -> bin closes cleanly.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else {
        // Last item: minimize post residual aggressively.
        score += 10.0;
    }

    // Compare against mean residual: prefer bins whose post residual deviates
    // favorably (smaller) from the mean; penalize leaving more than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (many fitting bins means opening a new bin is wasteful).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 35.0; // open a new bin
        } else if fitting_bins_count == 1 {
            score += 25.0; // keep the last-chance bin instead
        } else {
            score += 50.0; // plenty of alternatives, never open
        }
    }

    // Slight preference early in the stream to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    score -= 30.0 * (-post_residual as f64 / 12.0).exp();

    // Penalize creating dead space too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && (post_residual as i64) > 0 {
        // Next item won't fit here; penalize wasting residual if it's sizable.
        score += 0.3 * post_residual as f64;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Time horizon: early in the stream, be more conservative about opening
    // new bins (favor existing bins); late, allow new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 20.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_bias;
        // Opening a new bin is attractive when open bins are mostly full
        // (low mean residual) and many bins exist.
        score -= 0.15 * open_bins_count as f64;
        score += 0.5 * mean_residual;
    } else {
        // Existing bins: slight preference for fuller bins (waste less space overall).
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill_ratio;
    }

    // Mild penalty when many bins can fit the item: keep flexibility,
    // prefer bins that others cannot use later.
    score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);

    // Discourage leaving residuals just above mid-range item sizes.
    for gap in [10u32, 20, 30, 40, 50] {
        if post_residual >= gap && post_residual < gap + 8 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: penalize wasted space, with smooth non-linear shaping
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late, tight packing is critical
    let coupling = post * (0.5 + 1.5 * progress * progress + 0.7 * progress * (1.0 - progress));
    score += coupling * 0.6;

    // Reward filling bins nearly exactly (post_residual near 0), stronger late
    let tightness = 1.0 - norm_post;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: bonus if next item fits the post residual (smooth reward)
    if next_item_size > 0 {
        let fits = (post - next_item_size as f64).max(0.0) / cap;
        score -= 4.0 * (1.0 - 2.0 * fits) * (1.0 + progress);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Slight penalty for spreading across many bins when mean residual is high
    score += 0.15 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    // New-bin candidate: prefer it only when existing bins would leave large dead space
    if bin_residual == bin_capacity {
        score = 30.0 + 40.0 * progress - 3.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into capacity-fraction bands. Leftovers in the
    // smallest band (<= 10) are near-dead space; penalize them.
    let band = post_residual / 10; // 0..=10 classes
    score += (band as f64) * (band as f64) * -0.5; // smaller band -> less negative? invert:
    score += (10 - band as f64) * 3.0; // dead-space penalty grows as band shrinks

    // Lookahead harmony: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            // Reward leaving space the next item can still use reasonably.
            let next_band = next_left / 10;
            score -= 20.0 + (next_band as f64) * 2.0;
        } else {
            // Next item won't fit here; leftover is likely dead. Penalize
            // more if the leftover is small (unusable) rather than large.
            if post_residual < 10 {
                score += 30.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless post_residual is tiny).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
        if post_residual <= 5 {
            score += 100.0; // but avoid creating 1-5 unit dead space
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Favor keeping it closed when a decent fit exists in an open bin.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin; scaled by stream progress
        // (late in the stream, opening bins is costlier per-item).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 + 60.0 * progress;
        // If many open bins already have large mean residual, definitely reuse.
        if mean_residual >= item_size as f64 {
            score += 40.0;
        }
    } else {
        // Reward filling bins that are already fairly full (small residual).
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 25.0 * fill_ratio;
    }

    // Modulo-harmonic bonus: post_residual divisible by common item sizes
    // (10/20/25/50) is reusable by typical items.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 15.0;
    }

    // Mild tie-break: prefer bins whose residual is closest to item size
    // (tight fit) via quadratic term on post_residual.
    score += (post_residual as f64).powi(2) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, prefer packing tighter.
    score += open_bins_count as f64 * 0.3;

    // If lookahead item can use the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size <= post_residual + 9 {
        score += 5.0;
    }

    // New-bin candidate baseline: only attractive when current fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item: strong reward
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            score += diff * 0.5;
        }
        // If next item can't fit in post_residual, penalize dead space more
        if post_residual < next_item_size && post_residual > 0 {
            score += post_residual as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Late in stream: be more conservative, prefer tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual)
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize post-residuals that are too small to be useful later
    if post_residual > 0 {
        let min_useful = 9.0; // smallest plausible item
        if (post_residual as f64) < min_useful {
            score += 40.0; // dead space
        } else {
            // residual that could fit the next item is valuable
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 12.0;
            }
            // residual just below next item size is awkward
            if next_item_size > 0 && post_residual < next_item_size {
                score += 6.0;
            }
        }
    } else {
        score -= 20.0; // perfect closure
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = bin_residual as f64 - item_size as f64;
        score += 55.0;
        // open new bins more readily early and when open bins are crowded
        score -= 25.0 * (1.0 - progress);
        if open_bins_count > 0 {
            score -= 8.0 * (mean_residual / cap).min(1.0);
        }
        if waste < 15.0 {
            score -= 30.0; // item nearly fills a fresh bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin can also host next item
        }
    }

    // Prefer bins whose residual differs from the mean (avoid uniform fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 3.0 * (dev / cap);

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.15 * open_bins_count as f64;

    // Lookahead: if next item is large and this placement leaves room for it, reward
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual
    let p2 = prn * prn;
    let p3 = p2 * prn;
    let prog2 = progress * progress;
    // Early on, prefer leaving moderately large residuals (flexible); late, penalize any residual.
    score += 12.0 * p2 * (1.0 - progress) - 18.0 * p3 * progress;
    score += 6.0 * p2 * prog2;

    // Reward tight fits: small post residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Lookahead: bonus if next item exactly fits the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
        if nx > pr {
            // residual too small for next item: penalize proportionally
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Penalize deviating from mean residual (keeps bin residuals homogeneous).
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: encourage opening a fresh bin only when residuals are fragmented
    // or progress is late and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        let new_bin_bias = 20.0 * (1.0 - fragmentation) + 30.0 * progress * (1.0 - prn);
        // base cost of a new bin plus situational bias
        score = 45.0 - new_bin_bias + 10.0 * p2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // classes (multiples of common item sizes) are more valuable to keep.
    let class_bonus = if post_residual == 0 {
        -30.0 // perfect fit, ideal
    } else if post_residual % 10 == 0 {
        -12.0
    } else if post_residual % 5 == 0 {
        -6.0
    } else if post_residual >= 10 && post_residual <= 30 {
        -3.0
    } else {
        0.0
    };
    score += class_bonus;

    // Penalize dead space: post_residual too small for the smallest item class.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Harmonic coupling with next item: reward residual that can host the lookahead.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            score += 6.0;
        }
        // Integer division threshold: leftover after hosting next item
        let post2 = post_residual as i64 - next_item_size as i64;
        if post2 >= 0 {
            score -= (post2 % 10) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when existing
    // bins would create dead space or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - 10.0 * progress;
        if post_residual >= 50 {
            score -= 5.0; // fresh bin with roomy future is attractive early
        }
    }

    // Prefer filling bins that are already well-loaded relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Slight preference for compact bin sets.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize gap that neither closes the bin nor fits the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Open-bin pressure: discourage scattering across many bins when fit is poor.
    score += (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64) * 3.0;

    // Last-chance bonus: only one fitting bin; avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutralize its naturally large post_residual so it only wins on genuinely good fits.
    if bin_residual == bin_capacity {
        score -= post_residual as f64 * 0.9;
        score += 10.0 + (open_bins_count as f64) * 2.0;
    }

    // Mild stream-progression tightening: later items should prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    // Deviation from mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled quadratically.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 1.0 {
            score -= 60.0; // perfect 2-step chain
        } else if nxt <= post {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit in this bin's leftover: dead space penalty
            score += 10.0 + 0.5 * nxt.min(post);
        }

        // Coupling with mean residual: bins far below mean residual are "wasted" space holders;
        // prefer filling bins whose residual deviates strongly from the mean.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.8 * dev;
    } else {
        // Last item: just minimize leftover, slightly reward any placement.
        score -= 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when this bin's residual cannot plausibly
    // absorb the next item and the current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.5;
        let next_fits_elsewhere = next_item_size > 0 && next_item_size as f64 <= mean_residual;
        if poor_fit && next_fits_elsewhere {
            score -= 30.0;
        } else {
            score += 55.0; // discourage opening new bins by default
        }
    }

    // Slight stream-progression pressure: as stream nears end, prefer compacting.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but over-penalize near-zero
    // dead space less than moderately small waste (small slivers are unusable anyway).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize unusable slivers: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Mild penalty when many bins are open and residual is large (fragmentation risk),
    // scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    // Compare against mean residual: bins far below mean residual are already
    // crowded; prefer filling them further (lower score).
    score -= 0.08 * (mean_residual - post_residual as f64);

    // Slight preference for opening new bins early (spread large items),
    // but only when the fit is mediocre.
    if tightness < 0.5 {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post_residual, with non-linear (quadratic) coupling
    let mut score = pr / cap;

    // Quadratic penalty: residuals that are unusable dead space (small but nonzero)
    let pr_norm = pr / cap;
    score += 0.6 * pr_norm * (1.0 - pr_norm);

    // Smooth interaction with stream progress: late in the stream, tighten packing more
    score *= 1.0 + 0.5 * progress * (1.0 - pr_norm);

    // Reward filling bins that fit well relative to mean residual
    let fit_quality = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 0.4 * fit_quality * (1.0 - progress);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 1.2;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.3 * (next_item_size as f64 / cap);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item cannot use leftover: penalize small dead space more
        score += 0.5 * (1.0 - pr_norm) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 0.8;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 1.5 + 0.5 * progress;
    } else {
        // Prefer bins tighter than average
        score += 0.2 * ((bin_residual as f64) - mean_residual) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "useful"
    // residue classes (multiples of common item sizes / capacity fractions)
    // are more valuable than bins with awkward dead space.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus -= 60.0; // perfect fill
    } else if pr <= 5 {
        class_bonus -= 40.0; // near-perfect, negligible dead space
    } else {
        // Harmonic classes via modulo arithmetic on common divisors
        if pr % 10 == 0 { class_bonus -= 25.0; }
        else if pr % 5 == 0 { class_bonus -= 15.0; }
        if pr % 20 == 0 { class_bonus -= 10.0; } // extra for 20-multiples
        if pr % 25 == 0 { class_bonus -= 8.0; }
        // Dead-space penalty for awkward residues (prime-ish, odd non-divisors)
        if pr % 2 == 1 { class_bonus += 6.0; }
        if pr % 3 != 0 && pr % 7 != 0 { class_bonus += 4.0; }
    }
    score += class_bonus;

    // Lookahead coupling: does the leftover harmonically fit the next item?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (pr as f64) >= ni {
            let gap = pr as f64 - ni;
            if gap == 0.0 {
                score -= 50.0; // next item fills this bin exactly
            } else if gap <= 5.0 {
                score -= 30.0;
            } else if gap % 10.0 == 0.0 {
                score -= 18.0;
            } else if gap % 5.0 == 0.0 {
                score -= 10.0;
            }
            // penalize if next item would leave a bad residue anyway
            let next_post = gap;
            if next_post > 0.0 && next_post < 10.0 {
                score += 5.0;
            }
        } else {
            // leftover too small for next item: dead space
            score += (ni - pr as f64).min(20.0) * 0.8;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only open a new bin if the item is large relative
    // to the typical residual landscape, otherwise penalize.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = cap - item_size as f64;
        score += waste * 1.2;
        // Early on, opening bins is fine; late, prefer filling existing bins
        score -= (1.0 - progress) * 10.0;
        // If many open bins with slack, discourage new bins
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    } else {
        // Mild preference for tighter existing bins relative to mean residual
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    // Fraction-of-capacity harmonic structure on post_residual
    let frac = post_residual as f64 / cap;
    if frac < 0.10 { score -= 12.0; }
    else if frac < 0.25 { score -= 4.0; }
    else if frac > 0.70 { score += 8.0; } // mostly-empty bin being used: wasteful

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual).
    score = post_residual as f64 * 1.0;

    // Penalize small unusable dead space: gaps below the minimum item size
    // (1..=10) are worthless; gaps 11..=30 are partially usable.
    if post_residual < 10 {
        score += 60.0; // dead space
    } else if post_residual <= 30 {
        score += (30.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post_residual, this is a great placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Bonus if next item exactly fills the gap.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: mild penalty unless gap is dead anyway.
        score += 6.0;
    }

    // Last-chance: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 35.0;
        // Even stronger if residual is already small (few alternatives exist anyway).
        if bin_residual <= item_size + 15 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // Candidate is a brand-new bin.
        score += 25.0 + (open_bins_count as f64) * 4.0;
        // New bins are more attractive early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If existing fits are poor (large mean residual spread) opening new bin
        // is more acceptable: compare item fit quality.
        if post_residual > 40 {
            score -= 18.0;
        }
    } else {
        // Existing bin: slight reward for using already-open capacity.
        score -= 3.0;
        // Reward balancing residuals toward the mean (keeps bins uniformly filled).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Prefer filling bins with small residuals first (consolidate).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

