    // New-bin candidate handling: opening a new bin is expensive unless this bin
    // is a poor fit relative to alternatives. Baseline penalty for fresh bins.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if the item is large relative to mean residual of open bins,
        // a fresh bin becomes more attractive (mean residual can't hold it well)
        let mean_fit = mean_residual - item_size as f64;
        if mean_fit < 0.0 {
            score -= 70.0;
        } else if mean_fit < 10.0 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
