    score -= 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening.
    let mut score = pr + 40.0 * pr_norm * pr_norm * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tighter fits matter more.
    let coupling = 1.0 + 2.0 * progress * progress;
    score *= coupling;

    // Dead-space penalty: residuals too small to fit the next item are wasted.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            let gap = (ns - pr) / cap;
            score += 30.0 * gap * gap * cap;
        } else {
            // Reward residuals that accommodate the lookahead item smoothly.
            let fit_quality = 1.0 - ((pr - ns) / cap);
            score -= 10.0 * fit_quality * fit_quality;
        }
    } else {
        // Last item: strongly prefer minimal post-residual.
        score -= 5.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins; smooth in count.
    let ob = open_bins_count as f64;
    score += 0.5 * ob.ln() * (1.0 + progress);

    // Prefer bins whose residual is below the mean residual (denser bins),
    // with a smooth quadratic interaction.
    let diff = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * diff * diff;

    // Penalize the brand-new-bin candidate unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score += 20.0 - 25.0 * size_frac * size_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (e.g. 10, 20, 25, 50) are more likely to be filled later.
    let r = post_residual;
    if r == 0 {
        score -= 50.0; // perfect fit
    } else {
        let mut harmony = 0.0;
        if r % 10 == 0 { harmony += 6.0; }
        if r % 20 == 0 { harmony += 4.0; }
        if r % 25 == 0 { harmony += 3.0; }
        if r % 50 == 0 { harmony += 5.0; }
        // small dead space classes are worst
        if r < 10 { harmony -= 20.0; }
        score += harmony;

        // Lookahead: does the next item fit into the post-residual?
        if next_item_size > 0 && next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score -= 10.0 + 0.5 * slack; // reward leaving room for next item
        } else if next_item_size > r {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > mean_residual;
        if poor_fit && open_bins_count > 2 {
            score -= 8.0 * (1.0 - progress);
        } else {
            score += 30.0; // discourage opening new bins by default
        }
    }

    // Slight preference for tighter bins overall.
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (1..=10) are nearly unusable for future items.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual is good, but zero is perfect).
    if post_residual == 0 {
        score -= 120.0;
    } else {
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 30.0 * tight * tight;
    }

    // Perfect-fit lookahead: if next item exactly fills the remaining gap, strongly favor.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 90.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here: mild reward proportional to how well it uses the gap.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * fill;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the lookahead item: penalize if it is a dead gap.
        if post_residual <= 20 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // but allow it when open bins are nearly full on average.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 35.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin.
        // Attractive only if current item is large or no open bin fits well.
        let large_item = item_size as f64 / bin_capacity as f64;
        score += new_bin_bias - 30.0 * large_item;
        if post_residual == 0 {
            score -= 50.0; // large item exactly fills a fresh bin
        }
    } else {
        // Existing bin: reward keeping bins consolidated.
        score -= 5.0;
        // Penalize using bins whose residual is far below the mean (hoarding space).
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += 0.4 * dev;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: mild reward proportional to slack.
            score -= 30.0 - 0.2 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use the leftover: penalize dead space.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.1 * post_residual as f64;
    }

    // Tight fit bonus: reward small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize bins far below the mean residual (they are the "freshest" and
    // most flexible); prefer filling bins that are already fragmented.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let poor_fits = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        let base = 60.0 + 0.5 * item_size as f64;
        // Opening a new bin is penalized unless few fitting bins exist and fits are bad.
        score += base - 80.0 * poor_fits * (1.0 - (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0)));
    }

    // Late in the stream: be greedier about filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize large leftover dead space non-linearly.
    if post_residual > 0 {
        score += 0.15 * (post_residual as f64).powf(1.3);
    }

    // Perfect fit is heavily favored.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the residual left behind exactly fits the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // Penalize leaving a residual that is awkwardly large relative to next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin, scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if all open bins are nearly full, new bin is fine.
        if mean_residual < 12.0 {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer bins with residual below the mean (more full bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild bonus for using bins that can still fit typical future items.
    if post_residual >= 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = post;

    // Smooth polynomial coupling: post_residual^2 normalized, amplified by progress.
    score += 12.0 * norm_post * norm_post * (0.5 + progress);

    // Penalize dead space that is too small to be useful later (items >= 1..100).
    let dead = norm_post * (1.0 - norm_post); // peaks at 0.5 residual
    score -= 8.0 * dead;

    // Last-chance bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (item_size as f64 / cap);
    }

    // Lookahead coupling: reward if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post >= nxt) as i32 as f64;
        let tightness = 1.0 - (post - nxt).abs() / cap;
        score -= 6.0 * fits_next * tightness.max(0.0);
        // Penalize leaving exactly awkward gaps slightly larger than next item.
        let gap = (post - nxt) / cap;
        score += 4.0 * gap * gap * (1.0 - fits_next);
    }

    // Discourage new bins when many bins exist and mean residual is large.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 10.0 * pressure * (1.0 - mean_residual / cap).max(0.0);
        score -= 3.0 * progress; // late stream: new bins slightly cheaper
    }

    // Mild penalty for fragmenting a large residual with a small item.
    let waste = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * waste * waste * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of the leftover space: leftovers divisible into coarse
    // classes are more reusable by future items.
    let pr = post_residual;
    if pr > 0 {
        // Perfect fit reward
        if pr == 0 {
            score -= 1000.0;
        }
        // Small dead space (< 10) is nearly unusable: penalize strongly.
        if pr < 10 {
            score += 60.0;
        }
        // Harmonic classes: leftover that is a multiple of common item sizes
        // (5, 10, 20, 25) is reusable; reward those classes.
        if pr % 5 == 0 { score -= 6.0; }
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        // Integer-division thresholds on leftover size.
        let class = pr / 10; // 0..=10
        score -= class as f64 * 2.0;
        // Mid-range leftovers (30..60) are the most flexible; bonus.
        if pr >= 30 && pr <= 60 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0; // chain placement possible
            // Extra reward if next item exactly fills the leftover.
            if next_item_size == pr {
                score -= 25.0;
            }
            // Reward when next item uses a large fraction of leftover.
            let frac = next_item_size as f64 / pr as f64;
            score -= frac * 10.0;
        } else {
            // Next item won't fit here: leftover likely becomes dead space.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or the item fits no open bin well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a fresh bin; scales with how many bins are open.
        let mut new_bin_score = bin_capacity as f64 + 40.0;
        new_bin_score += open_bins_count as f64 * 3.0;
        // Late in the stream, prefer consolidating into open bins.
        new_bin_score += progress * 30.0;
        // If mean residual is large, open bins have room: penalize new bin.
        new_bin_score += mean_residual * 0.8;
        // If this bin is the only fitting option, new bin is comparatively fine.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        score = new_bin_score;
    } else {
        // Slight preference for tighter existing bins (smaller residual).
        score += (bin_capacity - bin_residual) as f64 * 0.05;
        // Prefer bins whose residual is below the mean (dense packing).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64 / 10.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 40.0;
    } else {
        // Larger gaps are mildly penalized quadratically to prefer tight fits.
        score += 0.15 * (post_residual as f64 / 10.0).powi(2);
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // Next item cannot use this bin anyway; gap becomes pure dead space.
            score += 0.3 * post_residual as f64;
        }
    }

    // Open-bin pressure: mild penalty for using already-open bins when many
    // are open, encouraging consolidation rather than spreading.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin) should only win when no open bin fits well:
    // penalize it proportionally to how much capacity would be wasted relative
    // to the item, and add a fixed opening cost.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * (bin_capacity - item_size) as f64;
    }

    // Mean-residual coupling: prefer bins deviating below the mean residual
    // (tighter bins) when the stream is early/mid; keeps large residuals
    // available for large future items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.2 * (mean_residual - bin_residual as f64) * (1.0 - 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual (chained packing)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
    }
    // Penalize if next item cannot use the leftover (dead space risk)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.8;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize wasting a nearly-full bin on a small item
    if item_size < bin_residual / 2 && bin_residual <= 30 {
        score += 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Late-stream tightening: reduce waste as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let fit_ratio = item / cap;

    // Reward tight fits: post_residual small relative to capacity.
    score -= (cap - post) * 0.6;

    // Penalize dead space that likely cannot be reused by typical items.
    if post_residual < 10 {
        score -= 8.0; // near-perfect fill bonus
    } else if post_residual < 20 {
        score -= 3.0;
    } else if post_residual > 50 {
        score += (post - 50.0) * 0.35; // large unusable gap penalty
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 4.0 + 3.0 * (1.0 - (nxt / post).abs());
        } else {
            score += (nxt - post).min(20.0) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 0.5; // many alternatives: be picky
    }

    // Global residual pressure: if mean residual is high, prefer consolidating
    // into bins that bring their residual down toward the mean.
    let dev = (post - mean_residual).abs();
    score += dev * 0.08;

    // Time horizon: early in the stream, be conservative (favor new bins less
    // aggressively penalized); late in the stream, squeeze existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;
    score += (1.0 - progress) * 1.5;

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and fits poorly elsewhere, or there are no good options.
    if bin_residual == bin_capacity {
        let base_penalty = 14.0;
        let large_item_bonus = if item_size > 60 { -6.0 } else { 0.0 };
        let scarcity_bonus = if fitting_bins_count <= 1 { -8.0 } else { 0.0 };
        let late_stream_penalty = progress * 5.0;
        score += base_penalty + large_item_bonus + scarcity_bonus + late_stream_penalty;
    }

    // Mild penalty for bin count pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.02;

    // Nonlinear coupling: reward placements where item size and residual are
    // nearly equal (exact-ish fit) with a smooth bump.
    let tightness = 1.0 - (post / cap);
    score -= 5.0 * tightness * tightness * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress * progress;
    score += 30.0 * norm_post * norm_post * (1.0 - progress);
    score -= 25.0 * norm_post * progress * (1.0 - progress);
    score += 15.0 * norm_post * norm_post * norm_post * progress;

    // Tight-fit reward (non-linear in fill fraction)
    let fill = 1.0 - norm_post;
    score -= 20.0 * fill * fill * fill * (0.5 + progress);

    // Dead-space penalty: post_residual too small for average future item
    if post > 0 {
        let dead = (mean_residual - post).abs() / cap;
        score += 10.0 * dead * dead;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * norm_next * (1.0 - progress);
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0 * norm_next * norm_post;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 * (1.0 - progress);
    }

    // New-bin candidate: prefer opening when open bins have poor fits
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - norm_item) * (1.0 - progress);
    }

    // Mild open-bin pressure to consolidate
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10 and mod 25.
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Dead-space penalty: residuals that are too small to be useful (typical item > post_residual).
    // Penalize awkward residues; reward residuals that are multiples of 10 (harmonic with capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 - (post_residual as f64) * 2.0; // tiny slivers are bad
    }
    score -= if r10 == 0 { 8.0 } else { 0.0 };
    score -= if r25 == 0 { 5.0 } else { 0.0 };
    score += (r10 as f64) * 0.4; // misaligned residue slightly penalized

    // Lookahead coupling: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill; // reward high next-item fill ratio
        } else {
            // next item won't fit here; penalize more if post_residual is a dead class
            score += if post_residual < next_item_size { 6.0 } else { 0.0 };
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has high raw score (post_residual = capacity);
    // only allow it when current bin's post-fit residual is unusable.
    if bin_residual == bin_capacity {
        // usable residual threshold via integer division on capacity
        let usable = bin_capacity / 4; // 25
        if post_residual_of(bin_residual, item_size) >= usable {
            score += 40.0; // discourage wasting a fresh bin when fit is decent
        } else {
            score -= 10.0; // current fit leaves dead space -> prefer new bin
        }
    }

    // Progress modulation: late in the stream, tighten bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    // Many open bins: prefer filling existing ones over spreading.
    score += (open_bins_count as f64) * 0.15;

    score
}

#[inline]
fn post_residual_of(bin_residual: u32, item_size: u32) -> u32 {
    bin_residual.saturating_sub(item_size)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (post_residual < 10, the classic "dead zone") are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that are small relative to capacity but above the dead zone are still mildly penalized.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit: post_residual 0 is ideal; reward strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 {
        let gap_diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= 30.0 / (1.0 + gap_diff as f64);
    }

    // --- Open bins pressure ---
    // Mildly reward using existing bins to keep open_bins_count small.
    score += 0.6 * open_bins_count as f64;

    // --- Last-chance bonus ---
    // If this is the only fitting bin, strongly prefer it over opening a new bin
    // (avoiding fragmentation), unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter fits (post_residual already encodes this).
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // --- New-bin candidate logic ---
    // For the brand-new empty bin (bin_residual == bin_capacity): score starts at
    // post_residual == capacity - item_size. Penalize opening a new bin when the
    // stream is early (waste amortization) but allow it late to close out cleanly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * (1.0 - progress) - 10.0 * progress;
        // Never open a new bin if a perfect fit exists elsewhere (post_residual 0 beats this).
        score += 5.0;
    }

    // Prefer bins with residual already far from mean (concentrate waste in few bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for filling larger bins first when residuals are close.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= 40.0 * (post_residual as f64 - next_item_size as f64).ln().max(0.0);
        } else {
            // dead space that next item cannot use
            score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Late in stream: consolidate, avoid waste
    let progress = step_index as f64 / total_items as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below
    // the minimum item size is worthless.
    let tight_bonus = if post_residual == 0 {
        60.0
    } else if post_residual < 10 {
        40.0
    } else {
        0.0
    };
    score -= tight_bonus;

    // Penalize residual that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 30.0 - (slack as f64).min(30.0) * 0.5;
        } else if post_residual >= next_item_size / 2 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: discourage fragmenting space further.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += crowding * 3.0;

    // Prefer bins whose residual is close to the item (good relative fit).
    let rel_fit = (bin_residual as f64 - item_size as f64).abs();
    score += rel_fit * 0.3;

    // Prefer bins that are already below mean residual (more filled bins).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.2;

    // Time horizon: late in the stream, favor consolidation into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let new_bin_bias = 20.0 + item_size as f64 * 0.5;
        score += new_bin_bias;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = pr / cap; // normalized post residual in [0,1]
    let t = progress.clamp(0.0, 1.0);
    // Smooth interaction: as stream progresses, penalize mid-range residuals more
    // (dead space becomes less recoverable), reward near-full packing.
    let coupling = (1.0 - t) * (x * x) + t * (4.0 * x * (1.0 - x));
    score += 12.0 * coupling;

    // Reward tight fits: subtract for post_residual close to 0 (smoothly).
    score -= 10.0 * (-pr / 8.0).exp();

    // Penalize creating residuals too small to fit the next item (wasted space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.05 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 * (post_residual as f64 / cap) * (1.0 - (next_item_size as f64 / cap));
    }

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // (mean residual low) or many bins already exist late in the stream.
    if bin_residual == bin_capacity {
        let crowding = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 20.0 - 18.0 * crowding - 8.0 * t;
    }

    // Mild preference for bins with residual close to the item (good fit).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * fit_gap * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover divisible by common size
    // increments (10/20/25/50) is more reusable than arbitrary dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, ideal
    } else {
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 8.0; }
        if pr % 50 == 0 { score -= 10.0; }
        // Small dead space (<10) is nearly unusable given min item size 1..100 mix
        if pr < 10 { score += 30.0; }
        else if pr < 20 { score += 10.0; }
    }

    // Lookahead: reward bins whose leftover can host the next item exactly or well.
    if next_item_size > 0 && pr >= next_item_size {
        let gap = pr - next_item_size;
        score -= 18.0;
        if gap == 0 { score -= 25.0; }
        else if gap % 10 == 0 { score -= 8.0; }
        if gap < 10 { score += 12.0; }
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize mildly
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 0 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Tightness reward: bins whose residual is close to item size are good fits.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Prefer fuller bins overall: compare residual to mean residual.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be conservative: prefer closing bins well rather than
    // spreading; slightly penalize opening new bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a good existing fit,
        // lowered when many bins are open (consolidation pressure).
        score += 14.0 - 6.0 * progress;
        if open_bins_count > 6 { score += 4.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual can still host the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // creates a gap the next item cannot use
        }
        // Bonus if this bin can host both current and next item exactly.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: mildly favor filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when item is large relative to residual
    // or no open bin fits well; make empty-bin default slightly costly.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 30.0 + waste * 0.3 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    // Prefer bins tighter than the average residual (best-fit coupling).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linearity
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Lookahead: exact match between post_residual and next item is ideal
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // If next item fits perfectly, strongly reward
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space too small for the next item (wasted)
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins with less residual than average
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is huge or no good fit exists
    if bin_residual == bin_capacity {
        if item_size > 60 || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 35.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Slight preference for consolidating fewer open bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 && post_residual < next_item_size {
            // leftover too small for the known next item -> mild penalty
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Time horizon: late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);

    // Prefer bins whose residual is close to the mean residual (balanced packing),
    // unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 - fit_ratio);

    // New-bin candidate (empty bin): make it attractive only when the item is large
    // relative to capacity or open bins are mostly full.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Penalty when existing bins are spacious; discount when bins are crowded
        // or the item is big enough to deserve fresh space.
        score += 35.0 * (1.0 - large_item) * (1.0 - fullness);
        score -= 20.0 * large_item * fullness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual (tight fits), smoothed non-linearly
    let mut score = prn * prn * 40.0 + prn * 10.0;

    // Stream-progress coupling: early on tolerate residual (future items fill it),
    // late in stream penalize residual more (dead space).
    let late = progress * progress;
    score += late * prn * 30.0;
    score -= (1.0 - progress) * prn * 8.0;

    // Lookahead coupling: reward post-residual that fits the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_amount = (pr - nxt).max(0.0) / cap;
        let miss = (nxt - pr).max(0.0) / cap;
        score -= fit_amount * 15.0 * (1.0 - progress);
        score += miss * miss * 50.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).ln().max(0.0) * 3.0;
    }

    // Mean-residual coupling: if this bin is near mean, mildly prefer it (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * 6.0;

    // New-bin candidate: penalize slightly by default, less when residuals are all poor
    if bin_residual == bin_capacity {
        score = 45.0 + 25.0 * progress - 15.0 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Harmonic classes: residual mod 10 buckets — small residues are more usable dead space.
    let rmod = post_residual % 10;
    score -= match rmod {
        0 => 60.0,
        1..=3 => 25.0,
        4..=6 => 5.0,
        _ => -10.0,
    } as f64;

    // Integer-division thresholds on post_residual: can next item fit here?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 80.0;
            // Harmonic pairing: next_item_size divides post_residual nicely
            if post_residual % next_item_size.max(1) == 0 {
                score -= 60.0;
            }
            // Fraction coupling: next item fills a large fraction of the residual
            let frac = next_item_size as f64 / post_residual as f64;
            if frac > 0.8 {
                score -= 70.0;
            } else if frac > 0.5 {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here: penalize leaving large stranded residue.
            score += (post_residual as f64 - (next_item_size as f64)) * 0.5;
        }
    } else {
        // Last item: prefer zero residual.
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: keep empty bin as fallback unless current fit is poor.
    if bin_residual == bin_capacity {
        // Baseline score for opening a new bin: proportional to item size class.
        let size_class = (item_size / 10) as f64;
        score = 50.0 + size_class * 8.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open new bin
        }
        // Open a new bin when item is large and would leave awkward residue in existing bins.
        if item_size >= 60 {
            score -= 40.0;
        }
    }

    // Progress coupling: as stream advances, prefer consolidating into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's a tight bin — favor it.
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.3;
    } else {
        score += (resid_f - mean_residual) * 0.1;
    }

    // Many open bins: mild penalty for adding to scattered bins, favor filling existing.
    if open_bins_count > 5 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual below the minimum conceivable item size (1) is impossible,
    // but residuals that no realistic next item can use are dead space.
    // Treat post_residual in [1, 12] as near-dead: quadratic penalty.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - pr) * (13.0 - pr) * 1.5;
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize creating a gap smaller than the lookahead item when the
    // lookahead could otherwise have used this bin's space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += (next_item_size as f64 - pr) * 2.0;
    }
    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing
    // bins (penalize new-bin candidate relatively more).
    let pressure = open_bins_count as f64 * 0.6;
    if bin_residual == bin_capacity {
        score += 15.0 + pressure;
    }

    // Late in the stream, tighten up: dead space matters even more.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.5 * progress;

    // Mild preference for bins tighter than average (better packing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual equals next item size -> very strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Near matches: small gap so next item still fits snugly.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Reward decreases as the gap grows; small gaps are good fits.
        score -= (12.0 * (-gap / 25.0).exp()).max(0.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead: penalize proportionally to wasted fraction.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.35 * waste;
    }

    // Penalize very small post residuals (unusable slivers) more than linear.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Compare against mean residual: prefer bins whose post residual stays near the mean
    // (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Early in the stream, be slightly more willing to fill existing bins tightly;
    // later, keep flexibility for large future items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: only attractive when item is large relative to capacity
    // or no good fits exist; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 18.0 * (1.0 - large_item);
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio through the stream
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: penalize large post_residual non-linearly
    let pr = post_residual as f64;
    score += (pr * pr) / (bin_capacity as f64 * 0.5);

    // Lookahead: if the next item fits in the post residual, reward this bin strongly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // creating dead space that the next item cannot use
            score += (post_residual as f64).min(next_item_size as f64) * 0.25;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        // many alternatives: prefer bins where the item fits snugly among others
        score += 1.5;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless the fit is poor
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
        // If the item is large relative to capacity, opening a fresh bin is more acceptable
        score -= (item_size as f64 / bin_capacity as f64) * 4.0;
    }

    // Prefer bins with below-average residual (fills fuller bins first)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild pressure to consolidate as the stream progresses
    score -= progress * 2.0;

    // Penalize very small unusable leftovers, scaled by how late we are
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress * (1.0 - progress) * 4.0; // peaks at 0.5, smooth
    score -= norm_post * norm_post * (1.0 + t) * 30.0;
    score += norm_post * norm_post * norm_post * 20.0;
    // Penalize dead space relative to mean residual
    let dev = pr - mean_residual;
    score += dev * dev / (cap * cap) * 15.0 * (0.5 + progress);
    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 40.0;
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }
    // Lookahead: reward leaving space for next item, penalize waste
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap);
    }
    // Mild pressure to consolidate as bins accumulate
    score += (open_bins_count as f64).ln() * 2.0 * progress;
    // New-bin candidate: only attractive when remaining open bins are poor fits
    if bin_residual == bin_capacity {
        score -= 12.0;
        score += 20.0 * (1.0 - fit_ratio.min(1.0));
        if fitting_bins_count > 2 {
            score += 30.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity
    let post_mod = post_residual % bin_capacity;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Reward tiny dead space (perfect or near-perfect fits)
    if post_mod == 0 {
        score -= 40.0;
    } else if post_mod <= bin_capacity / 10 {
        score -= 15.0;
    } else if post_mod <= quarter {
        score -= 4.0;
    } else if post_mod >= half {
        // large leftover is reusable
        score -= 6.0;
    } else {
        // awkward middle dead space (just above half down to quarter)
        score += 5.0;
    }

    // Integer-division threshold: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact class match: next item fills remainder tightly
            if post_residual - next_item_size <= bin_capacity / 10 {
                score -= 12.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; dead space risk
            score += 8.0;
            // harmonic check: post_residual in a "hard to fill" class
            if post_mod > half && post_mod < bin_capacity * 3 / 4 {
                score += 4.0;
            }
        }
    } else {
        // last item: strongly prefer any bin that fits
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // opening a new bin wastes the residual of existing bins; penalize
        score += 25.0;
        // but a fresh bin is good if the item is huge and nothing fits elsewhere
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // early stream: be more willing to open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Prefer bins below mean residual (keeps residuals balanced)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Slight preference for tighter bins overall
    score += (1.0 - (bin_residual as f64) / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward fitting into bins that cannot fit the next item (no waste of a useful bin).
    if next_item_size > 0 && post_residual < next_item_size {
        score -= 8.0;
    }

    // Pressure from number of open bins: prefer consolidation when many bins are open.
    score += (open_bins_count as f64) * 0.6;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for bins tighter than the mean residual (keep loose bins loose).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Early in stream, be more willing to open bins (keep flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0;

    // New-bin candidate: neutral-ish baseline so it wins only over genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space (unusable slivers)
        if post_residual < 10 {
            score += 60.0;
        }
        // 2-step lookahead: reward bins whose post_residual matches next item
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 400.0;
            } else if post_residual >= next_item_size {
                let gap = (post_residual - next_item_size) as f64;
                score -= 150.0 * (-gap / 20.0).exp();
            } else {
                // next item cannot fit here: dead space likely
                let gap = (next_item_size - post_residual) as f64;
                score += 40.0 * (1.0 - (-gap / 30.0).exp());
            }
        }
    }

    // Tightness reward: filling a large fraction of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 80.0 * fill;

    // Deviation from mean residual: prefer bins that are outliers (large residual absorbs item)
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.3 * dev;
    } else {
        score += 0.3 * (-dev);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so open bins are preferred unless fits are terrible
        score += 120.0;
        // if item is large relative to capacity, a fresh bin is fine
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 100.0;
        }
        // late in stream, avoid scattering
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
        // if many bins already open and mean residual is low, new bin is reasonable
        if mean_residual < item_size as f64 {
            score -= 80.0;
        }
    }

    // Slight preference for fewer open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize leaving dead space that cannot be filled by the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // next item can follow into this bin
        } else if post_residual > 0 && post_residual < 10 {
            score += 6.0; // tiny dead space
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    score += (open_bins_count as f64) * 0.8;

    // Prefer bins whose residual is below the mean residual (more filled bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Time horizon: early in the stream, be more willing to open new bins for large items;
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when item is large and progress is early,
        // or when the item would leave a large unusable gap in any existing bin.
        let large_item_bonus = (item_size as f64 / 100.0) * 10.0;
        score -= large_item_bonus * (1.0 - progress) * 0.6;
        // Penalize opening new bins when plenty of fitting bins exist.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    } else {
        // Existing bin: mild bonus late in the stream.
        score -= progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let norm_item = item / cap;

    // Base: penalize post residual with a non-linear (quadratic) waste term.
    let mut score = pr * (1.0 + 0.6 * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, push tight fits harder.
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward filling the bin tightly: subtract a cubic in (1 - norm_pr) weighted by item size.
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * tightness * norm_item;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        // Mild penalty when many bins compete, encouraging consolidation.
        score += 0.4 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            // Next item won't fit here: slight penalty proportional to overshoot.
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    // Penalize divergence from mean residual (smooth quadratic), encouraging balance.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference to keep open bin count low early, higher flexibility late.
    score += open_bins_count as f64 * (0.3 - 0.25 * progress);

    // Discourage opening new bins when a decent fit exists in an open bin.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic-class archetype: classify residual space into integer classes
    // (perfect / tight / dead / large) and couple with lookahead and scarcity.

    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual via capacity fractions ---
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // 0..1

    // Perfect fit: strongest reward (subtract heavily)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        // Tight but near-perfect: small dead space, still good
        score -= 25.0 - frac * 10.0;
    } else if post_residual <= 30 {
        // Dead-space class: penalize unusable slivers
        score += 8.0 + (30.0 - pr) * 0.2;
    } else if post_residual <= 50 {
        // Mid class: mildly attractive
        score -= 3.0;
    } else {
        // Large residual: keep flexible, slight penalty so we prefer
        // filling bins with tighter fits first (best-fit flavor)
        score += 2.0 + (pr - 50.0) * 0.05;
    }

    // --- Integer-division thresholds on post_residual ---
    // Reward residuals that are multiples of common item sizes (10,20,25,50)
    let mod_classes = [(10u32, 4.0), (20, 5.0), (25, 5.0), (50, 6.0)];
    for (m, r) in mod_classes.iter() {
        if post_residual % m == 0 && post_residual > 0 {
            score -= *r;
        }
    }

    // --- Lookahead coupling: does next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Good: bin remains useful for the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 - slack * 0.05; // reward tighter next-fit
        } else {
            // Next item cannot use this bin's remainder
            score += 3.0;
        }
        // Harmonic pairing: next item exactly consumes remainder
        if next_item_size == post_residual {
            score -= 12.0;
        }
    } else {
        // Last item: only perfect fits matter
        score += frac * 5.0;
    }

    // --- Scarcity: last fitting bin (last chance before new bin) ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: default neutral-ish cost.
        // Attractive early in the stream or when few bins are open,
        // unattractive when some existing bin fits well (post_residual small).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0
            - 20.0 * progress                 // later stream: prefer closing old bins
            - 2.0 * (open_bins_count as f64).min(8.0).sqrt() * 2.0
            + (item_size as f64) * 0.15;      // big items justify fresh bins
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // --- Mean-residual drift: prefer bins near the mean (balance) ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Fit quality relative to item size: prefer bins where item dominates residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score += (1.0 - fit_ratio) * 6.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Open-bin pressure: mild penalty per open bin to consolidate.
    score += open_bins_count as f64 * 0.4;

    // New-bin candidate: only attractive when current fit is bad or no good option.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10;
        if poor_fit || (fitting_bins_count == 1 && fit_ratio < 0.5) {
            score -= 5.0;
        } else {
            score += 12.0 + open_bins_count as f64 * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 30.0; // perfect chain
        } else {
            score -= 15.0 * (1.0 - next_fit_gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // next item does NOT fit in post_residual: dead space penalty proportional to leftover
        score += 10.0 + 0.5 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins whose post_residual deviates favorably
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent open bins exist (new-bin candidate has residual == capacity)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // early stream: opening bins is cheap; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract more when post_residual is small
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize creating "dead space" that no future item can plausibly use.
    // Smallest plausible item is ~1, but practical min granularity: penalize
    // residuals that are awkwardly small but nonzero.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 8.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 6.0 * chain_quality;
        } else {
            // Next item won't chain here; penalize proportionally to wasted lookahead
            score += 2.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else (e.g., item large, residuals fragmented).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: prefer reusing open bins when decent fit exists.
        score += 15.0;
        // If open bins are crowded (mean residual small relative to item), a new
        // bin becomes more attractive.
        if (mean_residual as u32) < item_size + 5 {
            score -= 20.0;
        }
        // Late in the stream, avoid leaving many open bins with tiny residuals.
        if progress > 0.7 && mean_residual < 15.0 {
            score -= 5.0;
        }
        // If many bins already fit, discourage opening a new one.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0).min(3.0);
        }
    }

    // Mild preference for bins whose residual is above average (balance load),
    // keeping some bins available for large future items.
    let residual_gap = bin_residual as f64 - mean_residual;
    score -= 0.05 * residual_gap;

    // Encourage consolidation when many bins are open.
    if open_bins_count > 4 {
        score += 0.3 * (open_bins_count as f64).ln() * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer bins with small post-residual (tight fit)
    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, larger residuals are more acceptable; later, penalize them super-linearly.
    let progress_coupling = post * post / cap * (0.25 + 1.75 * progress);
    score += progress_coupling;

    // Reward high fill ratio with a saturating smooth term
    let fill = 1.0 - post / cap;
    score -= cap * (fill * fill) * 0.5;

    // Penalize post_residual that cannot fit a typical (next) item smoothly
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        let unusable = (nxt - post).max(0.0) / nxt.max(1.0);
        score += 8.0 * unusable * unusable;
        // Reward leaving room for the next item
        let room = (1.0 - (post - nxt).abs() / cap).max(0.0);
        score -= 4.0 * room * room;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, favoring the tightest
        score += 2.0 * ((fitting_bins_count as f64 - 1.0).ln());
    }

    // New-bin candidate: make it unattractive unless open bins are very full
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / cap;
        score = cap * (1.5 - 0.5 * progress) - 30.0 * mean_fill * mean_fill;
    }

    // Slight preference for bins below mean residual (balances load)
    score += 0.05 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are preferred.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // dead-space penalty grows for residuals that are hard to fill
        let cls = pr % 10;
        let penalty = match cls {
            0 => -8.0,          // round residual: very reusable
            5 => -3.0,          // half-decade: reusable
            2 | 4 | 6 | 8 => 2.0,
            _ => 6.0,           // odd small remainder: awkward
        };
        score += penalty;

        // Large residuals are fine (bin still flexible); mid-range residuals are worst
        let frac = pr as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 10.0 * (frac - 0.5);
        } else if frac < 0.15 && pr > 0 {
            score += 12.0 * (0.15 - frac); // tiny slivers are dead space
        }
    }

    // Lookahead: does post_residual exactly fit the next item? Big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 20.0; // near-perfect chain
            }
            score -= 5.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; residual becomes a waiting slot
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer tightening existing ones over spreading
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in stream: keep bins flexible (favor larger post_residual slightly)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual < 15);
        if desperate {
            score -= 25.0;
        } else {
            score += 35.0; // discourage opening new bins when fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: penalize if the next item cannot use the post residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 18.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: penalize spreading across many bins slightly.
    score += open_bins_count as f64 * 0.4;

    // New-bin candidate: mildly penalize opening new bins unless fit is great.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Mean residual coupling: prefer bins below the mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly fits next item -> strongly reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to tightness
            score -= 0.5 * (post_residual as f64 - next_item_size as f64).abs().min(50.0);
        } else {
            // next item will NOT fit here -> penalize wasted residual
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // last item: just minimize post residual
        score += 0.0;
    }

    // Penalize dead space that is too small for any typical item (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins that are already tight (below mean residual)
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to residual
    if bin_residual == bin_capacity {
        score += 120.0 - 0.5 * item_size as f64;
        // open a new bin if next item is large and current bin would be fragmented anyway
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0;
        }
    }

    // Late in the stream, tighten packing (less willing to leave loose residuals)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * progress * post_residual as f64;

    // Slight preference to spread across many open bins when they are plentiful
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space relative to typical item sizes (dead space < 10 is unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
        // Bonus if post-residual exactly matches next item (chained perfect fit).
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else {
        // Last item: minimize final residual aggressively.
        score += post_residual as f64 * 0.5;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Global state coupling: many open bins -> discourage spreading, prefer tight packs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += crowding * 0.05 * (1.0 - progress);

    // Prefer bins with residual below mean (pack the fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        let poor_fits = if post_residual >= item_size { 0.0 } else { 0.0 };
        let _ = poor_fits;
        // Base penalty for opening a new bin, reduced when existing fits are wasteful.
        let min_waste = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 40.0 + desperation * 2.0 - min_waste * 10.0 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: tight fit preferred, but non-linearly — very small residuals are dead space.
    let mut score = pr as f64;
    score += 40.0 * x * (1.0 - x) * (1.0 - progress);

    // Late in the stream, penalize residuals that can't hold typical future items.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let waste = (pr - nxt).max(0.0) as f64;
        score += waste * (0.5 + 0.5 * progress);
        // Reward bins whose post-residual exactly accommodates the next item.
        let gap = (pr - nxt).abs();
        score -= 15.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    } else {
        score += 10.0 * x;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Many open bins: encourage consolidation onto tight fits.
    let crowding = (open_bins_count as f64).ln() / 5.0;
    score += crowding * pr * (0.3 + 0.7 * progress);

    // Mean-residual coupling: deviating far from the mean is risky.
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Penalize residuals in "dead zones" that few item sizes (1..=100) can use.
    // Small residuals (<10) are almost dead; medium residuals pair with small items.
    if post_residual > 0 {
        let usable_class: f64 = if post_residual < 10 {
            0.0
        } else if post_residual <= 25 {
            0.5
        } else if post_residual <= 50 {
            0.8
        } else {
            1.0
        };
        score -= usable_class * 12.0;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Modulo / integer-division harmonic classes on post_residual.
    let mod_class = post_residual % 10;
    if mod_class == 0 {
        score -= 6.0; // residual aligned to decade grid is more reusable
    } else if mod_class >= 7 {
        score += 3.0; // awkward 7..9 slivers
    }

    // Lookahead coupling: does the next item fit exactly / well into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize proportionally to wasted fraction
            score += 5.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: it's the empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin only when current fit is terrible and many bins are open.
        let bad_fit = frac < 0.15 && post_residual > 0;
        let pressure = (open_bins_count as f64) / (1.0 + step_index as f64 / total_items.max(1) as f64);
        if bad_fit && open_bins_count > 2 {
            score -= 8.0 + pressure * 0.5;
        } else {
            score += 20.0; // default: prefer existing bins
        }
    } else {
        // Tight fits into nearly-full bins are excellent: reward small frac.
        score += 8.0 * frac;
        // Deviation from mean residual: prefer bins tighter than average (best-fit flavor).
        score += 0.3 * (mean_residual - pr).abs().signum() * (mean_residual - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A post_residual that is too small to hold even the smallest item is pure waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable dead space
        } else if post_residual < 25 {
            score += 20.0; // risky small gap
        }
    } else {
        score -= 25.0; // perfect fit: fully close the bin
    }

    // Reward bins whose residual exactly matches the item (tight fit).
    if post_residual == 0 {
        score -= 15.0;
    }

    // Dead-space penalty relative to capacity: small post_residual relative to
    // bin capacity means the bin was used efficiently.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but reward using an existing bin when many are open (consolidation).
    score += 0.15 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make opening a new bin costly unless the item is large
    // or no good fit exists. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Opening a new bin is more attractive early in the stream (more items
        // to come that can use the fresh space) and less attractive late.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If the item is large, a fresh bin is safer.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // If many bins are open, prefer fitting into one of them.
        score += 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item would fit exactly in the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // If next item fits comfortably in post_residual, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size + 10 {
        score -= 8.0;
    }
    // If next item cannot fit in post_residual, the gap is likely dead space
    // for the lookahead horizon: penalize.
    if next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins),
    // encouraging balanced consolidation.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match with next item is ideal
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 8.0;
    }

    // Penalize dead space below typical minimum item size
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 2.5;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect closure
    }

    // Compare against mean residual: bins far below mean are scarce-space bins,
    // placing here may waste their flexibility
    let res = post_residual as f64;
    if res < mean_residual {
        score += 0.6 * (mean_residual - res);
    } else {
        score -= 0.3 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: open a fresh bin only when fit elsewhere is poor
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if next item is large and current item is small, fresh bin is attractive
        if next_item_size > 50 && item_size < 30 {
            score -= 30.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Slight preference for fuller bins overall
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits into post_residual (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + (next_item_size as f64) * 0.3;
    }
    // Penalize leaving a residual too small for the next item (dead space).
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large relative to capacity or the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / (bin_capacity as f64);
        // Base penalty for fragmenting into more bins.
        score += 55.0;
        // Large items benefit from a fresh bin.
        score -= tightness * 70.0;
        // Early in the stream, keep bins open longer (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
        // If many bins are open, discourage opening yet another.
        score += (open_bins_count as f64) * 3.0;
    }

    // Prefer bins whose residual deviates from the mean in a usable way:
    // filling bins with above-average residual reduces fragmentation risk.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.05;

    // Mild preference for bins that are already partly filled (consolidation).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Small late-stream nudge toward tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: polynomial in post_residual, modulated by stream progress.
    // Early on, prefer tight fits (low post_residual); later, tolerate slack.
    let progress_tilt = 1.0 + 0.6 * progress;
    let mut score = progress_tilt * (pr + 0.9 * pr * norm_pr + 0.4 * pr * norm_pr * norm_pr);

    // Non-linear interaction: post_residual vs next item lookahead.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        // Reward if post_residual can host next item, scaled smoothly.
        let coupling = (pr - nx) / cap;
        score -= fit_next * (8.0 + 12.0 * coupling.max(0.0)) * (1.0 - 0.3 * progress);
        // Penalize near-miss slack that wastes space for the next item.
        let miss = if pr < nx { (nx - pr) / cap } else { 0.0 };
        score += 6.0 * miss * (1.0 - miss);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - norm_pr);
    }

    // Slight preference for bins below mean residual (consolidating slack).
    score += 0.05 * (mean_residual - pr);

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let pressure = 1.0 / (1.0 + (fitting_bins_count as f64) * 0.5);
        score += 10.0 * pressure * (1.0 - 0.5 * progress);
    }

    // Exact-fill reward (non-linear bump near zero residual).
    score -= 12.0 * (-norm_pr * 20.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: prefer residuals that are "friendly"
    // to future items (multiples of common item sizes / capacity fractions).
    let cap = bin_capacity as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals below the minimum item size are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic class bonus: residual divisible by common item sizes
    // (1..=100 stream, but classic sizes cluster at multiples of 5/10/25).
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        }
        // Residual that is a capacity fraction (25/50/75) is reusable
        if pr == 25 || pr == 50 || pr == 75 {
            score -= 8.0;
        }
        // Awkward primes / odd residuals in mid range are less reusable
        if pr % 2 == 1 && pr > 15 {
            score += 3.0;
        }
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize small leftover further
            score += (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer filling bins with large residuals when many bins are open
    // (reduces fragmentation across the fleet).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / cap) * 10.0 * (1.0 - progress);

    // Mild penalty for deviating from mean residual (keeps bins balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: only attractive when nothing fits well
    // (post_residual == capacity means empty bin).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted late in the stream
        score += 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for even the
    // minimum item (1..100 range, but typical small item ~10) are wasted space.
    // Penalize unusable gaps heavily with a superlinear term.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // dead-space weight grows as gap shrinks below the "usable" threshold
        let usable_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
        if pr < usable_threshold {
            score += (usable_threshold - pr) * 6.0; // unusable micro-gap penalty
        }
        // general superlinear waste penalty
        score += (pr * pr) / (bin_capacity as f64 * 2.0);
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits relative to the item itself
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // extra pressure when many bins are already open
        score -= (open_bins_count as f64) * 0.8;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open,
    // so the new-bin candidate must beat a growing threshold.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize so it only wins when fits are bad
        score += 30.0 + (open_bins_count as f64) * 2.5;
        // but allow new bin early in stream when few bins exist
        score -= 20.0 * (1.0 - (step_index as f64 / (total_items.max(1) as f64)).min(1.0));
        // if mean residual is large, existing bins are roomy; discourage new bin
        score += mean_residual * 0.3;
    } else {
        // mild reward for using an existing bin
        score -= 5.0;
    }

    // Lookahead coupling: if the next item would fit in the post-residual,
    // reward this placement (chaining); otherwise slight penalty for blocking.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely attractive.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this is a chained perfect fit.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 50.0;
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Prefer tight fits relative to the mean residual across open bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when it yields a large usable residual
    // (i.e., item is small relative to capacity); penalize otherwise.
    if bin_residual == bin_capacity {
        score += 60.0 - post_residual as f64 * 0.5;
        // If no existing bin fits well, opening fresh is acceptable.
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
    }

    // Slight preference to fill earlier bins as the stream progresses.
    score += (step_index as f64 / (total_items as f64).max(1.0)) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful again
    // (assume future items >= 1; penalize residuals in awkward band 1..=15).
    if post_residual > 0 && post_residual < 15 {
        score += 12.0 * (15.0 - post_residual as f64) / 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward heavily.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else if (bin_residual as i64) >= (item_size as i64 + next_item_size as i64) {
            score -= 8.0;
        } else {
            // Next item won't chain here; slight penalty unless this is a tight fit.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    // Many alternatives: mildly prefer bins where item leaves the largest usable residual.
    if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only prefer a fresh bin when current fits are poor
    // and the lookahead suggests a big item is coming that would waste this bin's space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > 40.0; // item small relative to bin
        let lookahead_waste = next_item_size > 0 && next_item_size as f64 > mean_residual;
        if poor_fit && lookahead_waste && open_bins_count > 2 {
            score -= 15.0 * (0.5 + progress);
        } else {
            score += 35.0; // default: prefer existing bins
        }
    }

    // Global state: many open bins with high mean residual -> consolidate, avoid new bins.
    if mean_residual > 30.0 {
        score -= 0.05 * mean_residual;
    }
    if open_bins_count > 8 {
        score += 0.3 * (open_bins_count as f64 - 8.0);
    }

    // Time horizon: late in the stream, prioritize closing bins tightly (avoid stragglers).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic sharpening as stream progresses
    let mut score = norm_pr * (1.0 + 1.5 * progress * norm_pr);

    // Non-linear coupling: post-residual usefulness vs. next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let fit_next = (pr - next).abs() / cap;
        score += 0.4 * fit_next * fit_next;
        // Reward exact-ish fit for next item
        score -= 0.6 * (1.0 - fit_next.min(1.0)) * (1.0 - progress);
    }

    // Penalize last-chance bins slightly unless it's a tight fit
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - norm_pr);
    }

    // Mean-residual coupling: prefer bins close to mean residual (keeps diversity)
    let dev = (pr - mean_residual) / cap;
    score += 0.15 * dev * dev;

    // Open-bin pressure: with many open bins, favor filling existing ones
    score -= 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate: penalize mildly, less so when residual would be tiny
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
