pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the minimum item (1..=10)
    // are unusable unless exactly 0 -> treat them as wasted capacity.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 {
        // Usable leftover: mildly reward leaving room for a plausible future item.
        score -= 2.0;
    } else {
        // Perfect fill (post_residual == 0): strongly reward.
        score -= 25.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // encourage consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.35 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are poor. Penalize the fresh bin mildly; the dead-space penalties
    // above will override this when open bins would leave unusable gaps.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream with few bins, opening fresh can still be fine.
        if progress > 0.8 && open_bins_count > 4 {
            score -= 10.0;
        }
    }

    // Slight preference for bins below the mean residual (balances load).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small dead space)
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly-ish here -> big reward scaled by how snug
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 15.0 + 25.0 * snug;
        } else {
            // post_residual too small for next item: penalize dead space, worse if very small
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 10.0 + 20.0 * (1.0 - dead / (next_item_size as f64));
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residual below mean (concentrate waste in few bins)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 35.0;
        // but if lookahead suggests a fresh bin serves the next item better, ease penalty
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Late in stream: be more conservative, prefer compacting into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of the bin filled by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: subtract proportional to how well the item fills the bin
    score -= 30.0 * fill_frac * fill_frac;

    // Penalize dead space: small post_residual is good, but a tiny unusable
    // leftover (< 10) is wasted space; mildly reward exact fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += 5.0; // small unusable fragment
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; leftover becomes dead space
            score += 8.0 * (1.0 - progress);
        } else {
            // next item fits; prefer leaving a reasonable remainder
            let nxt_frac = next_item_size as f64 / bin_capacity as f64;
            score -= 15.0 * nxt_frac;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, decaying with progress
        // (late in the stream, waste matters more, so keep the cost).
        let mut new_bin_cost = 55.0 + 20.0 * progress;
        // If many bins can fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            new_bin_cost += 30.0;
        }
        // If the item is large relative to capacity, a fresh bin is natural.
        new_bin_cost -= 25.0 * fill_frac;
        // If mean residual is small overall, bins are nearly full; new bin ok.
        new_bin_cost -= (mean_residual / bin_capacity as f64) * 20.0;
        score += new_bin_cost;
    }

    // Global state: prefer bins with residual below average (fill the emptier-
    // than-average bins less; prefer tighter bins) — i.e., penalize bins whose
    // residual exceeds the mean (they are the "roomy" ones we want to fill).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap;

    // Mild incentive to keep the number of open bins from exploding early.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 40.0 * poly * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 12.0 * (0.3 + 0.7 * progress);

    // Penalize post_residual that fails to fit the lookahead item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (0.4 + 0.6 * progress);
        } else {
            score -= 3.0 * (1.0 - (ni / pr).min(1.0));
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // Mild penalty coupling with open bin count and mean residual dispersion
    score += 0.15 * open_bins_count as f64 * pr_norm;
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // Smooth dead-space penalty: unusable residual relative to smallest possible item
    score += 6.0 * (pr_norm * pr_norm) * (pr / 10.0).min(4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residue classes modulo 10.
    // Leftovers in "nice" classes (multiples of 10) are more reusable
    // for typical item sizes, so reward them (subtract).
    let post = post_residual;
    if post > 0 {
        let r = post % 10;
        if r == 0 {
            score -= 6.0;                       // perfectly reusable class
        } else if r <= 2 {
            score += 4.0;                       // dead sliver, nearly useless
        } else if r >= 8 {
            score -= 3.0;                       // almost a full decade
        } else {
            score += 1.5;                       // awkward middle class
        }
    } else {
        score -= 12.0;                          // perfect fill: best outcome
    }

    // Integer-division thresholds: big leftovers are flexible, tiny ones are not.
    let post_f = post as f64;
    if post > 0 {
        let decades = post / 10;                // integer division threshold
        score -= (decades as f64) * 1.2;        // reward large usable space
        if post < 10 {
            score += 8.0;                       // penalize sub-10 dead space
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (next_item_size as u32) == post {
            score -= 10.0;                      // perfect chaining
        } else if (next_item_size as u32) < post {
            let fit_frac = n / post_f;
            score -= 4.0 * fit_frac;            // smoother fit reward
        } else {
            let miss = (next_item_size as u32 - post) as f64;
            score += (miss / cap).min(1.0) * 5.0; // next item won't reuse leftover
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over
    // opening a new one, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 9.0 * tightness;               // reward tight use of last fit
        if post < 5 {
            score += 3.0;                       // but avoid near-dead leftovers
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit. Base new-bin score is its full residual,
    // already high; add a mild bonus so it's chosen only for poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 2.0 * (1.0 - progress);        // early stream: slightly cheaper to open
        if post > 0 && (post as f64) < 0.15 * cap {
            score -= 5.0;                       // fresh bin keeps a clean slate
        }
    }

    // Prefer consolidating into bins below mean residual (tighter bins),
    // spreading residual mass evenly across open bins.
    if bin_residual != bin_capacity {
        let dev = mean_residual - post_f;
        if dev > 0.0 {
            score -= (dev / cap).min(1.0) * 3.0; // brings bin below mean: good
        } else {
            score += (-dev / cap).min(1.0) * 2.0; // leaves oversized hole
        }
    }

    // Mild pressure against hoarding many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Gap too small for any item (min size 1): pure dead space.
            score += 40.0;
        } else {
            // Penalize gaps that are small relative to the smallest plausible item,
            // with a non-linear (quadratic) escalation.
            let gap = post_residual as f64;
            score += (10.0_f64 / gap) * (10.0 / gap) * 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // stronger late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Coupling with mean residual: bins far below mean residual are worse to fill
    // (they leave a relatively rich bin underused); bins below mean are favored.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: reward if the leftover space can fit the next item (good chaining),
    // penalize if leftover is nonzero but cannot fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // New-bin candidate: neutral-ish baseline; only chosen if all open bins score badly.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good (base score).
    // Aggressive 2-step lookahead: strongly reward when next item exactly
    // fills the post_residual (perfect chain), penalize when next item
    // cannot fit in post_residual (dead space risk).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportional to fill ratio
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // next item can't use the leftover: penalize dead space
            score += 8.0 + 0.15 * (post_residual as f64);
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving this bin far below mean residual creates fragmented space.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.25 * (pr - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - pr);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is
    // large and would leave a very awkward residual elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin for big items that barely fit anywhere well
        if item_size >= bin_capacity * 9 / 10 {
            score -= 35.0;
        }
    }

    // Mild early-stream preference for consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post-residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Penalize dead space: residuals below the smallest plausible item are waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent (perfect chain).
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here anyway; slight penalty for leaving
            // awkward mid-range residue.
            if post_residual >= 10 {
                score += 5.0;
            }
        }
    }

    // Prefer filling bins that are already relatively full (low residual)
    // to consolidate waste into few bins.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fullness * 20.0;

    // Time horizon: early in the stream, be more willing to spread items
    // across bins (keep flexibility); late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * fit_ratio;

    // Many open bins with high mean residual: encourage using existing bins
    // rather than opening yet another one.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 8.0;
    }

    // New-bin candidate: empty bin has full residual. Make it mildly
    // unattractive unless the item is large and nothing else fits well.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: prefer small post_residual (tight fits)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (dead space is permanent)
    let pr_norm = (pr / cap).clamp(0.0, 1.0);
    let progress_weight = 0.35 + 0.65 * progress * progress;
    score += progress_weight * 18.0 * pr_norm * pr_norm;

    // Reward near-perfect fits smoothly (quadratic trough around fit_ratio ~ 1)
    let fit_gap = 1.0 - fit_ratio;
    score -= 12.0 * fit_gap * fit_gap * fit_ratio;

    // Lookahead coupling: penalize if residual can't smoothly accommodate next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap < 0.0 {
            score += 6.0 * (-gap / cap);
        } else {
            // smooth bonus when next item exactly consumes remaining space
            let g = (gap / cap).clamp(0.0, 1.0);
            score -= 8.0 * (1.0 - g) * (1.0 - g) * g;
        }
    }

    // Last-chance bin: strong smooth reward scaled by how much would be wasted otherwise
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - pr_norm) * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins vs consolidating
    let mean_gap = (mean_residual - pr) / cap;
    score += 3.0 * mean_gap * mean_gap;

    // New-bin candidate: penalize opening a bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).clamp(0.0, 1.0);
        score += 14.0 * (1.0 - tightness) * (0.4 + 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small unusable chunks" are good closers.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits: post_residual in the lowest harmonic class.
    if post_residual <= eighth {
        score -= 12.0;
    } else if post_residual <= quarter {
        score -= 5.0;
    } else if post_residual > bin_capacity / 2 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item exactly fills the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // residual left after chaining next item; penalize awkward leftovers
            let chain = post_residual - next_item_size;
            score += (chain as f64) * 0.35;
            if chain <= eighth {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: dead space penalty scaled
            score += (next_item_size as f64) * 0.10;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with below-mean residual (denser bins) for better packing.
    score += (mean_residual - pr) * 0.15;

    // Modulo-class penalty: residuals congruent to small odd classes
    // (hard to fill later) get a nudge toward selection.
    let m = post_residual % 10;
    if m >= 1 && m <= 4 {
        score -= 2.0;
    } else if m >= 7 {
        score += 2.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this empty bin competes with many fitting bins or the item is large).
    if bin_residual == bin_capacity {
        let base = cap * 0.62; // typical "waste" of a fresh bin
        score = base
            - (fitting_bins_count as f64) * 3.0   // opening new bin worse if many alternatives
            + (item_size as f64) * 0.30;          // large items justify a fresh bin
        if item_size >= bin_capacity * 3 / 4 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight late-stream bias toward closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space that cannot fit the next item is worse
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward using a bin that fits the next item too (chain fits)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Penalize opening a new bin when good fits exist (empty-bin candidate)
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    // Late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
