pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize creating dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0; // moderately awkward residual
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Extra reward if next item fills the bin nearly exactly afterwards.
            let post2 = post_residual - next_item_size;
            score -= 4.0 * (1.0 - post2 as f64 / bin_capacity as f64);
        } else {
            score += 1.5; // breaks the chain
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
        // But if the fit wastes a lot, soften the bonus.
        if post_residual > bin_capacity / 2 {
            score += 12.0;
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // favor consolidating into existing bins rather than opening new ones.
    if open_bins_count > 0 {
        let consolidation_pressure = mean_residual / bin_capacity as f64;
        if bin_residual != bin_capacity {
            score -= 3.0 * consolidation_pressure;
        } else {
            // New-bin candidate: penalize opening bins when existing capacity is ample.
            score += 5.0 * consolidation_pressure + 0.5 * open_bins_count as f64;
        }
    }

    // Time horizon: early in the stream, be more willing to open fresh bins
    // for large items (preserve flexibility); late, squeeze everything in.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 4.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);
    } else {
        score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer placing large items into bins with smaller residuals (best-fit on residual).
    score += 0.02 * bin_residual as f64 * (item_size as f64 / bin_capacity as f64);

    // Exact-fill jackpot.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize small-but-nonzero post residual (dead space), strongest mid-stream
    let dead = norm_pr * (1.0 - norm_pr);
    score -= 30.0 * dead * dead * (1.0 + progress);

    // Reward tight fits (post_residual near 0)
    if pr == 0 {
        score -= 25.0;
    } else if pr <= item_size {
        score -= 8.0;
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (1.0 - progress);
    } else if next_item_size > post_residual {
        score += 5.0 * progress;
    }

    // Prefer bins with lower residual than the mean (denser bins)
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Mild penalty for spreading across many bins late in stream
    score += open_bins_count as f64 * 0.05 * progress;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small remainders is costly.
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        // Penalize awkward leftover classes (hard to fill: 1..9-ish remainders)
        match class {
            0 => score -= 8.0,               // perfectly round leftover, reusable
            1 | 2 | 3 => score += 6.0,       // tiny dead space
            4 | 5 | 6 => score += 2.0,       // moderate
            _ => {}
        }
    } else {
        score -= 25.0; // perfect fit
    }

    // Integer-division thresholds: residual large enough for another typical item
    if post_residual >= 50 {
        score -= 4.0;
    } else if post_residual < 10 {
        score += 5.0;
    }

    // Lookahead coupling: can next item fit in the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // exact harmonic match bonus
            if post_residual == next_item_size {
                score -= 15.0;
            } else {
                let slack = post_residual - next_item_size;
                if slack % 10 == 0 { score -= 3.0; }
                if slack > 30 { score += 3.0; } // wasteful overhang
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is poor or no open bin fits well
    if bin_residual == bin_capacity {
        let tightness = (post_residual as f64) / bin_capacity as f64;
        score = 100.0 - 30.0 * tightness;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 20.0; // big item coming, fresh bin useful
        }
    }

    // Stream progression: early on, be pickier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual - item_size) as f64 * 0.05;

    // Bin-count pressure: many open bins -> consolidate
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64) * 0.3;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0; // nearly unusable
    } else if post_residual < 40 {
        score += 8.0;  // moderately awkward gap
    }

    // Reward tight fits strongly (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + fit_ratio);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 6.0;
        // But a new bin is acceptable if the current fit would leave dead space.
        if post_residual < 10 && post_residual > 0 {
            score -= 20.0;
        }
    } else {
        // Reusing an open bin relieves pressure slightly as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * progress;
    }

    // Lookahead: favor bins whose residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // creates a gap the next item can't use
        }
    }

    // Mild tie-break: prefer bins with residual close to mean (keeps bin pool balanced).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: nearly-zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 800.0;
        } else if diff <= 3.0 {
            score -= 400.0 - diff * 50.0;
        } else {
            // Penalize residuals the next item can't use well.
            score += diff * 0.5;
        }
        // If next item fits exactly into the current residual (pre-placement),
        // this bin is a strong two-item chain candidate.
        if next_item_size == bin_residual {
            score -= 300.0;
        }
        // Penalize if next item cannot fit into post_residual at all
        // (dead space risk), scaled by how much space is wasted.
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // tightly packed already; prefer filling them further.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = resid_f / mean_residual;
        if rel < 0.8 {
            score -= (0.8 - rel) * 200.0;
        } else if rel > 1.3 {
            score += (rel - 1.3) * 100.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }
    // Many fitting bins: mild penalty to prefer consolidation.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 15.0;
    }

    // New-bin candidate: only attractive when it enables a great future fit
    // or stream is early; otherwise penalize opening fresh bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 120.0 + progress * 150.0;
        if next_item_size > 0 && next_item_size >= item_size {
            let chain = bin_capacity - item_size - next_item_size;
            if chain == 0 {
                new_bin_score -= 600.0; // perfect two-item chain in fresh bin
            } else {
                new_bin_score += chain as f64 * 0.6;
            }
        }
        if open_bins_count == 0 {
            new_bin_score -= 1000.0;
        }
        score += new_bin_score;
    }

    // Mild preference for consolidating into fewer open bins.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 60.0;

    // Penalize leaving dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward if next item fits reasonably well
            let next_waste = post_residual - next_item_size;
            score -= (1.0 - next_waste as f64 / bin_capacity as f64) * 15.0;
        } else {
            // next item cannot fit here; slight penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += (over / bin_capacity as f64) * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless
    // current bins fit poorly (large post_residual waste)
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open new bin when existing bins are crowded
        score -= mean_residual / bin_capacity as f64 * 20.0;
        // more open bins -> prefer reusing
        score += open_bins_count as f64 * 2.0;
        // early in stream, opening bins is fine (build diversity)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    // Prefer bins whose residual is close to mean (balance residual pool)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Mild penalty for very full bins being "wasted" on small items
    if item_size < 20 && bin_residual > bin_capacity / 2 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: post_residual, smoothly warped by stream progress.
    let warp = 0.6 + 0.8 * progress * (1.0 - progress) * 4.0; // peaks at 1.0 mid-stream
    let mut score = post * (1.0 + 0.5 * warp * (post / cap));

    // Non-linear penalty for dead space relative to capacity.
    let dead = (post / cap).powi(3);
    score += 40.0 * dead * (1.0 - progress);

    // Reward tight fits with smooth coupling to item size.
    let fit = (item_size as f64 / cap).powi(2);
    score -= 30.0 * fit * (1.0 - post / cap);

    // Last-chance bonus when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        let slack = (post - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - slack).max(0.0) * progress;
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Discourage opening new bins when many bins are open with slack.
    let mean = mean_residual / cap;
    score += 5.0 * mean * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: penalize slightly so it only wins on genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // in [0,1]

    // Integer division thresholds: post_residual buckets of size 10
    let bucket = post_residual / 10;
    let bucket_center = (bucket * 10 + 5) as f64;
    // Reward tight fit: post_residual near 0 heavily rewarded
    score -= 60.0 * (-post_f / 12.0).exp();

    // Penalize residuals in "dead" harmonic classes (hard to fill: e.g. 31..49, 61..79)
    let mod20 = post_residual % 20;
    if mod20 >= 11 && mod20 <= 19 {
        score += 8.0;
    } else if mod20 <= 9 && mod20 >= 1 {
        score -= 3.0;
    }

    // Perfect harmonic residuals (multiples of 10) are valuable — keep them
    if post_residual % 10 == 0 && post_residual > 0 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // harmonic match quality: how close next item fills the remainder
            let after2 = post_residual - next_item_size;
            score -= 25.0 * (-(after2 as f64) / 10.0).exp();
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 0.05 * post_f;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all poor
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap_f;
        // open new bin only if mean residual is small (existing bins nearly full)
        score += 30.0 + 40.0 * pressure;
        // but if item is huge, opening fresh bin is fine
        if item_size >= 60 {
            score -= 25.0;
        }
    }

    // Stream progression: later in stream, be slightly more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Mild tie-break toward bins with residual above mean (balance)
    score += 0.02 * (post_f - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to ever host a future item
    // are pure waste. Penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 60.0;
    } else {
        // Usable gap: mild reward proportional to how well the gap could host
        // the lookahead item, otherwise scale with gap size.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        score += 0.15 * post_residual as f64;
    }

    // Reward bins whose residual is close to the item (tight fit quality).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    // If this bin is the only one that can fit the item, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of open bins.
        score += 30.0 + 4.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is even less desirable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // But if current bins fit poorly (high mean residual waste potential is
        // low residual, so high mean residual means bins are roomy -> prefer new bin
        // only if nothing fits well is handled elsewhere); if lookahead can't fit
        // anywhere else, soften the penalty.
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 15.0;
        }
    }

    // Slight preference to fill bins that are already mostly full.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: prefer bins whose post_residual matches next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 150.0; // perfect chain: this bin fits item, next item fills remainder
        } else if diff <= 5.0 {
            score -= 50.0;
        } else {
            score += diff * 0.6; // penalize leftover space that next item cannot use
        }
        // If next item cannot fit anywhere else but fits here after placement, reward heavily.
        if next_item_size <= post_residual && fitting_bins_count <= 1 {
            score -= 40.0;
        }
    } else {
        // Last item: maximize packing tightness.
        score -= 30.0;
    }

    // Last-chance bin before opening a new one: strong reward to avoid new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize bins with large residuals relative to mean (hoarding space), unless lookahead matches.
    let resid = post_residual as f64;
    let mean_dev = resid - mean_residual;
    if mean_dev > 0.0 {
        score += mean_dev * 0.25;
    } else {
        score += mean_dev * 0.1;
    }

    // Early in the stream, encourage consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 1.5;

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit = next_item_size > 0
            && (post_residual as i64 - next_item_size as i64).abs() <= 5;
        if decent_fit {
            score -= 20.0;
        } else {
            score += 120.0; // discourage opening new bins by default
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize large dead space nonlinearly (wasted capacity is superlinearly bad).
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * waste * waste;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item nearly fills the remaining space too.
        let chain = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * chain;
    }
    // Penalize leaving a residual that is too small for the (likely large) next item.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing existing space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score -= 2.0 * crowding * (mean_residual / bin_capacity as f64);
    // Late in the stream, consolidation matters more.
    score -= 8.0 * progress * fit_ratio;

    // New-bin candidate logic: opening a new bin is only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 15.0;
        // If existing fitting bins are scarce, new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if fitting_bins_count == 1 {
            score -= 5.0;
        }
        // Early in the stream, opening bins is cheaper (builds a portfolio).
        score -= 10.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin gives a clean layout.
        score -= 8.0 * (item_size as f64 / bin_capacity as f64);
        // If open bins are already crowded (low mean residual), a new bin helps.
        score -= 15.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64 / cap;

    // Non-linear interaction: waste penalized more as stream progresses
    let coupling = pr * pr * (1.0 + 2.0 * progress) - pr * progress;
    score += 40.0 * coupling;

    // Penalize dead space that cannot fit a plausible next item
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 8.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild preference for bins tighter than the mean residual
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Penalize opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable" classes
    // (multiples of common item sizes / large chunks), penalize dead space.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -50.0 // perfect fit, strongly favored
    } else if pr % 10 == 0 {
        -8.0 // clean class residual, likely reusable
    } else if pr % 5 == 0 {
        -4.0
    } else if pr < 10 {
        15.0 // tiny dead space, unusable
    } else {
        0.0
    };
    score += class;

    // Integer-division threshold: how many "half-capacity" chunks remain
    let half_chunks = pr / (bin_capacity / 2);
    score -= 6.0 * half_chunks as f64;

    // Coupling with next item: if next item fits into post_residual exactly
    // or leaves a clean class, reward this bin strongly.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let nr = pr - next_item_size;
            if nr == 0 { score -= 20.0; }
            else if nr % 10 == 0 { score -= 10.0; }
            else if nr < 10 { score += 10.0; }
        } else {
            score += 5.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a bad fit
    // unless the fit is good; otherwise prefer opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if pr < 15 && pr > 0 {
            score += 25.0; // bad last-chance fit -> push toward new bin
        } else {
            score -= 12.0; // decent last-chance fit -> keep item here
        }
    }

    // New-bin candidate: neutral baseline, slightly above good existing fits,
    // but below terrible fits. Scale with stream progress (late stream -> consolidate).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 - 15.0 * progress + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin is attractive
        }
    }

    // Mild pull toward bins with below-average residual (fill emptier bins first)
    score += 0.3 * ((post_residual as f64) - mean_residual).max(-50.0).min(50.0) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A gap that cannot even hold the smallest plausible item is pure waste.
    if post_residual < item_size {
        // gap smaller than current item -> likely dead space
        score += 25.0 * (1.0 - post_residual as f64 / item_size as f64);
    }
    if post_residual > 0 && post_residual < 10 {
        // tiny unusable sliver -> strong penalty
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // gap only usable by very small items -> moderate penalty
        score += 15.0;
    }

    // Reward near-perfect fits (low post_residual relative to capacity).
    let fill_ratio = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward this placement (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here after this placement -> slight penalty
        score += 4.0;
    }

    // Open-bin pressure: discourage scattering items across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual alignment: prefer bins whose residual is below average
    // (i.e., already fairly full bins) to keep other bins flexible.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a decent fit (post_residual would be large / dead space elsewhere).
    if bin_residual == bin_capacity {
        // New bin: neutral baseline with mild penalty so tight fits in open
        // bins win, but large dead-space placements lose.
        score += 20.0 - 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits here too; reward proportional to how well it matches
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the post residual: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Compare post_residual relative to mean residual across open bins
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = pr / mean_residual;
        if rel < 0.5 {
            score -= 40.0 * (0.5 - rel); // leaves less dead space than average: good
        } else if rel > 1.5 {
            score += 30.0 * (rel - 1.5); // leaves much more dead space: bad
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
        score += 90.0 + 0.5 * open_bins_count as f64 - 0.3 * pressure;
        // but if no open bin fits well (large post residuals elsewhere), allow new bin
        if mean_residual < item_size as f64 * 0.6 {
            score -= 80.0;
        }
    }

    // Slight time-decay: early stream, be a bit more selective about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strong preference for minimal waste relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Exact or near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Extra reward for near-perfect chain fit.
            let chain_gap = post_residual - next_item_size;
            if chain_gap < 10 {
                score -= 10.0;
            }
        } else {
            // Penalize leaving a residual that almost (but not quite) fits next item.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 12.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize creating small dead space (<10) that no item (min size 1..10) may use well.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    // Global state: if many open bins with large mean residual, prefer consolidating
    // into bins with below-average residual (i.e., fuller bins).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 20.0 * dev; // fuller bin (lower residual) -> lower score -> favored
    }

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base score high, reduced early, raised late.
        score += 55.0 + 45.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0 * (1.0 - progress); // early: fresh bin OK for big chains
        }
    } else {
        // Existing bin gets a late-stream consolidation bonus.
        score -= 10.0 * progress;
    }

    // Mild penalty for opening bins when many are already open late in stream.
    if bin_residual == bin_capacity && open_bins_count > 4 {
        score += 3.0 * (open_bins_count as f64 - 4.0).min(15.0) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr;
    score += 40.0 * pr_norm * pr_norm;

    // Smooth coupling with stream progress: waste tolerance shrinks over time
    let tightness = 1.0 + 3.0 * progress;
    score *= tightness;

    // Dead-space penalty: residuals too small for typical future items
    let dead = (1.0 - (pr / (item_size.max(1) as f64 + 20.0))).max(0.0);
    score += 15.0 * dead * dead;

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 25.0 * fits_next * (1.0 - gap);
        score += 10.0 * gap * gap;
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer filling bins when many are open; penalize spreading thin
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 12.0 * open_norm * pr_norm;

    // Align with mean residual: avoid outliers above the mean
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: make it attractive only when no tight fit exists
    if bin_residual == bin_capacity {
        score = pr + 30.0 + 20.0 * (1.0 - progress) - 45.0 * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in a "usable"
    // residue class (small, item-like sizes 1..=40) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10; // harmonic decade class
        // Favor residues that are themselves plausible item sizes
        if pr <= 40 {
            score -= 12.0 + (40 - pr) as f64 * 0.35; // small leftovers are nearly perfect fits
        } else if class <= 4 {
            score -= 3.0; // mildly friendly residue
        } else {
            score += 2.5; // awkward residue class
        }
    } else {
        score -= 25.0; // perfect closure
    }

    // Integer-division thresholds: how many "average items" still fit
    let avg_item = if step_index > 0 { (bin_capacity as f64 * step_index as f64 / total_items as f64).max(1.0) } else { 50.0 };
    let fits_k = (post_residual as f64 / avg_item).floor() as i32;
    score -= fits_k as f64 * 4.0;

    // Lookahead coupling: does next_item_size fit harmonically in post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        // reward exact/near-exact chained fit (modulo harmony)
        if slack == 0 {
            score -= 20.0;
        } else if slack <= 10 {
            score -= 10.0 - slack as f64 * 0.5;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item won't chain: penalize wasting a large residual
        score += post_residual as f64 * 0.08;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate logic: only open a new bin if all open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        if fragmentation < 0.25 && fitting_bins_count > 0 {
            score += 30.0; // keep using fragmented-but-usable bins
        } else {
            score -= 6.0; // fresh bin is attractive when open bins are nearly full
        }
        // late in stream, prefer consolidation
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 8.0;
    }

    // Mild tie-break toward bins tighter than the mean
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Reward using bins that would otherwise be wasted (large residual, low fill).
    if bin_residual >= 70 {
        score -= 5.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open,
    // unless the fit is tight.
    let pressure = (open_bins_count as f64).ln().max(1.0) * 3.0;
    score += pressure * (1.0 - fill_ratio);

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item could use the post_residual, reward leaving that gap.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            // gap cannot host next item: mild extra penalty for large gaps
            if post_residual > 40 { score += 4.0; }
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // New-bin candidate baseline: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score = 10.0; // forced new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Partial lookahead: next item fits snugly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 / (1.0 + slack);
    } else if next_item_size > 0 {
        // Next item cannot fit: this residual is likely dead space.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Prefer bins with below-mean residual (tighter bins fill up first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Mild reward for many competing bins (keep bin count low naturally).
    score -= (fitting_bins_count as f64).ln() * 5.0;

    // Penalize opening a new bin when decent fits exist late in the stream.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 60.0 * progress;
    }

    // Reward high fill ratio.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item would not fit here; slight penalty proportional to wasted potential
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score -= 0.4 * pressure;

    // Prefer bins whose residual deviates from the mean (consolidate space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in stream, keep bins flexible (mild penalty for tiny residuals);
    // late in stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.08 * post_residual as f64;
    score -= progress * 10.0 * tightness;

    // New-bin candidate: make opening a new bin costly unless current fit is terrible
    // or the item perfectly matches an empty bin pattern (large item).
    if bin_residual == bin_capacity {
        let bad_fit = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 20.0 * bad_fit + 0.5 * post_residual as f64;
        if item_size >= 70 {
            score -= 10.0; // large items start fresh bins happily
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = post / cap;

    // Base: prefer small post_residual (tight fit), non-linearly.
    let mut score = post * (1.0 + 0.8 * fit_ratio * fit_ratio);

    // Penalize dead space that can never host a typical item: quadratically coupled with progress.
    if post > 0 {
        score += 12.0 * fit_ratio * fit_ratio * (1.0 + progress);
    }

    // Reward near-perfect fills.
    if post == 0 {
        score -= 30.0;
    } else if post <= 3 {
        score -= 15.0;
    }

    // Lookahead: penalize if post_residual can't fit the next item (wastes future options),
    // reward if it can, scaled by how snugly the next item fits.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * snug * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New empty bin candidate: penalize mildly so we prefer existing bins,
    // but less so when existing bins are fragmented (high mean residual) or late in stream.
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * (1.0 - progress);
        if mean_residual > 25.0 {
            score -= (mean_residual - 25.0).min(20.0) * 0.3;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual < item_size {
            // empty bin gives full flexibility; small extra penalty only if some bin fits well
            score += 4.0;
        }
    }

    // Mild preference to consolidate into bins with low residuals (fragment cleanup).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" classes (<=10) are perfect closures -> strong reward.
    let post_class = post_residual / 10; // 0..=10 harmonic bucket
    match post_class {
        0 => score -= 60.0,            // near-perfect fill
        1 => score -= 40.0,            // leftover 10..19, still reusable for min items
        2 => score -= 20.0,            // leftover 20..29
        3 => score -= 10.0,
        4 => score -= 5.0,
        _ => {}                        // large leftovers: no bonus
    }

    // Dead-space penalty: leftover that no plausible item (>=1, but typical >=10
    // in classic streams) can use is wasted. Penalize super-tiny but nonzero gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // awkward sliver
    }

    // Coupling with lookahead: if the next item fits exactly into the post
    // residual, this placement sets up a chain -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly
            let snug = (post_residual - next_item_size) as f64;
            score -= 30.0 - snug * 0.5;
        } else {
            // next item won't fit here: mild penalty scaled by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer bins that are already relatively full (small residual before placement)
    // -> classic best-fit bias, modulated by mean residual.
    let rel_fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= rel_fullness * 20.0;

    // Penalize bins far below mean residual (they waste space elsewhere) unless
    // this placement closes them.
    let dev = mean_residual - post_residual as f64;
    if post_residual > 0 {
        score += dev * 0.1;
    }

    // New-bin candidate handling: empty bin has residual == capacity. Only allow
    // it to win when no open bin offers a decent fit, i.e. penalize opening a
    // new bin when decent fits exist, but keep it competitive for huge items.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // opening a fresh bin costs ~1 bin; make it unattractive for small items
        score += 45.0 * (1.0 - item_frac);
        if post_residual == 0 {
            score -= 70.0; // item exactly fills a new bin: excellent
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Small tie-breaker toward using fewer open bins overall.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (low post_residual), with superlinear dead-space penalty.
    let pr = post_residual as f64;
    score += pr;
    score += 0.02 * pr * pr / bin_capacity as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // typical future items (<= 10) are "dead". Penalize heavily the zone
    // 1..=10, and mildly the awkward mid-gap zone.
    if post_residual >= 1 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 6.0;
    }

    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 3 {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor
    // filling existing bins, especially the tightest ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose fill state is above
    // average (concentrate waste in few bins).
    let mean_r = mean_residual;
    score += 0.3 * (bin_residual as f64 - mean_r).max(-30.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is truly terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward;
    // if post_residual is just barely too small for the next item, penalize
    // (we stranded the gap).
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only
    // prefer it when the current fit would create significant dead space
    // or when no real bin fits reasonably.
    if bin_residual == bin_capacity {
        // Neutral baseline; the dead-space penalties above on bad fits make
        // this candidate win only when opening is genuinely better.
        score += 5.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if item_size >= 80 {
            score -= 5.0; // big items are fine in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled against mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Exact match for the next item is highly desirable.
        score -= 8.0 * (1.0 - gap / bin_capacity as f64).max(0.0) * (1.0 - gap / (post_residual as f64 + 1.0));
        // Penalize post_residual that is unusable but nonzero relative to next item.
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / nxt);
        }
    } else {
        // Last item: only tightness matters.
        score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: keep it competitive only when current fits are loose.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.05 * open_bins_count as f64;
        // If next item is large, opening a fresh bin now is more attractive.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 6.0;
        }
    }

    // Mild stream-progression pressure to consolidate early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: small leftovers that cannot hold even the next item are wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else {
            score -= 6.0; // leftover still useful for lookahead item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let scarcity = (fitting_bins_count as f64).max(0.0);
        // Acceptable to open a new bin when mean residual across open bins is small
        // relative to the item, or late in the stream.
        let desperation = (mean_residual / bin_capacity as f64) - (item_size as f64 / bin_capacity as f64);
        score += 60.0 - 30.0 * desperation.max(0.0) - 10.0 * scarcity - 15.0 * progress;
    }

    // Mild preference for bins with residual close to item size (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    // Slight global balance: prefer bins whose residual is near the mean residual.
    score += 0.03 * (bin_residual as f64 - mean_residual).abs();

    // Early stream: be a bit greedy about tight fits; late stream: consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * fit_ratio * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: subtract a smooth non-linear function of fit ratio
    score -= 12.0 * fit * fit * (1.0 + progress);

    // Penalize large post residuals non-linearly (dead space grows quadratically)
    score += 4.0 * post_frac * post_frac * bin_capacity as f64;

    // Coupling: residual relative to mean residual across open bins
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        score += 2.0 * (ratio - 1.0) * (ratio - 1.0) * (0.5 + progress);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - post_frac);
    }

    // Lookahead: reward leaving residual that can fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 6.0 * (1.0 - (post_residual as f64 - nx) / bin_capacity as f64);
        } else {
            score += 3.0 * (nx - post_residual as f64) / bin_capacity as f64;
        }
    }

    // New-bin candidate: prefer opening a new bin only when existing bins fit poorly
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress - 8.0 * fit;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Slight preference for consolidating into fewer bins early
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of
    // capacity fractions are more "usable" by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional position within capacity quarters (0..4)
    let quarter = (pr * 4.0 / cap).floor();
    let quarter_pos = pr - quarter * cap / 4.0; // 0..25
    // Reward residuals that sit just above a quarter boundary (tight fit zone)
    score -= 6.0 * (1.0 - quarter_pos / (cap / 4.0));

    // Modulo arithmetic on post_residual: dead space classes
    // Residuals in [1..10] are almost unusable (min item size small, but waste)
    if post_residual > 0 && post_residual < 6 {
        score += 25.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 30.0; // perfect closure
    }

    // Integer-division threshold: residual / next_item_size coupling
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // This bin can also host the next item: strong reward
            let fits_next = (post_residual / next_item_size) as f64; // integer division count
            score -= 8.0 + 4.0 * fits_next.min(2.0);
            // Tight fit for next item is ideal (harmonic pairing)
            let gap = pr - nxt;
            if gap < 6.0 {
                score -= 12.0 * (1.0 - gap / 6.0);
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted lookahead
            score += 5.0 * (nxt - pr) / cap;
        }
    } else {
        // Last item: prefer tightest closure
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize opening new bins progressively.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        // But if item is huge relative to typical residual, new bin is fine
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
    } else {
        // Favor bins whose residual is close to the item (tight packing)
        let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
        score -= 10.0 * tightness;
    }

    // Stream progression: early on, be more willing to open bins (explore);
    // later, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score -= 8.0 * progress;
    }

    // Mean residual coupling: if this bin's post residual deviates badly
    // from the fleet mean, penalize (keeps residuals homogeneous).
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward filling the bin deeply (high fill ratio).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Penalize bins whose residual deviates badly from the mean residual
    // (keep the portfolio of residuals balanced).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Open-bin pressure: with many open bins, prefer existing bins over new ones.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: opening a bin should only win if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post residual, reward leaving
    // a useful gap; if not, penalize leaving a gap the next item can't use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Slight early-stream aggressiveness: fewer bins open early, be choosier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: bin becomes exactly full
        } else if next_item_size <= post_residual {
            // next item fits; reward proportional to how well it fills leftover
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * chain_fill;
        } else {
            // next item does NOT fit this bin: penalize leaving awkward gaps
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving a residual near the mean keeps flexibility; extremes penalized.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could still absorb the item,
    // unless this bin is empty (new-bin candidate) and item is large.
    if bin_residual == bin_capacity {
        // new-bin candidate: neutral baseline, slight penalty to prefer reuse
        score += 10.0;
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 20.0; // large item with no home: opening fresh bin is fine
        }
    }

    // Late in the stream, favor closing bins tightly (waste minimization).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * fit_ratio;

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.3 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: post_residual too small to matter later.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Lookahead: if next item fits in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Extra bonus if next item nearly fills post_residual too.
            let combo = (item_size + next_item_size) as f64 / bin_residual as f64;
            score -= 10.0 * combo;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            // Residual too small for lookahead -> penalize moderately.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mut open_cost = 60.0;
        // Early in stream: cheap to open bins; late: expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        open_cost += 40.0 * progress;
        // Few open bins: opening is cheaper (spreading load).
        open_cost -= 3.0 * (open_bins_count.min(10) as f64);
        // If mean residual across open bins is small, opening is more attractive.
        open_cost -= 0.3 * (mean_residual.max(0.0)).min(50.0);
        score = score + open_cost;
    } else {
        // Slight preference for bins with less residual (fill fuller bins first),
        // but avoid over-packing when many bins fit.
        score += 0.05 * (bin_capacity - bin_residual) as f64;
        if fitting_bins_count > 3 {
            score += 2.0;
        }
    }

    // Global balance: prefer bins whose residual is near mean residual (uniformity).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, waste is more costly -> amplify residual penalty.
    let progress_amp = 0.5 + 1.5 * progress * progress;
    score += 0.8 * (pr / cap).powi(3) * cap * progress_amp;

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: if the next item fits the post_residual, reward this placement.
    if nx > 0.0 && nx <= pr {
        let fit_ratio = nx / pr.max(1.0);
        score -= 8.0 * fit_ratio * (1.0 - progress);
    } else if nx > 0.0 {
        // Next item won't fit here; mildly penalize leaving a stranded gap.
        score += 3.0 * (pr / cap) * (1.0 - fit_ratio_smooth(nx, pr));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize spreading across many bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: keep its baseline competitive; favor it late in the stream
    // when open bins have large residuals (poor fits elsewhere).
    if bin_residual == bin_capacity {
        score = 0.35 * cap + 0.2 * mean_residual * (1.0 - progress) - 5.0 * progress;
        if fitting_bins_count <= 1 {
            score += 40.0; // avoid opening a new bin when this is the only fit
        }
    }

    score
}

#[inline]
fn fit_ratio_smooth(nx: f64, pr: f64) -> f64 {
    let r = nx / pr.max(1.0);
    1.0 / (1.0 + (r - 1.0) * (r - 1.0))
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction bands. Residuals in the "small leftover" class are good.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Integer-division classes on post_residual (harmonic buckets of size 10)
    let post_class = post_residual / 10;
    // Reward small classes (perfect fits): class 0..1 excellent
    match post_class {
        0 => score -= 25.0,
        1 => score -= 15.0,
        2 => score -= 5.0,
        3 => score += 2.0,
        4 => score += 5.0,
        _ => score += 8.0,
    }

    // Perfect fit detection via modulo: post_residual divisible by small units
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // Harmonic class of the double leftover
            let second_left = post_residual - next_item_size;
            let second_class = second_left / 10;
            score -= 10.0 - second_class as f64 * 2.0;
            if second_left % 10 == 0 { score -= 4.0; }
        } else {
            // Next item cannot follow here; penalize mildly, more if this bin
            // would be left with an awkward mid-range residual
            score += 4.0 + 6.0 * (0.5 - frac).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Cost of a new bin; cheaper late in the stream when open bins are messy
        score = cap_f * (1.0 + 0.3 * progress);
        if fitting_bins_count == 0 {
            score -= cap_f; // forced new bin anyway
        }
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 15.0; // fresh bin has room for lookahead
        }
    }

    // Avoid fragmenting bins when many bins are open and mean residual is high
    let mean_gap = (mean_residual - post_f).abs();
    score += 0.05 * mean_gap * (open_bins_count as f64).sqrt();

    // Mild tie-breaking toward fuller bins
    score -= 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver: worst outcome
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 40 {
        score += 8.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover < 10 {
                score -= 10.0; // would create sliver for the item after
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's residue; penalize tight residues more
            score += (10.0 * (1.0 - post_residual as f64 / bin_capacity as f64)).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit. Penalize the empty-bin candidate by the
    // number of open bins (pressure against bin proliferation), but waive the
    // penalty when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let pressure = 12.0 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= pressure; // no alternative: new bin is fine
        } else {
            score += pressure; // prefer reusing an open bin if it fits
        }
    }

    // Open-bin pressure: mild reward for filling bins when many are open.
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with residual far from mean residual (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for tighter fits as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
