    // post-residual, strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits; the leftover after both is dead space — penalize.
            let double_leftover = post_residual - next_item_size;
            score -= 50.0;
            score += double_leftover as f64 * 0.5;
        } else {
            // Next item does not fit here after placement; mild penalty scaled
            // by how badly it misses.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: bins tighter than average are good targets.
    score += (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // and open bins would be left with unusable slivers.
    if bin_residual == bin_capacity {
        let waste_elsewhere = fitting_bins_count as f64;
        let tight_fit_elsewhere = (item_size as f64 / bin_capacity as f64) > 0.6 && waste_elsewhere <= 2.0;
        if tight_fit_elsewhere {
            score -= 20.0; // allow opening when item is big and few alternatives
        } else {
            score += 150.0; // discourage opening new bins generally
        }
    }

    // Late in the stream, be greedier about tight fits to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Tight-fit reward: quadratic bonus for small post residuals.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: reward bins whose post-residual can host the next item,
    // scaled by how large that next item is (chaining potential).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = next_item_size as f64 / bin_capacity as f64;
        score -= 6.0 + 10.0 * chain;
    } else if next_item_size > post_residual && post_residual < next_item_size {
        // Penalize creating dead space that the lookahead item cannot use.
        score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin should only win when existing
    // fits are poor. Base penalty proportional to how many bins already fit.
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Late in the stream, avoid proliferating bins; early, allow fresh bins.
        score += 8.0 + 10.0 * (1.0 - progress) * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 6.0 * fitting_bins_count as f64;
        }
        // If the item leaves a residual close to the next item size, a fresh
        // bin is actually attractive (clean packing).
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 10.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer filling
    // already-loose bins rather than fragmenting space further.
    if !is_new_bin {
        let gap = mean_residual - bin_residual as f64;
        if gap > 0.0 {
            score -= 2.0 * gap / bin_capacity as f64;
        } else {
            score += 2.0 * (-gap) / bin_capacity as f64;
        }
    }

    // Mild penalty for very large dead space overall (unusable残 below min item size 1..100).
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0; // tiny slivers are worthless; prefer exhausting them
    } else if post_residual >= 10 && post_residual < 25 {
        score += 2.0; // awkward mid-range dead zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional utilization of the bin after placement
    let util = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Smooth non-linear reward for tight fits (quartic in utilization)
    score -= 12.0 * util.powi(4);

    // Polynomial coupling of post_residual with progress:
    // small residuals matter more early; large dead space penalized increasingly late.
    let pr = post_residual as f64;
    score += progress * (pr * pr) / (bin_capacity as f64 * bin_capacity as f64) * 20.0;
    score -= (1.0 - progress) * (1.0 - pr / bin_capacity as f64).powi(3) * 8.0;

    // Exact-fit bonus (smoothed)
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= 15.0 * tightness * tightness * tightness * tightness;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 5.0 * progress;
    }

    // New-bin candidate: penalize opening new bins when open bins are roomy,
    // but allow it late in the stream or when residual would be tiny/dead space.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
        if next_item_size > 0 {
            let gap = (bin_capacity as f64 - next_item_size as f64).abs();
            score += 0.05 * gap * progress;
        }
        // discourage hoarding bins when few exist relative to stream
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward bins whose post-residual accommodates the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // penalize bins that strand the next item
        score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Mild coupling with mean residual: prefer bins below mean (fill the emptiest-tight fit)
    score += 0.5 * (mean_residual - post_residual as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post-residual: classify dead space into octiles of capacity.
    // Class 0 (residual <= cap/8): excellent fill, strong reward.
    // Class 3-5 (mid residuals): moderately useful, mild reward.
    // Class 6-7 (large residual left): wasteful placement of a small item, penalize.
    let eighth = cap / 8.0;
    let class = (post / eighth).min(7.0) as u32;
    match class {
        0 => score -= 30.0 + 0.5 * (eighth - post),
        1 => score -= 12.0,
        2 => score -= 4.0,
        3 | 4 => score -= 0.0,
        5 => score += 3.0,
        6 => score += 8.0,
        _ => score += 14.0,
    }

    // Exact fit bonus (item perfectly fills the bin).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic compatibility: does the leftover residual still admit the lookahead item?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // Leftover usable by next item: reward proportionally to how tight that future fit is.
            let future_post = post_residual as f64 - nxt;
            let tightness = 1.0 - (future_post / cap);
            score -= 10.0 * tightness;
        } else {
            // Leftover is dead space for the lookahead item: penalize by the gap.
            let gap = nxt - post_residual as f64;
            score += 0.3 * gap.min(40.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that makes it attractive
    // only when current fits are bad. Scale slightly with stream progress so late
    // in the stream we consolidate more.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.55 * cap + 20.0 * progress;
        // Opening a new bin is bad if many bins are already open with slack.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild pull toward bins with below-mean residual (fill fuller bins first).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Tiny dead-space penalty scaled by class: residuals that only fit items < 10
    // are pure waste (but items can be as small as 1, so only near-zero is dead).
    if post_residual > 0 && post_residual < 3 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest conceivable item (1)
    // or too small to be useful for typical items (<= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Non-linear penalty on wasted residual, scaled by capacity fraction.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Last chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; mild pressure so we still open bins when needed.
    score += (open_bins_count as f64) * 0.35 * waste_frac;

    // Prefer bins whose residual is already below mean (tighter bins),
    // keeping looser bins available for larger future items.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        }
        // If post_residual cannot fit next item but is large, mild penalty
        // for fragmenting unless this bin is nearly full.
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin has neutral base score but
    // should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin while good fits exist.
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        // Late in the stream, slightly prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize leaving
    // residuals too small to ever be useful (dead space below min item size 1
    // is impossible, so treat very small residuals as wasted).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 5.0 {
        score += 12.0 * (5.0 - pr); // near-full but unusable sliver
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item size well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if pr >= nxt {
            // Next item fits perfectly in this bin afterwards: strong reward.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 20.0; // exact 2-chain bonus
            }
        } else {
            // Next item won't fit here afterwards; slight penalty scaled by gap.
            score += 3.0 * (1.0 - pr / nxt);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving below-average residual is good (compact packing).
    score -= 0.5 * (mean_residual - pr);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation onto existing bins.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate (empty bin): penalize unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If no open bin fits, opening fresh is fine (fitting_bins_count
        // already accounts for open bins; new bin call is separate).
        if next_item_size > 0 && (next_item_size as f64) >= 90.0 {
            score -= 10.0; // big next item: keep a fresh bin available
        }
    }

    // Late in the stream: tighten packing, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving residuals that are too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: slight penalty proportional to leftover
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base mild preference against opening new bins when a decent fit exists.
        score += 15.0;
        // But if the item is large and mean residual across open bins is small,
        // opening a fresh bin is attractive.
        let load_frac = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * load_frac * (1.0 - mean_residual / bin_capacity as f64);
        // Late in the stream, avoid proliferating bins.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * t;
        // Few open bins -> new bin is cheap.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Prefer filling bins that are already well-used (larger item/residual ratio).
        let usage = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 8.0 * usage;
        // Prefer bins whose residual is close to mean (balance) slightly.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Time horizon: early in stream, allow more exploratory placements; late, be greedy.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * t * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // reward tight fits (small post_residual) more than linearly
    score -= (cap - post) * (cap - post) / (cap * cap) * 12.0;

    // penalize dead space that cannot fit typical future items
    if post > 0.0 && (post < 10.0 || post > (next_item_size as f64).max(10.0)) {
        score += 6.0;
    }

    // lookahead coupling: if next item fits in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // stream progress: later in stream, prefer consolidating into existing bins
    score += progress * post * 0.5;
    score -= progress * 10.0 * (mean_residual / cap);

    // opening a new bin: penalize unless existing bins are poor fits
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 20.0 * scarcity + 5.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 6.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 60.0 * tight * tight;

    // Harmonic class of post_residual (mod 10 buckets): dead space that
    // cannot host small items (min size 1, common classes 10/20) is penalized
    let cls = post_residual % 10;
    if post_residual > 0 && cls != 0 {
        score += (10 - cls) as f64 * 1.5; // ragged residual is less reusable
    }
    if post_residual >= 1 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    }

    // Perfect fit jackpot
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.25 * next_item_size as f64;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // we consumed space the next item could have used
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = (bin_residual - item_size) as f64;
        score += 40.0 + 0.6 * waste;
        // open new bins more readily early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins below mean residual (denser bins first)
    if bin_residual != bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Integer-division threshold: reward placements leaving residual in
    // "useful" classes (multiples of 10 or >= 50)
    if post_residual >= 50 || (post_residual > 0 && post_residual % 10 == 0) {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Penalize leaving a gap that cannot serve the next item.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 12.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_open_fill = capacity_f - mean_residual;
        let pressure = avg_open_fill / capacity_f; // 0..1
        let openness = 1.0 - (open_bins_count as f64 / 20.0).min(1.0);
        // Base cost of a fresh bin, discounted by pressure and openness.
        score = 40.0 - pressure * 45.0 - openness * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus scaled by how snugly the next item fits after this placement.
            let next_post = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - next_post / bin_capacity as f64);
        } else {
            // Penalize leaving a residual that the next item cannot use.
            let waste = (next_item_size - post_residual) as f64;
            score += 1.5 * waste;
        }
        // Perfect chain: this item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 300.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins with
    // residuals close to the mean (balanced packing) unless it's a tight fit.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it is only chosen
    // when no open bin offers a good fit (its base score is post_residual = C).
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, prefer closing out open bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Many open bins: discourage spreading items too thin.
    if open_bins_count > 10 {
        score += 0.5 * (open_bins_count as f64 - 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't chain here: mild penalty proportional to wasted potential.
        score += 0.05 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many fitting bins: less pressure, mild penalty to keep diversity.
    if fitting_bins_count > 3 {
        score += 0.5 * (fitting_bins_count as f64 - 3.0).min(4.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad host.
    // Empty bin has bin_residual == bin_capacity; make it attractive only for large items
    // or when the item barely fits nowhere well.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Large items deserve fresh bins; small items should reuse.
        score += 20.0 * (1.0 - fill_frac);
        // Late in the stream, discourage proliferation of barely-used bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
        // If many open bins with slack, discourage new bin.
        score += 0.3 * open_bins_count as f64;
    }

    // Global residual coupling: placing into a bin whose residual is near the mean
    // keeps balance; avoid bins far above mean unless tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling bins with larger residual when item is large.
    score -= 0.02 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Early stream: be slightly conservative, prefer reuse to keep bin count low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * (1.0 - progress);
    score += 40.0 * poly * cap * 0.01;
    // reward tight fits more strongly late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);
    // penalize leaving dead space smaller than any plausible item
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (1.0 - pr / 10.0);
    }
    // lookahead: reward residuals that fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0;
    }
    // last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    // new-bin candidate: mild penalty unless open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 15.0 + 2.0 * progress * crowding * 0.1 - 5.0 * (1.0 - progress);
    }
    // mild preference to fill bins below mean residual (balance consolidation)
    score += 0.05 * (mean_residual - pr);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded,
    // near-perfect fits penalized as dead space, mid residuals okay.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score += 30.0 * (6.0 - post_residual as f64);
    } else if post_residual <= 10 {
        score += 8.0;
    }

    // Modulo-10 harmonic classes: residual divisible by 10 is more reusable
    // since item sizes tend to align on decade boundaries.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 10 != 0 && post_residual < 10 {
        score += 12.0;
    }

    // Integer-division thresholds on post_residual: large residuals are
    // flexible, tiny ones are dead space.
    let q = post_residual / 25;
    match q {
        0 => score += 15.0,          // 1..24: nearly dead
        1 => score += 0.0,           // 25..49: moderately usable
        2 => score -= 4.0,           // 50..74: good
        _ => score -= 8.0,           // 75+: very flexible
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual,
    // penalize if next item slightly exceeds it (wasted opportunity).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 40.0;
            } else {
                score -= 10.0;
            }
        } else {
            let gap = next_item_size - post_residual;
            if gap <= 5 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and residual would be tiny dead space.
    if bin_residual == bin_capacity {
        score += 55.0;
        if post_residual <= 5 {
            score -= 70.0; // tiny item: fine to open fresh bin
        }
    }

    // Prefer packing into bins whose residual is close to item_size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Early in stream, be slightly more conservative with open-bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress < 0.3 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // so penalize the empty new-bin candidate when bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * open_bins_count as f64;
    }

    // If the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item cannot fit the leftover and leftover is small, penalize waste.
    else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Prefer bins whose residual deviates below the mean (more filled bins).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Slight preference for older bins as the stream progresses.
    if bin_residual < bin_capacity {
        score -= 1.0 + 2.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // 2-step lookahead: if next item fits exactly into post_residual, strongly reward
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 500.0;
            } else if next_item_size <= post_residual {
                // next item fits: penalize proportionally to wasted pairing potential
                score -= 50.0 * (next_item_size as f64 / post_residual as f64);
            } else {
                // next item does not fit: penalize dead space relative to mean residual
                score += 20.0 * (post_residual as f64 / bin_capacity as f64)
                    * (1.0 + (post_residual as f64 - mean_residual).abs() / bin_capacity as f64);
            }
        }

        // Reward tight fits relative to capacity
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

        // Last-chance bin: strong reward to avoid opening a new bin
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 200.0;
        }

        // Many open bins: prefer consolidating into existing bins
        if open_bins_count > 4 {
            score -= 10.0 * (open_bins_count as f64 / 10.0);
        }

        // Prefer bins with residual close to item usage (tight packing)
        score -= 15.0 * (1.0 - (bin_residual as f64 - post_residual as f64).abs() / bin_capacity as f64);
    }

    // New-bin candidate: penalize unless current bin is a poor fit
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no tight option exists
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 60.0; // fresh bin good for large next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post-residual is small.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Reward placements that leave room for the lookahead item (chained fit),
    // penalize placements that leave a residual just below the next item size (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 12.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            let gap = nxt - post_residual as f64;
            score += 8.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, use it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of bins already fit the item well.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / bin_capacity as f64).powf(2.0);
        score -= 20.0 * pressure;
        score += 10.0 * (fitting_bins_count.min(8) as f64) / 8.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Global balance: prefer bins with residual below mean (filling emptier bins
    // keeps the residual distribution tight).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let x = fit_norm * fit_norm;

    // Base: prefer small post-residual, with non-linear tightening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress) - 15.0 * x * (1.0 + progress);

    // Reward near-perfect fits more aggressively as stream progresses
    score -= 20.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins (smooth coupling)
    score += 0.3 * (pr as f64 - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post-residual smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 - pr).abs() / cap);
    } else if next_item_size > 0 {
        score += 6.0 * progress;
    }

    // Mild penalty for proliferating bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: keep neutral baseline, slightly penalize unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // are more reusable. Penalize "dead" residues that few item sizes can use.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual quadratically (best-fit core with sharpening).
    score += 0.0; // base already post_residual
    let fit_ratio = item_size as f64 / cap;
    score += (post_residual as f64 / cap) * 12.0 * (1.0 - fit_ratio);

    // Harmonic class bonus: post_residual that is a multiple of typical item
    // sizes (mod classes) is more likely to be filled later.
    let mut harmonic_bonus = 0.0;
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            harmonic_bonus += 6.0;
        }
    }
    // Perfect fill is ideal.
    if post_residual == 0 {
        harmonic_bonus += 40.0;
    }
    score -= harmonic_bonus;

    // Penalize tiny unusable slivers (1..10 can't hold any item).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Lookahead: penalize if this placement blocks the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && next_item_size <= bin_residual {
            score += 10.0; // next item no longer fits here
        }
        if post_residual >= next_item_size {
            score -= 5.0; // next item can chain into this bin
        }
        // mod-class lookahead: next item matches residue class of post_residual
        if next_item_size <= post_residual && (post_residual % next_item_size.max(1)) < 5 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only when needed; relax as
        // stream progresses and open-bin count is low.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_penalty = 35.0;
        new_penalty -= 10.0 * progress;
        if open_bins_count == 0 {
            new_penalty = -100.0; // must open
        }
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size > bin_capacity / 2 {
            new_penalty -= 12.0;
        }
        score += new_penalty;
    } else {
        // Prefer bins with low residual relative to mean (tighter bins first).
        score += (mean_residual - pr) * 0.3;
    }

    // Mild preference for keeping few open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable gap
    } else if post_residual < 25 {
        score += 20.0; // hard-to-fill gap
    } else {
        // Reward tight fits that leave a "useful" residual
        score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space relative to bin capacity (non-linear coupling)
    score += 0.4 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * bin_capacity as f64;

    // Open bins pressure: penalize placements that leave gaps while many bins are open
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 15.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or pressure is high
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of opening a new bin
        score -= 25.0 * pressure; // cheaper to open when many bins already open
        if post_residual + item_size > bin_capacity {
            score += 0.0; // no-op guard
        }
        // penalize opening a new bin when an existing bin would be nearly perfect
        if bin_residual >= item_size && (bin_residual - item_size) < 10 {
            score += 50.0;
        }
        // lookahead: opening a new bin is good if next item also fits well in fresh space
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size);
            if fresh_left >= next_item_size {
                score -= 12.0;
            }
        }
    } else {
        // Lookahead: favor placements where post_residual can host the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 10.0;
            } else if post_residual > 0 && post_residual < next_item_size {
                score += 10.0;
            }
        }
    }

    // Stream progression: late in stream, tighten up (avoid opening bins, prefer filling)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    // Mean residual coupling: if mean residual is small, avoid wasting what's left
    if mean_residual < item_size as f64 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual as f64 - next;
            // tighter match to next item is better
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            // bonus if the next item also nearly fills the bin
            if gap <= 5.0 {
                score -= 100.0;
            }
        } else {
            // next item cannot fit here; penalize leaving dead space
            score += 0.5 * (next - post_residual as f64);
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    // Leaving less than average residual is good (tight packing).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize the fresh-bin candidate slightly so we prefer reusing open bins,
    // unless the fit in open bins is poor (handled by dead-space penalties above).
    if bin_residual == bin_capacity {
        score += 50.0;
        // But if next item is large and would pair well with this item in a new bin,
        // make the new bin more attractive.
        if next_item_size > 0 && (item_size + next_item_size) as f64 >= bin_capacity as f64 * 0.95 {
            score -= 250.0;
        }
    }

    // Mild late-stream tightening: as the stream progresses, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // Discourage accumulating many mostly-empty bins.
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 5.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * (next_item_size as f64).min(post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when it beats poor fits.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut nb = 25.0 + 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            nb -= 0.2 * next_item_size as f64; // fresh bin can host lookahead item
        }
        if open_bins_count == 0 {
            nb = -100.0;
        }
        score = nb + post_residual as f64;
        return score;
    }

    // Mild penalty for leaving residuals that are awkward slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Prefer filling bins with below-average residual (consolidate slack).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer minimal post residual (tight fits), scaled smoothly.
    let mut score = pr;

    // Non-linear coupling: tight fits matter more as the stream progresses.
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit a typical future item (smooth quadratic).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += 0.35 * waste * waste / cap;
        score -= 0.25 * gap * gap / cap;
    }

    // New-bin candidate handling: smooth penalty unless it is a last resort.
    if is_new_bin {
        let escape = (fitting_bins_count == 0) as i32 as f64;
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += (20.0 + 8.0 * pressure) * (1.0 - escape) - 30.0 * escape * (1.0 - progress);
    } else {
        // Reward using bins when many can fit (spread load away from near-full bins).
        if fitting_bins_count > 1 {
            score -= 3.0 * (1.0 - (fitting_bins_count as f64 / open_bins_count.max(1) as f64));
        }
        // Last-chance bonus: strongly prefer filling the only fitting bin.
        if fitting_bins_count == 1 {
            score -= 15.0 * (1.0 + progress);
        }
    }

    // Mild preference for bins below mean residual (balance load smoothly).
    score += 0.08 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual bands via integer division.
    // Small post_residual (tight fit) is desirable -> subtract.
    let tight_class = post_residual / 5; // 0..20 harmonic classes
    score -= (20 - tight_class.min(20)) as f64 * 4.0;

    // Penalize residuals that are too small to ever hold the smallest item (1..100 range).
    if post_residual < 1 {
        score += 1000.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual,
    // penalize if next item cannot fit any open bin class.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect pairing bonus, stronger for exact/very-tight matches
            let slack = post_residual - next_item_size;
            score -= 30.0 - (slack as f64).min(30.0);
        } else if next_item_size <= bin_residual {
            // next item could still fit this bin if we placed differently; mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual would be huge) or stream is early with few bins.
    if bin_residual == bin_capacity {
        score = post_residual as f64; // = capacity
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64).sqrt();
        score -= 40.0 * (1.0 - progress) / openness;
        // penalize opening new bin when a decent fit exists elsewhere
        if post_residual < 40 {
            score += 200.0;
        }
        if fitting_bins_count > 0 && item_size as f64 / cap_f > 0.5 {
            score += 60.0;
        }
    }

    // Prefer bins whose residual is close to mean residual (keeps bin states uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Prefer filling larger fraction of the bin.
    score -= (item_size as f64 / cap_f) * 10.0;

    // Modulo-based dead-space penalty: residuals congruent to awkward classes
    // (just above common item sizes) are likely dead space.
    let awkward = [1u32, 2, 3, 4, 6, 9, 11, 19, 21, 26, 31, 51].iter()
        .any(|&r| post_residual == r);
    if awkward {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are unusable
    // dead space since items are >= 1 but small gaps waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // heavy penalty for creating a tiny unusable gap
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit strongly rewarded
    } else {
        // Larger usable gaps: mild quadratic penalty scaled by waste
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 3.0 * waste * waste * 100.0;
    }

    // Reward tight fits: residual barely above item size
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 15.0 * (1.0 - tightness);

    // Open bins pressure: discourage proliferation of open bins
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large relative to the item (poor fits elsewhere)
    if bin_residual == bin_capacity {
        // Base new-bin cost
        score += 10.0;
        // If mean residual is small (bins nearly full), new bin is fine
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
        // If this bin is the last chance anyway, opening new bin is neutral
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit post_residual but could fit bin_residual better elsewhere
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 6.0;
    }

    // Stream progression: late in stream, be more conservative about new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * progress;
    }

    // Deviation from mean residual: prefer bins whose residual is extreme
    // (either near-full or large) to consolidate waste
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 2.0 * dev / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += match_gap * 0.9;

        // Perfect 2-chain bonus: item fills bin so next item fills remainder exactly
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that neither fits next item nor is small waste
        if next_item_size > post_residual && post_residual > 0 {
            score += 8.0; // dead space next step
        }
    } else {
        // Last item: strongly prefer tightest fill
        score += 5.0;
    }

    // Reward tight fits relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 6.0;

    // Relative to mean residual: prefer bins with less residual than average (more full)
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very full
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // Open new bin only if open bins are quite full or many bins already open
        score += 30.0 - avg_fill * 25.0 - (open_bins_count as f64).ln().max(0.0) * 4.0 - progress * 5.0;
        // Still allow new bin if lookahead matches perfectly with fresh capacity
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() <= 2 {
            score -= 22.0;
        }
    }

    // Small absolute waste is always good
    if post_residual <= 3 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual closely matches the item.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 12.0 * (-tightness / 6.0).exp();

    // Penalize leaving a large, awkward post-residual that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space below minimum item size
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item cannot use the leftover; penalize proportional waste
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    } else {
        // last item: just minimize residual
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins with high mean residual: prefer consolidating into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 3.0 * progress;
    }

    // New-bin candidate: only open a new bin when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        } else {
            // opening is attractive only if the best existing fit is bad and mean residual is high
            let bad_fit = (bin_capacity - item_size) as f64;
            score = bad_fit + 30.0 - 20.0 * progress;
            if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
                score -= 10.0; // room for the follow-up item in a fresh bin
            }
        }
    }

    // Slight preference for more-filled bins as the stream matures.
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: penalize large post_residual more as stream progresses
    score += (norm_pr * norm_pr) * cap * (0.5 + progress);

    // Reward tight fits (low post_residual) with a smooth cubic term
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.6;

    // Interaction: prefer bins whose post_residual can host the next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 8.0 * (norm_next * (1.0 - norm_pr)) * cap;
    } else if next_item_size > 0 {
        score += 6.0 * norm_pr * norm_next * cap;
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balance)
    score += 0.15 * ((bin_residual as f64 - mean_residual) / cap).abs() * cap;

    // Late-stream: discourage opening many bins; favor filling existing ones
    score += progress * 5.0 * (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Slight preference for placing larger items into fuller bins
    score -= norm_item * norm_item * 10.0 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class logic: partition post_residual into dead-space classes
    // via integer division thresholds. Residuals <= 10 are effectively dead
    // (smallest item is 1..100, but small leftovers rarely reusable).
    let dead_class = post_residual / 10; // 0..=10 classes
    match dead_class {
        0 => score -= 60.0,             // 0..9 : near-dead, great packing
        1 => score -= 25.0,             // 10..19 : tight but risky
        2 => score += 5.0,              // 20..29 : moderate
        3 => score -= 10.0,             // 30..39 : good landing zone
        4 => score += 8.0,
        5 => score -= 15.0,             // 50..59 : half-bin, very reusable
        6 => score += 5.0,
        7 => score -= 8.0,
        8 => score += 3.0,
        9 => score -= 5.0,
        _ => {}                          // 90..100 : near-empty (new bin)
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot ever fit, penalize dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let waste = post_residual - next_item_size;
            score -= (30.0 - waste.min(30) as f64) * 0.5;
        } else {
            score += 12.0; // post_residual too small for lookahead
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // spread across open bins; penalize unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        let open_penalty = open_bins_count as f64 * 4.0;
        let mean_waste = mean_residual / cap * 40.0;
        score += 55.0 + open_penalty * 0.3 + mean_waste;
        // Fresh bin is attractive only if item is huge relative to capacity
        // and would leave a sliver elsewhere.
        let frac = item_size as f64 / cap;
        if frac > 0.9 {
            score -= 70.0;
        }
        // Early stream: keep bins consolidated.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score += 25.0;
        }
    }

    // Fractional capacity coupling: reward post_residual that is a harmonic
    // fraction of capacity (50, 25/75, 33/66 style) since they compose well.
    let pr = post_residual;
    if pr == bin_capacity / 2 {
        score -= 20.0;
    } else if pr == bin_capacity / 4 || pr == bin_capacity * 3 / 4 {
        score -= 12.0;
    } else if pr == bin_capacity / 3 || pr == bin_capacity * 2 / 3 {
        score -= 10.0;
    }

    // Mild penalty for leaving residual just below common item sizes,
    // pushing placements toward cleaner class boundaries.
    for s in [10u32, 20, 30, 40, 50, 60, 70, 80] {
        if pr >= s && pr < s + 6 && pr != s {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 35.0;
    } else if post_residual < 30 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual is close to item (minimal waste).
    let gap = (bin_residual as i64 - item_size as i64) as f64;
    score -= 20.0 / (1.0 + gap.abs());

    // Lookahead: if next item fits the post-residual exactly-ish, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        if next_gap == 0 {
            score -= 45.0;
        } else if next_gap < 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post-residual unusable for the known next item: penalize.
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from many open bins: discourage spreading, favor new bin when few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Prefer bins below mean residual (fill emptier bins first, keep tight bins tight).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(-50.0).min(50.0);

    // New-bin candidate handling: baseline cost of opening a bin.
    if bin_residual == bin_capacity {
        // Attractive when no good fit exists or bins are very full.
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score = 15.0 - 25.0 * avg_fill;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: tighter fit preferred
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: strong reward scaled by how well it matches
            let match_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 30.0 * match_quality;
        } else {
            // Next item won't fit after placement: penalize, worse when post_residual is dead space
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 12.0 * dead;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly-full bin on a tiny item (poor coupling)
    if item_size < 20 && post_residual > 60 && bin_residual < bin_capacity {
        score += 15.0;
    }

    // Prefer bins with residual below mean residual (denser bins first)
    if bin_residual < bin_capacity {
        let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 8.0 * rel;
    }

    // New-bin candidate: keep it neutral-to-slightly-costly so it only wins when
    // no open bin offers a decent fit (post_residual high on empty bin = 100)
    if bin_residual == bin_capacity {
        // base score is bin_capacity; adjust with lookahead context
        if next_item_size > 0 && next_item_size >= item_size {
            // opening fresh bin may chain well: mild discount when open bins are crowded
            let crowded = (open_bins_count as f64).ln().max(0.0);
            score -= 5.0 + crowded;
        }
        // late in stream, opening new bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Early stream: slightly discourage bin proliferation
    if step_index < total_items / 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that nothing could use (below minimum item size 1..100, use small threshold).
    if post_residual > 0 && post_residual < 5 {
        score += 25.0; // nearly useless sliver
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= 8.0 - 0.05 * snug; // prefer chains that stay snug after next item
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual blocks the next item: mild penalty, worse late in stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a new bin wastes mean residual across open bins.
    if bin_residual == bin_capacity {
        let waste = mean_residual * open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in stream: opening bins is cheap and useful (keeps options open).
        // Late in stream: consolidate into open bins.
        let open_bonus = 20.0 * (1.0 - progress) * (1.0 - progress);
        score = 60.0 + waste * 0.3 - open_bonus - (post_residual as f64);
        // If nothing else fits (only this new bin can), make it attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins with residuals near item_size (perfect-fit coupling).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.02 * gap;

    // Slight penalty for spreading across too many open bins late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear coupling: post_residual weighted by stream progress
    let norm_post = post / cap;
    score += progress * norm_post * norm_post * cap * 0.5;

    // Penalize residual that is unusable for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let shortfall = (nxt - post) / cap;
            score += 25.0 * shortfall * shortfall;
        } else {
            // reward leaving room exactly for the next item
            let fit_gap = (post - nxt) / cap;
            score -= 8.0 * (1.0 - fit_gap).max(0.0);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a fresh bin when current bins fit poorly
    if bin_residual == bin_capacity {
        score -= 5.0 + 10.0 * (1.0 - progress);
    } else {
        // reward tight fits
        score -= (item_size as f64 / bin_residual.max(1) as f64) * 6.0;
        // penalize scattering residual across many open bins
        score += (open_bins_count as f64).ln().max(0.0) * norm_post * 3.0;
    }

    // Smooth interaction with mean residual: prefer bins deviating from mean residual
    let dev = (post - mean_residual).abs() / cap;
    score += dev * dev * 12.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    // (residuals that pair well with small/medium items), penalize dead space.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 5 {
        score -= 30.0; // near-perfect fill
    } else if pr <= 20 {
        score -= 12.0; // still highly usable for typical items
    } else if pr <= 40 {
        score -= 4.0;
    } else {
        score += 6.0; // large leftover: mild penalty, prefer tighter bins
    }
    // Penalize residuals that are "awkward" modulo classes (hard to pair)
    if class == 1 || class == 7 {
        score += 3.0;
    } else if class == 0 || class == 5 {
        score -= 2.0;
    }

    // Integer-division threshold: how many items of average size fit in the post residual
    let avg_item = 40.0f64.max(1.0);
    let fits_count = (pr as f64 / avg_item).floor();
    score -= fits_count * 2.0;

    // Lookahead coupling: does this placement still allow the next item to fit?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0; // keeps future option open
            // harmonic bonus: next item lands exactly in a nice class
            let npr = pr - next_item_size;
            if npr % 10 == 0 || npr == 0 {
                score -= 6.0;
            }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline, encourage only when
    // existing bins would waste a lot of space.
    if bin_residual == bin_capacity {
        score = 55.0 + (post_residual as f64) - (mean_residual / cap) * 10.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0;
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - pr as f64).min(60.0) * 0.05;

    // Many open bins: discourage spreading, favor tight fills
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Mean residual coupling: if open bins are already loose, be stricter here
    if mean_residual > cap * 0.5 && pr > 30 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=10)
    // are unusable — penalize them heavily, scaled by how dead they are.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 25.0;
    }

    // Reward tight fits: the smaller the post_residual, the better (superlinear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: penalize placements that keep many bins open when
    // mean residual is low (bins are nearly full anyway).
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when no open bin gives a decent fit
    // or open bins are very fragmented.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    } else {
        // Favor reusing bins whose residual is small but usable.
        if bin_residual <= 30 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if the next item fits in the post_residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score += 10.0; // would leave a dead gap after next item
    }

    // Mild stream progression: early on, be slightly more willing to open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: crush score toward strongly negative when residual vanishes.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let match_quality = 1.0 - (pr - nxt) / 100.0;
            score -= 60.0 * match_quality * match_quality;
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally.
            score += 0.5 * (nxt - pr).min(100.0);
        }
    }

    // Relative-to-mean-residual term: prefer bins tighter (smaller residual) than average.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.8 * mean_gap;

    // Dead-space penalty for large unusable leftovers (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placements are terrible.
    if bin_residual == bin_capacity {
        score += 150.0;
        // As stream progresses and many bins are open, opening new bins is less costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 80.0 * progress;
    }

    // Slight preference for bins with larger residual (best-fit style baseline).
    score -= 0.3 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale by how small the post-residual is relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward if the next item then fills it almost perfectly.
        let chain_residual = post_residual - next_item_size;
        if chain_residual < 10 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize leaving dead space too small for the next item.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits, else we open a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else {
        // With many fitting bins, prefer the tightest one; mild penalty to spread selection.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Penalize opening a brand-new bin when good alternatives exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let perfect = item_size == bin_capacity;
        if !perfect {
            let waste = (bin_capacity - item_size) as f64;
            score += 55.0 + 0.8 * waste;
            // Early in the stream, opening bins is cheaper; late, prefer consolidation.
            score += 25.0 * progress;
            // If many bins are open with slack, discourage new bins.
            if mean_residual > item_size as f64 {
                score += 15.0;
            }
        } else {
            score -= 50.0;
        }
    }

    // Mild preference for bins with below-average residual (already heavily used).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer minimal post residual, with non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth polynomial coupling with stream progress: later in the stream,
    // waste matters more (fewer chances to fill gaps), so amplify residual penalty.
    let progress_coupling = 1.0 + 1.5 * progress * progress + 2.0 * progress * pr_norm;
    score *= progress_coupling;

    // Reward tight fits: subtract based on item/capacity ratio squared.
    let fit_ratio = item_size as f64 / cap;
    score -= 30.0 * fit_ratio * fit_ratio * (1.0 - pr_norm);

    // Penalize leaving a residual that is too small to be useful for typical items,
    // via smooth term on post_residual relative to mean residual.
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / (mean_residual + 10.0);
        score += 8.0 * rel * rel;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - gap) * (1.0 - gap);
    }

    // Discourage opening new bins when open bins fit reasonably well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // Allow new bin late in stream if residual would be tiny anyway.
        score -= 20.0 * progress * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly
    score -= 12.0 * (1.0 - (post_residual as f64) / cap).powf(3.0);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic class: group post_residual into residue classes mod 10
    let pr_class = (post_residual % 10) as f64;
    score += pr_class * 0.6; // penalize awkward remainders (dead space not reusable)

    // Integer division thresholds: post_residual divisible by common item sizes is reusable
    if post_residual >= 10 {
        let half = post_residual / 2;
        if half >= 10 && (post_residual % 2 == 0) {
            score -= 4.0; // splittable residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; mild penalty proportional to wasted lookahead
            score += 3.0;
        }
    }

    // Discourage spreading across many open bins when mean residual is high
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (post_residual as f64) > mean_residual * 1.5 && open_bins_count > 2 {
        score += 6.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // open new bin early when few bins open (keeps large residuals for large items)
        if open_bins_count <= 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bins whose residual is nearly consumed get a discount.
    let fill_ratio = (bin_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fill_ratio * fill_ratio;

    // Strict dead-space avoidance: residual left below the next item's size
    // (but above zero) is likely unusable -> strong penalty.
    if post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 + gap * 0.6;
    }
    // Very small crumbs (<10) are almost certainly dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Perfect closure gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if this placement lets the next item also fit,
    // reward it (chaining two items into one bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Open-bins pressure: prefer consolidating into existing bins,
    // penalize opening a new bin, more so when many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 18.0 + 0.15 * open_bins_count as f64;
        // But if no existing bin fits well (poor fits everywhere), soften it.
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    } else {
        // Last-chance bin: if this is the only bin that fits, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        score -= 0.1 * fitting_bins_count as f64;
    }

    // Mild stream-progression pressure: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Near-perfect fit: partial reward.
    if post_residual > 0 && post_residual <= 5 {
        score -= 60.0 - (post_residual as f64) * 8.0;
    }

    // Two-step lookahead: reward if the next item fits exactly in the residual left behind.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // Next item won't fit: penalize proportionally to wasted lookahead.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize dead space relative to mean residual (creating unusable gaps).
    if post_residual as f64 > mean_residual {
        score += 0.6 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Discourage opening a new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 + 40.0 * progress;
        // If next item is small, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 50.0;
        }
    }

    // Slight preference for bins with tighter residuals among equals.
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness;

    // Penalize leaving awkward residuals that few typical items could fill.
    // Residuals just below the smallest item (or in awkward bands) are dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    } else if post_residual >= 20 && post_residual < 34 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual > next_item_size {
            score -= 1.5;
        } else {
            // Next item won't fit here; slight penalty for fragmenting.
            score += 1.0;
        }
    }

    // Time horizon: early in the stream, be more conservative (penalize new-bin-ish
    // waste less since many items remain to fill bins); late in the stream, prefer
    // closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> discourage spreading,
    // prefer bins below mean residual (filling up the emptier ones less).
    if open_bins_count > 0 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (fitting_bins_count as f64);
        if post_residual as f64 > mean_residual {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let base = pr + norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Penalize large post-residual more strongly later in the stream
    let late_penalty = norm_pr * pr * (progress * progress);

    // Reward tight fits (small post_residual) with a non-linear bonus
    let tight_fit_bonus = -cap * (1.0 - norm_pr).powi(4) * (0.3 + 0.7 * progress);

    // Coupling with mean residual: prefer bins whose post-residual stays near mean
    let mean_coupling = -((pr - mean_residual) / cap).powi(2) * cap * 0.2;

    // Lookahead: reward post_residual that can host the next item
    let lookahead = if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns { -0.5 * ns * (1.0 - norm_pr) }
        else { 0.3 * (ns - pr) * (1.0 + progress) }
    } else { 0.0 };

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    let last_chance = if fitting_bins_count == 1 { -cap * 0.25 } else { 0.0 };

    // Slight preference for existing bins vs opening new ones as stream progresses
    let open_penalty = if bin_residual == bin_capacity { cap * (0.15 + 0.2 * progress) } else { 0.0 };

    base + late_penalty + tight_fit_bonus + mean_coupling + lookahead + last_chance + open_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit class strongly rewarded
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Modulo classes of post_residual w.r.t. common item sizes (harmonic divisibility)
    let pr = post_residual;
    let div_bonus = |d: u32| -> f64 { if d > 0 && pr % d == 0 { -15.0 } else { 0.0 } };
    score += div_bonus(10) + div_bonus(20) + div_bonus(25) + div_bonus(50);

    // Penalize residuals in awkward dead zones (11..=19, 31..=39)
    if (11..=19).contains(&pr) { score += 12.0; }
    if (31..=39).contains(&pr) { score += 8.0; }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            let tight = (pr - next_item_size) as f64;
            score -= 40.0 - tight.min(40.0);
        } else {
            score += 6.0; // next item won't reuse this residual
        }
    } else {
        // Last item: prefer filling as much as possible
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when current bin fit is poor
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when beneficial
        score = 70.0
            - (item_size as f64 / bin_capacity as f64) * 30.0
            - if fitting_bins_count <= 1 { 20.0 } else { 0.0 }
            - if next_item_size > 0 && next_item_size >= item_size { 10.0 } else { 0.0 };
    }

    // Slight preference to keep fewer open bins early on
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (1..100 range) are pure waste.
    // Penalize any post_residual below the "unusable gap" threshold quadratically.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 {
        score += 50.0 * (10.0 - post_residual as f64) * (10.0 - post_residual as f64);
    }

    // Penalize gaps that cannot fit the lookahead item (k=2) but could
    // otherwise be useful: this creates stranded space.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < next_item_size as u64 {
        score += 8.0 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward a perfect or near-perfect fit strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward if the leftover gap exactly accommodates the next item
    // (chained tight packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening/spreading into many bins,
    // but relax the pressure when this is the last-chance bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing bins fit poorly
        // (large dead space) or this bin is the sole fitting option.
        score += pressure * 3.0;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        if (post_residual as f64) < mean_residual - 20.0 {
            score += 10.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it to avoid opening a new bin.
        score -= 30.0 + pressure;
    } else {
        // Mild preference for bins below mean residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly / well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 / (1.0 + gap);
        } else {
            // Next item cannot fit here; penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.5 * shortfall;
        }
    } else {
        // Last item: prefer minimal leftover, no lookahead concern.
        score -= 4.0 * tightness;
    }

    // Penalize bins whose residual is far below mean residual (fragmented bins),
    // reward bins that are "roomier" than average only if the fit is still decent.
    let dev = (bin_residual as f64) - mean_residual;
    if dev < 0.0 {
        score -= 0.15 * dev; // below-average residual: slightly favored (denser bin)
    } else {
        score += 0.10 * dev; // above-average residual: mildly discouraged
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when current fits are poor
    // (i.e., post_residual here would be tiny but unusable) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty for opening a new bin, softened early in the stream.
        score += 8.0 - 4.0 * (1.0 - progress);
        // If the new bin can host the next item too, make it slightly more appealing.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
    }

    // Mild scaling with item size: prefer placing larger items into bins
    // that still leave reasonable space for typical future items.
    score += 0.02 * (item_size as f64) * ((post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tight).powi(6);

    // Penalize dead space that cannot hold even the smallest plausible item (1).
    if post_residual > 0 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Bonus if post-residual leaves room for next item AND a near-perfect chain.
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        score -= 10.0 * (-((gap as f64) / 20.0)).exp();
    }

    // New-bin candidate logic: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        // Empty bin: post_residual == capacity - item_size.
        score = 25.0 + 60.0 * (1.0 - poor_fit).powi(2);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Late in stream, prefer closing out existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // Many open bins with slack: discourage opening another.
        score += 2.0 * (open_bins_count as f64);
        if mean_residual > item_size as f64 {
            score += 5.0;
        }
    } else {
        // Mild preference to fill bins with larger mean residual (balance load).
        if (mean_residual - bin_residual as f64).abs() < 5.0 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - norm_post;
    let poly = tightness * (1.0 + 2.0 * progress) * (1.0 + tightness * tightness);
    score -= 6.0 * poly * (post_residual as f64);

    // Penalize leaving residuals that are too small to ever be useful
    // (smooth penalty growing with progress).
    let useless = (1.0 - norm_post).max(0.0);
    let dead = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_residual as f64) / 10.0
    } else {
        0.0
    };
    score += dead * (20.0 + 40.0 * progress);

    // Reward using bins whose residual closely matches the item (good fit).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Lookahead: reward if next item can fit into post_residual (chaining),
    // penalize otherwise, scaled by progress.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64) * (1.0 + progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * (gap / bin_capacity as f64) * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit would be terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let poor_fit = (1.0 - fit_ratio).max(0.0);
        score += 30.0 - 40.0 * crowded - 20.0 * poor_fit * (1.0 - progress);
    }

    // Mild penalty when this bin's residual deviates from the mean residual
    // (prefer balanced bin usage), via smooth quadratic term.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.02 * dev * dev / (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions
    let cap = bin_capacity as f64;
    let frac = item_size as f64 / cap;
    let item_class = (frac * 4.0).floor() as i64; // 0..3 harmonic class

    // Class of the post-fit residual gap
    let gap_class = (post_residual as f64 / cap * 4.0).floor() as i64;

    // Reward tight fits: post_residual near a harmonic boundary (mod arithmetic)
    let boundary_dist = (post_residual as i64 % 25) as f64;
    score += boundary_dist * 0.4; // penalize residuals far from class boundaries

    // Perfect / near-perfect fit gets strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual < 10 {
        score -= 120.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (<=10)
    if post_residual < 10 && post_residual > 0 {
        score += 200.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // good: next item can also go here -> reward proportionally
            score -= (next_item_size as f64) * 0.8;
            let combo_waste = post_residual - next_item_size;
            if combo_waste <= 5 {
                score -= 150.0;
            }
        } else {
            // next item cannot use this gap -> penalize by wasted gap size
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Prefer fuller bins overall: deviation from mean residual
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Prefer keeping open bin count low late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 2.0;

    // New-bin candidate: empty bin gets a mild handicap so real bins are
    // preferred unless their fit is bad; harmonic class of item modulates this.
    if bin_residual == bin_capacity {
        score = 60.0 + item_class as f64 * 15.0 - (fitting_bins_count as f64) * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // pair large items with a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are worthless -> heavy penalty multiplier
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits relative to residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones;
    // with few open bins, allow spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // New bin candidate handling: make it attractive only when current bin leaves bad dead space
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline for fresh bin
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count <= 2 {
            // few alternatives -> new bin is fine
            score -= 10.0;
        }
        // lookahead: if next item fits the leftover of this fresh bin, slight bonus
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // existing bin: bonus if it also serves the lookahead item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 5.0; // dead space that blocks lookahead
        }
    }

    // Slight preference for bins below mean residual (consolidate emptier bins)
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let match_quality = 1.0 - (pr - next) / bin_capacity as f64;
            score -= 30.0 * match_quality * match_quality;
        } else {
            // Next item cannot follow into this bin; mild penalty scaled by overflow.
            score += 0.15 * (next - pr).min(bin_capacity as f64);
        }
    } else {
        // Last item: prefer exact fill.
        score -= 20.0 * tightness;
    }

    // Relative to mean residual: prefer bins already tighter than average.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new empty bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 60.0 - 0.5 * waste;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can chain with next item
        }
        if fitting_bins_count <= 1 {
            score -= 40.0; // no good alternative exists
        }
    }

    // Slight preference to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late-stream pressure: tighten up as the stream progresses.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills a large fraction of residual.
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= 60.0 * fill * fill;
    }

    // Penalize small unusable leftovers (< 10 units of dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits for the item (or the item is huge).
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin.
        score = item_size as f64 * 0.5 + 20.0;
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 50.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If the next item is large, a fresh bin may still be valuable.
        if next_item_size > 0 && next_item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is close to the mean (balanced packing),
        // slightly penalize outliers relative to global state.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = next_item_size as f64 / post_residual as f64;
        if next_tight > 0.8 {
            score -= 30.0 * next_tight;
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Penalize leaving a residual too small for the next item (dead space).
        score += 10.0;
    }

    // Time horizon: early in the stream, be conservative with tight fits
    // (keep flexibility); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear emphasis
    let mut score = pr as f64;
    score += 20.0 * norm_post * norm_post * cap;

    // Stream-progress coupling: later in the stream, waste is more costly
    let late = progress * progress;
    score += late * 30.0 * norm_post * cap;

    // Reward using an existing bin over opening a new one, scaled by scarcity of fitting bins
    if bin_residual != bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score -= 15.0 * (1.0 + scarcity);
    } else {
        // New-bin penalty, softened when many bins are open and mean residual is high
        score += 25.0 + 0.5 * mean_residual - 0.1 * open_bins_count as f64;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64 / pr).min(1.0);
        score -= 12.0 * fit_quality;
    } else if next_item_size > 0 {
        // Penalize leaving dead space the next item cannot use
        score += 6.0 * (1.0 - (pr / (next_item_size as f64 + pr)).max(0.0));
    }

    // Smooth coupling: item_size vs bin fill ratio interaction
    let fill = (bin_residual as f64 - pr) / cap;
    score -= 8.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    let frac = post_residual as f64 / cap;
    // Penalize residuals that fall into "dead zone" classes (too small for likely items).
    let dead = if post_residual == 0 { 0.0 }
        else if post_residual < 10 { 40.0 }
        else if post_residual < 20 { 25.0 }
        else if post_residual < 35 { 12.0 }
        else if post_residual < 50 { 4.0 }
        else { 0.0 };
    score += dead;

    // Integer-division thresholds: how well can next_item_size slot into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Lookahead fits: reward exact/near-exact couplings via modulo classes.
            let rem = post_residual % next_item_size.max(1);
            score -= 30.0 - 0.5 * rem as f64;
            if rem == 0 { score -= 15.0; } // perfect harmonic fit
        } else {
            // Lookahead won't fit here: penalize proportionally to wasted potential.
            score += 0.3 * (next_item_size - post_residual).min(60) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when open bins
    // are nearly full (small mean residual) or many bins already exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.5 * cap + mean_residual - 0.15 * open_bins_count as f64 - 10.0 * progress;
        // Prefer new bin if current item leaves a terrible residue class elsewhere.
        if post_residual == 0 { score -= 5.0; }
    }

    // Mild reward for tight fits overall (small post_residual already favored by base).
    let tightness = 1.0 - frac;
    score -= 5.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Non-linear penalty concentrated in the "unusable" small-gap zone (< ~10).
        if dead < 10.0 {
            score += 60.0 * (10.0 - dead) / 10.0;
        }
        // General superlinear pressure on wasted space.
        score += 0.05 * dead * dead / bin_capacity as f64;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to residual used.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            // post_residual too small for next item: mild penalty scaled by gap size.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when not needed.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: prefer bins whose residual is near/below mean
    // (keeps large residuals concentrated in few bins).
    score += 0.2 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if no open bin fits well, allow opening: reduce penalty.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // Next item large: reserve fresh capacity.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward if next item fits into post_residual (partial lookahead bonus,
    // scaled by how snugly it fits).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space too small for the next item (likely wasted).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Penalize large post_residual relative to mean residual (poor consolidation).
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (post_residual == 0
            || (next_item_size > 0 && next_item_size <= post_residual));
        if good_fit_exists {
            score += 100.0; // keep using existing bins when fits are good
        } else {
            score += 5.0; // mildly discourage opening unless necessary
        }
    }

    // Late in the stream, tighten packing further (avoid leftover fragments).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Penalize small dead space that nothing (min size 1) can use.
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in the stream, prefer compacting into few bins;
    // late, allow spreading to reduce dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0 * (mean_residual / bin_capacity as f64);
    score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else {
            let best_gap = (bin_residual - item_size) as f64;
            0.5 * best_gap / bin_capacity as f64
        };
        score = (bin_capacity as f64 - item_size as f64) - 10.0 * poor_fit + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += poly * cap * 0.5;
    // Reward tight fits more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 + progress) * 10.0;
    // Penalize last-chance bins less (favor using them)
    if fitting_bins_count == 1 {
        score -= 5.0;
    }
    // Lookahead: penalize if post_residual can't fit next item but could otherwise
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx && bin_residual as f64 >= nx {
            score += 3.0 + progress * 3.0;
        } else if pr >= nx {
            score -= 2.0;
        }
    }
    // New-bin candidate: neutral-ish baseline, slightly penalized early, eased later
    if bin_residual == bin_capacity {
        score += 2.0 - progress * 2.0 + (open_bins_count as f64) * 0.3;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fraction buckets
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Penalize dead space via integer division thresholds on post_residual
    let k = post_residual / 10; // harmonic bucket index
    score += (k as f64) * (k as f64) * 0.35; // quadratic waste penalty

    // Reward near-perfect fits: post_residual in {0,1,2}
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Modulo arithmetic: post_residual divisible by common item sizes => reusable
    if post_residual > 0 {
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 50, 100] {
            if post_residual % d == 0 {
                harmony += 8.0;
            }
        }
        // post_residual divisible by next item size => perfect chain
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            harmony += 25.0;
        }
        score -= harmony;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward leaving room for next item, scaled by leftover
        score -= 12.0 * ((post_residual - next_item_size) as f64 / cap_f);
    } else if next_item_size > 0 {
        // penalize blocking next item slightly
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize slightly
    // unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        score = 55.0 + 10.0 * frac;
        if mean_residual < 12.0 && open_bins_count > 0 {
            score -= 20.0; // open bins nearly full -> new bin fine
        }
        if next_item_size > 0 && next_item_size > 50 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Mild preference for filling bins with high residual relative to mean
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Progress-based tie-break: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Mid-range awkward gaps (10..=20) get a mild penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 25.0;
    }
    // If next item would NOT fit here anyway, mild reward for using this bin.
    if next_item_size > post_residual && post_residual >= 0 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many bins are open
    // or when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 20.0 * fitting_bins_count as f64;
        }
        // Late in the stream, opening new bins is even less desirable.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Open-bin pressure: prefer consolidating into fewer bins when residuals are large.
    score += 0.1 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step fit: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + gap * 0.15);
    }

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Favor bins whose residual is already below the mean (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
