        if next_item_size > 0 && post_residual == next_item_size {
            score -= 50.0; // fresh bin perfectly set up for the next item
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

