}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space above a small threshold.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) * 0.01;
    } else {
        // Perfect fill is heavily rewarded.
        score -= 50.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item (chaining),
    // penalize leaving a gap that neither fits the next item nor is near-zero.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Dead space that next item cannot use: penalize more when gap is mid-sized.
            let gap = post_residual as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open
    // bin offers a decent fit. Penalize new bins proportionally to how many bins
    // could fit the item and how good the mean fit is.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 10.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
        // If the item is large relative to capacity, a fresh bin is less wasteful later on.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= 15.0 * fill_frac;
    }

    // Global state coupling: prefer bins whose residual deviates from the mean
    // in a way that consolidates space (pack into emptier bins, keep tight bins tight).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for packing into already-open bins as stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual cost, with non-linear polynomial coupling to progress.
    // Early in the stream (progress ~ 0), residual space is more valuable (future items
    // can use it), so we discount large post_residuals slightly; late in the stream,
    // tight fits (small post_residual) matter most.
    let mut score = pr
        - 30.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress)
        + 20.0 * norm_pr * norm_pr * progress;

    // Reward near-perfect fits with a smooth quadratic term.
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize bins whose residual deviates strongly from the mean residual
    // (smooth coupling: creates fragmentation).
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward it
    // with a smooth saturating interaction; otherwise mild penalty proportional
    // to wasted potential.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_frac = 1.0 - (pr - nxt) / cap;
            score -= 12.0 * fit_frac * fit_frac;
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: gaps divisible by 10 are "perfect"
    // residual classes that future items (10..80 grid) can re-use exactly.
    let gap_class = post_residual % 10;
    if gap_class == 0 {
        score -= 12.0; // perfect-fit class: highly reusable
    } else if gap_class <= 3 {
        score += 8.0 + (3 - gap_class) as f64 * 2.0; // dead space risk
    } else {
        score += gap_class as f64 * 0.8; // mild penalty for imperfect classes
    }

    // Integer-division threshold: can next_item_size land exactly in the gap?
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = post_residual % next_item_size == 0;
        if exact {
            score -= 10.0; // chain fit for the lookahead item
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual {
        score += 4.0; // lookahead cannot use this bin's remainder
    }

    // Last-chance bin: strongly reward using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item leaves a perfect-class gap in a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 20.0 - 14.0 * progress - crowding.min(18.0);
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
    }

    // Prefer tighter bins overall: tie-break toward below-mean residuals.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late-stream tightening: near the end, minimize waste aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
