    }

    // Strict dead-space avoidance: small unusable gaps are penalized heavily.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Gap too small for the next item -> likely dead space.
        if next_item_size > 0 && (next_item_size as f64) > gap {
