        }
        // Reward gaps that can still host the lookahead item (pairing).
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 8.0;
        }
    }

    // New empty bin candidate: generally penalize opening new bins,
    // unless no existing open bin can fit (last resort).
    if bin_residual == bin_capacity {
        score += 25.0 + 4.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 60.0; // forced new bin: remove penalty
        }
    }

    // Last-chance existing bin: strongly prefer using it before it is wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, favor placements that
    // leave little residual (closing bins down) rather than spreading.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= open_bins_count as f64 * 0.5 * tightness;

    // Reward high fill ratio of this placement.
    if bin_residual > 0 {
        score -= (item_size as f64 / bin_residual as f64) * 5.0;
    }

    // Mild alignment with mean residual: avoid creating outliers far below mean.
    score += ((mean_residual - post_residual as f64) / bin_capacity as f64).max(0.0) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits (post residual near zero).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            let gap = post_residual as f64 - next;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize dead space creation.
            score += 8.0 + 0.15 * (next - post_residual as f64);
        }
        // Strong chain: current fit is tight AND next item fits the remaining space tightly.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Penalize opening a new bin when good fitting bins exist, unless item is large
    // and would leave a very tight residual (best-fit already handles that).
    if bin_residual == bin_capacity {
        // New-bin candidate: mildly attractive early, penalized as stream progresses
        // and when many bins are open (consolidation pressure).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 30.0 * progress + 1.5 * open_bins_count as f64;
        // But attractive if item is huge (leaves little waste anyway).
        score -= 0.3 * item_size as f64;
    }

    // Penalize very large leftovers that are hard to reuse (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0 * (10 - post_residual) as f64; // small unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let tight_bonus = 1.0 / (1.0 + post_residual as f64);
    score -= 12.0 * tight_bonus;

    // Penalize dead space that can't hold the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.9 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward residual that exactly fits the next item (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalize bins far below mean residual (avoid fragmenting well-packed bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Slight preference for fuller bins over emptier ones.
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fullness;

    // Time horizon: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * fullness;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when it enables a good future chain
    // or when existing bins create large dead space.
    if bin_residual == bin_capacity {
        let mut nb = 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            nb -= 8.0; // fresh bin can host the next item too
        }
        if fitting_bins_count > 0 {
            nb += 3.0 * (fitting_bins_count as f64).ln();
        }
        // Early stream: opening bins is cheaper; late stream: avoid spreading.
        nb -= 10.0 * (1.0 - progress);
        score += nb;
    }

    // Mild penalty for proliferating bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize leftover space, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - norm_pr; // 1 = perfect fit
    score -= 30.0 * tightness * tightness * (0.5 + progress);
    score -= 20.0 * tightness * progress * progress;

    // Dead-space penalty: residuals too small for typical future items.
    let dead_threshold = 0.15 * cap;
    if pr < dead_threshold {
        let d = (dead_threshold - pr) / dead_threshold;
        score += 25.0 * d * d * (1.0 + progress);
    }

    // Last-chance bin: strongly reward using it (avoid opening a new bin).
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * tightness;
    } else {
        // Spread load when many bins fit: mild penalty to avoid fragmentation.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward residual that still fits the next item,
    // penalize residuals that waste space relative to the upcoming demand.
    if next_item_size > 0 {
        let fits_next = pr >= next_item_size as f64;
        if fits_next {
            score -= 8.0 * (pr / (next_item_size as f64 + 1.0)).min(1.0);
        } else {
            score += 6.0 * ((next_item_size as f64 - pr) / cap) * (1.0 + progress);
        }
        // Bonus when post_residual matches next item almost exactly.
        let gap = (pr - norm_next * cap).abs() / cap;
        score -= 12.0 * (1.0 - gap.min(1.0)) * (1.0 - gap.min(1.0));
    }

    // Global context: prefer filling bins when mean residual is high / many bins open.
    score += 0.15 * mean_residual * (open_bins_count as f64).sqrt() / cap;
    score -= 5.0 * progress * (1.0 - norm_item);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 10 are
    // more reusable (typical item sizes cluster on decimal boundaries).
    let post = post_residual as u32;
    let cls = post % 10;
    let class_bonus = match cls {
        0 => 25.0,
        1 | 9 => 12.0,
        2 | 8 => 6.0,
        3 | 7 => 2.0,
        4 | 6 => -2.0,
        _ => -6.0, // cls == 5 : awkward half-slot
    };
    score -= class_bonus;

    // Exact fill is perfect.
    if post == 0 {
        score -= 60.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Reward proportional to how well the next item nests here.
            let slack = (post - next_item_size) as f64;
            let fit_quality = 1.0 - slack / cap;
            score -= 20.0 + 30.0 * fit_quality;
            // Harmonic match between next item and post-residual decade class.
            if (post - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit: penalize leaving a residual smaller than
            // the smallest useful item (dead space), scaled by dead fraction.
            let dead = (next_item_size - post) as f64;
            score += 0.5 * dead;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize when many bins can fit the item but this one is a mediocre fit:
    // compare against mean residual to keep residual balance across bins.
    let prog = step_index as f64 / (total_items.max(1) as f64);
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.15 * mean_gap * (1.0 + prog);

    // New-bin candidate (pristine bin): only attractive if this bin's post
    // residual is unusable dead space or the fit is very poor.
    if bin_residual == bin_capacity {
        // Fresh bin baseline; prefer it when the item is large relative to
        // capacity or when open bins are already fragmented.
        score = 45.0 + 0.3 * item_size as f64 - 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // big next item benefits from a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual below ~10 is effectively dead space (min item size ~10),
    // but items can be as small as 1, so treat < 5 as truly dead.
    if post_residual > 0 && post_residual < 5 {
        score += 500.0;
    } else if post_residual < 15 {
        score += 40.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (item_size + post_residual) as f64;
    score -= 60.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 12.0 * open_bins_count as f64;
    } else {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 15.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item packing
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetically placing next item
            score += slack * 0.5;
            // small bonus if the remainder after next item is small (still usable)
            if slack <= 10.0 {
                score -= 8.0;
            }
        } else {
            // next item cannot follow here; dead space risk grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    } else {
        // last item: just minimize waste
        score += (post_residual as f64) * 0.1;
    }

    // Reward tight fits relative to capacity
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= tightness * 5.0;

    // Penalize bins far from mean residual (prefer consistent fills)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // opening fresh is attractive when next item is large and post_residual tiny
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0;

    // Many open bins: discourage spreading
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post-residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 150.0;

    // Reward using very full bins (small residual before placement)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            score -= (leftover as f64).recip() * 60.0;
            if leftover == 0 {
                score -= 300.0;
            }
        } else {
            // post-residual too small for next item: penalize dead space
            score += post_residual as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: only open a new bin when current fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize opening new bins early / when many bins are open
        score += 120.0 + 50.0 * (1.0 - progress) + open_bins_count as f64 * 3.0;
        // but if mean residual is large (fragmentation), opening is acceptable
        score -= mean_residual * 0.4;
    }

    // Slight preference to place into bins whose residual is below mean (consolidate)
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - x) * (1.0 - x));

    // Reward tight fits, more strongly as stream progresses
    score -= (1.0 - x) * (1.0 + progress) * 15.0;

    // Penalize very small dead space that can never be used later
    let dead = if x > 0.0 && x < 0.1 { (0.1 - x) * cap } else { 0.0 };
    score += dead * (1.0 + progress);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving space for the next item, penalize blocking it
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack_fit = 1.0 - ((pr - n) / cap).abs();
            score -= 5.0 * slack_fit * (1.0 - progress);
        } else {
            score += 6.0 * (1.0 - pr / n.max(1.0));
        }
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.15;

    // Deviation from mean residual: prefer bins near the mean to keep balance
    score += 0.3 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (dead-space classes)
    let residue = (post_residual % 10) as f64;
    if post_residual > 0 {
        score += residue * 0.6; // penalize residuals not on the harmonic grid
    } else {
        score -= 15.0; // perfect fill: strong reward
    }

    // Integer-division thresholds: post_residual bucketed by quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score -= 5.0; // small leftover is fine
    } else if post_residual > 3 * quarter {
        score += 8.0; // huge leftover means item was small in a big bin
    }

    // Fraction of capacity filled
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    score -= fill_frac * 12.0;

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        // extra reward if next item exactly fills leftover (harmonic match)
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space: next item cannot use leftover
        score += (post_residual as f64) * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // pair large items together in fresh bins
        }
    }

    // Stream progression: tighten thresholds late in the stream
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 3.0 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space): residuals < 10 are pure waste
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.6;
    }

    // Open bins pressure: penalize creating many open bins slightly
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening a new bin is attractive if all fits are poor (large dead space elsewhere)
        if post_residual as f64 > mean_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, this placement is ideal — reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        if nxt <= post {
            if gap == 0.0 {
                score -= 180.0;
            } else if gap <= 5.0 {
                score -= 90.0;
            } else if gap <= 10.0 {
                score -= 40.0;
            } else {
                // next item fits but leaves more dead space: mild penalty
                score += gap * 0.15;
            }
        } else {
            // next item won't fit here after placement; penalize proportionally
            // to how badly the residual is mismatched vs. mean residual.
            let mean_gap = (post - mean_residual).abs();
            score += 10.0 + mean_gap * 0.3 + (nxt - post) * 0.2;
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Penalize creating small unusable dead space relative to mean residual.
    let post = post_residual as f64;
    if post > 0.0 && post < 10.0 {
        score += 25.0;
    }

    // Slight preference for keeping mean residual balanced: avoid dumping into
    // bins far below the mean residual (wasteful) early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post > mean_residual + 30.0 && progress < 0.8 {
        score += 8.0;
    }

    // Discourage opening new bins when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize so it only wins when open-bin fits are bad
        score += 30.0 + (100.0 - item_size as f64) * 0.1;
        if next_item_size > 0 && (next_item_size as f64) <= 100.0 - item_size as f64 {
            score += 40.0; // item + next could share a fresh bin, but prefer reuse
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space: post_residual too small for the smallest conceivable item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits into the resulting residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        } else {
            // Wasted slot for the upcoming item; penalize proportionally to overflow.
            let overflow = (next_item_size as f64 - post_residual as f64).min(100.0);
            score += 0.15 * overflow;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer fuller ones (small residual already encoded),
        // but add mild dispersion pressure toward bins below mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bonus = 35.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        // Never open a new bin when the current bin is a perfect fit.
        if post_residual == 0 {
            score += 1000.0;
        }
        // Discourage new bins when many bins are already open and fragmentation is high.
        score += 2.0 * open_bins_count as f64 * progress;
    }

    // Mild penalty for very large residual gaps that likely become dead space.
    if post_residual > 50 {
        score += 0.2 * (post_residual as f64 - 50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr * norm_pr);

    // Penalize very small residuals (dead space), more strongly late in the stream
    let dead = 1.0 - norm_pr;
    score += 18.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Reward tight fits (small post residual) with a smooth quadratic reward
    score -= 12.0 * (1.0 - norm_pr).powi(2) * (1.0 - progress);

    // Lookahead coupling: if next item fits the post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 * (1.0 - ((pr - nxt) / cap).powi(2));
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 4.0 + 8.0 * progress + 0.15 * open_bins_count as f64;
    } else {
        // Slight preference for bins below mean residual (balance)
        score += 0.05 * (pr - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify dead space by
    // capacity fractions (1/8 granularity) — small leftovers are precious.
    let eighth = bin_capacity / 8;
    if post_residual < eighth {
        // Very tight fit: excellent, strong reward.
        score -= 30.0;
    } else if post_residual < 2 * eighth {
        score -= 18.0;
    } else if post_residual < 4 * eighth {
        score -= 6.0;
    } else {
        // Large leftover: bin remains flexible, mild penalty relative to base.
        score += 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic class of the item itself (size / 8 classes).
    let item_class = item_size / eighth;
    let next_class = if next_item_size > 0 { next_item_size / eighth } else { 0 };

    // Lookahead: if the next item exactly fills the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits in the leftover: keep residual modularly compatible.
        let slack = post_residual - next_item_size;
        if slack < eighth {
            score -= 10.0;
        } else {
            score -= 2.0;
        }
    } else if next_item_size > 0 {
        // Next item does NOT fit into this bin's post residual: penalize
        // leaving a residual in a "useless" harmonic band.
        let waste = next_item_size - post_residual;
        if waste <= eighth {
            score += 6.0;
        } else {
            score += 12.0;
        }
    }

    // Integer-division threshold: residual divisible into item classes.
    if post_residual > 0 && item_class > 0 && post_residual % (item_class * eighth.min(1).max(1)) == 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and the item is large (best-fit-for-big-items logic).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = 20.0 + 60.0 * (1.0 - tightness);
        if item_size > bin_capacity / 2 {
            score -= 25.0; // big items deserve fresh bins
        }
        if fitting_bins_count > 0 && item_size <= bin_capacity / 4 {
            score += 30.0; // small items should go into existing bins
        }
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing
    // bins tightly over spreading out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild pressure to use bins with less residual relative to the mean.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: post_residual that is nonzero but too small
    // to hold even the smallest plausible item (<= 10) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Penalize post_residual that cannot fit the lookahead item if it otherwise could.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.15 * next_item_size as f64;
    }

    // Reward exact fit strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 6.0 * tightness;

    // Reward using the last fitting bin (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor packing into existing ones
    // over opening new bins; the new-bin candidate gets residual == capacity,
    // so this also discourages premature bin opening.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Penalize bins whose residual deviates badly from the mean residual
    // (prefer balanced residual portfolio).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate: make it unattractive unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fill.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space super-linearly (wasted capacity is quadratic in smallness).
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Partial credit: closer post_residual to next item is better.
            let gap = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize unusable remainder.
            score += 60.0;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers
    // that fragment the fleet of open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make empty bins generally unattractive so that any
    // reasonable fit in an open bin wins, but allow opening when the fit is bad.
    if bin_residual == bin_capacity {
        score += 450.0;
        // If the item fits poorly anywhere (huge dead space), opening a new bin
        // becomes competitive: scale down the penalty as item_size grows.
        score -= (item_size as f64 / 100.0) * 200.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        // If no open bin can otherwise fit, new bin must be chosen.
        if fitting_bins_count == 0 {
            score -= 10000.0;
        }
    }

    // Mild preference for tighter (fuller) bins among ties.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0;  // moderately awkward
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Slight preference when many bins compete (more choice, less urgency).
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: does this bin's post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: reward proportional to next item size.
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            // Chain broken: penalize proportionally to wasted lookahead potential.
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).min(bin_capacity as f64));
        }
    }

    // New-bin candidate logic: empty bins should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 22.0 - 10.0 * progress;
        // If many open bins are nearly full, opening fresh is cheaper.
        if mean_residual < 25.0 {
            new_bin_cost -= 8.0;
        }
        // If very few bins can fit, opening a new one is more acceptable.
        if fitting_bins_count <= 1 {
            new_bin_cost -= 10.0;
        }
        // Lookahead: empty bin guarantees room for next item.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_cost -= 4.0;
        }
        score += new_bin_cost.max(0.0);
    }

    // Global state coupling: prefer filling bins whose residual is far from mean
    // (balances residuals, keeps a portfolio of usable bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild reward for reducing the number of "wide-open" bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 && progress > 0.5 {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer minimal post residual (tight fit)
    let mut score = pr;

    // Normalized post residual and fill ratio
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // Smooth non-linear coupling: reward high fill with cubic term
    score -= 12.0 * fill * fill * fill;

    // Dead-space penalty: quadratic blow-up for small unusable residuals
    let dead = if pr > 0.0 { pr_norm } else { 0.0 };
    score += 8.0 * dead * (1.0 - dead) * (1.0 - dead);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * fill;
    }

    // Lookahead coupling: penalize residuals that neither fit next item well nor stay useful
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr as f64 - nxt).abs();
        let gap_norm = (gap / cap).clamp(0.0, 1.0);
        // Smooth interaction: reward residuals close to next item size
        score -= 6.0 * (1.0 - gap_norm * gap_norm);
        // If next item fits exactly-ish after this placement, big reward
        if nxt <= pr as f64 {
            score -= 4.0 * (nxt / cap);
        }
    } else {
        // Last item in stream: residual is pure waste
        score += 15.0 * pr_norm;
    }

    // Stream-progress coupling: early on, keep bins flexible (favor moderate residuals);
    // late in stream, aggressively fill existing bins rather than opening new ones
    let flexibility = (pr_norm * (1.0 - pr_norm) * 4.0).clamp(0.0, 1.0);
    score += 10.0 * flexibility * (1.0 - progress);
    score -= 8.0 * progress * fill;

    // Mean-residual context: penalize bins far from the fleet mean (fragmentation)
    let dev = ((pr - mean_residual) / cap).abs();
    score += 3.0 * dev * dev;

    // Many open bins: discourage spreading, prefer filling existing bins
    let ob = open_bins_count as f64;
    score += 0.15 * ob * (1.0 - fill);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
