    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit reward (harmonic class 0 mod capacity fraction).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Quantized residual classes: residual mod 10 harmony.
    let res_class = post_residual % 10;
    score -= (10 - res_class) as f64 * 0.5;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let fit_ratio = nxt / pr;
            score -= 20.0 * fit_ratio * fit_ratio;
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers less
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = pr > item_size as f64; // leftover larger than current item => wasteful placement
        if fitting_bins_count == 0 || (poor_fit && mean_residual < 30.0) {
            score -= 35.0 + 20.0 * progress;
        } else {
            score += 30.0;
        }
    }

    // Slight preference for filling bins below mean residual (balance pressure).
    score -= 0.05 * (mean_residual - pr);

    // Progress-based tightening: later in stream, avoid leaving mid-size gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mid_gap = (post_residual > 20 && post_residual < 50) as i32 as f64;
    score += mid_gap * 8.0 * progress;

    // Integer-division threshold: bins that can host another half-capacity chunk.
    if post_residual / 2 >= 10 && post_residual % 2 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

