    let open_pressure = open_bins_count as f64;
    if bin_residual != bin_capacity {
        score -= 2.0 * open_pressure.sqrt();
    } else {
        // New-bin candidate: penalize unless existing fits are poor.
        score += 3.0 * open_pressure.sqrt();
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's a tight fit already -> reward packing it further.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
