            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot use the leftover: mild penalty proportional to waste.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Early in the stream, be slightly more willing to open bins (diversity),
    // late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 5.0 - progress * 5.0;
    }

