        }
        if item_size >= 70 {
            score -= 35.0;
        }
    }

    // Coupling with mean residual: prefer bins tighter than the mean.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Early in the stream, be more willing to open bins (spread items);
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * frag;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: squared normalized post-residual penalty reduction
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tight * tight;

    // Penalize dead space that cannot fit typical future items (below min item size)
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < item_size.min(20) {
        score += 8.0;
    }

    // Lookahead coupling: reward bins whose post-residual fits the next item exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size as u32;
            if gap == 0 {
                score -= 30.0; // perfect chain fit
            } else {
                score -= 15.0 * (1.0 - gap as f64 / cap);
            }
        } else {
            // next item won't fit here; slight penalty for stranding
            score += 5.0;
        }
    }

    // Last-chance bonus: only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or item is large
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count == 1 && bin_residual != bin_capacity && (bin_residual - item_size) < 10);
        if poor_fits {
            score -= 45.0 + 20.0 * (item_size as f64 / cap);
        } else {
            // discourage opening bins when decent fits exist, more so late in stream
            score += 30.0 + 40.0 * progress;
        }
        // large items seed new bins well
        score -= 10.0 * (item_size as f64 / cap);
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    score -= 3.0 * (mean_residual / cap) * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins below mean residual (use the emptier ones) mildly
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);

    // Late-stream urgency: minimize bin count near the end
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Core: prefer small post_residual, with non-linear tightening as stream progresses.
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Smooth quadratic dead-space penalty: tiny residuals are wasted space.
    let frac = pr / cap;
    score += 18.0 * frac * (1.0 - frac).powi(3);

    // Perfect-fit coupling: reward small post_residual relative to mean residual state.
    score -= 6.0 * (mean_residual - pr) / cap;

    // New-bin candidate: smooth penalty that relaxes late in the stream (consolidation phase).
    if is_new_bin {
        score += 55.0 * (1.0 - progress).powi(2) + 0.15 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: penalize placements that leave post_residual unable to host the next item.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 10.0 * gap * gap;
    } else if next_item_size > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins whose post_residual falls into
    // "small" classes (0..=10) are nearly perfect fits; reward them strongly.
    let cls = post_residual / 10; // harmonic class 0..=10
    score -= match cls {
        0 => 30.0,
        1 => 18.0,
        2 => 9.0,
        3 => 4.0,
        _ => 0.0,
    };

    // Dead-space penalty: residuals that few item sizes can fill.
    // Items are 1..=100; a residual r is reusable if next items can land in it well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver, almost unusable
    }

    // Modulo coupling with next item: if next_item_size divides evenly into
    // post_residual (same harmonic family), this bin chains nicely.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 12.0; // perfect tiling potential
        } else if rem <= 5 {
            score -= 6.0;
        } else if rem > next_item_size / 2 {
            score += 4.0; // awkward leftover
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot go here anyway; slight penalty for stranding capacity
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral baseline, penalize opening new bins
    // when stream is early or open bins are few (consolidation phase).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 10.0 + 15.0 * (1.0 - progress);
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else {
        // Prefer tighter-than-average bins slightly.
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Late-stream urgency: squeeze into existing bins harder near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 10.0;
    }
    // Small unusable gaps (1..=9) are the worst outcome: penalize heavily,
    // making them rank worse than leaving a comfortably large residual.
    if post_residual >= 1 && post_residual < 10 {
        score += (10.0 - pr) * 12.0;
    }
    // Medium gaps (10..=20) are mildly wasteful too.
    if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - pr) * 1.5;
    }

    // --- Lookahead coupling: avoid killing the bin for the next item ---
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr < n && pr > 0.0 {
            // Leftover too small for the next item => dead space guaranteed.
            score += (n - pr) * 0.8;
        } else if pr >= n {
            // This bin can still host the next item: reward.
            score -= 3.0;
        }
    }

    // --- Open-bins pressure ---
    // Penalize spreading across many open bins: encourage consolidating
    // into existing bins when the open set is large.
    score += open_bins_count as f64 * 0.4 * (item_size as f64 / bin_capacity as f64);

    // --- Last-chance bonus ---
    // If this is the only bin that fits the item, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // A fresh bin is only attractive when existing bins fit poorly:
        // penalize it in proportion to how many bins already fit the item
        // and how much spare capacity is floating around.
        score += fitting_bins_count as f64 * 15.0;
        score += mean_residual * 0.5;
        // Late in the stream, prefer closing out open bins rather than
        // starting new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Reward filling existing bins more aggressively as the stream matures.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is already favored by base term,
    // but add a super-linear bonus for very tight fits.
    if post_residual <= 2 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        let next_fits = next_item_size as f64;
        let diff = (post_residual as f64 - next_fits).abs();
        if next_fits <= post_residual as f64 {
            // Next item fits: reward closeness to a perfect two-item fill.
            score -= 10.0 - 0.5 * diff;
            if diff < 0.5 {
                score -= 10.0; // exact chain fill
            }
        } else {
            // Next item does NOT fit in the residual: penalize proportionally
            // to how much space is wasted relative to the next item.
            let waste = next_fits - post_residual as f64;
            score += 0.3 * waste;
        }

        // Coupling with mean residual: if this bin's post-residual is far below
        // the mean residual, it is a "crumbling" bin; finishing it early is good.
        let post_f = post_residual as f64;
        if post_f < mean_residual {
            score -= 0.4 * (mean_residual - post_f);
        } else {
            score += 0.2 * (post_f - mean_residual);
        }
    } else {
        // Last item: just minimize post_residual (already base term).
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make opening a new bin unattractive unless the item is
    // large and few bins fit it; empty bins have residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: penalize by remaining stream length so early
        // new bins are discouraged, and by current open bin count.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 30.0 * (1.0 - progress);
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 10.0; // some open bin fits; opening new bin is wasteful
        }
        // But if item is huge relative to capacity, a fresh bin is more acceptable.
        score -= 0.15 * item_size as f64;
    }

    // Mild penalty for leaving large unusable gaps (dead space) relative to smallest items.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny slivers are hard to fill later
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space: post_residual that cannot fit the next item is wasted.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: bin can still host the lookahead item; reward slack that matches it.
            let gap = (post_residual - next_item_size) as f64;
            score -= 1.5 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead item.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize scattering across many open bins when residuals are plentiful.
    if open_bins_count > 1 {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.15 * spread;
        score += 0.3 * (open_bins_count as f64).ln();
    }

    // New-bin candidate logic: opening a fresh bin is only attractive when the
    // current item is large or the fit into open bins is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.5;
        let poor_fit = (post_residual as f64 / bin_capacity as f64) < 0.15;
        if large_item || poor_fit {
            score -= 6.0 + 3.0 * progress;
        } else {
            // Prefer reusing existing bins early/mid stream.
            score += 10.0 - 4.0 * progress;
        }
    }

    // Slight preference for filling bins with larger residual first (first-fit flavor)
    // to keep small residuals consolidated.
    score += 0.02 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual penalized more heavily as stream progresses
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    score += 30.0 * progress * pr_norm * pr_norm;

    // Reward tight fits via smooth saturation of post_residual
    score -= 12.0 * (1.0 - pr_norm).powi(3);

    // Penalize wasted space when it could fit the next item (smooth interaction)
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0) / bin_capacity as f64;
        score += 20.0 * waste * (0.5 + progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: mildly discourage opening a new bin when others fit well
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins near the mean (balance)
    let dev = (pr - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize leftover in "dead zone" classes: tiny slivers (1..15) are nearly useless.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0;
    } else if post_residual > 15 && post_residual <= 30 {
        score += 12.0;
    } else if post_residual > 30 && post_residual <= 50 {
        score -= 5.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Integer-division thresholds: leftover divisible into useful chunk classes
    let quarter = bin_capacity / 4;
    if post_residual >= quarter && post_residual % quarter == 0 {
        score -= 8.0; // leftover aligns with quarter classes -> likely reusable
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nfrac = next_item_size as f64 / post_residual as f64;
            // reward when next item consumes a large harmonic fraction of leftover
            if nfrac > 0.7 { score -= 15.0; }
            else if nfrac < 0.25 { score += 10.0; }
        } else {
            // next item won't fit here; leftover risk depends on size
            if post_residual < next_item_size && post_residual < 20 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin is decent.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: its residual is maximal, add structural penalty
        score += 35.0;
        // early in the stream, or many open bins with small mean residual -> prefer open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.1 { score += 20.0; }
        if mean_residual > item_size as f64 + 20.0 { score += 25.0; }
    }

    // Prefer tighter bins when several fit: closeness of fit reward.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 8 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance: tiny leftover gaps are wasted capacity ---
    // A residual that no plausible future item can use is dead space.
    let min_item = 1u32; // sizes 1..100
    if post_residual < min_item.max(next_item_size.min(20)) {
        // post_residual is smaller than the next item AND tiny overall:
        // it's near-perfect fill only if post_residual is very small.
        if post_residual <= 5 {
            score -= 30.0; // excellent tight fit, gap effectively zero
        } else {
            score += 25.0; // awkward sliver gap: penalize hard
        }
    }

    // Gap that exactly fits the next item is a jackpot
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Gap that can still hold the next item: mildly good
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 8.0;
    }

    // --- Reward closing bins (post_residual == 0 handled above) ---
    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Open bins pressure: discourage opening new bins when many are open ---
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with open bin count,
        // relaxed when no existing bin fits well (few fitting bins).
        let pressure = 15.0 + (open_bins_count as f64).sqrt() * 6.0;
        let last_chance_relief = if fitting_bins_count <= 1 { 10.0 } else { 0.0 };
        score += pressure - last_chance_relief;
    } else {
        // Existing bin: reward reuse, more so when bin count is high
        score -= 4.0 + (open_bins_count as f64).min(20.0) * 0.4;
    }

    // --- Last-chance bonus: if this is the only fitting bin, avoid new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins)
    // so large gaps stay available for large future items ---
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.15;
    } else {
        score += (bin_res_f - mean_residual) * 0.10;
    }

    // --- Stream progression: early on, be conservative with new bins;
    // late in stream, prefer closing out bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= progress * 10.0;
    }

    // Prefer placing into bins whose residual closely matches the item (best fit sharpening)
    let fit_gap = (bin_residual as f64 - item_size as f64);
    score += fit_gap * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear penalty
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item -> strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here later; reward closeness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would NOT fit in post_residual: penalize wasted space
            score += 0.5 * diff;
        }
    }

    // Reward being below mean residual (tighter than average bin)
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize leaving tiny unusable slivers (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Mild encouragement to consolidate when many bins are open
    score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Progress-based tightening: late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets a moderate penalty so it is
    // chosen only when no good fit exists among open bins
    if bin_residual == bin_capacity {
        score += 55.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits nonlinearly.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    // Items are >= 1; residual below the smallest plausible item is wasted.
    if post_residual > 0 {
        let waste = if post_residual < 10 { 12.0 } else { 0.0 };
        score += waste;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 2.0 * ((next_item_size - post_residual) as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when
    // existing bins are crowded or this bin would leave bad residue.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let crowding = (mean_residual / bin_capacity as f64).max(0.0);
        // Penalize new bins generally; relax when open bins have little room.
        score += 20.0 - 30.0 * crowding + 5.0 * progress;
        // If next item is large and this bin is fresh, mild bonus.
        if next_item_size > bin_capacity / 2 {
            score -= 4.0;
        }
    }

    // Slight preference to fill bins with many open bins (consolidation).
    score += 0.3 * open_bins_count as f64 * (1.0 - tightness);

    // Mild time-horizon modulation: early on, be conservative about
    // fragmenting bins; late in the stream, prefer any fit.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Later in the stream, tight residual packing matters more.
    let tightness_weight = 0.4 + 1.6 * progress * progress;
    score += tightness_weight * norm_pr * norm_pr * cap;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_frac * fit_frac;

    // Penalize leaving residual close to next item size mismatch (smooth interaction).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.5 * (gap / cap) * (gap / cap) * cap;
        // Reward exact next-item fit smoothly.
        let next_fit = if pr >= next_item_size as f64 { next_item_size as f64 / pr } else { 0.0 };
        score -= 4.0 * next_fit * next_fit;
    }

    // Last-chance bonus: strongly favor this bin if it's the only one that fits.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild pressure toward consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Penalize bins far from mean residual (smooth dispersion term).
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a new bin unless post_residual would be large
    // and few bins are open early in the stream (smooth gate).
    if bin_residual == bin_capacity {
        let new_bin_gate = (norm_pr - 0.5) * (1.0 - progress);
        score += 10.0 - 8.0 * new_bin_gate.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets penalize awkward dead space
    let pr = post_residual as u32;
    let class = pr % 10;
    score += match class {
        0 => -6.0,           // perfectly divisible residual -> reusable
        1..=3 => 2.0,        // sliver space, nearly dead
        4..=6 => 0.0,
        7..=9 => -1.5,       // chunky residual, still usable
        _ => 0.0,
    };

    // Integer-division threshold: residual that can host a mid-size item is valuable
    if pr >= 50 {
        score -= 4.0;
    } else if pr >= 25 {
        score -= 2.0;
    } else if pr > 0 {
        score += 3.0; // tiny dead space
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0; // perfect lookahead fit
        } else if next_item_size <= pr {
            score -= 3.0;
            // harmonic check: does next item divide residual nicely?
            if pr % next_item_size == 0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: penalize wasting large residual
            let waste = pr as f64 / cap;
            score += 4.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) * (mean_residual / cap);
        score = cap - item_size as f64; // baseline: full empty residual minus item
        score += 5.0 * (1.0 - progress);           // early stream: prefer new bins less
        score -= 6.0 * crowded;                    // many half-full bins -> discourage new bin
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 4.0; // pairable items: fresh bin can host both
        }
        if fitting_bins_count == 1 {
            score += 12.0; // never open new bin when a lone bin fits
        }
    }

    // Mild preference for tighter bins overall
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (below min item size 1, but practically
    // gaps too small to be useful for typical items) are wasted space.
    if post_residual > 0 {
        // Penalize gaps that are small relative to item sizes: unusable slivers.
        if post_residual < 20 {
            score += (20.0 - post_residual as f64) * 6.0;
        } else if post_residual < 40 {
            score += (40.0 - post_residual as f64) * 1.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize blocking the next item.
        score += 5.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    // The new-bin candidate has bin_residual == bin_capacity; add pressure so
    // that existing bins are preferred unless the fit is terrible.
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost of a fresh bin plus open-bin pressure.
        score += 40.0 + open_bins_count as f64 * 3.0;
        // But if no existing bin fits well (post_residual large gap), new bin
        // becomes attractive: reduce penalty when item is large.
        score -= (item_size as f64 / 100.0) * 20.0;
    } else {
        // Existing bin: slight preference as open bins accumulate (consolidation).
        score -= open_bins_count as f64 * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (fill up the emptiest-tail bins first to close them out).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Early in stream: allow more exploration of new bins; late: consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = (post_residual as f64) / (item_size as f64);
    score += 2.5 * tightness;

    // Aggressive 2-step lookahead: perfect match when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain completion: next item seals this bin
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how much it consumes
            let consumed = (next_item_size as f64) / (post_residual as f64);
            score -= 15.0 * consumed;
        } else {
            // next item does not fit here: penalize, worse if leftover is large
            score += 8.0 + 0.05 * (post_residual as f64);
        }
    }

    // Compare post_residual against mean residual across open bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin mildly unless current fits are bad
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if lookahead suggests a perfect chain elsewhere is unlikely, allow new bin
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0;
        }
    }

    // Penalize large dead space that nothing in typical range can use
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // nearly sealed bin is good
    }

    // Slight preference to fill earlier bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space that few future items could use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else if post_residual <= 50 { (post_residual as f64) * 0.25 } else { (post_residual as f64) * 0.9 };
        score += dead;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: penalize if next item can't use the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: only bin that fits — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let bad_fit = 1.0 - fit_ratio;
        score += 30.0
            + 45.0 * crowding * (1.0 - bad_fit)
            + (mean_residual / bin_capacity as f64) * 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // new bin useful for pairing big items
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // few alternatives: opening is fine
        }
    } else {
        // Mild penalty for many open bins to encourage consolidation.
        score += 0.6 * (open_bins_count as f64).ln().max(0.0);
    }

    // Time horizon: late in stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 35.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frac = pr / cap;

    // Base: quadratic dead-space penalty on post-residual
    let mut score = pr * (1.0 + 0.5 * frac * frac);

    // Smooth coupling of dead space with stream progress: later in stream, waste matters more
    score += 30.0 * frac * frac * progress;

    // Reward tight fits (small post-residual) with smooth discount
    score -= 20.0 * (1.0 - frac).powi(3);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward leaving space the next item can use, penalize near-miss residuals
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 8.0 * (1.0 - ((pr - ns) / cap).powi(2));
        } else {
            score += 6.0 * ((ns - pr) / cap);
        }
    }

    // Prefer denser bins when many bins are open
    score += 5.0 * (frac - mean_residual / cap).abs() * (open_bins_count as f64).sqrt() * 0.1;

    // Mild penalty for opening a new bin late in the stream
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction zone does it land in?
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Integer-division thresholds on post_residual (harmonic classes of C=100)
    let class = post_residual / 25; // 0..4: quarters of the bin
    match class {
        0 => {
            // Post residual < 25: near-perfect packing -> strongly reward
            score -= 60.0 + (25.0 - pr);
        }
        1 => {
            // 25..50: still useful; reward mildly, more so if next item fits
            score -= 25.0;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 30.0;
            }
        }
        2 => {
            // 50..75: medium zone; neutral-ish, small reward if next fits
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 20.0;
            } else {
                score += 10.0;
            }
        }
        _ => {
            // >75: wasteful placement, penalize heavily
            score += 40.0 + (pr - 75.0);
        }
    }

    // Modulo arithmetic: post_residual divisible by small harmonics implies
    // chunk-friendly dead space that many item sizes can still fill.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 12.0;
    }
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Perfect fit: zero dead space is always ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only open a new bin when the current bin
    // would be left with an awkward residual and the next item is large.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; discount early in stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 50.0; // big next item: fresh bin is good
        }
    }

    // Tight-fit penalty: leaving tiny unusable slivers (1..9) is bad
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer bins whose residual is close to the item (snug fit)
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    // Coupling with mean residual: favor bins below mean (tighter bins)
    score += (mean_residual - pr) * 0.1;

    // Slight bonus for using an already-open bin when many are open
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100 range,
    // but treat gaps < 10 as fully wasted) are useless; amplify penalty for tiny gaps.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Non-linear penalty on wasted fraction of the bin.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here: penalize proportionally to leftover size
            score += (post_residual as f64) * 0.35;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    // unless the fit is excellent (post_residual small).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // A new bin is acceptable late in the stream or when open bins have low mean residual.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
        if mean_residual < item_size as f64 {
            score -= 12.0; // open bins are too full anyway; new bin is fine
        }
    } else {
        // Mild reward for consolidating into bins that are already partially filled.
        score -= 3.0;
    }

    // Slight preference for bins whose residual is close to the mean (balance).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly matches next item
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasted chain opportunity
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    }

    // Compare post_residual to mean residual across open bins:
    // prefer bins whose post residual is near the mean (keeps residuals homogeneous)
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.10 * mean_gap;

    // Penalize large dead space that nothing typical can use
    if post_residual < 10 {
        score -= 5.0; // nearly full bin is good (item sealed it)
    } else if post_residual > 40 {
        score += 0.05 * (post_residual as f64 - 40.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Early in stream: be pickier about residual quality
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate: make it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can also host the next item, scaled by how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(50.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer fuller bins (small residual) when many bins are open.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Global state coupling: when mean residual is low, conserve open-bin space;
    // when mean residual is high, encourage consolidating into fuller bins.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize cramming); late in the stream, squeeze everything tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0 * fill_ratio;
    score -= progress * 6.0 * (1.0 - tightness);

    // New-bin candidate: neutral baseline with mild penalty so it is chosen
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * (1.0 - progress);
        // If item is large, opening a fresh bin is more attractive.
        score -= 0.1 * item_size as f64;
    }

    // Avoid fragmenting nearly-full bins with small items.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, tight fits (small post_residual) matter more.
    let poly = progress * (1.0 - progress) * 4.0; // peaks mid-stream, 0 at ends
    score += 6.0 * poly * (pr / cap).powi(2) * cap;
    score -= 14.0 * progress * (1.0 - tightness).powi(3) * cap;

    // Reward near-perfect fits with a smooth cubic term.
    let fit = 1.0 - pr / cap;
    score -= 10.0 * fit * fit * fit * cap;

    // Penalize dead space relative to mean residual of open bins.
    score += 0.35 * (pr - mean_residual).abs().powf(1.5) * (1.0 + progress);

    // Last-chance bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 12.0 * (1.0 - pr / cap);
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 3.0 * (1.0 - pr / cap) * (nxt / cap);
        }
    }

    // New-bin candidate: mildly discourage early, allow late when fits are poor.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (1.0 + total_items as f64)).sqrt();
        score += 15.0 * (1.0 - progress) - 10.0 * progress + 8.0 * openness;
    }

    // Slight penalty for many open bins to encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // Perfect fit: overwhelming reward
    if pr == 0 {
        score -= 2.0 * c;
    }

    // Harmonic class of post_residual (integer division into capacity/10 classes)
    let unit = (bin_capacity / 10).max(1);
    let class = pr / unit;

    // Sliver penalty: residuals just above a quarter-capacity harmonic boundary
    // tend to be dead space that only tiny items can fill.
    let quarter = (bin_capacity / 4).max(1);
    if pr > quarter && pr % quarter != 0 {
        score += ((pr % quarter) as f64) * 0.05;
    }

    // Lookahead (k=2) coupling
    if next_item_size > 0 {
        let n = next_item_size;
        if n > pr {
            // Leftover cannot host the next item: dead-space penalty,
            // extra harsh in the awkward upper-half band (C/2, C).
            score += (n - pr) as f64 * 0.6;
            if pr > bin_capacity / 2 {
                score += 15.0;
            }
        } else {
            // Next item fits: reward tight chaining (small combined leftover).
            score -= (pr - n) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer
    // using it unless the resulting fit lands in a terrible harmonic class.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
        if class <= 2 {
            score -= 12.0;
        }
    }

    // New-bin candidate (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Mild cost to avoid needless proliferation, growing with open bins.
        score += 3.0 + 0.02 * open_bins_count as f64;
        // Opening a bin for a small item (large post residual) is wasteful.
        if pr > bin_capacity / 2 {
            score += 10.0;
        }
        // Early in the stream, slightly discourage bin proliferation.
        if total_items > 0 {
            let t = step_index as f64 / total_items as f64;
            score += (1.0 - t) * 5.0;
        }
    }

    // Mean-residual coupling: prefer bins that are fuller than the average
    // open bin (consolidation pressure).
    score -= (mean_residual - pr as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to ever be useful
    // (below the minimum plausible item size) are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    } else if post_residual <= 12 {
        // Small but potentially usable gap: mild penalty.
        score += 6.0 * (1.0 - post_residual as f64 / 12.0);
    }

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than fragmenting space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement; if next item is bigger than post residual
    // while it would fit an empty bin, slightly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && next_item_size > bin_residual {
            score += 8.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (filling the emptier bins keeps a spread of useful residuals).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it moderately attractive only when the item
    // is large relative to existing residuals or nothing fits well.
    if bin_residual == bin_capacity {
        let base = 0.5 * bin_capacity as f64;
        score += base + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large item starting a fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fits (dead space minimization)
    if post_residual == 0 {
        score -= 500.0;
    } else {
        score -= 60.0 / (post_residual as f64).sqrt();
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            if chain_waste <= 10 {
                score -= 120.0; // tight chain, still good
            } else {
                score -= 40.0 / (chain_waste as f64).sqrt();
            }
        } else {
            // next item can't follow in this bin: penalize proportionally
            let gap = next_item_size - post_residual;
            score += 25.0 + (gap as f64) * 0.4;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize the brand-new empty bin candidate unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 30.0;
        // but a fresh bin is attractive early in the stream or when open bins are loose
        if open_bins_count > 3 && mean_residual > 45.0 {
            score -= 25.0;
        }
    }

    // Early stream: slightly favor consolidation; late stream: favor tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness: reward small post-residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Last-chance bin: strongly favor if this is the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward if next item fits in the post-residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // Extra reward if next item nearly fills leftover space
            let next_left = post_residual - next_item_size;
            score -= (1.0 - (next_left as f64 / bin_capacity as f64)) * 10.0;
        } else {
            // Penalize leaving dead space the next item cannot use
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Penalize bins far from mean residual (prefer balanced or well-above-mean fills)
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    // Prefer fuller bins when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * open_bins_count.min(10) as f64 * 2.0;

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin late in stream if few bins fit well
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count <= 1 {
            score -= 30.0 + progress * 15.0;
        }
    }

    // Late stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling: small post-residuals are valuable; penalize dead space quadratically.
    let norm_pr = pr / cap;
    score += 18.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Reward tight fits, stronger as the stream progresses.
    score -= (1.0 - norm_pr) * (2.0 + 6.0 * progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 4.0 * (nxt / cap);
        } else {
            score += 3.0 * (nxt / cap) * (pr / cap);
        }
    }

    // Slight preference toward bins deviating from the mean residual (consolidation).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 2.0 * dev * (1.0 - progress);

    // New-bin candidate: mild penalty that grows with progress (prefer packing into existing bins late).
    if bin_residual == bin_capacity {
        score += 1.5 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual left behind (quantized dead space).
    let class = post_residual / 10; // 0..10 classes
    // Dead space is worse when it cannot host the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual still usable: reward.
            score -= 12.0;
        } else {
            // Dead space: penalize by how far below the next item it falls.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
        // Bonus if post_residual exactly matches next item (perfect chaining).
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Harmonic divisibility: post_residual is a multiple of next item's class.
        if next_item_size % 10 == 0 && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
    } else {
        // Last item: pure tightness, no lookahead concerns.
        score -= 15.0;
    }

    // Class-based dead-space penalty: residuals in low classes (tiny slivers) are useless.
    let sliver = [0.0, 4.0, 7.0, 9.0, 10.0, 11.0, 12.0, 13.0, 14.0, 15.0, 16.0];
    score += sliver[(class as usize).min(10)];

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current bin would create bad dead space.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if the best fit leaves a large unusable remainder.
        let dead = (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
        score = 40.0 + dead - 10.0;
        // Early in the stream, prefer keeping bins consolidated.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 15.0;
        // If many open bins already, discourage opening more.
        score += open_bins_count as f64 * 1.5;
    }

    // Prefer bins tighter than the mean (better consolidation).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Fraction-of-capacity harmony: reward when post_residual is a "nice" fraction.
    let fr = post_residual as f64 / bin_capacity as f64;
    if (fr * 4.0).fract() < 1e-9 {
        score -= 4.0; // 0, 25, 50, 75% leftovers are reusable by common item sizes
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold a future item
    // are pure waste. Items arrive 1..=100, so gaps < ~10 are nearly dead.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this bin is a great choice (chained placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, using it avoids
    // opening a new bin (fragmentation control).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing bins,
    // discourage opening new ones; few open bins -> new bin is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual == bin_capacity {
        score += 12.0 + pressure;
        // Opening a new bin is fine early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    } else {
        score -= pressure * 0.5;
    }

    // Mild tie-break toward bins below mean residual (balancing load).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Lookahead feasibility: can next item also fit after this placement?
    if next_item_size > 0 && post_residual >= next_item_size {
        // slack after hypothetically placing next item too; reward tight chain
        let chain_slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - chain_slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // dead space relative to next item: penalize unusable gap
        let dead = (next_item_size - post_residual) as f64;
        score += 0.25 * dead;
    }

    // Penalize bins with residuals far from mean (prefer typical-fit bins)
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Avoid wasting a nearly-full bin on a small item
    if item_size < bin_residual / 4 {
        score += 5.0;
    }

    // Slight preference for keeping fewer open bins (fill existing bins early)
    score += 0.05 * open_bins_count as f64;

    // Late in stream: be more greedy about filling bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that is hard to reuse (post_residual in awkward low band).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing residuals are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins mildly; offset when open bins have low mean residual.
        score += 15.0 + 0.3 * (open_bins_count as f64);
        if mean_residual < item_size as f64 {
            // No open bin realistically fits well; allow new bin.
            score -= 25.0;
        }
    } else {
        // Prefer bins with residual close to item size (best-fit sharpening).
        let tightness = (bin_residual - item_size) as f64;
        score += 0.15 * tightness;
        // Favor reusing bins that are already fragmented (high count = consolidation).
        if open_bins_count > 3 {
            score -= 1.5;
        }
    }

    // Time horizon: early in stream, be conservative (avoid waste); later, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * fill_ratio;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global residual pressure: when mean residual is high, prefer bins below mean (balance).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, smoothly warped
    let mut score = pr * (1.0 + 0.8 * t * t);

    // Non-linear penalty on dead space: small residuals that are hard to fill
    let dead = (1.0 - norm_pr).powi(3) * (1.0 - norm_pr);
    score += 20.0 * dead * (1.0 - t);

    // Reward tight fits more strongly late in the stream
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * t;

    // Coupling with mean residual: prefer bins below mean residual (compact bins)
    score += 0.4 * (mean_residual - pr).abs();

    // Lookahead: if next item fits in post-residual, reward heavily (smooth bell)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_quality = (pr - nx).abs();
        let bell = (-fit_quality * fit_quality / 400.0).exp();
        score -= 12.0 * bell;
    } else {
        // Last item: strongly prefer filling existing bins
        score -= 10.0;
    }

    // Last-chance bin: penalize leaving it unused only mildly; reward using it
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mild congestion penalty when many bins are open
    score += 0.3 * (open_bins_count as f64).sqrt();

    // New-bin candidate: make it moderately unattractive, more so late in stream
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item-size classes
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Penalize dead space: small nonzero post_residual is wasted
    if post_residual > 0 {
        let dead = (post_residual as f64).min((bin_capacity - post_residual) as f64);
        if post_residual < 10 {
            score += (10.0 - post) * 2.5; // unusable sliver
        } else {
            // reward post_residuals that are "harmonic" with typical future items
            let harmonics = [
                post_residual % 10 == 0,
                post_residual % 20 == 0,
                post_residual % 25 == 0,
                post_residual % 50 == 0,
            ];
            let h_count = harmonics.iter().filter(|&&h| h).count() as f64;
            score -= h_count * 4.0;
        }
        let _ = dead;
    } else {
        score -= 12.0; // perfect fill is excellent
    }

    // Integer-division threshold classes on post_residual
    let class = post_residual / 10; // 0..10 coarse class
    score += match class {
        0 => 8.0,          // 0..9: near-dead
        1 => 3.0,
        2 => 0.0,
        3 => -1.0,
        4 => -2.0,
        5 => -3.0,         // ~50 residual: most reusable
        6 => -2.0,
        7 => -1.0,
        _ => 0.0,
    } as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open new bin when current fits are poor
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap * 0.62;
        // lookahead: if next item is large, fresh bin may be warranted
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt > post_residual as f64 + nxt * 0.0 + 40.0 {
                score -= 10.0;
            }
            // harmonic coupling: fresh bin pairs well when next item ~ half capacity
            if (nxt as u32) >= 40 && (nxt as u32) <= 60 {
                score -= 6.0;
            }
        }
        // many open bins with low mean residual -> avoid opening another
        if open_bins_count > 2 && mean_residual < cap * 0.35 {
            score += 12.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Modulo coupling between item_size and bin_residual (harmonic fit)
    let r = bin_residual % item_size.max(1);
    if r == 0 {
        score -= 5.0; // item divides residual evenly: perfect harmonic fit
    } else if r < 5 {
        score += 3.0; // leaves tiny dead space
    }

    // Prefer tighter bins when many alternatives exist
    if fitting_bins_count > 3 {
        score -= (bin_capacity - bin_residual) as f64 * 0.08;
    }

    // Lookahead: penalize if post_residual can't fit next item but barely misses
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as u32;
        if nxt > post_residual && nxt - post_residual <= 10 {
            score += 4.0; // frustrating near-miss
        } else if nxt <= post_residual && post_residual - nxt < 10 {
            score -= 3.0; // next item fits leaving tiny remainder: fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Treat residual <= 10 as nearly worthless.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) <= dead_threshold && post_residual > 0 {
        score += 40.0 * (dead_threshold - post_residual as f64 + 1.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to item size (small slack ratio).
    score += 0.5 * (post_residual as f64 / item_size.max(1) as f64);

    // Open-bin pressure: discourage spreading across many bins slightly,
    // but encourage using existing bins when many are open.
    score += 0.3 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover: penalize proportionally.
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (tighter bins) when post_residual is small.
    score += 0.2 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset if many open bins are crowded.
        score = bin_capacity as f64 * 1.5
            - 0.5 * open_bins_count as f64
            + if post_residual == 0 { 0.0 } else { 0.0 };
        // If this is the only fitting option (i.e., nothing else fits),
        // fitting_bins_count==1 means only the new bin fits -> allow it.
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral-ish baseline, penalized slightly
    // unless lookahead favors it.
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        return score;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item size well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 18.0 / (1.0 + gap * 0.15);
        // Exact lookahead match: strong reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Post-residual too small for next item: penalize dead space creation.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.12;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Early stream: be conservative, keep large residuals available.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.08;

    // Penalize leaving tiny unusable slivers (below minimum item size 1..100
    // but practically < 10 dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a super-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        } else if post_residual >= next_item_size && next_item_size > 0 {
            // Slight reward if leftover can host the next item.
            score -= 2.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // When many bins are open, prefer consolidation (fill existing bins).
    let pressure = (open_bins_count as f64) / ((mean_residual.max(1.0)) / 10.0 + 1.0);
    if bin_residual != bin_capacity {
        score -= 0.05 * pressure.min(20.0);
    } else {
        // New-bin candidate: penalize when existing bins are roomy on average,
        // reward opening a fresh bin only when the fit here would be perfect-ish
        // and current bins are fragmented.
        score += 8.0 + 0.03 * (open_bins_count as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if fragmentation > 25.0 && item_size >= 50 {
            score -= 20.0; // big item + fragmented bins => fresh bin is good
        }
        if post_residual == 0 {
            score -= 30.0; // perfect fit in a fresh bin
        }
    }

    // Time-horizon modulation: early in the stream, be frugal with new bins;
    // late, allow more freedom since future payoff matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 6.0 * progress;
    }

    // Mean-residual coupling: discourage dumping into bins far above/below mean
    // unless the fit is tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.04 * dev * (1.0 - tightness);

    // Exact-fit and near-exact-fit rewards.
    if post_residual == 0 { score -= 25.0; }
    else if post_residual <= 5 { score -= 10.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (0.5 + 0.5 * progress) - norm_pr * (1.0 - progress);
    score += 20.0 * coupling;
    // Penalize leaving residual that next item cannot use
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += 4.0 * (1.0 - norm_pr);
        }
    }
    // Reward last-chance bins to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }
    // Slight preference for tighter bins relative to mean residual
    score += 0.1 * (pr - mean_residual);
    // Early stream: prefer filling existing bins; late stream: tolerate new bins
    score += (1.0 - progress) * 2.0 * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.03;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are unusable (min item = 1... but treat <10 as near-dead),
    // residuals in [10, 20] are only usable by small items. Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // completely dead space
    } else if post_residual < 20 {
        score += 25.0; // narrow usability window
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tightness relative to residual before placement: favor filling a large fraction of the gap.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening new bins when open bins exist.
    if bin_residual == bin_capacity {
        // candidate new bin: base score above any decent existing fit
        score += 40.0 + 6.0 * open_bins_count as f64;
        // early in stream, opening bins is cheaper (future items need room)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    } else {
        // slight preference for bins with larger residual when many bins open
        score -= 0.05 * bin_residual as f64 * (open_bins_count as f64).min(10.0) / 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item would fit in the post-residual, reward keeping this bin;
    // if next item is large and post-residual too small, slight penalty for stranding space.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins get priority).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward bins where the item leaves no dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post residual matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // Next item fits exactly-ish: chain placement is desirable.
            let slack = post_residual as f64 - next;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does not fit here: penalize proportionally to the mismatch.
            let gap = next - post_residual as f64;
            score += 20.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are tighter fits;
    // prefer them, since loose bins remain flexible for future items.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // and nothing tight exists. An empty bin has maximum residual, so the
    // mean-residual term already penalizes it somewhat; add an explicit bias.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, avoid opening new bins even more (wasted capacity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // But if the item is large relative to capacity, a new bin is fine.
        score -= 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            score -= 18.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasting too much residual.
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer minimal post residual.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins are open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // New bin is more attractive if existing residuals are small.
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Mild preference for bins tighter than the mean residual.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with non-linear (quadratic) shaping.
    let mut score = post + 0.9 * (post * post) / cap;

    // Dead-space penalty: residuals too small to likely fit future items are waste.
    let dead = (post / cap).powi(3);
    score += 25.0 * dead;

    // Smooth stream-progress coupling: early on, mild tightness is fine;
    // late in the stream, penalize leftover space more strongly.
    let late = progress * progress;
    score += 12.0 * late * (post / cap);

    // Mean-residual coupling: if this bin's post-residual is far below the mean,
    // it's a tight fit worth rewarding; if far above, penalize.
    let mean_post = mean_residual - item_size as f64;
    let spread = post - mean_post;
    score += 0.35 * spread;

    // Lookahead: reward if the next item fits into post_residual (chain packing).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let snug = 1.0 - (post - next_item_size as f64) / cap;
        score -= 8.0 + 6.0 * snug;
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty proportional to how much it misses.
        let miss = (next_item_size as f64 - post) / cap;
        score += 4.0 * miss;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral base so it only wins when open bins score poorly.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 6.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit), but heavily penalize dead space
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Harmonic class of post_residual: bins whose residual falls into "usable" classes
    // (residuals that can host common item sizes) are rewarded.
    let usable = |r: u32| -> bool {
        let r = r as i64;
        // residuals that are multiples of common sizes or large enough for typical items
        r == 0 || r >= 10 && (r % 10 == 0 || r % 20 == 0 || r % 25 == 0 || r % 50 == 0)
    };

    if usable(post_residual) {
        score -= 12.0;
    } else if post_residual < 10 {
        // dead space below minimum item size: strong penalty unless exactly 0
        score += 25.0;
    } else {
        // awkward residual class: mild penalty growing with how "unusual" it is
        let oddness = (post_residual % 10) as f64;
        score += oddness * 0.4;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
            // harmonic bonus: post_residual - next_item_size lands on a good class
            if usable(post_residual - next_item_size) {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: slight penalty for stranding residual
            score += 4.0 + frac * 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit (tight packing elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins mildly; the base post_residual (=capacity) is large
        // already, add pressure so tight fits in open bins win.
        score += 15.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
        if mean_residual < item_size as f64 {
            // open bins are nearly full: new bin is reasonable
            score -= 18.0;
        }
    }

    // Slight preference for bins whose residual deviates from the mean in a useful way
    score -= (mean_residual - bin_residual as f64).abs().max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight-fit reward scaled by how much of the bin the item consumes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Pressure from number of open bins: prefer reusing existing bins
    // when the bin pool is large, but allow opening when few bins exist.
    let open_pressure = (open_bins_count as f64).ln() * 3.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's post residual is far below the mean,
    // it is a good compaction target.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.5 * mean_gap.max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral base for a fresh bin; only attractive
    // when existing fits are poor (large post_residual elsewhere) or the next
    // item is large and would be stranded by a small gap.
    if bin_residual == bin_capacity {
        score = 55.0 - fill_ratio * 10.0;
        if next_item_size > 0 && post_residual == bin_capacity {
            // Next item is big: slightly favor a fresh bin to keep large gaps.
            if next_item_size as f64 > 0.6 * bin_capacity as f64 {
                score -= 8.0;
            }
        }
    }

    // Lookahead: penalize leaving a gap that barely cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Mild stream-progression term: as the stream advances, be slightly more
    // conservative about leaving dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 40.0 / (post_residual as f64).sqrt();
    }

    // 2-step lookahead: reward if next item fits into the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.5 * (post_residual as f64 - next_item_size as f64).min(30.0);
        } else {
            // Penalize dead space that the next item cannot use.
            score += 0.6 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave large waste.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the item is large relative to capacity, opening fresh is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Late in stream: be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Penalize dead space relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead_frac * dead_frac;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size as f64 == post_residual as f64 {
            score -= 500.0;
        } else if (next_item_size as u32) <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 30.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting tight space.
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, be more selective about opening new bins;
    // late in the stream, prefer filling existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * t * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer reuse.
    if open_bins_count > 2 {
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        score += 25.0 + 60.0 * avg_pressure;
        if fitting_bins_count > 1 {
            score += 80.0;
        }
    }

    // Slight preference for bins with small residuals (tightest fit).
    score += 0.5 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    score += 6.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 8.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Penalize dead space that cannot fit the mean expected remainder
    let mean_r = mean_residual;
    if pr > 0.0 {
        let waste = (pr - mean_r).max(0.0) / cap;
        score += 5.0 * waste * waste;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + 4.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Slight penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Mild bias toward opening a new bin early (fresh bins score lower)
    if bin_residual == bin_capacity {
        score -= 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 20.0;

    // Harmonic classes: classify post_residual into residue classes mod 10
    let class = post_residual % 10;
    // Dead-space classes: residuals that few item sizes can use are penalized
    let dead_penalty = match class {
        1..=3 => 8.0,   // very hard to fill
        4..=6 => 4.0,   // moderately hard
        7..=9 => 1.5,   // easier (many item sizes in 10..80 fit)
        _ => 0.0,       // class 0: perfectly reusable
    };
    score += dead_penalty;

    // Integer-division thresholds on post_residual: quintiles of capacity
    let quint = post_residual / (bin_capacity / 5);
    score += quint as f64 * 3.0;

    // Reward leaving residual that exactly fits the lookahead item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            // harmonic penalty on leftover class
            let lclass = leftover % 10;
            score += if lclass == 0 { 0.0 } else if lclass <= 5 { 3.0 } else { 1.0 };
        } else {
            // lookahead cannot fit here; mild penalty
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it only wins when
    // open bins have poor fits
    if bin_residual == bin_capacity {
        score = 55.0 + fit_ratio * 10.0
            - (open_bins_count as f64).ln() * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 1.0;
        }
    }

    // Stream progression coupling: late in stream, be more conservative
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    // Coupling with mean residual: if this bin is far from mean, small penalty
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit bonus (zero residual)
    } else {
        // Penalize small "unusable" gaps harder than large leftovers.
        if post_residual <= 10 {
            score += 12.0 * (11.0 - post_residual as f64);
        }
        // General tightness reward: prefer smaller residuals, slightly superlinear.
        score += 0.35 * (post_residual as f64).sqrt();
    }

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if item_size >= bin_residual {
        // shouldn't happen (bin can't fit), but guard
        score += 5000.0;
    }

    // Lookahead coupling: if the next item fits the post residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual becomes dead space for the known next item
        score += 0.15 * post_residual as f64;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: encourage filling existing bins rather than spreading out.
    score += 0.05 * open_bins_count as f64;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins) to consolidate.
    score += 0.10 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: opening a new bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: post_residual = capacity - item_size.
        // Penalize mildly so good fits in open bins win, but not so much that bad fits win.
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        // Late in the stream, slightly discourage new bins to consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.5 * slack.min(40.0);
        } else {
            // Next item won't fit here; penalize wasted residual that cannot serve lookahead.
            score += 0.3 * (post_residual as f64 - (next_item_size - post_residual) as f64).max(0.0);
        }
        // Perfect 2-chain: post_residual equals next item size exactly.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: just prefer tightest fit.
        score += 0.1 * (post_residual as f64);
    }

    // Compare against mean residual: prefer bins whose post residual is below average
    // (keeps large residuals concentrated in fewer bins).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.4 * (mean_residual - pr);
    } else {
        score += 0.4 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize dead space that can never be filled by any item.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Early in the stream, allow opening new bins more freely to build diversity of residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 * progress; // new bin becomes less attractive as stream fills
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin pairs well with similar next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    score -= (item_size as f64 / bin_residual as f64) * 12.0;

    // Penalize dead space that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else if next_item_size >= bin_residual {
            // next item can't fit here anyway; mild penalty for wasting space
            score += 3.0;
        }
    }

    // Time horizon: early in stream, be more selective (favor new bins for big items);
    // later, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (balancing residuals)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Penalize opening new bins when many bins are open with slack
    if bin_residual == bin_capacity {
        let avg_slack = mean_residual * open_bins_count as f64 / open_bins_count.max(1) as f64;
        score += 4.0 + 0.03 * avg_slack;
        if item_size > 60 {
            score -= 6.0; // big items may deserve a fresh bin early
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 12.0 * norm_pr * norm_pr * (1.0 - t);
    score -= 10.0 * norm_item * norm_pr * t;
    score += 6.0 * norm_pr * norm_pr * norm_pr * t * t;

    // Reward tight fits, more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (4.0 + 10.0 * t);

    // Lookahead: reward bins whose post residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 5.0 * (1.0 - slack) * (1.0 - slack) * (0.5 + t);
    } else if next_item_size > 0 {
        score += 3.0 * t * (next_item_size as f64 - pr) / cap;
    }

    // Penalize scattering across many open bins relative to mean residual
    score += 2.0 * (open_bins_count as f64).ln() * (norm_pr - mean_residual / cap).abs();

    // Last-chance bin bonus: avoid wasting the only fitting bin on a bad fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - norm_item) * (0.5 + t);
    }

    // New-bin candidate: mildly penalize early, mildly favor late if fit is poor
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - t) - 8.0 * t * (1.0 - (1.0 - norm_item) * (1.0 - norm_item));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (capacity fractions, 1/4 classes)
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter;
    let pre_class = bin_residual / quarter;

    // Reward landing on exact harmonic boundaries (perfect closure)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual % quarter == 0 {
        score -= 12.0;
    }

    // Penalize dead space: small post_residual that is not exactly 0 is a trap
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Penalize leaving a residual in the "unfillable middle band" (41..=59)
    // where typical items (10..80) rarely pair well with next items
    if (41..=59).contains(&post_residual) {
        score += 8.0;
    }

    // Lookahead coupling: does post_residual admit next_item_size?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward exact modulo closure with the next item
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            score -= 5.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tight pre-fit bins (low pre_class = nearly full bin)
    score += pre_class as f64 * 2.0;

    // Mild pressure against proliferating open bins
    score += open_bins_count as f64 * 0.5;

    // Pull toward bins whose residual is near the mean (avoid stranding outliers)
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += drift * 0.15;

    // Early stream: be conservative, keep residuals flexible; late stream: close bins aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_class as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gap below minimum item size ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Strong penalty for medium dead space that likely can't be filled later
    if post_residual >= 10 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.8;
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item nearly fits but not quite (wasted space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate: mild penalty so it's only chosen when fits are bad
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the item is large relative to capacity, new bin is fine
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Early stream: be slightly more open to new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Prefer bins with below-mean residual (tighter packing)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual of this bin, strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 45.0 / (1.0 + lookahead_fit);
    } else if next_item_size > 0 {
        // Penalize if next item cannot use the leftover space (dead space risk).
        score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.6;
    }

    // Relative to mean residual: bins with residual far below mean are precious
    // small-capacity bins; penalize wasting them on large leftover creation.
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += (-dev) * 0.25;
    } else {
        score -= dev * 0.05;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // item would leave a very awkward residual in every open bin.
    if bin_residual == bin_capacity {
        let awkward = post_residual as f64 / bin_capacity as f64;
        // Fresh bin starts with a penalty; discount it when item is large
        // and lookahead suggests a good follow-up fit.
        score = 70.0 * awkward + item_size as f64 * 0.4;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
        // Late in the stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score when post_residual is small relative to item size.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 6.0 * tightness * (item_size as f64);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // the item leaves a large, reusable residual or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64);
        // Penalize new bins more when many open bins with slack exist.
        score += 15.0 + 20.0 * pressure;
        // Late in the stream, prefer consolidating into open bins.
        score += 30.0 * progress;
        // Reward opening a new bin when the item is large and would leave a clean residual.
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty for leaving a stranded residual.
            score += 5.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Global state: prefer filling bins when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Prefer bins whose residual is near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual) mildly; later, dead space is costly.
    let tightness = (pr_norm * pr_norm) * (0.5 + 1.5 * progress * progress);

    // Penalize leaving residual that is small but unusable for the next item (smooth interaction).
    let next_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
    let dead_space = pr_norm * (next_fit * (1.0 + 2.0 * progress));

    // Reward using a nearly-full bin (small post_residual) via cubic term.
    let fullness_reward = -(1.0 - pr_norm).powi(3) * 3.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    let last_chance = if fitting_bins_count == 1 { -5.0 * (1.0 - pr_norm) } else { 0.0 };

    // Mild penalty for spreading across many open bins when residuals are large.
    let spread = if open_bins_count > 0 { (open_bins_count as f64).ln() * pr_norm * 0.3 } else { 0.0 };

    let mut score = pr + tightness * cap * 0.5 + dead_space * cap + fullness_reward * cap + last_chance + spread;

    // New-bin candidate: only attractive when open bins would leave big dead space.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual - pr;
        score += (avg_waste.max(0.0)) * 1.2 - 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" is the leftover space?
    // Residuals that are multiples of common item sizes (or near-capacity-fractions)
    // are more likely to be filled by future items.
    let cap = bin_capacity as f64;

    // Reward residuals that align with coarse capacity fractions (1/4, 1/2, 3/4)
    let frac = post_residual as f64 / cap;
    let quarter_align = (frac * 4.0).round() - frac * 4.0;
    score -= 6.0 * (1.0 - quarter_align.abs() * 2.0).max(0.0);

    // Modulo-class bonus: residuals divisible by small harmonic steps (5,10,20)
    let pr = post_residual;
    if pr % 10 == 0 { score -= 4.0; }
    if pr % 20 == 0 { score -= 3.0; }
    if pr % 5 == 0 && pr % 10 != 0 { score -= 1.5; }

    // Penalize awkward dead space: small but nonzero residuals that few items can use
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Residuals in (10, 20) can only host tiny items; mild penalty
    if pr >= 10 && pr < 20 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // partial fit quality: how tightly next item nests
            let nest = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - nest / cap);
        } else {
            // next item cannot use this bin's leftover; penalize large leftovers
            score += 3.0 * ((next_item_size - pr) as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost so it loses
    // against good fits but wins against terrible fits (dead-space creation).
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin pairs well with a large follow-up item
        }
    }

    // Tight fits are excellent: reward near-perfect packing
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness > 0.9 {
        score -= 15.0 * (tightness - 0.9) / 0.1;
    }

    // Slight preference for consolidating into fewer bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Prefer bins below mean residual (keeps residuals balanced, avoids stranding)
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // small gap: likely unusable unless next item is tiny
        score += 25.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: only bin that fits the item -> strong bonus to use it.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Lookahead: if next item can use the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot use the leftover, penalize creating that dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are open.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: placing into a bin with residual far below mean
    // (a tight bin) is good; spreading waste across bins is bad.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. penalize opening a new bin, more so as stream progresses.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: opening is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // next item fits: reward proportional to how well it fills remaining space after both
            let two_step_waste = post_residual - next_item_size;
            score -= 300.0 * (1.0 - two_step_waste as f64 / bin_capacity as f64);
            score += 0.5 * two_step_waste as f64;
        } else {
            // next item won't fit here: penalize large dead space
            score += 0.8 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64)).abs();
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Compare residual against mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Slight preference for filling more-full bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize opening a new bin when open bins exist that fit decently
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0 + 2.0 * open_bins_count as f64;
        // but allow new bin if item is huge and mean residual is small
        if item_size as f64 > mean_residual + 30.0 {
            score -= 120.0;
        }
    }

    // Mild penalty for very small post_residual that likely becomes dead space
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic horizon effects
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward tight fits (small post_residual) with a non-linear term
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Penalize waste relative to the current item size: leaving space smaller
    // than the minimum plausible item is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual {
            // next item can't go here; mild penalty proportional to wasted potential
            score += 2.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        } else {
            // next item fits but leaves what residue?
            let nr = post_residual - next_item_size;
            score -= 5.0 * (1.0 - nr as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (i.e. tighter bins) to balance load.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // When many bins are open, discourage opening yet another bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize scaled by number of open bins and progress.
        let open_penalty = (open_bins_count as f64).ln().max(1.0);
        score += 30.0 + 4.0 * open_penalty + 10.0 * progress;

        // But if no open bin can fit and the item is large, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
        // If next item is large and this bin would be nearly full after placement,
        // opening fresh may help the future item.
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 15 {
            score -= 20.0;
        }
    }

    // Mild early-stream exploration: keep some bins available early.
    score -= 3.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer tight fits (low post_residual), with a convex penalty on dead space.
    let mut score = pr * (1.0 + 2.0 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, moderate residuals are acceptable; later, dead space is heavily penalized.
    let coupling = 1.0 + progress * progress * (1.0 - progress) * 4.0 + progress * 1.5;
    score += pr * coupling * 0.5;

    // Reward filling bins snugly relative to mean residual of open bins.
    let mean_norm = mean_residual / cap;
    score -= (cap - pr) * 0.05 * (1.0 - mean_norm);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize opening new bins when many bins are already open, smoothly.
    let open_norm = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * open_norm + 20.0 * progress * progress;
        // But allow a new bin if the item would leave an awkward residual in existing bins.
        let awkward = (norm_post - 0.5).abs();
        score -= 25.0 * awkward * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            let slack = pr - next;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            score += 3.0 * (next - pr) / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items sizes 1..100, capacity 100.
    // Classify post_residual by integer division into dead-space bands.
    let class = post_residual / 10; // 0..10 harmonic class
    // Penalize awkward classes (small leftovers that nothing fits into).
    let awkward: [f64; 10] = [0.0, 12.0, 9.0, 6.0, 4.0, 2.0, 0.0, 0.0, 0.0, 0.0];
    score += awkward[class.min(9) as usize];

    // Reward tight fits (harmonic pairing: post_residual close to a common size band).
    if post_residual <= 5 {
        score -= 15.0; // near-perfect packing
    } else if post_residual >= 90 {
        score -= 8.0; // bin nearly full
    }

    // Lookahead coupling: prefer leaving space that matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff <= 3 {
            score -= 20.0; // next item fits this bin perfectly
        } else if (post_residual as i64) < (next_item_size as i64) {
            score += 5.0; // leftover unusable for next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large or fit is bad.
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        if waste < 25 {
            score -= 30.0; // big item, fresh bin is fine
        } else if fitting_bins_count > 0 {
            score += 40.0 + (waste as f64); // discourage wasteful new bin
        } else {
            score -= 10.0;
        }
    }

    // Prefer filling bins with larger residuals relative to mean (balance classes).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild late-stream pressure to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // are pure waste, so punish them quadratically.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: when many bins are open, prefer
    // consolidating into existing bins; when few, new bins are cheaper.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer bins with below-mean residual (consume the emptiest-ish bins),
    // but only mildly so tight-fit logic dominates.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Lookahead: if the next item would fit exactly into this bin's
    // post_residual, reward heavily; if it cannot fit, mildly penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when residual is full capacity and fits are plentiful/poor.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count <= 1 { 0.0 } else { (fitting_bins_count as f64).ln() };
        score += 30.0 - poor_fits * 10.0 - (mean_residual / bin_capacity as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leaving almost nothing behind is excellent.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 2 {
        score -= 40.0;
    }

    // 2-step lookahead: if the next item exactly fills post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills the remainder.
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize dead space slightly.
            score += 8.0;
        }
    }

    // Relative-to-mean residual shaping: prefer bins whose residual is near/below mean
    // (tighter bins), discourage dumping into very loose bins.
    let res = post_residual as f64;
    if res > mean_residual + 10.0 {
        score += 0.5 * (res - mean_residual);
    } else if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // (few other bins would be efficient) late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let huge = item_size as f64 / bin_capacity as f64;
        score += 20.0 + 30.0 * progress - 40.0 * huge;
        // Opening a bin when next item is small wastes space.
        if next_item_size > 0 && next_item_size < 30 {
            score += 15.0;
        }
    }

    // Mild preference to fill bins with less residual overall (best-fit flavor).
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Penalize dead space: residuals too small for any plausible item (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or many bins are already open with poor residuals.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > bin_capacity as f64 * 0.5;
        let pressure = mean_residual / bin_capacity as f64;
        if bad_fit && pressure < 0.4 {
            score -= 8.0; // open a fresh bin when current bins are fragmented
        } else {
            score += 15.0; // prefer existing bins otherwise
        }
    }

    // Prefer fuller bins overall (best-fit flavor) scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * (8.0 + 6.0 * progress);

    // Mild penalty for spreading across many open bins late in the stream.
    score += open_bins_count as f64 * 0.3 * progress;

    // Nudge toward bins near mean residual (balanced consolidation).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized quantities
    let pr = post_residual as f64 / cap;              // post-residual in [0,1]
    let fill = 1.0 - pr;                              // fill level after placement
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_n = open_bins_count.max(1) as f64;

    // Smooth non-linear coupling: reward tight fits with polynomial decay
    // Tight fit => small pr => large reward, scaled by stream progress
    let tight_reward = (1.0 - pr).powi(3) * (1.0 + 2.0 * progress);
    score -= 20.0 * tight_reward;

    // Penalize dead space quadratically, stronger late in stream
    let dead = (pr * pr) * (1.0 + progress);
    score += 15.0 * dead;

    // Penalize residuals that cannot fit the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - post_residual as f64).max(0.0) / cap;
        let fits_next = (post_residual as f64 / nx).min(1.0);
        // reward if bin can still hold next item, penalize otherwise (smooth)
        score += 10.0 * gap * gap;
        score -= 8.0 * fits_next * fill;
    }

    // Last-chance bonus: only fitting bin => smooth urgency coupling with progress
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    } else {
        // slight penalty for spreading across many open bins
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Coupling with mean residual: prefer bins near the mean (smooth gaussian-like)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for opening new bins, growing with progress and open count
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 + progress) + 3.0 * open_n.sqrt();
    } else {
        score -= 5.0; // prefer reusing existing bins
    }

    // Normalized stream-progress polynomial modulation of overall score
    score *= 1.0 + 0.3 * progress * (1.0 - progress) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it lands in.
    let frac = post_residual as f64 / cap; // 0.0 = perfect fit
    let band = (frac * 10.0).floor() as i64; // integer division thresholds 0..10

    // Reward tight fits strongly; penalize dead space super-linearly per band.
    score += match band {
        0 => -60.0,
        1 => -10.0,
        2 => 5.0,
        3 => 12.0,
        4 => 20.0,
        5 => 28.0,
        6 => 36.0,
        7 => 45.0,
        8 => 55.0,
        9 => 65.0,
        _ => 75.0,
    };

    // Modulo arithmetic: residual classes that pair well with common item sizes (divisors of 100).
    // Residuals that are multiples of 10 or 25 are "harmonic" — likely to host future items exactly.
    let pr = post_residual;
    if pr == 0 {
        score -= 100.0; // perfect fill
    } else if pr % 25 == 0 {
        score -= 25.0;
    } else if pr % 10 == 0 {
        score -= 15.0;
    } else if pr % 5 == 0 {
        score -= 5.0;
    } else {
        score += 8.0; // non-harmonic dead space
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            let nfrac = next_item_size as f64 / pr as f64;
            score -= 20.0 * nfrac; // prefer bins where next item fills a large share
        } else {
            score += 10.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when current item is large and
    // no open bin offers a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let item_frac = item_size as f64 / cap;
        // Penalize opening a new bin; relief only for large items late in stream.
        score += 55.0 - 30.0 * item_frac;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_frac > 0.5 && mean_residual < item_size as f64 {
            score -= 35.0 * progress;
        }
        // Never open a new bin for a tiny item.
        if item_frac < 0.35 {
            score += 40.0;
        }
    }

    // Slight preference for bins below mean residual (balancing loads).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild stream-progression term: tighten packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small gaps (<= 10) are nearly unusable given
    // item sizes drawn from 1..100 with unknown distribution; treat
    // very small post-residuals as wasted space unless they are zero.
    if post_residual > 0 && post_residual <= 10 {
        score += 120.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 35.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: prefer spreading across existing bins when few
    // are open, but penalize hoarding many open bins with large residuals.
    score += 3.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no open bin fits well
        // or the current item is large enough to dominate a fresh bin.
        score += 25.0 + 4.0 * open_bins_count as f64;
        if item_size >= 70 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if the next item would fit into the post-residual,
    // reward creating that residual chain; otherwise penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Mean residual coupling: avoid dumping items into bins whose
    // residual is far below average (they are already tight).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // Stream progression: early on, be more willing to open bins
    // (future items unknown); late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0;
        } else if post_residual as f64 >= next_item_size as f64 {
            // next item can still fit: reward proportional to closeness
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit this bin afterwards: penalize dead space
            score += 10.0 + gap * 0.5;
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Penalize bins far above mean residual (wasteful), reward below-mean residual
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
    }

    // Late in the stream, be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward tight fits (small dead space) non-linearly.
    score -= 20.0 * (1.0 - post / cap).powi(3);

    // Strong reward for very tight fits (near-perfect packing).
    if post_residual <= 5 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, especially early in the stream
    // and when other bins could already fit the item.
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (1.0 - t);
        if fitting_bins_count > 0 {
            score += 12.0;
        }
        // Opening a new bin is more acceptable for large items (leaves small residual).
        score += 0.1 * item_size as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // Penalize bins that would leave residual too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mild dispersion penalty: prefer bins close to the mean residual (balanced packing).
    score += 0.05 * (mean_residual - post).abs();

    // Slight preference for reducing the number of open bins late in the stream.
    score += 0.02 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;
    let mut score = pr;

    // Core: reward tight fits (small post_residual) with non-linear emphasis
    score -= (1.0 - pr / cap).powi(3) * 60.0 * (0.6 + 0.4 * progress);

    // Penalize dead space: post_residual too small for the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = nx - pr;
        if gap > 0.0 {
            score += (gap / cap).powi(2) * 45.0 * (1.0 - 0.4 * progress);
        } else {
            // reward leaving room exactly useful for the next item
            score -= 12.0 * (1.0 + (nx / cap));
        }
    }

    // Penalize very small unusable slivers (dead space), smooth in pr
    score += (-(pr / 10.0)).exp() * 8.0;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild dispersion penalty: prefer bins below mean residual (consolidate fullness)
    score += ((pr - mean_residual) / cap) * 10.0;

    // New-bin candidate: penalize opening a new bin, more so early and when fits exist
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score = cap as f64 * (1.1 - 0.2 * progress) + 20.0 * (1.0 - fit) - 15.0 * open_pressure;
        // allow new bin for very large items late in stream
        score -= fit * fit * 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small dead-space classes" (0..=10, or exact multiples of 25) are prized.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else if pr <= 10 {
        score -= 12.0;
    } else if pr % 25 == 0 {
        score -= 10.0; // leftover usable by large item classes
    } else if pr % 10 == 0 {
        score -= 6.0;
    } else {
        score += 3.0 + ((pr % 10) as f64); // ragged leftovers penalized
    }

    // Integer-division threshold on bin_residual: bins in the "half-full to
    // nearly-full" band are the sweet spot for compacting.
    let half = bin_capacity / 2;
    if bin_residual > half + half / 2 {
        score -= 4.0; // bin already quite full -> keep compacting it
    } else if bin_residual < half / 2 {
        score += 5.0; // nearly empty bin: wasteful to fragment
    }

    // Lookahead coupling: if next item exactly fits the post_residual,
    // strongly reward (harmonic pairing of consecutive items).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 8.0;
            // modulo class match: next item's class divides leftover nicely
            if pr % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            score += 4.0; // next item cannot use this leftover
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening new bins
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish baseline that
    // only wins when open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score = cap * 0.35 + (open_bins_count as f64) * 0.5
            - (mean_residual - cap * 0.5).max(0.0) * 0.3;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big upcoming item: fresh bin is attractive
        }
    }

    // Mild stream-progress term: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Small tie-breaker toward bins whose residual is close to the item size
    // (best-fit flavor with harmonic sharpening).
    let gap = (bin_residual - item_size) as f64;
    score += gap * 0.05 + (gap * std::f64::consts::PI / cap).sin().abs() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 3.0 * post_residual as f64;
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual (waste ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins;
    // discourage opening new bins when plenty are already open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 20.0;
        } else {
            score -= 10.0 * (1.0 - gap / 100.0);
        }
    }

    // Prefer bins whose residual deviates below the mean (tighter bins used first).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize mildly so it's chosen only when no good fit exists,
    // but relax penalty late in the stream when consolidation is less useful.
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial lookahead credit: how close post_residual is to next item size.
        let gap = (post_residual - next_item_size) as f64;
        score -= 200.0 / (1.0 + gap / 10.0);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportionally to wasted potential.
        let miss = (next_item_size - post_residual) as f64;
        score += 30.0 * (1.0 - (miss / 100.0).min(1.0));
    }

    // Reward tight fits relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 50.0 * tightness * tightness;

    // Penalize deviating far above mean residual (creating dead space vs fleet average).
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.5 * dev;
    } else {
        score += 0.2 * dev; // mild reward for being below mean
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Late in the stream, consolidate: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, costly later or when many bins open.
        score += 20.0 + 60.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below a
    // "usefulness floor" is penalized extra (space too small for typical items).
    let floor = 10.0f64;
    if (post_residual as f64) < floor {
        score -= (floor - post_residual as f64) * 1.5; // near-perfect fill bonus
    } else {
        score += (post_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Lookahead: if the next item fits into this bin's post_residual, reward;
    // if post_residual cannot hold the next item, penalize wasted potential.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 3.0 + next_item_size as f64 * 0.05;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins where the item fills a larger fraction of residual.
        let frac = item_size as f64 / bin_residual as f64;
        score -= frac * 10.0;
    }

    // Time horizon: late in the stream, avoid opening new bins (fewer chances
    // to fill them), so penalize the new-bin candidate more as we progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 + progress * 40.0 + open_bins_count as f64 * 0.5;
    }

    // Global state: if mean residual is low, conserve open-bin space more
    // aggressively; if mean residual is high, spreading is less costly.
    let mr = mean_residual.max(0.0);
    score += (post_residual as f64 - mr) * 0.08;

    // Penalize leaving residuals that are awkwardly in the middle range.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 && pr >= floor {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on wasted space (dead space grows quadratically)
    let mut score = post * norm_post;

    // Smooth coupling: waste matters more late in the stream
    score += 8.0 * norm_post * progress;

    // Cubic term: strongly punish near-empty residuals (tiny unusable slivers)
    score += 12.0 * norm_post * norm_post * norm_post;

    // Reward tight fits (post_residual near 0) via smooth exponential-like shaping
    score -= 6.0 * (1.0 - norm_post).max(0.0) * (1.0 - norm_post).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer bins with below-mean residual (keep large bins free for large items)
    let mean_norm = mean_residual / cap;
    score -= 3.0 * (mean_norm - norm_post);

    // Lookahead coupling: penalize if next item could have used this residual better
    let next = next_item_size as f64;
    if next > 0.0 {
        let waste_vs_next = (post - next).max(0.0) / cap;
        score += 5.0 * waste_vs_next * waste_vs_next;
        // Reward if next item fits exactly in the post residual
        if post >= next && post - next < 10.0 {
            score -= 2.0;
        }
    }

    // Mild penalty on many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * norm_post;

    // New-bin candidate: make empty bins moderately attractive only for large items
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score = 15.0 - 20.0 * fill_ratio + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and residues that are
    // "friendly" divisors/multiples of common item sizes are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: zero waste
    } else {
        // Dead-space penalty grows super-linearly for small unusable residues.
        if pr < 10 {
            score += (10 - pr) as f64 * 2.5; // tiny unusable slivers
        }
        // Harmonic bonus: residue divisible by common small sizes (mod classes)
        let mut harmonic = 0.0;
        if pr % 10 == 0 { harmonic += 12.0; }
        else if pr % 5 == 0 { harmonic += 6.0; }
        if pr % 20 == 0 { harmonic += 6.0; }
        if pr % 25 == 0 { harmonic += 4.0; }
        if pr % 50 == 0 { harmonic += 8.0; }
        score -= harmonic;

        // Fraction-of-capacity classes: residues in the top quarter are easy
        // to fill later, so mildly prefer them.
        let frac = pr as f64 / bin_capacity as f64;
        if frac > 0.75 { score -= 5.0; }
        else if frac < 0.15 { score += 8.0; }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 15.0;
        } else if next_item_size > pr && next_item_size <= bin_residual {
            // next item needs this bin's CURRENT space; don't waste it
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into tight bins to allow closures.
    score += (open_bins_count as f64) * 0.15 * (1.0 - pr as f64 / bin_capacity as f64);

    // Progress scaling: late in stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Mean residual context: if this bin is far below mean residual it is
    // already tight; small extra penalty keeps balance.
    score += (mean_residual - pr as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Dead zone: residual too small for the smallest plausible follow-up item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 30.0;
    }

    // Lookahead synergy: if next item fits exactly in post_residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 1.5 * (1.0 - fit_ratio);

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no bin fits well (post_residual
    // of a fresh bin is large, so base score already high; add mild pressure).
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // But if current item is huge relative to mean residual, new bin is fine.
        if item_size as f64 > mean_residual * 0.9 {
            score -= 60.0;
        }
    }

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits (small post_residual is already favored by base term).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack left after hypothetically placing the next item too.
            let two_step_slack = post_residual - next_item_size;
            score -= 50.0 + two_step_slack as f64 * 0.5;
        } else {
            // Next item won't fit here: penalize proportionally to wasted lookahead.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Penalize creating dead space relative to mean residual across open bins.
    let mean_res = mean_residual;
    if (post_residual as f64) > mean_res + 20.0 {
        score += (post_residual as f64 - mean_res) * 0.4;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bin would leave awkward residue
    // and the item is large (tight fit in a fresh bin).
    if bin_residual == bin_capacity {
        let fresh_slack = bin_capacity - item_size;
        // Prefer fresh bin if item is huge (>= 60) or all other fits are bad.
        if item_size >= 60 {
            score -= 30.0;
        } else {
            score += 40.0 + fresh_slack as f64 * 0.3;
        }
        // Late in the stream, discourage opening extra bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing can use later (min item ~1)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins with slack: discourage spreading, prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += 0.15 * (open_bins_count as f64) * (1.0 - progress);
    }

    // Prefer bins with residual above mean (balance residuals)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when current item is small relative to
    // capacity and existing bins are fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        let fragmented = mean_residual / bin_capacity as f64;
        if fragmented < 0.5 || item_size > 60 {
            score += 25.0; // discourage new bin unless nothing fits well
        } else {
            score += 5.0;
        }
        // Late in stream, avoid opening new bins for small items
        if progress > 0.7 && item_size < 30 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothly warped by stream progress.
    // Early on, prefer tight fits mildly; late, penalize residual harder.
    let warp = 0.5 + 1.5 * progress;
    let mut score = pr * warp;

    // Smooth non-linear coupling: quadratic + cubic of normalized residual,
    // scaled by progress to grow penalty for large dead space over time.
    score += (norm_pr * norm_pr) * cap * (0.2 + 0.8 * progress);
    score += (norm_pr * norm_pr * norm_pr) * cap * progress;

    // Reward near-perfect fits: smooth bell around small residuals.
    let perfect = (-norm_pr * norm_pr * 30.0).exp();
    score -= perfect * (10.0 + 20.0 * progress);

    // Lookahead: bonus if next item fits in the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - (next_item_size as f64 / pr.max(1.0)).abs();
        score -= (5.0 + 10.0 * progress) * (0.5 + snug);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize opening new bins when many bins are already open and mean
    // residual is high (fragmentation pressure), smoothly coupled.
    let frag = (open_bins_count as f64) / (1.0 + open_bins_count as f64);
    score += frag * mean_residual * (0.1 + 0.3 * progress);

    // Slight penalty if this bin is brand new (residual == capacity) unless
    // nothing fits — encourage reusing open bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residual modulo capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual small relative to capacity
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    }

    // Penalize dead space that no plausible item (10..80) can use well:
    // leftover in (1..10) is actually great (near-full), leftover just above
    // common item sizes is bad. Use modulo arithmetic on post_residual.
    let mod_class = post_residual % 25; // harmonic class over quarter-capacity
    score -= (mod_class as f64) * 0.4;  // mild class-based shaping

    // Dead-space penalty: leftover that is too small for the smallest item
    // (interface: items >= 1, but typical stream items are >= 10) yet nonzero
    if post_residual >= 1 && post_residual < 10 {
        score -= 20.0; // effectively sealed bin: good
    }

    // Coupling with lookahead item: if next item fits exactly in the leftover,
    // strongly reward; if leftover is just barely too small for next item, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 10.0; // next item just misses: leftover likely wasted
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Make it attractive only when open bins are fragmented or the item is large.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if item_size > bin_capacity / 2 {
            score -= 6.0; // large items like fresh bins
        }
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 25.0; // nothing usable open: open a new bin
        }
        if open_bins_count > 4 && fragmentation < 5.0 {
            score += 20.0; // many similar bins: prefer filling one instead
        }
        // scale new-bin penalty with stream progress: late in stream, consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure to prefer fuller bins among equals
    score -= (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are worthless.
    if post_residual < 10 {
        score += 40.0; // unusable sliver: strong penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill: big reward
    } else if post_residual < item_size {
        score += 8.0; // gap can't take another item of this size class
    } else if post_residual >= item_size {
        score -= 6.0; // gap remains reusable
    }

    // Exact match to next item's size: reserve this space perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that fits next item only marginally (waste risk).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 3.0;
    }

    // Tight fit reward: fill fraction of the space being consumed.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill;

    // Open-bin pressure: discourage scattering across many bins unless fit is tight.
    score += (open_bins_count as f64) * (1.0 - fill) * 0.6;

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins),
    // penalize dumping into already-loose bins.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate handling: neutral baseline, but avoid opening bins early in the
    // stream when open bins exist and fit reasonably; encourage late in stream only
    // if all fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score = 0.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it fills
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // next item cannot use this bin's residual: penalize dead space
            score += 12.0;
        }
    }

    // Penalize residuals below the smallest plausible item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Compare against mean residual: prefer bins with less residual than average
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless all fits are bad
    if bin_residual == bin_capacity {
        score += 55.0;
        // If no existing bin fits, allow opening a new bin
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item could co-exist in the post residual,
    // reward this bin; if next item is large and only barely fits now,
    // prefer saving this bin's residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else if (bin_residual as u32) >= next_item_size && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // New-bin candidate logic: an empty bin has huge raw residual, but we
    // add a penalty so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheap; later, prefer reuse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (balancing load) when
    // many bins are open.
    if open_bins_count > 2 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.6 * progress * progress);

    // Smooth curvature penalty: reward tight fits (small post_residual) more strongly late in stream
    let curvature = 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize post_residual that is unusable for a wide range of items (too small)
    let dead = if pr > 0.0 && pr < 10.0 { 25.0 * (10.0 - pr as f64) / 10.0 } else { 0.0 };

    // Lookahead: reward residual that can still hold the next item
    let lookahead = if next_item_size > 0 {
        let fits = (pr as u32 >= next_item_size) as f64;
        -15.0 * fits * (1.0 - progress)
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -30.0
    } else {
        0.0
    };

    // New-bin candidate: neutral-ish baseline, penalize slightly if open bins are sparse
    let new_bin = if bin_residual == bin_capacity {
        10.0 + 5.0 * (open_bins_count as f64).ln().max(0.0) + 20.0 * progress
    } else {
        0.0
    };

    // Divergence from mean residual: prefer bins whose post-residual aligns with fleet mean
    let align = 0.3 * (pr - mean_residual).abs();

    base + curvature + dead + lookahead + last_chance + new_bin + align
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

