    }

    // Small usable residual (<= 10% capacity) is nearly dead space: penalize mildly,
    // but a perfect-zero is best, so keep small nonzero worse than larger usable space.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }

    // Residual in the "harmonic sweet zone" (10..=25% capacity) is very reusable:
    // reward so these bins win ties over fresh bins.
    if post_residual > 10 && post_residual <= 25 {
        score -= 40.0;
    }

    // Modulo classes of post_residual: residuals that are multiples of 10 align
    // with common item sizes -> more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly prefer this bin (two-item chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            // Reward chain fits that leave good residuals again.
            if npost <= 25 {
