            } else if npost % 10 == 0 {
                score -= 25.0;
            }
        } else {
            // Next item can't use this residual: residual likely dead -> penalize
            // proportionally to how "odd" the residual is.
            if post_residual % 10 != 0 && post_residual < next_item_size {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: brand-new empty bin should only win when no
    // open bin offers a decent fit. Give it a neutral-to-high baseline.
    if bin_residual == bin_capacity {
