        if next_item_size > 60 && item_size < 40 {
            score -= 35.0;
        }
    }

    // Mild global pressure: prefer tighter bins when many are open.
    score -= 0.05 * mean_residual.min(cap_f);

    // Integer-division threshold: residual >= half capacity is roomy; slight
    // penalty so we prefer filling bins with less room first.
    if post_residual >= (bin_capacity / 2) && bin_residual != bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are "dead" — punish them hard.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Penalize leaving a gap that only a very small item could use,
    // but is above the hard-dead threshold.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more expensive.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has high residual; make it
    // attractive only when no open bin fits well, otherwise discourage.
    if bin_residual == bin_capacity {
        let base = 20.0 + open_bins_count as f64 * 2.0;
        score += base;
        // If the item would leave a large residual in a fresh bin anyway,
        // opening is fine when few bins are open.
        if open_bins_count <= 2 {
            score -= 25.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward preserving that pairing.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // Penalize placements that leave a residual the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Slight drift over the stream: early on, be a bit more willing to
    // open bins; later, be conservative.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward perfect 2-step match — post_residual exactly fits next item.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 60.0; // perfect chain: fills bin exactly over two items
        } else if diff > 0 && (diff as u32) <= 10 {
            score -= 30.0 * (1.0 - diff as f64 / 10.0); // near-perfect chain
        } else if diff < 0 {
            // next item cannot fit here; penalize small dead space more when it's tiny
            let dead = -diff as f64;
            score += 8.0 * (10.0 / (dead + 1.0)).min(6.0); // tiny gaps are wasted space
        }
        // lookahead relative to mean residual state
        let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if (post_residual as f64 - mean_residual).abs() < 5.0 {
            score -= 5.0 * (1.0 - prog); // keep residual profile balanced early
        }
    } else {
        // last item: maximize fill
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let good_chain = next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 10;
        if fitting_bins_count > 0 && !good_chain {
            score += 45.0; // discourage opening new bin when a usable fit exists
        } else {
            score -= 10.0;
        }
    }

    // Penalize leaving large unusable gaps relative to smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space smaller than any item
    }

    // Prefer tighter bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64; // tightness of fit
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, weighted more for large dead space.
    let mut score = post * (1.0 + 0.5 * (post / cap));

    // Reward tight fits strongly (small post_residual relative to residual).
    score -= 8.0 * fit_ratio * fit_ratio;

    // Lookahead: if next item fits into post_residual, this placement chains nicely.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 4.0 * (next_item_size as f64 / post.max(1.0));
        } else {
            // Penalize leftovers that no plausible item can use (dead space).
            score += 3.0 * (1.0 - post / cap);
        }
    } else {
        // Last item: only exact fits matter.
        if post_residual == 0 { score -= 10.0; }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins with high mean residual: encourage consolidation into existing space.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 2.0 * (mean_residual / cap);
    }

    // Early in stream: prefer opening new bins to keep flexibility (avoid fragmenting few bins).
    // Late in stream: strongly prefer filling existing bins.
    let new_bin_bias = (1.0 - progress) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: competitive early, penalized late.
        score += new_bin_bias;
        score -= 1.5 * (post / cap); // empty bin has large post_residual naturally
        if fitting_bins_count == 0 { score -= 5.0; } // no alternative: must open
    } else {
        score -= progress * 3.0; // late-stream reward for using open bins
    }

    // Exact fill is always excellent.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth polynomial shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Dead-space penalty: residuals too small to ever fit (min item 1, but
    // practically small slivers) get a smooth super-linear penalty.
    let tiny = (1.0 - norm_pr).clamp(0.0, 1.0);
    score += 12.0 * norm_pr * norm_pr * (1.0 - norm_pr * norm_pr) * (1.0 - progress);

    // Perfect fit reward: smooth bump near zero post_residual.
    score -= 25.0 * (-norm_pr * 40.0).exp();

    // Lookahead coupling: reward residuals that can host the next item,
    // penalize residuals that strand the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 8.0 * (-slack * 6.0).exp() * (1.0 - progress * 0.5);
        } else {
            let miss = (ni - pr) / cap;
            score += 6.0 * (-miss * 8.0).exp();
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - progress * 0.3);
    }

    // New-bin candidate: penalize opening a new bin when good fits exist,
    // but allow it when existing residuals are fragmented (high mean_residual
    // relative to item) or late in the stream when many bins are open.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - item_size as f64 / cap).max(0.0);
        score += 20.0 - 15.0 * fragmentation * fragmentation - 10.0 * progress;
        score += 1.5 * open_bins_count as f64;
    } else {
        // Mild preference for bins whose residual is close to item (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64) / cap;
        score += 4.0 * tightness * tightness;
    }

    // Late-stream consolidation: encourage filling existing bins harder.
    score *= 1.0 - 0.15 * progress * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are "perfect fits"
    // for common item classes (multiples of 10, and small residuals) are
    // valuable dead space; large awkward residuals are less useful.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect closure
    } else if r % 10 == 0 && r >= 10 {
        // residual exactly matches a harmonic item class -> likely reusable
        score -= 12.0;
    } else if r < 10 {
        // tiny dead space: nearly full bin, good
        score -= 8.0;
    } else {
        // awkward residual: penalize proportionally to how far from a
        // multiple of 10 it is (harmonic distance)
        let dist = (10 - (r % 10)) as f64;
        score += dist * 1.5;
    }

    // Integer-division threshold: bins whose residual can hold the next
    // item (lookahead chaining) deserve a reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = (next_item_size as f64) / (post_residual as f64);
        score -= 10.0 + 20.0 * tight;
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty, worse if residual is large
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // is large relative to capacity or many bins are already open.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = 100.0 - 55.0 * frac - 30.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // stacking large items into fresh bins
        }
    }

    // Late-stream consolidation: favor tight fits as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if open bins are generally slack, prefer
    // filling the slackest-compatible bins harder.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps (below the minimum item
    // size of 1..100 stream -> treat anything < ~10 as near-dead) are heavily
    // penalized. Exact fits are strongly rewarded.
    if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else if post_residual < 10 {
        score += 300.0; // unusable dead space
    } else if post_residual < 20 {
        score += 120.0;
    } else if post_residual < 35 {
        score += 40.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + 0.5 * next_item_size as f64;
        } else {
            score += 30.0; // cannot host the lookahead item
        }
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // prefer consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 1.0 + 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    score *= pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make the empty bin attractive only when existing bins
    // would create dead space or the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by how much dead space we avoid.
        score += 150.0 + 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 400.0; // nothing fits elsewhere -> new bin is required
        }
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score -= 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space quadratically: small residuals are wasteful.
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64);

        // Aggressive 2-step lookahead: reward if next item fits the leftover.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0; // perfect chaining
            } else if next_item_size <= post_residual {
                // Reward proportionally to how well next item consumes leftover.
                let fill = next_item_size as f64 / pr;
                score -= 300.0 * fill;
            } else {
                // Next item cannot use leftover: leftover likely dead space,
                // penalize more if leftover is small (unusable).
                if post_residual < 10 {
                    score += 150.0;
                } else {
                    score += 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
                }
            }
        }
    }

    // Relative-to-mean coupling: prefer bins whose leftover is below average
    // (tighter packing), penalize bins with above-average leftover.
    score += 2.0 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor. Give the empty bin a baseline score that is
    // competitive but slightly worse than a good existing fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + 30.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // opening fresh may help future large items
        }
    }

    // Late-stream pressure: as the stream progresses, discourage proliferation
    // of open bins slightly to keep consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a non-linear bonus.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Penalize bins whose residual is far below the mean (poor global fit).
    score += 0.35 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item won't fit anywhere after this placement, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual {
            score += 3.0;
        }
        // Reward leaving room for next item generally.
        if post_residual >= next_item_size {
            score -= 2.0;
        }
    }

    // New-bin candidate: only attractive when existing bins fit badly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual as f64; // = capacity - item
        score = bad_fit + 20.0 - 15.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 30.0; // must open a bin anyway
        }
    }

    // Slight preference for filling bins when many are open.
    score += 0.05 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress.
    // Early in the stream, tolerate large residuals (bins stay flexible).
    // Late in the stream, penalize large residuals more aggressively.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (0.5 + progress) + pr_norm * (1.0 - progress);
    score += 30.0 * poly;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - pr_norm;
    score -= 20.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // If the next item fits exactly in the post_residual, reward keeping this bin for it.
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= pr;
        if next_fits {
            let slack = pr - next_item_size as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Post-residual too small for next item: mild penalty for dead space.
            score += 5.0 * pr_norm * progress;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (0.5 + progress);
    }

    // New-bin candidate handling: an empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so early (flexibility is cheap later? no:
        // early opening is fine, late opening adds bins when stream nearly done).
        score += 10.0 + 20.0 * progress;
        // If many bins already fit, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If the item fits poorly everywhere, a fresh bin may still be best:
        // soften the penalty when the item is large relative to capacity.
        let fill = item_size as f64 / cap;
        score -= 25.0 * fill * fill;
    }

    // Slight preference for bins with residuals below the mean (consolidate space).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev.abs().sqrt() * (0.5 + progress);

    // Mild load balancing: fewer open bins -> prefer spreading across them.
    if open_bins_count > 0 {
        score += 2.0 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual as u32;
    let class = pr % (bin_capacity / 4).max(1); // quarter-capacity harmonic class
    // Residuals that are "harmonically clean" (multiples of 25) are more reusable.
    if class == 0 && pr > 0 {
        score -= 12.0;
    } else {
        score += class as f64 * 0.35;
    }

    // Penalize awkward dead zones: residuals just below common item sizes (1..100 unknown dist).
    // Use integer division thresholds: post_residual in [1,10] is nearly unusable.
    if pr <= 10 && pr > 0 {
        score += 25.0;
    } else if pr >= 11 && pr <= 20 {
        score += 10.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly or with small waste.
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            let slack = pr - n;
            if slack == 0 {
                score -= 30.0; // perfect lookahead fit
            } else if slack <= 10 {
                score -= 15.0;
            } else {
                score += slack as f64 * 0.15;
            }
        } else {
            // next item cannot fit here; residual may still be useful later.
            score += 5.0;
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score; prefer it only when
    // existing fits are terrible (high post_residual penalty dominates).
    if bin_residual == bin_capacity {
        // Opening fresh: score slightly worse than a perfect fit, better than a bad one.
        score = cap * 0.55 - (item_size as f64 / cap) * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing large items together
        }
        // Late in stream, discourage opening too many bins if mean residual is healthy.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 8.0;
        }
    }

    // Best-fit tightening: favor smaller post_residual among similar classes.
    score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.05;

    // Mild pressure against bin sprawl early-to-mid stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 10 && progress < 0.9 {
        score += 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small to hold even the smallest item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 50.0; // unreachable in practice, but guards the concept
    }
    // Quasi-dead space: residual below a fraction of capacity that few future items can use.
    let dead_threshold = 0.15 * bin_capacity as f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // leaving a gap too small for the next item is wasteful
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins
    // and encourage filling existing ones (tight fits preferred).
    let pressure = open_bins_count as f64 * 0.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins fit poorly or none exist.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 && post_residual as f64 > dead_threshold {
            // last-chance bin exists: strongly prefer using it over a new bin
            score += 40.0;
        } else {
            score += pressure * 2.0;
        }
    } else {
        // Existing bin: slight bonus when it is the only fitting bin (avoid opening new).
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Prefer bins whose residual is close to the item (tight packing).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * pressure;
        // Prefer bins below mean residual (emptier bins get filled first, keeping
        // near-full bins for perfect fits).
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        }
    }

    // Early in the stream, be slightly more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits (low dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else {
        // Penalize dead space quadratically relative to capacity.
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 150.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack must be tight enough that the next item is a good fit too.
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 80.0;
            if slack_after_next <= 5.0 {
                score -= 150.0; // chain of two near-perfect placements
            } else {
                score -= (bin_capacity as f64 - slack_after_next) / bin_capacity as f64 * 40.0;
            }
        } else {
            // Post residual too small for next item: penalize proportionally to waste.
            let waste = post_residual as f64 / next_item_size as f64;
            score += waste.min(2.0) * 60.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight",
    // placing there concentrates waste; prefer bins near/above mean unless fit is exact.
    let res_f = post_residual as f64;
    if res_f > mean_residual {
        score -= (res_f - mean_residual).min(50.0) * 0.8;
    } else if res_f < mean_residual {
        score += (mean_residual - res_f).min(50.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Mild pressure against bin sprawl when many bins are open.
    score += open_bins_count as f64 * 2.0;

    // Early-stream: be slightly more conservative (keep bins balanced for future items).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 30.0;

    // New-bin candidate: only attractive when current bin would leave bad dead space
    // and the item fits poorly everywhere. An empty bin gives full flexibility.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted if the fit in existing bins is bad.
        let mut new_bin_cost = 120.0;
        if post_residual == item_size as f64 as u32 && post_residual == item_size {
            // this IS the empty bin call: post_residual = C - item
            let empty_waste_potential = (bin_capacity - item_size) as f64;
            if next_item_size > 0 && empty_waste_potential < next_item_size as f64 {
                new_bin_cost += 40.0; // new bin would strand next item too
            }
        }
        if post_residual <= 10 {
            new_bin_cost -= 100.0; // item nearly fills a fresh bin: great choice
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (dead space minimization).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize residuals that are too small to ever be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead (k=2): penalize placements that block the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving room for the next item, scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 6.0 + 0.25 * next_item_size as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let mean_fit_gap = if next_item_size > 0 { mean_residual } else { mean_residual };
        // Base cost of opening a new bin, discounted when open bins are crowded.
        score = 55.0 + 0.3 * open_bins_count as f64
            - 0.15 * mean_fit_gap
            - 20.0 * (1.0 - (item_size as f64) / (bin_capacity as f64));
        // Early in the stream, opening bins is cheaper (build a pool).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Slight preference for bins with residual close to the mean (balanced packing).
    score += 0.08 * ((bin_residual as f64) - mean_residual).abs();

    // Time-horizon modulation: as the stream ends, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses.
    let pr_norm = pr / cap;
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 12.0 * tightness * (0.4 + 0.6 * progress);

    // Penalize residuals that can't hold the next item (dead space prediction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 0.5 * (nx - pr);
        } else {
            // Reward leaving space exactly usable by next item (smooth kernel).
            let fit = (pr - nx) / cap;
            score -= 6.0 * (-8.0 * fit * fit).exp();
        }
    }

    // New-bin candidate: penalize opening a bin unless existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity && post_residual < bin_capacity;
    if is_new_bin {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        let waste = (pr - item_size as f64).abs() / cap;
        score += 20.0 - 15.0 * scarcity * (1.0 - waste);
        score += open_bins_count as f64 * 0.3;
    }

    // Mild preference for filling bins below average residual (balance avoidance).
    score += 0.1 * (pr - mean_residual).abs().ln1p();

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residue modulo small divisors of capacity
    let pr = post_residual as u32;
    let mod8 = pr % 8;
    let mod16 = pr % 16;
    let mod25 = pr % 25;

    // Penalize residuals that are "awkward" (small nonzero dead space)
    if pr > 0 && pr <= 9 {
        score += (10.0 - pr as f64) * 6.0; // tiny dead space is worst
    }

    // Favor residuals in "harmonic" classes: multiples of 25, 20, 10, 8, 5
    if pr % 25 == 0 { score -= 30.0; }
    if pr % 20 == 0 { score -= 20.0; }
    if pr % 10 == 0 { score -= 12.0; }
    if pr % 5 == 0 { score -= 5.0; }

    // Next item lookahead: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0; // chains a perfect fit
        } else if next_item_size <= pr {
            let npr = pr - next_item_size;
            // Reward if pair leaves harmonic residue
            if npr % 10 == 0 { score -= 25.0; }
            if npr % 25 == 0 { score -= 35.0; }
            if npr > 0 && npr <= 9 { score += 20.0; } // pair creates tiny dead space
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here: penalize slightly more if this bin is a new bin
            score += 5.0;
        }
    }

    // Capacity-fraction thresholds: bin filled past 3/4 is valuable
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 0.75 { score -= 15.0; }
    if fill_frac >= 0.9 { score -= 20.0; }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: default score is full residual; adjust based on stream progress
    if bin_residual == bin_capacity {
        // Early stream: opening bins is cheap-ish; late stream: prefer filling existing
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 50.0 * progress;
        // If next item is large and no good fit, opening new bin may help
        if next_item_size >= 60 && fitting_bins_count <= 1 { score -= 30.0; }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Small tie-breaker against fragmenting open bins when many are open
    if open_bins_count > 8 {
        score += (open_bins_count as f64) * 0.5;
    }

    // Integer-division threshold on post_residual: buckets of 16
    let bucket = pr / 16;
    score -= bucket as f64 * 2.0;

    // mod16 penalty for awkward small residues
    if mod16 > 0 && mod16 <= 4 { score += 4.0; }
    let _ = mod8; let _ = mod25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit is ideal
    }

    // Penalize post_residual that cannot host the lookahead item (creates a stranded gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // gap remains usable for the next item
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // over opening new ones; with few bins, be less picky.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 20.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins moderately attractive only when fits are poor.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 25.0; // no alternative, new bin is fine
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Late-stream tightening: as stream progresses, avoid leaving mid-range gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect packing: small post_residual is good, but zero dead space is best.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item exactly fills the remaining space,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too: reward proportionally to how much of the
            // post_residual it consumes (tight chaining is desirable).
            let fill_frac = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill_frac;
        } else {
            // Next item cannot use post_residual: penalize large dead space,
            // scaled by how far the next item overshoots.
            let waste = next_item_size - post_residual;
            score += 0.15 * waste as f64;
        }
    }

    // Compare against mean residual across open bins: bins tighter than average
    // should be filled first (best-fit bias relative to fleet state).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing open bins unless the fit is poor (large post_residual)
    // and there are many open bins already fragmenting capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when the stream is young
        // or when open bins are already fragmented.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 45.0 - 20.0 * progress;
        if open_bins_count > 3 {
            new_bin_cost -= 10.0;
        }
        // If the next item is small, an empty bin offers flexible future use.
        if next_item_size > 0 && next_item_size <= 30 {
            new_bin_cost += 10.0;
        }
        score += new_bin_cost;
    }

    // Mild penalty for very large items into very tight bins (risk of miscalculation
    // is nil, but tight fits that leave 1-9 units are handled above; discourage
    // mid-range waste explicitly).
    if post_residual >= 10 && post_residual <= 20 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size < post_residual {
            let waste = post_residual - next_item_size;
            score -= 20.0 * (1.0 - waste as f64 / (bin_capacity as f64));
        } else {
            score += 8.0; // next item cannot use this residual anyway
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 0.0 {
        let rel = (post_residual as f64) / mean_residual;
        score += 10.0 * (rel - 1.0).tanh(); // below-mean residual rewarded
    }

    // Early stream: slightly favor opening new bins to spread load; late stream: consolidate.
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == bin_capacity;
    if bin_residual == bin_capacity {
        let gap = (bin_capacity - item_size) as f64;
        // New bin baseline cost; grows late in stream.
        score += 40.0 + 30.0 * progress;
        // If item is huge relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 35.0;
        }
        // If few fitting bins exist, new bin is more acceptable.
        score -= 5.0 * (fitting_bins_count as f64).ln().max(0.0);
        let _ = gap;
    }

    // Mild penalty for leaving residual equal to small awkward sizes (prime-ish dead zones).
    match post_residual {
        1..=9 => score += 12.0,
        10..=20 => score -= 5.0,
        _ => {}
    }

    // Coupling: prefer bins whose residual is close to item size (snug but not exact waste).
    let snug = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * snug;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with quadratic sharpening.
    let mut score = pr + 12.0 * (pr / cap) * (pr / cap) * cap * 0.1;

    // Smooth stream-progress coupling: late in the stream, tighten residual preference.
    let tightness = 1.0 + 2.5 * progress * progress;
    score *= tightness;

    // Reward near-perfect fits (small post_residual) with smooth exponential bonus.
    let fit_ratio = 1.0 - (pr / cap);
    score -= 8.0 * fit_ratio * fit_ratio * fit_ratio;

    // Penalize bins whose residual deviates from mean (encourage residual homogenization).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 2 {
        score += 0.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Lookahead coupling: reward leaving space compatible with next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 2.0 * (1.0 - ((pr - n) / cap).abs());
        } else {
            score += 1.5 * (n - pr) / cap;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = pr + 4.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 4 classes
    let class = post_residual / (bin_capacity / 4).max(1);
    match class {
        0 => score -= 40.0,          // near-perfect fit: residual < 25
        1 => score -= 10.0,          // good fit
        2 => score += 5.0,           // mediocre
        _ => score += 20.0,          // wasteful placement
    }

    // Dead-space penalty: residual too small for any plausible future item (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last chance: only this bin fits the item -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer filling bins with small residuals relative to fleet mean
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Slight preference for existing bins over opening new ones as stream matures
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * progress;
    }

    // Modulo harmonic: exact quarter/half splits of capacity are valuable
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Mild penalty for accumulating many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are wasted.
    // Penalize post_residual that is too small to be useful (unusable dead space),
    // reward post_residual that is either zero (perfect fit) or large enough to matter.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strong reward
    } else {
        // Non-linear penalty for small gaps: the smaller the gap, the worse.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 12.0; // hard dead-space penalty
        } else if pr < 25.0 {
            score += (25.0 - pr) * 3.0; // soft penalty for marginal gaps
        }
    }

    // Reward tightness of fit: how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage opening new bins when many are open.
    // For the new-bin candidate (bin_residual == bin_capacity), apply pressure
    // proportional to open_bins_count.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 8.0;
        // But if this bin is the last chance to fit the item, opening a new bin
        // may be preferable to a bad fit in an existing bin.
        if fitting_bins_count == 1 {
            // If the existing fit would create heavy dead space, favor the new bin.
            if post_residual > 0 && post_residual < 10 {
                score -= 15.0;
            }
        }
    } else {
        // Existing-bin candidate: slight reward for using open bins.
        score -= 5.0;
        // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to how well it fits
            let nr = next_item_size as f64 / post_residual as f64;
            score -= nr * 10.0;
        } else {
            // next item won't fit in residual: penalize small residuals that
            // block the next item, scaled by stream progression.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (next_item_size - post_residual) as f64 * 0.15 * (0.5 + progress);
        }
    }

    // Mean-residual coupling: prefer bins with residual below mean (tighter bins),
    // pushing consolidation into nearly-full bins.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(-1.0);
        // Perfect chain fit bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Exact fill bonus
        if post_residual == 0 {
            score -= 40.0;
        }
    } else {
        // Last item: strongly prefer exact fills
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Penalize tiny dead space (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Penalize leaving large residual far above mean (wasteful spread)
    if (post_residual as f64 - mean_residual) > 0.0 {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless lookahead chains well
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 20.0 };
        score += 45.0 + chain_bonus + 0.5 * open_bins_count as f64;
        if post_residual == 0 {
            score -= 60.0; // perfect fill in fresh bin is fine
        }
    }

    // Late-stream tightening: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.0 + progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual (already partly via base).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits into post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement blocks the next item from using this bin; mild penalty
            score += 8.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when the
    // current bin is a poor fit (large post_residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open a new bin early in the stream (more future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If many bins fit, prefer reusing; if only this bin fits, opening new is fine.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // If mean residual across open bins is small, open bins are nearly full;
        // opening a new bin is reasonable.
        score -= 0.3 * mean_residual;
        // Large items leave little waste in a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Mild penalty when open bins are plentiful and this one is loose fit.
        if post_residual as f64 > mean_residual {
            score += 0.15 * (post_residual as f64 - mean_residual);
        }
    }

    // Prefer filling bins that are already mostly full (waste consolidation).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    let mut score = pr;

    // Reward tight fits, amplified as stream progresses
    score -= (1.0 - norm_post).powi(3) * (20.0 + 40.0 * progress);

    // Penalize small dead space that is hard to reuse (smooth trough)
    let dead = norm_post;
    score += 30.0 * dead * (0.15 - dead).powi(2).max(0.0) * 0.0;
    score += 25.0 * (-(dead - 0.1).powi(2) / 0.01).exp();

    // Lookahead: reward residual that can hold next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 15.0 * (1.0 - (pr - n as u32 as f64).abs() / cap) * (0.5 + progress);
        } else {
            score += 10.0 * (1.0 - n / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (1.0 - progress * 0.5);
    }

    // New bin candidate: penalize mildly, less so when open bins are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).abs();
        score += 8.0 + 20.0 * progress - 12.0 * frag;
    }

    // Penalize bins far from mean residual (prefer balanced fills)
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Mild penalty for many open bins
    score += (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (or small) are more reusable dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fit is best
    } else if pr <= 10 {
        score += 40.0; // tiny unusable sliver
    } else {
        // reward residuals that many item sizes can still use
        let mut div_count = 0u32;
        for d in 1..=10u32 {
            if pr % d == 0 {
                div_count += 1;
            }
        }
        score -= 8.0 * div_count as f64;

        // integer-division thresholds on post_residual
        if pr % 10 == 0 {
            score -= 15.0; // round decade residuals align with item grid
        }
        if pr % 25 == 0 {
            score -= 10.0; // quarter-capacity alignment
        }
        if pr >= 50 {
            score -= 12.0; // half-capacity residual still very usable
        } else if pr < 20 {
            score += 18.0; // cramped residual, penalize
        }
    }

    // Lookahead coupling: if next item fits exactly in post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Avoid spreading across too many open bins when mean residual is high.
    if (mean_residual - post_residual as f64).abs() > 30.0 {
        score += 10.0;
    }
    if open_bins_count > 4 && post_residual as f64 > mean_residual {
        score -= 5.0;
    }

    // New-bin candidate handling: only prefer fresh bin when all open
    // residuals are poor (small) relative to the item.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (100.0 - mean_residual) / 100.0;
        if fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.6 {
            score -= 30.0 + pressure;
        } else {
            score += 25.0 + pressure * 0.5; // keep using open bins
        }
    }

    // Mild stream-progression regularization.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the smallest plausible item
    // (1..=5) are pure waste -> heavy quadratic penalty.
    if post_residual > 0 && post_residual < 6 {
        score += 40.0 * (6.0 - post_residual as f64) * (6.0 - post_residual as f64);
    }

    // Reward tight fits (small but usable post residual).
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 12.0 - post_residual as f64; // near-perfect fill
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += 0.9 * open_bins_count as f64;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item would fit current residual
    // but not post residual, penalize blocking.
    if next_item_size > 0 {
        if next_item_size as f64 == post_residual as f64 {
            score -= 20.0;
        } else if (next_item_size as u32) > post_residual && (next_item_size as u32) <= bin_residual {
            score += 8.0;
        }
    }

    // Mild progression pressure: early on, prefer consolidation into
    // existing bins; the new-bin candidate (residual == capacity) naturally
    // gets high post_residual, so it loses unless fits are poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * mean_residual / bin_capacity as f64;

    // Slight preference toward bins with residual close to item size
    // (minimizes relative waste).
    score += 3.0 * (bin_residual as f64 - item_size as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward leaving just enough room for the next item.
            score -= 40.0 / (1.0 + slack / 10.0);
        } else {
            // Next item won't fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Relative to mean residual: prefer bins whose post-residual is near/below
    // the mean (compact bins), penalize bins that stay far above the mean.
    let dev = (post_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to capacity (poor fit elsewhere would waste little).
    if bin_residual == bin_capacity {
        let waste_ratio = (bin_capacity - item_size) as f64 / (bin_capacity as f64);
        score += 20.0 + 30.0 * waste_ratio;
    }

    // Late in the stream, consolidation matters more: penalize leaving large residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Blocking the next item with a useless leftover.
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty for spreading across many fitting bins; prefer tightest.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with residual close to mean (balanced usage) when many bins open.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Early in the stream: allow opening new bins more freely to build a good pool.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 40.0 * progress;
        // But if no open bin fits at all, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Late in the stream: strongly prefer filling existing bins.
        score -= 15.0 * progress;
    }

    // Mild penalty for very large items going into nearly full bins (waste risk).
    if item_size >= 60 && bin_residual < item_size + 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress.clamp(0.0, 1.0);
    let poly = 1.0 + t * (0.8 - 1.6 * t); // smooth arch-shaped weighting

    let mut score = pr * (0.5 + 0.5 * poly);

    // Penalize dead space non-linearly (quartic-ish small residual penalty)
    score += 40.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm) * t;

    // Reward tight fits (small post_residual) more strongly late in stream
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * t;

    // Lookahead coupling: favor bins whose post_residual fits next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap) * (1.0 + t);
    } else if next_item_size > 0 {
        score += 8.0 * t;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Mild penalty for spreading across many open bins late
    score += 0.5 * open_bins_count as f64 * t;

    // New-bin candidate: smooth threshold via logistic of mean residual
    let logistic = 1.0 / (1.0 + (-8.0 * (mean_residual / cap - 0.35))).max(1e-9);
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.35 * logistic) + 20.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: bins partitioned into
    // residue classes modulo 10 (typical item granularity). Small
    // residues < 10 are "dead" and heavily penalized.
    let dead = (post_residual % 10) as f64;
    score += dead * 1.5;

    // Harmonic tier of post_residual via integer division thresholds.
    // Tier 0: post_residual == 0 -> perfect fit, big reward.
    // Tier 1: 1..=10 -> near-perfect.
    // Tier 2: 11..=30 -> usable for small items.
    // Tier 3: > 30 -> wasteful for a large item placement.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    } else {
        score += 12.0;
    }

    // Fraction-of-capacity coupling: reward when post_residual is a
    // clean fraction (1/4, 1/2) of capacity that a future item can match.
    let quarter = cap / 4.0;
    let half = cap / 2.0;
    let pr = post_residual as f64;
    if (pr - half).abs() < 1.0 || (pr - quarter).abs() < 1.0 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly into the post-residual,
    // strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0);
        } else {
            // next item cannot use this bin's remainder: mild penalty
            // scaled by how much would be wasted.
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (pristine bin): only attractive when current
    // item is large and no open bin fits well, or when open bins are
    // already fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progress
        // (late new bins amortize worse) and with number of open bins.
        score = cap * 0.9 + (open_bins_count as f64) * 2.0
            + (step_index as f64 / total_items.max(1) as f64) * 15.0;
        // If the item is huge (>= 3/4 capacity), a fresh bin is fine.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 30.0;
        }
        // If mean residual across open bins is tiny, open bins are
        // nearly full -> new bin is reasonable.
        if mean_residual < 12.0 {
            score -= 20.0;
        }
        // If next item is large too, fresh bin gives it room.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild preference to fill bins that are already mostly consumed
    // (keeps the count of open bins low).
    let fill_ratio = 1.0 - (bin_residual as f64) / cap;
    score -= fill_ratio * 10.0;

    // Small deterministic tie-breaker from harmonic class of item size.
    score += ((item_size % 7) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the smallest
    // plausible item are "dead" — penalize them heavily.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness bonus: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins;
    // a fresh empty-bin candidate gets penalized when bin count is already high.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty for leaving awkward gap
            score += 3.0;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to the
    // item size (good packing), penalize outliers.
    let dev = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * dev;

    // Mild stream-progression regularization.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits here too; penalize leftover after pair placement
            let pair_left = post_residual - next_item_size;
            score -= 100.0 - pair_left as f64 * 3.0;
            if pair_left == 0 {
                score -= 300.0;
            }
        } else {
            // next item cannot use this residual: penalize dead space relative to mean
            score += (post_residual as f64 - mean_residual).abs() * 0.5;
            if post_residual < 10 {
                score += 50.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so we prefer good fits into open bins,
    // but allow opening a new bin when residual would be awkward dead space
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= progress * (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits strongly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 range, min 1)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            // extra reward if post residual closely matches next item
            let gap = post_residual - next_item_size;
            score -= 4.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // penalize leaving a residual that just barely misses the next item
            let overshoot = next_item_size - post_residual;
            if overshoot <= 15 {
                score += 3.0 + 0.2 * overshoot as f64;
            }
        }
    }

    // Last-chance bonus: only bin that fits -> strong preference to use it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Scarcity pressure: many bins open, few fit -> prefer existing bins
    if fitting_bins_count > 0 && !is_new_bin {
        let scarcity = open_bins_count as f64 / (fitting_bins_count as f64 + 1.0);
        score -= 2.0 * scarcity.min(5.0);
    }

    // New-bin candidate handling: penalize opening new bin, more so early and when good alternatives exist
    if is_new_bin {
        let mut penalty = 10.0;
        // if there are other fitting bins, discourage new bin
        if fitting_bins_count > 0 {
            penalty += 12.0;
        }
        // early in stream, opening bins is cheap and useful
        penalty -= 6.0 * (1.0 - progress);
        // if mean residual is large, plenty of slack exists -> avoid new bin
        penalty += 0.15 * mean_residual;
        score += penalty.max(0.0);
    }

    // Slight preference for bins with below-average residual (keep large-slack bins flexible)
    if !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear base: quadratic waste penalty on post_residual.
    let mut score = post + 0.9 * (post * post) / cap;

    // Tight fit reward: strongly subtract when post_residual is small.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward when next item fits into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // Penalize leaving a residual that barely misses the next item.
            let miss = (nxt - post) / cap;
            score += 4.0 * miss;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many open bins could still absorb the item.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 10.0 + 20.0 * (1.0 - progress) + 3.0 * open_pressure;
        // But if no other bin fits (fitting_bins_count==1 refers to this new bin), soften.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
    }

    // Stream-progress coupling: as stream advances, favor tighter packing
    // (amplify waste penalty, reduce tolerance for loose fits).
    score += 6.0 * progress * (post / cap);

    // Mean residual interaction: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual = tighter bin = better).
    let bin_res = bin_residual as f64;
    score += 0.05 * (bin_res - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common capacity fractions
    let pr = post_residual;
    let res_mod = (pr % 10) as f64;
    let res_div = (pr / 10) as f64;

    // Reward post-residuals that are "clean" (small residue mod 10, or exact zero)
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        score += res_mod * 1.5; // penalize ragged remainders
        // Reward post_residuals that leave useful harmonic slots (>= next item size)
        if next_item_size > 0 && pr >= next_item_size {
            score -= 12.0 + (pr - next_item_size) as f64 * 0.3;
        } else if next_item_size > 0 {
            score += (next_item_size - pr) as f64 * 0.8; // dead space for lookahead
        }
        // Integer-division thresholds: post_residual in [20,30) is a classic dead zone
        let slot = pr / 10;
        if slot == 2 {
            score += 8.0;
        } else if slot == 3 {
            score -= 4.0;
        } else if slot == 0 {
            score += 25.0; // tiny unusable sliver
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / cap).min(1.0);
        score = cap - post_residual as f64; // baseline ~ item_size
        score -= 15.0 * (1.0 - tightness); // prefer new bin for large items
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size <= pr.min(100) {
            score -= 5.0;
        }
        // Discourage opening new bins when open bins have plenty of slack
        if mean_residual > item_size as f64 + 15.0 {
            score += 18.0;
        }
    }

    // Fill factor: reward tighter fills as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - post_residual as f64 / cap) * 10.0 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the mean (balance load)
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 6.0;

    // Penalize many open bins slightly to encourage consolidation
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is strongly rewarded
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward tight fits (small but usable residual)
    score -= (bin_residual - post_residual) as f64 * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Penalize opening a new bin when open bins pressure is low
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
        // But if item is large, a fresh bin is fine
        score -= item_size as f64 * 0.2;
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Mild pressure from mean residual: prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream consolidation: prefer reusing existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.4 * slack;
    } else if next_item_size > 0 {
        // Penalize leaving a gap that the next item cannot use (dead space).
        score += 0.6 * (next_item_size as f64 - post_residual as f64);
    }

    // Compare post_residual relative to mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer opening a new bin only if fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If the next item is large, a fresh bin is more attractive.
        score -= 0.15 * next_item_size as f64;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (next_item_size as f64 - post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward reserving room for the lookahead item.
        score -= 3.0 * (post_residual as f64 - next_item_size as f64).min(10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual);
        score += 20.0 - 10.0 * fit_quality - pressure.min(5.0);
        // Early in stream, opening bins is cheaper; late, prefer filling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates from mean (consolidation of similar gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Slight preference for bins with larger residual when item is large.
    score -= 0.05 * (item_size as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let shape = 1.0 + 0.9 * progress - 1.2 * progress * progress;
    score *= shape;

    // Reward tight fits more strongly as stream progresses.
    score -= 14.0 * norm_item * norm_pr * (1.0 - norm_pr) * (1.0 + 2.0 * progress);

    // Penalize dead space quadratically, amplified late in the stream.
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Prefer bins whose residual is near the mean residual (balance load).
    let dev = (pr - mean_residual) / cap;
    score -= 6.0 * dev * dev * (1.0 - progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64 / cap;
        let gap = norm_pr - ns;
        if gap >= 0.0 {
            score -= 10.0 * ns * (1.0 - gap) * (0.6 + 0.8 * progress);
        } else {
            score += 6.0 * gap.abs() * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize into capacity fractions.
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor(); // 8 harmonic classes: 0..7
    // Class-dependent shaping: small residuals (class 0-1) are near-perfect fits -> reward.
    score -= match class as i32 {
        0 => 25.0,
        1 => 18.0,
        2 => 10.0,
        3 => 4.0,
        4 => 0.0,
        5 => -3.0,
        6 => -5.0,
        _ => -6.0,
    };

    // Integer-division threshold: residual must be able to host plausible future items.
    if post_residual < 10 {
        score += 40.0; // dead space penalty
    }

    // Coupling with lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly next item nests
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 20.0 * tight;
        } else {
            // next item cannot fit here; mildly penalize large leftover
            score += (post_residual as f64 - mean_residual).abs() * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins are crowded
    // relative to the item (poor fits everywhere).
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // base cost of a fresh bin
        score = cap * 0.9;
        // discount the new bin when open bins have little room on average
        score -= (1.0 - crowding) * 120.0 / pressure;
        // if next item is large, a fresh bin is attractive
        if next_item_size >= 50 {
            score -= 30.0;
        }
    }

    // Stream progression: late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // Harmonic modulo bonus on exact divisions of capacity by residual classes.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;

    // Pressure from number of open bins: prefer filling existing bins
    // when many are open; allow new bins when few are open.
    score += (open_bins_count as f64) * 2.0;

    // Prefer bins with residual below mean residual (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item nearly fits but would be blocked, slight penalty.
    if next_item_size > post_residual && next_item_size - post_residual <= 10 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: neutral baseline, adjusted by stream progression
    // and open-bin count so late in the stream we avoid proliferating bins.
    if bin_residual == bin_capacity {
        score = 30.0 + (open_bins_count as f64) * 3.0
            + (step_index as f64 / total_items.max(1) as f64) * 20.0;
        // But if no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual matches next item size exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect chain: post_residual == next_item_size -> strong reward.
        if diff < 0.5 {
            score -= 40.0;
        } else {
            // Penalize mismatch, scaled by how far off we are.
            score += 0.25 * diff;
        }
        // If next item fits into post_residual, mild reward (keeps chains going).
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Compare post_residual against mean residual: leaving near-average residual
    // keeps flexibility; extreme small residuals are dead space.
    let pr = post_residual as f64;
    let mean_gap = (pr - mean_residual).abs();
    score += 0.10 * mean_gap;

    // Penalize very small unusable residuals (< typical min item size).
    if pr < 10.0 && pr > 0.0 {
        score += 30.0 * (10.0 - pr);
    }

    // Last-chance bin: if this is the only bin that fits, reward using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: reserve it. Only prefer a new bin when the item fits
    // perfectly in it (item_size == capacity residual) or current fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously.
        score += 15.0;
        if item_size == bin_capacity {
            score -= 100.0; // perfect full packing
        }
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 20.0;
        }
    }

    // Slight preference to fill older/denser bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0; // near-perfect fit leaves (almost) dead space anyway
    }

    // Penalize bins whose residual is much larger than the item (wasteful).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.3 * waste;

    // Lookahead: if next item could exactly use this bin's post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // post_residual too small for next item: penalize proportionally
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or many bins are already open (fragmentation risk).
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bin is less bad.
        score -= 0.2 * mean_residual;
        // Early in stream, allow more bins; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Slight preference to fill bins with larger residuals to balance them.
    score -= 0.05 * bin_residual as f64;

    // Global balance: prefer bins below mean residual (keep residuals even).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let pr2 = pr_norm * pr_norm;
    let pr3 = pr2 * pr_norm;

    // Tight fits are rewarded increasingly over time (waste penalty shrinks for small residuals)
    score -= 12.0 * (1.0 - pr3) * (0.5 + 0.5 * progress);

    // Penalize large dead space super-linearly, more so late in the stream
    score += 8.0 * pr2 * (1.0 + progress);

    // Interaction: cubic residual vs progress — early stream tolerates big residuals, late does not
    score += 6.0 * pr3 * (1.0 - progress) * -1.0;

    // Lookahead coupling: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack * slack) * (0.3 + 0.7 * progress);
        } else {
            score += 5.0 * ((nxt - pr) / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mean residual pressure: prefer bins below mean residual (fill fuller bins first)
    score += 3.0 * ((pr - mean_residual) / cap).tanh();

    // New-bin candidate: penalize opening a new bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap);
        score += 20.0 * (0.5 + 0.5 * progress) * (0.5 + 0.5 * avg_tightness);
        if next_item_size > 0 {
            score -= (next_item_size as f64 / cap) * 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals in "useful" classes
    // (multiples of common small sizes / capacity fractions).
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit is always best
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr >= 10 && pr <= 20 {
        -8.0 // small residual can absorb small items
    } else if pr < 10 {
        10.0 // dead space penalty
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division threshold on post_residual relative to next item:
    // if the next item fits the post residual, strongly reward this bin.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 25.0;
        // extra reward if next item exactly consumes post residual (modular match)
        if pr % next_item_size == 0 || next_item_size % 10 == 0 && pr % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here afterwards; mild penalty scaled by gap
        score += ((next_item_size - pr) as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / cap);
        score += 45.0 - crowded * 5.0;
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer bins with residual close to item (tight fit), scaled by mean residual.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= tightness * 8.0;
    score += (mean_residual - post_residual as f64) * 0.05;

    // Modulo coupling: reward residuals that pair with typical item classes (10..80)
    if pr >= 10 && pr <= 80 && (pr % 20 == 0 || pr % 25 == 0) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual < 10 {
        score += 60.0; // tiny dead space, nearly wasted
    } else if post_residual <= 15 {
        score += 25.0;
    } else if post_residual <= 25 {
        score += 8.0;
    }

    // Reward very tight fits (item consumes almost all residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 40.0;
    } else if fill_ratio > 0.7 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a marginal gain.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, consolidate rather than spread.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Lookahead: if next item fits into post_residual, reward leaving it here.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If post_residual is too small for next item but bin_residual could have,
    // slight penalty for near-miss dead space.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps a balanced portfolio of bins for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: neutral-to-slightly-high baseline so that
    // only genuinely poor fits in existing bins trigger a new bin.
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * progress; // cheaper to open new bin late in stream
        if fitting_bins_count <= 1 {
            score -= 35.0; // no real alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward for perfect 2-step chain (post_residual == next_item_size)
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            // Extra bonus for exact match
            if slack == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot chain here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // Last item: prefer tightest fit only
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Penalize leaving dead space that is too small to be useful (below min item size)
    if post_residual < 1 {
        score -= 5.0; // perfect fill, excellent
    } else if post_residual <= 10 {
        score -= 8.0; // near-perfect fill, hard to reuse -> good now
    } else if post_residual < 20 {
        // awkward dead zone: small but reusable-ish, slight penalty
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when the fit into
    // existing bins would create large dead space. Give the empty bin a mild
    // handicap so it only wins on genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item is large relative to capacity, opening fresh is natural
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Slight pressure against bin sprawl late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (open_bins_count as f64).sqrt().ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose leftover is minimal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        } else {
            // Reward residuals that can still host the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 0.15 * (1.0 - slack / (bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (a fresh bin gives a clean fit) or when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / (bin_capacity as f64)).min(1.0)
        } else {
            0.0
        };
        // Large items benefit from a fresh bin; fragmented bins push toward opening new ones.
        score -= 6.0 * size_ratio * size_ratio + 4.0 * fragmentation;
        // Early in the stream, opening bins is cheap; later, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 * progress;
        score += 0.5 * open_bins_count as f64;
    } else {
        // Mild preference for filling bins that are already mostly full.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 3.0 * fill;
    }

    // Exact-fit celebration.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Small unusable slivers are still better than medium dead zones.
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (pr / cap);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 10.0 + 0.5 * (nxt - pr);
        } else {
            // Reward leaving exactly usable room for the next item.
            let usable = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - usable) * (1.0 - usable);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: open new bins sparingly, more acceptable
    // early in the stream or when mean residual across open bins is large.
    if bin_residual == bin_capacity {
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        score += 30.0 * (1.0 - progress) - 20.0 * openness + 0.5 * open_bins_count as f64;
    }

    // Mild stream-progress coupling: later in the stream, prefer tighter packing.
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "friendly"
    // (small, or exact multiples of common item sizes 10..80 via gcd classes).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Class by post_residual / capacity fraction thirds
        let frac = pr as f64 / cap;
        if frac < 0.1 {
            score -= 25.0; // tiny dead space is fine
        } else if frac < 0.3 {
            score += 8.0;
        } else if frac < 0.5 {
            score += 15.0;
        } else {
            score += 25.0; // large residual but item didn't fill: wasteful-ish
        }
        // Modulo-class reward: residuals divisible by small item sizes are reusable
        let m = pr % 10;
        if m == 0 {
            score -= 12.0;
        } else if m <= 2 {
            score -= 5.0;
        } else {
            score += m as f64 * 0.8;
        }
    }

    // Lookahead: strongly favor bins where the next item also fits the post-residual
    if next_item_size > 0 && next_item_size <= pr {
        score -= 18.0 + (pr - next_item_size) as f64 * 0.15;
    } else if next_item_size > pr && pr > 0 {
        score += 6.0; // next item won't fit here; slight penalty unless residual tiny
    }
    // Perfect two-item closure: item + next exactly fills bin
    if next_item_size > 0 && next_item_size == pr {
        score -= 30.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: keep fresh bins attractive only when current
    // placements would leave awkward mid-range residuals.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.05 - (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
        if item_size >= 50 {
            score -= 10.0; // big items fine in fresh bins
        }
    }

    // Mild stream-progress adaptation: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0 - mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small nonzero gaps are unusable for typical items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 60.0 } else if post_residual < 20 { 30.0 } else { 0.0 };
        score += dead * (post_residual as f64 / 10.0).sqrt();
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Tightness reward: fraction of bin used by this item.
    let tight = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * tight * tight;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Pressure from too many open bins: prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).powf(1.3) * (0.5 + 0.5 * progress);

    // If the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space relative to lookahead: gap too small for next item.
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    }

    // New-bin candidate: attractive only when no open bin fits well or bins are scarce.
    if bin_residual == bin_capacity {
        let good_fit_exists = mean_residual >= item_size as f64 + 10.0;
        if good_fit_exists && fitting_bins_count > 0 {
            score += 150.0; // discourage opening new bin when decent fits exist
        } else {
            score -= 30.0; // encourage new bin for large items with poor fits
        }
        // Late in stream, opening new bins is cheap; early, prefer consolidation.
        score += 80.0 * (1.0 - progress);
    }

    // Slight preference toward bins whose residual is close to mean (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled.
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: strongly reward exact/near match of
    // post_residual to the next item size (perfect chain).
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - match_gap / bin_capacity as f64).max(0.0);
        // Perfect chain: next item exactly fills bin afterwards.
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 20.0;
        }
        // Penalize leaving a residual that the next item cannot use at all.
        if next_item_size > post_residual {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: any residual is dead space; minimize it hard.
        score += 20.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer
    // resource; filling them tightly is good.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else (large post_residual elsewhere)
    // or there are no open bins yet.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            // New empty bin leaves residual = C - item; judge it as such but
            // add a mild opening penalty so tight existing fits win.
            score += 12.0;
            // If item is large, fresh bin wastes less relative space.
            score -= 0.1 * item_size as f64;
            // If next item is large too, a fresh bin enables the chain.
            if next_item_size > 0 && next_item_size >= item_size {
                score -= 8.0;
            }
        }
    }

    // Mild pressure against bin sprawl late in the stream.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use:
    // dead space is worst when post_residual is small but nonzero.
    if post_residual > 0 {
        let dead = (post_residual as f64) / cap;
        score += 25.0 * dead * (1.0 - dead) * (1.0 - dead);
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let fill = (next_item_size as f64) / (post_residual as f64);
            score -= 40.0 * fill;
        } else {
            // Next item won't fit here; mild penalty proportional to leftover gap.
            score += 8.0 * ((next_item_size as f64) - (post_residual as f64)) / cap;
        }
    } else {
        // Last item: prefer zero leftover, otherwise new bin is fine.
        score += if post_residual > 0 { 10.0 } else { -20.0 };
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has neutral residual; make it
    // attractive only when open bins are crowded or the fit here is poor.
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / cap).max(0.0);
        let poor_fit = (post_residual as f64) / cap; // = 1 - item/cap for empty bin
        score += 35.0 * (1.0 - crowding);           // cheaper to open when bins are full
        score -= 30.0 * poor_fit * poor_fit;        // large items justify a fresh bin
        score += 10.0 * (open_bins_count as f64).sqrt().min(5.0); // mild consolidation bias
    } else {
        // Prefer bins whose residual is close to the item (minimize fragmentation).
        let fit_ratio = (item_size as f64) / (bin_residual as f64);
        score -= 20.0 * fit_ratio * fit_ratio;

        // Slight preference for bins below the mean residual (drain small leftovers).
        score += 5.0 * ((bin_residual as f64) - mean_residual) / cap;
    }

    // Time horizon: as the stream nears its end, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: square of post residual penalizes wasted space super-linearly.
    score += 0.35 * (post / cap) * (post / cap) * cap;

    // Smooth non-linear coupling of fit quality with stream progress:
    // later in the stream, waste matters more, so amplify post residual.
    score += 2.0 * post * progress * (1.0 - progress + 0.25);

    // Reward bins that leave room for the next item (lookahead synergy).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let slack = post - next_item_size as f64;
        score -= 3.0 * (1.0 - slack / cap) * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty for blocking lookahead.
        score += 1.5 * (next_item_size as f64 / cap) * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    } else {
        // More competing bins => slight penalty to prefer the best fit among many.
        score += 0.4 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is below mean (consolidate waste).
    score -= 1.2 * ((mean_residual - post) / cap).tanh();

    // Slight preference for keeping fewer open bins early; later allow spreading.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline, penalized by stream progress
    // (late in stream, opening bins is cheap; early it wastes capacity).
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.25 * progress) + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: reward small, "dead" residuals that are hard to reuse.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class the post-residual into integer-division buckets (harmonic classes).
    let class = post_residual / 10; // 0..10 buckets
    match class {
        0 => score -= 25.0,           // near-perfect fit, tiny dead space
        1 => score -= 18.0,
        2 => score -= 12.0,
        3 => score -= 6.0,
        4 => score -= 2.0,
        5 => score += 4.0,            // half-empty: reusable, mildly penalize
        6 => score += 8.0,
        7 => score += 12.0,
        8 => score += 16.0,
        9 => score += 20.0,
        _ => score += 30.0,           // nearly untouched bin: wasteful placement
    }

    // Reward tight fits strongly (residual exactly filling a harmonic slot).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item cannot use this residual: penalize leaving medium residual
            score += 8.0 * frac;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement is bad.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost; make it unattractive if decent fits exist.
        score += 40.0;
        // But attractive late in stream or when many bins are already open and fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * progress;
        if open_bins_count > 3 && mean_residual < 30.0 {
            score -= 30.0; // existing bins are fragmented; fresh bin helps
        }
    } else {
        // Prefer bins whose residual is closest below the item (best-fit flavor).
        let waste = (bin_residual - item_size) as f64;
        score += 0.15 * waste;
    }

    // Mild normalization by mean residual state.
    score -= 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals that can never host typical items are wasted.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 25 {
            score += 25.0; // hard-to-fill gap
        } else if post_residual < 50 {
            score += 8.0;
        }
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Reward bins whose residual matches the item tightly (low fragmentation).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a bin when a decent fit exists,
    // but allow it if all fits are terrible (large dead space everywhere).
    if bin_residual == bin_capacity {
        let base_open_penalty = 30.0 + 5.0 * open_bins_count as f64;
        // Lookahead: if next item is large, a fresh bin is valuable.
        let lookahead_bonus = if next_item_size > 50 { 45.0 } else if next_item_size > 0 { 10.0 } else { 0.0 };
        score += base_open_penalty - lookahead_bonus;
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    } else {
        // Open-bin pressure: with many open bins, prefer consolidating into fewer.
        score += 2.0 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is far below the mean (already fragmented) to absorb items,
    // keeping high-residual bins flexible for future items.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead synergy: reward leaving a gap that fits the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_match = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap_match / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small waste
    if next_item_size > 0 && next_item_size <= post_residual {
