        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit this residual: penalize leaving awkward gap
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0 + 0.2 * (next_item_size - post_residual) as f64;
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Penalize deviation from mean residual (prefer balanced bins)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening new bins unless current fits are poor
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item (>= 10... but sizes unknown 1..100) can use:
    // small post_residual is fine; large post_residual wastes the bin.
    if post_residual > 0 {
        score += (post_residual as f64) * (post_residual as f64) * 0.02;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits in post_residual, big reward for this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward if next item nearly fills the remaining space too.
        let chain_tight = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - chain_tight / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't chain here: mild penalty scaled by how much we'd strand.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin generally, more when many bins fit.
    if bin_residual == bin_capacity {
        let base_penalty = 15.0 + 3.0 * (fitting_bins_count as f64);
        // Late in the stream, prefer reusing existing bins even more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += base_penalty * (1.0 + progress);
        // But if the item is huge relative to mean residual and no tight fit exists,
        // opening a fresh bin is less bad.
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
        // Lookahead synergy: a fresh bin can host item + next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Mild preference for bins with below-mean residual (consolidate emptier bins? no:
    // prefer filling bins that are already low to close them out).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    // Prefer packing into bins when many bins are open (reduce bin count pressure).
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize leftover space, quadratically (dead space is doubly bad).
    let mut score = pr * (1.0 + norm_pr);

    // Non-linear coupling: leftover penalty intensifies with stream progress
    // (later in the stream, compacting matters more).
    let progress_coupling = 0.5 + 2.0 * progress * progress;
    score += progress_coupling * pr * norm_pr;

    // Reward tight fits: small post_residual relative to item size.
    score -= (item_size as f64) * (1.0 - norm_pr).max(0.0) * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly into the resulting residual,
    // strongly reward; if the residual is too small for the next item, penalize.
    if next_item_size > 0 {
        let diff = pr - norm_next * cap;
        if diff.abs() < 0.5 {
            score -= 30.0 * (1.0 + progress);
        } else if diff < 0.0 {
            score += 3.0 * (-diff) * (0.3 + 0.7 * progress);
        } else {
            // residual can hold next item with slack: mild penalty on excess
            score += 0.05 * diff;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin, more so when good
    // alternatives exist and late in the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if mean residual of open bins is very low, opening is less bad.
        score -= 10.0 * (mean_residual / cap).min(1.0);
    }

    // Mild preference for bins whose residual is close to mean (balance).
    let dev = (pr as f64 - mean_residual).abs();
    score += 0.1 * dev * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "reusable"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // reward residuals that are multiples of small common sizes (10,20,25,50)
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 5.0; }
        // penalize awkward dead space (prime-ish small residuals)
        if pr < 10 { score += 12.0 * (10 - pr) as f64; }
    } else {
        // perfect fill is best
        score -= 40.0;
    }

    // Integer-division threshold classes on post_residual
    let class = pr / 10; // 0..10 harmonic class
    score -= (class as f64) * 2.0; // larger residual classes slightly favored (more usable)

    // Lookahead coupling: if the next item exactly fits the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 10.0 - (slack as f64).min(10.0);
            if slack % 10 == 0 { score -= 3.0; }
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fits are bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 18.0;
        // but if mean residual across open bins is small (poor fits everywhere),
        // opening a new bin becomes attractive
        score -= (mean_residual * 0.25).min(20.0);
        // large items prefer fresh bins
        if item_size > bin_capacity / 2 { score -= 8.0; }
    } else {
        // prefer tighter existing fits (small pre-residual gap)
        score += (bin_residual - item_size) as f64 * 0.05;
    }

    // Progress coupling: late in the stream, consolidation matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64) * 0.1;

    // Many open bins: favor reusing existing ones to avoid fragmentation
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
