        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        let pressure = if fitting_bins_count == 0 { 40.0 } else { 12.0 };
        score = 100.0 + mean_fit_gap * 0.4 - pressure
            + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // fresh bin can host next item too
        }
    }

    // Mild preference to fill existing bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 8.0 * progress;
    }

    // Prefer bins with residual below mean (consolidate waste into few bins).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear coupling of post-residual with stream progress.
    // Early on (progress ~ 0): mild penalty on dead space, weight grows with progress.
    let dead_weight = 0.5 + 2.5 * progress;
    let mut score = x + dead_weight * x * x * cap * 0.01;

    // Cubic interaction: reward tight fits more strongly as stream progresses.
    score -= (1.0 - x).powi(3) * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= fits_next * nx * (1.0 - gap) * (1.0 + progress);
        score += (1.0 - fits_next) * nx * 0.5;
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    let mean_x = mean_residual / cap;
    score += 0.3 * (x - mean_x).abs() * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 1.5 + 3.0 * (1.0 - progress) - 2.0 * open_pressure * mean_x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "usable" class (large enough for typical future items) are rewarded.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold classes
    match class {
        0 => score += 40.0,          // dead space (<10): heavily penalize
        1 => score -= 2.0,           // 10..19: usable small slot
        2 => score -= 6.0,           // 20..29
        3 => score -= 9.0,           // 30..39
        4 => score -= 11.0,          // 40..49
        5 => score -= 12.0,          // 50..59
        6 => score -= 12.0,          // 60..69
        7 => score -= 11.0,          // 70..79
        _ => score -= 8.0,           // 80+: nearly empty bin
    }

    // Exact-fit / tight-fit bonus via modulo arithmetic.
    if pr == 0 {
        score -= 60.0;
    } else if pr % 10 == 0 {
        score -= 5.0; // round leftover: harmonically reusable
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or snugly; penalize wasted lookahead compatibility.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (next_item_size as u32) == pr {
            score -= 30.0; // perfect chaining
        } else if next_item_size <= pr {
            let waste = pr - next_item_size;
            score -= 12.0 - (waste as f64).min(12.0) * 0.4;
        } else {
            // next item cannot fit here: mild penalty proportional to gap
            score += ((next_item_size - pr) as f64) * 0.15;
        }
        // If next item is large, prefer conserving big residuals
        if n > 0.5 * cap && pr < n as u32 {
            score += 3.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is justified only if this
    // item is large and no tight fits exist elsewhere.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // Base cost of opening a new bin; decreases late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 20.0 * (1.0 - progress);
        if item_size > bin_capacity / 2 {
            score -= 10.0; // large items tolerate fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 15.0; // could have chained in an existing bin
        }
        // Many open bins with slack: discourage yet another bin.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 12.0;
        }
    } else {
        // Prefer filling bins that deviate below the mean residual (tighter bins first).
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
        // Slight preference for fewer open bins when fit is good.
        if post_residual < 20 {
            score -= open_bins_count as f64 * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 4.0 * post_residual as f64; // gap 1 -> +56, gap 9 -> +24
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Moderate fill reward: tighter fit preferred
    score -= 0.6 * (item_size as f64 / bin_capacity as f64) * 20.0;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // bonus when it nearly fills the bin completely afterwards
        let second_gap = post_residual - next_item_size;
        if second_gap < 5 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // leftover gap too small for next item -> extra penalty if tiny
        if post_residual < 15 {
            score += 12.0;
        }
    }

    // Open-bin pressure: discourage spreading when many bins are open,
    // encourage using existing bins instead of opening new ones.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin fit is bad
    if bin_residual == bin_capacity {
        // neutral base for a fresh bin
        score = 50.0 + 0.35 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // fresh bin has room for lookahead too
            score -= 8.0;
        }
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            // an open bin already has enough space on average; new bin is wasteful
            score += 20.0;
        }
        if fitting_bins_count == 1 {
            // the only fitting open bin is a last chance; opening new bin is worse
            score += 30.0;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize placements far below mean residual usage (imbalance)
    if post_residual as f64 > mean_residual + 30.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item exactly fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 200.0 * tight;
        } else {
            // next item won't fit: penalize large dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual to mean residual: prefer bins whose remaining
    // space stays close to the open-bin average (balanced residual profile)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin
    // would leave unusable space
    if bin_residual == bin_capacity {
        score += 50.0 + 0.4 * mean_residual;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 100.0; // pair of identical items goes to fresh bin
        }
    }

    // Late in stream: consolidate aggressively into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but only mildly beyond linear.
    score += 0.35 * ((post_residual as f64) * (post_residual as f64)) / (bin_capacity as f64);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize dead space that can never fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit reward, stronger for larger chained items.
            score -= 8.0 + 0.15 * (next_item_size as f64);
        } else {
            // Post residual too small for lookahead item: penalize wasted space.
            score += 4.0 + 0.10 * (post_residual as f64);
        }
    } else {
        // Last item: prefer finishing tight.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large item relative to residuals) or few bins fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a fresh bin: its post_residual is large, add explicit opening cost.
        score += 30.0;
        // Relax cost when the item is large (hard to fit) or few bins can host it.
        let tightness = (item_size as f64) / (bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    } else {
        // Prefer bins whose residual is close to the item (best-fit bias).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.05 * gap;
    }

    // Global state coupling: many open bins with large mean residual -> encourage filling them.
    if !is_new_bin {
        let fill_urgency = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln1p();
        score -= 2.0 * fill_urgency;
    }

    // Mild time-dependent exploration: early stream, be slightly greedy on tight fits;
    // late stream, strongly avoid new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.10 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic in post_residual, growing with stream progress
    score += (post / cap) * (post / cap) * cap * (0.5 + 1.5 * progress);

    // Reward tight fits (small post_residual) strongly
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * 20.0;

    // Lookahead: penalize if post_residual is large but cannot fit next item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        // Large leftover that is unusable is bad; small-but-unusable leftover is mild
        let gap = (nxt - post).max(0.0) / cap;
        score += gap * gap * cap * (0.3 + 0.7 * (1.0 - fits_next));
        // Reward when post_residual still accommodates next item
        score -= fits_next * 5.0;
    }

    // Last-chance bin bonus: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Mild competition penalty scaled by number of alternatives
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: penalize opening a bin unless current residuals are poor
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        // Compare mean residual quality: if open bins are fragmented, opening is fine
        let fragmentation = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 25.0 - 20.0 * fragmentation * fragmentation;
        // Late in stream, prefer closing out existing bins
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference to fill bins with low residual relative to mean
    score += 0.1 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are multiples of common item sizes (or land in friendly
    // integer-division classes) are more likely to be filled later.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit: ideal closure
    } else {
        // Integer-division class: r / 10 quantizes the dead space.
        let class = r / 10;
        // Small classes (1-3) are dead space; larger classes are more reusable.
        score += match class {
            0 => 8.0,
            1 => 6.0,
            2 => 4.0,
            3 => 2.0,
            _ => 0.0,
        };
        // Modulo harmony: residuals divisible by 10, 20, or 25 pair well with
        // typical item sizes drawn from wide ranges.
        let harmony = if r % 10 == 0 {
            3.0
        } else if r % 20 == 0 || r % 25 == 0 {
            2.0
        } else if r % 5 == 0 {
            1.0
        } else {
            0.0
        };
        score -= harmony;

        // If the next item fits exactly into the post residual, big reward.
        if next_item_size > 0 {
            if next_item_size == r {
                score -= 25.0;
            } else if next_item_size < r {
                let slack = r - next_item_size;
                // reward tight follow-up fits, penalize sloppy ones
                score -= 10.0 * (1.0 - slack as f64 / r as f64);
                // harmonic check on the resulting second-order residual
                if slack % 10 == 0 {
                    score -= 4.0;
                }
            } else {
                // next item cannot use this residual: mild penalty scaled by
                // how much dead space is stranded
                score += (r as f64) * 0.05;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing bins are crowded (mean residual low) or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // penalize new bins when open bins still have room
        score += 30.0 + 20.0 * crowding - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 40.0; // nothing else available
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 12.0; // big next item: fresh bin useful
        }
    }

    // Slight preference for bins tighter than the average residual.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 {
        // Residual that can still host a typical item is mildly good; scale by usefulness.
        score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Tightness coupling: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward; penalize if it wastes space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over opening new.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; escape hatch only if current bins are bad.
        score += 30.0 + pressure;
        // Allow opening a new bin when all open residuals are small/unusable.
        if mean_residual < 10.0 {
            score -= 45.0;
        }
    } else {
        // Mild penalty for spreading across many bins.
        score += pressure * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Next item fits in the post residual -> reward proportionally.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover space -> penalize dead space.
        score += 25.0;
    }

    // Penalize small nonzero post_residual (unusable sliver) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Deviation from mean residual: prefer bins whose post residual stays near mean
    // (balanced packing) unless it's a tight fit.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it unattractive unless no decent open bin exists.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Early in stream, opening bins is cheaper; late in stream, prefer filling.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 80.0 * (1.0 - progress);
    }

    // Reward tight fits generally.
    score -= 0.3 * item_size as f64;

    // Many open bins: encourage closing them out (filling existing bins).
    if open_bins_count > 4 {
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that likely can't be used.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // small unusable slivers are pure waste
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * (next_item_size as f64);
        } else if post_residual > 0 {
            score += 5.0; // blocks the next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Prefer bins that deviate favorably from the mean residual (filler bins).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 3.0 * dev;
    }

    // Mild penalty for proliferating open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_norm = item_size as f64 / cap;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let smooth_progress = progress * progress * (3.0 - 2.0 * progress);

    // Base: prefer bins with small post-residual (tight packing).
    let mut score = post;

    // Non-linear tightness reward: reward small post_residual quadratically.
    let post_norm = post / cap;
    score += 40.0 * post_norm * post_norm * cap;

    // Penalize near-full but wasteful fits (post residual in awkward small band),
    // coupled smoothly with stream progress: late in stream, dead space hurts more.
    let awkward = {
        let x = post_norm;
        let center = 0.2;
        -((x - center) * (x - center)) / (2.0 * 0.08 * 0.08)
    };
    score += 12.0 * awkward.exp() * (0.5 + smooth_progress);

    // Reward filling bins that are already quite full (small residual before placement).
    let res_norm = bin_residual as f64 / cap;
    score -= 25.0 * (1.0 - res_norm) * (1.0 - res_norm) * fit_norm * cap;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * smooth_progress;
    }

    // Lookahead: penalize leaving residual that next item almost fits but not quite;
    // reward residual that next item fits snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            let snug = 1.0 - (gap / cap).abs().min(1.0);
            score -= 15.0 * snug * snug;
        } else {
            score += 8.0 * (gap / cap).abs();
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (consolidate emptiness).
    let dev = (mean_residual - bin_residual as f64) / cap;
    score -= 10.0 * dev * dev * dev.signum();

    // New-bin candidate handling: brand-new empty bin should only win when open bins
    // offer poor fits. Penalize opening new bins, more so late in the stream.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 55.0 + 30.0 * smooth_progress + 5.0 * open_pressure;
        // But if item is large and mean residual is small, opening is less bad.
        score -= 20.0 * fit_norm * (1.0 - (mean_residual / cap).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo buckets on capacity fractions
    let pr = post_residual;
    let class = pr / (bin_capacity / 8).max(1); // 8 harmonic classes
    score -= (class as f64) * 3.0;

    // Perfect fit bonus
    if pr == 0 {
        score -= 1000.0;
    }
    // Tiny dead space: strongly reward near-perfect fills
    if pr > 0 && pr <= 5 {
        score -= 150.0;
    }
    // Penalize residuals that are unusable for typical small items
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Next-item lookahead: reward if next item fits exactly / well in post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= 40.0 + (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: keep it competitive only when fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin, reduced when many items remain or few open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap_f * (1.0 - 0.3 * progress) + 250.0 / (open_bins_count as f64 + 1.0);
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
    } else {
        // Prefer fuller bins: tie-break with tightness ratio
        let tightness = 1.0 - (bin_residual as f64) / cap_f;
        score -= tightness * 25.0;
        // Spread penalty: avoid bins far from mean residual (harmonic balancing)
        score += ((bin_residual as f64) - mean_residual).abs() * 0.2;
    }

    // Modulo-based dead-space heuristic on post_residual classes
    let m = pr % 10;
    if m == 0 && pr > 0 {
        score -= 20.0; // round residuals pair well with decade-sized items
    } else if m >= 8 {
        score += 10.0; // awkward residual slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (small gaps that few future items can fill) are heavily penalized.
    let dead_low = 1.0f64;
    let dead_high = 12.0f64;
    let pr = post_residual as f64;
    if pr > dead_low && pr < dead_high {
        let depth = (dead_high - pr) / (dead_high - dead_low);
        score += 40.0 * depth * depth; // quadratic penalty inside dead zone
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect-fit bonus when residual equals item size exactly.
    if bin_residual == item_size {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins,
    // but relax pressure late in the stream when consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (8.0 - 4.0 * progress);
    score += pressure;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if the item fits badly everywhere else.
    // An empty bin has zero dead-space risk, so penalize it mildly by default,
    // but less when the current bin would leave a large awkward gap.
    if bin_residual == bin_capacity {
        let awkward = (post_residual as f64 / bin_capacity as f64) * 30.0;
        // empty bin score = capacity residual + small constant vs filled-bin score;
        // favor empty bin when placing here wastes more than ~half the bin.
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            score -= 45.0 + awkward;
        } else {
            score += 25.0;
        }
    }

    // Lookahead: if the next item fits snugly into this bin's post-residual,
    // reward the placement (enables good 2-item chains).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() <= 3.0 {
            score -= 20.0;
        } else if nxt > pr {
            score += 6.0; // next item won't fit here; slight penalty for hogging space
        }
    }

    // Mean-residual coupling: when open bins are already loose (high mean residual),
    // avoid adding to the looseness.
    score += 0.15 * (pr - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual is good
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasted residual relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Compare post_residual against mean residual: prefer leaving typical-sized space
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        let base = 25.0;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() * 3.0 };
        let lookahead_penalty = if next_item_size > 0 && item_size + next_item_size <= bin_capacity { 0.0 } else { 8.0 };
        score += base + pressure + lookahead_penalty;
    }

    // Mild bonus for filling bins when many are open
    score -= 0.02 * (open_bins_count as f64) * (item_size as f64 / bin_capacity as f64);

    // Slight tightening over the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * tightness * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), especially perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 12.0 * tightness * tightness;
    }

    // Penalize dead space that no plausible future item can use.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 5.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 10.0; // sliver waste
    }

    // Lookahead coupling: if next item fits the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after = post_residual - next_item_size;
            score -= 18.0 * (1.0 - slack_after as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.2 * item_size as f64;
    }

    // Time horizon: early in the stream, prefer keeping bins flexible
    // (penalize low residual); late, prefer consolidating (reward tight fills).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let horizon = (1.0 - progress).clamp(0.0, 1.0);
    score += 6.0 * horizon * (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> discourage
    // spreading; favor filling existing bins rather than opening new ones.
    if open_bins_count > 2 {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.05 * spread;
        score -= 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: empty bin should only win when the fit
    // elsewhere is poor. Penalize fresh bin by residual-waste baseline plus
    // pressure from number of fitting alternatives.
    if bin_residual == bin_capacity {
        let base = 0.55 * bin_capacity as f64;
        let alt_pressure = 8.0 * (fitting_bins_count.saturating_sub(1)) as f64;
        let time_pressure = 10.0 * progress;
        score += base + alt_pressure + time_pressure;
        // But if item is huge relative to capacity and no good fit exists,
        // relax slightly so new bin can win.
        if item_size as f64 > 0.7 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = pr * (1.0 + 0.35 * progress * x) + 12.0 * x * x * (1.0 - progress);

    // Penalize dead space that no plausible next item can use.
    let lookahead_fit = if next_item_size > 0 && next_item_size as f64 <= pr {
        -8.0 * (1.0 - pr / (next_item_size as f64 + 1.0))
    } else if next_item_size > 0 {
        (next_item_size as f64 - pr) * 0.15
    } else {
        0.0
    };

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -20.0 } else { 0.0 };

    // Mild pressure toward consolidation as many bins accumulate.
    let congestion = 0.05 * open_bins_count as f64 * x;

    // Deviation from mean residual: prefer balanced fills.
    let balance = (pr as f64 - mean_residual).abs() * 0.1;

    // Slight preference for tighter fits overall.
    let tightness = -item_size as f64 * 0.05;

    base + lookahead_fit + last_chance + congestion + balance + tightness
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral-ish baseline, only attractive when fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin mildly; reward it only if no bin fits well.
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced option
        }
        // If the next item is large, a fresh bin is valuable.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 25.0;
        }
        return score;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Harmonic class logic: partition post_residual into residue classes mod 10.
    // Small dead space that cannot host typical items is penalized.
    let pr = post_residual;
    let cls = pr % 10;
    match cls {
        0 => {
            // Round residual: highly reusable.
            score -= 20.0;
            if pr >= 40 && pr <= 70 {
                score -= 15.0; // sweet spot for mid-size items
            }
        }
        1 | 2 => {
            // Nearly round: still good.
            score -= 10.0;
        }
        8 | 9 => {
            // Just below a round number: worst dead space class.
            score += 18.0;
        }
        5 => {
            score -= 5.0; // half-class: moderately reusable
        }
        _ => {
            score += 4.0;
        }
    }

    // Integer-division thresholds on post_residual: unusable slivers.
    if pr > 0 && pr < 10 {
        score += 30.0; // tiny sliver = wasted space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap <= 5 {
            score -= 25.0;
        } else {
            // Prefer residual matching harmonic classes of next item.
            let ncls = next_item_size % 10;
            if (pr % 10) == ncls && pr >= next_item_size {
                score -= 8.0;
            }
        }
    } else if next_item_size > pr {
        // Next item cannot use this bin's remainder: mild penalty scaled by closeness.
        score += (next_item_size - pr) as f64 * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Tightness coupling: reward filling bins relative to mean residual.
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= tight * 30.0;

    // Stream progression: early on, keep bins balanced (avoid many tiny residuals);
    // late in stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - post_residual as f64) * (0.5 - 0.8 * progress);

    // Discourage spreading across many bins when residuals are large.
    if open_bins_count > 3 && pr > 50 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Penalize leaving gaps too small for the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * next_item_size as f64;
    }
    // Reward gaps that exactly or nearly fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.3 * (post_residual as f64 - next_item_size as f64).min(20.0);
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 55.0 - 0.4 * item_size as f64;
    }

    // Late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero or near-zero post residual is ideal.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // 2-step lookahead: strongly reward placements that leave room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0; // exact two-item chain completion
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward closeness of next item fit
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize dead space that is too small for any plausible item (min size 1..~10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual is already below mean
    // (tightening nearly-full bins), penalize dipping into roomy bins.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.3 * (mean_residual - residual_f);
    } else {
        score += 0.3 * (residual_f - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make empty bin attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 100.0;
        // cheaper to open a new bin late in the stream? No: opening is always costly,
        // but scale with how many bins already fit the item
        if fitting_bins_count > 0 {
            score += 30.0 * fitting_bins_count as f64;
        }
        // if next item is large and current item is small, new bin keeps room
        if next_item_size > 0 && next_item_size >= 60 && item_size <= 30 {
            score -= 40.0;
        }
        // early in stream, a fresh bin is relatively cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins (consolidation pressure).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: penalize leaving large gaps
            score += 0.15 * post_residual as f64;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.2 * (item_size as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins have poor residuals relative to the item.
    if bin_residual == bin_capacity {
        // Mild penalty so a reasonably tight existing fit beats a new bin.
        score += 30.0;
        // But if open bins are nearly full on average, a fresh bin is fine.
        score -= 0.4 * mean_residual;
        // Early in the stream, prefer consolidating into few bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If many bins are open, discourage opening yet another.
        score += 1.5 * open_bins_count as f64;
    }

    // Penalize creating dead space that no typical item (>=1) could use well:
    // residuals of exactly 0 are perfect; residuals just above the smallest
    // item size are fine; mid-size residuals are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    }

    // Slight penalty proportional to how much worse this bin's residual is
    // compared to the mean residual across open bins (prefer filling emptier
    // bins first to consolidate).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fits are rewarded non-linearly (quartic-ish decay of residual utility)
    let tightness = 1.0 - post / cap;
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize creating dead space that cannot hold plausible future items
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 25.0 * (1.0 - post / nxt.max(1.0)) * (0.5 + 0.5 * progress);
        } else {
            // reward leaving room for the lookahead item
            let slack = (post - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening bins unless current bin would be wasted
    if bin_residual == bin_capacity {
        score += 45.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild coupling with mean residual state
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: small residues are "dead space" classes.
    // Class 1: residue <= 10 is nearly unusable (min item is 1, but tiny gaps waste).
    let tiny = (post_residual <= 10) as f64;
    score += tiny * 60.0 * (1.0 - (post_residual as f64) / 10.0);

    // Class 2: residue in (10, 20] — awkward mid-range gap.
    if post_residual > 10 && post_residual <= 20 {
        score += 25.0;
    }

    // Reward residues that are multiples of common capacity fractions (harmonic classes).
    let r = post_residual;
    let harmonic_bonus = if r % 50 == 0 {
        40.0
    } else if r % 25 == 0 {
        30.0
    } else if r % 20 == 0 {
        20.0
    } else if r % 10 == 0 {
        10.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward, scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to the wasted potential.
            score += 15.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins can already fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // New bin competes: make it unattractive unless existing fits are terrible.
            score += 120.0 - 10.0 * (fitting_bins_count as f64).ln().max(0.0);
        } else {
            score -= 50.0; // no alternative: opening is fine
        }
    }

    // Mild pressure to consolidate: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight early-stream preference for keeping bins balanced/open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the smallest plausible item, here assumed ~10) are pure waste.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty on small-but-usable residuals: a residual of 1..=9
    // is dead; 10..=25 is nearly dead; smooth quadratic ramp.
    let pr = post_residual as f64;
    if pr < 25.0 {
        score += 0.08 * (25.0 - pr) * (25.0 - pr);
    }

    // Reward tight fits strongly (post_residual close to 0 but still "clean").
    if item_size as f64 >= 0.6 * bin_capacity as f64 {
        score -= 12.0;
    }

    // Open-bin pressure: penalize placements into bins when many bins are open,
    // encouraging consolidation into fewer bins unless the fit is excellent.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post_residual exactly-ish, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Perfect chaining: next item fills the bin completely.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for stranding space.
        score += 3.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Make it less attractive than a decent fit into an existing bin, but
    // attractive when all existing fits would create heavy dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Reduce the penalty when many bins are already open (consolidation
        // pressure is satisfied; a fresh bin may be preferable to a bad fit).
        if open_bins_count > 3 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already fragmented; prefer filling it (its residual is small).
    let bin_res = bin_residual as f64;
    if bin_res < mean_residual {
        score -= 0.15 * (mean_residual - bin_res);
    } else {
        score += 0.10 * (bin_res - mean_residual);
    }

    // Mild stream-progression term: early on, be slightly conservative about
    // opening bins; later, prioritize tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core).
    score = post_residual as f64;

    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // ---- Aggressive 2-step lookahead matching ----
    if next_item_size > 0 {
        // Perfect follow-up fit: this bin's leftover exactly hosts the next item.
        let gap = (post - nxt).abs();
        if gap == 0.0 {
            score -= 60.0; // strong reward for exact 2-chain
        } else {
            // Penalize mismatch scaled by how badly next item fails to fit.
            score += gap * 0.6;
            if nxt > post {
                // Next item won't fit here at all: leftover is likely dead space.
                score += (nxt - post) * 0.35;
            }
        }
        // Reward when post_residual is small relative to next item (tight chain).
        if post <= nxt {
            score -= 8.0 * (1.0 - post / (nxt + 1.0));
        }
    } else {
        // Last item: pure best-fit.
        score -= 20.0;
    }

    // ---- Relative-to-mean-residual shaping ----
    // Bins far below mean residual are "cramped"; avoid dumping there unless exact fit.
    let dev = mean_residual - post;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score += dev * 0.05; // slight reward for roomier-than-average bins
    }

    // ---- Last-chance bin before opening a new bin ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0; // strongly prefer using the only fitting open bin
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline; penalize lightly so only good alternatives win,
        // but reward opening fresh bin when item is large and open bins are messy.
        score = cap - item_size as f64; // post_residual of fresh placement
        if open_bins_count > 0 && fitting_bins_count > 1 {
            score += 12.0; // discourage opening when decent bins exist
        }
        if item_size >= 70 {
            score -= 10.0; // big items start fresh bins happily
        }
        if next_item_size > 0 && next_item_size <= (cap as u32 - item_size) {
            score -= 15.0; // fresh bin can chain with next item
        }
    }

    // ---- Late-stream tightening: consolidate as stream ends ----
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * 0.1 * progress;

    // Small tie-breaker: prefer bins with more open competition (keeps bin count low).
    score -= (open_bins_count as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: penalize post_residual non-linearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr / 10.0) * (pr / 10.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves slack: mild reward proportional to reuse.
            score -= 0.3 * next_item_size as f64 / (post_residual as f64 + 1.0);
        } else {
            // Next item cannot use this bin's remainder: penalize dead space slightly more.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Crowding pressure: with many open bins, discourage spreading; favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual anchoring: bins far below mean residual (very full) are attractive.
    score -= 0.25 * (mean_residual - pr).clamp(-50.0, 50.0);

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // gives a tight fit (large post_residual) and stream is early/uncrowded.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Cheaper to open early when few bins exist.
        score -= 8.0 * (1.0 - progress);
        // If item leaves awkward remainder in a fresh bin, that's normal; if item is large,
        // a fresh bin is a reasonable home.
        score -= 0.2 * item_size as f64;
        // If next item also fits alongside in a fresh bin, opening is attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
        // If many bins can already fit the item, don't open a new one.
        score += 3.0 * fitting_bins_count as f64;
    }

    // Small penalty for leaving residual just below the smallest plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 + 2.0 * progress * progress) * (1.0 - 0.5 * progress);
    score += 6.0 * coupling;

    // Reward tight fits more strongly later in the stream
    let tight = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 14.0 * tight * tight * (0.5 + progress);

    // Penalize large dead space quadratically
    score += 0.05 * pr * pr / cap;

    // Lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - diff / cap) * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: prefer only when existing fit is poor
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful"
    // multiples / near-multiples of common item sizes (1..=100 unknown dist,
    // so use coarse classes via integer division).
    let pr = post_residual;
    let cls = pr / 10; // coarse class 0..=10
    match cls {
        0 => score -= 30.0,                 // near-perfect fit
        1 => score -= 22.0,                 // excellent
        2 => score -= 15.0,                 // good
        3 => score -= 8.0,                  // decent
        4 | 5 => score -= 2.0,              // average
        6 | 7 => score += 3.0,              // mediocre
        8 | 9 => score += 8.0,              // poor
        _ => score += 0.0,                  // untouched bin
    }

    // Modulo coupling: residuals divisible by 5/10 are more reusable.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // how tightly next item fits into post_residual
            let slack = pr - next_item_size;
            score -= (20.0 * (1.0 - slack as f64 / bin_capacity as f64)).max(0.0);
        } else {
            // next item won't fit here: slight penalty proportional to overshoot
            score += ((next_item_size - pr) as f64 * 0.05).min(5.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it's only chosen
    // when open bins score poorly.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.5;
    }

    // Progress: early in stream, be slightly more willing to open bins /
    // keep flexibility; late in stream, tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 4.0;

    // Discourage creating dead space far below mean residual utility.
    if pr > 0 && (pr as f64) < mean_residual * 0.3 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward leaving that gap.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap == 0.0 {
            score -= 80.0;
        } else if gap > 0.0 && gap < 10.0 {
            score -= 30.0;
        } else if gap < 0.0 && post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> penalize opening/spreading further,
    // but the new-bin candidate (bin_residual == bin_capacity) should be penalized
    // when plenty of open bins can still absorb items.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
    }

    // Mild preference for tighter bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Late-stream pressure: as the stream progresses, favor consolidating into
    // existing bins to avoid leftover fragmentation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: minimize dead space
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 == nr {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual as f64 - nr;
            // small slack after next item is good; penalize proportionally
            score -= 300.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize relative to gap
            score += 0.5 * (nr - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.7;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: keep it neutral-high so only genuinely bad fits trigger opening
    if bin_residual == bin_capacity {
        score += 60.0;
        // open a new bin if item is large relative to typical residuals
        if item_size as f64 > mean_residual {
            score -= 120.0;
        }
    }

    // Dead-space penalty for large unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Late-stream tightness: as stream progresses, waste less
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - 2.0 * tightness).max(0.0);

    // Penalize dead space that no plausible future item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // unusable sliver given min item size 1? keep mild
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting large residual
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: empty bin gets baseline cost plus bias
    // depending on how bad the best existing fit would be and stream progress.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 25.0 + 5.0 * fitting_bins_count as f64;
        }
        // Early in the stream, opening fresh bins is cheaper (more future use).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If mean residual across open bins is high, prefer reusing open bins.
        score += 0.3 * mean_residual;
        // If next item is large and current item is small, a fresh bin may pair them well.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Mild penalty for proliferating bins.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual is below mean (consolidate space).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;

    let mut score = norm_pr * (1.0 + 0.5 * progress * norm_pr);

    // smooth polynomial coupling of post_residual with stream progress
    score += 0.35 * norm_pr * norm_pr * (1.0 - progress);
    score -= 0.6 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // tight fit reward, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 0.8 * tightness * tightness * (0.5 + progress);

    // lookahead: reward leaving space that fits the next item
    if next > 0.0 {
        let gap = (norm_pr - next).abs();
        score += 0.4 * gap * gap * (1.0 - progress);
        if next <= norm_pr {
            score -= 0.5 * (1.0 - progress);
        }
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // penalize spreading across many open bins late in stream
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // new-bin candidate: make it mildly unattractive unless residual is huge
    if bin_residual == bin_capacity {
        score += 0.25 + 0.5 * progress;
    }

    // dead-space penalty for very small residuals
    if norm_pr < 0.1 && norm_pr > 0.0 {
        score += 0.3 * (0.1 - norm_pr) / 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (large enough chunks divisible into capacity fractions)
    // are more valuable to keep tight than bins with dead-space leftovers.
    let pr = post_residual;
    let c = bin_capacity;
    // class 0: dead space (1..=10), class 1: small (11..=25),
    // class 2: medium (26..=50), class 3: large (51..)
    let class = if pr == 0 { 0 } else if pr <= 10 { 0 } else if pr <= 25 { 1 } else if pr <= 50 { 2 } else { 3 };

    // Reward tight fits strongly: subtract for small post_residual.
    match class {
        0 => score -= 12.0 + 0.5 * (c - pr) as f64, // perfect/near-perfect fit
        1 => score -= 4.0,
        2 => score -= 1.0,
        _ => {}
    }

    // Penalize leaving residuals that are unusable for typical future items:
    // leftover in (0, 10) exclusive of exact fit is dead space.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // fraction of next item's need covered by this residual
            let cover = next_item_size as f64 / pr as f64;
            if cover > 0.7 {
                score -= 8.0 * cover;
            }
        } else if pr > 0 && pr >= next_item_size / 2 {
            // residual could pair with another bin for the next item
            score += 2.0;
        }
        // residual too small for next item's minimum: mild penalty
        if pr > 0 && pr < next_item_size.min(10) {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current open bins have small residuals (poor fits everywhere).
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 30.0;
        // large items are better placed in fresh bins
        score -= (item_size as f64 / c as f64) * 25.0;
        // if no open bin fits well (few fitting bins relative to open bins)
        if fitting_bins_count == 0 || (open_bins_count as f64) * (item_size as f64 / c as f64) < 1.0 {
            score -= 20.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // many open bins with high mean residual: new bin is fine
        if mean_residual > 40.0 && open_bins_count > 3 {
            score -= 8.0;
        }
    } else {
        // prefer bins with residual close to item size (best fit shaping)
        let waste = (bin_residual - item_size) as f64;
        score += 0.1 * (waste / c as f64) * (waste / c as f64) * 100.0;
        // prefer filling bins that are already fairly full (reduce bin count)
        score -= 3.0 * (1.0 - bin_residual as f64 / c as f64);
    }

    // Modulo-style harmonic bonus: residuals that are multiples of common
    // item sizes (10/20/25/50) are more likely to be reused exactly.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small positive residuals are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: discourage spreading across too many bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += pressure * 4.0;

    // Prefer bins tighter than average residual (better fit quality).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., residual would be very small dead space elsewhere).
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills (waste minimization).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Dead-space penalty: residuals that no typical item (1..=100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits exactly / well here -> strong reward.
            if gap < 1.0 {
                score -= 150.0;
            } else if gap <= 5.0 {
                score -= 90.0;
            } else if gap <= 15.0 {
                score -= 40.0;
            } else {
                // Leftover after next item would be large; mild penalty scaled by gap.
                score += gap * 0.5;
            }
        } else {
            // Next item does NOT fit after placing here: penalize proportionally
            // to how much we "strand" capacity, unless this is a last-chance bin.
            score += gap * 0.8;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let tightness = (mean_residual - residual_f) / mean_residual;
        score += tightness * 30.0; // tighter (smaller residual) bins get lower score
    }

    // Prefer filling bins that are already fairly full (small residual relative to capacity).
    let fill_ratio = item_size as f64 / residual_f.max(1.0) as f64;
    score -= fill_ratio * 40.0;

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit. Make empty bin mildly unattractive by default.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream
        // (fewer future items -> wasted open capacity matters less).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 70.0 * (1.0 - 0.5 * progress);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 25.0;
        }
    }

    // Mild entropy term coupling stream position and open bins: when many bins
    // are open, consolidate into existing bins to avoid spreading items.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strong preference for tight fits (best-fit core).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here: mild penalty for large leftovers.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowding effect: with many open bins, prefer consolidating into
    // bins with small residuals (below mean) to close them out.
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.3 * diff;
    }

    // Time horizon: early in the stream, be picky (penalize loose fits);
    // late in the stream, accept decent fits more readily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.2 * (bin_residual - item_size) as f64;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Default mild penalty so existing bins usually win.
        score += 20.0;
        // But if item is huge and fit is poor elsewhere, new bin becomes good.
        if large_item > 0.7 {
            score -= 35.0 * (large_item - 0.7) / 0.3;
        }
        // If many bins are open and mean residual is high, reuse is cheap:
        // make new bins less attractive.
        score += 0.15 * mean_residual;
    }

    // Small bonus for filling more than half of the bin's current space.
    if item_size * 2 >= bin_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    // Reward tight fits with a smooth quadratic bonus scaled by stream progress.
    score -= 12.0 * fit_quality * fit_quality * (0.5 + progress);
    // Penalize residuals that cannot host the lookahead item (dead space), smoothly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap < 0.0 {
            score += 0.35 * (-gap) * (1.0 + progress);
        } else {
            // Slight reward if post-residual exactly accommodates next item.
            score -= 2.0 * (1.0 - (gap / bin_capacity as f64).min(1.0));
        }
    }
    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }
    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;
    // Nudge toward bins whose residual is close to the mean (balance), smooth coupling.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs() * (0.3 + 0.7 * progress);
    // New-bin candidate: keep its base score competitive but slightly penalized early,
    // increasingly attractive late when fragmentation dominates.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 6.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into buckets.
    // Residuals <= 10 are perfect (class 0), small residuals are penalized lightly,
    // mid-range residuals are the worst (dead space that nothing can use).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr <= 40 {
        score += 8.0; // awkward mid dead space
    }

    // Harmonic compatibility: can next_item_size land exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // perfect follow-up
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            // modulo classes: gap small or a divisor-like relation is good
            if gap <= 10 {
                score -= 15.0;
            } else if pr % next_item_size == 0 && next_item_size >= 20 {
                score -= 12.0; // harmonic division
            } else {
                score += gap as f64 * 0.3;
            }
        } else {
            // next item cannot fit here; post_residual becomes dead space
            score += (pr as f64) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and the new bin offers a fresh harmonic canvas.
    if bin_residual == bin_capacity {
        let tight_fit_here = pr <= 10;
        if !tight_fit_here {
            score += 25.0;
        } else {
            score += 15.0;
        }
        // early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (tighter bins keep slack concentrated).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Modulo threshold on post_residual: multiples of 10 are "harmonic" slots
    if pr % 10 == 0 && pr > 0 && pr < 100 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept a future item (>=1, unknown distribution so assume >=10 safe zone)
    // are pure waste -> heavy quadratic penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 * (10 - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose post-residual can still plausibly host a future item.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Coupling with lookahead: if next item fits the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many open bins
    // unless the fit is genuinely tight.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 30.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when the item barely fits
    // nowhere well or open bins are very full on average.
    if bin_residual == bin_capacity {
        // Baseline mild cost: opening a new bin is generally worse than
        // placing into an existing bin with a reasonable fit.
        score += 15.0;
        // But if all open bins are nearly full, a new bin is fine.
        let tight = mean_residual / bin_capacity as f64;
        if tight < 0.15 {
            score -= 60.0;
        }
        // If the item is large relative to mean residual, new bin is good.
        if (item_size as f64) > mean_residual {
            score -= 30.0;
        }
    }

    // Mild preference for fuller bins overall (waste-not heuristic).
    score -= 0.3 * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    // Small early-stream conservatism: keep bins openable early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * fit_quality;

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chain: two perfect fills
        } else if next_item_size < post_residual {
            // next item fits: penalize leftover after the pair
            let pair_left = post_residual - next_item_size;
            score += 0.5 * pair_left as f64;
            if pair_left == 0 {
                score -= 40.0;
            }
        } else {
            // next item cannot use this bin's leftover: dead space risk
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good open bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin still attractive if next item would pair well
            if bin_capacity - next_item_size >= item_size {
                score -= 10.0;
            }
        }
    }

    // Mild late-stream tightening: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: low post_residual is good, but dead space
    // below the minimum plausible item size is pure waste.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize small unusable leftovers more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting capacity
            score += 5.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: can afford to be pickier about tight fits.
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, pack tightly since future flexibility matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - fill_ratio);

    // Global state: many open bins with high mean residual -> prefer reusing
    // existing capacity rather than spreading out.
    if open_bins_count > 4 && mean_residual > item_size as f64 * 1.5 {
        score -= 10.0;
    }

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 }
            else if post_residual as f64 > mean_residual { 0.5 } else { 0.0 };
        score = (bin_capacity as f64 - item_size as f64) + 30.0
            - 80.0 * desperation
            - (if next_item_size > item_size { 20.0 } else { 0.0 });
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); late in stream,
    // dead space matters less so discount it.
    let phase = (progress * std::f64::consts::PI).sin();
    score *= 0.75 + 0.25 * phase;

    // Polynomial penalty for small-but-nonzero post_residual (unusable dead space),
    // strongest when residual is just below the typical small item (1..20).
    let dead = 1.0 - pr_norm;
    let dead_curve = dead * dead * (1.0 - dead);
    score -= 18.0 * dead_curve * (1.0 - progress);

    // Reward near-perfect fills superlinearly.
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * pr_norm;

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - gap) * (1.0 - progress);
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // post_residual can't host next item: mild penalty scaled by waste
        score += 4.0 * (1.0 - pr_norm) * (1.0 - progress);
    }

    // Prefer bins already below mean residual (consolidate emptier bins) with
    // smooth quadratic interaction with progress.
    let dev = (mean_residual - pr) / cap;
    score -= 6.0 * dev * dev * (0.5 + 0.5 * progress);
    score += 3.0 * dev * progress;

    // New-bin candidate: penalize opening a new bin mildly, more early in stream.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 40.0;
    }

    // Penalize unusable dead space: post_residual too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic classes: modulo arithmetic on post_residual.
    // Residuals divisible by common item sizes (10, 20, 25, 50) are reusable.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 5.0;
    }
    if pr % 50 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Awkward class: residual just below a small item threshold (e.g. 9, 19, 24).
    if pr == 9 || pr == 19 || pr == 24 || pr == 49 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit: penalize proportionally to how close it came.
        let gap = (next_item_size as f64 - post_residual as f64).min(30.0);
        score += 0.4 * gap;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate logic: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        let tight = (bin_residual - item_size) as f64;
        // Base cost of opening a new bin.
        score += 12.0;
        // If existing bins are crowded (mean residual small), new bin is fine.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
        // Large item leaving large post_residual in a fresh bin is wasteful.
        if tight > 50.0 && item_size <= 50 {
            score += 15.0;
        }
        // Many open bins: discourage opening yet another.
        score += 1.5 * open_bins_count as f64;
    } else {
        // Reward using bins that are already fairly full.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill;
    }

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * fill_proxy(post_residual, bin_capacity);

    score
}

fn fill_proxy(post_residual: u32, bin_capacity: u32) -> f64 {
    1.0 - (post_residual as f64 / bin_capacity as f64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can hold few future items are bad.
    // Penalize small-but-nonzero post_residual harder than large residuals.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            40.0 // unusable gap for items >= 10
        } else if post_residual < 20 {
            18.0
        } else if post_residual < 30 {
            8.0
        } else {
            0.0
        };
        score += dead;
    } else {
        // Perfect fit is heavily rewarded.
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity (waste ratio penalty).
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Open-bin pressure: discourage spreading when many bins are open,
    // but encourage using nearly-full bins to close them out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Reward bins whose residual is well below the mean (they are being filled).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size > post_residual {
            // next item cannot fit here; slightly penalize leaving this bin open
            score += 6.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * -1.0;
        if fitting_bins_count == 1 {
            score -= 50.0; // still prefer new bin over terrible last-chance fit? no: keep pressure
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits (small post_residual is already good; deepen it).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Aggressive 2-step lookahead: if the next item fits in the post residual,
    // reward this bin strongly (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= (1.0 - chain_waste / bin_capacity as f64) * 35.0;
        } else {
            // Next item cannot chain here; penalize proportionally to leftover dead space.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Relative to mean residual: bins below-mean residual are "tight" — prefer
    // filling them (rewards), bins above-mean are looser — slight penalty.
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make an empty bin unattractive unless the item
    // is large relative to capacity or no real alternative exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 40.0 - large_item * 30.0;
        if fitting_bins_count <= 1 {
            score -= 45.0; // no real alternative, allow opening
        }
    }

    // Late in the stream, consolidate: discourage spreading across many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 + progress) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size is worthless.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fill
    } else {
        // dead-space penalty grows super-linearly for small unusable gaps
        let usable = (post_residual as f64 / bin_capacity as f64).powf(1.5);
        score += usable * 8.0;
    }

    // Fit ratio: prefer bins where the item occupies a large fraction of residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to leftover tightness
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: penalize slightly, more if this bin was the only option
            score += 4.0 + (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless the item
    // is huge or all existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit = mean_residual / bin_capacity as f64;
        // penalize new bins more when many bins exist and residuals are large
        let waste_penalty = 20.0 + open_bins_count as f64 * 2.0 * (0.3 + avg_fit) * (1.0 - progress * 0.5);
        score += waste_penalty;
        // but if the item is very large relative to capacity, new bin is fine
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
        // if no other bin could fit (fitting_bins_count would be 0 elsewhere), neutralize
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Time horizon: late in the stream, be more aggressive about filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual below the mean (consolidate small leftovers)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    score += poly * cap * 0.5;
    // penalize dead space more as stream advances
    score += norm_pr * norm_pr * progress * 30.0;
    // reward tight fits
    let tight = item_size as f64 / bin_residual.max(1) as f64;
    score -= tight * tight * 10.0;
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // lookahead coupling: reward residual matching next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let fit_next = next_item_size as f64 / pr.max(1.0);
        score -= fit_next * 8.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }
    // mild new-bin penalty so open bins are preferred unless residual is tiny
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: bucket post_residual by integer division on capacity quarters.
    let class = post_residual / (bin_capacity / 4);
    let class_penalty = match class {
        0 => -60.0, // near-perfect fit: residual < 25
        1 => -20.0, // good fit: 25..50
        2 => 10.0,  // mediocre: 50..75
        _ => 30.0,  // wasteful: >= 75
    };
    score += class_penalty;

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic pairing: reward if next item fits the post residual (mod-style compatibility)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0;
            // extra reward for exact chaining
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            }
        } else {
            // post residual dead relative to lookahead: penalize proportional dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a premium cost unless the stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = cap * 0.6; // base reluctance
        if open_bins_count == 0 {
            new_bin_score = -1000.0; // must open
        }
        // early stream: opening bins is cheap (more future items to fill them)
        new_bin_score -= 200.0 * (1.0 - progress);
        // if many bins can fit, opening a new one is wasteful
        if fitting_bins_count > 2 {
            new_bin_score += 150.0;
        }
        score = new_bin_score;
    } else {
        // Prefer bins whose residual deviates from the mean in a compacting direction
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Mild open-bins pressure: discourage scattering across many bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny unusable gaps (1..10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to the item size (low waste ratio).
    let waste_ratio = post_residual as f64 / (bin_residual as f64 + 1.0);
    score += 30.0 * waste_ratio;

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.25 * tightness;

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }
    // Penalize leaving a gap just under the next item (dead space for it).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; encourage filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Mean residual coupling: prefer bins below mean residual (fill the fullest bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large dead-space risk elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score = bin_capacity as f64 * 0.75 + desperation - 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
