pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that cannot serve the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        } else {
            // Reward residuals that exactly accommodate the lookahead item.
            if post_residual == next_item_size {
                score -= 6.0;
            }
        }
    }

    // Penalize large residuals lightly (waste), but only when many bins are open.
    score += 0.05 * (post_residual as f64) * (open_bins_count as f64).min(10.0) / 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor (high post_residual) or the item is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fits_exist = fitting_bins_count > 0;
        let mut new_bin_penalty = 15.0;
        if fits_exist {
            // The more bins can fit the item, the less attractive a new bin is.
            new_bin_penalty += 5.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in the stream, prefer consolidating into open bins.
        new_bin_penalty += 10.0 * progress;
        // Large items benefit from a fresh bin (avoid fragmenting many bins).
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty;
    }

    // Slight bonus for filling bins above mean residual (balance consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * x * x);

    // Smooth stream-progress coupling: tighter bins favored more late in stream
    score -= 30.0 * (1.0 - x) * (x * x) * (1.0 + t);

    // Dead-space penalty: quadratic in unusable gap relative to typical item
    let gap = x * x * x;
    score += 20.0 * gap;

    // Lookahead: reward residual that fits next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let d = x - nx;
        let fit = 1.0 / (1.0 + 40.0 * d * d);
        score -= 15.0 * fit * (1.0 - t * 0.5);
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x * x);
    }

    // Prefer filling bins with low mean residual (consolidation)
    score += 0.3 * (mean_residual - pr).abs();

    // Slight penalty for opening new bins when many exist
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
