    // New-bin candidate: only attractive when current bin would leave big dead space
    // and many bins are already open (prefer consolidation otherwise).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_waste = post_residual as f64 > 0.5 * cap;
        if big_waste && open_bins_count > 2 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 30.0; // discourage spreading items across fresh bins
        }
    }

    // Mild consolidation pressure toward bins tighter than the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are "dead".
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space penalty grows as gap becomes unusable; near-zero gaps are worst.
        let gap = post_residual as f64;
        score += 12.0 + (10.0 / (gap + 1.0));
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // Last chance: strongly favor using the only bin that fits to avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize placements in bins when many bins are open,
    // encouraging consolidation... but reward filling a bin close to capacity.
    if post_residual <= 10 {
        score -= 10.0; // nearly perfect fill bonus
    }

    // Mild preference to fill bins below mean residual (good fits) when many bins open.
    if open_bins_count > 2 {
        let mr = mean_residual;
        if (post_residual as f64) < mr {
            score -= 2.0;
        } else {
            score += 2.0;
        }
    }

    // New-bin candidate: neutral-ish baseline with slight penalty so it's chosen
    // only when existing bins have bad fits (their dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score += 6.0;
        // If next item is large and current item is large, a fresh bin is attractive.
        if item_size > 60 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 120.0 - 0.6 * slack_after_next;
            // Extra bonus if the next item then leaves another usable chunk.
            if slack_after_next >= 10.0 && slack_after_next <= 40.0 {
                score -= 25.0;
            }
        } else {
            // Post-residual is dead space relative to the next item.
            score += 0.5 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0));
        }
    } else {
        // Last item: just minimize leftover.
        score -= 50.0;
    }

    // Compare against mean residual: bins tighter than average are more precious.
    let residual_gap = post_residual as f64 - mean_residual;
    if residual_gap < 0.0 {
        score += 0.4 * residual_gap; // tighter than average -> lower score
    } else {
        score += 0.25 * residual_gap; // looser than average -> penalize mildly
    }

    // Last-chance bin: only this bin fits -> strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would waste a lot.
    if bin_residual == bin_capacity {
        score = (post_residual as f64) + 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        if item_size > 70 {
            score -= 40.0; // big items are fine in fresh bins
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer reusing existing ones over opening more.
    score += 3.0 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.6 * post_residual as f64;
        }
        // Reward leaving exactly enough room for the next item
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // Reward leaving room >= next item with mild preference for snugness
        if post_residual >= next_item_size {
            score -= 0.25 * (post_residual as f64 - next_item_size as f64).recip().min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Many open bins: discourage spreading, prefer filling existing bins
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (consolidate waste)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Time horizon: early on, be more willing to open fresh bins for large items;
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (35.0 - 45.0 * progress);
    // Opening a new bin is bad if many bins already open
    score += new_bin * 0.8 * open_bins_count as f64;

    // Slight bonus for filling a bin completely
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 18.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 14.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Tight fits are strongly rewarded, quadratically
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness;

    // Penalize new-bin candidate (residual == capacity) with smooth term
    let is_new = if (bin_residual as f64 - cap).abs() < 0.5 { 1.0 } else { 0.0 };
    score += is_new * (30.0 + 40.0 * progress + 10.0 * mean_residual / cap);

    // Last-chance bin bonus (only one fitting bin)
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        let fits_next = if (post_residual as f64) >= next_item_size as f64 { 1.0 } else { 0.0 };
        let waste = ((next_item_size as f64 - pr).abs()) / cap;
        score -= 15.0 * fits_next;
        score += 8.0 * waste * (1.0 - progress);
    }

    // Spread pressure from mean residual
    score += 0.05 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes vs reusable classes.
    // Class A: post_residual in [1, 10] -> near-perfect fit, strong reward.
    if post_residual <= 10 {
        score -= 60.0;
    }
    // Class B: post_residual in (10, 30] -> usable for small items, mild reward.
    else if post_residual <= 30 {
        score -= 15.0;
    }
    // Class C: post_residual in (30, 60] -> awkward middle zone, mild penalty.
    else if post_residual <= 60 {
        score += 8.0;
    }
    // Class D: post_residual > 60 -> bin left mostly empty, penalize relative to fill ratio.
    else {
        score += (post_residual as f64 - 60.0) * 0.9;
    }

    // Modulo-10 harmonic sub-class: residuals divisible by 10 align with
    // typical item sizes and are more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Odd/prime-ish residuals (mod 10 in {1,3,7,9}) are harder to fill.
    let m = post_residual % 10;
    if m == 1 || m == 3 || m == 7 || m == 9 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly; reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item fits with a good margin, mild reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 12.0;
        }
    }
    // If next item will NOT fit here, this bin's residual is terminal dead
    // space; penalize proportionally (wasted capacity).
    else if next_item_size > post_residual && post_residual > 0 {
        score += post_residual as f64 * 0.35;
    }

    // Last-chance bonus: if this is the only bin that fits the item, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to capacity (poor candidates elsewhere) or no meaningful fit
    // exists; otherwise penalize spreading across bins.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill >= 0.7 {
            score -= 10.0; // large items start fresh bins willingly
        } else {
            score += 40.0 - 40.0 * fill; // small items should reuse open bins
        }
    }

    // Prefer tighter existing fits: compare against mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late in the stream, consolidation matters more: favor filling existing
    // bins over leaving many partially-filled bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    // Mild penalty for accumulating too many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Dead space that cannot fit the lookahead item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild late-stream tightening: prefer tighter fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / 10.0);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let baseline = item_size as f64 + 10.0;
        score = baseline.max(score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact 2-step chain match: post_residual == next_item_size.
        if gap == 0.0 {
            score -= 40.0;
        } else {
            // Penalize proportional to mismatch, scaled by lookahead size.
            score += (gap / (next_item_size.max(1) as f64)) * 20.0;
        }
        // If next item can't fit in the post-residual, penalize dead space creation.
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    }

    // Tight fit: item fills most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Compare post_residual against mean residual: leaving less than average is good.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full
    // or the item is a poor fit everywhere.
    if bin_residual == bin_capacity {
        score += 10.0;
        if mean_residual < item_size as f64 + 10.0 {
            score -= 20.0; // existing bins too full, new bin justified
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing potential in fresh bin
        }
    }

    // Late in the stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    }

    // Many open bins: favor filling existing ones rather than spreading.
    score += open_bins_count as f64 * 0.3 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 35.0 * tightness.powi(4);

    // Lookahead: bonus if the next item also fits in the leftover space
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 10.0;
        // extra reward if next item fills the remainder almost exactly
        let gap = post_residual as f64 - next_item_size as f64;
        score -= 6.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // mild penalty proportional to leftover that the next item cannot use
        score += 0.03 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Best-fit flavor: prefer bins whose residual is below the mean (more filled)
    score += 0.06 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    if bin_residual == bin_capacity {
        score += 6.0 + 2.5 * (open_bins_count as f64).sqrt();
        // early in the stream, opening bins is cheaper
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - t);
    }

    // Avoid leaving large dead space late in the stream
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * t * (post_residual as f64 / bin_capacity as f64).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = (item_size as f64) / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (0.5 + progress) - pr_norm * (1.0 - progress) * (1.0 - progress);
    score += 8.0 * poly;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (10.0 + 20.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 6.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 3.0 * (pr - nx) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Mild penalty for spreading many open bins when residuals are large
    let mr = mean_residual / cap;
    score += 0.5 * open_bins_count as f64 * mr * progress;

    // New-bin candidate: prefer it only when post_residual is huge and stream is early
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress) - 10.0 * pr_norm * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits with a non-linear discount.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 30.0 * (-8.0 * tightness).exp();

    // Harmonic classes: classify post_residual into residue classes mod 10 / mod 25.
    // Residuals in "dead" classes (small leftovers that few items can use) are penalized.
    let pr = post_residual;
    if pr > 0 {
        let cls = pr % 25;
        let dead_penalty = match cls {
            1..=9 => 12.0,               // nearly unusable slivers
            10..=19 => 4.0,              // only tiny items fit
            _ => 0.0,                    // 20..=24 and 0: still usable
        };
        score += dead_penalty;
        // Integer-division threshold: residual that cannot host the next item is worse.
        if next_item_size > 0 && pr < next_item_size {
            score += 10.0 + 0.05 * (next_item_size - pr) as f64;
        }
        // Exact-divisibility harmony: residual divisible by 25 is valuable.
        if pr % 25 == 0 && pr > 0 {
            score -= 6.0;
        }
        // Harmonic fraction: residual as fraction of capacity in harmonic bands.
        let frac = pr as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 5.0 * frac;
        } else if frac < 0.1 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, else new bin opens.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if next item exactly complements this placement, reward heavily.
    if next_item_size > 0 && next_item_size == pr {
        score -= 20.0;
    } else if next_item_size > 0 && pr >= next_item_size {
        score -= 3.0;
    }

    // Prefer filling existing bins over opening new ones, scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / many bins open.
        score += 15.0 + 20.0 * progress + 0.3 * open_bins_count as f64;
        // But if mean residual across open bins is too small to host future items,
        // opening fresh space is reasonable.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 12.0;
        }
    } else {
        score -= 4.0 + 3.0 * progress;
        // Bonus for bins already below mean residual (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
