    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight packing (small post_residual)
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item -> big reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 60.0 * (1.0 - (diff as f64 / bin_capacity as f64)).max(0.0);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Post-residual too small for next item: mild penalty scaled by dead space
        if (post_residual as u64) < (next_item_size as u64) {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward bins whose residual deviates favorably from the mean (tighter than average)
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly encourage using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, especially early and when alternatives exist
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 20.0;
        }
        // Opening a new bin is more acceptable when it enables a perfect next fit
        if next_item_size > 0 && (bin_capacity as u32 - item_size) == next_item_size {
            score -= 50.0;
        }
    }

    // Slight preference for filling nearly-full bins late in the stream
    if post_residual < 10 {
        score -= 10.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 12 {
        score += 30.0;
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Penalize residuals that the next item cannot use.
            score += 8.0 * ((post_residual as f64) / (bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (post_residual as f64) > 0.35 * (bin_capacity as f64);
        if fitting_bins_count > 1 || !poor_fit {
            // Existing bins are decent; discourage opening a new one.
            score += 120.0 + 20.0 * progress;
        } else {
            // Poor fits exist; opening a fresh bin is acceptable, slight penalty
            // to keep bin count low when possible.
            score += 15.0 + 0.5 * (open_bins_count as f64);
        }
    }

    // Global state: mildly prefer filling bins with above-average residual
    // (larger holes) to keep small holes available for small items.
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Slight preference for bins with more slack overall early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: waste after placement (quadratic coupling to punish dead space)
    let mut score = pr * (1.0 + pr / cap) * (1.0 + progress);

    // Reward tight fits: smooth sigmoid-like term on fill ratio
    let fill = 1.0 - pr / cap;
    let tightness = fill * fill * (3.0 - 2.0 * fill); // smoothstep
    score -= 12.0 * tightness;

    // Penalize near-full bins slightly less as stream progresses (lock in placements)
    score -= 6.0 * progress * tightness;

    // Last-chance bonus: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's post-residual would be large dead space
    if bin_residual == bin_capacity {
        // Penalize opening new bins early; allow late in stream when waste is big
        let open_penalty = 8.0 + 30.0 * (1.0 - progress);
        score += open_penalty;
        // But if item leaves a very usable gap for the lookahead item, soften
        if next_item_size > 0 && (pr as u32) >= next_item_size {
            score -= 10.0;
        }
    }

    // Lookahead coupling: favor residuals that still accommodate the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack_fit = 1.0 - ((pr - ni) / cap).min(1.0);
            score -= 5.0 * slack_fit * (1.0 - progress);
        } else {
            score += 4.0; // dead space for the known next item
        }
    }

    // Crowd penalty: many open bins with low mean residual -> prefer filling existing
    if open_bins_count > 1 && bin_residual != bin_capacity {
        let mean_fill = 1.0 - mean_residual / cap;
        score -= 3.0 * mean_fill;
    }

    // Mild preference for bins tighter than average
    score += 2.0 * ((bin_residual as f64) - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Integer-division thresholds: reward small post_residual classes.
    let cap = bin_capacity as f64;
    let q = post_residual / 10; // harmonic decade class
    score -= (10 - q.min(10)) as f64 * 2.0;

    // Modulo arithmetic: bins whose residual is a "nice" divisor of capacity
    // (50, 25, 20, 10) are more reusable.
    if post_residual > 0 && (bin_capacity % post_residual.max(1)) == 0 {
        score -= 8.0;
    }
    if post_residual % 10 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item exactly fills post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * frac;
        } else {
            // next item cannot use this residual: penalize large dead space
            score += 0.05 * (post_residual as f64 - (cap - next_item_size as f64)).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere (item is large relative to capacity).
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        if big_item > 0.7 && fitting_bins_count <= 1 {
            score -= 30.0;
        } else {
            score += 25.0 + 20.0 * (1.0 - big_item);
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's already tight; prefer packing it tightly.
    let dev = mean_residual - post_residual as f64;
    score -= 0.1 * dev.max(0.0);

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tightness bonus: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_frac;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins;
    // a new empty bin should look expensive.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and remaining stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 3.0 * pressure * (1.0 - 0.5 * progress);
    } else {
        // Existing bin: slight reward that grows with pressure (consolidation incentive).
        score -= 0.8 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, this
    // placement leaves a useful gap; reward it. Otherwise penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps the bin pool balanced); penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream, be extra thrifty: reward filling existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 10.0 * progress * fill_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward: strongly prefer bins where the item fills residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness reward: quadratic decay of residual waste.
        score -= 2.0 * (bin_capacity as f64 - post_residual as f64).sqrt();

        // 2-step lookahead: reward bins whose post_residual matches the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 40.0 / (1.0 + gap as f64);
            if gap == 0 {
                score -= 60.0; // perfect chain: item then next item fill bin
            }
        } else if next_item_size > 0 {
            // Post-residual too small for next item: penalize dead space
            score += 15.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Penalize wasting a near-full bin on a small item (poor fit).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio < 0.4 {
        score += 25.0 * (0.4 - fit_ratio) * 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins have
    // large residuals that would be fragmented anyway.
    if bin_residual == bin_capacity {
        score += 120.0;
        if mean_residual > 60.0 {
            score += 40.0; // plenty of space left elsewhere; don't open new bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // pairing potential in a fresh bin
        }
    }

    // Mild preference for balancing residuals relative to mean early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * (post_residual as f64 - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Reward perfect fit.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that no future item (>= 1) can use badly:
    // prefer post_residual either 0 or reasonably large.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64).log1p();
        } else {
            // next item won't fit here; penalize leaving medium residuals
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: be picky about fit quality
        score += 4.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Empty new-bin candidate: prefer it only when current bins fit poorly
    // (large residual waste) or stream is early with many items remaining.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste_gap = (mean_residual - item_size as f64).max(0.0);
        score += 20.0; // baseline penalty for opening a new bin
        score -= waste_gap * 0.6;   // worth it if open bins are wasteful
        score -= (1.0 - progress) * 10.0; // early stream: new bins are cheap long-term
        if mean_residual < item_size as f64 {
            score += 15.0; // open bins are tight; new bin reasonable
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins with residual above mean (balance spread).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_ratio = post_residual as f64 / cap;
    let is_new_bin = bin_residual == bin_capacity;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, waste matters more, so penalize large post_residual super-linearly.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score += progress_coupling * 8.0 * post_ratio * post_ratio * (1.0 - fit_ratio);

    // Reward tight fits (low post_residual relative to item) with a non-linear bonus.
    let tightness = 1.0 - post_ratio;
    score -= 6.0 * tightness * tightness * fit_ratio;

    // Penalize dead space that cannot plausibly hold the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap > 0.0 {
            score += 3.0 * (gap / cap) * (gap / cap) * (1.0 + progress);
        } else {
            // next item fits this bin's post residual: reward saving it
            score -= 2.0 * (-gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0 + 6.0 * progress;
    }

    // New-bin candidate: penalize opening a bin, more so when alternatives exist
    // and early in the stream where consolidation is cheap.
    if is_new_bin {
        let alt_pressure = (fitting_bins_count as f64).ln_1p();
        score += 10.0 + 8.0 * alt_pressure * (1.0 - progress) + 4.0 * (open_bins_count as f64).ln_1p();
    } else {
        // Mildly favor bins whose residual deviates from the mean (fragmentation control)
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 1.5 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (residual in {0,1}) heavily rewarded.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 2 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 pair well
    // with the 10..80 item range (common sizes divide into 10-blocks).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    } else if post_residual % 10 >= 8 {
        // 8/9 leftover is nearly a dead class unless small items arrive.
        score += 10.0;
    }

    // Integer-division thresholds: can next_item_size land in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain bonus: stronger when the chained fit is tight.
            let tight = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.3 * tight;
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0; // chained result again in a good class
            }
        } else {
            score += 8.0; // next item cannot follow here
        }
    }

    // Fraction of capacity wasted: quadratic penalty on residual/capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * frac * frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // or many bins are already open with high mean residual.
    if bin_residual == bin_capacity {
        score += 35.0;
        if post_residual as f64 > mean_residual + 20.0 {
            score += 20.0;
        }
        if open_bins_count as f64 > 8.0 + 0.05 * total_items as f64 * (step_index as f64 / total_items.max(1) as f64) {
            score += 15.0;
        }
    }

    // Slight tie-break toward bins below mean residual (better consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small to fit the smallest item (1..100, so <10 is dead)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize small-but-maybe-usable gaps lightly
    if post_residual >= 10 && post_residual < 30 {
        score += 5.0;
    }

    // Reward tight fits (near-perfect packing)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.8 {
        score -= 15.0 * (fit_ratio - 0.8);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open bins pressure: with many open bins, discourage spreading into new/other bins
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: only attractive when no good fit exists (large item vs residuals)
    if bin_residual == bin_capacity {
        // base penalty so new bins are used sparingly
        score += 8.0;
        // if the item fits poorly in typical open bins (item larger than mean residual), new bin becomes viable
        if item_size as f64 > mean_residual {
            score -= (item_size as f64 - mean_residual) * 0.4;
        }
    }

    // Lookahead: if next item would fit the post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item barely misses the post_residual, penalize slightly (dead space risk)
    if next_item_size > post_residual && next_item_size - post_residual < 10 && post_residual > 0 {
        score += 4.0;
    }

    // Early stream: allow more bins; late stream: consolidate aggressively
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
