    if bin_residual == bin_capacity {
        // Mild penalty so an existing reasonable fit wins; relax late in stream
        // or when many bins are already open and fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 - 20.0 + 15.0 * progress + 0.5 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize post_residual that is unusable: too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    } else if post_residual >= 10 && post_residual < 30 {
        // small but potentially useful; mild penalty scaled by how small
        score += (30 - post_residual) as f64 * 0.4;
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra reward if next item fills post_residual almost exactly.
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; penalize proportionally.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless the fit
    // in existing bins is terrible. Give the empty bin a high baseline penalty
    // that shrinks as the stream progresses (fewer chances left, be less frugal).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 - 10.0 * progress;
        // If no open bin can fit the item at all, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If open bins are nearly full on average, a fresh bin is reasonable.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 12.0;
        }
    } else {
        // Mild reward for using existing bins, stronger when many are open.
        score -= 2.0 + (open_bins_count.min(20) as f64) * 0.3;
    }

    // Prefer bins whose residual is close to the mean (balance load) slightly.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    // Time-dependent frugality: early on, be conservative about filling bins tightly.
    score -= 4.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let g = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * prn * prn * (1.0 + 2.0 * g);

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) / cap;
        score += 8.0 * waste * waste;
        // Reward residual closely matching next item (smooth coupling)
        let match_term = 1.0 - ((pr - nx) / cap).abs();
        score -= 6.0 * match_term * match_term * match_term;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly unless existing fits are bad
    if bin_residual == bin_capacity {
        let tight = if pr >= 0.0 { 0.0 } else { 0.0 };
        score += 10.0 + 15.0 * (1.0 - g) + tight;
        // If many bins fit, opening new bin is wasteful
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mild penalty when bin is far from mean residual (keeps bins homogeneous)
    score += 0.05 * (pr - mean_residual).abs();

    // Reward tight fits (small post_residual) with smooth cubic term
    score -= 4.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - prn);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: post_residual bucketed by capacity fractions (integer division)
    let frac = post_residual * 4 / bin_capacity; // 0..3 quartile class
    let class_penalty: [f64; 4] = [0.0, 2.0, 8.0, 20.0];
    score += class_penalty[frac as usize];

    // Dead-space classes via modulo: residuals of 1..=4 are nearly useless
    if post_residual > 0 && post_residual <= 4 {
        score += 15.0;
    }

    // Lookahead harmony: does next item exactly fill post_residual? big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits here: reward tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * tight;
            // modulo harmony: next item leaves a class-0 residual again
            let next_post = post_residual - next_item_size;
            if next_post * 4 / bin_capacity == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last chance: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count > 0 {
            score += 40.0 + 20.0 * progress;
        } else {
            score -= 5.0; // no alternative: new bin is fine
        }
        // avoid hoarding bins early
        score += open_bins_count as f64 * 0.5;
    } else {
        // prefer bins whose residual deviates from mean less (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Mild preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space severity grows as gap becomes too small for typical future items.
        let dead = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
        // Penalize gaps that cannot fit even a small item (post_residual < ~10).
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        }
        // Mild penalty for medium gaps that are hard to fill.
        if post_residual >= 10 && post_residual < 30 {
            score += 8.0 * (30.0 - post_residual as f64) / 20.0;
        }
        let _ = dead;
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits: the smaller the waste relative to the item, the better.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into new bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += 3.0 * pressure;

    // If a new empty bin is a candidate, make it unattractive unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * open_bins_count as f64;
        // But if this bin is the only fitting bin, opening new is worse.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier gaps first? no—
    // prefer bins with residual close to item to reduce fragmentation).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good, but dead space < next item is bad).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain fill
        } else if post_residual >= next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.15 * leftover; // next item fits: reward, less if it leaves more waste
        } else {
            // next item does NOT fit in post_residual: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than average is good (we consumed the "easy" space).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving unusable tiny dead space (< smallest plausible item) unless perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Later in the stream: prefer consolidating into fewer bins.
    score += 10.0 * progress * (open_bins_count as f64 / (1.0 + post_residual as f64 / 100.0));

    // New-bin candidate: neutral-ish base, only chosen if no open bin scores better.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight fit).
    let mut score = post;

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 2.0 * cap;
    }

    // Lookahead: reward if the next item exactly fills the resulting residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 1.5 * cap;
    } else if next_item_size > 0 {
        // Penalize post residuals that are too small to ever hold the next item
        // (dead space), but only mildly since later items may fit.
        if (next_item_size as f64) > post {
            score += 0.15 * (next_item_size as f64 - post);
        } else {
            // Next item could fit here later; slight bonus for keeping option.
            score -= 0.05 * (post - next_item_size as f64).min(30.0);
        }
    }

    // Penalize creating small unusable gaps relative to typical item scale.
    if post > 0 && post < 10.0 {
        score += 0.5 * (10.0 - post);
    }

    // Last chance: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 0.8 * cap;
    }

    // New-bin candidate handling: bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Compare post residual of new bin against mean residual of open bins.
        // If open bins have large residuals, they can absorb the item; penalize new bin.
        let open_pressure = mean_residual - item; // how much slack open bins have on average
        if open_pressure > 0.0 {
            score += 0.6 * open_pressure; // discourage new bin when slack exists
        } else {
            score -= 0.6 * (-open_pressure); // encourage new bin when bins are tight
        }
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * t;
        // Many open bins: discourage opening more.
        score += 4.0 * (open_bins_count as f64).sqrt();
    }

    // Mild preference for filling fuller bins (small residual before placement).
    score += 0.1 * (bin_residual as f64 - item).max(0.0);

    // Global balance: if mean residual is high, prefer bins below mean (use the emptier ones? no —
    // prefer bins whose post residual stays near mean to keep flexibility).
    if !is_new_bin {
        let dev = (post - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post residual (tight fit).
    let mut score = pr;

    // Smooth non-linear reward for very tight fits: (1 - pr/cap)^3 scaled.
    let tightness = 1.0 - pr / cap;
    score -= 30.0 * tightness * tightness * tightness;

    // Normalized stream progress coupling: as stream advances, reward tight fits more
    // (consolidation pressure grows smoothly with progress).
    score -= 20.0 * progress * tightness * tightness;

    // Penalize post residual relative to mean residual of open bins:
    // creating dead space above average is bad; below average is a small bonus.
    score += 0.5 * (pr - mean_residual);

    // Lookahead: reward if the next item fits into post_residual (chain packing),
    // smoothly scaled by how well it fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_after = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack_after) * (1.0 - slack_after);
        } else {
            // Next item won't fit: mild penalty proportional to overflow gap.
            score += 0.2 * (nxt - pr);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when other bins can fit the item; relax slightly late in stream.
    if bin_residual == bin_capacity {
        let base = 45.0;
        let decay = 25.0 * progress * progress;
        let fit_pressure = if fitting_bins_count > 0 { 20.0 } else { 0.0 };
        score += base + fit_pressure - decay;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize leftover space, with a superlinear dead-space penalty.
    let mut score = post * (1.0 + 0.002 * (post / cap_f) * post / cap_f * 10.0);

    // Harmonic class of post_residual: residues that pair well with common item
    // sizes (multiples of 10 and small sizes 1..=10) are less punishing.
    let r = post_residual % 10;
    let harmonic_bonus: f64 = match r {
        0 => 6.0,                 // perfectly reusable slot
        1..=5 => 2.0,             // small items (1..=10) can still fill
        6..=9 => -2.0,            // awkward residue, mildly penalize
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division thresholds: classify post_residual into usable bands.
    let band = post_residual / (bin_capacity / 4).max(1); // quarter bands
    match band {
        0 => score -= 4.0,        // near-full bin: excellent packing
        1 => score += 1.0,
        2 => score += 3.0,
        _ => score -= 1.0,        // nearly empty bin: almost a new bin
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // fraction of next item consumed by this residual
            let frac = next_item_size as f64 / post.max(1.0);
            score -= 6.0 * frac;
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            let waste = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            score += 0.02 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless current
    // fit is terrible or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if next_item_size > 0 && post_residual > 0 {
            (next_item_size as f64 / post) > 1.0
        } else { false };
        let mut new_bin_score = 10.0;
        if poor_fit { new_bin_score -= 14.0; }
        if progress < 0.1 { new_bin_score -= 3.0; }
        if open_bins_count == 0 { new_bin_score -= 20.0; }
        // discourage new bin when mean residual is large (room exists elsewhere)
        new_bin_score += 0.05 * mean_residual;
        score += new_bin_score;
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    score += 0.001 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    // Exact-fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Exact fit: strongly reward (zero waste).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Small unusable gap: dead space penalty (strict avoidance archetype).
        score += 18.0 + (10 - post_residual) as f64;
    } else if post_residual <= 20 {
        // Moderate gap: mild penalty, could still be usable for small items.
        score += 4.0;
    }

    // Lookahead (k=2): reward if the next item can also fit in the leftover space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin, more so when many bins are already open
    // (open_bins_count pressure) and early in the stream when consolidation matters most.
    if is_new_bin {
        score += 10.0 + open_bins_count as f64 * (1.5 + 2.0 * (1.0 - progress));
        // But reward opening a fresh bin if the item leaves a large, versatile residual.
        if post_residual >= 50 {
            score -= 8.0;
        }
    } else {
        // Reward reusing open bins, scaled by how much slack the fleet has.
        score -= 2.0 + mean_residual / 50.0;
    }

    // Mild global preference for keeping residual close to the fleet mean (balance).
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item's size -> strong reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Post residual too small for next item: dead space penalty (unusable sliver).
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 + 0.3 * post_residual as f64;
        }
        // Post residual large enough to host next item comfortably: mild bonus.
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual far below mean wastes the bin's remaining usefulness.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score += 0.4 * mean_gap;
    } else {
        score -= 0.15 * (-mean_gap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize opening a bin when the item fits reasonably
    // elsewhere; allow it when this is a forced or very tight situation.
    if bin_residual == bin_capacity {
        let tight_fit = item_size as f64 / bin_capacity as f64;
        score += 25.0 + 50.0 * (1.0 - tight_fit);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: opening is correct
        }
    }

    // Relative fill efficiency: reward high utilization of the bin.
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Late in the stream, prefer consolidating into few bins.
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically (unusable slivers).
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain;
        } else {
            // Next item won't chain here: penalize leaving a small awkward gap.
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 6.0 * (1.0 - gap / next_item_size as f64);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless post-residual would be a useless sliver.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
        if post_residual < 10 {
            score -= 8.0;
        }
    }

    // New-bin candidate logic: an empty bin should only win when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 20.0;
        // If many bins fit, opening a new bin is wasteful.
        score += 4.0 * fitting_bins_count as f64;
        // Early in the stream, opening fresh bins is cheaper (more future items to pair).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If mean residual is high, open bins are roomy; prefer using them.
        score += 0.15 * mean_residual;
        // Small items pair well with fresh large residual.
        if item_size <= 30 {
            score -= 10.0;
        }
        // Huge item nearly filling capacity alone: fine to open new bin.
        if item_size >= 70 {
            score -= 12.0;
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * fit_ratio;

    // Slight reward for bins already below-average residual (packing them tighter first).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early: prefer tight fits (small post_residual). Late: residual matters more.
    let mut score = pr * (1.0 + 1.5 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Dead-space penalty: residuals too small for typical future items are costly.
    let dead = (pr - next_item_size as f64).max(0.0) / cap;
    score += 60.0 * dead * dead * (1.0 - progress);

    // Lookahead synergy: reward bins whose post_residual exactly accommodates next item.
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let fit_quality = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 25.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or late in the stream; smooth in fitting_bins_count and progress.
    if bin_residual == bin_capacity {
        let escape_urge = (fitting_bins_count as f64).recip();
        score += 30.0 + 50.0 * (1.0 - escape_urge) + 60.0 * progress;
        // But allow opening when mean residual across open bins is small (all bins tight).
        score -= (mean_residual / cap).max(0.0) * 70.0;
    }

    // Mild diversity term: prefer bins whose residual deviates from mean when mean is large.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: post_residual small relative to smallest possible item
    if post_residual < 10 {
        score -= 60.0;
    }

    // Harmonic class logic: quantify how "usable" the post residual is
    // via modulo structure against common item sizes (1..=100).
    let pr = post_residual;
    if pr > 0 {
        // fraction of capacity left
        let frac = pr as f64 / bin_capacity as f64;
        // dead-space penalty if residual falls in awkward class (e.g., 91..=99 hard to fill)
        if pr >= bin_capacity / 2 {
            // large residual is valuable: reward
            score -= frac * 40.0;
        } else if pr > 90 {
            // awkward tiny sliver: penalize
            score += 25.0;
        } else {
            // mid residual: mild reward scaled by divisibility with next item
            score -= frac * 10.0;
        }
        // modulo harmonic classes: reward residuals divisible by common sizes
        let mut harmony = 0.0;
        for d in [5u32, 10, 20, 25, 50] {
            if pr % d == 0 {
                harmony += 4.0;
            }
        }
        score -= harmony;
    } else {
        score -= 40.0; // exact fill is ideal
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= 15.0;
            // harmonic: next item divides post_residual well
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use leftover: penalize proportional to leftover
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing fits are terrible
    if bin_residual == bin_capacity {
        // baseline for new bin: slightly worse than decent fits
        score = 95.0 + (open_bins_count as f64).sqrt() * 2.0;
        // late in stream, opening new bins is fine
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
        // if next item is huge, a fresh bin is attractive
        if next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer bins with below-mean residual (fill the emptiest useful bins)
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.05;

    // Slight preference to reuse fewer bins overall
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below half the smallest plausible
    // next item are "unusable gaps" — penalize them heavily and nonlinearly.
    if post_residual > 0 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 3.0;
    }

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += next_item_size as f64 - post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many open bins
    // unless this is a tight fit.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - tightness) * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin has a good fit
    // (i.e., this item would create large dead space in every open bin).
    if bin_residual == bin_capacity {
        // Baseline new-bin score: moderate, so it wins only over bad fits.
        score = 60.0 + post_residual as f64 * 0.5;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff * 0.5);
        if post_residual == next_item_size {
            score -= 80.0; // exact chaining bonus
        }
        // Penalize residuals too small for any plausible next item (dead space)
        if post_residual < next_item_size.min(10) {
            score += 20.0;
        }
    } else {
        // Last item: minimize waste directly
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (good packing density)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when other bins fit,
    // unless the current fit is very poor (large post_residual).
    if bin_residual == bin_capacity {
        let base = 45.0 + 0.5 * open_bins_count as f64;
        // allow new bin if this placement would leave a big awkward gap
        if post_residual as f64 > mean_residual * 1.5 {
            score -= 30.0;
        }
        score += base;
    }

    // Mild preference to fill bins progressively deeper over stream time
    score -= (step_index as f64 / (total_items.max(1) as f64)) * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Exact / near-exact fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 5 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize spreading across many open bins; encourage consolidation
    // when open bins are relatively empty.
    if bin_residual < bin_capacity {
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 3.0 * fill_ratio;
        if (bin_residual as f64) < mean_residual {
            score += 2.5; // this bin is emptier than average -> prefer fuller bins
        } else {
            score -= 1.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 25.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        } else {
            // If the best alternative fit is poor (high post_residual), soften penalty.
            new_bin_penalty -= (post_residual as f64).min(20.0);
        }
        score += new_bin_penalty;
    }

    // Mild time-horizon coupling: early in stream, be more open to new bins
    // (long horizon amortizes); late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    } else {
        score += 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let mut score = pr;

    // Non-linear coupling: residual squared normalized, penalizing large dead space
    score += 0.8 * (pr / cap) * (pr / cap) * cap;

    // Smooth progress interaction: tighter bins favored later in the stream
    score -= (1.0 - progress) * 0.3 * it;
    score += progress * 0.5 * pr;

    // Reward tight fits via smooth saturating term
    let tight = (it / bin_residual.max(1) as f64).min(1.0);
    score -= 6.0 * tight * tight;

    // Lookahead coupling: penalize leaving residual that only awkwardly fits next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).abs();
        let fit_next = if nx <= pr { 1.0 - (pr - nx) / cap } else { 0.0 };
        score -= 4.0 * fit_next * fit_next;
        score += 0.05 * gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist, but
    // allow it when open bins are crowded (low mean residual) or late stream
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score += 30.0 - 20.0 * crowding - 10.0 * progress;
        score += 0.2 * open_bins_count as f64;
    }

    // Mild pressure to reduce number of open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by integer division
    // into coarse "usable slots" (what sizes could still fit: 1..=100).
    let post = post_residual as f64;
    let post_class = (post_residual / 10) as f64; // 0..=10 harmonic class

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 25 {
        score -= 18.0;
    } else if post_residual <= 50 {
        score -= 5.0;
    } else {
        // Large dead space: penalize, especially if nothing typical fits.
        score += 8.0;
        // Harmonic residue: leftover that is awkwardly small (e.g. mod 10 in 1..9)
        let awkward = post_residual % 10;
        if awkward > 0 && awkward < 10 && post_residual < 30 {
            score += 6.0;
        }
    }

    // Coupling with next item: reward if next item fits into post_residual exactly/well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let chain_left = post_residual - next_item_size;
            score -= 25.0 - chain_class_penalty(chain_left);
        } else {
            // Next item won't fit here; mildly penalize bins that trap the stream,
            // unless post_residual is tiny (bin effectively closed anyway).
            if post_residual >= 10 {
                score += 4.0;
            }
        }
    } else {
        // Last item: any bin works, prefer tightest (post_residual already dominates).
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a fresh bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: high, but scales down if existing bins are fragmented.
        let mut new_bin_score = 55.0;
        // If mean residual across open bins is small, open bins are nearly full -> new bin cheaper.
        let frag = mean_residual / cap;
        new_bin_score -= 20.0 * (1.0 - frag).min(1.0);
        // If many bins already open, discourage sprawl slightly.
        new_bin_score += (open_bins_count as f64).sqrt() * 2.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 15.0 * progress;
        // If the item is large relative to capacity, a fresh bin is natural.
        new_bin_score -= 10.0 * (item_size as f64 / cap);
        score = score.max(new_bin_score);
        return score;
    }

    // Prefer bins whose residual is close to item (best-fit core), modulated by
    // harmonic class of bin_residual.
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.15 * fit_gap;

    // Modulo-class bonus: bins whose residual shares a harmonic class with the item
    // (same decade) tend to leave class-aligned leftovers.
    if (bin_residual / 10) == (item_size / 10) {
        score -= 6.0;
    }

    // Small preference to fill bins with larger residual when many bins are open.
    score -= 0.05 * mean_residual.min(cap);

    score
}

#[inline]
fn chain_class_penalty(chain_left: u32) -> f64 {
    // Penalty for chained leftover space quality: small leftovers after chaining are good.
    if chain_left == 0 { 0.0 }
    else if chain_left <= 10 { 3.0 }
    else if chain_left <= 25 { 10.0 }
    else { 18.0 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it's smaller than the smallest plausible item (1..100
    // range, but treat < 12 as effectively unusable waste).
    if post_residual < 12 && post_residual > 0 {
        score += 40.0; // creating tiny dead space is bad
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly preferred
    } else if post_residual <= 5 {
        score -= 25.0; // near-perfect fit
    }

    // Coupling with mean residual: prefer bins whose residual is close to the
    // item (fills a bin that is "due" to be closed) rather than a nearly full
    // or nearly empty bin mismatched with the item.
    let diff = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.15 * diff;

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins; when few are open, opening a new bin is less costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, this
    // placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0; // next item likely fits well after this placement
    }
    // Penalize placements that leave a gap just barely too small for the
    // known next item (wasting the lookahead opportunity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate handling: the empty-bin call has bin_residual ==
    // bin_capacity. Opening a new bin is only attractive when the item fits
    // poorly everywhere (large post_residual waste) or no other bin fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins are open.
        score += 55.0 + 1.5 * open_bins_count as f64;
        // But if the item is large (leaves small residual in a fresh bin),
        // a new bin is a reasonable "big item" strategy.
        if item_size >= 60 {
            score -= 25.0;
        }
        // Late in the stream, avoid opening new bins for small items.
        if progress > 0.7 && item_size < 30 {
            score += 30.0;
        }
    }

    // Mild preference for filling larger-residual bins when the fit is good
    // (keeps small-residual bins available for small future items).
    if post_residual <= 20 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already base term).
    // Penalize dead space relative to mean residual across open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but imperfectly: mild reward scaled by how much would remain
            let second_residual = post_residual - next_item_size;
            score -= 15.0 - (second_residual as f64) * 0.15;
        } else {
            // next item would NOT fit here: penalize leaving awkward gaps
            score += 8.0;
            // extra penalty if post_residual is a small unusable sliver
            if post_residual < 10 {
                score += 12.0;
            }
        }
    } else {
        // last item: prefer minimal waste
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer; using them well is valuable.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all fits are poor.
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 30.0;
        // cheaper to open new bins late in stream when many bins are open anyway
        score -= progress * 10.0;
        // if many bins already open, consolidation is preferable
        score += open_bins_count as f64 * 0.5;
        // if next item is large, a fresh bin gives flexibility
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Prefer filling bins that are already quite full (small residual) to close them out.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into post_residual, this is a great chain.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_left = post_residual - next_item_size;
        score -= 20.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
    }
    // Penalize leaving a residual that nothing useful can fill (dead space).
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // dead space penalty grows if residual is too small for typical items
        if post_residual < 10 {
            score += 15.0 * (10.0 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_residual - item_size) as f64 > mean_residual);
        if poor_fit_everywhere {
            score -= 30.0;
        } else {
            // discourage opening bins when decent fits exist
            score += 40.0 + 5.0 * open_bins_count as f64;
        }
        // early in stream, opening bins is cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to item_size (best-fit core).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * fit_gap;

    // Mild preference for bins with residual near the global mean (balance).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Late in the stream, consolidate: penalize spreading across many bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * progress * open_bins_count as f64 * 0.1;

    // Small noise-free tiebreaker: prefer lower-indexed (earlier) bins implicitly
    // via mean residual coupling; keep deterministic.
    if post_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual normalized, shaped by progress
    let prn = pr / cap;
    let prog_sq = progress * progress;
    let coupling = prn * prn * (1.0 - progress) + prn * prog_sq;
    score += 12.0 * coupling;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 8.0 * (1.0 - prn) * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            let miss = (nx - pr) / cap;
            score += 10.0 * miss * miss;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins already open and mean residual is large
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (10.0 + 0.5 * open_bins_count as f64 + 0.2 * mean_residual);

    // Mild penalty for leaving residual near the awkward mid-range (too big to waste, too small for typical items)
    let awkward = (prn - 0.35) * (prn - 0.35);
    score += 5.0 * awkward * (1.0 - progress);

    // Prefer bins with residual below mean (denser bins)
    score += 0.1 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes (small gaps that common item sizes can fill)
    // get rewarded. Class = post_residual mod 10.
    let gap = post_residual;
    let gap_class = (gap % 10) as f64;
    // reward gaps that are either near-zero or in {10,20,...} multiples usable later
    if gap == 0 {
        score -= 50.0; // perfect fit
    } else if gap % 10 == 0 && gap <= 50 {
        score -= 15.0; // clean reusable class
    } else if gap < 10 {
        score -= 5.0; // small dead space, tolerable
    } else {
        score += gap_class * 0.8; // penalize awkward residue classes
    }

    // Integer-division threshold on post_residual: large leftovers invite future items
    let gap_quotient = gap / 20; // 0..5 harmonic bands
    score -= gap_quotient as f64 * 6.0;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this bin (modular match on gap - next_item_size).
    if next_item_size > 0 {
        if next_item_size <= gap {
            let next_gap = gap - next_item_size;
            if next_gap == 0 {
                score -= 40.0;
            } else if next_gap % 10 == 0 {
                score -= 20.0;
            } else {
                score += (next_gap % 10) as f64 * 0.5;
            }
        } else {
            // next item won't fit here; mild penalty proportional to wasted band
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, penalize heavily
    // so a new bin may be preferred when the fit is bad.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score += 8.0 + (gap % 7) as f64 * 1.5;
    }

    // New-bin candidate: opening a fresh bin should only win when the current
    // fit is poor. Base its score on capacity fraction of the item.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score = 30.0 + frac * 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // stream of large items: fresh bin reasonable
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin anyway
        }
    }

    // Progress coupling: late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - gap as f64).abs() * 0.3;

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize creating gaps too small for the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Reward using gaps that exactly fit the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Open bins pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild preference for tighter bins (small residual before placement).
    score += 0.15 * bin_residual as f64;

    // Mean residual coupling: avoid bins far below mean residual (wasteful spread).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Late-stream tightening: dead space matters more as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: tight fit. Reward small post_residual.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let gap = pr - next;
            // Perfect chain: next item fills bin completely.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Reward proportionally to how well next item fits leftover.
                score -= 30.0 * (1.0 - gap / pr);
            }
        } else {
            // Next item cannot use the residual: penalize dead space creation.
            score += 12.0 * (next - pr) / bin_capacity as f64;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 25.0 * (1.0 - tightness);
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.25 * mean_residual;
        // Late in the stream, opening new bins is less harmful (no waste risk).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins when item is small.
    if item_size < 30 && open_bins_count > 5 {
        score += 0.5 * (open_bins_count as f64 - 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack * 0.1);
        } else {
            // next item cannot use leftover; mild penalty for large leftovers
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Crowding: when many bins are open, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress * crowd / (1.0 + open_bins_count as f64);
    } else {
        // New-bin candidate: penalize opening bins unless residual spread is bad.
        score += 30.0 + 20.0 * (1.0 - progress);
        if mean_residual < item_size as f64 * 0.5 && open_bins_count > 2 {
            score -= 35.0; // existing bins are too full; opening is fine
        }
    }

    // Prefer bins whose residual is close to item_size (waste minimization).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: minimize waste, with non-linear (quadratic) waste penalty that
    // intensifies as the stream progresses (tighter packing demanded later).
    let mut score = pr + (pr / cap) * (pr / cap) * (12.0 + 18.0 * progress) * cap;

    // Reward bins whose post-residual exactly accommodates the lookahead item
    // (smooth coupling, no piecewise constants).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let fit_quality = 1.0 - gap / cap;
        let bonus = 30.0 * fit_quality * fit_quality;
        if pr >= nxt {
            score -= bonus;
        } else {
            score += bonus * 0.5;
        }
    }

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty for bins deviating from the mean residual (keeps residual
    // profile homogeneous, smooth in mean_residual).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // Discard proliferation late in the stream: prefer filling existing bins.
    score += (open_bins_count as f64) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill of the bin after placement
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Harmonic class logic: post_residual mod classes reveal dead-space quality
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, ideal
    } else {
        // Integer division thresholds on post_residual
        if pr < 10 {
            score += 25.0; // tiny unusable sliver -> dead space penalty
        } else if pr < 20 {
            score += 8.0;
        } else if pr < 35 {
            score -= 5.0; // useful mid-range residual
        }
        // Modulo arithmetic: residuals divisible by common item sizes are reusable
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 && pr > 0 {
                score -= 6.0;
            }
        }
    }

    // Lookahead: if the next item cannot fit into post_residual, this bin becomes dead
    if next_item_size > 0 {
        if next_item_size > pr {
            // bin will be closed anyway -> placing here is "free" if fit is decent
            score -= 12.0;
        } else if next_item_size == pr {
            score -= 40.0; // next item perfectly fills this bin
        } else {
            let gap = pr - next_item_size;
            score += gap as f64 * 0.3; // leaving a gap sized awkwardly for next item
        }
        // modulo coupling between next item and post residual
        if pr > 0 && next_item_size % pr.max(1) == 0 && pr >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bin where waste is smallest relative to others
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a fresh bin
        score = bin_capacity as f64 * 0.85;
        // cheaper to open early when many items remain (amortize)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // if existing bins would leave bad residuals, opening is more attractive
        score += (post_residual as f64 - mean_residual).abs() * 0.1;
        // avoid spreading across too many bins when few remain
        score += open_bins_count as f64 * 1.5;
    } else {
        // favor bins whose residual is close to the mean (balance open bins)
        score += (bin_residual as f64 - mean_residual).abs() * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps (1..=9) are heavily penalized,
    // since item sizes are 1..100 and small gaps rarely get filled.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0;
    } else if post_residual <= 19 {
        score += 12.0;
    }

    // Perfect fit: strongly reward leaving exactly zero residual.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Pressure from number of open bins: prefer reusing bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // Mean residual coupling: if this bin's post residual is far below the mean
    // residual, it's a good consolidation; penalize leaving large residuals
    // when the mean residual is small (waste in otherwise tight bins).
    if (post_residual as f64) > mean_residual + 10.0 {
        score += 6.0;
    } else if (post_residual as f64) < mean_residual - 10.0 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 30.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

