    // 2-step lookahead: strongly reward bins where the next item exactly fills
    // the post residual (chained perfect fit).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it matches
            let match_frac = next_item_size as f64 / post_residual as f64;
            score -= 100.0 * match_frac;
        } else {
            // next item cannot fit here: penalize leftover dead space
            score += 20.0;
        }
    }

    // Tightness reward: small post_residual relative to capacity is good,
    // but only if it doesn't create unusable slivers.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 50.0 * tightness * tightness;

    // Compare against mean residual: bins already tighter than average are
    // preferred to absorb this item (keeps loose bins available).
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 10.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to capacity or existing fits are very poor.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.5 && fitting_bins_count == 0 {
            score -= 300.0; // big item with no existing fit -> open new bin
        } else {
            score += 250.0; // otherwise discourage opening new bins
        }
    }

    // Early in stream, allow more bins to keep flexibility; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
