    }

    // Prefer bins with residuals close to mean (balance load)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: early in stream, be conservative (favor filling existing bins less aggressively);
    // late in stream, prioritize closing bins tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate logic: penalize opening a new bin unless current fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin
        score += 55.0;
        // Reduce cost if existing fit would leave very wasteful residual
        let waste = if post_residual > 0 { post_residual as f64 } else { 0.0 };
        if item_size <= bin_residual {
            score -= (waste / bin_capacity as f64) * 40.0;
        }
        // If no open bins exist at all, opening is free
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If next item is large and won't fit anywhere else anyway, new bin is fine
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Slight preference to fill bins with more residual used already (larger item_size)
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr) + 12.0 * norm_pr * norm_pr * cap;

    // Smooth coupling of post_residual with stream progress: late in stream,
    // tight fits matter more (dead space increasingly costly)
    score += 30.0 * progress * norm_pr * (1.0 - norm_pr);

    // Reward large item fraction filling the bin
    score -= 20.0 * norm_item * (1.0 - progress);

    // Lookahead: reward if next item fits the post residual (smooth coupling)
    let fits_next = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
    let tightness = if next_item_size > 0 { 1.0 - ((post_residual as i64 - next_item_size as i64).unsigned_abs() as f64 / cap) } else { 0.0 };
    score -= 15.0 * fits_next * tightness * (0.5 + progress);
    // Penalize post residual that is too small for next item (creates near-dead space)
    score += 10.0 * (1.0 - fits_next) * (1.0 - norm_next) * norm_pr * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    score -= 25.0 * last_chance;

    // New-bin candidate: penalize mildly unless existing fits are bad
    score += 18.0 * is_new_bin * (1.0 - 0.6 * norm_item) - 5.0 * is_new_bin * progress;

    // Spread across many open bins is bad; prefer consolidating into bins below mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * (1.0 - is_new_bin);

    // Mild penalty for opening bins when many are open
    score += is_new_bin * (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over small moduli
    // capture "waste shape" — residuals that are multiples of common item
    // sizes are more reusable, so reward them (subtract).
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        // Very small residuals are near-dead space; penalize extra.
        if pr < 10 { score += 12.0; }
        else if pr < 20 { score += 5.0; }
    } else {
        // Perfect fit is the best outcome.
        score -= 25.0;
    }

    // Integer-division threshold on post_residual: can it hold a "small" item?
    let small_thresh: u32 = 30;
    if pr >= small_thresh {
        score -= (pr / small_thresh) as f64 * 2.0;
    }

    // Lookahead coupling: reward residuals that can hold the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 8.0 + 0.05 * (pr - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to how close.
        score += 0.1 * (next_item_size - pr) as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // spread across open bins; make the empty-bin call less attractive unless
    // the item is large and fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual * (open_bins_count as f64) * 0.01;
        score += 20.0 + waste - 0.15 * item_size as f64 - 5.0 * progress;
        // If item is huge relative to capacity, opening fresh is fine.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 18.0;
        }
    }

    // Mild preference to fill earlier bins (first-fit flavor) to consolidate.
    score += 0.002 * open_bins_count as f64;

    // Small tightness bonus: fraction of bin used by this placement.
    score -= 3.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 8.0; // tiny gaps are almost worthless
    } else if pr == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if pr >= 10 && pr < 25 {
        score += 6.0; // moderately awkward gap
    }

    // Reward when post_residual exactly matches the lookahead item (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 12.0; // would create new dead space for the next item
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0; // lookahead can also fit here
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 20.0 * fill_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // consolidating into existing bins, but allow new bins when mean residual is low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - progress) * 1.5;
    score += pressure;

    // New-bin candidate: base cost of opening a bin, discounted when existing
    // bins have high residuals (poor fits) or many bins already fit poorly.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 25.0;
        if mean_residual > 0.0 {
            new_bin_score -= (mean_residual / bin_capacity as f64) * 15.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0; // no alternative
        }
        // penalize opening new bins late in the stream
        new_bin_score += progress * 10.0;
        score += new_bin_score;
    } else {
        // Reward using bins whose residual is below average (good consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: zero dead space is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this placement enables a perfect chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item still fits in leftover: mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space creation
            score += 25.0;
        }
    }

    // Penalize leaving tiny unusable gaps (below minimum item size 1..=100 heuristic:
    // gaps smaller than 10 are nearly dead).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Prefer bins whose residual is already below the mean residual
    // (tighter bins get packed first, keeping large residuals flexible).
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a good fit (post_residual large relative to capacity).
    if bin_residual == bin_capacity {
        // Neutral-ish base for new bin; make it attractive only for very poor fits elsewhere.
        score = 100.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidate aggressively to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 20.0 + 0.35 * mean_residual;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild time-horizon adaptation: later in stream, be more conservative about new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Penalize bins deviating far below mean residual (fragmentation avoidance)
    score += 0.08 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth progress coupling: later in stream, value tight fits more
    let tight_fit_bonus = (1.0 - norm_pr).powi(3) * (1.0 + progress) * 30.0;
    score -= tight_fit_bonus;

    // Penalize residuals that are awkwardly small but nonzero (dead space)
    let dead = (norm_pr * (1.0 - norm_pr) * 4.0).powi(2);
    score += dead * (10.0 + 20.0 * progress);

    // Lookahead coupling: reward if post_residual matches next item size
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let match_bonus = (-gap / 20.0).exp() * 25.0;
        score -= match_bonus * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 40.0 * (0.6 + 0.4 * progress);
    }

    // Many fitting bins: mild penalty to prefer tighter bins
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Deviation from mean residual: prefer bins below mean residual (tighter)
    score += 0.15 * (pr - mean_residual);

    // New-bin candidate: smooth penalty growing with stream progress
    if bin_residual == bin_capacity {
        score += 8.0 + 25.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward tight fits (small post_residual)
    score -= 30.0 * (1.0 - frac).powi(3);

    // Penalize post_residuals in "dead zones": residuals that few item sizes (1..=100) can use
    // Usable if post_residual >= 10 (min item) or 0; otherwise it is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Modulo classes: residuals divisible by common item sizes are more reusable
    let p = post_residual;
    let mut reusable = 0u32;
    for k in [10u32, 20, 25, 50, 100] {
        if p % k == 0 {
            reusable += 1;
        }
    }
    score -= 5.0 * reusable as f64;

    // Lookahead coupling: does post_residual fit the next item exactly / well?
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_gap = post_residual - next_item_size;
        score -= 20.0 * (1.0 - next_gap as f64 / cap);
        if next_item_size == post_residual {
            score -= 50.0; // perfect chaining
        }
    } else if next_item_size > post_residual {
        // next item cannot go here; penalize more if this residual is large (waste potential)
        score += 0.3 * pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let avg_fit_penalty = (mean_residual - item_size as f64).abs();
        score += 40.0 + avg_fit_penalty * 0.2 - (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference to balance residuals early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold the
    // minimum item size are pure waste — penalize them hard.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps usable only by tiny items: moderate penalty.
        score += 18.0;
    }

    // Reward very tight fits (nearly perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual is close to the item size (high fill ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.9 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if the item fits terribly everywhere
    // else; make the empty bin costly by default, discounted by mean residual
    // pressure (high mean residual means open bins are already full-ish).
    if bin_residual == bin_capacity {
        score += 45.0 - 0.25 * mean_residual;
        // If the next item is large and this item nearly empties the bin,
        // opening fresh is more reasonable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Lookahead: prefer leaving residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mild preference for bins with residual below mean (denser bins first).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - chain_waste / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual is dead space for the next item: penalize proportionally.
        score += 0.35 * post_residual as f64;
    }

    // Reward perfect fits (zero post residual).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize creating small unusable slivers (below minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: prefer bins below mean residual (filling emptier... actually
    // filling bins with less residual concentrates usage; prefer bins whose residual is close to item).
    let residual_gap = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.15 * residual_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    // or it enables a perfect two-item pairing.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut new_bin_score = 55.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            new_bin_score -= 20.0 * (1.0 - chain_waste / (bin_capacity as f64));
        }
        if fitting_bins_count <= 1 {
            new_bin_score -= 35.0; // opening new bin is fine when alternatives are bad
        }
        // Late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += 20.0 * progress;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins with small post_residual
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Exact-fill jackpot
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: leftover space too small for typical items (<= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: if this is the only fitting bin, penalize alternatives
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, big reward (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize large wasted residual relative to next need
            score += (post_residual as f64 - (bin_capacity - next_item_size) as f64).max(0.0) * 0.3;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins are badly fragmented
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // discount the new bin when existing residuals are large/fragmented
        score -= (mean_residual / bin_capacity as f64) * 30.0;
        // early in stream: opening bins is cheap (build options)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
        // if few bins can fit, new bin is attractive
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    } else {
        // Prefer bins already deviating from mean residual (reuse concentrated space)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
        // mild penalty when many open bins exist, to consolidate
        score += open_bins_count as f64 * 0.5;
    }

    // Time-horizon modulation: late in the stream, prioritize tightness even more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += tightness * progress * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - (pr / cap);

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Reward tight fits more strongly as stream progresses
    score -= 30.0 * tightness.powi(3) * (0.5 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0 * (1.0 - pr / (next_item_size as f64)) * (0.5 + progress);
    } else if next_item_size > 0 {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize spreading residual too widely across many bins
    score += 0.5 * (mean_residual - pr).abs() * (0.5 + progress);

    // Mildly discourage opening new bins early, allow later
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
    }

    // Smooth quadratic interaction between fit ratio and progress
    score -= 15.0 * fit_ratio * fit_ratio * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity/4 (25-unit classes)
    let quarter = bin_capacity / 4;
    let residue = post_residual % quarter;
    // Penalize awkward residues (dead space unlikely to be reused)
    if residue != 0 {
        score += 6.0 * (1.0 - residue as f64 / quarter as f64);
    } else {
        score -= 4.0; // perfect harmonic fit (post_residual is multiple of 25)
    }

    // Integer-division thresholds: tiny post_residual is great (near-tight packing)
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual < 10 {
        score -= 6.0;
    } else if post_residual > bin_capacity / 2 {
        // leaving more than half the bin free after placement is wasteful
        score += 8.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item slots in: reward proportionally to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize by how much we "almost" fit
            let miss = (next_item_size - post_residual) as f64;
            score += 5.0 * (miss / bin_capacity as f64).min(1.0);
        }
    } else {
        // last item: prefer filling bins as tightly as possible
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive if no open bin is a good harmonic fit
    if bin_residual == bin_capacity {
        // base cost of opening a bin, softened late in the stream or when bins are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 10.0 * progress;
        if mean_residual > 0.0 {
            score += (mean_residual / bin_capacity as f64).min(1.0) * 8.0;
        }
    }

    // Slight preference for bins tighter than the mean (consolidate fullness)
    score += 0.15 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0;
    }
    // Zero post_residual (perfect fit) is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual (small waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Open-bin pressure: discourage spreading across too many bins when many are open.
    score += open_bins_count as f64 * 2.0;

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (concentrate large residuals for future large items).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item is large and post residual is small, slight penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (many fitting bins exist -> keep consolidating).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 80.0 + fitting_bins_count as f64 * 10.0;
        } else {
            score -= 10.0;
        }
    }

    // Slight stream-progression pressure: as the stream progresses, prefer
    // closing bins tightly rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (low post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else {
        // Penalize dead space quadratically relative to capacity.
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        score += 50.0 * dead_frac * dead_frac;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 150.0 * (1.0 - gap / 10.0);
            } else {
                score += 0.3 * gap;
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.8 * miss;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Mild penalty for spreading across too many open bins when new-bin candidate.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // If no open bin fits well, opening a new bin may be preferable.
        if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 5 {
            score -= 100.0;
        }
    }

    // Slight phase adaptation: early in stream, be more conservative about filling.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fit strongly favored.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize dead space non-linearly; small residuals are cheap.
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64 * 2.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Mild reward proportional to how well next item uses leftover.
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize leaving medium gaps that become dead space.
            let gap = (post_residual as f64) - (next_item_size as f64);
            if post_residual < next_item_size && post_residual > 0 {
                score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
            }
            let _ = gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // existing bins unless the fit is poor, but reward opening a new bin when
    // open bins are crowded (mean residual low) and this fit is bad.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; overcome only by tight fits elsewhere failing.
        score += 60.0;
        // If current open bins are nearly full on average, opening is attractive.
        if mean_residual < item_size as f64 * 1.5 {
            score -= 80.0;
        }
        // Late in stream with many items, prefer consolidation less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    } else {
        // Existing bin: slight preference when its residual is close to mean (balanced use),
        // penalize bins that are outliers (very full or very empty relative to mean).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
        // Penalize using very empty bins for tiny items (waste of fresh space).
        if bin_residual as f64 > mean_residual + 40.0 && item_size < 30 {
            score += 25.0;
        }
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 5 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.8 * progress) - 30.0 * progress * norm_pr * (1.0 - norm_pr);

    // Penalize dead space quadratically when stream is late
    let dead = 0.15 * norm_pr * norm_pr * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity { -25.0 } else { 0.0 };

    // New-bin candidate: neutral-ish, slightly penalized early, favored late
    let new_bin = if bin_residual == bin_capacity {
        8.0 + 15.0 * progress - 0.2 * item_size as f64
    } else { 0.0 };

    // Lookahead coupling: reward residual that can still hold next item
    let lookahead = if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        -6.0 * fits_next * (1.0 - progress)
    } else { 0.0 };

    // Smooth interaction with mean residual across open bins
    let coupling = -0.05 * (mean_residual - pr) * (1.0 - norm_pr);

    base + dead + last_chance + new_bin + lookahead + coupling
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "nice"
    // fractions of capacity (perfect fits, halves, thirds) via modular classes.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr == 0 {
        harmonic_bonus -= 60.0; // perfect closure
    } else if pr % 50 == 0 {
        harmonic_bonus -= 30.0;
    } else if pr % 25 == 0 {
        harmonic_bonus -= 18.0;
    } else if pr % 10 == 0 {
        harmonic_bonus -= 10.0;
    } else if pr % 5 == 0 {
        harmonic_bonus -= 4.0;
    }
    // Penalize small dead space that nothing (min size 1..10) can pair with well
    if pr > 0 && pr < 10 {
        harmonic_bonus += 25.0;
    } else if pr >= 10 && pr < 20 {
        harmonic_bonus += 8.0;
    }
    score += harmonic_bonus;

    // Integer-division class of post_residual against next item size:
    // reward if next item can exactly fill or nicely divide the post residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == pr {
            score -= 45.0; // next item closes this bin perfectly
        } else if next_item_size < pr {
            let rem = pr - next_item_size;
            if rem % 10 == 0 { score -= 12.0; }
            if rem < 10 { score += 15.0; } // leaves unusable sliver for next
            score -= (rem as f64 / cap) * 10.0;
        } else {
            // next item cannot fit here; slight penalty for hoarding space
            score += 6.0;
        }
    }

    // Fractional fill level coupling: prefer bins that become fuller.
    let fill = (bin_capacity - pr) as f64 / cap;
    score -= fill * fill * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make empty bins mildly unattractive unless open bins
    // are crowded or residual classes are bad.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 30.0 + pressure * 5.0;
        if mean_residual < cap * 0.25 {
            score -= 20.0; // open bins nearly full -> new bin is fine
        }
    }

    // Stream progression: early on, be conservative about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Tie-break toward bins below mean residual (consolidating space).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable dead space.
    if post_residual > 0 {
        if post_residual <= 9 {
            score += 60.0 * (10.0 - post_residual as f64); // harsh penalty for small unusable gaps
        } else if post_residual <= 19 {
            score += 12.0; // moderate penalty for marginal gaps
        } else {
            // Larger leftover space is reusable; slight reward for big residuals.
            score -= 0.15 * post_residual as f64;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 80.0; // chain of perfect fits
            } else if slack <= 9 {
                score += 30.0; // next placement would create dead space here
            } else {
                score -= 0.2 * slack as f64;
            }
        } else {
            // Next item cannot use this bin's leftover: residual becomes dead space.
            score += 0.3 * post_residual as f64;
        }
    }

    // Open-bin pressure: prefer spreading across fewer bins when residuals are healthy.
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: if open bins are already tight on average,
    // opening a new bin is more acceptable; if they're loose, prefer filling them.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score += 25.0 + 1.5 * open_bins_count as f64;
        // Favor new bin if mean residual across open bins is small (they're nearly full).
        score -= 0.4 * mean_residual;
        // If this bin is the only fitting option, opening a new bin is worse than using it.
        if fitting_bins_count == 1 {
            score += 150.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it over opening a new bin.
        score -= 70.0;
    }

    // Mild stream-progression term: later in stream, be slightly more conservative.
    if total_items > 0 {
        score += 5.0 * (step_index as f64 / total_items as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item leaves only tiny dead space afterwards.
    if next_item_size > 0 && post_residual > next_item_size {
        let two_step_waste = post_residual - next_item_size;
        if two_step_waste < 10 {
            score -= (10 - two_step_waste) as f64 * 2.0;
        }
    }
    // Penalize residuals too small for anything (dead space).
    if post_residual < 10 {
        score += 15.0;
    }
    // Penalize post_residual that is below the minimum item size but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Early stream: be more aggressive about opening fresh bins for big items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when item is large or many bins open.
        if item_size > 60 {
            score -= 20.0;
        }
        score -= open_bins_count as f64 * 0.5;
        score += progress * 10.0;
    }

    // Mild penalty for opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 3 {
        score += 12.0;
    }

    // Reward tight fits generally.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good, but a perfect fit is extra-rewarded.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Penalize dead space that is too small for typical future items (1..100).
        // Dead space < next_item_size is nearly unusable for the immediate lookahead.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
        // Dead space larger than the max item size (100) is never truly "dead".
        if post_residual >= 100 {
            score -= 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is generally wasteful,
    // penalize it, but less so when no existing bin fits well.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        // If the item is large relative to capacity, opening a fresh bin is more attractive.
        new_bin_penalty -= 0.15 * item_size as f64;
        // Early in the stream, opening bins is cheaper (more future items to pair with it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty *= 1.0 - 0.4 * progress;
        // If many bins are open and mean residual is large, prefer consolidating instead.
        if open_bins_count > 0 {
            new_bin_penalty *= 1.0 + 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        }
        score += new_bin_penalty;
    }

    // Lookahead synergy: reward placing item here if the next item could fit the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 0.1 * next_item_size as f64;
    }

    // Mild preference for filling fuller bins (best-fit flavor) scaled by stream progress.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Non-linear waste penalty: dead space hurts super-linearly, more so early.
    let waste_curve = norm_post * norm_post * (1.0 - 0.5 * progress);
    score += 40.0 * waste_curve * cap;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item + 1.0) / (post + item + 1.0);
    score -= 30.0 * tightness * tightness;

    // Smooth coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let combo = norm_next * (1.0 - norm_post);
        score -= 25.0 * (0.5 + progress) * (1.0 + combo * 4.0);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize mildly, scaled by progress.
        score += 12.0 * (0.3 + 0.7 * progress) * norm_next * cap * 0.1;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - norm_post * 0.5);
    }

    // Compare against mean residual: bins with residual far below mean are precious.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * (1.0 - progress * 0.5);

    // Many open bins: prefer filling existing ones rather than spreading.
    let openness = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += 8.0 * openness * norm_post;

    // New-bin candidate handling: empty bin gets a smooth adaptive penalty so it
    // only wins when all open fits would create large dead space.
    if bin_residual == bin_capacity {
        let best_possible_waste = norm_post * norm_post;
        score += 35.0 + 60.0 * (1.0 - progress) - 50.0 * best_possible_waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes over capacity 100.
    let pr = post_residual;
    let class = (pr % 10) as f64;

    // Perfect fit: strongly reward.
    if pr == 0 {
        score -= 1000.0;
    }
    // Tiny dead space classes (1..=5): reward tight fits.
    if pr >= 1 && pr <= 5 {
        score -= 60.0 - class * 8.0;
    }
    // Mid classes 6..=15: moderately usable residual.
    if pr >= 6 && pr <= 15 {
        score -= 20.0;
    }
    // Dead zone: residual that no item (>=1) from a small-size stream easily
    // fills, e.g. awkward classes 16..=29 — penalize.
    if pr >= 16 && pr <= 29 {
        score += 15.0 + class;
    }
    // Integer-division thresholds on post_residual (capacity fifths).
    let fifth = bin_capacity / 5;
    if pr >= 4 * fifth {
        score -= 10.0; // leaves 4/5+ capacity: very reusable
    } else if pr >= 3 * fifth {
        score -= 5.0;
    } else if pr >= 2 * fifth {
        score += 5.0;
    } else if pr >= fifth {
        score += 12.0;
    }

    // Harmonic coupling with next item: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size < pr {
            // how well next item divides the leftover space
            let gap = pr - next_item_size;
            if gap <= 10 {
                score -= (20.0 - gap as f64) * 2.0;
            } else {
                score += gap as f64 * 0.3;
            }
        } else {
            // next item cannot use this residual: penalize wasted lookahead fit
            score += 8.0;
        }
    } else {
        // Last item: any residual is pure waste.
        score += 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin fits well. Penalize new bin mildly by default; if the current
    // open-bin fit is poor (large post_residual class), the penalty flips.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 90.0;
        // If stream is early, allow spreading (bins cheap to open).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // If many open bins already, discourage opening more.
        score += open_bins_count as f64 * 3.0;
        // If mean residual is large, open bins are underused — discourage.
        score += mean_residual * 0.5;
    } else {
        // Using an open bin keeps bin count down: reward.
        score -= 25.0;
        // Reward matching residual tightness relative to mean.
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) * 0.6;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; mild penalty for trapping space.
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: make the empty bin moderately attractive only when
    // current bins fit poorly (large post_residual waste or dead space).
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: moderately low, but beaten by tight fits
        // and by last-chance usage of existing bins.
        score = 15.0 + open_bins_count as f64 * 0.3;
        if post_residual == 0 { score = 10.0; } // unreachable but safe
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by base term.

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this placement is a perfect chain — strongly reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: partial reward proportional to how well
            // it would fill the remaining space.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill_ratio;
        } else {
            // Next item cannot use the leftover: penalize dead space,
            // scaled by how much of the bin becomes unusable.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 25.0 * waste;
        }
    }

    // Compare post_residual against mean residual: leaving less than average
    // is good (concentrating waste), leaving more than average is bad.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // unless the item is large and would fragment an open bin badly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let frag = item_size as f64 / bin_capacity as f64;
        if frag < 0.5 && next_item_size > 0 && next_item_size > post_residual {
            // Large item into fresh bin wastes most of it; discourage.
            score += 15.0;
        } else {
            // Mild default penalty so open bins are preferred on ties.
            score += 5.0;
        }
    }

    // Slight late-stream conservatism: as the stream progresses, prefer
    // consolidating into existing bins to reduce tail waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose residual is consumed well.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 24.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space: post_residual that is small but
    // cannot host typical small items (below 10) is worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin should only win when no
    // open bin offers a decent fit. Base cost of a fresh bin:
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, having bins open is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If open bins are already congested (low mean residual), a new bin
        // is more attractive.
        score -= 0.3 * (bin_capacity as f64 - mean_residual).max(0.0);
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Prefer filling already-open bins: mild pressure proportional to how
    // many bins are open (encourages consolidation).
    if bin_residual != bin_capacity {
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
        // Bins below mean residual are "behind" — filling them balances state.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Time horizon: late in the stream, waste matters more since fewer
    // chances remain to recover dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);

    // Base: prefer tight fits (low post_residual), with non-linear shrink
    let mut score = post * (1.0 + 0.6 * progress * (1.0 - post / cap));

    // Penalize large dead space superlinearly (wasted capacity matters more late)
    let waste_frac = post / cap;
    score += 12.0 * waste_frac * waste_frac * (0.5 + progress);

    // Reward bins that are nearly full (post_residual small) with a smooth bonus
    score -= 8.0 * (-post / 8.0).exp();

    // Lookahead: if next item fits the post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (1.0 - post / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty proportional to open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate handling: make an empty bin mildly unattractive early,
    // but acceptable when remaining bins have poor residuals
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - post).max(0.0);
        score += 4.0 + 0.3 * open_bins_count as f64 - 0.5 * mean_gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" small-grain classes
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let class = pr / 10; // integer division class: 0..10
    let class_bonus = match class {
        0 => -14.0,           // near-perfect fill
        1 => -10.0,
        2 => -7.0,
        3 => -4.0,
        4 => -1.5,
        5 => 1.0,             // half-full residual: mediocre
        6 => 2.5,
        7 => 4.0,
        8 => 6.0,
        9 => 8.0,
        _ => 0.0,
    };
    score += class_bonus;

    // Modulo harmonic coupling: residuals divisible by common item grains (10/20/25) are reusable
    if pr % 10 == 0 && pr > 0 { score -= 3.0; }
    if pr % 20 == 0 && pr > 0 { score -= 2.0; }
    if pr % 25 == 0 && pr > 0 { score -= 2.0; }

    // Lookahead: penalize if next item cannot fit the post residual (dead space risk)
    if next_item_size > 0 {
        if next_item_size > pr {
            score += 5.0 + (next_item_size - pr) as f64 * 0.15;
        } else {
            // reward if next item exactly fills or nearly fills post residual
            let gap = pr - next_item_size;
            if gap == 0 { score -= 12.0; }
            else if gap <= 5 { score -= 6.0; }
            else if gap <= 10 { score -= 3.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 18.0 - (post_residual as f64 - cap * 0.5).abs() * 0.0;
        // allow opening a new bin late in the stream if many bins open and residual mean is high
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 6.0 + open_bins_count as f64 * 0.3;
        if mean_residual > 60.0 { score -= 4.0; }
    }

    // Tight-fit reward: small absolute waste relative to item size
    let waste_ratio = post_residual as f64 / cap;
    score -= (1.0 - waste_ratio) * 4.0;

    // Penalize creating tiny unusable slivers (< min plausible item size 10)
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Mild dispersion penalty: prefer bins deviating from mean residual (keeps spread balanced)
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    // Progress-scaled tightness pressure: later in stream, prefer tighter fits harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += waste_ratio * progress * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0 * (20 - post_residual) as f64 / 10.0;
    }

    // Reward tight fits (post_residual near zero but not tiny dead gap).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Exact fit of next item into post residual is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot fit here; slight penalty if dead space would remain
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    } else {
        // New bin candidate: penalize mildly unless current bins fit poorly.
        if fitting_bins_count > 0 {
            score += 15.0 + 2.0 * open_bins_count as f64;
        }
        // Favor new bin early when mean residual is large (fragmented bins).
        if mean_residual > item_size as f64 * 1.5 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to item size (minimize waste).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 30.0 - (leftover as f64).min(30.0) * 0.5;
        if leftover == 0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Dead space the next item cannot use — penalize.
        score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.6;
    }

    // Prefer bins below mean residual (consolidate waste).
    score += ((post_residual as f64) - mean_residual).max(0.0) * 0.3;
    score -= ((post_residual as f64) - mean_residual).min(0.0).abs() * 0.1;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // New-bin candidate: prefer only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Early stream: slightly discourage opening many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space quadratically: residuals too small for typical items are waste.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.08 * dead * dead / (bin_capacity as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.5 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    // (leaves a useful residual) or existing fits are loose.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 >= 0.6 * bin_capacity as f64;
        let mut penalty = 30.0;
        if large_item {
            penalty -= 20.0;
        }
        // If the next item could pair with this item's residual, opening a fresh bin is good.
        if next_item_size > 0 && post_residual > 0 {
            let pairing = (post_residual as i64 - next_item_size as i64).abs() as f64;
            if pairing <= 5.0 {
                penalty -= 18.0;
            }
        }
        // Late in the stream, prefer closing existing bins rather than spawning new ones.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty += 10.0 * progress;
        score += penalty;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward moderately when next item still fits, scaled by snugness.
        let snug = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
        score -= 6.0 * snug;
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling
    // existing bins over spreading waste.
    if open_bins_count > 2 {
        let waste_pressure = mean_residual / (bin_capacity as f64);
        score += 4.0 * waste_pressure * (open_bins_count as f64).ln();
    }

    // Mild preference for bins already below mean residual (balance residuals).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic waste penalty, amplified as stream progresses.
    let mut score = post * (1.0 + 1.5 * progress) + 40.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual) non-linearly.
    score -= 25.0 * (1.0 - norm_post).powi(6);

    // Penalize creating residuals that cannot host the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            score += 8.0 + 12.0 * (nx - post) / cap;
        } else {
            score -= 5.0 * (1.0 - ((post - nx) / cap).min(1.0));
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate handling: only attractive when few fitting bins or large item.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score = 60.0 + 20.0 * progress - 45.0 * scarcity * norm_item
            - 10.0 * (1.0 - (mean_residual / cap).min(1.0));
    } else {
        // Mildly prefer bins whose residual deviates favorably from mean.
        score += 3.0 * (post - mean_residual) / cap;
    }

    // Small open-bin consolidation bonus to limit bin sprawl.
    score -= 2.0 / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by integer
    // division into coarse "harmonics" of the capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let harmonic = (post / cap * 8.0).floor(); // 0..8 class of leftover fraction

    // Perfect fits and tiny leftovers are excellent: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + post;
    } else if post_residual <= 15 {
        score -= 80.0 + (15.0 - post) * 4.0;
    }

    // Harmonic-class penalty: leftovers that are "dead" (too small for typical
    // items but too large to ignore) are penalized super-linearly.
    if post_residual > 15 {
        let dead = (post - 15.0) / cap;
        score += dead * dead * 300.0;
    }

    // Coupling with lookahead: if the next item can exactly use this leftover,
    // reward heavily; if leftover is just barely too small for next item,
    // penalize (near-miss dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            score -= (nxt / post) * 60.0;
        } else {
            let miss = (nxt - post) / cap;
            score += miss * 250.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless this bin is hopeless
    // (very tight fit already handled above) or many bins are open with
    // high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let frag = (mean_residual / cap - 0.5).max(0.0);
        score = 55.0 + frag * 120.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
        if post_residual == 0 { score -= 1000.0; }
    }

    // Mild preference for bins with residual close to item (tight packing),
    // modulated by harmonic class so tight classes dominate.
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * (10.0 + harmonic * 2.0);

    // Small penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item are "unusable" and cost extra.
    let min_gap = 10u32;
    if post_residual > 0 && post_residual < min_gap {
        score += 40.0;
    } else if post_residual < min_gap {
        // perfect fit: zero residual
        score -= 25.0;
    }

    // Non-linear penalty on small-but-nonzero post residuals
    // (gap of 1..=9 is dead space; gap >= 10 may still fit future items).
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // If next item exactly fills the residual, strongly prefer.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with below-mean residual (tighter bins get filled first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference for filling nearly-full bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (0.5 + progress);

    // New-bin candidate: make it moderately expensive so it is chosen only
    // when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (6 - post_residual) as f64 * 20.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this placement is excellent (chain of perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let rem2 = post_residual - next_item_size;
            if rem2 <= 10 {
                score -= 100.0 - rem2 as f64 * 5.0;
            }
            score -= (rem2 as f64).sqrt() * 10.0;
        } else {
            // Next item cannot use the residual: penalize proportional dead space.
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 2.0;
        }
    }

    // Prefer bins whose residual is already small relative to the mean
    // (consolidate fragments rather than spreading across many bins).
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += (rel - 1.0) * 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it instead of opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // offers a decent fit (post_residual small means good fit; large residual
    // left after placement means a fresh bin is preferable).
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Mild pressure to keep the number of open bins low.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit: reward tight fits.
    score -= (bin_residual as f64 - post_residual as f64) * 0.5;
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Penalize small dead space that nothing can use (items >= 1).
    if post_residual > 0 {
        score += (post_residual as f64 / 10.0).min(6.0);
    }
    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use the leftover; penalize wasted space proportionally.
            score += 5.0;
        }
    }

    // Global state: many open bins with slack -> prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += crowding * 0.3;

    // Prefer bins below mean residual (consolidating slack).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // in the stream or when no good fit exists (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * 20.0;
        // Penalize new bin when existing bins fit well (post_residual small on others),
        // approximated via mean residual being large.
        score = (bin_capacity as f64) * 0.9 - early_bonus - (mean_residual / 20.0);
        // If the only alternative is a bad fit, make new bin less bad.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Late in stream: consolidate hard, avoid opening bins.
    score += progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - (pr / cap).powf(2.0);
    score -= tightness * (20.0 + 60.0 * progress * progress);

    // Penalize large post_residual quadratically, scaled by progress
    score += (pr / cap).powi(3) * 50.0 * (0.5 + progress);

    // Lookahead coupling: reward residual that can hold the next item smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let compat = 1.0 - ((pr - ns).abs() / cap);
        score -= compat.max(0.0) * compat.max(0.0) * 25.0;
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild preference to keep mean residual high across open bins
    score -= (mean_residual / cap) * 8.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes and integer division tiers
    let post = post_residual as u32;
    let class = post % 10;
    let tier = post / 25; // 0..4 tiers

    // Dead-space penalty: residuals that are awkward (small but nonzero)
    if post > 0 && post < 10 {
        score += (10 - post) as f64 * 3.0;
    }
    // Favor exact / near-exact fills
    if post == 0 {
        score -= 50.0;
    } else if class == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // reward proportionally to how well next item uses leftover
            let fill = next_item_size as f64 / post as f64;
            score -= 15.0 * fill;
            if next_item_size == post {
                score -= 30.0; // perfect two-item chain
            }
        } else {
            // next item won't fit here; penalize by wasted capacity fraction
            score += (next_item_size - post) as f64 * 0.5;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, keep it attractive
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing
    // residuals are genuinely unusable
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if no open bin fits, opening is necessary
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, opening new bins is more acceptable
        score -= (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Prefer using bins below mean residual (tighter bins first)
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Tier coupling: mid-tier residuals (25-50) are the most reusable
    score -= match tier {
        1 => 6.0,
        2 => 4.0,
        3 => 2.0,
        _ => 0.0,
    };

    // Many open bins: encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (unusable by typical items)
    // are heavily penalized, while large usable residuals are fine.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 10.0 {
            // tiny dead sliver -> strongly penalize
            score += (10.0 - pr) * 6.0;
        } else if pr < 25.0 {
            // awkward gap zone -> moderate penalty
            score += (25.0 - pr) * 2.5;
        } else {
            // large residual is potentially reusable -> slight reward
            score -= (pr - 25.0) * 0.3;
        }
    } else {
        // perfect fit: big reward
        score -= 40.0;
    }

    // Reward tight packing: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Encourage using bins whose residual is close to the item (good fit).
    let fit_tightness = (bin_residual as f64 - item_size as f64).abs();
    score += fit_tightness * 0.4;

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit (post_residual here is large).
    if bin_residual == bin_capacity {
        // neutral baseline plus mild penalty so only genuinely bad fits
        // among open bins lose to it.
        score += 12.0;
        // if next item is large, a fresh bin is more valuable
        if next_item_size > 60 {
            score -= 8.0;
        }
    }

    // Lookahead: if this placement leaves room for the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // extra reward for an exact follow-up fit
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover too small for the known next item -> penalize
        score += (next_item_size as f64 - pr) * 1.5;
    }

    // Mean residual coupling: if this bin's residual is far below average,
    // it's a "straggler" bin; prefer closing it out.
    let res_diff = mean_residual - bin_residual as f64;
    if res_diff > 0.0 {
        score -= res_diff * 0.2;
    }

    // Early stream: be slightly more willing to open bins (long horizon ahead).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post residual is good.
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Aggressive 2-step lookahead: reward when next item fits exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            // Perfect match: next item exactly fills this bin afterwards.
            score -= 30.0;
        } else if (post_residual as f64) >= nxt {
            // Next item can still fit here: chain two placements.
            score -= 8.0 + (nxt / bin_capacity as f64) * 10.0;
        } else {
            // Dead space relative to the next item: penalize proportionally.
            let gap = nxt - post_residual as f64;
            score += gap * 0.25;
        }
    }

    // Compare against mean residual across open bins: prefer bins with less residual (fuller bins).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in an open bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no open bin fits well.
        if fitting_bins_count > 0 {
            score += 20.0;
        } else {
            score -= 5.0;
        }
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Small penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward mid-range residuals that few future items can use.
    let dead = (post_residual as f64) * (1.0 - ((post_residual as f64) / bin_capacity as f64));
    score += 0.35 * dead;

    // Lookahead: if the next item fits the post-residual exactly-ish, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is costly unless nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64 / 8.0).min(2.0);
        score += 30.0 * scarcity + 15.0 * crowded + 10.0 * (1.0 - progress);
        // If next item is large and this bin's post-residual can't help, new bin is fine.
        if next_item_size > post_residual && post_residual < 10 {
            score -= 20.0;
        }
    } else {
        // Favor bins whose residual deviates favorably from the mean (consolidation).
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.15 * dev;
        // Mild bonus for reducing the number of very fragmented bins.
        score -= 2.0;
    }

    // Late-stream pressure: prefer compacting into fewer bins as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: wasted space, superlinear penalty (quadratic coupling)
    let mut score = pr + 0.35 * (pr * pr / cap);

    // Tightness reward: smooth bell around perfect fit
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness;

    // Stream progress coupling: late in stream, tighten more aggressively
    score -= progress * 6.0 * tightness;

    // Dead-space penalty: post_residual too small to ever be useful (min item size 1, but small slivers waste)
    let sliver = (pr - 1.0).max(0.0);
    score += 0.02 * sliver * sliver / cap;

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= 8.0 * fit_next * (1.0 - (pr - nx) / cap).max(0.0);
        // Penalize leaving residual that next item almost-but-not-quite fits (frustration)
        let near_miss = ((pr - nx) / cap).max(0.0);
        if pr < nx && near_miss < 0.15 {
            score += 6.0 * (1.0 - near_miss / 0.15);
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual deviation: prefer bins whose residual is below average (fill fuller bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev;

    // New-bin candidate: penalize mildly so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 18.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions
    let frac = post_residual as f64 / cap_f; // fraction of bin wasted
    let class = (frac * 8.0).floor() as i64; // 8 harmonic classes of dead space

    // Reward tight fits (small post_residual class)
    score -= 12.0 * (1.0 - frac * frac);

    // Penalize mid-range dead space that nothing (min size 1) can still use well:
    // post_residual in [1..=10] is a "sweet spot" leftover; [11..=30] is dead zone
    if post_residual >= 11 && post_residual <= 30 {
        score += 18.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Modulo arithmetic on post_residual: leftovers divisible by common item
    // sizes (5,10,20,25,50) are more likely reusable by future items
    let reusable = |r: u32| r > 0 && (r % 5 == 0 || r % 25 == 0);
    if reusable(post_residual) {
        score -= 6.0 + (post_residual % 10) as f64;
    } else if post_residual > 0 && post_residual % 7 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            // harmonic class of the double-lookahead leftover
            let frac2 = post2 as f64 / cap_f;
            score -= 15.0 * (1.0 - frac2);
            if post2 == 0 {
                score -= 20.0;
            }
            if post2 >= 11 && post2 <= 30 {
                score += 8.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 4.0 + ((next_item_size - post_residual) as f64).sqrt();
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item_size)
    // on average; only prefer it when all open bins would leave bad leftovers.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // cheaper if item is large (little waste) or stream is early
        score -= 0.35 * item_size as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // if many open bins with large mean residual, prefer spreading load
        if open_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score -= 12.0;
        }
    } else {
        // mild preference for using existing bins as stream progresses
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
        // reward bins whose residual is harmonically aligned with item size
        if bin_residual % 10 == item_size % 10 {
            score -= 3.0;
        }
    }

    // Tie-break with mean residual: prefer bins below mean (keep big holes open)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for typical upcoming items are dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - waste_ratio);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }
    // Many fitting bins: slight penalty to prefer the best fit among them.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 1.5 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += 0.3 * post_residual as f64;
        }
    }

    // Mean-residual coupling: bins far below the mean residual are less attractive.
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild progression term: later in the stream, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * waste_ratio;

    // New-bin candidate must lose unless all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        score += gap as f64 * 0.5;
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Dead space too small for next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 30.0;
        }
    }

    // Penalize post_residual far below mean residual (wasteful fragmentation)
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are bad
    if bin_residual == bin_capacity {
        score += 40.0;
        // But open new bin if item is large and fits poorly elsewhere
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild pressure to fill bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    let tightness = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0;
    } else if tightness < 0.10 {
        score -= 25.0;
    } else {
        // penalize dead space superlinearly
        score += tightness * tightness * 40.0;
    }

    // Lookahead: reward if the next item can still fit in the leftover space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // exact chain fit bonus
            if post_residual - next_item_size == 0 {
                score -= 12.0;
            }
        } else {
            // leftover too small for next item: mild penalty proportional to waste
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // A fresh bin is attractive for big items or when alternatives are poor.
        score += 35.0 - 30.0 * fill_frac;
        if next_item_size > 0 && next_item_size <= post_residual - item_size.max(0) {
            score -= 8.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    } else {
        // Reward reusing existing bins, more so when many are open.
        score -= 6.0;
        if open_bins_count > 4 {
            score -= 4.0;
        }
    }

    // Global state coupling: prefer bins whose residual is above the mean
    // (keep low-residual bins for small future items).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.10 * diff;
    }

    // Mild time-horizon shaping: early stream, be conservative with tight fits
    // to preserve flexibility; late stream, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (100.0 - post_residual as f64) * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize key quantities into [0,1]-ish scales.
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post_residual as f64 / cap;                 // dead space fraction after placement
    let fit_norm = post_residual as f64 / (cap as f64);          // same scale for coupling
    let fill = 1.0 - post_norm;                                  // how full the bin becomes

    // Smooth non-linear penalty on dead space: quadratic coupling with stream progress.
    // Later in the stream, wasted residual is costlier (less chance to fill it).
    score += 40.0 * post_norm * post_norm * (0.5 + progress);

    // Reward tight fits: cubic in fill, stronger late in the stream.
    score -= 30.0 * fill * fill * fill * (0.4 + 0.6 * progress);

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement; if it almost fits, mild reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            let match_quality = 1.0 - (gap / cap);
            score -= 25.0 * match_quality * match_quality;
        } else {
            // Next item cannot use this residual: slight penalty proportional to leftover.
            score += 6.0 * post_norm;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - post_norm);
    }

    // Penalize spreading across many open bins mildly; encourage consolidation
    // into bins already below mean residual (tighter bins).
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.05 * mean_gap * (1.0 + progress);

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a good fit. Base penalty decays as the stream progresses (early on,
    // opening bins is cheaper since there is more time to fill them).
    if bin_residual == bin_capacity {
        let base = 35.0 * (1.0 - 0.5 * progress);
        score += base;
        // If item is large relative to capacity, opening a fresh bin is more attractive.
        score -= 0.2 * item_size as f64 * (1.0 - progress);
    }

    // Small smooth regularization coupling open bins count and progress to avoid
    // unbounded bin proliferation late in the stream.
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress) * (1.0 + fit_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residuals into capacity-fraction bands
    let quarter = bin_capacity / 4;
    let band = post_residual / quarter; // 0..=4 harmonic class

    // Reward tight fits: post_residual in low bands is good
    score -= match band {
        0 => 30.0,
        1 => 15.0,
        2 => 5.0,
        3 => 0.0,
        _ => -5.0, // nearly empty bin used: small bonus
    };

    // Modulo arithmetic on post_residual: residual divisible by small numbers
    // is more "usable" for typical item sizes
    if post_residual > 0 {
        let mut usability = 0.0;
        for m in [5u32, 10, 20, 25, 50].iter() {
            if post_residual % m == 0 {
                usability += 4.0;
            }
        }
        score -= usability;
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Dead space penalty: post_residual too small for the minimum item (1)
    // but too small for typical items is wasted; penalize residuals in [1, 9]
    if post_residual >= 1 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does next_item_size fit the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit is valuable, more so the tighter the chain
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 + 25.0 * chain_tightness;
            // harmonic class of next item: large items (>50) harder to place later
            if next_item_size > 50 {
                score -= 10.0;
            }
        } else {
            // next item cannot chain here; penalize leftover that nothing can use
            score += 8.0;
            if post_residual < next_item_size && post_residual > 0 {
                score += (next_item_size - post_residual) as f64 * 0.1;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current fit is bad. Penalize the fresh bin moderately so good fits win.
    if bin_residual == bin_capacity {
        score += 35.0;
        // late in stream, opening bins is cheaper (fewer future regrets)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // if next item is large, a fresh bin is more attractive
        if next_item_size > 60 {
            score -= 12.0;
        }
    }

    // Many open bins with high mean residual: prefer consolidating into bins
    // whose residual is below mean (tighter bins) to close them out
    if open_bins_count > 1 {
        let dev = mean_residual - post_residual as f64;
        score += 0.15 * dev;
        // pressure to close bins when too many are open
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Integer division threshold: residual that could hold a "half-bin" item
    if post_residual >= bin_capacity / 2 {
        score += 5.0; // leaving half a bin is somewhat wasteful vs. tight fit
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize "dead space": small leftover gaps that few future items can use.
    let dead_threshold = 10.0 + 0.15 * (item_size as f64);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 + 4.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 25.0 * tightness;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // Next item won't fit here: the leftover becomes dead space unless large.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(80.0);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when current bins
    // fit poorly (large post_residual) or too many bins are already open with waste.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: residual after placement = capacity - item_size.
        // Penalize slightly so we only open when existing bins are worse.
        score += 40.0;
        // Pressure: with many open bins, discourage opening more unless necessary.
        score += 3.0 * (open_bins_count as f64).sqrt();
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 80.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (minimize fragmentation).
        let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 50.0 * waste_ratio;
    }

    // Mean residual coupling: when open bins are generally full (low mean residual),
    // conserve them; when they are loose, prefer filling loose bins.
    if bin_residual != bin_capacity {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * deviation;
        if (bin_residual as f64) < mean_residual {
            score -= 10.0; // tighter-than-average bin: good target
        }
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, with a mild superlinear penalty.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 2.0);

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size exactly,
    // penalize when the leftover is "almost but not exactly" usable by the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff < 0.5 {
            // Perfect chaining: this bin will be exactly consumed next step.
            score -= 40.0;
        } else if pr >= nxt {
            // Next item fits, but leaves more waste; scale penalty with mismatch.
            score -= 15.0 - diff.min(30.0);
        } else {
            // Next item will NOT fit in the leftover: dead space risk.
            score += (nxt - pr) * 0.8;
        }
        // If nothing fits the lookahead at all, slightly favor conserving big bins.
        if pr < nxt && pr >= item_size as f64 * 0.0 {
            score += 2.0;
        }
    }

    // Relative-to-mean-residual coupling: penalize bins whose leftover deviates badly
    // from the fleet average (outliers create fragmentation).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open fits are terrible.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; exact/near-exact fits in open bins will beat this.
        score = bin_capacity as f64 * 0.9;
        if next_item_size > 0 && (next_item_size as f64 - bin_capacity as f64).abs() < 1.0 {
            score -= 50.0; // opening fresh bin perfect for next item
        }
        // Early in the stream, opening bins is cheap and builds diversity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild pressure to consolidate when too many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize large dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect closure is excellent
    }
    if post_residual > 50 {
        score += 8.0 * ((post_residual as f64 - 50.0) / 50.0); // large awkward gaps
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the residual; mild penalty proportional to waste
            score += 5.0 * (1.0 - post_residual as f64 / (next_item_size as f64 + 1.0)).max(0.0);
        }
    }

    // New-bin candidate logic: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; discounted when many items remain.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score = 55.0 + 40.0 * (1.0 - progress);
        // If current best-fit residual in open bins is large (mean_residual high),
        // opening a fresh bin is less attractive.
        score += 0.15 * mean_residual;
        // If the item is large relative to capacity, prefer a fresh bin less often.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 10.0;
        }
        // Many open bins: discourage spreading further.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Slight global pressure: when many bins are open, prefer consolidating
        // into existing bins (any existing-bin candidate already beats new-bin base).
        score += 0.02 * open_bins_count as f64;
        // Time horizon: early in the stream, be choosy (tight fits matter more);
        // late in the stream, just close bins out.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 10.0 * progress * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear penalty on wasted residual (quadratic coupling, normalized by capacity)
    let pr_norm = pr / cap;
    score += 8.0 * pr_norm * pr_norm * cap;

    // Reward tight fits: small post_residual gets a strong bonus
    score -= 6.0 * (1.0 - pr_norm).powi(3) * (item_size as f64 / cap);

    // Dead-space penalty if the next item cannot use the leftover space
    if next_item_size > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            score += 4.0 * pr_norm * (1.0 + progress);
        } else {
            // bonus if next item fits exactly-ish into the remaining space
            let gap = ((post_residual as i64 - next_item_size as i64).abs()) as f64 / cap;
            score -= 3.0 * (1.0 - gap).powi(2);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 + progress);
    }

    // When many bins are open, prefer filling existing ones (avoid bin proliferation)
    score += (open_bins_count as f64).ln().max(0.0) * pr_norm * 2.0;

    // Slight preference for bins whose residual is close to the mean residual (balance)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 1.5;

    // New-bin candidate: keep it competitive only when the item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = 0.5 * cap + 10.0 * (1.0 - fill) - 8.0 * fill * (1.0 + 2.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 10 defines "dead-space quality"
    let post = post_residual;
    let residue = post % 10;
    // Residuals that are multiples of 10 are more reusable -> reward
    if residue == 0 {
        score -= 6.0;
    } else if residue <= 2 {
        score += 4.0; // tiny slivers are nearly dead space
    } else if residue >= 8 {
        score -= 2.0; // close to a clean class
    }

    // Integer-division thresholds: how many items of size 10 could still fit
    let slots = post / 10;
    score -= slots as f64 * 1.5;

    // Reward tight fits (small post_residual) more aggressively
    if post <= 5 {
        score -= 15.0;
    } else if post <= 15 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits into post_residual, this placement chains well
    if next_item_size > 0 && next_item_size <= post {
        score -= 8.0;
        // Perfect chain: post_residual % next_item_size == 0
        if post % next_item_size == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover -> leftover riskier
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize spreading when many bins are open and mean residual is high
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).sqrt() * 0.8;
    score -= (mean_residual - post as f64).abs() * 0.05;

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin would leave a bad harmonic class AND few bins fit the item.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        let mut new_bin_score = 100.0 - (item_size as f64);
        if fitting_bins_count == 0 {
            new_bin_score -= 30.0; // forced
        }
        if next_item_size > 0 && next_item_size <= post {
            new_bin_score += 5.0;
        }
        if residue == 0 && post >= next_item_size && next_item_size > 0 {
            new_bin_score += 10.0; // existing bin chains nicely, don't open new
        }
        // Late in stream, prefer consolidating
        new_bin_score += progress * 10.0;
        score = score.max(0.0) + new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Penalty on residual scaled by how far below mean residual this bin sits:
    // prefer bins already "worse off" so better bins stay flexible.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.15;

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few are open, mildly encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.6 * (1.0 - progress);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 0.3;
        if fitting_bins_count == 1 {
            score -= 20.0; // opening a bin is fine if the only alternative is last-chance misuse
        }
        if item_size > 60 {
            score -= 10.0; // large items fit best in fresh bins
        }
    }

    // Lookahead coupling: keep residual that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 3.0; // leftover that can't host next item is dead weight
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 40.0; // exact 2-step chain match
        }
        // Penalize residuals too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Tight fit reward relative to capacity.
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    // Compare against mean residual: avoid leaving this bin far below average usable space.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin pairs well with big next item
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (bin_capacity as f64) * 0.5;

    // Penalize dead space: post_residual that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if post_residual >= next_item_size {
            // reward bins that remain usable for the lookahead item
            score -= 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when other bins can fit the item
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64) * 2.0;
        score += 40.0 + open_pressure * (1.0 - progress);
        // but allow new bin if post_residual would be a perfect slot for next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild penalty when this bin's residual deviates far from the mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Prefer filling bins with larger residuals when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count.min(20) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late in the stream, tight fits are prized.
    let tightness = post / cap;
    let coupling = tightness * (1.0 + 2.5 * progress * progress);
    score += 4.0 * coupling * cap * 0.25;

    // Reward bins whose residual matches the item size closely (smooth term).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Lookahead: bonus if next item can use the post residual exactly-ish.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let norm_gap = gap / cap;
        score += 2.0 * norm_gap * norm_gap * cap;
        if next_item_size as f64 <= post {
            score -= 3.0 * (1.0 - norm_gap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when plenty of bins fit the item.
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * fitting_bins_count as f64;
        // Late in the stream, opening new bins is more wasteful.
        score += 20.0 * progress;
    } else {
        // Slight preference for bins with larger residual (keep small holes consolidated).
        score -= 0.5 * (bin_residual as f64 / cap);
    }

    // Mild penalty if this bin's residual deviates from the mean residual
    // (encourages balanced residual distribution).
    score += 0.3 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class of post_residual: divisible-by-10 residuals are "usable" slots
    let pr = post_residual;
    if pr > 0 {
        let harmonic = match pr % 10 {
            0 => 0.0,
            5 => 0.5,
            _ => 1.5,
        };
        score += harmonic * 8.0;

        // Dead-space penalty: residual too small for typical items
        if pr < 10 {
            score += 60.0;
        } else if pr < 20 {
            score += 20.0;
        }

        // Integer-division threshold: does next item fit in the post residual?
        if next_item_size > 0 {
            if next_item_size <= pr {
                score -= 25.0 + (pr - next_item_size) as f64;
            } else {
                // next item cannot follow here; penalize more if gap is small (wasted)
                let gap = (next_item_size - pr) as f64;
                if gap <= 15.0 {
                    score += 30.0;
                }
            }
        }

        // Pairing bonus: post_residual + next_item_size exactly fills capacity
        if next_item_size > 0 && pr + next_item_size == bin_capacity {
            score -= 80.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.4 + open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Tightness coupling: reward leaving small-but-usable residual
    let tight = (post_residual as f64 / cap).powi(2);
    score += tight * 15.0;

    // Slight preference to balance load across bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical items
    // (below minimum item size 1 and below a practical threshold ~10) are wasted.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Post residual is unusable dead space: heavy penalty proportional to waste.
        score += 3.0 * (dead_threshold - post_residual as f64);
        // Extra penalty if it's not even zero (perfect fit avoided waste).
        score += 5.0;
    }

    // Reward near-perfect fills (post_residual very small but usable).
    if post_residual > 0 && post_residual <= 5 {
        score -= 8.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: when many bins are open, prefer consolidating
    // into existing bins; opening new bins becomes less attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and stream progress.
        score += 20.0 + 6.0 * open_pressure + 10.0 * progress;
        // But if no open bin fits well (this is the only fitting candidate and
        // residuals elsewhere are large), soften the penalty.
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
        // If mean residual is high, existing bins are roomy: keep penalizing new bin.
        score += 0.05 * mean_residual;
    } else {
        // Existing bin: mild reward scaled by how much better than mean it fits.
        score -= 0.03 * (mean_residual - bin_residual as f64).max(0.0);
        // Small penalty for leaving a gap that next item could have used.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && (bin_residual as u32) >= next_item_size {
            score += 4.0;
        }
        // Encourage using bins that can still host the lookahead item after placement.
        if next_item_size > 0 && post_residual >= next_item_size as u32 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect match: next item exactly fills this bin. Strongly reward.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here; reward closeness of the match.
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + gap);
        } else {
            // Next item won't fit here: the leftover is likely dead space.
            let excess = (next_item_size - post_residual) as f64;
            score += 0.8 * excess;
        }
    } else {
        // Last item: just minimize leftover.
        score += 5.0;
    }

    // --- Penalize tiny unusable residuals (dead space) ---
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // --- Relative-to-mean coupling ---
    // Prefer bins whose residual is below average (tighter bins), which
    // consolidates packing; penalize filling already-tight bins badly.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 {
        // This is the only bin that can fit the item; avoid opening a new bin.
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: be pickier about wasted space.
        score += 0.1 * (fitting_bins_count as f64);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual space of all open bins.
        // Cost grows with number of open bins and their average slack.
        let mut new_bin_score = 100.0 + 12.0 * open_bins_count as f64 + 0.4 * mean_residual;
        // Early in the stream, opening bins is cheap and often good.
        new_bin_score -= 50.0 * (1.0 - progress);
        // If next item is large and no bin can hold both, a fresh bin is attractive.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            new_bin_score -= 45.0;
        }
        // Only attractive if the best existing fit would leave big dead space.
        if post_residual > 0 && (post_residual as f64) < 0.2 * mean_residual {
            new_bin_score += 20.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residual too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mild reward proportional to how well it uses the leftover
        let use_ratio = next_item_size as f64 / post_residual as f64;
        score -= 4.0 * use_ratio;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover too small for next item: penalize wasted space
        score += 2.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Prefer bins with residual close to mean (balance load across bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early in stream: be conservative, keep bins flexible (penalize very tight packing)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 && post_residual > 0 && post_residual < item_size {
        score += 3.0;
    }

    // Many open bins: encourage closing out nearly-full bins to reduce active count
    if open_bins_count > 4 {
        score -= 0.3 * (open_bins_count as f64).ln() * tightness;
    }

    // New-bin candidate: only attractive when no good alternative exists
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so when other bins fit the item
        score += 10.0 + 3.0 * fitting_bins_count as f64;
        // But if this is a large item and open bins would leave huge waste, allow it
        let best_case_waste = if fitting_bins_count > 0 { item_size as f64 * 0.05 } else { 0.0 };
        score -= best_case_waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let fit = item_size as f64 / cap;
    let nx = next_item_size as f64 / cap;
    let mean_r = mean_residual / cap;

    let mut score = prn;

    // Smooth polynomial coupling: tight fits are better, more so early in the stream
    let tightness = 1.0 - prn * prn; // high when post_residual small
    score -= tightness * (1.5 + 2.0 * progress);

    // Penalize large dead space non-linearly, amplified late in stream
    score += 0.8 * prn * prn * prn * (0.5 + progress);

    // Lookahead: reward residual that can hold next item (smooth gate)
    let can_next = (prn - nx).max(0.0);
    score -= 0.6 * can_next * (1.0 - progress);

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 + fit);
    }

    // Mild penalty if this bin is much worse than average residual (fragmentation)
    score += 0.3 * (mean_r - prn).max(0.0);

    // Discard hoarding many open bins; slight pressure to fill existing bins
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * prn;

    // New-bin candidate: smooth preference early, discourage late
    if bin_residual == bin_capacity {
        score -= 0.5 * (1.0 - progress) - 0.4 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left after placement

    // Penalize residuals that fall into "dead zones": too small to be useful
    // for typical items (1..100 interface). Items <= post_residual can still fit,
    // so usefulness ~ fraction of the item range that fits.
    let usable = post / 100.0; // max item size is 100
    if usable < 0.15 {
        score += 18.0 * (0.15 - usable) / 0.15; // strong penalty near-dead space
    } else {
        score -= 4.0 * usable; // reward leaving roomy residuals
    }

    // Modulo harmonic classes: residuals that are multiples of common item
    // sizes (e.g., 10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 2.5; }
        if pr % 20 == 0 { bonus += 1.5; }
        if pr % 25 == 0 { bonus += 1.5; }
        if pr % 50 == 0 { bonus += 2.0; }
        score -= bonus;
    } else {
        score -= 6.0; // perfect fill is excellent
    }

    // Integer-division threshold on post_residual vs next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Can host the next item: great, especially exact/near-exact fits.
            let slack = post_residual - next_item_size;
            score -= 5.0;
            score -= (slack as f64).min(10.0) * 0.3;
        } else {
            // Next item won't fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (mean_residual / cap).max(0.01);
        let pressure = (mean_residual / cap - frac).max(0.0);
        // Base cost of a new bin, discounted by stream progress and crowding.
        score += 30.0 - 10.0 * progress - pressure * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0; // fresh bin guarantees next-item capacity
        }
        let _ = crowding;
    }

    // Slight reward for keeping the number of open bins from exploding.
    if !is_new {
        score -= (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Mild tie-break noise-free harmonic jitter on item class.
    let item_class = (item_size / 10) % 4;
    score -= item_class as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Pressure from number of open bins: prefer filling existing bins when many are open
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins with residual close to mean residual (keeps balance)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.3;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item almost fits but not quite, mild penalty for leaving a tempting gap
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // New-bin candidate: only attractive when few bins open or residual would be huge waste
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 2.0;
        score += 15.0 + pressure;
        if fitting_bins_count == 1 {
            score -= 30.0; // allow opening when no good alternative exists
        }
        if item_size >= 80 {
            score -= 10.0;
        }
    }

    // Progression: slightly more tolerant of imperfect fits late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits tightly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize proportionally to wasted potential
    if next_item_size > 0 && next_item_size > post_residual {
        score += 10.0 + 0.2 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 0.5 * (mean_residual - post_residual as f64);
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only if all open bins are nearly full
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 55.0 * pressure;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream urgency: consolidate to reduce open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual == post_residual + item_size) as i32 as f64 * (item_size as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item (size <= 80, min 1) can use.
    if post_residual > 0 {
        let max_next = if next_item_size > 0 { next_item_size as f64 } else { 80.0 };
        if (post_residual as f64) < max_next {
            // residual smaller than the next item: likely dead space
            score += 6.0 * (1.0 - (post_residual as f64) / max_next);
        } else {
            // residual can host the lookahead item: reward strongly
            score -= 10.0;
            if post_residual == next_item_size {
                score -= 15.0; // perfect lookahead match
            }
        }
    } else {
        score -= 20.0; // perfect closure
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer the bin with best relative fit.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state coupling: penalize bins whose residual deviates from mean
    // (prefer balanced residual portfolio), scaled by number of open bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 + (open_bins_count as f64).ln());

    // Time horizon: early in stream, be conservative (favor filling existing bins
    // less aggressively to keep flexibility); late in stream, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;

    // Prefer placing into bins with small residual overall as stream matures.
    score += (1.0 - progress) * 0.05 * (bin_residual as f64);

    // Mild penalty for opening a new bin when existing bins fit well.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let best_possible = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
        if post_residual as f64 >= best_possible {
            // new bin leaves room for lookahead: acceptable sometimes
            score -= 3.0 * progress;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = (post_residual as f64) / cap;

    // Core: quadratic growth of penalty with leftover space (smooth, non-linear)
    let mut score = pr * pr / cap;

    // Tight-fit reward: strongly subtract when item nearly fills the bin
    let tightness = 1.0 - fit;
    score -= 30.0 * tightness * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly-ish
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: discourage opening bins unless residual is truly bad
    if bin_residual == bin_capacity {
        let waste = pr; // = capacity - item
        score += 40.0 + 0.6 * waste as f64 - 20.0 * progress;
        score += open_bins_count as f64 * 0.5;
    } else {
        // Prefer bins with residuals close to the mean (keeps spread uniform)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 8.0 * dev * dev;
    }

    // Mild stream-progress term: later in stream, slightly prefer tighter packing
    score += 10.0 * progress * fit * fit;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post_residual.
    score -= 2.5 * ((cap - post_residual as f64) / cap).powi(2) * 10.0;

    // Perfect fit gets a strong discount.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic class: post_residual bucketed by integer division thresholds.
    let pr = post_residual;
    let class = pr / 10; // classes 0..10
    score += match class {
        0 => -8.0,
        1 => -4.0,
        2 => -1.0,
        3 => 1.0,
        4 => 2.5,
        5 => 3.5,
        6 => 4.5,
        7 => 5.5,
        8 => 6.5,
        _ => 7.5,
    };

    // Modulo arithmetic on post_residual: residues divisible by small item
    // sizes are more likely fillable later.
    let fillable = |r: u32| r >= 1 && r <= 100 && {
        let rr = r % 10;
        rr == 0 || rr == 5 || r % 3 == 0
    };
    if fillable(pr) {
        score -= 3.0;
    } else if pr > 0 {
        score += 2.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            score -= 2.0 * (pr as f64 - next_item_size as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 12.0 + 6.0 * progress;
        // If many bins are open and mean residual is large, prefer reuse.
        if mean_residual > item_size as f64 {
            nb += 8.0;
        }
        // Opening a bin is fine when nothing fits well elsewhere.
        if fitting_bins_count == 0 {
            nb -= 25.0;
        }
        score += nb;
    }

    // Slight preference for bins below mean residual (consolidate emptier space).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Small tie-breaker favoring fuller bins.
    score -= 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let capacity = (bin_capacity as f64).max(1.0);
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;

    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let mean_res = if mean_residual.is_finite() {
        mean_residual.clamp(0.0, capacity)
    } else {
        residual
    };

    let is_new_bin = bin_residual == bin_capacity;
    let open_pressure = open.min(120.0);

    let mut score = post;

    // Reward high immediate utilization; tighter existing bins get a stronger reward.
    score -= 5.0 * (item / residual.max(1.0));

    // When many bins are already open, leftover space is more expensive.
    score += 0.010 * open_pressure * post;

    // Exact closure is highly desirable.
    if post_residual == 0 {
        score -= 34.0 + 10.0 * progress + 0.20 * open_pressure;
    }

    // Lookahead dead-space avoidance: penalize positive leftovers that cannot hold the next item.
    if next > 0.0 && post_residual > 0 && post < next {
        let gap_ratio = ((next - post) / next).clamp(0.0, 1.0);
        let size_factor = 0.6 + 0.4 * (item / capacity);
        let urgency = 0.85 + 0.35 * progress + 0.01 * open.min(30.0);
        score += 55.0 * gap_ratio * gap_ratio * urgency * size_factor;
    } else if next > 0.0 && post >= next {
        // Reward leftovers that match the next item well.
        let match_quality = 1.0 - ((post - next).abs() / capacity).clamp(0.0, 1.0);
        score -= 7.0 * match_quality;

        if post_residual == next_item_size {
            score -= 8.0 + 4.0 * progress;
        }
    }

    // Prefer bins that are fuller than the current open-bin average.
    if residual > mean_res {
        score += 0.04 * (residual - mean_res);
    } else {
        score -= 0.015 * (mean_res - residual);
    }

    if is_new_bin {
        // Opening a fresh bin is penalized increasingly when many bins are already active
        // or when several existing bins could still accommodate the item.
        let pressure = 6.0
            + 1.10 * open.sqrt()
            + 0.035 * mean_res
            + fitting.min(20.0);

        score += pressure * (0.8 + 0.6 * progress);
    } else if fitting_bins_count == 1 {
        // Strongly favor the last existing chance before opening a new bin.
        score -= 8.0 + 8.0 * progress + 0.08 * open_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect pairing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this residual: penalize leftover
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(30.0);
        }
    } else {
        // last item: just minimize post_residual
        score -= 5.0 * tightness;
    }

    // Compare residual against mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 2.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin offers a good fit (post_residual near 0 in some bin).
    if bin_residual == bin_capacity {
        // Penalize new bins mildly; escalate when other options exist.
        score += 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            // If some open bin fits, discourage new bin further.
            score += 10.0;
        }
        // Late in stream, prefer closing out open bins rather than opening new.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Small bonus for filling bins that are already mostly full.
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: nonlinear bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving dead space that likely cannot be used later.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny slivers are wasted
    }
    if post_residual >= 10 && post_residual < 20 {
        score -= 4.0; // usable mid-range residual is good
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 3.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Early in the stream, opening bins is cheaper (more future to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If many open bins with high mean residual, prefer consolidating into them.
        score += 0.35 * open_bins_count as f64 * (mean_residual / cap).max(0.0);
        // Large items justify fresh bins more.
        score -= 0.25 * item_size as f64;
        // If next item is small, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size < 30 {
            score -= 10.0;
        }
    }

    // Prefer filling bins that are already relatively empty (consolidation).
    let fill_frac = 1.0 - (bin_residual as f64 / cap);
    score -= 6.0 * fill_frac;

    // Mild penalty when many bins fit the item: prefer the tightest, discourage scattering.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear penalty on residual magnitude (dead space grows super-linearly)
    let x = pr / cap;
    score += 12.0 * x * x * (1.0 + progress);

    // Reward leaving room for the lookahead item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (pr - next_item_size as f64) / cap;
        // strongly subtract when post_residual >= next item size and close fit
        let fit_quality = (-gap.abs() * 8.0).exp();
        score -= 10.0 * fit_quality * (1.0 - progress);
        // penalize residual slightly below next item size (near-miss dead space)
        if pr < next_item_size as f64 {
            score += 6.0 * nx * (1.0 - pr / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a bin when mean residual across open bins is high
    if bin_residual == bin_capacity {
        let mr = mean_residual / cap;
        score += 8.0 * mr * (1.0 + progress) + 0.5 * open_bins_count as f64 * progress;
    }

    // Mild coupling: favor bins whose residual deviates from mean (consolidate slack)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ir = item_size as f64;

    // Harmonic class of post_residual: residual modulo capacity quarters
    let q = bin_capacity / 4;
    let class = (post_residual % q) as f64;
    let class_frac = class / (q as f64);

    // Reward tight fits: post_residual near a harmonic boundary (0, q, 2q, 3q)
    let boundary_dist = class_frac.min(1.0 - class_frac);
    score -= 12.0 * boundary_dist;

    // Penalize dead space: residual too small to ever fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: can next item fit in post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // bonus if next item fits snugly too
            let pr2 = (post_residual - next_item_size) as f64;
            if pr2 < 10.0 { score -= 6.0; }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if is_new_bin {
        // Prefer reusing open bins, especially when fit is decent
        let reuse_pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).ln().max(0.5)
        } else {
            0.0
        };
        score += 25.0 + 20.0 * (1.0 - progress) + 15.0 * reuse_pressure;
        // Open a new bin when the item is large relative to capacity
        score -= (ir / cap) * 20.0;
        // If item leaves huge waste in every open bin, new bin is fine
        if post_residual == 0 { score -= 30.0; }
    } else {
        // Reward filling bins that are already fairly full
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= 10.0 * fill;
        // Last-chance bin: strongly favor using it
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Penalize spreading across too many open bins with big residuals
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 5.0;
        }
    }

    // Perfect fill reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small tie-break via harmonic class of item size
    score += ((item_size % 7) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (small gaps below the minimum item size) are heavily penalized.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit: strongly rewarded
    }

    // Tightness reward: fraction of the bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Penalize leaving a gap that is just barely too small for the next item
    // (wasted lookahead opportunity), reward if next item fits the post gap.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0; // chain placement possible
        } else if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 8.0; // gap blocks next item and is unusable anyway
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (1.0 - fill);

    // Deviation from mean residual: prefer bins whose residual is close to the item,
    // i.e. avoid placing into bins with much larger residual when a tighter one exists.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness - 0.10 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate calibration: opening a new bin is only attractive when the
    // item is large relative to capacity and open-bin pressure is low.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64 - 20.0 * fill;
        if fitting_bins_count <= 1 {
            score -= 15.0; // nothing else fits: opening new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: strongly prefer minimal post_residual (tight fit), superlinear.
    score += (post_residual as f64 / bin_capacity as f64).powf(1.8) * 30.0;

    // Perfect chain match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0 + 20.0 * (1.0 - progress);
    }
    // Partial lookahead match: next item still fits in the residual.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // Reward only when the leftover after the lookahead item is small.
        score -= 25.0 * (1.0 - slack / bin_capacity as f64) - slack * 0.15;
    }
    // Lookahead cannot fit: penalize creating residual that likely becomes dead space.
    else if next_item_size > post_residual {
        score += 8.0 + (next_item_size as f64 - post_residual as f64) * 0.25;
    }

    // Reward bins whose residual is below the mean (already well-packed, keep them tight).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced late in the stream.
        let mut open_cost = 14.0 - 6.0 * progress;
        // If no open bin fits well (post_residual of best fit would be large), open a new bin.
        if post_residual == bin_capacity && item_size <= bin_capacity {
            // Compare: placing here wastes (capacity - item); opening wastes that too,
            // but a fresh bin keeps large residual for future items.
            let waste_here = (bin_capacity - item_size) as f64;
            if waste_here > 0.35 * bin_capacity as f64 {
                open_cost -= 10.0;
            }
        }
        // Fewer open bins -> cheaper to open a new one.
        open_cost -= (open_bins_count as f64).ln().max(0.0) * 1.5;
        score += open_cost;
    }

    // Mild penalty for very large residual waste regardless of lookahead.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // nearly perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // Penalize opening a new bin when plenty of open bins could take the item,
    // but relax this penalty late in the stream (consolidation phase).
    if is_new_bin {
        let crowding = (fitting_bins_count as f64).min(8.0);
        score += 25.0 + 6.0 * crowding * (1.0 - 0.5 * progress);
    } else {
        // Mild reward for reusing existing bins.
        score -= 4.0;
    }

    // Lookahead coupling (k=2): reward bins whose post-residual can host the
    // next item; penalize bins that would strand a large residual the next
    // item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.15 * post_residual as f64;
        } else if !is_new_bin && post_residual > 0 && post_residual < 10 {
            // Creating tiny dead space (<10, minimum item size) is pure waste.
            score += 12.0;
        }
    } else {
        // Final item: just minimize residual waste.
        score -= 5.0;
    }

    // Global pressure: when mean residual across open bins is high, prefer
    // packing into existing space more aggressively (unless it's a new bin).
    if !is_new_bin {
        score -= 0.05 * mean_residual;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Time-horizon modulation: early on, be slightly more willing to open
    // bins (flexibility); late, compress into existing bins.
    if is_new_bin {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap;
    let coupling = prn * prn * (1.0 - progress) - prn * progress * progress;
    score += 25.0 * coupling;

    // Reward near-perfect fits, smoothly.
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit * fit;

    // Last-chance bonus: avoid opening a new bin when only this one fits.
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - prn);
    }

    // Lookahead: favor residuals that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (nx / cap)) * (1.0 - prn);
        } else {
            score += 6.0 * (1.0 - pr / nx.max(1.0));
        }
    }

    // Mild penalty when bin residual deviates from mean residual of open bins.
    score += 0.05 * (pr - mean_residual).abs();

    // Encourage filling existing bins as stream progresses.
    score -= 5.0 * progress * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: mod-10 classes capture
    // classic bin-packing "good residual" sizes (0, 10, 20 ...).
    let pr = post_residual;
    let class = pr % 10;
    let class_bonus = match class {
        0 => 18.0,          // perfectly reusable chunk
        5 => 10.0,          // half-decade residual, very composable
        1 | 9 => 6.0,       // near-decade residuals still pair well
        2 | 8 => 4.0,
        3 | 7 => 1.5,
        _ => 0.0,           // 4 | 6
    };
    score -= class_bonus;

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.85 {
        score -= 14.0 * (fill - 0.85);
    } else if fill > 0.6 {
        score -= 6.0 * (fill - 0.6);
    }

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: strongly reward residuals that can host the next item,
    // especially when few bins can fit the current item (last-chance bin).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 8.0 + 10.0 * snug;
        } else {
            // dead space relative to next item
            score += 3.0 * (next_item_size - post_residual) as f64 / cap * 10.0;
        }
    }
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // last chance: strongly prefer using this bin over opening a new one
        score -= 20.0;
    }

    // Penalize leaving residual far from mean (fragmentation risk),
    // scaled by how far along the stream we are.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = (post_residual as f64 - mean_residual).abs() / cap;
    score += dev * 8.0 * (0.3 + 0.7 * progress);

    // Many open bins: discourage spreading into yet another bin;
    // few open bins: allow consolidation pressure.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate (empty bin): baseline cost of opening a bin.
    if bin_residual == bin_capacity {
        score += 22.0
            + 6.0 * (1.0 - item_size as f64 / cap)
            + 4.0 * progress * (open_bins_count as f64).sqrt();
        // still allow a new bin for large items that would leave tiny residuals elsewhere
        if item_size >= 80 && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual < item_size.min(20) {
        score += 60.0; // dead space that likely can never be used
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect fit: residual almost fully consumed
    } else if post_residual <= 25 {
        score -= 10.0; // good fit, still potentially usable for small items
    }

    // Penalize leaving large residuals only mildly (they remain usable),
    // but reward tight fits proportionally.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Open-bins pressure: discourage opening new bins when many are open,
    // and encourage filling existing ones when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current bins fit poorly.
        score += 30.0 + 8.0 * pressure;
        // Allow a new bin if the only fitting bin would leave a bad gap.
        if fitting_bins_count <= 1 && post_residual >= 0.0 {
            score -= 20.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 35.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // residual too small for lookahead item: slight penalty
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (i.e., bins that are already relatively full).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Mild early-stream exploration: keep scores stable over time.
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits: minimize wasted residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: bonus proportional to how well next item fills the leftover.
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * chain_fill;
        } else {
            // Next item won't fit here: penalize leaving dead space that's too small.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - dead);
            }
        }
    }

    // Relative to mean residual: bins with more room than average are better targets.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin unless the fit is poor.
    if bin_residual == bin_capacity {
        if fit_ratio > 0.6 {
            score -= 10.0; // good fill for a fresh bin
        } else {
            score += 20.0; // discourage wasting a fresh bin on a small item
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strongly reward perfect closures.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: reward residual that can host the next item,
    // penalize residuals that nearly (but not quite) fit it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 0.5 * nxt;
        } else {
            score += 0.3 * (nxt - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: mild pressure to fill existing ones rather than spread.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: penalize slightly, less so late in the stream or
    // when existing bins are on average tight (low mean residual).
    if bin_residual == bin_capacity {
        score += 12.0 + 0.4 * mean_residual - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.35 * progress) - 0.5 * post * pr * (1.0 - progress);

    // Reward tight fits, stronger early when dead space matters most
    let tightness = 1.0 - pr;
    score -= 12.0 * tightness.powf(3.0) * (1.0 - progress);

    // Penalize leaving residuals that cannot fit a typical future item
    let next = next_item_size as f64;
    if next > 0.0 {
        if post >= next {
            score -= 4.0 * (1.0 - (post - next) / cap);
        } else {
            score += 6.0 * (next - post) / cap;
        }
    }

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many fitting bins: prefer the fullest (smallest post_residual) more strongly
    if fitting_bins_count > 2 {
        score += 2.0 * pr * (fitting_bins_count as f64).ln();
    }

    // Slight penalty for spreading across too many open bins relative to mean residual
    score += 0.05 * (mean_residual - post).abs() * (1.0 + progress);

    // New-bin candidate: keep it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 3.0 - 10.0 * (1.0 - (fitting_bins_count as f64).min(5.0) / 5.0);
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 4 classes
    let cap = bin_capacity as f64;
    let quarter = cap / 4.0;
    let pr = post_residual as f64;

    // Class index 0..3 of post_residual (0 = tightest fit)
    let class = (pr / quarter).floor().min(3.0);

    // Reward tight fits strongly (non-linear)
    score -= (cap - pr) * 0.35 * (1.0 + class / 3.0);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space in unusable harmonic bands: residual in (10, 20) is a trap
    if pr > 10.0 && pr < 20.0 {
        score += 12.0 * (20.0 - pr) / 10.0;
    }

    // Modulo logic: items near half capacity pair well; if next item fits post_residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // extra reward if next item exactly fills the bin (harmonic pair)
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mild penalty proportional to wasted opportunity
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.9 + open_bins_count as f64 * 0.5 - progress * 5.0;
        // if mean residual across open bins is small, opening new bin is more acceptable
        score -= (mean_residual / cap).max(0.0) * 20.0;
    }

    // Small penalty for spreading across many bins
    score += open_bins_count as f64 * 0.05;

    // Integer-division threshold: residuals that are exact quarters are more usable
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible future item
    // (items are >= 1, but small gaps < ~12 are hard to fill) are quadratic.
    let pr = post_residual as f64;
    if post_residual < 12 {
        score += (12.0 - pr) * (12.0 - pr) * 2.5;
    } else if post_residual == 0 {
        // Perfect fit is excellent: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Pressure from many open bins: discourage spreading when bins are numerous.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the item (minimize leftover mismatch).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 3.0 {
        score -= 20.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; slightly prefer filling this bin now.
        score -= 5.0;
    }

    // New-bin candidate: penalize mildly so it's only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff * diff);
        // Penalize if next item cannot fit into this bin after placement
        if next_item_size as u32 > post_residual {
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        }
        // Reward near-perfect two-item packing
        if post_residual + item_size >= bin_capacity / 2 && diff < 3.0 {
            score -= 25.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score += (bin_capacity as f64 - post_residual as f64) * 0.1;
    }

    // Penalize large dead space relative to mean residual across open bins
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += dead * 0.3;
    } else {
        score += dead * 0.15;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Discourage opening new bins when many open bins already exist
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
    }

    // Small penalty for wasting capacity outright
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Early stream: slightly favor consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * tightness * tightness;

    // Penalize leaving awkward dead space (small but nonzero residual).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward perfect closure.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: bonus if the next item can use the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let next_tight = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 20.0 * next_tight;
        } else {
            // Post-residual too small for next item: penalize proportionally to wasted chunk.
            score += 0.15 * (post_residual as f64).min(50.0);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when good fits exist,
    // but allow it when open bins are crowded (high mean fill) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
        let crowding = open_bins_count as f64 / 20.0;
        score += 45.0 - 35.0 * mean_fill - 20.0 * progress - 10.0 * crowding.min(1.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big items coming: fresh bin useful
        }
    }

    // Mild preference to fill older/more-filled bins among many open bins.
    score += 0.3 * ((open_bins_count as f64) - (bin_residual as f64 / bin_capacity as f64) * 2.0);

    // Time horizon: as stream progresses, be more conservative with residual waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly damped by progress (late stream -> waste matters more)
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear penalty for mid-size dead space: residuals near half capacity are least reusable
    let dead = norm_pr * (1.0 - norm_pr); // peaks at 0.5
    score += 40.0 * dead * (1.0 - progress);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-gap / 20.0) * (1.0 - progress);
        // penalize if next item cannot fit but residual is large
        if next_item_size as f64 > pr {
            score += 10.0 * progress;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Prefer bins with below-mean residual (consolidate fuller bins)
    score -= 5.0 * (mean_residual - pr) / cap;

    // New-bin candidate: penalize opening a new bin unless residual would be huge waste elsewhere
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 10.0 * open_bins_count as f64;
        if pr >= 0.0 && item_size as f64 >= 0.9 * cap {
            score -= 40.0; // big item fits perfectly in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band it lands in.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Classify post_residual into harmonic bands (1/8th of capacity).
    let band = (post_residual * 8) / bin_capacity; // 0..8 integer class
    // Dead-space penalty: residuals too small to fit any plausible item (1..100)
    // are nearly unusable; smallest band (band 0) is worst.
    match band {
        0 => score += 40.0,           // 0..12 : dead space
        1 => score += 12.0,           // 12..25 : fits only tiny items
        2 => score += 4.0,            // 25..37
        3 => score -= 2.0,            // 37..50 : sweet mid-range
        4 => score -= 4.0,            // 50..62 : very reusable
        5 => score -= 2.0,            // 62..75
        6 => score += 2.0,            // 75..87
        _ => score += 6.0,            // 87..100 : nearly empty bin
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward residuals that exactly host the next item,
    // penalize residuals that waste the next item's complement class.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // harmonic class of the leftover gap after serving next item
            let gap_band = (gap * 8) / bin_capacity;
            score -= match gap_band {
                0 => 10.0,
                1 => 6.0,
                2 => 4.0,
                3 => 8.0,
                4 => 10.0,
                _ => 6.0,
            };
        } else {
            // next item cannot use this residual: penalty scaled by how far off
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Crowding pressure: with many open bins, prefer tightening existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    // Mean-residual alignment: if this bin's post residual is close to the mean,
    // it keeps the bin population homogeneous (easier future packing).
    let drift = (post - mean_residual).abs();
    score += drift * 0.05;

    // New-bin candidate: only attractive when current bin would be badly fragmented
    // or no good fit exists. Base cost of opening a bin.
    if bin_residual == bin_capacity {
        score += 55.0;
        // cheaper to open a new bin early when few bins are open
        score -= (open_bins_count as f64).sqrt() * 3.0;
        // if the item would leave a dead-space band in any existing bin, new bin is fine
        if band == 0 && fitting_bins_count >= 1 {
            score -= 30.0;
        }
        // if the next item is large and nothing fits it well, fresh bin helps
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized (non-linear "dead zone" coupling).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Also punish gaps too small for the smallest plausible follow-up item
    // relative to the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 * 0.5 {
        score += 15.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 30.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio * fit_ratio;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: encourage closing out existing bins rather than
    // proliferating bins when many are open.
    score += (open_bins_count as f64) * 0.8;

    // Slight preference for bins with below-average residual (consolidation).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: make empty bins moderately attractive only when the
    // item is large relative to capacity or few bins are open.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size >= bin_capacity / 2 { 12.0 } else { 0.0 };
        score += 18.0 - large_item_bonus - (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect 2-step match: post_residual exactly fits next item
        let gap = (post_residual as f64 - nxt).abs();
        if gap == 0.0 {
            score -= 60.0; // chainable bin: strongly favored
        } else if post_residual as f64 > nxt {
            // next item fits with leftover; penalize leftover mildly
            score += (post_residual as f64 - nxt) * 0.3;
        } else {
            // next item won't fit in leftover: dead space risk
            score += (nxt - post_residual as f64) * 0.6;
        }
        // reward tight overall packing relative to mean residual
        score -= (mean_residual - post_residual as f64) * 0.25;
    } else {
        // last item: prefer minimal waste
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 45.0;
    }

    // New-bin candidate: penalize unless it is genuinely attractive
    if is_new_bin {
        // opening a new bin wastes (capacity - item_size) of usable space
        let waste = (bin_capacity - item_size) as f64;
        score += 25.0 + waste * 0.4;
        // more open bins -> slightly more willing to open another
        score -= open_bins_count as f64 * 0.5;
        // late in stream, prefer consolidating into open bins
        score += progress * 15.0;
    }

    // prefer bins whose residual is small relative to capacity (tight fill)
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose residual is close to the item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize post_residual values that are too small to ever hold a future item
    // (dead space), but reward moderate usable leftovers.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 25.0; // nearly-dead space
        } else {
            score -= 4.0 * ((post_residual as f64) / bin_capacity as f64).sqrt();
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; leftover becomes potential dead space
            score += 3.0 * (post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: fill as tightly as possible.
        score -= 8.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the fit
    // in existing bins is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and load.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 20.0 * progress + 0.15 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If mean residual across open bins is large, existing bins should suffice.
        score += 0.3 * mean_residual;
    }

    // Mild preference for consolidating into bins with below-average residual
    // (keeps some bins large for future big items).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 2.0 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 1.5 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: mild penalty on wasted space; late: strong penalty (no time to fill).
    let x = (pr / cap).clamp(0.0, 1.0);
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep: punishes mid-range waste
    let waste_weight = 1.0 + 4.0 * progress * progress;
    score += waste_weight * poly * cap * 0.25;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - x;
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving residual that is small but larger than typical next item
    // (dead space); reward residual that can host the lookahead item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 3.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 4.0 * (ni - pr) / cap;
        }
    }

    // New-bin candidate: neutral baseline; open a fresh bin only when existing
    // fits are poor (post_residual too small relative to capacity) or few options.
    if bin_residual == bin_capacity {
        let poor_fit_pressure = if fitting_bins_count > 0 {
            (1.0 - (fitting_bins_count as f64).recip()).min(1.0)
        } else { 1.0 };
        score = 0.5 * cap + 10.0 * (1.0 - poor_fit_pressure) - 6.0 * progress;
    }

    // Mild penalty for bin proliferation pressure when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Nudge toward bins with above-average residual (keep balanced fill).
    score += 0.5 * (mean_residual - (bin_residual as f64)) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity-fraction classes.
    // Small post residuals are good (tight fit); classify dead space into bands.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Tight-fit reward: post_residual in the smallest harmonic band (0..=5)
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Harmonic class via integer division: residual / 10 class
    let class = post_residual / 10;
    score += class as f64 * 3.0;

    // Perfect-fill modulo classes: residual divisible by 25/50 are structurally clean
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item exactly fills the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it uses the leftover
            let fill_ratio = next_item_size as f64 / post.max(1.0);
            score -= 15.0 * fill_ratio;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only open a new bin if current bin fit is terrible
    if bin_residual == bin_capacity {
        // empty bin: neutral base, but penalize if a decent fit exists elsewhere
        if fitting_bins_count > 0 && post >= 0.0 {
            score += 12.0;
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Penalize bins whose residual is far below the mean (fragmented bins)
    let dev = mean_residual - post;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Mild preference for bins with larger residual (waste big bins first is bad;
    // instead prefer filling fuller bins to keep large residuals flexible)
    score -= 0.05 * (bin_residual as f64);

    // Reward compacting when many bins are open
    score -= 0.5 * open_bins_count.min(20) as f64 * (1.0 - post / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit is highly rewarded
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Open-bin pressure: discourage spreading across many bins when few are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to existing open bins,
        // but relax if no bin fits well (post_residual of best alternative unknown,
        // so use fitting_bins_count as last-chance signal).
        score += (open_bins_count as f64) * 6.0;
        if fitting_bins_count == 1 {
            score -= 20.0; // last chance: prefer existing bin over new bin
        }
    } else if fitting_bins_count == 1 {
        // This is the only bin that fits; strongly favor using it.
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 && (post_residual as u32) < next_item_size {
        score += 8.0; // dead space that blocks the next item
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Stream progression: as stream advances, tighten packing (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: this bin's leftover exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Good lookahead: next item still fits after this placement (with slack margin).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + 20.0 * (slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow: dead-space penalty, worse the tighter the fit was.
        let waste = next_item_size as f64 - post_residual as f64;
        score += 10.0 + 0.5 * waste;
    }

    // Penalize leaving unusably tiny residuals (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Coupling with mean residual: prefer bins whose residual is below average
    // (i.e., consuming fuller bins first keeps many-roomy bins available).
    let res = post_residual as f64;
    score += 0.4 * (res - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - res).max(0.0);

    // Last-chance bin: strongly reward using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 15.0;
        // Early in the stream, opening fresh bins is cheaper (room for future items).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin gives it room.
        if next_item_size > 0 && next_item_size > bin_residual.saturating_sub(item_size) {
            score -= 12.0;
        }
    }

    // Mild pressure to keep the number of open bins low.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact placements get strong discounts.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio * fit_ratio;
    }

    // Penalize small dead space that is hard to fill later (below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - chain_waste / cap);
        } else {
            // Next item won't fit here; penalize leaving large unusable chunks.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 8.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large post_residual) or bins are few.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when existing residuals are small (poor fits) and
        // item is large; discourage early in stream or when many bins open.
        score -= 10.0 * pressure;
        score += 5.0 * (item_size as f64 / cap);
        score -= 3.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Favor bins with residual close to item (best-fit flavor).
        let slack = (bin_residual - item_size) as f64;
        score += 4.0 * (slack / cap);
        // Mild preference for consolidating into fewer bins.
        if open_bins_count > 2 {
            score -= 1.0;
        }
    }

    // Global state: when mean residual is large, prefer using fuller bins.
    score -= 2.0 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tight * tight * tight;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize creating dead space that cannot serve the next item (smooth coupling).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.4 * gap * (1.0 + progress);
        // Reward leaving room exactly for the next item.
        if post_residual as f64 >= next_item_size as f64 {
            score -= 8.0 * (1.0 - (post_residual as f64 / cap));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when
    // alternatives exist; relax late in the stream where consolidation is done.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let alt = fitting_bins_count.max(1) as f64;
        score += 45.0 / alt * (1.0 - 0.5 * progress);
        // Slightly favor new bin for large items that would leave tiny residue elsewhere.
        let waste = (bin_capacity as f64 - item_size as f64);
        score -= 0.15 * waste * progress;
    }

    // Mild preference for bins below mean residual (balance load smoothly).
    score += 0.05 * (mean_residual - bin_residual as f64).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (harmonic class: post_residual in small buckets)
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    }

    // Penalize dead space: residual too small to ever be useful for typical items
    if pr > 0 && pr < 10 {
        score += 15.0; // unusable sliver
    }

    // Reward bins where the lookahead item fits the post-residual (chained placement)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // extra bonus if chain leaves a small remainder again
        let pr2 = post_residual - next_item_size;
        if pr2 <= 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post residual can't hold next item; mildly penalize
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only
    // when no good fit exists (many fitting bins means prefer existing bins)
    if bin_residual == bin_capacity {
        score += 45.0; // default penalty: prefer reusing open bins
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: open new bin
        } else if fitting_bins_count == 1 {
            score += 20.0; // last-chance bin exists, keep new-bin penalty high
        }
        // if open bins are all nearly full (large mean residual means poorly packed),
        // opening a fresh bin is less bad
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    }

    // Harmonic modulo logic on post_residual classes (capacity fractions)
    let quarter = bin_capacity / 4;
    if pr == quarter || pr == quarter * 2 || pr == quarter * 3 {
        score -= 8.0; // aligned residuals are reusable targets
    }

    // Mild pressure to consolidate when many bins are open
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum plausible item are "dead" — penalize them heavily.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Semi-dead space: post_residual that cannot fit a likely next item
    // (conservatively anything > 40 is often reusable; below that, penalize).
    if post_residual > 0 && post_residual < 40 {
        score += 12.0 * (1.0 - post_residual as f64 / 40.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering items across many bins unless fit is good.
    score += 2.0 * open_bins_count as f64 * (1.0 - fit_ratio.min(1.0));

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate evaluation: only attractive when the item is large relative
    // to typical residuals, or no good fit exists.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; make it competitive for big items.
        score = 55.0 - 0.35 * item_size as f64;
        // If the item would leave a very reusable gap in an existing bin, prefer that.
        if fitting_bins_count > 0 {
            let best_gap = mean_residual.max(0.0);
            if best_gap - item_size as f64 >= 30.0 {
                score += 15.0;
            }
        }
        // Late in the stream, avoid opening bins for marginal gains.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item would fit here now but not after this placement — mild penalty.
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 120.0;
            // bonus for tight two-item packing
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // penalize dead space that next item cannot use
            score += 40.0 + 0.5 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a new bin when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 150.0 * fitting_bins_count as f64;
    }

    // Early in stream: be less picky about opening bins; later: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 100.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: discount score when post_residual is a small fraction of capacity.
    let tightness = post_residual as f64 / cap;
    score -= 0.6 * (1.0 - tightness) * (item_size as f64);

    // Reward exact / near-exact fills heavily.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the leftover space, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // Next item fits but leaves more fragmentation: mild reward proportional to fill.
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: penalize larger dead space.
            score += 0.25 * (post_residual as f64 - (post_residual as f64 % next_item_size as f64).max(0.0)) * 0.0;
            score += 5.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current fit is poor
    // or many open bins already exist with plenty of slack.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity - item_size) as f64;
        let global_slack = mean_residual * open_bins_count as f64;
        score += 15.0 + 0.1 * poor_fit;
        // If open bins are very fragmented (high mean residual), new bin is less bad.
        score -= 0.15 * mean_residual;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If global slack across open bins is huge, opening new bins is wasteful.
        if global_slack > item_size as f64 * 2.0 {
            score += 20.0;
        }
    }

    // Prefer bins whose residual is close to the mean (keep bins balanced), mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: penalize leftover residual, with non-linear (quadratic/cubic) waste shaping.
    let norm_pr = pr / cap;
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr) + 8.0 * norm_pr * norm_pr * norm_pr * cap;

    // Smooth progress coupling: later in the stream, waste matters more (less future to fill it).
    score *= 1.0 + 0.6 * progress * norm_pr;

    // Tight fit reward: strongly subtract when post_residual is small but non-zero.
    let tight = ((it - pr) / cap).max(0.0); // high when item nearly fills bin
    score -= 18.0 * tight * tight;

    // Lookahead coupling: reward residual that can host the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        score -= 10.0 * (-fit_gap / cap).exp() * (pr >= nx) as i32 as f64;
        score += 6.0 * (nx / cap) * (1.0 - (pr / cap).max(0.0));
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // smoothly relaxing as mean residual across open bins shrinks.
    if is_new {
        let mr_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score += 30.0 * mr_norm * (1.0 + 0.5 * progress) - 5.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Favor bins with residual above the mean (balanced packing), smooth coupling.
        score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class: which capacity-fraction band does the post-residual land in?
    let frac = pr / cap; // 0..1
    // Class boundaries: 0, 1/8, 1/4, 1/2, 3/4 (dead-space classes)
    let class_bonus = if post_residual == 0 {
        -60.0 // perfect fill
    } else if post_residual <= bin_capacity / 8 {
        -35.0
    } else if post_residual <= bin_capacity / 4 {
        -18.0
    } else if post_residual <= bin_capacity / 2 {
        0.0
    } else {
        15.0 // large residual left behind: wasteful unless reusable
    };
    score += class_bonus;

    // Integer-division threshold: residual divisible into common item classes
    let r = post_residual;
    if r > 0 {
        // Residual matching common item sizes (10,20,25,30,40,50) is reusable
        if r % 10 == 0 { score -= 12.0; }
        if r % 25 == 0 { score -= 6.0; }
        // residual that cannot fit the smallest plausible item
        if r < 10 { score += 40.0; }
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - pr / (pr + 1.0)); // chain-friendly
            score -= (nxt / cap) * 10.0;
        } else {
            // next item won't fit here; penalize less if residual is small anyway
            score += 8.0 * (frac - 0.25).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin gets neutral base; discourage opening
    // new bins unless current fit is poor.
    if bin_residual == bin_capacity {
        // base for fresh bin ~ slightly worse than a good fit, better than a bad one
        score = 30.0 + (item_size as f64 / cap) * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening fresh bin is good when item is large (poor fits elsewhere)
            if item_size > bin_capacity / 2 { score -= 10.0; }
        }
        // fewer open bins => opening is cheaper
        score -= open_bins_count as f64 * 1.5;
    }

    // Stream progression: late in stream, tighten packing (avoid sprawl)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (frac - 0.3).max(0.0);

    // Mean-residual coupling: if open bins already have lots of slack,
    // penalize adding more slack elsewhere less; reward consolidation.
    score -= (mean_residual / cap) * 8.0 * (1.0 - frac);

    // Modulo harmonic class on item size vs residual: perfect complementarity
    if bin_residual >= item_size {
        let complement = bin_residual - item_size;
        if complement % 10 == 0 { score -= 5.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Residuals in the 10..30 band can still host typical small items: mild reward.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 5.0;
    }

    // Tightness: reward using a large fraction of the bin's residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fill_ratio;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 20.0;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; slight penalty if we leave a tiny dead gap.
            if post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (many contenders) or mean residual is low; otherwise penalize opening.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() * 12.0 };
        score += 30.0 + pressure - (mean_residual / bin_capacity as f64) * 10.0;
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, heavily reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this placement is ideal — reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    }
    // Next item fits into the post residual: good chaining, moderate reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Reward tightness of the chain (little slack after the pair).
        let slack = post_residual - next_item_size;
        score -= (bin_capacity as f64 - slack as f64) * 0.1;
    }
    // Next item cannot use the leftover: dead space risk, penalize proportionally.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare post residual against mean residual across open bins:
    // leaving less than average keeps bins tight, reward; leaving more, penalize.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // (large items in fresh bins are fine) or many bins are already open.
    if bin_residual == bin_capacity {
        score += 80.0;
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
        if open_bins_count > 10 {
            score -= 20.0;
        }
    }

    // Slight pressure toward tighter bins as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strong bonus for near-perfect fits.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Dead-space penalty: residual too small to hold even the smallest item (size 1).
    if post_residual == 0 {
        score -= 10.0; // perfect fit, excellent
    } else if post_residual < 10 {
        score += 3.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is usually wasteful,
    // penalize it, but less when the current fit would leave large dead space
    // that the next item cannot use anyway.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let dead = post_residual as f64;
        let next_waste = if next_item_size > 0 && next_item_size <= post_residual {
            0.0
        } else {
            dead
        };
        score += 12.0 - 0.05 * next_waste;
        // Early in the stream, opening bins is cheaper (more items to come to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * (1.0 - progress);
    }

    // Lookahead synergy: reward bins whose post-residual accommodates the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
        // Extra reward if the next item fills the leftover almost exactly.
        let gap = (post_residual - next_item_size) as f64;
        score -= 2.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Penalize leaving a residual that the next item just barely misses.
        score += 1.5;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidation into existing bins rather than opening new ones.
    if !is_new_bin {
        score -= 0.02 * mean_residual;
    } else {
        score += 0.02 * mean_residual;
    }
    if is_new_bin && open_bins_count > 0 {
        score += 2.0;
    }

    // Mild preference for filling bins that are already relatively full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 2.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress) * (1.0 - progress);
    score += 18.0 * coupling;

    // Reward tight fits smoothly (quadratic in item size fraction)
    let tight = (item_size as f64 / cap) * (1.0 - pr_norm);
    score -= 10.0 * tight * tight;

    // Penalize when this is the last fitting bin (avoid losing the only option)
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - pr_norm) * (1.0 - progress);
    } else {
        score += 2.0 / fit;
    }

    // Mean residual interaction: prefer bins near the mean (smooth penalty)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Lookahead: reward if next item fits the post residual (smooth sigmoid-ish)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0) / cap;
        let slot = if pr >= nx { 1.0 - fits_next } else { -1.0 * (nx - pr) / cap };
        score -= 5.0 * slot * (0.5 + progress);
    }

    // Mild pressure to consolidate as many bins accumulate
    score += 0.05 * open * (1.0 - progress) * pr_norm;

    // New-bin candidate handling: neutralize base residual, add opening cost
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) - 3.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo small capacity fractions
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual is a "harmonic residue" (divisible by 10/20/25) -> clean space
    let post_u = post_residual;
    let harmonic_bonus = if post_u == 0 {
        60.0 // perfect fit, huge reward
    } else if post_u % 10 == 0 {
        8.0
    } else if post_u % 5 == 0 {
        3.0
    } else {
        -4.0 // ragged residue penalized
    };
    score -= harmonic_bonus;

    // Integer division threshold classes on post_residual (quarters of capacity)
    let quarter = (bin_capacity / 4).max(1);
    let half = (bin_capacity / 2).max(1);
    if post_u < quarter {
        score += 6.0; // tiny dead space class
    } else if post_u < half {
        score -= 2.0; // medium leftover still useful
    }

    // Coupling with next item: reward if next item fits exactly into post_residual class
    if next_item_size > 0 {
        if next_item_size == post_u {
            score -= 25.0; // perfect chained fit
        } else if next_item_size <= post_u {
            let gap = (post_u - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / cap_f);
            // harmonic match: next item leaves harmonic residue again
            if (post_u - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residue: penalize proportional residue size
            score += 0.05 * post;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: prefer it only when current bin fit is very poor
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap_f;
        if tightness > 0.75 {
            score -= 15.0; // big item: fresh bin is fine
        } else {
            score += 10.0 + 10.0 * (1.0 - tightness); // discourage wasting fresh bins
        }
    }

    // Progression & congestion modulation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;
    if open_bins_count > 8 {
        score -= 0.02 * mean_residual; // consolidate when many bins open
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // minimum item size are pure waste — penalize them quadratically.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 25.0;
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward tight fits relative to the item size (waste ratio coupling).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 30.0;

    // Open-bin pressure: when many bins are open, prefer filling existing
    // ones; discourage opening new bins unless the fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + progress);

    // Mean residual coupling: bins far below mean residual are less
    // attractive targets (their space is more useful later).
    if (bin_residual as f64) > mean_residual * 1.25 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this
    // placement for preserving a usable gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size.min(10) {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin starts at full residual;
    // make it attractive only when the current fit is bad or no bin fits.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual < 10 && post_residual > 0;
        let no_alternatives = fitting_bins_count == 0;
        if bad_fit || no_alternatives {
            score -= 40.0;
        } else {
            score += 15.0 + open_bins_count as f64 * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Next item does not fit in this bin's remainder: penalize dead space.
    else if next_item_size > 0 {
        score += 12.0;
    }

    // Reward filling bins tightly relative to mean residual of open bins.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let tight_exists = next_item_size > 0 && post_residual <= next_item_size;
        if tight_exists {
            score += 45.0; // an open bin gives a perfect follow-up; avoid new bin
        }
        score += 10.0 * open_bins_count as f64;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Mild bonus for very small leftovers (fragmentation avoidance).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space), with a non-linear boost
    let tight = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += tight * 30.0;

    // Reward filling bins almost exactly
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward leaving space for the next item (k=2 lookahead)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // extra reward if next item fills the post residual exactly
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else {
            // penalize creating dead space that next item cannot use
            score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.3;
        }
    }

    // Penalize spreading across many open bins; encourage consolidation
    score += (open_bins_count as f64) * 0.5;

    // Compare residual to mean residual: prefer bins below mean (denser bins)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate handling: make it attractive only when the fit
    // into existing bins would be very poor (large post_residual)
    if bin_residual == bin_capacity {
        // neutral baseline slightly above a perfect fit elsewhere
        score = 35.0 + (item_size as f64) * 0.1;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Slight time-dependent drift: later in the stream, prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.6 * progress + 0.8 * progress * progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= (1.0 - norm_pr).powi(2) * (1.0 + progress) * 4.0;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = pr - (next_item_size as f64).min(pr);
        if pr < next_item_size as f64 {
            score += 2.5 * (next_item_size as f64 - pr) / cap;
        } else {
            score -= 1.5 * (next_item_size as f64 / cap);
        }
        let _ = gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0;
    }

    // Mild preference to fill bins below mean residual (balance avoidance)
    score += 0.3 * (pr - mean_residual) / cap;

    // Slight penalty for proliferating bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * fit_ratio * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify by capacity fraction buckets.
    // Residuals that are "dead" (too small for typical items) should be penalized hard.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left after placement

    // Dead-space penalty: residual below the smallest useful item (<=10) is wasted.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post);
    }

    // Harmonic class: bucket post_residual into integer-division classes of width 10.
    // Class 0 (0..10) = dead, class 9 (90..100) = nearly empty.
    let class = (post_residual / 10) as f64;
    // Prefer leaving residuals in classes that future items (10..100) can use:
    // sweet spots are large residuals; penalize mid-low classes non-linearly.
    score += 8.0 * (9.0 - class) * (9.0 - class) * 0.05; // mild convex pull toward fuller bins

    // Modulo arithmetic: residuals that are multiples of common item sizes (10,20,25,50)
    // are "harmonic" and likely to be exactly filled later -> reward them.
    let r = post_residual;
    if r != 0 && (r % 10 == 0 || r % 25 == 0 || r % 50 == 0) {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pair
        } else if next_item_size < post_residual {
            // reward proportional to how well next item harmonizes with post residual
            let harm = (post_residual % next_item_size.max(1)) as f64;
            score -= 12.0 * (1.0 - harm / next_item_size as f64);
        } else {
            // next item cannot use this residual at all; if residual is small, penalize
            if post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless post residual would be dead space).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases if many items remain to fill it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score = 30.0 + 40.0 * progress;
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += 0.5 * mean_residual;
        // Perfect fit of item into fresh bin (item == capacity) is great.
        if item_size == bin_capacity {
            score -= 100.0;
        }
        // If lookahead item is large, a fresh bin can host it later: small discount.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Slight tie-break: prefer bins whose residual is far from mean (consolidation).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // Mild time-decay: later in the stream, filling existing bins tightly matters more.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Gap too small to ever hold the smallest plausible item (<= 1..10) -> dead space
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
