    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
        score -= 6.0;
    }

    // Last chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: many open bins -> discourage opening new ones,
    // encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 15.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins with residual close to item size (tight fit) relative to mean residual.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * (tightness - mean_residual.abs()).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
