            score += 0.35 * post_residual as f64;
            // Harsher if post_residual is dead space (below typical small item size).
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Relative to mean residual: prefer bins that are already below-average residual
    // (i.e., closer to full), avoid fragmenting high-residual bins.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item leaves huge dead space
