        }
        // If this bin could chain item + next item almost fully, big reward
        if item_size + next_item_size <= bin_residual {
            let chain_fill = (item_size + next_item_size) as f64 / bin_residual as f64;
            if chain_fill > 0.9 {
                score -= 20.0 * chain_fill;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is expensive; discourage unless
    // item is large (poor fit candidate) or few bins fit and mean residual is low.
    if bin_residual == bin_capacity {
        let mut open_penalty = 45.0;
        // Large items pack better in fresh bins
        if item_size > bin_capacity / 2 {
            open_penalty -= 20.0;
        }
        // If current bins are crowded (low mean residual), a new bin is more attractive
        open_penalty -= (mean_residual / bin_capacity as f64).max(0.0) * 30.0;
        // Late in the stream, prefer consolidating into open bins
        open_penalty += 15.0 * progress;
        // If many bins fit the item, no reason to open a new one
        if fitting_bins_count > 2 {
            open_penalty += 20.0;
        }
        score += open_penalty;
    }

    // Slight preference for bins with below-average residual (fill emptier bins first
    // keeps tight bins available for small future items)
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // Mild pressure to keep the number of open bins low
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) penalty
    let mut score = pr + 40.0 * x * x * cap;

    // Smooth coupling of post-residual with stream progress:
    // later in the stream, dead space becomes more costly
    score += 30.0 * progress * x * x * cap;

    // Reward tight fits (small residual) more strongly as stream progresses
    score -= 25.0 * progress * (1.0 - x).powi(2);

    // Lookahead coupling: if next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        let nd = diff / cap;
        score += 15.0 * nd;
        score -= 20.0 * (-diff / (0.15 * cap)).exp();
        // penalize leaving residual that is awkwardly between next item and larger sizes
        if pr < nx {
            score += 10.0 * (nx - pr) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly, more so when good existing fits exist
    if bin_residual == bin_capacity {
        score += 50.0 + 10.0 * (fitting_bins_count as f64).ln().max(0.0);
        // early in stream, opening bins is cheaper
        score -= 40.0 * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (balance load smoothly)
    score += 5.0 * ((pr - mean_residual) / cap);

    // Non-linear penalty for very small unusable residuals (dead space)
    let dead = (x * (1.0 - x)).powi(2);
    score += 25.0 * dead * cap;

    // Mild penalty for many open bins
    score += 2.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1
    let class = (frac * 10.0).floor() as i64; // 0..9 harmonic class

    // Reward near-perfect fits heavily (post_residual small).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if class == 0 {
        score -= 150.0;
    } else {
        // Penalize large dead space, superlinear in class.
        score += (class as f64) * (class as f64) * 8.0;
    }

    // Harmonic coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chains the next item into this bin.
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 120.0 - chain_tight * 2.0;
        } else {
            // Next item won't fit here; penalize modulo mismatch of class pairs.
            let nc = ((next_item_size as f64 / cap) * 10.0).floor() as i64;
            let mismatch = (class - nc).abs();
            score += 40.0 + mismatch as f64 * 6.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 180.0;
    } else if fitting_bins_count > 1 {
        // Prefer the bin where item fits most snugly relative to others.
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // current item is huge relative to all residuals or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (mean_residual - item_size as f64).abs();
        // Base cost of a fresh bin; cheaper late when open bins are crowded.
        score = 260.0 - progress * 60.0 - pressure * 0.5 - (open_bins_count as f64) * 2.0;
        // A fresh bin is attractive only if the item leaves a small residual
        // that itself belongs to a good harmonic class.
        score += frac * 100.0;
        if post_residual <= 20 {
            score -= 80.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 90.0;
        }
    }

    // Mild global regularization: keep scores comparable across stream phases.
    score += mean_residual * 0.01 - (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual < 10 && post_residual > 0 {
        score += 45.0;
    }
    if post_residual < 5 && post_residual > 0 {
        score += 60.0;
    }

    // Reward very tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 80.0;
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably from the mean (tighter than average).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Open-bin pressure: discourage spreading across many bins slightly.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be stranded by a small leftover, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate handling: opening a new bin is usually worse than
    // using an existing fitting bin, unless it is the only option.
    if bin_residual == bin_capacity {
        let base_penalty = 70.0 + 1.5 * open_bins_count as f64;
        score += base_penalty;
        if fitting_bins_count <= 1 {
            score -= 90.0; // no real alternative: allow new bin
        }
    }

    // Mild stream-progression term: tighten packing as the stream advances.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits (low post_residual)
    score -= 20.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Discourage opening new bins mid-stream when decent fits exist
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild pressure against accumulating many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space proportional to how much of the bin it wastes.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Lookahead: if the next item could use the leftover space, reward leaving it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0; // leftover is reusable
            if (post_residual - next_item_size) <= 5 {
                score -= 10.0; // near-perfect two-item chain
            }
        } else {
            // leftover too small for next item: dead space penalty
            let gap = post_residual as f64;
            if gap < 10.0 {
                score += 12.0;
            }
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Opening a new bin: penalize mildly, more when many bins are already open
    // with slack that could absorb the item.
    if bin_residual == bin_capacity {
        let mut penalty = 25.0;
        penalty += (open_bins_count as f64).sqrt() * 4.0;
        // If mean residual across open bins comfortably fits the item, discourage new bin.
        if mean_residual >= item_size as f64 {
            penalty += 20.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty += 15.0 * progress;
        score += penalty;
    } else {
        // Slight preference for bins with less residual (best-fit tendency)
        score += bin_residual as f64 * 0.05;
    }

    // Reward packing into bins already below mean residual (balancing).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap; // fraction of bin used after placement

    // Base: prefer small post residual, with non-linear (quadratic) coupling
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Reward high fill ratio non-linearly (smooth cubic in fill)
    score -= 18.0 * fill * fill * fill;

    // Stream progress coupling: later in the stream, waste tolerance shrinks
    let tightness = 1.0 + 0.8 * progress;
    score += tightness * pr * (1.0 - fill);

    // Lookahead: bonus if the next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            // smooth reward peaked when next item nearly fills the residual
            let fit_quality = 1.0 - (slack / cap) * (slack / cap);
            score -= 12.0 * fit_quality;
        } else {
            // next item cannot follow: penalize proportionally to overshoot
            let over = (nxt - pr) / cap;
            score += 8.0 * over * over;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless it would be exceptionally tight
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * fill * fill;
    }

    // Slight penalty for scattering across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * ((pr - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // integer division into "usable" bands for typical item sizes.
    let band = post_residual / 10; // 0..=9 harmonic class
    match band {
        0 => score -= 60.0,          // near-perfect fit, tiny waste
        1 => score -= 45.0,          // excellent
        2 => score -= 25.0,          // good
        3 => score -= 10.0,          // decent
        4 => score += 5.0,           // mediocre
        5 => score += 15.0,          // poor
        6 => score += 25.0,
        7 => score += 35.0,
        8 => score += 45.0,
        _ => score += 55.0,          // nearly empty bin being used wastefully
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 + 40.0 * tightness;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            // near-miss: mildly penalize blocking the next item
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins that are already partially filled
        score += 8.0 * (fitting_bins_count as f64).ln();
    }

    // Penalize creating dead space relative to the mean residual of open bins:
    // leaving a residual far below the mean means this bin becomes an outlier
    // of unusable scraps.
    let dead = mean_residual - post_residual as f64;
    if dead > 0.0 {
        score += dead * 0.35;
    } else {
        score += dead * 0.15; // small reward for staying above mean
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Opening a new bin is only attractive for large items that would wreck an
    // almost-full bin, or when many bins compete (fragmentation risk).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        // default: discourage opening new bins
        score += 70.0;
        // large items: opening fresh space is more acceptable
        score -= 90.0 * fill_fraction.max(0.0);
        // late in the stream with many open bins, consolidation matters more
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // many fitting bins => prefer reusing; further discourage new bins
        score += 6.0 * fitting_bins_count as f64;
        // if the next item is large and nothing else would fit it, a fresh bin
        // with room for both is attractive
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 25.0;
        }
    }

    // Mild global pressure: fewer open bins => tighter packing preferred.
    score -= 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (non-linear quadratic ramp).
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 0.6;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Sweet-spot residuals (usable for medium items) get a mild reward.
    if post_residual >= 30 && post_residual <= 70 {
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // Penalize if next item is large and post residual leaves an awkward gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing bins,
    // making the new-bin candidate less attractive.
    score += (open_bins_count as f64) * 0.8;
    score += (bin_residual == bin_capacity) as i32 as f64 * (30.0 + (open_bins_count as f64) * 1.5);

    // Late in the stream, tighten up: prefer compact placements.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Deviation from mean residual: prefer bins with residual close to item
    // (good fit) rather than outliers.
    score += ((bin_residual as f64 - item_size as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: reward tight packing.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item exactly fits the post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item still fits here afterwards: mild reward proportional
            // to how much slack remains for a third item.
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space,
            // more strongly when the leftover is small (unusable).
            let waste = post_residual as f64;
            let unusable = if waste < 10.0 { 150.0 } else { 0.0 };
            score += unusable + 0.3 * waste;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    // (best-fit style), penalize placing into already-loose bins.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 30.0 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current
    // placements are poor (large post_residual relative to next item).
    if bin_residual == bin_capacity {
        score += 250.0;
        // But allow opening when no open bin chains with the next item well.
        if next_item_size > 0 && post_residual == bin_capacity - item_size {
            // fresh-bin post_residual = capacity - item; check chain potential
            if bin_capacity - item_size >= next_item_size {
                score -= 100.0;
            }
        }
    }

    // Late in the stream, consolidate: discourage new bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 100.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to lookahead; worse the closer post_residual is to a "just misses" band.
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.35 * miss;
        } else {
            // Reward leaving room exactly usable by the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 3.0 * (-slack / 15.0).exp();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        let mean_r = mean_residual.max(0.0);
        // New bin is acceptable only if mean residual across open bins is small (they're all full-ish).
        let mean_usable = mean_r / (item_size as f64).max(1.0);
        score += 18.0 + 6.0 * open_pressure + 10.0 * (1.0 - progress) - 14.0 * (1.0 - (-mean_usable).exp());
        // If no open bin can fit at all, opening is inevitable: soften penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Slight preference for filling bins that are already mostly consumed.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 5.0 * fill;
        // Prefer bins whose residual is close to item_size (exact-fit shaping).
        let gap = (bin_residual - item_size) as f64;
        score -= 6.0 * (-gap / 10.0).exp();
    }

    // Mild time-horizon coupling: early in the stream, be more conservative with residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);

    // Penalize creating residuals in the awkward 1..=9 range (hard to fill later).
    if post_residual >= 1 && post_residual <= 9 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits, with a non-linear polynomial in x modulated by progress.
    // Early on, waste is cheap (many items left to fill gaps); later, waste is costly.
    let waste_penalty = x * x * (1.0 + 2.0 * progress) + x * progress;

    // Reward near-perfect fits smoothly (small post_residual gets extra discount).
    let tight_bonus = -(1.0 - x).powi(4) * (1.5 + progress);

    // Lookahead coupling: if the next item fits exactly in the post residual, reward.
    let lookahead = if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        -0.8 * (1.0 - gap).powi(3)
    } else {
        0.0
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -2.0 } else { 0.0 };

    // Mild penalty for leaving residuals that match no plausible item size band,
    // approximated smoothly: dead space is residual far from multiples of small sizes.
    let dead = (x - (x * 4.0).round() / 4.0).abs() * progress;

    // Slight preference to spread load when many bins are open.
    let spread = 0.1 * (open_bins_count as f64).ln().max(0.0) * x;

    let mut score = pr + waste_penalty * cap * 0.5 + dead * cap
        + tight_bonus * cap + lookahead * cap + last_chance + spread;

    // New-bin candidate: empty bin has zero tightness; make it mildly unattractive
    // unless residuals everywhere are bad (encoded via mean_residual comparison).
    if bin_residual == bin_capacity {
        let openness = ((mean_residual / cap) - 0.5).max(0.0);
        score += 3.0 - 4.0 * openness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: minimize post_residual (tight fit preference)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Strong penalty for dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    }

    // Harmonic class of post_residual: reward residuals in "useful" bands
    let class = post_residual / 10; // integer division classes 0..10
    let class_bonus: f64 = match class {
        0 => -40.0,                    // perfect fit
        1 => -18.0,                    // small gap, still fillable by tiny items
        2 | 3 => -8.0,                 // medium gap
        4 | 5 | 6 => 0.0,              // half-ish residual
        _ => 6.0,                      // large residual: bin stays flexible
    };
    score += class_bonus;

    // Lookahead: if next item fits into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size as f64;
            score -= 25.0 + 0.5 * slack_after_next;
            // exact chaining (item+next fill bin completely)
            if post_residual == next_item_size {
                score -= 35.0;
            }
        } else {
            // next item won't fit here; penalize leaving a big awkward gap
            let gap = post_residual - (next_item_size as f64 - 1.0);
            if gap > 20.0 {
                score += 0.3 * gap;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is bad if a good fit exists elsewhere;
        // neutral baseline plus penalty scaled by how many bins could fit.
        score = 0.55 * cap + 15.0 * (fitting_bins_count as f64);
        // Late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If next item is huge and this bin is fresh, fresh bin is attractive
        if next_item_size >= 60 && post_residual == 0 {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score -= 0.15 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post / cap);

    // Deviation from mean residual: prefer bins whose residual is shrinking toward mean
    score += 0.1 * (post - mean_residual).abs();

    // Modulo harmonic: residuals congruent to 0 mod 20 align with common item sizes
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 15.0;
    } else if post_residual > 50 {
        score += 5.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual tightly matches the item (waste = residual - item).
    let waste = bin_residual as f64 - item_size as f64;
    score += 0.3 * waste;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer compacting.
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: if this bin's post residual is far below mean, it's a good compaction.
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size <= 5 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else {
            score += 30.0 + 2.0 * open_bins_count as f64; // prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual: bins tighter than average are more valuable to fill
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= 0.8 * (mean_residual - resid);
    } else {
        score += 0.3 * (resid - mean_residual);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no existing bin fits well
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 60.0 };
        score += 30.0 + poor_fit_penalty + 0.5 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 100.0; // opening a bin is fine when alternatives are scarce
        }
    }

    // Mild late-stream consolidation: prefer tight packing as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * resid * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space that no future item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
        // Perfect chain: next item exactly fills the leftover
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: prefer fullest packing
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer compacting into fuller bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 3 {
        score += 0.4 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mean residual coupling: if this bin is much emptier than average, penalize slightly
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 18.0 + 10.0 * fit_ratio;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate larger residuals; later, punish dead space quadratically.
    let pr_norm = pr / cap;
    let progress_poly = 0.5 + 1.5 * progress * progress;
    score += 40.0 * pr_norm * pr_norm * progress_poly;

    // Reward tight fits: fraction of bin consumed by this item, amplified non-linearly.
    let fill = it / cap;
    score -= 30.0 * fill * fill;

    // Exact-fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: reward if next item fits in the post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (nx / cap) * (1.0 - progress);
        } else {
            // Penalize leaving a residual too small for the next item late in the stream.
            let gap = (nx - pr) / cap;
            score += 15.0 * gap * gap * (0.5 + progress);
        }
    }

    // Prefer bins whose residual is below the mean residual (denser bins first).
    score += 5.0 * ((bin_residual as f64) - mean_residual) / cap;

    // Slight penalty for spreading across many open bins.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: keep its baseline high unless tight fit is impossible elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: harmonic class where post_residual is a multiple of small units.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual % 10 == 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 7.0;
    } else {
        // penalize awkward residuals by their distance to nearest multiple of 5
        let d = (post_residual % 5).min(5 - post_residual % 5) as f64;
        score += d * 2.0;
    }

    // Integer division thresholds on post_residual: small dead space is bad (unusable).
    let cap_frac = bin_capacity as f64;
    let pr = post_residual as f64;
    if pr < cap_frac * 0.1 {
        score += 12.0; // tiny sliver wasted
    } else if pr < cap_frac * 0.25 {
        score += 4.0;
    } else if pr < cap_frac * 0.5 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item exactly fits remaining residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual && (post_residual - next_item_size) % 10 == 0 {
            score -= 40.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; mild penalty proportional to waste class
            let waste_class = (next_item_size - post_residual) / 20;
            score += waste_class as f64 * 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only prefer fresh bin when existing fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0; // base cost of opening a bin
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Mean residual alignment: prefer bins whose residual is close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Many open bins: encourage closing bins out (fill tighter).
    if open_bins_count > 4 {
        score -= 1.5;
    }

    // Harmonic class of item: large items (>= half capacity) prefer tight fills.
    if item_size * 2 >= bin_capacity {
        score -= (post_residual as f64).min(20.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (dead zone below ~20 units).
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (1.0 - post_residual as f64 / 20.0);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is good.
    score += 1.5 * open_bins_count as f64 * tightness;

    // Mean residual coupling: placing in a bin far below mean residual wastes
    // the large residual; prefer bins near the mean.
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (i.e., this empty-bin call) — otherwise penalize.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin, reduced early in the stream.
        score = 100.0 + 50.0 * (1.0 - progress);
        // If next item is large, a fresh bin can be valuable.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap that the next item cannot use is doubly wasteful.
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // 2-step lookahead: reward when next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 22.0 / (1.0 + slack * 0.08);
        if slack < 5.0 {
            score -= 18.0; // near-perfect 2-step chain
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the next item: penalize proportionally.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.45 * dead;
        if post_residual < next_item_size / 2 {
            score += 12.0; // residual likely unusable for next item
        }
    }

    // Compare against mean residual: bins far below mean are "wasted" targets.
    let dev = (bin_residual as f64 - mean_residual) / (mean_residual + 1.0);
    score += 6.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: prefer only when no open bin offers a good chain fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin supports perfect lookahead chain
        }
        if fitting_bins_count <= 1 {
            score -= 60.0; // no real alternative, allow new bin
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;

    // Lookahead: if the leftover residual exactly accommodates the next item,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Leftover usable by next item: mild reward proportional to slack.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize dead space, worse when
            // the dead space is tiny (irrecoverable).
            let dead = post_residual as f64;
            score += 15.0 * (1.0 - dead / bin_capacity as f64);
        }
    } else {
        // Last item: any residual is pure waste; prefer exact fills.
        score += 30.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when open
    // bins have large mean residual (fragmentation) or few bins fit the item.
    if bin_residual == bin_capacity {
        // Penalize new bins by default.
        score += 20.0;
        // But if open bins are highly fragmented (mean residual small relative
        // to item), opening fresh is reasonable.
        let frag = item_size as f64 / mean_residual.max(1.0);
        score -= 30.0 * frag.min(1.0);
        // Few alternatives: new bin less bad.
        score -= 8.0 / fitting_bins_count.max(1) as f64;
        // Early in stream, tolerate new bins; late in stream, consolidate.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - t) - 10.0 * t;
        // If next item is large and this bin would be nearly filled, new bin fine.
        if next_item_size >= item_size && post_residual <= 10 {
            score -= 12.0;
        }
    }

    // Discourage spreading across too many open bins when mean residual is high:
    // prefer filling bins that are already well loaded relative to average.
    let rel_load = (bin_capacity as f64 - bin_residual as f64)
        / (bin_capacity as f64 - mean_residual).abs().max(1.0);
    score -= 6.0 * rel_load.min(2.0);

    // Mild penalty for leaving residuals in the awkward 1..=10 range (hard to fill).
    if post_residual >= 1 && post_residual <= 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
