    let tightness = 1.0 - pr / cap; // ~1 for perfect fit
    score -= 12.0 * tightness * tightness;

    // Penalize residuals that are too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 - pr / 10.0);
    }

    // Non-linear stream-progress coupling: later in stream, prefer tighter packing (waste penalized more).
    let prog_term = progress * progress;
    score += prog_term * pr * 0.35;
    score -= prog_term * 6.0 * tightness;

    // If this is the only fitting bin, strongly favor using it (last-chance effect).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying with stream progress and open bins.
        let mut open_cost = 10.0 + 0.25 * open_bins_count as f64;
        open_cost *= 1.0 - 0.5 * progress;
        // If a large chunk of the new bin would remain and no lookahead synergy, discourage.
        let waste = pr / cap;
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt <= pr {
                open_cost -= 4.0; // lookahead fits in the fresh bin
            } else {
                open_cost += 3.0;
            }
        }
        score += open_cost;
        score += 5.0 * waste;
    } else {
        // Existing bin: slight preference for bins whose residual deviates from mean (consolidate waste).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Lookahead: if next item fits in resulting residual, reward.
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by residue classes.
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are "harmonically useful" (small, or classic gap sizes)
    match class {
        0 => score -= 12.0,                       // multiple of 10: reusable
        1 | 2 | 3 => score += 4.0,                // awkward slivers
        4 | 5 | 6 => score += 1.5,                // moderate
        _ => score -= 3.0,                        // 7..9 pair well with 10..30 items
    }

    // Integer-division thresholds: reward near-perfect fits.
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;                  // quadratic fill reward

    if pr == 0 {
        score -= 50.0;                            // perfect closure
    }

    // Lookahead coupling: does post_residual admit next_item_size?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;                         // kills the lookahead
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets baseline score;
    // discourage opening when good fits exist, encourage when residuals are fragmented.
    if bin_residual == bin_capacity {
        score = 45.0
            + mean_residual * 0.3
            + (open_bins_count as f64).ln().max(0.0) * 4.0
            + (pr as f64); // = capacity residual, harmonic-neutral baseline
    }

    // Slight preference for consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit typical items are wasted.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
        score -= tightness * item_size as f64 * 0.6;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading (favor new bin when fills are poor).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits perfectly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item cannot fit in post residual but would fit elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size <= bin_capacity {
        score += 5.0;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean (balanced packing),
    // penalize outliers that create fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: attractive early or when remaining item stream is long and fits are bad;
    // discourage when the bin is nearly full anyway (opening new bins too eagerly wastes bins).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) < dead_threshold || (fitting_bins_count <= 1 && bin_residual != bin_capacity);
        let base = bin_capacity as f64 * 0.85;
        if poor_fit {
            score = score.min(base - 10.0);
        } else {
            score = base + progress * 10.0 + open_bins_count as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item's size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // chain perfectly: item fills bin, next item fills remainder
        } else {
            score += diff as f64 * 0.6; // penalize mismatch between leftover and lookahead
        }

        // Reward if next item fits exactly in the current bin's residual BEFORE placement
        // (i.e., current item leaves room for nothing useful but bin was near-perfect anyway)
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 8.0; // next item would have fit here; we broke a potential pairing
        }
    } else {
        // Last item: just minimize waste
        score += 5.0;
    }

    // Relative-to-mean residual shaping: prefer bins whose post_residual
    // sits below the open-bin average (tighter packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(40.0) * 0.25;
    } else {
        score += (pr - mean_residual).min(40.0) * 0.15;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred...
        score += 30.0;
        // ...unless item is large relative to capacity and open bins are crowded.
        let load = item_size as f64 / bin_capacity as f64;
        if load > 0.7 || open_bins_count > 12 {
            score -= 35.0;
        }
    }

    // Slight bias toward filling bins proportionally as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: prefer minimal post_residual.
    let t = step_index as f64 / (total_items.max(1) as f64);

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no plausible future item can use:
    // small odd residuals (< 10) are near-useless waste.
    if post_residual < 10 {
        score += 6.0 * (10 - post_residual) as f64;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // mild reward proportional to how well next item uses the leftover
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // leftover too small for next item: penalize proportionally to waste
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (large post_residual everywhere) or many bins are already open.
        let poor_fits = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64
            - 15.0 * poor_fits
            - 2.0 * mean_residual / bin_capacity as f64
            - 10.0 * t;
        // Late in the stream, prefer consolidating into open bins.
        if t > 0.7 {
            score += 8.0;
        }
    }

    // Mild global pressure: with many open bins, favor reusing existing space.
    score += 0.05 * open_bins_count as f64;

    // Early stream: slight preference for balancing residuals toward the mean.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let prog_sq = progress * progress;
    score += 12.0 * pr_norm * pr_norm * (0.5 + prog_sq);

    // Reward tight fits (small post_residual) more strongly later in stream
    let tightness = 1.0 - pr_norm;
    score -= 10.0 * tightness * tightness * (0.3 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += 6.0 * (1.0 - pr / nxt) * (1.0 + progress);
        } else if pr >= nxt {
            score -= 4.0 * (pr / cap) * (nxt / cap);
        }
    }

    // Last-chance bin bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize unless current bins are mostly full
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 15.0 * (0.4 + mean_fill) * (1.0 - 0.5 * progress);
        if post_residual < item_size as f64 {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by small
    // denominators are more reusable by future items.
    let pr = post_residual;
    let harmony = if pr == 0 {
        -6.0
    } else if pr % 10 == 0 {
        -2.0
    } else if pr % 5 == 0 {
        -1.0
    } else if pr % 2 == 0 {
        -0.5
    } else {
        0.5
    };
    score += harmony;

    // Dead space penalty: residuals too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // If the lookahead item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && pr >= next_item_size {
        let slack = (pr - next_item_size) as f64;
        score -= 3.0 - 0.05 * slack;
        // Perfect chaining: next item fills bin completely.
        if pr == next_item_size {
            score -= 4.0;
        }
    }
    // Lookahead item would leave this residual nearly dead.
    if next_item_size > pr && next_item_size > 0 && pr < 10 {
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: penalize unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        score = 30.0 + fragmentation * 0.3 - (open_bins_count as f64) * 0.1;
        if fitting_bins_count == 1 {
            score += 10.0; // don't open a new bin when a last-chance bin exists
        }
    }

    // Mild tightness bonus: filling a bin closer to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 2.0;

    // Slight preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Dead space that cannot even fit the smallest possible item is worst.
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }
    // Penalize if post_residual is a trap: too small for next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: prefer reusing bins when many are open.
    score -= 2.0 * open_bins_count as f64;

    // Mean residual coupling: prefer bins below mean residual (denser bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin, but less when no open bin
    // fits well (post_residual of empty bin = capacity - item_size is large anyway).
    if bin_residual == bin_capacity {
        score += 35.0;
        // If many bins are open, opening new bins is more wasteful.
        score += 1.5 * open_bins_count as f64;
        // If this is the only fitting candidate, reduce the penalty.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // Slight stream-progression tilt: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match: next item fills this bin completely.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score -= 25.0 / (1.0 + diff);
        }
        // Penalize leaving residual that neither fits the next item nor is tiny.
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins whose residual is below average (tighter bins first).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating large dead space relative to capacity.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Early in stream, be slightly more willing to open new bins for big items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus small bonus late when open bins are scarce.
        score += 5.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space: residuals too small for the smallest plausible item.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fill, likely unusable otherwise
    } else {
        // Larger post_residual is mildly penalized beyond the base value.
        score += 0.05 * (post_residual as f64).sqrt();
    }

    // Lookahead coupling: reward bins whose post_residual pairs with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // exact pair
        } else if post_residual >= next_item_size {
            score -= 10.0; // next item still fits here
        } else {
            score += 5.0; // next item won't fit after this placement
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones.
    let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 2.0 * crowd;

    // Time horizon: early in stream, be more open to new bins; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when item is large relative to mean residual.
        let item_rel = item_size as f64 / bin_capacity as f64;
        let mean_rel = mean_residual / bin_capacity as f64;
        let openness = (1.0 - progress) * 20.0 + item_rel * 30.0 - mean_rel * 40.0;
        score += 60.0 - openness.max(0.0);
        // If no open bin can fit, new bin is the fallback (fitting_bins_count==0).
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: later in stream, discount more.
        score -= progress * 10.0;
    }

    // Mean residual coupling: bins far below mean residual are worth filling.
    let dev = mean_residual - post_residual as f64;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * progress * progress;
    score += 20.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += 0.15 * gap * (1.0 + progress);
    }

    // Last-chance bin bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // Discourage opening new bins unless residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score += 12.0 - 20.0 * fragmentation * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: fraction of capacity in coarse buckets
    let post_frac = post_residual as f64 / cap;
    let class = (post_frac * 8.0).floor(); // 0..7 harmonic classes of dead space

    // Penalize leftover space nonlinearly — small leftovers are worthless
    score += match class {
        0.0 => -12.0,   // near-perfect fill (post_residual tiny)
        1.0 => -6.0,
        2.0 => 0.0,
        3.0 => 2.0,
        4.0 => 5.0,
        5.0 => 8.0,
        6.0 => 11.0,
        _ => 13.0,
    };

    // Lookahead coupling: reward if next item fits exactly into the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        let tight = 1.0 - slack / cap;
        score -= 10.0 * tight * tight;
        // extra reward for exact harmonic match (next item fills a class boundary)
        if post_residual == next_item_size {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover can't host the next item: penalize proportionally to wasted potential
        score += 3.0 * post_frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Many open bins with high mean residual: discourage spreading, favor tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) > mean_residual {
        score += 2.0 * progress;
    } else {
        score -= 1.5 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted early when few bins are open
        score = cap * 0.55 + 10.0 * (open_bins_count as f64).sqrt() - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 4.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize unusable small gaps (dead space nothing can fill, sizes >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Moderate penalty for medium gaps that only tiny items can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // Wasted gap: next item cannot use it.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Pressure against opening new bins when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus open-bin pressure.
        score += 150.0 + open_bins_count as f64 * 20.0 * (0.4 + 0.6 * progress);
        // If an existing bin is a tight fit, prefer it over a new bin.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Mild preference for filling bins that are already quite full.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fullness * 15.0;
    }

    // Prefer bins with below-mean residual (tighter bins get priority).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // prefer post_residual close to next_item_size (tight 2-step chain)
            score -= 60.0 + (post_residual - next_item_size) as f64 * -0.3;
        } else {
            // penalize dead space the next item cannot use
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // exact chain: post_residual == next_item_size leaves zero after two placements
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else {
        // last item: any fit is fine, prefer tightest
        score -= 50.0;
    }

    // Relative to mean residual: prefer bins with residual above mean (larger holes)
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += rel * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, more so if good fits exist
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0; // allow opening when a fresh pair-packing is plausible
        }
    }

    // Late in stream: consolidate, avoid proliferation of open bins
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: only remaining open bin that fits
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins whose residual is tighter than the fleet average
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Penalize tiny unusable dead space (worse than a clean zero)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate handling: default reluctance, relax when fits are scarce
    if is_new_bin {
        score += 40.0;
        if fitting_bins_count <= 1 {
            score -= 60.0;
        } else if fitting_bins_count == 2 {
            score -= 20.0;
        }
        // Late in the stream, avoid spawning bins that will strand space
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild pressure to close out crowded fleets
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap; // in [0,1]
    let t = progress;
    // Smooth interaction: waste penalized more heavily early, dead-space quadratic term
    score += norm_pr * norm_pr * cap * (0.6 + 0.8 * t);

    // Reward tight fits: subtract a smooth function of item fraction and progress
    let fill = item_size as f64 / cap;
    score -= fill * fill * cap * (0.9 - 0.4 * t);

    // Penalize opening a new bin when open bins exist and item fits elsewhere
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += cap * (0.35 + 0.65 * (1.0 - t)) * (1.0 - fill);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * (0.5 + 0.5 * t);
    }

    // Coupling with mean residual: avoid bins far from the mean (fragmentation)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * cap * 0.5;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= (next_item_size as f64) * (0.3 + 0.4 * t);
    } else if next_item_size > 0 {
        score += (next_item_size as f64) * 0.15 * (1.0 - t);
    }

    // Mild scaling by number of open bins to encourage consolidation
    score *= 1.0 + 0.02 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual buckets by capacity fraction.
    // Small post_residuals (< smallest possible item) are dead space -> penalize.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 5.0;
    }

    // Integer-division class of post_residual: how many more "typical" items fit.
    let typical = 25u32;
    let fits_more = post_residual / typical;
    score -= fits_more as f64 * 12.0;

    // Modulo arithmetic: reward residuals that are friendly to common size classes.
    // Sizes 1..100; residue classes mod 10 and mod 25 matter for tight packing.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits but not perfectly: mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0);
        } else {
            // next item cannot use this bin's remainder: penalize wasted potential
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
        if post_residual < dead_threshold {
            score += 30.0; // still bad if it creates dead space
        }
    }

    // New-bin candidate: neutral-ish baseline; open a new bin when the fit is poor
    // or when many open bins have large mean residual (fragmentation).
    if bin_residual == bin_capacity {
        // baseline: new bin has full 100 residual, score starts at 100 via post_residual
        // penalize opening new bins when a decent fit exists elsewhere
        if fitting_bins_count > 0 {
            let best_possible = (bin_capacity - item_size) as f64;
            let frag = (mean_residual - post_residual as f64).abs();
            if post_residual as f64 >= mean_residual - 10.0 && frag < 25.0 {
                score += 120.0; // discourage new bin when an open bin fits comparably
            }
            let _ = best_possible;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
    } else {
        // prefer bins whose residual is close to the item (tight fit)
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.15;
    }

    // Prefer filling bins when many are open (limit sprawl).
    score += open_bins_count as f64 * 0.5;

    // Slight preference for earlier bins (stability), scaled by mean residual.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the smallest
    // possible item are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 45.0;
    } else if post_residual < 30 {
        score += 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item would leave dead space, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            let gap_after_next = post_residual - next_item_size;
            if gap_after_next < 10 {
                score += 25.0;
            }
        } else {
            // next item cannot use this bin's leftover; leftover likely dead
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many open bins,
    // favor consolidating into fewer bins when fit is decent.
    let pressure = open_bins_count as f64 * 1.5;
    score -= pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: mild penalty so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
    }

    // Stream progression: as the stream advances, tighten dead-space tolerance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect or near-perfect match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 40.0; // exact 2-chain fit
        }
        // Penalize leaving a residual that cannot fit the next item (dead space)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize wasteful residuals relative to mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing fits are poor (large post_residual).
    if bin_residual == bin_capacity {
        score = 70.0 + post_residual as f64 - 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.1 * next_item_size as f64;
        }
    }

    // Slight late-stream tightening: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize waste relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * (item_size as f64 / bin_capacity as f64);

    // Penalize small dead space that nothing (min item 1, but practically >10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many fitting bins: prefer the one leaving residual closest to mean_residual
    // (keeps bin fleet homogeneous, easier future packing).
    if fitting_bins_count > 1 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
        score -= 2.0; // mild bonus for having alternatives
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overflow.
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and fits poorly everywhere, or fleet is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fitting_bins_count == 1 && bin_residual - item_size > 30;
        let big_item = item_size as f64 / bin_capacity as f64 > 0.6;
        if poor_fit || (big_item && open_bins_count > 3) {
            score -= 20.0 + 15.0 * progress;
        } else {
            // Discourage opening new bins when existing ones can absorb the item.
            score += 35.0 + 5.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Late in the stream: consolidate, prefer reusing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize post_residual, but with non-linear (quartic) shaping
    // so small residuals are heavily favored (tight packing).
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tolerating residual waste becomes more costly.
    let progress_coupling = (1.0 + progress * progress * progress * 3.0);
    score *= progress_coupling;

    // Interaction: post_residual vs mean residual across open bins.
    // A bin whose post-residual deviates strongly from the mean residual
    // creates heterogeneity; mildly penalize large positive deviations.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * cap * 0.05 + 4.0 * dev.max(0.0);

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // strongly reward this placement (perfect chained fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let slack = (pr - nxt).max(0.0);
        // reward near-exact chaining, penalize leaving space just larger than next item
        score -= (1.0 - gap / cap).max(0.0) * 6.0 * (1.0 - progress * 0.5);
        score += 3.0 * (slack / cap) * (slack / cap) * cap * 0.1;
    }

    // Last-chance bin: strongly reward using the only fitting bin
    // (avoids opening a new bin unnecessarily).
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Prefer filling nearly-full bins: smooth sigmoid-like bonus on fill ratio
    let fill = 1.0 - norm_pr;
    score -= 5.0 * (fill * fill * fill);

    // Mild penalty when many bins are open and this bin is relatively empty:
    // encourages consolidating into existing fuller bins.
    let emptiness = 1.0 - (bin_residual as f64 / cap);
    score += open_bins_count as f64 * 0.3 * emptiness;

    // New-bin candidate handling: empty bin has high post_residual; make it
    // attractive only when no open bin offers a tight fit (its raw score is
    // naturally high, but add a small calibrated offset so it is chosen when
    // the best existing fit still leaves substantial waste).
    if bin_residual == bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space penalty grows for residuals that are "hard to fill".
        // Class A: tiny residuals (1..=5) are near-perfect, mildly rewarded.
        if post_residual <= 5 {
            score -= 25.0;
        }
        // Class B: residuals in the "awkward band" (6..=19) rarely refilled -> penalize.
        if post_residual >= 6 && post_residual <= 19 {
            score += 12.0;
        }
        // Class C: large residuals are flexible -> mild reward scaled by fraction.
        let frac = post_residual as f64 / bin_capacity as f64;
        if post_residual >= 40 {
            score -= 10.0 * frac;
        }
        // Modulo-10 harmonic: residuals divisible by 10 align with typical item sizes.
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let nxt_frac = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * (1.0 - nxt_frac);
        } else {
            // Next item won't fit here; penalize leaving large unusable gaps.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit (this call has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheaper to open a bin early when few bins are open (spreading load).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress) * (open_bins_count as f64).recip().max(0.1);
        // If mean residual across open bins is small, opening fresh is better.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // Perfect packing potential: item size divides capacity harmonically.
        if bin_capacity % item_size == 0 {
            score -= 10.0;
        }
    } else {
        // Prefer bins with tighter fit relative to current residual.
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 8.0 * tightness;
        // Slight preference to fill older/more-constrained bins when many open.
        if open_bins_count > 3 && bin_residual < mean_residual {
            score -= 4.0;
        }
    }

    // Early stream: encourage consolidation into few bins.
    if step_index < total_items / 4 {
        score += 2.0 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< min plausible item size)
    // are heavily penalized since no future item can ever use them.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 80.0;
    } else {
        // Reward tight fits proportionally (small post_residual among usable ones).
        score -= 0.6 * (bin_capacity as f64 - post_residual as f64);
    }

    // Coupling with mean residual: prefer bins whose residual is already below
    // average (i.e., we are consuming a "nearly full" bin rather than a loose one).
    score += 0.4 * (mean_residual - bin_residual as f64).max(-40.0).min(40.0);

    // Open-bin pressure: when many bins are open, discourage spreading; slightly
    // prefer filling existing bins, but when few bins are open, allow new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item would fit exactly in the post_residual,
    // reward leaving that gap; if the gap is just barely unusable for it, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual, so the
    // base score already discourages it; add a mild penalty so a fresh bin is
    // chosen only when no decent fit exists (all fits are poor/dead-space-y).
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if no open bin can fit the item at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Post residual can still host next item: mild reward proportional to tightness.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 * tight;
        } else {
            // Next item won't fit in the leftover: penalize dead space more strongly.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Favor bins whose residual is small relative to the mean (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize opening a brand-new bin when good fits exist, unless residual is tiny.
    if bin_residual == bin_capacity {
        // New bin baseline: slightly worse than a decent existing fit.
        score += 25.0;
        // But if the item nearly fills a fresh bin, opening is attractive.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 50.0;
        }
    }

    // Mild preference for filling bins more completely early vs late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward placements that leave little residual (non-linear).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 60.0 * tightness.powf(1.5);

    // Penalize creating dead space that is likely unusable.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress); // small slivers are worse early
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // next item won't chain here
        }
    } else {
        // Last item: strongly prefer filling any bin completely.
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the fit
    // in existing bins is poor or many bins are already open with big residuals.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        let poor_fit_bonus = 45.0 * (1.0 - tightness) + spread * 0.3;
        let congestion = (open_bins_count as f64).ln() * 6.0;
        score += poor_fit_bonus - congestion;
        // Late in the stream, prefer consolidating into open bins.
        score += 20.0 * progress;
    }

    // Mild preference for bins with residuals close to the mean (balance load).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling: tight fits are rewarded increasingly
    // as the stream progresses (endgame packing pressure).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64).powf(2.0);
    score -= 40.0 * tightness * (0.5 + 0.5 * progress) * (1.0 + 0.5 * (1.0 - progress));

    // Quadratic penalty for residual relative to the mean residual of open bins:
    // bins whose leftover will deviate strongly from the fleet mean are risky.
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 15.0 * dev * dev;

    // Lookahead: reward residuals that can host the next item exactly or closely.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - (fit_gap / bin_capacity as f64).powf(2.0));
    } else if next_item_size > post_residual {
        // Residual too small for the next item: penalize dead space non-linearly.
        score += 10.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64).powf(1.5);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        let poor_fit = (item_size as f64 / bin_capacity as f64).powf(2.0);
        score = bin_capacity as f64 * (0.9 + 0.4 * progress)
            - 30.0 * crowding * (1.0 - poor_fit)
            - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty on opening pressure late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a small remainder
    // (hard to reuse) vs. a large chunk (easy to reuse).
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Penalize residuals in "awkward" classes: small leftovers < 10 can
    // never fit any typical item; reward residuals that are multiples of
    // common size classes (harmonic buckets of capacity).
    if post_residual < 10 {
        score += 25.0; // unusable dead space
    } else if post_residual % 10 == 0 {
        score -= 6.0; // aligned residual, reusable by decile-sized items
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Non-linear waste term: quadratic penalty on large residuals that
    // fragment capacity (favor tight fits, i.e. small post_residual).
    score += 0.05 * (post * post) / cap;

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly reward this placement (perfect pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills leftover
            score -= 10.0 * (next_item_size as f64 / post.max(1.0));
        } else {
            // leftover won't host next item: mild penalty scaled by waste
            score += 4.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    // (item leaves big residual everywhere) or few bins fit.
    if bin_residual == bin_capacity {
        // opening a new bin wastes the residual of existing fitting bins
        let avg_fit_waste = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0)
        } else {
            0.0
        };
        score += 45.0 - 0.5 * avg_fit_waste - 2.0 * open_bins_count as f64;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // mild bonus for filling existing bins tighter than the mean
        score -= (mean_residual - bin_residual as f64) * 0.15;
    }

    // Integer-division threshold: prefer placements where item fills at
    // least half the bin's current residual (good space utilization).
    if item_size * 2 >= bin_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any plausible future item
    // (items >= 1, but small gaps are still waste) get a superlinear penalty.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: post_residual close to but below next item size is bad
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 6.0; // this residual can't host the lookahead item
    }
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0; // bin stays useful for the lookahead item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += 15.0 + bin_pressure * 2.0;
    } else {
        score -= bin_pressure * 0.3;
    }

    // Prefer bins whose residual deviates from mean residual (consolidate waste)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills remaining space
            if post_residual == next_item_size {
                score -= 1000.0;
            } else {
                // Reward proportional to how small the leftover after the next item would be
                let leftover_after_next = post_residual - next_item_size;
                score -= 60.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
            }
        } else {
            // Penalize residuals that are just barely too small for the next item (dead space)
            let miss = (next_item_size - post_residual) as f64;
            score += 0.8 * miss;
        }
    }

    // Penalize large dead residuals relative to mean residual across open bins
    let residual_gap = post_residual as f64 - mean_residual;
    score += 0.25 * residual_gap.max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bin would leave awkward tiny residual
    if bin_residual == bin_capacity {
        let awkward = (post_residual as f64) < 10.0 && post_residual > 0;
        if awkward {
            score -= 40.0; // nearly full after placement is fine
        } else {
            score += 55.0; // discourage spreading items into fresh bins
        }
    }

    // Slight preference to keep number of open bins low early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress) * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (wasted space dominates).
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 60.0;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward using an open bin (avoid opening new bins when fit is decent).
    if bin_residual != bin_capacity {
        score -= 25.0;
    } else {
        // New-bin candidate: penalize, less so when many bins already open
        // or current fit would leave large dead space.
        score += 40.0;
        if post_residual as f64 > mean_residual {
            score += 15.0;
        }
        if open_bins_count > 3 {
            score -= (open_bins_count.min(20) as f64) * 1.5;
        }
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 30.0 - (gap as f64).min(30.0);
    }
    // If next item would need a new bin anyway, mild penalty for wasting residual.
    if next_item_size > post_residual && next_item_size > bin_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in stream, be conservative with new bins;
    // late in stream, prefer closing out residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean.
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let coupling = prn * prn * (1.0 - progress) * 40.0
                 + prn * progress * 25.0;
    score += coupling;

    // Penalize residual that is close to but not exactly zero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 - prn * 10.0);
    }
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 4.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Penalize opening a new bin when fitting bins exist, more so early on.
    if bin_residual == bin_capacity {
        let open_penalty = 20.0 + 30.0 * (1.0 - progress);
        score += open_penalty;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // A fresh bin is attractive if all open residuals are small.
        score -= (mean_residual / bin_capacity as f64) * 15.0;
    }

    // Mean-residual alignment: prefer bins near the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 10.0 * dev * dev;

    // Slight preference for tighter fits via item/bin ratio.
    score += 5.0 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class: dead space that cannot fit typical future items is worse.
    // Classify post_residual by capacity fraction buckets.
    let pr = post_residual as f64;
    let frac = pr / cap;
    if frac > 0.0 && frac < 0.10 {
        score -= 15.0; // small dead space, acceptable
    } else if frac < 0.20 {
        score += 5.0; // awkward mid-low residual
    } else if frac < 0.35 {
        score += 12.0; // large dead space penalty
    }

    // Lookahead: reward residuals that can host the next item exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack.min(20.0) * 0.4;
        if slack == 0.0 {
            score -= 25.0; // perfect chain fit
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // residual can't host next item: penalize proportionally to wasted class
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full or crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / cap;
        // prefer new bin when existing bins are well filled or too many open bins
        score = 40.0 - avg_fill * 45.0 - open_bins_count.min(20) as f64 * 1.5 - progress * 10.0;
        // opening new bin is bad if a last-chance bin exists elsewhere
        if fitting_bins_count == 1 {
            score += 35.0;
        }
    }

    // Mild preference for bins below mean residual (balance spreading)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the fuller the bin becomes, the better.
    let fill = (bin_capacity - post_residual) as f64;
    score -= 0.6 * fill;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Pressure from number of open bins: mildly discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No existing bin fits: opening a new bin is fine.
            score -= 60.0;
        } else {
            // Some bin fits: penalize opening a new one, more if existing residuals are wasted.
            let waste = (mean_residual - item_size as f64).max(0.0);
            score += 25.0 + 0.6 * waste + 6.0 * fitting_bins_count as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit this item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead (k=2): reward if the next item can also fit in the leftover space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual < 10 {
            // Dead space that even the next item cannot use: extra penalty.
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills (waste minimization).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_frac).powi(6) * 40.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= (1.0 - gap / bin_capacity as f64) * 30.0;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that cannot host the next item.
        score += 15.0;
    }

    // Coupling with mean residual: bins with residual near the mean are neutral;
    // large residuals relative to mean are attractive targets.
    if mean_residual > 0.0 {
        score -= (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in the stream, prefer consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (open_bins_count as f64) * 0.5;

    // Penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // New bin is attractive if item is large relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 15.0 * (dead_threshold - post_residual as f64);
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 6.0 * (1.0 - (slack as f64) / (bin_capacity as f64));
        } else {
            // Next item won't fit here after placement; mild penalty.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive
    // only when current bins would leave large waste.
    if bin_residual == bin_capacity {
        let best_possible_waste = if post_residual == bin_residual {
            // This is the new-bin call itself.
            item_size as f64
        } else {
            0.0
        };
        let _ = best_possible_waste;
        // Base penalty so new bins are opened only when worthwhile.
        score += 12.0;
        // If many bins are open and mean residual is large, discourage new bins.
        score += 0.5 * mean_residual;
        // Early in the stream, new bins are cheaper (long horizon to fill them).
        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            0.0
        };
        score -= 10.0 * (1.0 - progress);
        // If no open bin fits well (this new bin call with many fitting bins means
        // competition), adjust via fitting_bins_count.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    } else {
        // Existing bin: slight reward when many bins compete (choose best fit).
        if fitting_bins_count > 1 {
            score -= 1.0;
        }
        // Prefer bins whose residual deviates favorably from mean (consolidation).
        let dev = (bin_residual as f64) - mean_residual;
        score -= 0.05 * dev;
    }

    // Mild time-varying exploration term to diversify placements.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= 2.0 * (std::f64::consts::PI * progress).sin() * 0.0
        + 1.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fit_frac = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Tight fit reward: strong non-linear polynomial in post_residual fraction.
    // Small post_residual (good packing) gets a large subtraction.
    let tightness = 1.0 - post_frac;
    score -= 30.0 * tightness * tightness * (1.0 + progress);

    // Penalize medium dead space (unusable leftovers) with a smooth bump
    // centered around post_residual ~ item_size/2 region: quadratic coupling.
    let dead_center = fit_frac * 0.5;
    let dead_dev = post_frac - dead_center;
    score += 12.0 * dead_dev * dead_dev;

    // Last chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward placements leaving residual close to next item size
    // (smooth quadratic attraction), penalize otherwise mildly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = post_residual as f64 - nxt;
        let norm = diff / cap;
        score += 8.0 * norm * norm - 6.0 * (-norm * norm * 40.0).exp() * (1.0 + progress);
    }

    // Stream-progress coupling: later in stream, prefer consolidating into existing bins;
    // penalize new empty bins progressively via smooth interaction with post_frac.
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (10.0 + 40.0 * progress * progress) * (1.0 - fit_frac);

    // Mild penalty proportional to open bins count to discourage sprawl,
    // interacting smoothly with mean residual (fragmented state).
    let frag = (mean_residual / cap - post_frac).abs();
    score += 0.15 * open_bins_count as f64 * frag;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: reward residuals that are "dead" (small)
    // and residuals that are perfectly reusable by common size classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 20.0;
    } else if pr <= 20 {
        score -= 8.0;
    } else {
        // residual class modulo 10: multiples of 10 are more reusable
        if pr % 10 == 0 {
            score -= 6.0;
        } else {
            score += (pr % 10) as f64 * 0.5;
        }
    }

    // Lookahead: strongly reward leaving room exactly for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot fit here: penalize proportionally to wasted hope
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or all existing fits are terrible. Penalize default new bin.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 30.0 - 25.0 * fill;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can also host the next item
        }
    }

    // Prefer filling bins tighter than the mean residual (reduce fragmentation).
    score += 0.5 * ((post_residual as f64) - mean_residual).max(0.0);

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..100 range, but typical min ~10) are wasted space.
    let dead_threshold = 8.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is the ideal outcome: strong reward.
        score -= 80.0;
    }

    // Tightness reward: the smaller the post_residual relative to item,
    // the better the fit density.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 12.0 * tightness;

    // Penalize large leftover that still could have been split better
    // when the item barely fits into a big gap.
    if post_residual as f64 > 0.5 * bin_capacity as f64 {
        score += 8.0;
    }

    // Lookahead: if the next item would fit exactly into post_residual,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            score += (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item won't fit here; leftover likely dead space
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += 2.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: penalize bins far below mean residual
    // (they are "hole" bins), reward bins near/above mean usage.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin should only win when the fit there is
        // excellent and existing bins would leave bad dead space.
        // Base penalty keeps consolidation preferred.
        score += 30.0;
        // But if existing fits are all poor (high mean residual waste),
        // relax the penalty a bit.
        score -= 0.1 * mean_residual;
        // Never open a new bin for a tiny item.
        if item_size < 30 {
            score += 40.0;
        }
    }

    // Slight late-stream conservatism: as the stream progresses,
    // avoid scattering residual space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step match).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let gap = post - next;
            // Exact match => big bonus; near match => partial bonus decaying quadratically.
            let match_bonus = 60.0 - gap * 1.5 - (gap / post.max(1.0)) * 40.0;
            score -= match_bonus.max(0.0);
        } else {
            // Next item cannot follow in this bin: mild penalty proportional to overshoot.
            score += (next - post).min(30.0) as f64 * 0.3;
        }
    }

    // Penalize post_residual that is too small to ever be useful (dead space).
    // Sizes range 1..100, so residual below ~10 is nearly dead weight.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Compare post_residual against mean residual: leaving a bin close to the
    // mean keeps flexibility; leaving it far above mean wastes capacity.
    score += (post_residual as f64 - mean_residual).abs() * 0.4;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is
    // large relative to capacity (big items are better served by a fresh bin).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= tightness * 55.0;
        // Discourage opening bins early in the stream when many bins are open.
        score += open_bins_count as f64 * 1.5;
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Mild late-stream consolidation pressure: prefer filling existing bins as
    // the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item leaves a large residual
    // and many open bins already exist (diversification late in the stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64).ln().max(0.0);
        let waste_penalty = (bin_capacity - item_size) as f64;
        score = 80.0 + waste_penalty * (0.4 + 0.6 * progress) - 8.0 * openness;

        // Opening a bin when no other bin fits is still necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere.
        if fitting_bins_count >= 1 && post_residual >= item_size {
            score += 50.0;
        }
    }

    // Mild global-state coupling: prefer filling bins whose residual is far
    // from the mean (consolidating under-filled bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Encourage using older/more filled bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let mut score = norm_pr * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0);
    score += norm_pr * norm_pr * (2.0 + 3.0 * progress);

    // Reward tight fits more strongly as the stream progresses.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (1.5 + 2.0 * progress);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless residuals are getting large.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).clamp(0.0, 1.0);
        score += 6.0 - 10.0 * pressure * pressure - 4.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack) * (3.0 + 3.0 * progress);
            // Perfect pairing bonus
            if slack < 0.02 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here: slight penalty for wasting residual.
            score += 0.5 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64 / (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual by capacity fraction
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Dead-space penalty: residuals too small to ever be useful
    let min_item = 1u32;
    if post_residual < min_item {
        score += 0.0;
    } else if post_residual <= quarter {
        // small residual: only useful if next item fits it
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0;
        } else {
            score += 30.0 * (1.0 - pr / cap);
        }
    } else if post_residual <= half {
        // mid class: harmonic modulo structure on post_residual
        let class = post_residual % (bin_capacity / 10).max(1);
        score -= 10.0 + class as f64 * 0.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }
    } else {
        // large residual kept open: good
        score -= 20.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill;

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when open bins fit reasonably
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 55.0 + open_bins_count as f64 * 2.0;
        // but if no existing bin can fit, new bin is the only option
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // lookahead: if next item is huge, keep current bins compact
        if next_item_size > bin_capacity / 2 {
            score += 10.0;
        }
    }

    // Progress-based drift: later in stream, be more conservative with new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score += 20.0 * progress;
    }

    // Mean residual coupling: prefer bins below mean residual (more filled)
    score -= (mean_residual - pr) * 0.3;

    // Next item exact-fit bonus: this bin can host both items nicely
    if next_item_size > 0 && next_item_size <= post_residual {
        let combo = (item_size + next_item_size) as f64 / cap;
        if combo > 0.9 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10] are almost unusable
    // (smallest item is >= 1 but typical streams rarely fill tiny gaps),
    // so apply a strong super-linear penalty for small non-zero leftovers.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as i32) as f64 * 8.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 4.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 30.0;
    }

    // Exact-fit lookahead: if the next item exactly consumes the post_residual,
    // this placement is ideal.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot fit into post_residual but could fit a fuller bin,
    // slight bonus for leaving a gap next item can use.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual as f64 - next_item_size as f64) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is cheaper so penalize open bins mildly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.15;

    // New-bin candidate (empty bin): default score equals capacity residual.
    // Make it attractive only when no open bin fits well (handled implicitly),
    // but penalize it when good existing options exist via open-bin pressure.
    if bin_residual == bin_capacity {
        // New bin should lose to perfect fits / last-chance bins.
        score += 2.0;
        // Early in stream, opening new bins is fine; late, avoid bin sprawl.
        score += progress * 10.0;
    }

    // Mild tie-breaker: prefer bins whose residual deviates least from mean
    // (keeps residuals homogeneous and packable).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
