pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual (quadratic coupling).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items are wasted.
    if post_residual < 10 {
        score -= 5.0; // near-perfect fill bonus
    } else if post_residual < 20 {
        score += 3.0; // awkward sliver
    }

    // Lookahead coupling: reward if the next item fits into the post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Penalize blocking the next item slightly, scaled by overflow amount.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    } else {
        // Last item: fill any bin as fully as possible.
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // fits are poor (high mean residual waste) or many bins already fit the item.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin is not chosen when a decent fit exists.
        score += 18.0;
        // Reward opening a new bin when open bins are fragmented (high mean residual)
        // and the item would leave an awkward fit elsewhere.
        score -= 0.08 * mean_residual;
        // As the stream progresses, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins can fit the item, opening a new bin is wasteful.
        score += 4.0 * fitting_bins_count as f64;
        // Early stream with few bins: new bin is cheaper.
        if open_bins_count < 3 {
            score -= 10.0;
        }
    }

    // Mild pressure to prefer bins with less residual overall (balance load).
    score += 0.02 * (bin_residual as f64 - mean_residual);

    // Slight preference for fewer open bins.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 + progress) * cap * 0.5;
    score += coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_size as f64 * (0.5 + progress);

    // Penalize dead space: residuals too small for typical future items
    let dead = (norm_pr * (1.0 - norm_pr)).sqrt();
    score -= dead * mean_residual * 0.1;

    // Lookahead: reward bins whose post-residual matches next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - gap / cap) * next_item_size as f64 * 0.3;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_frac = pr / cap; // 0..1

    // Perfect fit gets a huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space: leftovers that nothing (min size 1..100) can use well.
        // Harmonic class via integer division thresholds on post_residual.
        let class = post_residual / 10; // 0..=10 harmonic class
        match class {
            0 => score -= 40.0,               // 0..9: near-perfect fill
            1 => score -= 25.0,               // 10..19
            2 => score -= 15.0,               // 20..29
            3 => score -= 8.0,                // 30..39
            4 => score -= 3.0,                // 40..49
            5 => score += 0.0,                // 50..59: half-full, neutral
            6 => score += 3.0,
            7 => score += 8.0,
            8 => score += 15.0,
            9 => score += 25.0,
            _ => score += 40.0,               // 100 impossible, but near-full residual
        }

        // Nonlinear coupling: small residuals are precious, large ones wasteful.
        score += 0.5 * pr_frac * pr_frac * cap;

        // Lookahead: if the next item fits exactly into post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 300.0;
            } else if next_item_size <= post_residual {
                let slack = (post_residual - next_item_size) as f64;
                // Reward proportional to tightness of the lookahead fit.
                score -= 100.0 * (1.0 - slack / cap);
                // Penalize leaving a residual in an awkward harmonic class for next item.
                let after = post_residual - next_item_size;
                if after > 0 && after < 10 {
                    score -= 20.0; // leaves tiny dead space after next item
                }
            } else {
                // Next item won't fit here; mildly penalize hoarding large residuals
                // that block future packing? Actually large residual is useful, small penalty.
                score += 5.0;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 60.0;
        }

        // New-bin candidate handling: opening a new bin should only win when
        // the current item fits terribly everywhere (huge post_residual waste).
        if bin_residual == bin_capacity {
            // Base score for a fresh bin: it has full residual after placement.
            // Make it unattractive unless post_residual here is much better than
            // what open bins offer. Compare against mean residual of open bins.
            let fresh_waste = pr; // wasted capacity in the new bin right away
            let open_waste = mean_residual - item_size as f64; // best-ish comparison
            if open_waste.is_finite() && fresh_waste > open_waste + 15.0 {
                score += 200.0; // open bins fit better; don't open a new one
            } else {
                score -= 30.0; // fresh bin competitive when open bins are crowded
            }
            // Late in the stream, prefer consolidating into open bins.
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score += 80.0 * progress;
            // Too many open bins: discourage opening more.
            score += 4.0 * open_bins_count as f64;
        }
    }

    // Modulo-arithmetic harmonic bonus: residuals divisible into nice chunks
    // (multiples of 10 or 25) are easier to fill later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Mild preference to balance residual against the mean (avoid fragmentation).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item size are wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Soft penalty for small gaps that future items (>=10 in typical streams) can't use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and remaining stream.
        score += 30.0 + 8.0 * open_bins_count as f64 * (1.0 + progress);
        // But if no open bin fits well, opening may be justified: relax penalty
        // when the next item would fit better in a fresh bin alongside this one.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Mild penalty for spreading across many bins.
        score += 1.5 * open_bins_count as f64 * 0.1;
    }

    // Prefer bins whose residual is close to the mean (keep residuals balanced),
    // but only slightly, so tightness dominates.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that neither fits the next item nor is useful.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward tight leftover after that future placement
            let after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize proportionally to how far off
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Reward tight fits relative to mean residual across open bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 55.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // Late in the stream, keep bins tight; opening new bins is less attractive
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Discard bins whose residual becomes dead space (too small for any item >= 1..=min typical)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Favor bins with smaller residual generally (best-fit bias)
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.15 * (post_residual as f64).min(next_item_size as f64);
        }
    } else {
        // Last item: strongly prefer filling existing bins
        score -= 25.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Prefer bins with residuals below mean residual (pack fuller bins first)
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be conservative (penalize low residual bins);
    // late in the stream, fill aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage consolidation into existing bins
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it unattractive unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 18.0;
        // Allow new bin early when lookahead won't fit anywhere well anyway
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual) strongly; later, dead space
    // matters more because remaining opportunities shrink.
    let tightness = (pr / cap).powi(2) + (pr / cap).powi(4);
    score += tightness * cap * (0.5 + 1.5 * progress);

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_frac * fit_frac;

    // Penalize leaving residual that is too small to hold typical future items
    // (smooth sigmoid-like gate rather than piecewise constant).
    let small_space = 1.0 - 1.0 / (1.0 + (pr / 20.0).exp());
    score += 15.0 * small_space * (0.5 + progress);

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-gap / 15.0);
        // Penalize residuals just barely too small for the next item (dead zone).
        let dead = 1.0 / (1.0 + ((next_item_size as f64 - pr) / 8.0).abs());
        let too_small = ((next_item_size as f64 - pr) / 10.0).max(0.0);
        score += 10.0 * dead * too_small.min(2.0);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mild pressure toward consolidation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 4.0;

    // Mean-residual coupling: bins far from the mean residual are slightly
    // deprioritized to keep residual distribution homogeneous.
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: opening a fresh bin is only attractive when all open
    // bins would leave large unusable residuals; otherwise penalize it.
    if bin_residual == bin_capacity {
        let avg_waste = (mean_residual / cap).max(0.0);
        score = cap - 30.0 * avg_waste + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are likely
    // to be filled by common item sizes (capacity fractions).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward when post_residual matches a "harmonic" slot: multiples of 25
    // (quarter classes) are highly reusable.
    let quarter = (post_residual % 25 == 0) as i32 as f64;
    score -= 12.0 * quarter;

    // Fifth-class harmony: residuals divisible by 20.
    let fifth = (post_residual % 20 == 0) as i32 as f64;
    score -= 8.0 * fifth;

    // Third-class harmony: residuals divisible by 30.
    let third = (post_residual % 30 == 0) as i32 as f64;
    score -= 6.0 * third;

    // Penalize "dead" residuals: small but nonzero leftovers that few items
    // (sizes 1..100) can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // strongly reward; if next item fits at all, mild reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // Harmonic residue match: next item leaves a divisible remainder.
            let rem = post_residual - next_item_size;
            if rem % 25 == 0 {
                score -= 10.0;
            } else if rem % 20 == 0 {
                score -= 6.0;
            }
            score -= 4.0;
        } else {
            // Next item cannot fit here: slight penalty proportional to waste.
            score += 2.0;
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.5 * mean_residual;
    }

    // New-bin candidate: penalize mildly so it is chosen only when no open
    // bin offers a decent fit; scale with stream progress and open bins.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64
            + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        // Prefer bins below mean residual (pack tight bins first).
        score -= 0.3 * (mean_residual - pr);
    }

    // Integer-division threshold on post_residual: bucket the leftover into
    // coarse classes and reward smaller buckets.
    let bucket = post_residual / 10;
    score += bucket as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let gap = post_residual as f64;
    if gap > 0.0 {
        // Gap below smallest plausible item (<=10) is pure dead space.
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0;
        } else if gap < 20.0 {
            // Gaps of 10..19 are only usable by small items; moderate penalty
            // unless the next item actually fits into this gap.
            if (next_item_size as f64) > gap {
                score += 25.0 * (1.0 - gap / 20.0);
            } else {
                score -= 10.0;
            }
        }
        // Perfect fit reward.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Reward tight fits relative to bin capacity.
    score -= 30.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid bin proliferation); scale penalty on new empty bins.
    if bin_residual == bin_capacity {
        score += 40.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is already below the mean (consolidate waste).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward; if it would leave an even worse gap, penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= gap {
            let second_gap = gap - ni;
            if second_gap < 10.0 && second_gap > 0.0 {
                score += 15.0;
            } else {
                score -= 12.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for
    // flexibility; late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match with the next item is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // bin becomes exactly reusable by the next item
        } else if post_residual >= next_item_size {
            // next item can still fit here: mild reward proportional to slack match
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space more when leftover is small
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Reward tight fits (low post residual) beyond the raw value.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Penalize wasting a nearly-full bin on an item that leaves a large unusable hole.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item fits poorly everywhere else
    // (i.e., this call is the empty bin and post_residual is large).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 - 15.0 * progress;
        // If existing bins fit, discourage opening a new one unless it's a perfect
        // lookahead match (handled above by the subtraction).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Slight preference for bins already below mean residual (reduces fragmentation).
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.0;
        }
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.05 * open_bins_count as f64;

    score
}
